window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":38000,"as":"链霉菌属编码了一个高度保守的生物合成 megacluster，可产生四个结构独特的天然产物家族（stravidins、acidomycin、dapamycins 和 α-Me-KAPA）以及生物素结合蛋白链霉亲和素。这些成分通过互补的机制协同汇聚于细菌的生物素代谢。这一发现揭示了微生物可编码协调的多代谢物系统，打破了将生物合成基因簇视为单一活性分子来源的传统观念。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":8.0},"kp":["生物合成基因簇[链霉菌产生协同靶向生物素的抗生素]: 高度保守的巨型集群"]},{"i":38001,"as":"","scd":null,"kp":[]},{"i":38002,"as":"使用激光照射堆叠的二维材料层，可在层间产生超过100开尔文的温差。这一现象实现了在超薄结构中利用激光开启热流的效果。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["温差[二维材料堆叠层在激光照射下]: > 100 K"]},{"i":38003,"as":"从尼安德特人骨骼遗骸中提取的大量基因组数据，推翻了先前关于这些古人类的一些假设，并提出了关于其种群动态和消亡的新问题。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":3.0,"t":6.0},"kp":["[骨骼遗骸的遗传数据]: 推翻了关于尼安德特人种群的部分假设并提出新问题"]},{"i":38004,"as":"","scd":null,"kp":[]},{"i":38005,"as":"链霉菌能够产生由四种抗生素化合物组成的混合物。这四种化合物通过攻击一条必需代谢途径的多个不同部分，从而有效杀死具有耐药性的超级细菌。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":4.0,"t":6.0},"kp":["抗生素种类[链霉菌属细菌产生并杀死超级细菌]: 4种化合物","杀菌机制[链霉菌产生的抗生素混合物]: 攻击必需代谢途径的多个部分"]},{"i":38006,"as":"一种廉价的多孔聚合物膜无需加热或选择性涂层即可分离原油。重质碳氢化合物在孔隙内自组装形成宽度不到2纳米的通道，将渗滤液富集为轻质“石脑油范围”碳氢化合物。长链碳氢化合物沉积在孔壁上使通道变窄，直到仅允许较小分子通过。此方法的能源成本和二氧化碳排放量比传统蒸馏法低30%。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":7.0},"kp":["孔道宽度[重烃在多孔聚合物膜孔内自组装]: < 2 nm","能耗与碳排放[多孔膜原油无热自精炼]: 较传统蒸馏降低30%","[分离机制]: 长链烃沉积在孔壁上使通道变窄，仅允许较小分子通过"]},{"i":38007,"as":"β-抑制蛋白调节G蛋白偶联受体（GPCR）超家族的信号传导。三种小分子能够破坏β-抑制蛋白与GPCR蛋白的结合，直接结合并抑制其活性。这些分子是首个用于探索其生物学特性的化学工具，为针对转导蛋白的特定通路GPCR疗法开辟了途径。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["靶标[条件]: β-抑制蛋白","技术状态[条件]: 首个用于探究其生物学的化学工具","作用机制[条件]: 直接结合β-抑制蛋白并抑制其活性","作用效果[条件]: 阻断β-抑制蛋白与G蛋白偶联受体(GPCR)蛋白的结合","化学实体数量[条件]: 三种小分子"]},{"i":38008,"as":"从人工智能到生物技术，当今的科学突破引发了一系列单纯依靠技术专业知识无法解决的伦理和社会挑战。面对这些复杂问题，科学领域比以往任何时候都更需要人文学科的介入与融合。","scd":{"b":2.0,"i":2.0,"r":3.0,"d":2.0,"t":4.0},"kp":[]},{"i":38009,"as":"通过结合卫星图像和机器学习技术，研究人员成功创建了首个全面的海草草甸全球地图。这一成果为海草生态系统的保护工作提供了重要的数据支持。","scd":{"b":5.0,"i":6.0,"r":8.0,"d":5.0,"t":6.0},"kp":["[卫星图像与机器学习结合]: 首次创建了全面的海草草甸地图"]},{"i":38010,"as":"二维材料科学虽然充满各种可能性，但目前缺乏系统化的“实验记忆”。将已合成的材料、其制备方法以及它们与计算预测的关系关联起来，对于塑造未来的科学发现至关重要。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":3.0},"kp":["发展瓶颈[二维材料科学]: 缺乏有组织的实验记忆(合成与制造方法的历史记录及关联)"]},{"i":38011,"as":"基于2243个中国宏基因组样本，研究生成了2009至2022年中国土壤抗生素抗性基因（ARGs）的14年时空分布图，并开发了交互式开放平台。数据显示，与2015年前相比，2016年后农田总ARGs（52.6%）和Rank I ARGs（77.0%）的相对丰度显著下降，这与2016至2020年的国家AMR控制政策时期吻合。全球对比显示农田抗性组出现同质化现象。","scd":{"b":4.0,"i":4.0,"r":8.0,"d":8.0,"t":6.0},"kp":["研究样本量[中国宏基因组]: 2,243","时间跨度[中国土壤ARGs时空分布]: 14年 (2009-2022)","ARGs相对丰度[2015年后农田样本]: 下降52.6%","Rank I ARGs相对丰度[2015年后农田样本]: 下降77.0%"]},{"i":38012,"as":"太阳快风的加速和加热机制一直是空间物理难题。利用太阳轨道飞行器的极紫外成像仪的高时空分辨率数据，研究人员在太阳极区日冕羽流中识别出此前未被发现的隐身高频磁流体动力学（MHD）波。分析表明，超过三分之一的传播扭折波周期短于100秒，这类具有显著能量的高频波填补了理论与观测之间的空白。","scd":{"b":7.0,"i":1.0,"r":8.0,"d":6.0,"t":6.0},"kp":["波类型[太阳极区日冕加热所需]: 高频磁流体力学(MHD)波"]},{"i":38013,"as":"研究人员构建了一种结合邻位B-π-B模式的新型四硼多共振（MR）框架ICZ4B，以吲哚[2,3-c]咔唑为中心构建块实现高效四重硼化。ICZ4B展现出明亮的黄色发射（半峰宽仅为24纳米），并将反向系间窜越（RISC）速率提升至4.7×10^4 s^-1。基于该材料的非敏化器件实现了36%的杰出外部量子效率。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":8.0,"t":7.0},"kp":["发光材料[高效黄色窄带OLED]: 具有邻-B-π-B图案的四硼多共振(MR)框架ICZ4B","[核心构建块]: 吲哚并[2,3-c]咔唑"]},{"i":38014,"as":"探讨光纤技术从单一信号发射载体向多模态传感平台转型的技术路径与应用潜力。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[光纤技术]: 从单一无源信号发射载体转变为多模态传感平台"]},{"i":38015,"as":"在零间隙CO2还原反应（CO2RR）电解槽中，含有烷基链的聚芴类阴离子交换膜（PBFA-QA）展现出优异的性能。其CO部分电流密度达331.7 mA cm^-2，高于商用膜。在200 mA cm^-2电流密度下，电池稳定运行200小时，且CO法拉第效率（FECO）保持在92.3%以上，期间未发生阴极水浸或盐沉淀。","scd":{"b":6.0,"i":5.0,"r":8.0,"d":9.0,"t":7.0},"kp":["CO部分电流密度[零间隙CO2RR电解槽PBFA-QA膜]: 331.7 mA/cm²","运行稳定性[PBFA-QA基CO2电解槽在200 mA/cm²下]: 连续运行200小时","CO法拉第效率[PBFA-QA基CO2电解槽稳定运行期间]: > 92.3%"]},{"i":38016,"as":"研究发现钙钛矿太阳能电池在长期户外运行后，会同时出现电极腐蚀、边缘图案和相分离现象。通过使用光强度和电偏置作为关键应力源复现这些降解模式，该研究将实际的实地老化降解与加速老化测试联系起来，指出未来应开展针对特定机制的加速老化测试。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["空间降解模式[钙钛矿太阳能电池户外长期运行后]: 电极腐蚀、边缘图案和相分离共存","[老化测试加速机制]: 利用光强和电偏压作为关键应力源进行靶向模拟"]},{"i":38017,"as":"土壤细菌能够制造由多种分子组成的混合物，这些分子能够协同抑制微生物病原体的生长。这种协同机制为应对抗药性感染和开发新型抗生素提供了有效策略。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[细菌产生抗生素混合物]: 协同抑制微生物病原体生长"]},{"i":38018,"as":"核苷酸修饰的mRNA-脂质纳米颗粒（LNP）疫苗通过引发强大的先天和适应性免疫反应，对COVID-19提供了高效保护。深入理解mRNA-LNP疫苗驱动保护性免疫的作用机制对于开发下一代疫苗至关重要。目前关于LNP如何被免疫系统感知并发挥佐剂活性的关键知识依然存在空白。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":3.0},"kp":["[mRNA-LNP疫苗]: 依赖诱导强大且协同的先天和适应性免疫反应发挥作用"]},{"i":38019,"as":"传统数字像素只能单一地检测或发射光强度。研究人员提出了一种基于傅里叶光学的微型衍射元件多功能平台，利用等离子体表面波，开发出能够同时感知并生成光波前，且能完全控制振幅、相位和偏振的“傅里叶像素”，实现了复杂光场的双向控制与反馈。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[多功能像素]: 同时具备光学波前感知与生成能力"]},{"i":38020,"as":"医疗AI模型的训练数据通常包含敏感患者信息，易受隐私攻击。现有研究多量化整个数据集的攻击成功率，忽视了贡献了多条相似记录的个体患者的隐私风险。该研究针对医疗诊断AI模型进行了患者级别的隐私审计，重点关注成员推理攻击（MIAs），旨在确定特定个人数据是否被用于模型训练。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[医疗AI隐私风险]: 针对患者个体的隐私攻击暴露敏感信息"]},{"i":38021,"as":"可溶液加工的二维半导体可用于制造大面积电子器件，但电学性能不及高温化学气相沉积法。该研究报道了一种晶圆级、二维层状铜铟硒化物（CuIn5Se8）半导体的溶液加工制备技术，具备高迁移率。通过在环境空气中沉积4英寸薄膜，并开发退火步骤以消除可逆吸附的水分子，显著提升了其电学性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["二维六方铜铟硒化物半导体[晶圆级制备]: 具备高迁移率值","半导体前驱体[空气稳定性]: 可溶液加工的二维墨水"]},{"i":38022,"as":"随着晶体管横向微缩停滞、三维堆叠和新型纳米材料的引入，栅极电介质可靠性成为保障器件功能的关键。现有学术文献提出的电介质研究方法通常无法满足工业测试需求。该研究探讨了如何以符合工业要求的方式评估电介质材料的可靠性，并审查了工业界测试与基准评估的方法。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["晶体管栅极电介质[可靠性测试]: 需承受高电场并阻断电荷传输以保障器件功能"]},{"i":38023,"as":"聚焦材料或生物样本在X射线照射下的损伤评估机制，旨在实现辐射风险的精确量化。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[X射线损伤]: 建立精确量化辐射损伤风险的评估机制"]},{"i":38024,"as":"分析微型电网系统故障的多重交互成因，探讨复杂电网架构下的稳定性与风险控制。","scd":{"b":3.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[微型电网故障]: 由多重交互因素共同导致"]},{"i":38025,"as":"研究钙钛矿太阳能电池的露天环境制造工艺，关注其大规模商业化生产的稳定性与可行性。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[钙钛矿太阳能电池]: 露天环境制造工艺"]},{"i":38026,"as":"混凝土的生产量远超其他工程材料，会导致局部资源稀缺和生态退化。研究量化了全球生产混凝土所消耗的矿物、能源和水资源。结果显示，2019年全球直接消耗了300亿吨资源用于生产混凝土及硅酸盐水泥产品，若计入资源损耗，总体资源消耗量将更高。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["混凝土产量[对比其他材料]: 超过所有其他人造材料三倍以上","混凝土产量[对比钢铁及木材]: 分别约为钢铁的20倍和实木产品的40倍"]},{"i":38027,"as":"","scd":null,"kp":[]},{"i":38028,"as":"研究通过利用严重的晶格畸变激活马氏体内部变形孪生作为塑性载体，成功制备出兼具超高强度与延展性的马氏体钢。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["马氏体钢[微观变形机制]: 晶格畸变激活变形孪生作为塑性载体","马氏体钢[力学性能]: 超高强度且具备延展性"]},{"i":38029,"as":"","scd":null,"kp":[]},{"i":38030,"as":"外尔半金属Mn(Bi,Sb)2Te4在磁场强迫下由于极端的粒子-空穴对称性破缺，展现出巨大的红外圆二色性。螺旋度分辨磁光红外光谱显示，其圆二色性超过3000 mdeg，且在6-13微米光谱范围内具有超过1度的响应。这种光学共振通过II型外尔色散朗道能级的能带嵌套效应得到显著增强。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["外尔半金属Mn(Bi,Sb)2Te4[磁场强制诱导]: 极端粒子-空穴对称性破缺","圆二色性[中远红外波段磁致效应]: 巨大的宽带圆二色性"]},{"i":38031,"as":"探讨传输过程中拓扑间隙检测算法的鲁棒性，回应相关技术在复杂环境下的可靠性问题。","scd":{"b":3.0,"i":1.0,"r":3.0,"d":2.0,"t":4.0},"kp":["[拓扑间隙检测]: 评估传输过程中检测算法的鲁棒性"]},{"i":38032,"as":"","scd":null,"kp":[]},{"i":38033,"as":"深入探讨通过传输机制进行拓扑间隙检测时的鲁棒性，涉及拓扑物理学与信号传输理论。","scd":{"b":3.0,"i":1.0,"r":3.0,"d":2.0,"t":4.0},"kp":[]},{"i":38034,"as":"人工智能模型的训练数据漏洞存在泄露医疗记录的识别风险。这种风险在训练数据中代表性不足的群体中表现得更为严重。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":4.0,"t":6.0},"kp":["[AI训练数据漏洞]: 训练数据中代表性不足群体的身份识别泄露风险更严重"]},{"i":38035,"as":"淋病奈瑟菌已对大多数治疗用抗生素产生耐药性。通过应用机器学习筛选技术，研究人员发现了能够对抗这种耐药性淋病细菌的潜在新疗法和抗生素。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["抗生素发现[机器学习筛选]: 揭示对抗耐药性淋病细菌的潜在新疗法"]},{"i":38036,"as":"从地下物质中冒出的二氧化碳气泡在海底凝固，最终雕刻形成高达5米的怪异圆顶状岩石结构。","scd":{"b":3.0,"i":1.0,"r":4.0,"d":4.0,"t":3.0},"kp":[]},{"i":38037,"as":"干扰素基因刺激蛋白（STING）是免疫信号传导的关键蛋白。该研究开发了一种大规模并行测定方法，系统绘制了STING的序列-功能图谱。通过对数千个单氨基酸变异进行谱分析，研究鉴定了控制细胞内STING激活或失活的特定序列元件。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":[]},{"i":38038,"as":"为实现消除饥饿的目标，农业需同时提高产量、增加维矿密度以实现多重生物强化，并增强对气候变化的适应力。气候变化会降低作物微量元素密度。CRISPR-Cas等基因编辑技术在应对气候压力、提升作物营养价值及多重生物强化方面发挥着重要作用。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":5.0,"t":3.0},"kp":["[农业发展核心目标]: 增强产量、提高维生素和矿物质密度以维持每日推荐摄入量（多重生物强化）、以及增强气候变化适应力"]},{"i":38039,"as":"肝低密度脂蛋白受体（LDLR）的代谢决定了胆固醇平衡。研究发现了一条由Ral GTP酶调节的新途径，将细胞外胆固醇信号与控制LDLR周转的细胞内转运机制相连。长期摄入膳食胆固醇通过增加RAS活性激活Ral蛋白，引导LDLR进入溶酶体降解并抑制其循环。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":[]},{"i":38040,"as":"研究基于475万张Sentinel-2卫星影像和深度学习分类器，绘制了首个空间分辨率为10米的全球海草分布高分辨率地图。研究共识别出全球148,506平方公里的海草，其中包含5,961平方公里的潮间带和142,545平方公里的潮下带区域。","scd":{"b":6.0,"i":5.0,"r":8.0,"d":8.0,"t":5.0},"kp":["空间分辨率[全球清晰浅水区海草测绘]: 10米","影像数据量[海草测绘]: 475万张"]},{"i":38041,"as":"海洋浮游植物产生的二甲基硫(DMS)氧化会生成甲磺酸(MSA)。在CERN CLOUD舱内进行的实验表明，在低于-10°C的条件下，MSA能与氨(NH3)结合发生成核作用，速率与硫酸-氨相当。此外，MSA与硫酸在极低温下协同成核，即便在超低氨水平下也能驱动颗粒物的生长。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["MSA产量[温度条件]: 低于10 °C时高于SA","MSA与NH3成核率[温度条件]: 低于−10 °C时与SA-NH3相当","MSA与SA协同成核[温度条件]: 低于−10 °C","MSA驱动颗粒物生长[温度条件]: 低于9 °C","MSA驱动颗粒物生长[湿度条件]: 高于40 %相对湿度(RH)"]},{"i":38042,"as":"镍催化交叉偶联反应在化学合成中至关重要，但由于难以分析，Ni(II)上的金属转移速率数据十分有限。该研究报道了一种利用核磁共振(NMR)光谱分析Ni(II)金属转移的简便方法。该方法通过生成与Ni(0)配位的不饱和偶联产物，有效防止了与剩余Ni(II)的歧化反应及棘手Ni(I)的生成。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["分析技术[Ni(II)金属转移动力学]: 基于NMR光谱的用户友好型分析方法"]},{"i":38043,"as":"将硝酸盐电还原为氨是实现废水资源化的可持续方法，但实际废水中低浓度的硝酸盐及共存干扰离子严重影响催化选择性和稳定性。该研究首次证明脉冲设计能够实现从实际废水中的稀硝酸盐高效电合成氨，在含约5mM硝酸根及多种干扰离子的石墨烯厂废水中展现出优异的性能。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":5.0},"kp":["技术策略[实际废水稀硝酸盐电合成氨]: 脉冲设计"]},{"i":38044,"as":"基于环辛炔探针和叠氮化物的张力促进1,3-偶极环加成反应（SPAAC）常用于生物大分子的标记。针对SPAAC反应动力学缓慢且需洗去过量荧光探针的缺陷，该研究开发了一种光触发、反应快速的荧光噻吩基环炔，实现了在无洗涤条件下对1,3-偶极子标记分子的生物正交荧光标记。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["反应动力学[应变促进的炔烃-叠氮化物环加成(SPAAC)]: 慢动力学"]},{"i":38045,"as":"果蝇的肠道代谢性别差异导致了对病原体感染的性别二态性结果。雌性果蝇无法克服病原体诱导的氧化应激，导致排便受阻、病原体持续存在并致死。而雄性果蝇的碳水化合物代谢和磷酸戊糖途径活性增加，作为抗氧化防御系统，使其能够清除病原体并存活。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":4.0,"t":5.0},"kp":[]},{"i":38046,"as":"","scd":null,"kp":[]},{"i":38047,"as":"","scd":null,"kp":[]},{"i":38048,"as":"","scd":null,"kp":[]},{"i":38049,"as":"","scd":null,"kp":[]},{"i":38050,"as":"","scd":null,"kp":[]},{"i":38051,"as":"","scd":null,"kp":[]},{"i":38052,"as":"","scd":null,"kp":[]},{"i":38053,"as":"","scd":null,"kp":[]},{"i":38054,"as":"","scd":null,"kp":[]},{"i":38055,"as":"","scd":null,"kp":[]},{"i":38056,"as":"家犬表现出巨大的形态多样性，传统的人工表型测量难以捕捉复杂的视觉特征。研究构建了包含13,254张多品种犬类图像的数据集，利用ResNet和ViT深度学习模型自动提取了256维的图像特征嵌入。通过UMAP进行降维后，将提取的特征与品种级别的基因型数据进行全基因组关联分析（GWAS）。该方法成功识别出15个此前已知的基因，证明了深度学习在复杂动物表型定量分析中的有效性。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["数据集规模[犬类图像表型分析]: 13254张多品种犬类图像","深度学习模型[狗内表型特征提取]: ResNet和ViT模型"]},{"i":38057,"as":"由五唑阴离子（N5-）代表的氮环结构因其能够形成高能量密度材料而备受关注，但其固有的高能特性使得在环境条件下获取稳定晶体成为巨大挑战。基于第一性原理的结构和动力学研究，文章报道了一种在环境条件下稳定存在的聚合氮晶体Li4(N5)2。在其晶胞中，锂原子向N5环发生电子转移并占据其离域轨道，形成稳定的超原子氮环结构。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":6.0,"t":6.0},"kp":["[多氮晶体]: Li4(N5)环境条件下稳定的超原子氮环晶体"]},{"i":38058,"as":"泪液富含生物标志物，具有非侵入式疾病监测的潜力。为解决血清尿酸（SUA）与泪液尿酸（TUA）缺乏相关性分析的局限，研究开发了一种无线智能隐形眼镜，可实现实时、无创的TUA监测。在兔子、人类受试者（包括高尿酸血症和痛风患者）中进行的验证表明，TUA与SUA之间存在强线性关系。通过日常生活监测和个性化滞后时间分析，成功构建了回归模型以推算和预测个性化尿酸水平。","scd":{"b":8.0,"i":5.0,"r":8.0,"d":8.0,"t":7.0},"kp":["[无线智能隐形眼镜]: 实时无创监测泪液尿酸(TUA)以替代血液尿酸检测的数字孪生系统"]},{"i":38059,"as":"YAP及其旁系同源基因TAZ是Hippo通路中调节细胞生长的转录共激活因子。研究发现，在肝脏中YAP主导的克隆会迅速使细胞去分化为干细胞样状态，并招募炎症免疫细胞，随后被清除；而TAZ克隆则促进抗炎环境，实现长期维持和器官大量生长。具体而言，YAP克隆招募的炎症源性血液单核细胞会抑制YAP克隆的生长，若抑制这些单核细胞则允许YAP克隆继续生长。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":4.0,"t":5.0},"kp":["[YAP克隆在肝脏中的行为]: 迅速将细胞去分化为干细胞样状态，并伴有炎症免疫细胞的招募"]},{"i":38060,"as":"光电化学固氮制氨受到稳固的氮氮三键及竞争性界面反应动力学的限制。受固氮酶启发，研究设计了单原子铁掺杂的氧化钨（WO3）亚纳米线作为仿生动态集成催化平台。扭曲的晶格和不对称位点形成了动态响应催化中心，光诱导的价态-晶格振荡驱动电子离域，改变了传统的N2吸附模式和反应路径。该催化剂具有独特的自粘附和成膜特性，有效提升了催化效率。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["催化剂[光电化学合成氨]: 单原子铁(Fe)掺杂氧化钨(WO3)亚纳米线"]},{"i":38061,"as":"神经嵴是脊椎动物中最具进化变革性的细胞谱系之一，由其迁移能力和多能性定义。文章探讨了神经嵴如何作为“进化机会主义者”，通过共同选择中胚层、基板和中枢神经系统的特征来产生新结构。研究区分了这些被共同选择的特征与在神经嵴环境下产生的真正创新，并讨论了神经嵴可能起源于光合感觉和神经分泌细胞群体的进化假说。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":2.0,"t":3.0},"kp":["[神经嵴细胞特性]: 迁移能力和多能性，非固定细胞类型，而是具有重塑和重新分配细胞程序能力的干细胞样群"]},{"i":38062,"as":"北大西洋涛动（NAO）的十年期预测对气候服务至关重要，但受内部变率限制，提取预测技能极具挑战。研究引入了时间对齐平均（TAA）创新后处理框架，大幅提升了冬季NAO的预测技能，将1961年至2023年间的解释方差从34%提升至69%，并为4到5年的短期平均值提供可靠预测。结合单模型大集合的子采样策略，TAA有效克服了多模型混合带来的不一致性和偏差。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[时间对齐平均(TAA)后处理框架]: 显著增强冬季北大西洋涛动(NAO)的预测技能"]},{"i":38063,"as":"分层上皮的屏障组织依赖朗格汉斯细胞（LCs）维持免疫监视。研究确定TAM配体GAS6是口腔粘膜LC生物学的中枢调节因子。GAS6可维持上皮完整性、抑制局部炎症，并通过控制LC在组织中的留存来微调其丰度。在前体细胞水平上，GAS6促进树突状细胞前体（尤其是pre-DC1）的增殖和分化，且优先支持AXL+ pre-DC衍生的LCs，而不影响AXL+ MERTK+ 细胞。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["TAM信号配体[口腔粘膜朗格汉斯细胞生物学]: GAS6","调节机制[GAS6调控粘膜LC稳态]: 维持上皮完整性、抑制局部炎症，并通过控制细胞在组织内的潴留来微调LC丰度","调节机制[GAS6在前体水平的作用]: 促进增殖"]},{"i":38064,"as":"在二维亚铁磁体中实现多步磁化切换对于高密度非布尔逻辑和存储器件具有重要意义，但现有材料受限于较低的居里温度和缺乏可调的多重磁态。研究成功合成了具有强室温亚铁磁性的二维Fe0.875S(1-x)Sex合金家族。通过调整材料中的硫族元素比例，可以有效调控其关键磁性和电学性质，成功实现了室温下的多步磁化切换。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":7.0,"t":6.0},"kp":["材料体系[二维亚铁磁体]: 二维Fe0.875S(1-x)系列材料"]},{"i":38065,"as":"兼具组织粘附性和抗纤维化能力的水凝胶在软组织治疗中需要同时满足功能性和硬度要求，但两者通常存在内在权衡制约。通过引入聚合物刷涂层，研究开发了一种模块化水凝胶系统，实现了水凝胶硬度和功能的独立控制。通过定制涂层化学、厚度及网络拓扑，该水凝胶在1千帕至1兆帕的软组织硬度全范围内，均能保持约100焦耳/平方米的稳定生物粘附性并有效抑制纤维化。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["水凝胶系统[功能与硬度调控]: 通过引入聚合物刷涂层实现生物粘附、抗纤维化和硬度的独立控制"]},{"i":38066,"as":"","scd":null,"kp":[]},{"i":38067,"as":"通常磁场会通过塞曼效应或诱导涡旋形成来抑制超导性，但在特定条件下也能稳定超导。这种重入超导性现象多见于三维材料，在二维系统中极少被探索。研究者在外延(110)取向的LaTiO3-KTaO3界面观察到了重入超导性现象，提示了非常规超导性的存在。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["重入超导性[氧化物异质界面]: 磁场在二维体系中通过磁相互作用稳定而非抑制超导态"]},{"i":38068,"as":"纳米限域水在纳米流体学、电化学和催化中起关键作用，但其反应活性存在争议。基于机器学习势函数的分子动力学研究表明，受限水的解离行为对水的密度、几何形状和表面化学极其敏感。化学势与界面相互作用共同主导了纳米尺度水的解离和反应性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["水自分解行为[二维狭缝孔与纳米液滴受限环境]: 通过增强采样分子动力学结合机器学习势函数揭示其受限反应性规律"]},{"i":38069,"as":"","scd":null,"kp":[]},{"i":38070,"as":"针对慢性口腔疾病，研究人员开发了一种无电池、无线的穿戴式智能矫治器。该系统集成了受蝴蝶启发的柔性双面诊疗电极阵列，能够同步监测空间分辨的pH值和亚硝酸盐，并按需电控释放抗菌剂。系统通过近场通信(NFC)和低功耗蓝牙中继供电与控制，实现闭环治疗诊断。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["智能矫治器[慢性口腔疾病闭环治疗诊断]: 无电池无线可穿戴且集成了仿生微针贴片实现空间分辨的治疗与诊断"]},{"i":38071,"as":"GOLDEN2-LIKE (GLK) 蛋白是植物光合作用的核心转录调控因子。在水稻中，OsGLK1和OsGLK2在光合作用调节中具有部分冗余作用。转录组测序表明OsGLK调控碳水化合物代谢和光合作用相关基因的表达。过表达OsGLK1能够调节水稻的光合作用并影响产量。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["OsGLK1/2-DGP1/2/3模块[水稻光合与产量调控]: 调节水稻光合作用及产量的核心分子机制"]},{"i":38072,"as":"","scd":null,"kp":[]},{"i":38073,"as":"针对卵巢癌预后差且易复发的难题，研究者开发了靶向叶酸受体1(FOLR1)的锕-225(225Ac)α粒子疗法。PET成像显示，该疗法在SKOV3异种移植瘤中具有高度的肿瘤特异性摄取，表现出极高的治疗效果，能够有效消除卵巢癌的肿瘤病灶。","scd":null,"kp":["靶向疗法[FOLR1靶向225Ac]: 利用225Ac释放的α粒子有效消除卵巢癌"]},{"i":38074,"as":"","scd":null,"kp":[]},{"i":38075,"as":"石榴石型LLZTO陶瓷颗粒表面的碳酸锂钝化层会导致界面相容性差及锂离子传输不连续。研究通过化学转化方法，利用多重氢键桥构建了复合固体电解质(CSE)。该策略有效改善了陶瓷颗粒的界面分布，为固态锂电池提供了连续且稳定的锂离子(Li+)传输路径。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["复合固体电解质[固态锂电池界面改性]: 构建多氢键桥结构以消除Li2CO3钝化层并提供连续的Li+传输途径"]},{"i":38076,"as":"盐胁迫植物根际的假单胞菌具有独特的耐盐基因组特征(如Na+转运蛋白)。这些假单胞菌能够在大豆根系稳健定殖，并在温室和田间条件下显著提高大豆的耐盐性。其介导的植物耐盐机制是通过增强植物木质素的生物合成来实现的，从而促进作物的胁迫适应。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["假单胞菌[盐胁迫下大豆抗逆性]: 通过携带高耐盐基因特征并增强宿主植物木质素生物合成来促进胁迫适应"]},{"i":38077,"as":"针对长链DNA数据存储稳定性差的问题，研究提出一种长链异种核酸-环状单链DNA(XNA-cssDNA)杂合策略以提升存储鲁棒性。评估确定2'-氟阿拉伯核酸(FANA)为最佳存储材料。通过温度引导的语言模型进化出FANA聚合酶Tgomut，合成速度比TgoD4K快4.4倍，可合成超过7500个核苷酸的长链。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":7.0,"t":5.0},"kp":["数据存储材料[XNA-cssDNA杂合体]: 鉴定出2'-氟阿拉伯核酸(FANA)为极端条件下具有高鲁棒性的最优长链存储介质"]},{"i":38078,"as":"对比分析增强岩石风化技术在可持续农业中的应用，指出其比传统碳去除技术更具前景。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":3.0,"t":3.0},"kp":["技术应用前景[增强岩石风化技术在农业中]: 比传统二氧化碳去除技术更具可持续性和发展前景"]},{"i":38079,"as":"在非小细胞肺癌中，甲基转移酶METTL5表达上调，其缺失会抑制肿瘤细胞的增殖和迁移。尽管野生型p53是传统的肿瘤抑制因子，但在METTL5缺失引起癌症消退的过程中，野生型p53却通过维持线粒体呼吸发挥了缓解肿瘤抑制的促癌作用。","scd":null,"kp":["表达水平[非小细胞肺癌中的METTL5]: 上调","临床相关性[METTL5表达与非小细胞肺癌]: 与晚期肿瘤分级和不良预后相关","生物学机制[野生型p53在METTL5缺失时的作用]: 通过维持线粒体呼吸发挥致癌作用，缓解由METTL5缺失引起的癌症消退"]},{"i":38080,"as":"","scd":null,"kp":[]},{"i":38081,"as":"TDP-43蛋白的错误定位和积累是肌萎缩侧索硬化症(ALS)和额颞叶痴呆(FTD)的关键病理特征。研究通过遗传筛选发现，内质网跨膜蛋白IRE1能够强效抑制TDP-43蛋白水平。核糖体相关质量控制(RQC)因子在调节TDP-43蛋白稳态中也发挥着至关重要的作用。","scd":null,"kp":["病理特征[ALS/FTD发生发展]: TDP-43蛋白的胞质错误定位和异常积累","调控机制[IRE1调节TDP-43蛋白质稳态]: 通过核糖体相关质量控制(RQC)途径调节"]},{"i":38082,"as":"安东尼奥·加西亚-贝利多是西班牙发育生物学的先驱。他发现了果蝇翅膀中“发育区室”的存在，并提出这些区域对应于同源异型基因的作用范围。他始终坚持以数据为核心的科学精神，为发育遗传逻辑的建立做出了杰出贡献。","scd":null,"kp":["科学发现[果蝇翅膀发育遗传学]: 发现了“发育区室”的存在"]},{"i":38083,"as":"约翰·P·斯莫尔通过研究湖泊沉积物岩芯揭示了数十年至数百年间的环境变化，确立了古湖沼学这一科学学科。他的研究记录了酸雨对北美湖泊的影响和北极气候变暖趋势。近期研究表明，由于变暖加速，即使是最深层的北极湖泊也正在跨越生态阈值，对土著渔业产生影响。","scd":null,"kp":[]},{"i":38084,"as":"针对McWilliams关于位势坐标系中排除水平重力的理论模型发布学术更正与说明。","scd":null,"kp":[]},{"i":38085,"as":"基于北美五大湖23年的天气雷达数据，对成千上万只鸣禽的迁徙轨迹分析证实了“群体智慧”现象。较大的鸟群比较小鸟群能更准确地朝种群的迁徙方向定向。这种多错效应平均了个体导航误差，但鸟群规模随时间下降的趋势削弱了群体的导航性能。","scd":null,"kp":[]},{"i":38086,"as":"在开花植物中，茎尖分生组织(SAM)的稳态由WUSCHEL(WUS)基因与多种植物激素信号通路共同维持。油菜素类固醇(BR)信号通过增强组织中心中WUS的表达并调节其活性来维持SAM稳态。BR信号受损会导致SAM尺寸减小、提前终止以及总花数减少，BR与细胞分裂素协同激活WUS。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["油菜素类固醇信号[茎尖分生组织稳态调控]: 通过协同增强细胞分裂素与WUSCHEL活性来维持分生组织稳态"]},{"i":38087,"as":"截肢导致运动感觉与运动执行解耦。肌动觉界面(MKkI)通过远程振动植入截肢前臂肌肉中的永磁体来恢复动觉。参与者报告了符合生理学边界的手部开合协调运动感。从单一前臂肌肉引出的复杂协调抓握感表明，大脑中的动觉表征具有模块化的结构特征。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["动觉界面[截肢患者假肢控制]: 植入永磁体的肌动动觉界面(MKkI)","运动感觉恢复机制[前臂肌肉植入磁体远程振动]: 协调的指部开合运动感且受限于生理范围"]},{"i":38088,"as":"利用火星毅力号车上的拉曼光谱仪，在火星杰泽罗陨石坑古河谷的泥岩中检测到了具有异质分布的有机碳。两块泥岩的数百次检测证实了有机物的存在，这也是火星自然岩石表面大分子碳的首次明确探测。光谱分析显示，有机物与成岩或沉积矿物存在明确的空间关联。","scd":{"b":8.0,"i":5.0,"r":8.0,"d":6.0,"t":7.0},"kp":["复杂有机物探测[火星杰泽罗陨石坑古老河谷泥岩]: 拉曼光谱仪探测到数百处有机物信号","大分子碳探测[火星自然岩石表面]: 首次探测到大分子碳"]},{"i":38089,"as":"","scd":null,"kp":[]},{"i":38090,"as":"室旁核（PVN）催产素（OXT）神经元在调节应对社会威胁的防御行为中具有功能多样性。急性社会挫败应激（ASDS）会激活小鼠的PVN OXT神经元。研究发现，在遭受攻击时，投射至伏隔核（NAc）的PVN OXT神经元受到抑制，而投射至中央杏仁核的PVN OXT神经元被激活。通过狂犬病毒追踪和环特异性技术，研究揭示了其特定的神经元回路基础。","scd":null,"kp":[]},{"i":38091,"as":"电化学水分解被用于大规模制氢，但阳极析氧反应（OER）动力学迟缓且过电位高。用甲醇氧化反应（MOR）替代OER可提高能效。研究报道了一种界面工程化的RuOx@Mo(Mn)Ox自活化催化剂，具有不对称的Ru-O位点。该催化剂在安培级电流密度下表现出高活性、高选择性和长期稳定性，为工业级制氢提供了高效的电催化方案。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["阳极反应[电化学制氢]: 以甲醇氧化反应(MOR)替代缓慢高电势的析氧反应(OER)","催化剂设计[高效电化学甲醇氧化]: 具有不对称Ru-O位点的自活化催化剂"]},{"i":38092,"as":"识别蛋白质结合的DNA位点对理解基因组功能至关重要。研究开发了一种全基因组脱氨测序技术，将紫外线照射诱导的光产物（嘧啶二聚体）转化为突变。该技术在超深度覆盖率下生成了酿酒酵母的定量光足迹。通过比较细胞DNA与裸露DNA，该方法能够高分辨率地解析蛋白质的占用情况，且无序列偏好，实现了在活细胞内研究蛋白质-DNA相互作用。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":[]},{"i":38093,"as":"为解释距主震数千公里外引发远程地震的现象，研究提出了一种基于断层泥孔隙压力动态变化的统一机制。基于临界状态土力学的边界面模型计算表明，远震波的动态加载驱使孔隙压力增加，其幅度数倍于施加的应力幅度，从而显著弱化断层，使其在微小扰动下即可发生破坏。波的压缩分量在放大孔隙压力方面的作用远大于剪切分量。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":[]},{"i":38094,"as":"人类乙醛脱氢酶1B1（ALDH1B1）活性低下的变体通常存在（等位基因频率>0.1%）。部分错义变体活性低且不稳定，三个变体因提前终止密码子导致功能完全丧失。携带ALDH1B1 G193fs和ALDH2*2 E504K双基因敲入的小鼠实验表明，这两种共同常见的无活性变体会导致小鼠在单次乙醇剂量后表现出升高的神经炎症反应。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":38095,"as":"为优化抑郁症管理中的可穿戴生物电子学，研究开发了一个三重分类框架，以识别处于不可逆发病前的可逆“疾病前状态”。通过复杂系统理论分析多模态生物标志物的早期预警信号。利用超软神经电子器件连续监测，人工智能代理结合多模态数据，以95.2%的准确率实现了对正常、疾病前和疾病状态的分类，准确定义了临界转变点。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["连续监测多模态生物标志物数量[抑郁症前兆预警]: 9种","疾病状态分类框架[抑郁症可穿戴生物电子干预时机]: 识别疾病前可逆状态的三重分类AI框架"]},{"i":38096,"as":"","scd":null,"kp":[]},{"i":38097,"as":"","scd":null,"kp":[]},{"i":38098,"as":"","scd":null,"kp":[]},{"i":38099,"as":"在时空上建立一个一致适用的量子态概念是构建相对论量子理论的关键步骤。该研究通过因果不可知论的测量方法，赋予了任意时空区域中多部分量子态以操作意义上的可测量性，为在时空中探测量子态提供了全新的物理视角。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":["量子态定义[时空干涉测量]: 通过因果不可知测量方法赋予多部分量子态跨时空的操作性意义"]},{"i":38100,"as":"微波屏蔽技术的最新进展增强了极性分子的稳定性与控制力。受此启发，研究人员通过模型探讨了在具有SU(N)对称性的屏蔽极性分子中，具有吸引力的SU(3)费米-哈伯德模型内Trion（三子）的形成机制及其在空间中的排序规律。","scd":{"b":9.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["微波屏蔽控制[极性分子大型阵列]: 提高稳定性和控制力","分子玻色-爱因斯坦凝聚态[微波屏蔽极性分子]: 首次实现","对称性特征[屏蔽极性分子]: 表现出SU(N)对称性"]},{"i":38101,"as":"","scd":null,"kp":[]},{"i":38102,"as":"","scd":null,"kp":[]},{"i":38103,"as":"储备工程可实现能量和信号的单向流动。研究确立了两个腔体之间由挤压引起的对称性破缺作为物理机制，能够呈指数级放大由储备介导的非互易性。该机制并非简单缩放耦合强度，而是策略性地增强非互易传输，为单向量子器件设计提供了指导原则。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["非互易性放大机制[双腔系统]: 挤压引起的对称性破缺可指数级放大"]},{"i":38104,"as":"","scd":null,"kp":[]},{"i":38105,"as":"","scd":null,"kp":[]},{"i":38106,"as":"交变磁体具有独特的双重特性：在动量空间中类似铁磁体具有自旋劈裂的电子能带，而在实空间中维持类似反铁磁体完全补偿的磁化强度。研究通过超快磁光技术，成功在MnTe材料中探测到了交变磁性特有的超快自旋动力学指纹特征。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":8.0},"kp":["交变磁性特征[MnTe晶体等材料]: 动量空间中具有类似铁磁体的自旋分裂能带，实空间中保持反铁磁体的完全补偿磁化"]},{"i":38107,"as":"受保护状态因其固有的抗噪声能力在量子技术中极具潜力，但在实验中难以寻找。研究提出了一种机器学习方法，通过探测和调整系统参数空间中的抗噪能力，能够有效定位并优化这些通常只存在于离散参数点的受保护量子态。","scd":{"b":6.0,"i":2.0,"r":8.0,"d":5.0,"t":8.0},"kp":["机器学习应用[量子态抗噪保护]: 通过探测抗噪能力调整和寻找参数空间中难以发现的受保护状态"]},{"i":38108,"as":"研究采用实空间密度矩阵重整化群方法，在巨正则和正则系综下，分析了具有Kanamori-Hubbard相互作用的Bernevig-Hughes-Zhang模型。在二维量子自旋霍尔绝缘体中，研究详细探讨了由电子-电子相互作用驱动的边缘重建现象及其物理机制。","scd":{"b":6.0,"i":1.0,"r":7.0,"d":5.0,"t":8.0},"kp":["边缘重建机制[量子自旋霍尔绝缘体]: 相互作用驱动的边缘重建","计算模型[BHZ模型与Kanamori-Hubbard相互作用]: 结合巨正则和正则系综的实空间密度矩阵重整化群方法"]},{"i":38109,"as":"研究团队采用元胞动力学平均场理论，对二维哈伯德模型中超导关联的频率结构进行了系统且详尽的量化研究。研究系统量化了其各项依赖关系，旨在深入揭示并解释铜氧化物材料中的超导配对机制。该成果发表于《物理评论快报》。","scd":{"b":6.0,"i":1.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[二维哈伯德模型超导关联分析]: 采用元胞动力学平均场理论系统量化频率结构与超导对的依赖关系"]},{"i":38110,"as":"研究人员提出了一种针对非微扰S矩阵泛函的重正化群流方程。该方程能够生成S矩阵元素，并展现出与著名的Wetterich和Polchinski方程相似的特性。该理论成功扩展了现有的重正化群方程框架，为非微扰性质的物理过程研究提供了新工具。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":5.0,"t":8.0},"kp":["[非微扰S-矩阵重正化]: 提出生成S矩阵元素的泛函重正化群流方程"]},{"i":38111,"as":"凝聚态系统为在量子临界点涌现时空超对称性（SUSY）提供了重要平台。研究人员深入探讨了二维分数化量子临界点处的时空超对称性，证实了在特定对称性破缺的量子临界点处可以涌现出超对称性，为实验研究提供了新的理论方向。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":5.0,"t":8.0},"kp":["[凝聚态系统对称性破缺量子临界点]: 涌现出时空超对称性"]},{"i":38112,"as":"基于KTaO3的氧化物界面的超导转变温度（Tc）强烈依赖于晶体的晶格取向。研究团队在a-LaAlO3/KTaO3界面处发现并报道了Tc与单一几何参数（即晶体取向角度）之间存在线性缩放关系，为解释该界面的超导机制提供了关键的实验证据。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":7.0,"t":8.0},"kp":["超导转变温度Tc[KTaO3基氧化物界面]: 与晶体取向几何角度参数呈现线性缩放关系"]},{"i":38113,"as":"基于线性理论推导的离子驱动等离子体不稳定性阈值，严格限制了太阳风观测的参数空间分布并界定了稳定等离子体参数的边界。当超出这些阈值时，粒子能量会转移至相干电磁波，从而引发太阳风加热现象。研究阐明了倾斜漂移不稳定性对太阳风加热与观测分布的影响。","scd":{"b":6.0,"i":1.0,"r":7.0,"d":5.0,"t":8.0},"kp":[]},{"i":38114,"as":"研究构建了一个通用模型，量化了全球环境变化率、生物进化适应率与物种灭绝之间的内在联系。模型测试了环境变化速度超过物种适应能力会导致灭绝的传统假设，揭示了由于适应率分布未知，在全球尺度上验证该假设的机制。","scd":{"b":5.0,"i":1.0,"r":7.0,"d":5.0,"t":8.0},"kp":[]},{"i":38115,"as":"研究探讨了化学活性乳液在相分离过程中的复杂动力学行为。研究证明，在远离热力学平衡的化学活性乳液中，化学反应、相分离与流体动力学效应的相互作用导致了复杂的自组织现象，并在系统中引发了流体流动与时空混沌。","scd":{"b":6.0,"i":1.0,"r":7.0,"d":5.0,"t":8.0},"kp":["[相分离流体混合物]: 化学反应、相分离与流体动力学的相互作用导致复杂的自组织时空混沌"]},{"i":38116,"as":"研究团队在相干驱动的双稳态光学微腔的随机切换过程中，证实了热力学不可逆性的存在。通过测量相空间概率流，研究提供了打破细致平衡的直接证据，该现象与热力学不可逆性直接相关，并定量评估了其不可逆性的量级。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":["[相干驱动双稳态光学腔]: 展现出热力学不可逆性并打破细致平衡"]},{"i":38117,"as":"手性物体对两种不同的圆偏振光通常表现出不同的消光特性，传统检测方法多采用圆二色性光谱技术。研究人员提出了一种全新的光学手性光谱检测技术，旨在更加精确、高效地检测物体的手性特征，为手性材料的光谱表征提供了新方法。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":["[手性物体检测]: 提出一种新型手性光学光谱检测技术"]},{"i":38118,"as":"研究团队提出了一种针对含时密度泛函理论（TDDFT）的几何重构方案。这种全新的几何公式重构方法能够更加准确地描述处于非平衡态的系统，为计算和解决非平衡态物理问题提供了改进的理论框架。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":3.0,"t":8.0},"kp":["[非平衡系统描述]: 提出一种几何瞬态密度泛函理论重整方案以更好描述系统状态"]},{"i":38119,"as":"研究人员提出利用杂散场磁力测量技术，直接探测量子自旋冰中涌现的光子，即无带隙的涌现电动力学激发。该方法为实验上确切证实量子自旋冰中U(1)量子自旋液体相提供了一种直接的探测手段，突破了现有的实验挑战。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":4.0,"t":8.0},"kp":["[量子自旋冰U(1)量子自旋液体相]: 提出杂散场磁力测量作为直接探测涌现光子的探针"]},{"i":38120,"as":"","scd":null,"kp":[]},{"i":38121,"as":"质子交换膜水电解槽在低铱负载下实现持久酸性水氧化是一大瓶颈。研究人员提出了一种限制工程策略，在层状共价有机框架的纳米通道内构建了具有2.68埃收缩Ir-Ir双位点几何结构的超薄双晶Ir-IrO2界面，成功激活了氢键介导的氧化物途径机制（OPM）。","scd":{"b":8.5,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[质子交换膜水电解阳极氧化]: 低铱负载下实现持久酸性水氧化","Ir-Ir双位点距离限制[高阳极电位]: <2.9 Å (低于该值不稳定)","[OPM氧化物途径机制激活]: 通过限制工程化Ir-IrO2界面由氢键介导激活"]},{"i":38122,"as":"钾离子电池在低温下面临去溶剂化动力学迟缓的挑战。研究人员耦合高浓度电解质与氟苯（FB）和碳酸丙烯酯（PC）间的拖曳效应，设计出新型电解液。该电解液富含接触离子对和聚集体，使粘度降低三倍，离子电导率提升40%，极大促进了体相和界面离子传输，使电池在-50°C下稳定运行。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["Stokes半径[K+在碳酸丙烯酯中]: 3.6 Å","运行温度[氟苯介导的钾离子电池]: -50°C"]},{"i":38123,"as":"利用可再生电力直接将碳酸氢盐电化学转化为乙烯等多碳（C2+）产品是实现碳利用的可持续途径。针对CO2利用率低和反应环境不佳的痛点，研究人员提出了一种全新的电极设计以调节局部反应环境，直接转化碳酸氢盐，打破了传统方法中选择性与能量效率之间的权衡限制。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["目标产物[碳酸氢盐电化学转化]: 多碳产品（如乙烯）","反应体系[阴极环境调节]: 直接电合成CO2还原"]},{"i":38124,"as":"研究通过热力学与电子结构分析结合颗粒自组装技术，构建了具有分层多孔结构的高熵合金气凝胶。其晶格畸变产生微应变场和纳米孪晶界，破坏了原子周期性，形成了不饱和的Pd配位环境并增加活性位点密度；同时发生从3d到4d的电子转移，有效促进了锌空气电池的氧还原反应。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["材料结构[高熵合金气凝胶]: 纳米孪晶与分级多孔结构","催化机制[氧还原反应]: 缺乏Pd配位与多轨道杂化"]},{"i":38125,"as":"针对质子陶瓷燃料电池（PCFCs）中质子传输受限和表面阳离子偏析的挑战，研究人员开发了一种基于原子层沉积（ALD）的原位反向原子捕获策略。该策略在钙钛矿阴极表面原位构建了质子导体，显著增强了质子传导能力和氧还原反应动力学。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":7.0,"t":7.0},"kp":["材料改性策略[质子陶瓷燃料电池阴极]: 原子层沉积原位反向原子捕获","改性效果[阴极优化]: 增强质子传导与氧还原动力学"]},{"i":38126,"as":"添加剂与钙钛矿之间的结合亲和力对器件长期稳定性至关重要。研究提出利用手性立体锚定策略，通过引入手性分子构型作为结晶调节剂来调控FAPbI3钙钛矿的胶体结晶。由于具备更优的空间位阻可及性，R型分子在钙钛矿表面展现出比S型分子更有利的吸附几何构型，大幅提升了太阳能电池的性能。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["结晶调控策略[FAPbI3钙钛矿]: 手性分子立体锚定","作用机制[添加剂与钙钛矿作用]: 调节胶体结晶并最大化结合亲和力"]},{"i":38127,"as":"研究开发了一种含有四丁基铵（TBA+）阳离子和高氯酸根（ClO4-）阴离子的多功能无氟电解液添加剂，构建了环保型电解液体系，显著提升了钠离子电池在宽温范围内的快充性能。其中，TBA+阳离子凭借其低还原电位诱导产生静电屏蔽效应，协同阴离子优化了溶剂化化学。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["电解液添加剂[宽温快充钠离子电池]: 四丁基铵阳离子和高氯酸根阴离子","协同机制[溶剂化与屏蔽]: 增强溶剂化化学与阳离子静电屏蔽"]},{"i":38128,"as":"嵌段共聚物通过微相分离可构建力学可编程的网络结构。研究合成了CO2基聚碳酸酯共聚物，深入剖析了可交联的玻璃态A嵌段与非交联柔态B嵌段的重复单元序列和溶剂环境及其相互作用。通过调节还原光聚合顺序和溶剂选择性溶胀，实现了对交联共聚物机械性能的精准调控。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":4.0,"t":6.0},"kp":["性能调控机制[嵌段共聚物光聚合]: 重复单元序列和溶剂选择性溶胀","材料特点[还原光聚合]: 机械性能可编程的微相分离网络结构"]},{"i":38129,"as":"该研究提出一种喷雾辅助原位组装策略，在玻璃纤维基底上构建唑醇杂化框架，经热聚合形成阻燃准固态电解质。该杂化框架提供有序的亲锂配位位点与连续离子传输通道，实现高效的锂离子迁移与优异的热稳定性，从而提升锂电池的安全性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["电解质形态[锂电池]: 基于唑醇杂化框架的阻燃准固态","制备工艺[电解质成型]: 喷雾辅助原位自组装"]},{"i":38130,"as":"该技术结合化学氧化还原反应与电化学电位，精确调控苝二酰亚胺-组氨酸（PDI-His）的超分子聚合。利用连二亚硫酸钠的化学还原过程，将分子内氢键稳定的动力学捕获二聚体快速转变为热力学有利的螺旋纳米纤维，实现了可编程的动力学自适应材料构建。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":4.0,"t":6.0},"kp":["驱动方式[超分子聚合]: 整合化学氧化还原与电化学电位","材料体系[超分子组装]: 苝二酰亚胺-组氨酸"]},{"i":38131,"as":"针对钙金属阳极表面钝化阻碍Ca2+传输的问题，该技术在Ca[B(hfip)4]2/DME电解质中引入约139 ppm的微量水。这些微量水稳定进入Ca2+溶剂化鞘层，引导可控的电化学水解路径，从而避免了有害的体相副反应，有效改善了钙金属电池的界面化学与沉积均匀性。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":8.0,"t":7.0},"kp":["水含量[Ca[B(hfip)4]2电解质]: ~139 ppm","界面机制[钙金属阳极SEI]: 水介导固体电解质界面形成"]},{"i":38132,"as":"针对La3-xTe4热电材料，研究突破传统取代掺杂或空位调节的局限，采用间隙铜掺杂策略。该方法在不产生相互干扰的前提下，同时调节材料的电学和热学性能，即优化载流子浓度、调节导带结构并抑制晶格热导率，从而显著提升了其应用于放射性同位素热电发生器的热电性能。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["材料体系[同位素热电发电机]: La3-xTe4","性能优势[La3-xTe4材料]: 极佳的热电性能与高温稳定性","[La3-xTe4载流子浓度调控]: 间隙铜掺杂与热激活"]},{"i":38133,"as":"该研究开发了一种新型多孔有机聚合物（POPs）合成方法。通过胺类对亚胺的亲核加成反应，使用间苯二胺交联线性聚亚胺，形成缩醛胺连接结构。该材料具有高达650 m2/g的比表面积和丰富的微孔，且估算成本仅为16美元/千克，非常适用于C2烃与甲烷的分离。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":6.0},"kp":["[多孔有机聚合物(POPs)合成]: 线性聚亚胺与间苯二胺通过亚胺亲核加成交联形成缩醛胺连接","[应用场景]: C2烃/甲烷分离"]},{"i":38134,"as":"为解决富锂锰基层状氧化物晶格氧释放和结构退化问题，研究在富锂材料中引入硼异质配位结构，构建约4纳米厚的富BO3表面层并保留内部的BO4结构。这种表面BO3构型使四面体BO4和三角BO3发生位移，实现了高度稳定的阴离子氧化还原反应，提升了电池的库伦效率和循环稳定性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["材料体系[高能量密度锂电池]: 富锂锰基层状氧化物(LRMOs)","表面构型[LRMOs正极材料]: 引入BO3非均相配位结构","作用机制[BO3非均相配位结构]: 抑制晶格氧释放和表面结构退化，实现高度稳定的阴离子氧化还原反应"]},{"i":38135,"as":"","scd":null,"kp":[]},{"i":38136,"as":"针对细胞间分子张力检测挑战，研究开发了一种基于DNA的力锁定整合探针（FLIP）系统。该探针利用膜锚定DNA发夹作为受力传感器，展开时与带荧光标记的锁链杂交形成稳定双链，并结合细胞内吞作用，将瞬时的膜张力信号转化为长期的细胞荧光，实现了单细胞水平累积分子张力的记录。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[细胞间分子张力检测系统]: 力锁定DNA发夹探针(FLIP)","检测特点[细胞间分子张力]: 高通量且能随时间记录累积的分子张力事件"]},{"i":38137,"as":"针对水系锌离子电池中锌阳极析氢和腐蚀等副反应，研究提出一种原位聚合水凝胶涂层策略。在锌表面构建包含聚乙二醇和高浓度ZnCl2的聚丙烯酰胺（PAM）水凝胶层。该多功能界面层通过氢键作用有效抑制水分子活性并调节Zn2+溶剂化结构，显著稳定了锌金属阳极。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":7.0,"t":6.0},"kp":["界面工程策略[水系锌离子电池锌阳极]: 原位聚合PAM基水凝胶涂层(包含PEG和浓缩ZnCl2)","稳定机制[锌阳极界面]: 通过氢键抑制水活性并调节溶剂化结构"]},{"i":38138,"as":"该研究设计了Ir/NiFe层状双氢氧化物异质结构用于海水电解。金属Ir到NiFe LDH的自发界面电荷转移形成内置电场，调节活性中心电子结构，同时激活吸附物演化机制和晶格氧机制，加速析氧反应（OER）动力学。此外，Ir-Cl基序的氯离子汇效应有效抑制了寄生氯氧化，提升了选择性与耐久性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["催化剂[碱性海水电解]: Ir/NiFe层状双氢氧化物异质结构","[海水电解选择性与耐久性提升机制]: 异质界面内置电场与Ir-Cl基序实现双路径OER动力学促进及氯化物汇效应"]},{"i":38139,"as":"欧洲原子能共同体为ITER项目提供了关键的等离子体与第一壁诊断系统，承担了约四分之一的核心测量任务，以避免部件损坏、控制等离子体并探索物理特性。具体贡献包括八个诊断系统、六个端口塞以及广泛的生命电气系统。目前这些系统的设计阶段已近尾声，许多部件已进入制造环节。","scd":{"b":4.0,"i":5.0,"r":5.0,"d":5.0,"t":5.0},"kp":["诊断系统数量[欧洲实物贡献]: 8","端口插件数量[欧洲实物贡献]: 6","测量提供占比[避免损伤、控制等离子体及探索物理的基础测量]: 约1/4","设计阶段进度[欧洲对ITER诊断及端口集成系统]: 接近完成"]},{"i":38140,"as":"蛋白质是动态的分子机器，其功能与运动方式紧密相关。通过核磁共振波谱和分子动力学模拟，研究发现GB1蛋白结构域的动力学运动受到其分子邻近环境的显著影响。这一发现表明，通过调节蛋白质的结构可塑性，能够实现对蛋白质功能的精确控制。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[蛋白质动力学机制]: 分子邻居环境可重塑蛋白质动力学并改变其运动状态","[蛋白质功能调控方法]: 调节结构可塑性以控制蛋白质功能"]},{"i":38141,"as":"该研究对3至8级中型和重型车辆的温室气体排放进行生命周期评估。结果表明，与传统柴油车相比，各类替代动力系统均能减排：混合动力车减排1-26%，电网供电纯电动车减排44-68%，而由可再生电力驱动的纯电动车和氢燃料电池车的减排效果最为显著，分别达到87-92%和72-82%。","scd":{"b":4.0,"i":5.0,"r":5.0,"d":7.0,"t":4.0},"kp":["[中重型车辆脱碳技术评估]: 对比内燃机、混合动力(HEV)、燃料电池(FCEV)和纯电动(BEV)车辆进行全生命周期温室气体排放评估"]},{"i":38142,"as":"该研究通过一步法制备出乙基纤维素涂层，成功克服了传统辐射制冷材料在着色与高太阳能反射率之间的矛盾。该涂层能产生鲜艳的结构色，具备极低的太阳能吸收率与高长波红外发射率。在阳光照射下，涂层能够实现低于环境温度达9℃的日间冷却效果。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["太阳反射率[彩色辐射冷却涂层]: 具有可忽略的太阳吸收率和高长波红外发射率","亚环境日间冷却[彩色辐射冷却涂层]: 阳光下最高可达9℃","[涂层制备工艺]: 乙基纤维素涂层一步法制备并获得鲜艳的结构色"]},{"i":38143,"as":"针对钙钛矿太阳能电池对热和湿度敏感的问题，该研究开发了一种级联空穴转移策略。该策略应用于混合钙钛矿/有机太阳能电池中，能够有效抑制电荷的复合过程，同时为器件提供内在的防潮稳定性，从而显著提升了电池的实用性与耐久性。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":6.0,"t":6.0},"kp":["稳定性[混合钙钛矿太阳能电池]: 对热和水分敏感限制实际应用","抑制机制[混合钙钛矿/有机太阳能电池]: 级联空穴转移策略抑制电荷复合并提供本征湿度稳定性"]},{"i":38144,"as":"该研究开发出一种兼具低电阻率与高电荷-自旋转换效率的极性金属。这种层状双辉铜矿材料通过极性畸变打破反演对称性，同时在材料内部保持极高的金属导电性。这一特性的结合大幅提升了自旋源材料的能量转换效率。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["物理机制[层状 delafossite]: 极性畸变打破反演对称性同时保持高金属电导率","自旋源材料[能量效率]: 低电阻率与高电荷-自旋转换在同一材料中结合"]},{"i":38145,"as":"使火星变得宜居正从科幻构想转变为受到关注的科学议题。研究人员就如何改造火星环境以适合人类生存进行了探讨，并设计出了一套模拟自然界生态改造机制的实验性方案。","scd":{"b":2.0,"i":1.0,"r":4.0,"d":2.0,"t":3.0},"kp":[]},{"i":38146,"as":"该研究开发了一种基于配体的过渡金属催化策略，利用专门设计的O-烯丙基酰胺基酯（OAAE）配体，通过钯催化实现无偏脂肪族羧酸中远端γ-亚甲基和甲基C(sp3)-H键的区域选择性活化。该技术克服了构象柔性带来的近端激活偏好，成功将脂肪酸底物直接转化为远端去饱和与内酯化产物。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["配体策略[脂肪酸远端去饱和内酯化]: 设计的O-烯丙基酰胺配体实现惰性C(sp3)-H键的区域选择性远端活化"]},{"i":38147,"as":"为了克服传统核酸酶基因组编辑在人类胚胎中产生的基因毒性，研究应用腺嘌呤碱基编辑技术（ABE8e），精确靶向外显子剪接供体位点，导致剪接缺陷从而实现NANOG基因的功能性敲除。这是碱基编辑首次在人类胚胎发育研究中的应用，揭示了NANOG在人类胚胎首次细胞谱系分化中的关键作用。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[基因编辑人类胚胎]: 揭示NANOG转录因子在人类胚胎发生和早期细胞谱系维持中的关键作用"]},{"i":38148,"as":"","scd":null,"kp":[]},{"i":38149,"as":"","scd":null,"kp":[]},{"i":38150,"as":"中国的LineShine超级计算机近期成功登顶全球超算排行榜。该系统具备业界领先的性能表现，其核心在于采用了创新的芯片设计架构。得益于这一技术突破，该超级计算机能够实现极其强大的数据处理能力，每秒可执行超过200京（百亿亿）次的高速计算。这一成就标志着中国在尖端计算硬件技术上取得了重大进展，进一步巩固了其在全球超算领域的领先地位。","scd":{"b":7.0,"i":8.0,"r":7.0,"d":6.0,"t":8.0},"kp":["计算性能[超级计算机创新芯片设计]: >2 quintillion次/秒 (200万万亿次/秒)"]},{"i":38151,"as":"研究人员通过开发具有偏振分辨率的高场磁红外光谱系统，首次在II型外尔半金属Mn(Bi1-xSbx)2Te4中观察到了巨大的宽带红外圆二色性现象。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["观测现象[II型外尔半金属Mn(Bi1-xSbx)2Te4]: 首次观测到巨大的宽带红外圆二色性","测试仪器[外尔半金属红外手性研究]: 具有偏振分辨率的高场磁红外光谱系统"]},{"i":38152,"as":"低密度脂蛋白（LDL）携带的胆固醇由表达LDL受体（LDLR）的肝细胞清除。研究发现，高胆固醇通过特定的细胞信号传导机制促进酶介导的LDLR降解。阻断该酶可恢复肝细胞中的LDLR水平，为治疗高胆固醇提供了新策略。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[长期高胆固醇环境]: 通过细胞信号传导机制促使LDLR受体蛋白发生酶介导的细胞内降解","[阻断LDLR降解酶]: 恢复肝细胞LDLR受体水平，提供治疗高胆固醇的新策略"]},{"i":38153,"as":"研究发现，氘原子核对电场的响应未显示出不对称性的证据，这一实验结果与传统的粒子物理学理论完全相符。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[重氢原子核电场响应]: 无不对称性证据，符合传统粒子物理学理论"]},{"i":38154,"as":"随着基因组编辑科学的不断进步，研究人员指出，当前迫切需要针对人类胚胎编辑等相关技术开展伦理讨论，以应对技术发展带来的伦理挑战。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[人类基因组编辑技术]: 技术进展引发关于人类胚胎研究的伦理争论"]},{"i":38155,"as":"针对低光子通量下超低剂量X射线成像面临的泊松涨落和非均匀性瓶颈，研究开发出一种新型液相生长与退火（LPGA）策略。该策略消除了传统方法中的热学和传质不稳定性，成功制备出垂直均匀的钙钛矿薄膜，从而满足了自动化定量AI成像对可靠探测器的需求。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["材料特征[低剂量X射线成像探测器]: 垂直均匀钙钛矿薄膜"]},{"i":38156,"as":"自然界中的旋转分子电机能够响应环境变化反转其旋转方向。近期两项研究提出了全新方法，成功实现了在全合成分子电机中反转旋转运动方向。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":4.0,"t":7.0},"kp":["[合成分子旋转电机]: 开发出响应环境变化反转旋转方向的新策略"]},{"i":38157,"as":"将脂肪族醛转化为羟酮类自由基常用于构建碳-碳键，但酮的同类反应此前尚未见报道。研究利用源自酮的甲硅烷基氰醇的自由基重排策略，成功实现了这一转化过程。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[酮类衍生的甲硅烷基氰醇]: 利用自由基重定位策略实现酮向羰基型自由基转化并构建碳-碳键"]},{"i":38158,"as":"出版商更正声明，涉及高效蓝色钙钛矿LED的原位纳米晶体限制技术，主要修正已发表论文的细节错误。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":[]},{"i":38159,"as":"H5高致病性禽流感病毒在全球范围内感染了超过60种哺乳动物。研究结合空间转录组和单细胞基因组学，构建了H5病毒感染禽类和哺乳动物肺部的单细胞转录图谱。研究发现H5病毒主要感染禽类内皮细胞和哺乳动物上皮细胞，并在成纤维细胞中诱发严重炎症，导致肺泡上皮脱落。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":9.0,"t":7.0},"kp":["[H5高致病性禽流感病毒]: 全球引发超过60种哺乳动物感染","[H5流感病毒感染肺部单细胞图谱]: 整合空间转录组学构建了鸟类和哺乳动物肺部1499669个细胞的转录组学景观"]},{"i":38160,"as":"纳米科学提供了必要的概念和技术桥梁，将物理和生物学的视角统一起来，从而在机械生物学领域中实现了跨学科的深度融合。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["学科交叉[纳米技术与机械生物学]: 纳米科学提供统一物理学和生物学视角的概念与技术桥梁"]},{"i":38161,"as":"光辅助锂氧电池受限于光生载流子与Li2O2化学反应的耦合效率。研究开发了氟取代石墨二炔（FGDY）作为光响应阴极。在光照下，FGDY发生分子内电荷重排，调节锂离子和氧中间体的吸附，促使Li2O2沿着纤维网络呈膜状生长，而非形成绝缘盘状晶体。该策略显著提高了反应可逆性，使电池在光照下的往返效率达到97.5%。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":8.0,"t":7.0},"kp":["光电极材料[光辅助锂氧电池]: 氟取代的石墨二炔(FGDY)","电荷机制[FGDY光电极]: 光诱导分子内电荷重排调控Li+及氧中间体的吸附","Li2O2沉积形貌[FGDY网络]: 沿纤维网络生长的膜状结构而非绝缘的盘状晶体"]},{"i":38162,"as":"全固态电池中的界面接触损耗常被归因于锂金属界面的空洞形成。研究表明，剥离过程中锂负极内部的绝缘杂质会在界面处积累，形成一层多孔且机械稳定的阻挡层，从而阻断锂离子进入电解质的通量。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["接触损耗原因[全固态电池]: 锂负极内部绝缘杂质在剥离过程中于界面累积","界面阻挡层[锂负极剥离过程]: 形成多孔且机械稳定的阻挡层阻断锂通量"]},{"i":38163,"as":"全球塑料行业实现温室气体净零排放依赖于生物基材料、碳捕获与利用（CCU）以及清洁氢能。前瞻性生命周期评估显示，到2050年实现净零排放需要将氢气需求增加14倍，总量达到1.26至1.45亿吨。结合生物基和电力制氢技术，塑料行业能够有效平衡多种地球环境边界。","scd":{"b":5.0,"i":4.0,"r":7.0,"d":8.0,"t":6.0},"kp":["氢气需求增长倍数[2050年净零温室气体排放全球塑料行业]: 14倍","氢气总需求量[2050年净零温室气体排放全球塑料行业]: 126–145 Mt"]},{"i":38164,"as":"细菌通过细胞外膜囊icles进行细胞间的合作与分子共享，这种机制显著提升了细菌在抗生素环境下的持久存活能力。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":4.0,"t":7.0},"kp":["[细菌在抗生素中的生存机制]: 通过膜囊泡进行细胞间合作以增强抗生素持续存活率"]},{"i":38165,"as":"","scd":null,"kp":[]},{"i":38166,"as":"","scd":null,"kp":[]},{"i":38167,"as":"","scd":null,"kp":[]},{"i":38168,"as":"RNA套索在剪接过程中形成并由脱支酶DBR1降解。研究发现，DBR1介导的脱支反应能阻止21和22个核苷酸的siRNA的产生，防止有害的外显子siRNA爆发。当DBR1功能发生障碍时，套索RNA会被DCL4和DCL2劫持并加工成siRNA，这些siRNA会靶向免疫基因，从而破坏植物的防御反应。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["异常小干扰RNA尺寸[Lariat RNA脱支受损引发的siRNA爆发]: 21和22个核苷酸","[lasiRNA生成的依赖条件]: RNA依赖机制"]},{"i":38169,"as":"研究开发了一种新的表面制备和沉积方法，在有机晶体表面的单分子中实现了傅里叶极限电子跃迁。通过在液氦温度下进行光谱分析和超分辨率显微技术，消除了退相干现象，跃迁线宽完全由激发态寿命决定。这为深入研究吸附物质的精细光谱和空间特征铺平了道路。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[表面单分子光谱学突破]: 开发了一种表面制备和沉积方法，可消除退相干并实现由激发态寿命决定跃迁线宽的傅里叶极限光谱分辨率"]},{"i":38170,"as":"","scd":null,"kp":[]},{"i":38171,"as":"","scd":null,"kp":[]},{"i":38172,"as":"","scd":null,"kp":[]},{"i":38173,"as":"","scd":null,"kp":[]},{"i":38174,"as":"科学家构建了多层方形平面镍酸盐（Ndₙ₊₁NiₙO₂ₙ₊₂）的超导相图。方形平面镍酸盐中超导性的发现为探索高温超导的起源提供了丰富的材料平台，而此前的实验研究主要局限于无限层RNiO₂镍酸盐。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[多层方形平面镍酸盐]: 构建了多层方形平面钕镍酸盐的超导相图"]},{"i":38175,"as":"","scd":null,"kp":[]},{"i":38176,"as":"研究发现，铁介导的程序性细胞死亡能够在有毒蓝藻的群落中进行传播和扩散，这一机制引发了有害藻华的协调性消亡。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":[]},{"i":38177,"as":"大型陨石撞击产生的热量可能熔化了地球早期地壳的大部分区域。这表明远古时期的巨大撞击事件在塑造和形成地球第一块大陆的过程中发挥了决定性作用。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":4.0,"t":6.0},"kp":[]},{"i":38178,"as":"化石蛋白质分析表明，在南非一个洞穴中发现的某种已灭绝人类物种的20名成员均为女性，这一发现为破解古人类种群构成和历史的古老谜团提供了直接证据。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":6.0,"t":6.0},"kp":[]},{"i":38179,"as":"使用TriNetX内置分析工具轻松撰写并发表论文数量的增加引发了学术界担忧。这些分析工具的使用虽然降低了医学研究的门槛，但极易产生和报道具有误导性的研究结果。","scd":{"b":3.0,"i":4.0,"r":5.0,"d":4.0,"t":6.0},"kp":[]},{"i":38180,"as":"美国国家科学基金会（NSF）将资金向技术计划进行了转移。这一资金分配的迟滞转变导致该机构发放的研究资助数量出现了急剧下降。","scd":{"b":1.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":[]},{"i":38181,"as":"企业与美国政府围绕人工智能安全问题展开博弈，而Fable 5模型的强制下架事件引发了研究人员对开放科学研究前景的担忧，使研究人员在这场技术争斗中陷入交火。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":7.0},"kp":[]},{"i":38182,"as":"随着构建更大、更先进聊天机器人的技术难度和挑战不断增加，人工智能研究人员正逐渐将研究重点转向能够在模拟世界中学习的智能体。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":3.0,"t":6.0},"kp":["[人工智能研究趋势]: 由于构建更大型、更优化的聊天机器人难度增加，研究重心转向在模拟世界中学习的AI智能体"]},{"i":38183,"as":"Tara极地站计划于下个月发射，旨在探索北冰洋中部的生物学特征。科学家们将在该极地站随北极冰层漂流长达8个月，以开展极地生物科学研究。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":[]},{"i":38184,"as":"美国存在这样一个科学组织，其召集科学专家遵循证据而非新闻头条，通过严谨透明的流程分析复杂问题，为国家提供清晰理解，且不服务于特定意识形态或利益。尽管面临诸多挑战，该组织在当今比以往任何时候都更为迫切地被需要。","scd":{"b":0.0,"i":1.0,"r":3.0,"d":2.0,"t":3.0},"kp":[]},{"i":38185,"as":"三位国际可再生能源领域的先驱因其在该领域的杰出贡献，被评选为Mani L. Bhaumik年度突破奖的获得者，标志着可再生能源领域拥有光明的未来。","scd":{"b":0.0,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":[]},{"i":38186,"as":"针对共价键合单分子结光开关电导率研究的勘误，主要涉及分子电子学及单分子器件的稳定性和可逆性。","scd":{"b":2.0,"i":1.0,"r":2.0,"d":2.0,"t":4.0},"kp":["[共价键合单分子结]: 具有稳定和可逆的光开关电导率"]},{"i":38187,"as":"","scd":null,"kp":[]},{"i":38188,"as":"","scd":null,"kp":[]},{"i":38189,"as":"","scd":null,"kp":[]},{"i":38190,"as":"","scd":null,"kp":[]},{"i":38191,"as":"","scd":null,"kp":[]},{"i":38192,"as":"","scd":null,"kp":[]},{"i":38193,"as":"","scd":null,"kp":[]},{"i":38194,"as":"研究结合冷冻电子显微镜、低温振动光谱和量子/分子力学建模，分析了食蟹猴红绿视锥色素的结构。红绿光谱调谐主要由285位苏氨酸的羟基偶极子调节发色团静电场主导，而空间位阻影响较小。此外，研究还识别出面向膜的特定结构特征。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["显色机制[狭鼻灵长类红绿视锥色素]: 共享11-顺式视黄醛发色团，但吸收峰值不同","结构表征[红绿视锥色素解析对象]: 食蟹猴冷冻电镜结构"]},{"i":38195,"as":"该研究阐明了人类日光视觉（主要负责日光下的快速运动和色彩感知）的分子基础。日光视觉由视锥视蛋白（一种G蛋白偶联受体）介导。尽管三种受体亚型共享同种发色团，却能吸收不同波长的光，但其光谱特性和快速响应机制此前尚不明确。\n\n研究人员利用冷冻电镜技术，结合飞秒级光谱学、功能实验和高级模拟，解析了人蓝敏感和绿敏感视锥蛋白暗适应状态的结构。结果揭示了不同视蛋白独特的发色团稳定机制，以及GPCR微开关基序中特定的序列适应特征，突显了它们的高结构可塑性与独特激活机制。这些发现深刻揭示了视觉系统为满足日光视觉需求而发生的分子进化机制。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["受体亚型[日光视觉介导蛋白]: 介导日光视觉的视锥视蛋白（ specialized G protein–coupled receptors）具有三种亚型","光谱特性[三种视锥受体]: 共享同一发色团但在可见光谱的不同波长处吸收光"]},{"i":38196,"as":"研究报道了三种人类视锥视蛋白（长波、中波、短波敏感）结合G蛋白和全反式视黄醛的活性态冷冻电镜结构。它们与视紫红质显著不同：长波和中波视蛋白具有独特的反离子位点，短波视蛋白则围绕视黄醛具有一圈丝氨酸。这些结构解释了氨基酸取代如何决定其光谱特性。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["结构表征[人类三色视觉视锥视蛋白]: 解析了三种人类视锥视蛋白（LWS、MWS、SWS）结合G蛋白和全反式视黄醛的冷冻电镜结构"]},{"i":38197,"as":"多组学分析表明泛素及相关翻译后网络参与上皮分化。对人类原代角质形成细胞的研究和条件性敲除小鼠模型证实，NEDD8在维持祖细胞、皮肤再生和炎症中发挥关键作用，而SUMO2是细胞分化所必需的。NEDD8调控的蛋白质组变化与RNA丰度直接相关。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":[]},{"i":38198,"as":"研究发现铁催化的活性脂质过氧化物是驱动开花蓝藻群体崩溃及细胞铁死亡的主要诱因。蓝藻消亡过程依次为：游离铁爆发、氧化应激、脂质过氧化和细胞死亡。脂质过氧化产生的截短磷脂会破坏细胞膜并诱导纳米级膜孔形成，最终导致突发性集体死亡。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["催化剂[驱动开花蓝藻集体细胞死亡]: 铁","[蓝藻衰亡事件的时间序列]: 游离铁爆发、氧化应激、脂质过氧化和细胞死亡"]},{"i":38199,"as":"","scd":null,"kp":[]},{"i":38200,"as":"研究以1.8至2.2埃的高分辨率解析了黄藻管状鞭毛体的冷冻电镜结构，揭示了复杂的糖基化修饰。除已知的N-聚糖外，还在AND基序上发现了非典型N-聚糖。表面密集的O-聚糖包裹着PSXX四肽重复序列，且糖类、共价修饰物、水分子和阳离子共同参与了结构维持。","scd":{"b":7.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["分辨率[冷冻电镜解析N-和O-聚糖结构]: 1.8-至2.2-埃","研究对象[金藻管状鞭毛体]: 发现非典型N-聚糖"]},{"i":38201,"as":"细胞形态变化主要由质膜下的肌动蛋白细胞骨架控制。本研究探讨了在波状细胞膜上生长的活性凝胶的曲率不稳定性。该理论模型解释了细胞如何在缺乏细胞外基质支撑的情况下，通过调节细胞膜的力学特性来形成并维持扩展的独立凸起结构。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":4.0,"t":7.0},"kp":["调控机制[波状膜上生长的活性凝胶]: 由肌动蛋白细胞骨架和膜敏感蛋白调控曲率不稳定性"]},{"i":38202,"as":"","scd":null,"kp":[]},{"i":38203,"as":"","scd":null,"kp":[]},{"i":38204,"as":"研究重新审视了层状过渡金属硫族化合物1T-TiSe2的电荷密度波（CDW）超晶格。针对激子凝聚、轨道有序和手性出现等伴随现象，研究人员通过深入的结构分析，揭示了CDW超晶格形成的精确原子级动力学机制，为解释这些新奇的量子现象提供了关键结构基础。","scd":{"b":6.0,"i":1.0,"r":5.0,"d":4.0,"t":7.0},"kp":["物理现象[1T-TiSe2电荷密度波超晶格]: 伴随激子凝聚、轨道有序化和手性涌现等效应"]},{"i":38205,"as":"研究发现，暴露在微波环境下的磁性薄膜中，微小的凸起结构能够引发具有精确等距频率的自旋波。这种机制被称为曲率感应磁振子频率梳，为在纳米尺度上生成和控制具有特定频率间隔的自旋波信号提供了一种全新的物理途径。","scd":{"b":6.0,"i":1.0,"r":5.0,"d":4.0,"t":7.0},"kp":["[曲率感应磁振子频率梳]: 磁性薄膜的微小凸起在微波暴露下可产生精确间隔频率的自旋波"]},{"i":38206,"as":"研究确立了反铁轴交变磁性作为一种广泛存在且具有微观基础的多铁性机制。在这种机制中，反铁轴反向旋转畸变能够诱导交变磁性和电极化。该理论证明了反铁轴态不仅是重要的铁性有序，还能引发自旋劈裂与铁电性的微观耦合。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":7.5},"kp":["多铁性机制[反铁轴交变磁性]: 反铁轴反向旋转畸变诱导产生交变磁性"]},{"i":38207,"as":"针对核物理领域费米子状态角动量零空间属性研究的勘误，修正了关于两体相互作用静态属性的文章细节。","scd":{"b":0.0,"i":0.0,"r":0.0,"d":0.0,"t":0.0},"kp":[]},{"i":38208,"as":"研究展示了在手性二维钙钛矿中通过光学控制实现载流子与应变介导的巨自旋劈裂（达100 meV）。超快圆二色性测量表明，自旋分裂与应变间的动态相互作用能够显著延长热载流子的寿命，为凝聚态物理中电子性质的动力学调控提供了新方法。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":7.5},"kp":["自旋分裂[手性二维钙钛矿]: 100 meV","热载流子寿命[手性钙钛矿自旋分裂与应变相互作用]: 显著延长"]},{"i":38209,"as":"研究开发了一种界面外延策略，在蓝宝石基底间约束钼箔，成功合成了高质量的钼酸铝（Al2(MoO4)3, AMO）单晶薄片。该单晶内强烈的声子-光子耦合激发了双曲声子极化子，其传播特性可通过对激发频率和晶体各向异性的调控来进行有效剪裁。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":6.5},"kp":["[单晶Al2(MoO4)3薄片]: 开发界面外延策略实现具有各向异性声子极化激元的合成"]},{"i":38210,"as":"研究提出了一种声化学策略，在环境条件下几分钟内实现了氧化钌的均匀硼掺杂。硼取代晶格钌位点并形成强共价硼氧键，通过优化氧中间体吸附并抑制晶格氧参与反应，大幅提升了酸性水氧化的内在活性和稳定性。该催化剂在10 mA cm-2下过电位仅180 mV，且稳定运行超3000小时。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":6.5},"kp":["制备条件[氧化钌硼掺杂]: 室温环境下数分钟内完成","掺杂策略[酸性水氧化氧化钌]: 空化介导的声化学方法实现均匀的替位硼掺杂","效能增强[硼掺杂氧化钌]: 替代晶格钌位点并形成强共价硼氧键，提升活性和耐久性"]},{"i":38211,"as":"研究开发了一种利用交流电致发光结合导电微粒自组装的双传感显示器。通过施加交流电场，介电泳力驱动微粒自组装产生依赖介电泳的发光；施加声波时，声泳力同样驱动微粒组装产生发光。该技术实现了介电泳和声泳两种物理力的动态可视化对比。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[介电泳和声泳双传感电致发光显示器]: 结合交流电致发光与介电泳/声泳力控制的导电微球自组装实现力的动态可视化"]},{"i":38212,"as":"研究探讨了锌离子电池中锌枝晶形成的根本原因，指出电化学反应动力学与传质速率之间的不平衡是关键。通过研究尿素衍生物，提出用无量纲常数K来量化这两者间的平衡。含有N,N-二甲基脲的电解质具有最高K值，成功平衡动力学与传质，有效抑制了锌枝晶的生长。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":7.0,"t":6.5},"kp":["枝晶成因[锌负极]: 快速电化学反应动力学与相对迟缓的传质过程之间的差异","调控机制[Zn2+电镀]: 利用一系列尿素衍生物平衡电化学反应动力学和传质以抑制枝晶"]},{"i":38213,"as":"研究在硅供体自旋量子比特系统中，利用硬件高效的量子电路成功制备了四比特纠缠态的九大典型类别。通过重叠层析和多方面验证技术，确认了真实的多粒子纠缠，解析了其纠缠结构，并证明了系统在量子比特丢失情况下的鲁棒性，同时观测到了对多粒子贝尔不等式的显著违背。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.5},"kp":["纠缠态制备[硅中供体自旋]: 完整制备四量子比特纠缠的九种标准族","量子电路[原生多量子比特操作]: 硬件高效型量子电路"]},{"i":38214,"as":"研究利用时间-温度叠加（TTS）原理指导加工，成功制备了以玻璃态ZIF-62为连续相、多种晶态MOF为分散相的晶体玻璃复合膜。该策略通过精确调控加工温度与时间，最大程度减少了填料的热降解。所得复合膜对CO2/N2、CH4/N2及C4碳氢化合物混合物展现出极高的分离效率。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":7.0,"t":6.5},"kp":["复合膜设计[时间-温度叠加原理]: 解决加工过程中填料热降解的挑战","复合膜成分[连续相与分散相]: 玻璃态ZIF-62(连续相)与晶态UiO-66、Mg-MOF-74、MOF-801(分散相)"]},{"i":38215,"as":"研究设计了一种带有密集有序哒嗪基团的sp2碳共轭共价有机框架。该设计实现了高效的二氧化硫（SO2）捕获，在25°C和1.0 bar下容量高达19.4 mmol/g，对SO2具有极高选择性。经过50次吸附-脱附循环后性能几乎无衰减，其优异性能源于共轭诱导的π电子调节增强了客体分子的识别与结合。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":8.0,"t":6.5},"kp":["SO2吸附容量[集成哒嗪基团的sp2碳共轭共价有机框架(DpTb-COF)]: 19.4 mmol/g","吸附剂设计[共轭诱导的π电子调节]: 密集排列且有序的吡啶嗪基团"]},{"i":38216,"as":"可逆交换信号放大（SABRE）是一种利用仲氢和目标底物与铱络合物瞬间相互作用实现底物极化的核自旋超极化技术。该技术无需化学修饰，可在温和条件下数秒内完成极化累积。研究结合仲氢增强的自旋选择性核磁共振方法、交换模型拟合和密度泛函理论计算，探究了丙酮酸的的结合机制。结果发现，氢化物的分子内氢交换速率快于丙酮酸交换，这些发现重塑了目前对SABRE机制的理解。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["超极化技术[可逆交换信号放大(SABRE)]: 无需化学修饰直接实现底物超极化","极化累积时间[温和条件]: 数秒内完成"]},{"i":38217,"as":"可逆固体氧化物电池（rSOC）技术在欧洲能源脱碳框架中展现出长期和短期储能的重要作用。研究证实，rSOC实现长期储能的往返效率达到60%，具备即时的环境与经济效益。针对欧洲2050年的能源格局，各国所需储能容量差异较大，为54至680 kWh/kW。将rSOC作为专一储能技术能实现最低的储能度电成本。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["往返效率[可逆固体氧化物电池长期储能]: 60%"]},{"i":38218,"as":"","scd":null,"kp":[]},{"i":38219,"as":"","scd":null,"kp":[]},{"i":38220,"as":"","scd":null,"kp":[]},{"i":38221,"as":"","scd":null,"kp":[]},{"i":38222,"as":"","scd":null,"kp":[]},{"i":38223,"as":"阴离子氧化还原反应（ARR）是支撑下一代高能量密度电池的关键机制，但其充放电之间的电压滞后会导致较差的能量效率，限制了其实际应用。本研究以具有约2.0V独立ARR平台的Li1.17Ti0.58Ni0.25O2（LTNO）为模型系统，深入探究了决定ARR工作电压的关键因素，并揭示了通过过锂表面壳层的形成对ARR电压进行动力学调节的作用。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["动力学调节[高能量密度电池亚稳态过锂表面壳]: 有效控制阴离子氧化还原反应(ARR)的电压滞后现象"]},{"i":38224,"as":"针对水系锌电池中传统隔膜较厚、易脆且无法有效调控锌枝晶生长和副反应的问题，研究人员构建了一种柔性超薄非对称MOF隔膜。该隔膜在具有大孔结构的亲水性细菌纤维素膜上原位生长了一层均匀的导电镍基MOF微孔层。纤维素基底提供高强度和吸液能力，而微孔MOF层则有效调节锌离子传输，从而实现快速的离子选择性和电池稳定性。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["隔膜材料[水性锌离子电池]: 超薄、坚韧的非对称异质结构MOF隔膜","隔膜结构[导电Ni基金属有机框架]: 均匀、密集集成的微孔层","电池性能[非对称MOF隔膜]: 快速选择性离子传输与抑制锌枝晶生长及副反应"]},{"i":38225,"as":"开发替代负极材料是提升钠离子电池体积能量密度的关键途径。研究系统评估了不同锡磷（Sn-P）原子比例的合金作为钠合金负极的表现。其中，SnP3在成本、体积容量和循环稳定性之间展现出最佳平衡。在钠化过程中，晶态SnP3会转变为非晶态并在后续循环中保持非晶特征。这种非晶态的NaxSnP3呈现出固溶体行为，有效提升了电池的循环稳定性和能量密度。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"kp":["负极材料[钠离子电池]: 非晶态Sn-P合金","最佳平衡[SnP3合金]: 在体积能量密度、成本和循环稳定性之间提供最佳平衡"]},{"i":38226,"as":"下一代聚变设备要求等离子体面向组件（PFC）能够承受10-15 MW/m²的稳态热负荷及数千小时的等离子体辐照，并在多次热应力下保持高可靠性。研究在WEST和ASDEX Upgrade（AUG）托卡马克装置上对钨（W）组件进行了广泛测试。WEST超导托卡马克与AUG装置结合其各自优势，验证了钨PFC在极端高热负荷和粒子流环境下的排热能力和抗瞬态事件韧性。","scd":{"b":7.5,"i":6.0,"r":6.0,"d":8.0,"t":6.0},"kp":["稳态功率通量[托卡马克钨等离子体表面组件]: 10-15 MW/m²"]},{"i":38227,"as":"π共轭自由基含有未配对电子，自发现以来推动了电子结构理论和有机反应活性的发展，并在过去40年中作为功能材料被广泛应用，如单组分有机导体、场效应晶体管半导体、有机磁体以及电致发光和量子材料。本综述回顾了125年来稳定π自由基的设计发展史，提供了基础的量子化学背景，并探讨了其不稳定的原因及稳定化设计策略。","scd":{"b":5.5,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["应用方向[稳定设计的π共轭自由基]: 单组分有机导体、场效应晶体管半导体、有机磁体及电催化等功能材料"]},{"i":38228,"as":"直接电解不纯水（DIWE）技术不依赖淡水，能够克服淡水资源与可再生能源分布的地理不匹配问题，为可持续生产绿氢提供了新途径。然而，杂质引起的性能退化阻碍了其工业化进程。本综述评估了海水和废水中杂质的特定影响，提出了基于杂质相互作用的技术协同优化方案。研究还进一步阐明了将DIWE工艺整合到现有工业流程中的清晰工业化路径及其技术经济可行性。","scd":{"b":6.0,"i":5.0,"r":6.5,"d":7.0,"t":5.0},"kp":["[直接电解不纯水]: 旨在摆脱淡水依赖，利用海水和废水可持续生产绿氢，但面临杂质引起的性能衰减等工业化挑战"]},{"i":38229,"as":"聚烯烃在全球塑料产量中占比过半，但其使用寿命短且难以回收，造成了严重的环境污染和资源损失。催化增值技术能够将废聚烯烃转化为高附加值化学品和燃料。实际应用中，该技术的规模化部署需要跨越分子尺度的活性位点化学、工艺开发优化以及反应器选择设计等多个尺度。本综述从催化剂、工艺到反应器的多维度集成视角，全面描述了聚烯烃催化增值技术的最新进展。","scd":{"b":5.5,"i":4.5,"r":6.0,"d":6.0,"t":4.0},"kp":["[聚烯废料催化增值]: 通过催化剂-工艺-反应器链的协同创新，将废料转化为高附加值化学品和燃料"]},{"i":38230,"as":"核相互作用决定原子核的稳定性和恒星环境演化。尽管现有的相互作用模型能精确复现质子与中子散射数据，但聚焦于氦-4（4He）第一激发共振态的电子散射实验揭示了核现象学理解中可能存在的空白。研究通过4He + 4He散射实验，以前所未有的高灵敏度数据和谱线形状分析，结合采用相同核密度的反应建模，深入探究了4He的共振态特性。","scd":{"b":7.5,"i":1.5,"r":5.5,"d":5.0,"t":4.0},"kp":[]},{"i":38231,"as":"研究田地边缘对美国不同气候区作物产量的影响，发现在湿润区增产而在干旱区减产，涉及农业生态学。","scd":{"b":4.5,"i":6.0,"r":5.0,"d":3.5,"t":5.0},"kp":["田地边缘影响[美国湿润地区]: 提高作物产量","田地边缘影响[美国干旱地区]: 抑制作物产量"]},{"i":38232,"as":"神经形态电子学通过模拟大脑工作原理实现低功耗存内计算，但其实际应用受限于器件非理想性、训练精度低和适应性不足等问题。研究探讨了数字、混合信号及新型神经形态电子器件的训练方法，分析了片外训练片内推理、片内训练推理以及混合离在线训练等策略的特点与优势。研究指出，未来需在高级训练算法、标准化基准测试及软硬件协同设计方面解决关键挑战。","scd":{"b":6.5,"i":4.0,"r":6.0,"d":5.0,"t":4.5},"kp":["[神经形态电子学]: 模仿大脑原理实现低功耗存内计算，其实际应用受限于器件非理想性、训练精度和适应性不足"]},{"i":38233,"as":"色散器件和模拟计算技术的进步正推动光谱仪的尺寸不断缩小。这两项关键技术的发展使得制造微型光谱仪成为可能，为光谱设备的小型化和集成化开辟了新途径。","scd":{"b":6.0,"i":4.0,"r":4.0,"d":3.5,"t":4.0},"kp":["[微型光谱仪]: 结合色散器件和模拟计算技术缩小设备体积"]},{"i":38234,"as":"为克服多元素掺杂无铅(K,Na)NbO₃压电陶瓷研发中掺杂趋势复杂和实验试错繁琐的难题，研究提出了一种人机协作的人工智能引导材料设计框架。该框架利用大语言模型从文献中提取隐性构效关系并提出新配方，结合专家干预加速实验合成。通过织构化和烧结助剂优化，合成的无铅压电陶瓷压电常数d33从440-500 pC/N提升至600-620 pC/N，展现出优异的性能。","scd":{"b":8.0,"i":5.0,"r":7.0,"d":6.5,"t":7.0},"kp":["[无铅压电陶瓷设计与实现]: 利用大语言模型提取隐性结构性能知识，并通过人机协作指导多元素掺杂材料的实验合成"]},{"i":38235,"as":"锰掺杂的硒化镉量子点能够通过一种超快自旋交换介导的电子转移途径，在常规能带边缘能量不利于电荷转移的情况下实现甲基紫精的还原。飞秒瞬态吸收光谱表明，锰掺杂使电子转移动力学加速了一个数量级以上，并开启热激子还原通道。在该通道中，锰离子捕获光激子，随后激发态锰离子的自旋弛豫过程有效驱动了电荷分离与分子还原反应。","scd":{"b":8.5,"i":2.5,"r":7.0,"d":7.5,"t":6.0},"kp":["[锰掺杂硒化镉量子点]: 实现了界面自旋交换介导的超快电子转移路径，在常规能带不利于电荷转移时驱动甲基紫精还原并加速电子转移"]},{"i":38236,"as":"有机分子氧化反应被认为是替代析氧反应（OER）以降低绿氢生产过电位的节能方案。为解决氢气生产规模与精细化工过程不匹配及大量释氧的问题，研究提出了一种伴随易分离特性的气泡辅助耦合氧化策略。以苄胺氧化反应（BOR）为探针，该策略激活OER并利用产生的氧气气泡，及时将不溶性产物苯甲腈带离电极表面，有效克服了高电流密度下的传质限制，实现安培级电流密度下的稳定运行。","scd":{"b":6.5,"i":3.5,"r":5.0,"d":6.0,"t":5.0},"kp":["[有机分子氧化反应(伯胺氧化)]: 作为一种节能的析氧反应(OER)替代方案，与易清洗的耦合氧化反应结合，可稳定适应大电流密度产氢过程"]},{"i":38237,"as":"研究提出了一种镍催化的交叉电偶联方法，通过三齿配体控制电活化顺序，实现了未活化烷基卤化物与炔基卤化物的直接烷基-炔基键构建。该策略具有广泛的官能团兼容性，支持伯、仲、叔烷基卤化物生成内部炔烃，并实现了未活化叔烷基电试剂的还原偶联。机理表明三齿配体强制执行了不寻常的顺序活化途径，其中Ni(0)催化剂在氧化加成前先与烷基卤化物结合。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["催化剂[镍催化烷基-炔基偶联]: 三齿配体","[交叉亲电偶联]: 通过配体控制亲电试剂的顺序激活，直接构建炔基-烷基键并实现广泛的官能团兼容性"]},{"i":38238,"as":"研究探讨了非线性对非厄米集肤效应的影响，发现非线性诱导的点隙拓扑相变伴随着集肤模式局域化的反转。该现象在非线性微波超材料中得到了实验验证，电磁波被局域在系统一端。该研究揭示了能带拓扑与材料非线性之间的相互作用，在非厄米系统中发现了新的物理现象。","scd":{"b":8.0,"i":1.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[非线性非厄米拓扑]: 揭示了非线性对非厄米集肤效应的影响，观察到局域化反转和谐波产生现象"]},{"i":38239,"as":"研究开发了一种基于离子凝胶/ZnO异质结构的耦合双通道忆阻器（CDCM），打破了传统忆阻器在硬件贝叶斯神经网络（BNN）实现中的限制。该器件利用垂直离子门控建立两个可调谐忆阻通道，将突触权重定义为两通道间的差分电导，实现了硬件本机对突触权重均值（μ）和标准差（σ）的正交控制，从而精确合成权重并量化预测不确定性。","scd":{"b":7.5,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[贝叶斯神经网络硬件实现]: 利用基于离子凝胶/ZnO异质结构的耦合双通道忆阻器(CDCM)打破电导均值与随机噪声之间的基本权衡，实现本机值得信赖的边缘智能"]},{"i":38240,"as":"研究在沸石咪唑酯框架[ZIF-4(Zn)]中发现了巨大的可调谐气压热效应。对于充入氮气的ZIF-4(Zn)，在约190 K附近和1 kbar压力下，可实现38 J K-1 kg-1以上的等温熵变和10 K以上的绝热温度变化；在脱溶剂框架中，绝热温度变化可达60 K，等温熵变高达210 J K-1 kg-1。该MOF材料具备一阶结构相变和显著的体积变化，在气压制冷和加热领域具有广阔前景。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["气压热效应[客体分子吸附]: 巨大的可调气压热效应","起始温度[氮气负载的ZIF-4(Zn)]: 高度可调"]},{"i":38241,"as":"研究提出了一种前馈电光分频架构，成功打破了微波频率合成器中频率可调谐性与光谱纯度之间的制约。该架构在不进行下游电子频率合成的情况下，不仅保留了频率的可调谐性，还将光源的光谱纯度划分到微波域，消除了微波源的相位噪声，实现了具有光学衍生光谱纯度的可调谐微波合成。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[光电分频技术(eOFD)]: 将光学源的光谱纯度转移到微波域"]},{"i":38242,"as":"研究在纳米金刚石中实现了与环境具有强宽带声子去耦作用的单色心单光子发射器。这些色心在室温下展现出低至0.3纳米的创纪录窄线宽和超过10 Mcps的稳定明亮发射。体声子侧带几乎被完全抑制，表明存在位于金刚石声子带外的单一局域振动模式。这种独特的声子去耦机制显著提升了单光子发射器的相干性和可控性。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":7.0,"t":5.0},"kp":["线宽[室温下纳米金刚石单色心]: 低至 0.3 nm","[纳米金刚石单色心]: 与体声子环境强宽带解耦且发射明亮稳定"]},{"i":38243,"as":"研究提出一种创新的电化学直接空气捕获平台，通过在三维空气-电极界面处局部生成氢氧化物来改善吸收动力学和碱度利用率。捕获的CO2随后通过质子耦合电子转移介体释放，实现了低能耗再生和高纯度气体产出。多孔隔板进一步扩展了该架构，有效克服了传统系统捕获率低、再生耗能高及稳定性差的挑战。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[电化学直接空气捕获(eDAC)]: 在三维界面处局部产生氢氧化物"]},{"i":38244,"as":"研究利用空气作为氧化剂，通过贱金属催化实现了联烯C(sp)–C(sp2)双键和C(sp3)–C(sp2)单键的断裂。该转化由联烯C(sp2)–H键的氢原子抽取引发，具有高度的化学和区域选择性。通过甲硅烷基取代，成功生成了多种远端官能化酮、烷基化杂芳烃、烷基化腈和氘代产物，解决了合成化学中联烯键断裂的长期挑战。","scd":{"b":6.0,"i":1.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[联烯C(sp)–C(sp2)和C(sp3)–C(sp2)键]: 碱金属催化断裂实现自由基转变","[甲硅烷基取代]: 解决自由基断裂的化学和区域选择性问题"]},{"i":38245,"as":"研究提出利用酸性粘合剂诱导铜腐蚀的策略，激活了宽温钠硫族电池的块状S/Se/Te正极。富含羧酸的粘合剂在加工中创造酸性微环境（pH≈3），在铜集流体上自发形成铜硫族化合物中间层，并在循环中原位重构为活性Cu2X催化剂。实验和DFT分析证实，在Na-Se电池中，Cu2Se使液固转化势垒降低了约24.1%，加速了多硒化物转化，同时极性基团增强了化学吸附，有效抑制了穿梭效应。","scd":{"b":7.5,"i":2.0,"r":5.0,"d":7.0,"t":5.0},"kp":["微环境pH值[富羧酸粘合剂加工过程]: ≈3","[铜硫族化物中间层]: 酸性粘合剂诱导铜腐蚀自发形成以激活块状S/Se/Te正极"]},{"i":38246,"as":"研究演示了通过两亲分子和小分子的最小结构变化（包括同分异构体、烷基链长和反离子）来控制凝聚层的浮力，进而决定其在水柱中的垂直迁移和空间分层。通过系统调整参数和环境线索（如浓度和温度），可动态调节液滴的位置。结构分析表明，浮力源于由水合物组成的海绵状结构，为益生元原生细胞的垂直物理接触和分子交换提供了可能。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":5.0,"t":7.0},"kp":["[益生元凝聚层垂直分层]: 两亲物和分子的微小结构变化控制凝聚物浮力进而主导垂直迁移"]},{"i":38247,"as":"研究利用磁光谱μSQUID-EPR方法，成功解析了镧系单离子分子磁体[160GdPc₂]⁻中的量子隧道分裂。通过在横向磁场下用微波辐照单晶，绘制了自旋流形（S=7/2），并观察到明显的几何相位干涉（Berry相位），实现了对4f分子磁体拓扑特性的直接探测，为基于拓扑的抗扰量子计算提供了物理基础。","scd":{"b":8.5,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[镧系单离子分子磁体]: 通过拓扑抑制量子隧穿以保持量子相干性"]},{"i":38248,"as":"","scd":null,"kp":[]},{"i":38249,"as":"针对欧洲近期创纪录的高温热浪，探讨了这种极端炎热夏季是否已成为伦敦、巴黎和柏林等城市的新气候常态。","scd":{"b":2.0,"i":3.0,"r":4.0,"d":2.0,"t":6.0},"kp":[]},{"i":38250,"as":"勘误声明，涉及在金表面合成开壳三角烯稠合卟啉及界面电荷分布的研究，主要方向为表面化学与合成。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["合成基底[Au(111)表面]: 开壳[3]三角烯稠合卟啉","界面特性[开壳[3]三角烯稠合卟啉/Au(111)]: 界面电荷重新分布"]},{"i":38251,"as":"研究编制了超过800 GB的高分辨率太阳能塔发电厂运行数据，建立了符合FAIR数据原则的开放获取数据库PAINT。该接口使结构化运行数据大众化，旨在促进太阳能塔领域数据驱动解决方案的研发。","scd":{"b":6.0,"i":7.0,"r":9.0,"d":8.0,"t":8.0},"kp":["[太阳能塔发电厂开放数据库(PAINT)]: 超过 800 GB 的高分辨率运行数据"]},{"i":38252,"as":"研究展示了使用可重构自由空间衍射光学器件并行执行非线性逻辑电路的全光计算系统。该系统将非线性函数的串行链折叠为单一光学阶段，成功实现了所有基本逻辑门以及并行半加器/全加器，克服了电子计算在人工智能负载下的瓶颈，实现了快速、高并发的多维信息处理。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[计算架构]: 依赖级联线性和非线性操作实现电子计算","[计算架构]: 利用可重构自由空间衍射光学器件进行具有高并行度的快速多维信息处理"]},{"i":38253,"as":"研究通过空间位阻单态甲苓烯的光激发，成功在室温下表征出一种半衰期长达14小时的三重态。打破了三重态中间体寿命短的传统认知，实现了对高度活泼中间体的长期观察。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":7.0,"t":7.0},"kp":["半衰期[室温三重态单态甲锗烯]: 14小时"]},{"i":38254,"as":"美国国立卫生研究院（NIH）实施了新的政治审查程序，高级卫生官员的强制审查以及对235个特定敏感词汇的排查，导致数百份已通过审核的拨款申请陷入行政停滞状态。","scd":{"b":1.0,"i":3.0,"r":6.0,"d":5.0,"t":8.0},"kp":["[审查机制]: 政治审查机制包含235个特定受限词汇"]},{"i":38255,"as":"多家初创公司正在开发针对特定表观遗传标记的疗法。这些基于CRISPR技术的表观基因组编辑疗法正处于测试阶段，旨在治疗从高胆固醇到罕见肌肉疾病等多种疾病。","scd":{"b":7.0,"i":5.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[治疗靶点]: 针对特定表观遗传标记治疗高胆固醇和罕见肌肉疾病"]},{"i":38256,"as":"","scd":null,"kp":[]},{"i":38257,"as":"研究开发了一种简明且可扩展的策略，从易得的前体高效合成了桥头取代的[2]-梯烷。该梯烷可作为多功能中间体，实现可编程的区域选择性桥头官能化，并与缺电子烯烃发生应变释放环加成反应，生成多种多取代的双环[2.2.2]辛烷（BCO）。BCO骨架还可作为饱和的生物电子等排体，进行定点多样化修饰。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[桥头取代的[2]-梯烷]: 采用易得前体实现简明且可扩展的合成策略，产物作为通用中间体实现可编程与多样化应变释放"]},{"i":38258,"as":"赫什菲尔德原子细化（HAR）作为一种可视化化学键的方法，被应用于包含多中心钍-钍键的三钍簇极端测试案例。实验与计算结果高度吻合，为HAR方法在化学键可视化中的常规应用铺平了道路。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["表征方法[化学键共价性实验测量]: 赫什菲尔德原子细化(HAR)","[含多中心键的三钍团簇]: 利用HAR技术实现锕系元素-锕系元素键合的实验可视化"]},{"i":38259,"as":"《自然》团队探讨了类人猿笑声中共享的节奏，指出这种节奏有助于理解人类语言的进化过程。同时，简报还涵盖了人工智能的使用可能导致医学和计算机科学领域人员技能下降的问题。","scd":null,"kp":["[技能退化]: AI的使用可能导致医学和计算机科学领域的技能退化"]},{"i":38260,"as":"锂金属电池因内部界面不稳定易失效。研究设计了一种具有空间工程界面的准固态聚合物电解质，可同时保护锂金属阳极和高压阴极。该策略使电池在宽温度范围和不同阴极材料下安全运行，为实现高能可充电池提供了实用途径。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["电解质设计[高电压和宽温区准固态锂电池]: 空间工程聚电解质界面，同时保护锂金属负极和高压正极"]},{"i":38261,"as":"为解决高电压有机阴极在钾双离子电池中氧化还原电位不足、结构稳定性差和动力学迟缓的问题，研究提出了硫介导电荷离域的设计策略。将硫原子引入吩嗪骨架实现扩展π共轭与高效电荷电子离域，从而提高电子电导率和氧化还原电位，开发出一种硫取代的p型共轭聚合物。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["设计策略[高压钾双离子电池有机阴极]: 硫介导的电荷离域，以克服氧化还原电位不足、结构稳定性差及动力学迟缓"]},{"i":38262,"as":"为解决质子交换膜水电解中阳极析氧反应的低铱载量、高活性与高稳定性难以兼得的问题，研究设计了具有“动脉-毛细血管”分层传质网络的IrRuCu三元合金纳米海绵催化剂。该催化剂独特的梯度核壳结构由晶格失配引发显著的拉伸应变，诱导出非破坏性的表面交换机制，显著提升了催化性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["催化剂[PEM水电解析氧反应]: IrRuCu三元合金纳米海绵","结构特征[IrRuCu三元合金纳米海绵]: 具有动静脉毛细血管级层状传质网络，通过表面应变诱导实现动态表面交换"]},{"i":38263,"as":"针对天然葡萄糖氧化酶不稳定且昂贵、传统纳米酶缺乏底物特异性的问题，研究开发了一种具有双仿生结构的锰基单宁酸单原子纳米酶（TA-Mn SA）。该纳米酶在单宁酸衍生的分子口袋内嵌有原子级分散的Mn催化位点，专为选择性识别葡萄糖而定制，展现出卓越的催化效率和底物选择性，可用于连续汗液葡萄糖监测。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["纳米酶[汗液葡萄糖监测仿生单原子催化剂]: 锰基单宁酸单原子纳米酶(TA-Mn SA)","结构特征[TA-Mn单原子纳米酶]: 具有底物结合袋的双重仿生架构，以解决天然酶的不稳定性和常规纳米酶缺乏底物特异性的问题"]},{"i":38264,"as":"针对三阴性乳腺癌高度异质性和缺乏靶向分子导致治疗效果差的问题，研究开发了PEI/siENPP1@Mn-ZIF-8（PEMZ）基因-化学动力学-免疫纳米复合物。该复合物能够高效包裹并保护siENPP1，实现酸性响应的胞质释放，通过一种前所未有的三重激活机制有效激活cGAS-STING通路，实现协同治疗。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["纳米复合物[三阴性乳腺癌协同治疗]: PEI/siENPP1@Mn-ZIF-8 (PEMZ)","作用机制[PEI/siENPP1@Mn-ZIF-8纳米复合物]: 整合基因、化学动力学和免疫疗法，三重激活cGAS-STING通路"]},{"i":38265,"as":"针对有机机械发光材料机理不明确导致难以同时兼顾耐久性、灵敏度和热耐受性等问题，研究提出基于手性与超分子协同的设计策略。通过手性打破对称性，定向超分子相互作用在非中心对称晶体中放大宏观极性，揭示了机械发光活性受宏观净极性控制，实现了高性能的圆偏振机械发光。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["材料设计策略[高性能圆偏振机械发光材料]: 构建具有明显宏观极性的非中心对称晶体，以兼顾耐久性、灵敏度、热耐受性和偏振控制"]},{"i":38266,"as":"传统颜料易褪色，而结构色颜料凭借微观结构对光的操控可产生强烈的虹彩和金属光泽，是安全、可持续的替代方案。受自然界启发，研究人员利用胶体纳米粒子、纤维素纳米晶体和嵌段共聚物等聚合物构建单元的受限自组装，制造出光子颜料。文章重点关注了受限自组装策略、光学特性及其新兴应用。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["成色机制[聚合物光子颜料]: 受限自组装微观结构操纵光产生结构性颜色"]},{"i":38267,"as":"二维铁硫族化合物因其独特的物理性质在自旋电子学和量子计算中极具潜力。针对高质量极限厚度二维FeS合成困难的问题，研究采用空间受限化学气相沉积（CVD）策略，直接合成了厚度可调、低缺陷密度且化学计量比严格的二维FeS薄片。该材料展现出交叉磁阻效应和超高电导率。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["合成工艺[2D FeS制备]: 空间受限化学气相沉积","磁性状态[二维FeS]: 具有交变磁性特征"]},{"i":38268,"as":"针对近红外IIb/c荧光材料因能隙定律限制而光致发光量子产率（PLQY）低的问题，研究提出极化子工程策略。通过将Nd³⁺掺入CdTe量子点晶格加速辐射复合速率（提升150倍），实现了在1730 nm处的高效宽带发射，水溶液中的PLQY达11.34%±0.79%，斯托克斯位移超过900 nm，适用于深层组织生物成像。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["发射波段[Nd掺杂CdTe量子点]: 1730 nm (NIR-IIb/c)","策略机制[克服能隙定律]: 极化子工程增加电荷局域化","复合速率[辐射跃迁]: 提升150倍"]},{"i":38269,"as":"针对固体聚合物电解质存在的锂枝晶生长、界面不稳定和离子电导率低等难题，研究开发了一种三层复合固体电解质（CSE）。外层为PEO/LiTFSI，内层由聚多巴胺包覆的Li7La3Zr2O12（PDA@LLZO）增强的PEO/LiTFSI基体组成。该设计结合了界面工程与机械增强，有效抑制了锂枝晶并实现了高效离子传导。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["电解质结构[复合固体电解质]: 结合PEO/LiTFSI和表面功能化LLZO的三层结构","功能特性[三层CSE]: 抑制枝晶生长和实现高效离子传导"]},{"i":38270,"as":"针对可逆质子陶瓷电池空气电极中缓慢的氧化还原反应，传统高温煅烧易致表面钝化而低温煅烧结晶度不足的问题，研究采用热限制煅烧工艺，动力学上保留仅在特定温度下形成的亚稳态纳米相。这构建了丰富的异质界面用于高效的ORR/OER，通过控制温度诱导Ce选择性掺入Ba(Co)宿主晶格，显著提升了电池性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["制备工艺[质子陶瓷电池空气电极]: 有限煅烧/热受限煅烧","相态特征[空气电极催化剂]: 动力学亚稳态纳米相"]},{"i":38271,"as":"有机半导体在水溶液中具有独特的混合离子和电子传导特性，在生物传感领域极具潜力。通过分析有机电化学晶体管（OECT）的性能，研究首次证明带负电荷的核糖核酸（RNA）与共轭聚合物之间存在密切相互作用。这种相互作用实现了超灵敏的生物标志物检测，为疫情预防和健康监测提供了关键支持。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["传感机制[有机电化学晶体管]: 核酸与共轭聚合物密切相互作用","检测性能[生物标志物生物传感器]: 超灵敏"]},{"i":38272,"as":"倒置钙钛矿太阳能电池中，开发能同时实现理想表面覆盖率、高器件效率和长期稳定性的四足自组装单分子层极具挑战。研究合理设计并合成了两种以芘为中心的新型四足自组装单分子层（4PACz-Py-C2和4PACz-Py-C4）。通过间隔工程调节分子堆积，促进空穴提取并抑制非辐射复合，基于4PACz-Py-C2的优化器件实现了高效稳定的性能。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":5.0,"t":5.0},"kp":["空穴传输层[倒置钙钛矿太阳能电池]: 间隔调节的新型芘基四足自组装单分子层"]},{"i":38273,"as":"在高盐条件下实现零液体排放的界面太阳能蒸发极具挑战。研究开发了一种具有分层结构的凝胶蒸发器，其界面光热层由熔融核壳碳-聚合物纳米球组成。表面受限的光热层确保了有效热限制和丰富的液-汽界面，底层水凝胶基质维持连续的水分补充。该设计有效解决了热、质量和盐分的耦合管理，实现了定向盐结晶和零液体排放。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["光热层材料[太阳能蒸发器]: 熔融核壳碳聚合物纳米球","系统特性[高盐水界面蒸发]: 定向盐结晶和零液体排放(ZLD)"]},{"i":38274,"as":"高温压电材料通常难以同时兼具高压电性能和优异的热稳定性。研究提出通过构建混合对称的铁电畸变态来稳定内禀晶格贡献的设计策略，并在Pb(Zr0.53Ti0.47)O3-xNb陶瓷中得到验证。优化的N3成分展现出高压电系数d和良好的温度稳定性，解决了两种属性之间的竞争矛盾。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["设计策略[高压电热稳定材料]: 构建混合对称铁电畸变态以稳定极性畸变","材料体系[压电材料]: Pb(Zr0.53...)基"]},{"i":38275,"as":"通常所有碳在机械移动界面处都会倾向于石墨化，而无法逆向形成金刚石。研究打破了这一规律，在超润滑滑动界面（摩擦系数为0.008）实现了金刚石的形成。这一过程通过氧化铝球在涂有二硫化钼的无定形碳表面滑动时，对碳磨损碎屑进行范德华封装来完成。原子模拟揭示了其形成机制。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["摩擦系数[超润滑滑动界面]: 0.008","物理现象[超润滑界面]: 室温下降服势垒原位形成金刚石"]},{"i":38276,"as":"通过原位实时生成发光基元在聚合物中实现聚集诱导发光（AIE）并支持可编程4D发光极具挑战。研究开发了一种简便平台，利用光触发自由基反应在聚合物主链中动态构建硫代羰基（C=S）基元，将非发光聚合物前体转化为活性材料。该设计建立了两个动力学可编程模块：模块1实现可逆写入-读取-擦除并演化为稳定状态；模块2产生更稳定的C=S基元，用于4D发光加密。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["发光加密机制[光触发自由基反应]: 动态构建硫代羰基(C=S)基序","[无发射聚合物前体]: 光触发转化为AIE活性材料","[聚合物发光加密]: 可编程4D(时间/序列依赖)发光"]},{"i":38277,"as":"电催化炔醇半加氢在接近工业大电流密度下极易引发析氢副反应，降低整体效率。研究开发了一种PdSb金属烯电催化剂，作为高效的“活性氢储层”克服了此限制。Sb的掺入诱导了p-d轨道杂化，调节了Pd的电子结构，从而促进了水的解离并抑制了竞争性析氢反应，实现了大电流密度下的高效电催化半氢化。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["电催化剂[炔醇半加氢]: PdSb金属烯(PdSb ene)","[抑制析氢反应(HER)]: p-d轨道杂化实现活性氢储库","[电化学半加氢]: 近工业级电流密度"]},{"i":38278,"as":"针对无阳极锂金属电池因锂沉积不均引发枝晶生长的安全隐患，提出一种5-甲基-1H-四氮唑（MTZ）分子界面工程策略。该分子通过强烈的Cu-N化学键在铜箔表面形成稳定的自组装单分子层（SAMs）。该界面层以分子级精度引入了高密度成核位点，同时促进电解液中LiNO3的优先分解，从而构建出稳定的固体电解质界面（SEI），助力实现能量密度达600 Wh/kg的无阳极锂金属电池。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":8.0,"t":7.0},"kp":["能量密度[无阳极锂金属电池]: 600 Wh/kg","界面工程[Cu箔表面保护]: 5-甲基-1H-四唑(MTZ)自组装单分子层(SAMs)","[无阳极锂金属电池]: 解决锂枝晶生长并提升安全性"]},{"i":38279,"as":"针对植入式支架早期感染与晚期生物膜-矿物堵塞导致失效的问题，受金属硫蛋白动态金属稳态机制启发，开发了一种基于β-羟基醚的离子调节网络涂层。该网络通过编程具有不同动力学和热力学特性的竞争性结合位点，为静态材料内置了“功能时钟”。以银离子为例，该涂层成功将传统金属杀菌剂转化为阶段适应性防御因子，实现了初期感染触发的杀菌活性和后期的长期防污保护。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["涂层响应机制[植入支架防护]: 感染触发杀菌与长期防污双级离子调节","涂层材料[动态金属稳态]: β-羟基醚基离子调节网络"]},{"i":38280,"as":"为解决倒置钙钛矿太阳能电池埋底界面配位无序的问题，提出一种N-杂环活化的配位策略。该策略将咪唑鎓衍生物分子集成到自组装单分子层（SAMs）中，与相邻的铅多卤化物物种建立协同配位相互作用。这一机制重塑了局部前驱体环境，精准调控了SAM-钙钛ite界面的前驱体化学性质和结晶过程，引导晶体均匀成核与生长，从而有效稳定了SAM结构，显著提升了钙钛矿太阳能电池的结构稳定性。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["界面调控策略[倒置钙钛矿太阳能电池]: N-杂环激活的π协同配位","[埋底界面化学]: 稳定SAMs组织并精确调控前驱体化学"]},{"i":38281,"as":"近红外（NIR）激活的聚集诱导发光（AIE）光敏剂在深部肿瘤光动力治疗中极具潜力，但现有的D-A-D型苯并双噻二唑衍生物由于S1到S0的能隙较小，严重限制了活性氧（ROS）的生成。为突破此瓶颈，研究提出一种新策略，通过结合一氧化氮（NO），将广泛使用的D-A-D型近红外AIE分子成功转化为高效的I型光敏剂，显著提升了其在耐缺氧条件下的光动力治疗效果。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["光敏剂转化机制[一氧化氮结合]: NIR-II AIEgens转化为I型光敏剂","光动力疗法特性[耐缺氧深层肿瘤]: I型光动力疗法"]},{"i":38282,"as":"针对传统盐水蒸发系统受拉乌尔定律限制导致蒸发受阻的问题，提出一种通过配体场诱导静电极化来热力学活化水分子的策略。在海藻酸钠水凝胶网络中共同配位Fe3+和Co2+，引发聚合物框架内显著的电子重新分布，产生极化的配位环境。该环境有效破坏了水分子的协同氢键网络，降低了水分子簇的结合能，从而成功打破拉乌尔定律的限制，实现了高性能的太阳能驱动盐水蒸发。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["水活化机制[高盐海水蒸发]: 配体场极化打破拉乌尔定律","太阳能蒸发系统[Fe3+共配位]: 热力学活化水分子"]},{"i":38283,"as":"研究揭示了脊椎动物肾脏起源的演化过程，挑战了其仅起源于中间中胚层的传统认知。研究发现，脊椎动物的前肾及成年肾脏实际上起源于一个特定、分段的体节亚区——生肾节。在早期发育过程中，生肾节脱落并形成肾导管。研究指出，在非脊椎动物脊索动物中，生皮肌节与生肾节的共同祖细胞表达相同的中胚层标志物；而在圆口类和板鳃类动物中，这些标志物则逐渐分离进入体节的不同区域。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[肾脏起源]: 脊椎动物肾脏起源于早期发育过程中脱落的特定、分段的体节亚区（生肾区）"]},{"i":38284,"as":"为实现对体内微血管网络中细胞动态的高时空分辨率追踪，研究开发了一种基于近红外染料的优化标记方案。利用吲哚菁绿（ICG）和DiR染料对红细胞和中性粒细胞进行标记，使其产生光谱特征截然不同的光声特征。该技术结合磁驱动方法，成功突破了光学显微镜的穿透深度限制，实现了对活体小鼠体内不同循环细胞群的单细胞级无创、多重光声同步成像与追踪。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["活体细胞追踪[体内微血管网络]: 多重光声跟踪与磁驱动标记"]},{"i":38285,"as":"为解决骨关节炎治疗中关节负荷难以在体监测的问题，研发出一种全可降解、可植入的压电压力传感器。该传感器采用单端结构设计，仅含单个电极，使用生物相容性材料制成。在模拟体外及在体环境中，该传感器保持了超过2个月的稳定性能监测，是目前报道的功能寿命最长的可降解压力传感器之一，能够无线监测膝关节负荷，为软骨再生和退化评估提供直接数据。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["传感器特性[骨关节炎膝关节监测]: 可生物降解的植入式无线压电压力传感器"]},{"i":38286,"as":"研究通过开发带有氢键“贴纸”的非缠结聚合物模型系统，揭示了可逆键分布和密度对聚合物动态特性的调控机制。结果表明，随机分布的贴纸既不形成簇也不改变流变性能；而位于链端的贴纸即使在低浓度下也能驱动纳米簇的形成。增加端基贴纸数量可产生跨越八个数量度频率的橡胶平台，并表现出两个不同的弛豫时间尺度。这证明了贴纸的空间分布是决定材料是否表现出支化聚合物流体力学或弹性凝胶特征的关键因素。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["聚合物动力学[缔合型聚合物贴片]: 可逆键分布与密度调控材料宏观性质","[链端放置的氢键贴片]: 驱动纳米团簇形成"]},{"i":38287,"as":"为了克服光声计算断层扫描（PACT）在超声检测孔径和灵敏度之间的性能权衡，提出了三维孔径驱动光声断层扫描技术（3D-ADPAT）。该技术将高数值孔径聚焦超声换能器（HNA-FUT）与相位反转聚焦等效重建（PIFER）算法协同结合。实验验证表明，该方法显著提升了成像性能，实现了空间分辨率约2.21倍的提升以及对比噪声比约10倍的增强，有效改善了图像的对比度、分辨率和穿透深度。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[光声断层扫描(PACT)]: 存在超声检测孔径与灵敏度之间的权衡限制","[三维孔径驱动光声断层扫描(3D-ADPAT)]: 克服了图像对比度、分辨率和穿透深度的限制"]},{"i":38288,"as":"研究揭示了炎症小体激活后中性粒细胞命运的决定机制。发现粒细胞-巨噬细胞集落刺激因子（GM-CSF）通过放大TLR4驱动的炎症小体启动，赋予中性粒细胞在NLRP3和Pyrin激活时发生焦亡的能力。此外，单独使用TLR1/2激动剂Pam3CSK4进行启动也足以使中性粒细胞发生焦亡，因为Pam3CSK4比LPS引发了更强效的炎症小体启动。这一发现阐明了中性粒细胞抵抗caspase-1依赖性焦亡的分子机制，表明威胁评估直接决定了细胞的命运走向。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[免疫机制]: GM-CSF（粒细胞-巨噬细胞集落刺激因子）赋予中性粒细胞对caspase-1依赖性焦亡的敏感性"]},{"i":38289,"as":"骨质疏松性骨折愈合常受TH1/M1偏态炎症微环境的阻碍。研究表明，细胞外镁离子（Mg2+）以剂量和时间依赖性方式重塑骨免疫微环境。具体而言，Mg2+通过抑制TRPM7介导的Ca2+峰值和NFATc1驱动的促炎轴，促进TH2/M2免疫反应，从而有利于成骨；然而，持续过量的Mg2+会抑制Orai1/CaV依赖的钙信号，反而削弱TH2/M2反应。该结论揭示了Mg2+在骨折愈合过程中的时间免疫调节机制。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[骨免疫反应]: 细胞外镁离子以剂量和时间依赖性方式重塑骨质疏松性骨折愈合的骨免疫微环境","[分子机制]: Mg2+抑制由TRPM7介导的Ca2+峰值及NF-κB信号通路"]},{"i":38290,"as":"开发了一种基于纳米脂质体的多靶标亚单位疫苗平台，用于同时抵御多种呼吸道病毒。该平台共同展示了来自三种季节性流感毒株的重组血凝素胞外域、新冠病毒（SARS-CoV-2）受体结合域以及呼吸道合胞病毒（RSV）F胞外域（呈融合前构象）。在小鼠、雪貂和棉鼠模型中，接种该疫苗成功激发了对这三种主要呼吸道病毒的保护性免疫反应，其抗体反应水平与各自的单一病原体疫苗相当。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[疫苗平台]: 基于纳米脂质体的亚单位疫苗平台可共同展示多种重组蛋白以同时应对多种呼吸道病毒"]},{"i":38291,"as":"尽管完全敲除NLRP3炎症小体可预防或减轻心血管、神经退行性疾病等多种与年龄相关的疾病，但这并非可行的临床治疗策略。研究发现，在模拟人类部分抑制药物的Nlrp3单倍体不足小鼠模型中，NLRP3表达减少会引发一种补偿性的NLRP1-NLRP3相互作用。这种代偿机制打破了原有的平衡，反而导致小鼠出现加速衰老的表象。该发现对当前针对NLRP3的部分抑制药物研发策略提出了警示。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[代偿机制]: NLRP3单倍体不足会暴露NLRP1与NLRP3的代偿性相互作用，从而导致小鼠加速衰老"]},{"i":38292,"as":"研究证明，在铪锆氧化物（HZO）外延薄膜中，由电致伸缩驱动的相不稳定性能够产生巨大的赝压电响应。当外加电场超过24 kV/cm的临界值时，非极性相与极性相之间的电场诱导转变被激活，从而引发约1000 pm/V的内在压电响应。在偏置电场的稳定下，其赝压电应变更是超过10000 pm/V。这种超常的性能源于材料巨大的电致伸缩效应与相变临界点附近的相不稳定性的共同作用。","scd":{"b":9.0,"i":4.0,"r":8.0,"d":8.0,"t":7.0},"kp":["临界电场[铪锆氧薄膜(HZO)]: 24千伏/厘米","[铁电薄膜(HZO)]: 电致伸缩驱动的相位不稳定性产生巨大的赝压电响应"]},{"i":38293,"as":"构建了一个涵盖15种癌症类型、源自191名患者的220个泛癌患者来源类器官（PDO）平台。综合表征显示，该PDO平台与亲本肿瘤保持了极高的一致性：组织病理学一致性达93%，驱动突变中位基因组一致性为80%，基因表达中位相关性为0.85。且传代10次后表达谱基本稳定，85%的主导肿瘤克隆被保留。功能实验证实，58%的来自患者的PDOs成功识别出了具有潜在临床应用价值的治疗漏洞。","scd":{"b":6.0,"i":6.0,"r":7.0,"d":9.0,"t":7.0},"kp":["样本规模[跨癌症患者来源类器官平台]: 220个类器官（来自191名患者的15种癌症类型）","组织病理学一致性[类器官与原代肿瘤]: 93%","基因组中位一致性[驱动突变]: 80%","基因表达中位相关性[类器官与原代肿瘤]: 0.85","表达谱稳定性[长期传代]: 保持稳定超过10代"]},{"i":38294,"as":"研究发现RNA甲基转移酶METTL3在乳腺癌中不仅通过m6A修饰依赖性途径发挥作用，还能独立于m6A调控细胞分泌途径。在乳腺癌患者肿瘤细胞中，METTL3发生错误定位并聚集于细胞质中。在细胞质内，METTL3直接与胞吐作用的关键调节因子EXOC7发生相互作用，从而促进肿瘤细胞的胞吐过程。这一m6A非依赖性的机制显著促进了肿瘤的发生与恶性表型，为癌症治疗提供了新的靶点。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[METTL3酶的非经典功能]: 独立于m6A甲基化修饰机制直接调节胞吐作用并促进肿瘤发生"]},{"i":38295,"as":"研究利用果蝇睾丸模型揭示了干细胞微环境衰老如何驱动睾丸功能退化。随着年龄增长，微环境细胞分泌的骨形态发生蛋白（BMP）信号水平下降，导致生殖干细胞（GSCs）中转录共抑制因子Hairless表达量上升。Hairless的升高抑制了RNA结合蛋白Imp的水平，进而造成干细胞因子Chinmo缺失。这一连锁反应最终引发细胞外基质异常积累、干细胞位置偏移及微环境恶化。通过上调BMP信号、过表达Imp或降解基质可有效延缓这一衰老过程。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[睾丸微环境衰老机制]: 骨形态发生蛋白（BMP）信号水平随年龄下降，导致生殖干细胞中转录共抑制因子Hairless表达增加"]},{"i":38296,"as":"利用酪酰胺信号放大测序技术，全面描绘了与Polycomb（PcG）小体相关的基因组区域，包括特定的着丝粒和端粒位点。这些区域富含抑制性组蛋白标记H3K27me3和H3K9me3，缺乏活性标记H3K4me3，且染色质可及性极低。研究发现，PcG小体周围存在高密度的复制起点，这复制起点与定位于此的复制起始识别复合体相关蛋白（ORCA/LRWD1）直接相关。ORCA与Polycomb抑制复合物相互作用，证实Polycomb介导的三维基因组组装直接控制DNA复制的时间。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[Polycomb小体相关基因组特征]: 富集抑制性标记H3K27me3和H3K9me3，包含特定的着丝粒和端粒位点"]},{"i":38297,"as":"基于长期草原实验平台，研究了二氧化碳浓度升高、气候变暖和干旱对生态系统功能（水汽与二氧化碳通量、水分利用效率及碳利用效率）的独立及交互影响。结果显示，尽管二氧化碳浓度升高和变暖单独作用时影响有限，但两者的协同交互作用显著放大了生态系统的呼吸作用。这一协同效应加剧了干旱对草原碳通量和水通量的负面影响，对于准确预测未来陆地生态系统气候反馈机制具有重要指导意义。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[草原生态系统功能退化机制]: 气候变暖与CO2浓度升高的协同效应加剧了干旱对碳通量和水通量的负面影响"]},{"i":38298,"as":"细胞在迁移过程中能感知并响应物理信号。研究发现，长时间暴露于升高的生理性静水压力下，会降低细胞对基底硬度、流体粘度、流体作用力和液压阻力的迁移敏感性。这种降低的机械敏感性在高压消除后仍可持续数天，表明细胞具有静水压力记忆。机制上，高压下调了Rho/MRTF/SRF通路，激活了不依赖肌球蛋白II的机械感知机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[静水压力对细胞迁移的影响]: 长时间暴露于病理生理相关的静水压力会降低细胞对基底刚度、流体粘度等机械因素的迁移敏感性"]},{"i":38299,"as":"研究人员开发了一种基于磁悬浮驱动的多功能软超表面系统，旨在解决传统机械超表面脆弱、响应慢及难以集成的缺陷，实现有形的双向人机交互。该系统采用6x6弹性像素阵列，通过底层电磁阵产生的吸引力或排斥力进行精准驱动。超表面最高可实现8.5毫米的高度调节，能够同步为用户提供视觉与触觉双重反馈。该技术具有结构坚固、响应迅速等优势，有效提升了人机交互的自然性与直观性，在智能交互显示等领域具有广阔应用前景。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[磁悬浮软超表面特性]: 具备高鲁棒性、快速响应和多功能的机械可重构特征，支持有形双向人机交互"]},{"i":38300,"as":"共生固氮发生在根瘤中，根瘤菌分化为类菌体。终末分化能增强固氮但限制根瘤寿命，适合一年生豆科植物。相反，具有不确定根瘤的多年生豆科植物必须长期维持共生，这与终末分化的类菌体不相容。研究鉴定了一个结节特异性蛋白家族，能够在不引起终末分化的情况下调节根瘤菌生理学，从而维持多年生豆科植物的长期共生固氮。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[共生固氮策略]: 终末分化限制根瘤寿命但可增强固氮作用"]},{"i":38301,"as":"针对细胞生物学领域“有丝分裂激酶对Erk信号的发育调节”一文的勘误，主要修正了原研究文章的偏差。","scd":null,"kp":[]},{"i":38302,"as":"本文是对H. Chu等人关于中国大米镉含量标准健康风险评估研究文章的勘误更正。","scd":null,"kp":[]},{"i":38303,"as":"血浆GDF15是一种与痴呆风险密切相关的分泌型细胞因子。研究表明，在中年测量时，血浆GDF15与未来15至25年内更高的痴呆风险相关，且与阿尔茨海默病相比，与血管性痴呆的关联更强。研究证实了GDF15在痴呆症中的机制作用，将其与脑小血管病、神经退行性变、磷酸化tau蛋白及表明神经免疫激活的脑脊液蛋白质组学特征联系起来。暴露于GDF15的培养髓系细胞也证实了其对神经免疫信号的改变作用。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["痴呆风险预测[中年期血浆GDF15指标]: 与15至25年随访期内的痴呆风险增加显著相关（尤其是血管性痴呆）"]},{"i":38304,"as":"双环[1.1.1]戊烷常被用作药物中芳香族框架的生物等排体。现有合成路线存在底物范围窄和官能团耐受性有限的问题。研究提出了一个通用的光诱导锰催化平台，用于[1.1.1]丙烷的连续双功能化，实现了多功能磺酰化BCP衍生物的模块化合成。该平台能够构建包含-Cl、-Br、-I、-CN、-SCD3等多种官能团的磺酰化BCP衍生物。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":4.0},"kp":["[双环[1.1.1]戊烷双功能化]: 光诱导锰催化平台"]},{"i":38305,"as":"水稻钙调蛋白样蛋白OsCML27通过OsMRLK63-OsCML27-OsRbohB模块调节水稻耐旱性。OsCML27作为OsRbohB介导的ROS产生的“柔性刹车”，负向调节水稻的耐旱性。过表达株系在干旱条件下表现出更快的失水率和较低的存活率，而突变体则表现出较慢的脱水率。机制上，OsCML27与受体激酶OsMRLK63相互作用并被磷酸化，进而微调ROS信号。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[水稻耐旱机制]: OsCML27作为柔性制动器负向调控耐旱性并抑制OsRbohB介导的活性氧(ROS)产生"]},{"i":38306,"as":"干细胞在自我更新和分化之间保持平衡。研究发现转录抑制因子TGIF2在神经发生过程中的转录启动中起关键作用。通过ATAC-seq和RNA测序，发现成百上千个神经元分化基因在神经干细胞中处于开放但低表达状态。TGIF2结合并调控这些神经源性启动基因，确保干细胞保持未分化状态，同时使其子细胞能够快速上调分化基因。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["转录特征[神经干细胞分化启动]: 分化相关基因的低水平表达"]},{"i":38307,"as":"脂肪胺是生物活性分子的核心结构，亟需通用且绿色的合成策略。研究报道了一种铁催化的脱羧羰基烷基胺化反应，在室温及温和光照下于HFIP中进行。该反应以醛、胺和羧酸为原料，无需额外添加剂，副产物仅为CO2和水。该方案具有优异的底物兼容性，能够克服空间位阻并耐受多种官能团，实现了复杂脂肪胺的高效合成。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["反应条件[脂肪胺合成(脱羧羰基烷基胺化)]: 铁催化、室温、温和光照","反应物体系[脱羧羰基烷基胺化]: 醛、胺和羧酸(HFIP溶剂中)"]},{"i":38308,"as":"酰胺键是生物活性分子的重要结构。在芳基卤化物的单氨基羰基化(MC)和双氨基羰基化(DC)中实现选择性控制一直是一项挑战。研究报道了一种在掺钯的氧化铟纳米催化剂中引入氧空位的策略，通过调节钯的第二配位层，彻底反转了从MC到DC的选择性。该催化剂在合成多种酰胺和α-酮酰胺（130个实例）中表现出优异的活性、选择性和可重复使用性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["[氨基羰基化反应]: 引入氧空位的Pd掺杂In2O3纳米催化剂可将单羰基化(MC)选择性完全反转为双羰基化(DC)"]},{"i":38309,"as":"挠曲电是一种产生极化响应的机电耦合机制。研究利用原子分辨率扫描透射电子显微镜（包括HAADF成像、EDX和EELS）研究了LSAT晶界处的挠曲电效应。结果显示，钽在晶界处偏析，形成了独特的化学有序结构，这种原子级的有序结构实现了巨大的挠曲电效应。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":4.0},"kp":["材料成分[LSAT晶界]: La0.24Sr0.76Al0.62Ta0.38O3","[挠曲电效应]: 通过晶界处的原子级有序实现巨大的挠曲电响应"]},{"i":38310,"as":"细胞壁重塑和适应性反应对植物耐盐性至关重要。研究发现磷脂酶Dα1（PLDα1）和PLDδ与细胞壁传感器FER激酶发生物理相互作用。PLD衍生的磷脂酸（PA）能稳定质膜上的FER并增强其激酶活性。这种PA驱动的FER激活促进了CC1的磷酸化，进而促进了盐胁迫下微管的重组。遗传分析揭示了PLDα和PLDδ在植物耐盐性中的协同功能。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["质膜定位与激酶激活[FERONIA受体]: 由磷脂酶D衍生的磷脂酸(PA)稳定并增强"]},{"i":38311,"as":"针对慢性呼吸道疾病缺乏家庭连续监测工具的问题，研究人员开发了异质模态表皮液态金属贴片（HELP）。该贴片采用铟驱动的银纳米线合金化来锚定液态金属消除漂移，分级半球形凸起作为模拟应变门，实现了R2=0.998的线性度、低于0.4%的迟滞、0.01%的应变检测限以及超过50万次循环的耐用性。其双通道设计允许同时进行对应变不敏感的心电图和超灵敏呼吸监测。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":4.0},"kp":["[表皮液态金属贴片(HELP)]: 铟驱动的银纳米线合金化锚定液态金属以消除漂移","[应变传感门控]: 分级半球形凸起作为模拟收缩门提高准确度、线性和稳定性"]},{"i":38312,"as":"血管生成是椎间盘退变的关键病理基础。研究表明，机械应力通过激活Hippo信号通路并诱导髓核细胞中YAP蛋白的降解，从而诱导椎间盘血管化。机制上，YAP经历液-液相分离形成生物分子凝聚物，招募并隔离转录因子SNAI1。破坏YAP凝聚物或释放SNAI1会恢复SNAI1介导的转录，导致其靶基因上调并驱动血管生成。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["病理机制[椎间盘血管化]: 机械应力激活Hippo信号通路并诱导髓核细胞中YAP蛋白降解"]},{"i":38313,"as":"研究人员利用扫描探针显微镜针尖施加高接触力引起的不对称摩擦响应，实现了对薄膜和单晶体中铁电极化的空间分辨可视化。这种摩擦不对称性是由挠曲电诱导的极化与铁电极化相互竞争或增强的结果。该技术被称为极化衍生摩擦显微镜，能够实现铁电畴的快速、低成本和无电压成像。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[铁电极化成像]: 扫描探针显微镜尖端施加高接触力产生不对称摩擦响应，实现空间分辨的可视化","[摩擦不对称性]: 源于柔性电响应"]},{"i":38314,"as":"代谢重编程是癌症的标志。通过CRISPR筛选，研究人员鉴定出甲羟戊酸途径酶PMVK是肝癌进展的关键调节因子。PMVK直接磷酸化转录因子SP1的Thr355位点，增强其DNA结合亲和力并促进其与脂质调节因子SREBP1/2的相互作用，从而驱动胆固醇和脂肪酸的合成。临床上，PMVK水平与磷酸化SP1水平正相关，并预示肝癌患者预后不良。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["转录因子磷酸化位点[SP1蛋白]: Thr 355","代谢重编程驱动因子[肝癌干细胞特性与进展]: 甲羟戊酸途径酶(PMVK)"]},{"i":38315,"as":"研究介绍了一类此前未被识别的微陨石子集——富硫堆积橄榄石（SCumPo）宇宙球粒。这些球粒以证明橄榄石晶体沉降的堆积结构和贫乏的氧-16（16O）体成分为特征。系统性的贫镍橄榄石斑晶、频繁的铁镍硫液滴、异常富硫的基质以及几乎没有磁铁矿的现象，均指向其在小行星撞击熔融期间经历了异常高度还原的条件。这表明其来源于当前陨石收藏中未代表的小行星。","scd":{"b":6.0,"i":2.0,"r":8.0,"d":6.0,"t":4.0},"kp":["宇宙球粒异常同位素比例[近地CY球粒陨石小行星来源]: 约10%","[SCumPo宇宙球粒]: 具有展示橄榄石晶体沉降的堆积结构且富含硫"]},{"i":38316,"as":"研究人员提出了掺杂Mn2+的氮化铝（AlN:Mn2+）作为发光材料。该材料同时具备明亮的橙色光致发光、强烈且持久的余辉发光、热释光以及机械发光特性。AlN:Mn2+在摩擦、冲击和超声激发等多种机械刺激下表现出多模态机械发光行为，能够将声音和力转化为光信号，展示了其在下一代传感和光电技术中的巨大潜力。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":7.0},"kp":["发光响应[AlN:Mn2+机械发光材料]: 可同时实现明亮的橙色光致发光和机械发光"]},{"i":38317,"as":"核糖体是蛋白质合成的中心。研究发现，在鼠伤寒沙门氏菌从对数生长期过渡到稳定期（营养饥饿）的过程中，单细胞内的核糖体蛋白水平表现出异质性。核糖体水平较高的细胞对基因表达的诱导反应较弱，但积累了更多的毒力基因产物。机制上，这种单细胞异质性是由环磷酸腺苷（cAMP）信号驱动的，cAMP信号增加了核糖体水平和蛋白质合成在单个细胞间的差异。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[营养饥饿期间单细胞蛋白质合成调节]: 由cAMP信号驱动并表现出异质性"]},{"i":38318,"as":"超级地磁暴的特征是近地空间环电流的极端增强。通过Arase卫星的原位测量表明，在2024年5月的超级地磁暴期间，尽管太阳风密度很高，但来自地球的重离子在环电流中占据了前所未有的主导地位。太阳风对环电流能量密度的贡献微乎其微。这一观测证据突出了地球离子供应和磁层内传输过程在超级地磁暴环电流发展中的关键作用，且超强环电流深入渗透至靠近地球的磁层区域。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":8.0},"kp":["[2024年5月超级地磁暴期间地球附近环电流离子来源]: 呈现出地源重离子的极端主导地位"]},{"i":38319,"as":"","scd":null,"kp":[]},{"i":38320,"as":"","scd":null,"kp":[]},{"i":38321,"as":"本研究以多环芳烃衍生物为模型系统，系统阐明了共轭芳烃的节点和非节点位置取代如何决定其化学反应性和物理性质。研究发现，在相同回流条件下，由于分子轨道振幅受抑制，节点位置发生的Sonogashira C-C偶联反应产率明显低于非节点位置。光谱表征进一步揭示了取代产物在光物理性质上的显著差异，将化学反应性与室温磷光（RTP）特性联系起来。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[多环芳烃衍生物的分子轨道节点工程]: 节点和反节点取代系统地决定了其化学反应性和物理性质"]},{"i":38322,"as":"据《自然·电子学》报道，研究人员开发出一种基于干燥MXene-压敏胶复合材料的高密度、低漂移电极阵列。该技术能够实时可视化植物中由环境刺激产生的电波，为植物电生理信号的精准监测提供了创新的工具。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[基于MXene-压敏胶复合电极]: 实现植物环境刺激电波的实时可视化且具有低漂移特性"]},{"i":38323,"as":"据《科学进展》报道，研究人员设计出一种MXene网格架构天线。该天线具备保形、透明且高效的特性，完美适配可穿戴设备和柔性超表面的应用需求，为柔性电子设备的通信器件开发提供了新的平台方案。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":4.0,"t":8.0},"kp":["天线平台特性[MXene网格架构]: 共形、透明且高效，适用于可穿戴设备和柔性超表面"]},{"i":38324,"as":"通过空间与单细胞转录组学的综合分析，研究对比了皮肌炎（DM）与皮肤红斑狼疮（CLE）。结果显示，癌症相关DM皮损的特征是含有富含巨噬细胞的分散免疫浸润物，或具有致密B细胞核心及CD4+/CD8+ T细胞包绕的淋巴聚集体，且血管结构保持完整。非癌症相关DM皮损则以致密髓系细胞浸润为特征，局部伴有IL1B和CXCL10的高表达。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[癌症相关皮肌炎皮肤病变]: 以富含巨噬细胞的分散免疫浸润物为特征"]},{"i":38325,"as":"单细胞转录组和质谱成像分析表明，人参胚性愈伤组织（EC）的原胚层能有效累积人参皂苷，含量与林下参相当。表观遗传分析显示，EC在再生和皂苷代谢相关基因位点上的组蛋白乙酰化水平升高及染色质开放性增强，与其产皂苷能力直接相关。提升组蛋白乙酰化水平或过表达再生相关基因能进一步促进该过程。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":7.0},"kp":["人参皂苷高效合成部位[人参胚胎]: 胚胎原表皮"]},{"i":38326,"as":"研究提出了一种名为SMURF的跨平台软分割算法，利用深度学习将mRNA从捕获点精准分配至附近细胞核。SMURF还能通过将细胞投影到笛卡尔坐标来展开复杂的组织结构，从而分析细胞类型的组织分布和基因表达梯度。相比现有方法，SMURF能更准确地将mRNA分配给单细胞，并稳健地揭示多组织内的转录程序和空间结构。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["算法技术特征[空间转录组学软分割]: 利用深度学习将mRNA从捕获点映射到附近细胞核"]},{"i":38327,"as":"研究人员提出了PlanarFold，一种整合了二维分子动力学模拟与动态规划的粗粒度RNA计算模型。与全原子模型相比，该模型速度提升超过四个数量级。在二级结构层面，PlanarFold能够定量重现多种实验场景下的结果，包括天然二级结构、热力学与动力学、力学特性，以及共转录和从头折叠过程。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["计算效率提升[PlanarFold二维粗粒度RNA模型]: 较全原子模型加速四个数量级以上"]},{"i":38328,"as":"研究探讨了CRISPR-Cas13a系统与II型毒素-抗毒素模块（HicAB）在异源表达于大肠杆菌时的功能协同作用。研究发现，抗毒素HicB表现出毒性，而Cas13a能直接激活HicB，抑制细菌生长并赋予其抗噬菌体能力。结构分析表明，Cas13a的结合促进了HicB四聚体在空间上的接近，从而触发了防御机制。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["功能协同性[细菌免疫防御]: CRISPR-Cas13a系统与II型毒素-抗毒素模块(HicAB)"]},{"i":38329,"as":"研究发布了亚麻荠属的改进基因组组装，包括四倍体和两种具有不同染色体数目的六倍体（Type 1: 2n=40, Type 2: 2n=38）。研究发现了亚麻荠属的第四个亚基因组（Type 2），该亚基因组表现出区别于其他已知亚基因组的独特染色体重排。在近期形成的物种中，第二个亚基因组表现出基因表达优势，这一现象与染色体邻近度密切相关。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["亚基因组发现[亚麻荠属]: 揭示第四个亚基因组","染色体倍性特征[多倍体微果亚麻荠Type 1]: 2n = 40","染色体倍性特征[多倍体微果亚麻荠Type 2]: 2n = 38"]},{"i":38330,"as":"本研究结合神经成像与多变量模式分析，以国际象棋为模型，揭示了专家大脑信息处理的三大核心机制。首先，专家脑内的表征内容由表面的视觉特征转化为高级的关系型信息；其次，这种转变伴随着结构变化，表现为低维且优化的表征模式，即信息编码变得更紧凑、更有序，同时保留了精确评估所需的细节；最后，信息的表征负荷从特定的感觉皮层转移到了通用的额顶网络。总之，专家大脑能够以更精简的神经表征承载更丰富的专业知识。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[专家大脑高级信息处理]: 依赖于特定领域的知识，并以国际象棋为模型系统结合神经影像学和多元模式分析揭示了专家大脑的三个原则"]},{"i":38331,"as":"通过分析法国国家森林清查中超过50万棵树木的数据（2015-2023），研究发现主要树种的死亡率正在上升。模型分析确定树木大小、竞争和季节性气候异常是死亡率的主要驱动因素。其中，温暖的冬季和春季是最常见且最具影响力的气候预测因子，这与物候扰乱和寒冷季节害虫存活率提高有关。温暖的夏季同样具有影响力，可能与害虫活动和干旱胁迫增加有关。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":8.0,"t":6.0},"kp":["树木死亡率驱动因素[法国主要树种]: 树木尺寸、竞争以及季节性气候异常（尤其是暖冬和暖春）"]},{"i":38332,"as":"研究提出了一种基于拓扑声学的几何相位传感方法，通过整合台站阵列信号来编码地震波场的固有几何特征。几何相位变化（Δη）能够捕获波路径积分的介质扰动。在Kı̄lauea火山的实际应用表明，Δη紧密追踪了2018年喷发前的岩浆增压和喷发期的火山口塌陷，为火山的综合监测提供了稳定且独特的量化指标。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":5.0,"t":6.0},"kp":["火山活动监测方法[夏威夷Kı̄lauea火山]: 基于拓扑声学的几何相位传感方法，通过整合台站阵列信号编码地震波场的固有几何形状"]},{"i":38333,"as":"研究基于卫星总初级生产力数据，绘制了分辨率为0.05度的全球作物最高气温（Topts）地图：水稻（28.63±2.65°C）、大豆（27.34±2.34°C）、玉米（26.12±3.46°C）和小麦（24.73±3.41°C）。分析发现作物最高气温存在广泛的空间异质性，在亚热带地区达到峰值。这种热驯化是由当地温度、水分有效性和太阳辐射共同塑造的。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":9.0,"t":5.0},"kp":["最适温度[水稻]: 28.63 ± 2.65 °C","最适温度[大豆]: 27.34 ± 2.34 °C","最适温度[玉米]: 26.12 ± 3.46 °C","最适温度[小麦]: 24.73 ± 3.41 °C","空间分辨率[全球作物最适温度图]: 0.05度"]},{"i":38334,"as":"孔明系统是一种由效应复合物KomBC组成的细菌抗病毒免疫系统。在噬菌体感染时产生的非典型信号核苷酸dITP会激活该系统。结构分析表明，KomBC组装成由KomB-KomC重复单元垂直堆叠而成的螺旋丝状物。dITP与KomB结合会引发丝状物的渐进式构象重排，使KomC呈现具有NADase酶活性的构象，进而限制噬菌体增殖。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[孔明抗噬菌体防御系统激活机制]: 噬菌体感染产生的非典型信号核苷酸dITP诱导KomBC效应复合物组装成螺旋丝状结构"]},{"i":38335,"as":"对撒哈拉以南非洲地区60,558个农业地块的分析表明，女性小农户受高温影响的程度是男性小农户的2至2.5倍。在家庭内部也观察到明显的异质性，以及劳动调整和补偿性投资方面的不同适应策略。极端高温每增加一个度日，作物受损和粮食不安全的风险就会显著加剧。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["评估样本量[撒哈拉以南非洲女性小农高温损失]: 60,558个农业地块"]},{"i":38336,"as":"一项研究指出，过去三十年中，快速发展经济体巨大的混凝土需求推动了资源使用的激增。尽管在生产工艺改进方面做出了努力，但这仅能有限地减轻资源消耗压力。研究强调，迫切需要找到将人类发展目标与混凝土的大量资源消耗相脱钩的有效解决方案。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[快速发展的经济体]: 过去三十年间的混凝土需求推动了资源使用的增加，且生产改进仅略微减轻了资源负担"]},{"i":38337,"as":"研究表明，溶剂化离子的溶剂交换动力学与界面电化学反应动力学存在内在耦合关系。基于这一机制设计的电解质，能够有效加速界面的电荷转移，从而实现锂离子电池的快速充电以及在低温环境下的稳定运行。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["电化学反应动力学[溶剂化离子溶剂交换]: 与界面电化学反应动力学存在本征耦合","[电解液设计机制]: 利用溶剂交换动力学与界面电荷转移的耦合实现快充与低温运行"]},{"i":38338,"as":"小型高山湖泊正迅速成为全球高寒山区冰冻圈风险中被忽视的关键组成部分。尽管其规模不大，但在不稳定和消退的冰川地形中，小型湖泊加速形成，并已引发破坏性的溃决洪水。这些洪水对适应能力有限的偏远社区造成了尤为严重的影响。迫切需要将此类灾害纳入气候和灾害治理框架中。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[高山洪水风险盲区]: 加速形成于不稳定退化地形中的小型高山湖泊极易引发破坏性的溃决洪水"]},{"i":38339,"as":"研究利用冷冻电镜技术解析了构巢曲霉的高亲和力嘌呤转运蛋白UapA的结构。高分辨率结构（2.06至3.5 Å）揭示了水分子和脂质在底物结合、特异性、转运蛋白二聚化及其活性调节中的关键作用。此外，结构还显示了UapA的N端尾部在调节过程中的具体机制，为理解核碱基抗坏血酸转运蛋白（NAT）家族的运转机制提供了重要见解。","scd":{"b":9.0,"i":1.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[嘌呤转运蛋白UapA结构解析]: 报道了构巢曲霉高亲和力嘌呤转运蛋白UapA的近全长冷冻电镜结构","[NAT家族转运机制]: 电梯型转运器"]},{"i":38340,"as":"人类白细胞抗原(HLA)基因的多态性会增加疾病风险。在乳糜泻(CeD)中，HLA-DQ2.5通过向CD4+ T细胞呈递麸质肽，并促使这些T细胞通常采用固定的T细胞受体(TCR)，从而引发疾病。研究团队对103名乳糜泻患者和103名对照组受试者的初始CD4+ T细胞的αβ TCR库进行了测序，并进行了基因使用数量性状基因座分析，以探究HLA和TR基因内部的遗传变异是否塑造了初始TCR库。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[乳糜泻发病机制]: HLA-DQ2.5通过向CD4+ T细胞呈递面筋肽，并使用典型T细胞受体引发疾病"]},{"i":38341,"as":"能力验证测试常作为法庭证据，以证明法医模式比对方法的准确性和可靠性。然而，其科学价值取决于测试设计、评分规则及其支持现实推断的程度。近期一项针对法医枪支识别（比对子弹和弹壳是否由特定枪支发射）的能力验证测试报告指出，其假阳性错误率接近20%。研究指出了法医能力验证中存在的几项局限性，例如测试样本的使用问题。","scd":{"b":3.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[法医模式比较方法有效性]: 法庭上常引用的能力验证的科学价值高度依赖于测试设计、评分规则以及对现实世界性能的有效推断"]},{"i":38342,"as":"","scd":null,"kp":[]},{"i":38343,"as":"在分子尺度上经典连续介质假设的失效，给理解流体饱和纳米多孔材料的力学和声学特性带来挑战。研究提出了一种多尺度理论框架，将线性化学-多孔弹性理论扩展用于描述纳米多孔固体与受限流体对机械波激发的耦合响应。研究通过甲烷在沸石中吸附和传输的原子模拟，计算出有效多孔力学参数（如弹性、应力化学耦合张量和流体迁移率张量），并将这些参数嵌入到机械波传播的连续介质模型中。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["理论框架[流体饱和纳米多孔介质波传播]: 扩展线性化学-孔隙弹性理论的多尺度框架","[化学-孔隙力学有效参数]: 可描述纳米多孔固体和受限流体对机械波激发的耦合响应"]},{"i":38344,"as":"蛋白质进化的过程通常被视为种群在适应度景观上的攀爬。研究引入了适应度景观设计(FLD)的基础原理，能够以定量精度定制生物物理适应度景观的结构峰谷，从而实现对长期进化结果的稳健控制。FLD算法利用化学衍生的生物物理适应度模型进行随机优化，成功发现了最优的抗体集合，这些集合能够迫使目标蛋白以特定的方式进化，填补了定量重塑适应度景观方法论的空白。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["合成生物学方法论[蛋白质进化]: 适应度景观设计(FLD)","[适应度景观设计(FLD)]: 用于定量重塑蛋白质进化发生的基础景观，定制结构峰谷"]},{"i":38345,"as":"当正常的伤口愈合策略失调时，会导致纤维化。视网膜下纤维化是新生血管性年龄相关性黄斑变性(nAMD)的终末阶段。为了寻找导致视网膜下纤维化的细胞外基质(ECM)来源，研究利用Col1a1-YFP报告小鼠，在两种模型（消退性视网膜损伤模型和纤维化视网膜下疾病模型）中实时活体成像胶原蛋白的产生，并构建了产生胶原蛋白的细胞图谱，揭示了早期损伤与纤维化视网膜下疾病中截然不同的成纤维细胞命运。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":[]},{"i":38346,"as":"商用锂离子电池的石墨负极在快充时受限于界面极化，会导致SEI生长和锂沉积。双草酸硼酸锂(LiBOB)等硼酸盐添加剂可提升倍率性能，但会产生高阻抗界面和气体膨胀。为此，研究开发了一种无水双儿茶酚硼酸锂(LiBCB)添加剂，通过一步非水合成消除了结晶水这一容易被忽视的因素。该添加剂能够消除结晶水的影响，从而展现出其内在的界面化学功能。","scd":{"b":6.5,"i":3.0,"r":4.0,"d":5.0,"t":6.0},"kp":["负极界面极化[石墨负极快充]: 限制快充性能并驱动高阻抗SEI生长与锂沉积","电解液添加剂[锂离子电池]: 双草酸硼酸锂(LiBOB)","[双草酸硼酸锂(LiBOB)]: 虽可提升倍率性能但易产生厚且高阻抗的界面层及气体导致的电池胀气"]},{"i":38347,"as":"电化学耦合二氧化碳(CO2)和硝酸根(NO3-)是合成尿素并同步处理废水脱氮的可持续策略。然而，传统催化剂对反应物的非选择性吸附阻碍了关键的碳(C)和氮(N)中间体在空间上的对齐相互作用，降低了C-N键的合成效率。研究为此合理设计了一种双位点催化剂Au24Cd/CZ9-700。该催化剂的尿素产率峰值达到668.60 µg/h，解决了传统催化剂缺乏选择性的问题。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["选择性瓶颈[CO2和硝酸盐共还原]: 传统催化剂非选择性吸附阻碍关键中间体的空间对齐相互作用","电催化剂[电化学尿素合成]: Au-Co双位点催化剂","[Au-Co双位点]: 定制关键中间体以实现空间对齐相互作用，提升反应物吸附选择性"]},{"i":38348,"as":"水系锌离子电池(AZIBs)的锌金属负极存在引发水致副反应和离子迁移缓慢的问题，严重降低了库伦效率和寿命。研究通过在锌负极和电解质之间引入由三聚氰胺(MA)和间苯二甲酸(IPA)自组装的有机共晶，构建了具有广泛氢键网络的超分子结构。理论和实验结果均表明，这些共晶能够从锌负极表面捕获并隔离活性水分子，其内部的氨基、羧基等亲锌位点能显著增强离子传输。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":5.0,"t":6.0},"kp":["界面工程[水系锌离子电池锌金属负极]: 三聚氰胺(MA)和间苯二甲酸(IPA)自组装的有机共晶超分子结构","[有机共晶层]: 具有广泛的氢键网络以抑制水诱导的副反应并改善离子迁移动力学"]},{"i":38349,"as":"电池材料的热化学表征能够将材料的内在特性与控制性能和安全的分解途径、热量产生及气体逸出联系起来。针对NMC811-石墨电池配置多样性和微型电池架构应用受限的问题，本研究建立了一种自下而上的组件解析方法。该方法整合了差示扫描量热法/热重分析(DSC/TGA)、逸出气体分析(EGA)和原位XRD技术，关联了部分配置和微型电池配置中的分解途径与能量释放，为评估新兴化学体系的安全性和稳定性提供了可转移的方案。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["热安全与热力学分析[NMC811-石墨电池]: 建立自下而上、基于组件分辨的微电池架构表征方法","[微电池架构(DSC/TGA)]: 将材料本征属性与分解途径、产热和逸出气体联系以评估电池安全性能"]},{"i":38350,"as":"一项研究发现，袭击地球的太阳风暴（行星际日冕物质抛射）减少了入射的高能宇宙射线数量，导致了TeV（万亿电子伏特）量级宇宙射线出现瞬态大尺度各向异性现象。这一观测结果提出了一种测量太阳活动的新方法。","scd":null,"kp":["宇宙线瞬态大尺度各向异性[行星际日冕物质抛射(太阳风暴)]: 高能宇宙射线入射量减少"]},{"i":38351,"as":"研究提出了一种针对开放量子系统的统一多体微扰理论。该理论利用Keldysh-Lindblad形式，将耗散、电子关联和外部驱动置于同等重要的位置进行处理。研究引入了一种图解法来处理代表准粒子流和波动的耗散相互作用线。","scd":null,"kp":["多体摄动理论[开放量子系统]: 采用Keldysh-Lindblad形式统一处理耗散、电子关联和外部驱动"]},{"i":38352,"as":"研究探讨了一维波导中由弱相干场共振驱动的N个相同二能级原子的散射场特性。当原子间距为驱动波长时，增加原子数量会抑制光的透射，同时增强光子的聚束效应。此时，透射率会表现出特定的变化规律。","scd":null,"kp":["光子传输与聚束效应[一维波导中共振驱动的N个二能级原子]: 原子间距等于驱动波长时，增加原子数会抑制传输并增强光子聚束(超级聚束)"]},{"i":38353,"as":"在两相共晶固体的熔化过程中，会出现丰富多样的图案。研究详细描述并分析了这种层状共晶熔化过程中的图案形成现象。","scd":null,"kp":["相变图案形成[两相层状共晶固体的熔化过程]: 产生丰富多样的图样"]},{"i":38354,"as":"窄带系统中的磁性源于电子关联、量子几何与能带色散之间的相互作用。铁磁体和反磁体均可作为具有窄带的不同模型的基态出现。研究探讨了量子几何与能带色散之间的竞争机制，阐述了在特定条件下哪一种磁性状态会被优先选择。","scd":null,"kp":["磁性基态[窄带系统]: 铁磁和反铁磁性源于电子关联、量子几何与能带色散之间的竞争"]},{"i":38355,"as":"研究利用部分子-强子-量子分子动力学(PHQMD)方法，探讨了吉电子伏特能量下的重离子碰撞中，核物质状态方程(EOS)对集体观测量的影响。具体分析了动量相关势下，核子和轻团簇的直接流(v1)和椭圆流(v2)的变化规律。","scd":null,"kp":["集体流(v1和v2)[吉电子伏特能级重离子碰撞中的核物质状态方程(EOS)]: 利用部分子-强子-量子分子动力学(PHQMD)方法研究动量相关势对核子与轻团簇定向流和椭圆流的影响"]},{"i":38356,"as":"反铁磁体中的畴壁在自旋极化电流的作用下表现出铁磁体中未见的新动力学特性，且该动力学可通过电流的极化方向进行调节。当面内极化电流作用时会产生传播的畴壁，而垂直极化电流则会产生进动动力学。研究详细观测了自旋轨道扭矩下反铁磁畴壁的轮廓变化和动力学机制。","scd":{"b":7.5,"i":2.0,"r":7.0,"d":5.0,"t":7.5},"kp":["动力学特征[反铁磁畴壁]: 面内极化下获得传播畴壁","[自旋极化电流调控]: 垂直极化下表现为进动动力学且动力学状态可通过自旋极化电流极化方向进行可调谐"]},{"i":38357,"as":"时空涡旋是一种在空间和时间上交织轨道角动量的多色模式。研究引入了一类新型的涡旋——“时空等离子体涡旋”，其携带着非平凡的拓扑自旋结构。这种涡旋是通过时间上分离的表面等离激元的时序干涉产生的，可在芯片尺度上实现合成。","scd":{"b":8.5,"i":3.0,"r":8.0,"d":6.0,"t":7.5},"kp":["等离子体涡旋[芯片级合成时空]: 携带非平庸拓扑自旋织构","[时空等离子体涡旋生成]: 通过时间脉冲的时空干涉生成"]},{"i":38358,"as":"","scd":null,"kp":[]},{"i":38359,"as":"","scd":null,"kp":[]},{"i":38360,"as":"","scd":null,"kp":[]},{"i":38361,"as":"研究探讨了过渡金属硫族化物（TMDs）中拓扑电子态与长寿命激子强光学响应的独特结合。通过耦合激子与拓扑态构建相互作用的费米子-玻色子系统，深入研究了分数陈绝缘体中激子与任意子的结合现象，并揭示了该相互作用产生的特定光谱指纹。","scd":{"b":7.5,"i":2.0,"r":7.0,"d":4.0,"t":7.5},"kp":["激子-任意子结合[分数陈绝缘体]: 具有独特的光谱指纹特征","材料体系[分数陈绝缘体]: 过渡金属硫族化物(TMDs)","[过渡金属硫族化物(TMDs)]: 独特结合了无外磁场实现拓扑电子态和长寿命激子产生的强光学响应"]},{"i":38362,"as":"研究证明了连续时间晶体可以作为一种PT对称状态出现。通过分析Lindblad开放量子系统，阐明了连续时间平移对称性自发破缺的条件，并揭示了在特定参数下系统出现的临界异常点，为理解开放量子系统中时间晶体的形成条件提供了明确的机制解释。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":4.0,"t":7.5},"kp":["时间晶体[连续时间对称性破缺]: 作为PT对称状态出现并伴随关键异常点","[开放量子系统Lindbladian]: 阐明了连续时间平移对称性自发破缺及时间晶体出现的完全显现条件"]},{"i":38363,"as":"研究通过实验测量了铍中电子交换关联空穴的动态行为。结果显示，其基态交换关联空穴尺寸约为2埃，但在等离子体激元激发能下，该尺寸会显著扩展至约5埃。这直接证明了电子动力学过程对材料内部电子关联特性具有显著影响。","scd":{"b":5.0,"i":1.0,"r":7.0,"d":5.0,"t":7.5},"kp":["交换相关空穴尺寸[铍]: 约2 Å","交换相关空穴扩展尺寸[等离激元激发能]: 高达约5 Å"]},{"i":38364,"as":"研究利用精确的数值模拟，探讨了非互易耦合对量子多体临界性和纠缠的影响。通过研究受非互易增益和损耗影响的相互作用费米子链，揭示了非互易效应与多体相互作用之间的竞争机制，并阐明了该系统经历耗散相变的具体物理过程与特性。","scd":{"b":6.5,"i":2.0,"r":7.0,"d":4.0,"t":7.5},"kp":["[非互易费米子]: 相互作用系统的耗散相变受到非互易增益与损耗相互作用的显著影响"]},{"i":38365,"as":"提出了一种利用预成型笼引导组装的策略，以解决金属有机框架（MOFs）中缺陷空间分布难以控制的难题。使用预合成的Rh(II)金属有机多面体作为持久空腔模板，在HKUST-1型网络中诱导了拓扑相关的非周期性缺陷。利用缺失一个羧酸基团的连接体，成功构建了9种独立的不同局部缺陷构型。","scd":{"b":7.0,"i":2.0,"r":6.5,"d":6.0,"t":6.0},"kp":["组装策略[非周期柔性金属有机框架]: 利用预成型笼引导缺陷组装","缺陷工程[HKUST-1型MOF]: 实现拓扑相关缺陷的编程引入和诱导非周期性"]},{"i":38366,"as":"提出了一种通过能量陷阱调节稀土掺杂纳米颗粒进行深度学习增强生物成像的技术。针对传统纳米探针在成像深度和光学分辨率之间的矛盾，利用Er³⁺在1530纳米发射的高分辨率与其他探针的深穿透特性，结合能量陷阱概念，优化了体内近红外成像的穿透深度与分辨率。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["发射波长[Er³⁺掺杂纳米颗粒]: 约1530 nm","[深部组织生物成像]: 面临高光学分辨率与有限水吸收组织穿透深度的折中挑战"]},{"i":38367,"as":"报道了一种利用光生氧杂环丁烷作为中间体的环丙烷化催化路线。通过醛和呋喃的光化学[2+2]环加成反应生成氧杂环丁烷，随后在路易斯酸催化下发生分子内SN型重排，以理想的原子经济性生成环丙烷。该策略从可再生原料出发，避免了传统方法中的危险重氮前体和化学计量副产物。","scd":{"b":7.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["合成路径[环丙烷化]: 以光化学[2+2]环加成形成的光生氧杂环丁烷为门户的催化路线"]},{"i":38368,"as":"概述了花青染料基光敏剂在医疗特别是光动力治疗中的应用与进展。针对传统光敏剂治疗效率受限的问题，花青染料作为首选分子框架被广泛开发。研究总结了过去8年间团队在花青染料光敏剂领域的开创性合理设计贡献，为解决该领域内部沟通碎片化和关键技术模糊性提供了系统性归纳。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["分子框架[光动力治疗用光敏剂]: 花青染料"]},{"i":38369,"as":"开发了一种非极性交联聚合物架构，用于稳定离子导电聚合物中的离子通道，实现稳健的二氧化碳到酒精的电催化转化。将离子导电聚芳烃哌啶集成到非极性聚苯乙烯网络中，构建的疏水支架有效锁定了离子通道，抑制了富醇环境引起的溶胀，使聚合物机械性能保持在97%以上。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["聚合物结构[CO2到酒精电合成]: 非极性交联聚合物架构","[非极性交联聚合物]: 在富醇环境中稳定离子通道，实现稳健的CO2电还原转化"]},{"i":38370,"as":"探索了利用酰胺酶生物催化加速单乙醇胺（MEA）水溶液捕集二氧化碳的溶剂再生步骤。基于氨基甲酸乙酯降解的酰胺酶特征超家族酶进行序列挖掘，利用生物催化剂替代原本主导二氧化碳去除过程能量成本的高耗能热溶剂再生工艺，从而实现二氧化碳的高效释放与利用。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["脱附机制[单乙醇胺水溶液捕获的CO2]: 酰胺酶催化解吸","传统脱附方式[胺洗法CO2释放]: 能量密集的热溶剂再生"]},{"i":38371,"as":"设计了一种新型氟醚共溶剂（FTE），以解决锂氧电池实际应用中电解液挥发分解、锂负极退化及放电产物不可逆的挑战。该共溶剂具有高沸点，能有效抑制电解液蒸发，其引入还优化了电池的界面化学和溶剂化动力学，显著提升了高理论能量密度锂氧电池的综合循环性能。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["能量密度[锂氧电池]: 超高理论能量密度","主要挑战[锂氧电池实际应用]: 电解液挥发与分解、锂负退化及Li₂O₂放电产物不可逆"]},{"i":38372,"as":"开发了一种用于盐湖提锂的自适应Mg²⁺门控膜（PA-15C5膜）。通过将4'-氨基苯并15-冠-5-醚（AB-15C5）大环接枝到聚酰胺（PA）膜表面，利用门控效应使纳米通道通过空间重排实现响应性尺寸切换。该自适应机制克服了传统固定尺寸纳米通道在Mg²⁺/Li⁺比例剧烈变化时的分离局限。","scd":{"b":7.5,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["膜材料[电池级锂提取]: 自适应Mg²⁺门控膜","改性技术[盐湖提锂纳滤膜]: 将AB-15C5大环分子接枝到膜上","传统膜缺陷[复杂多级分离过程]: 固定纳米通道尺寸不足以应对Mg²⁺/Li⁺比例的剧烈变化"]},{"i":38373,"as":"通过控制苝双酰亚胺衍生物的弯曲度，揭示了结构扭曲增强非辐射弛豫的物理机制。光谱测试表明，系统在单重态流形内实现了从近单位发射到强非辐射衰变的转变，排除了系间窜越路径。时间分辨拉曼测量证实，弯曲引起的振动景观重组是控制能量耗散和内部转换的核心机制。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["发光特性[苝双酰亚胺衍生物]: 弯曲结构诱导从近统一发射向增强非辐射弛豫的显著转变"]},{"i":38374,"as":"提出了一种自由基介导的色散（RMD）策略，以解决单壁碳纳米管（SWCNTs）严重自聚集导致热电性能退化的问题。合理设计了带有给体-受体共轭主链和自由基末端的小分子OTN。该策略通过主链增强π相互作用与自由基末端的双重协同作用，有效打破了碳热电材料的聚集极限，提升了电导率。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[单壁碳纳米管]: 严重自聚集导致热电性能退化","[单壁碳纳米管]: 具有优异导电性和机械坚固性，常规分散策略无效"]},{"i":38375,"as":"研究了聚乙烯与O₂和NOx催化氧化转化为二羧酸的增强形成机制。发现在无催化剂和特定反应条件下，二羧酸产率可达约29 mol%，且过氧化为一氧化碳和二氧化碳的程度极低。在高一氧化氮分压下，气态产物的形成被有效抑制，从而在多种产物中实现了极高的碳回收率。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[聚乙烯与O2和NOx催化氧化]: 二羧酸产物可通过反应参数调节和催化剂设计实现增量"]},{"i":38376,"as":"通过生物勘探废弃塑料并结合荧光激活细胞分选（FACS）技术，鉴定出用于降解聚氨酯（PUR）和聚酰胺（尼龙）的新型酶。研究识别了29种塑料降解细菌，并通过质谱和同源搜索确定了12种酶。与现有酶相比，这些新鉴定的酶对高分子量PUR聚合物和尼龙纺织品表现出更高的热稳定性和水解活性。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["酶挖掘机制[废弃塑料]: 使用荧光塑料类似物结合荧光激活细胞分选技术（FACS）进行生物勘探","[聚氨酯和尼龙降解]: 鉴定出29种新型降解酶"]},{"i":38377,"as":"综述了多孔有机笼（POCs）在离子分离膜领域的最新进展。多孔有机笼具备精确可调的孔道结构和优异的溶液可加工性。其独特的结构限域与可调离子-通道相互作用能力，实现了对尺寸和理化性质高度相似的离子进行选择性分离，文章还重点讨论了该膜的分子设计、界面工程及分离机制。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[多孔有机笼膜]: 结合结构限域与可调离子-通道相互作用实现尺寸相近离子的选择性分离"]},{"i":38378,"as":"提出并验证了“配位饱和异构”作为分子设计范式，以系统调控碘化亚铜团簇闪烁体的发光和闪烁特性，应用于计算机断层扫描成像。通过调节单一A位阳离子（N-甲基哌嗪）的质子化状态，实现了离子型一维链、有机型等多种不同结构模式的构建，优化了发光效率、稳定性和器件兼容性。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":5.0,"t":4.0},"kp":["分子设计范式[碘化亚铜团簇]: 利用“配位饱和异构”系统调控发光和闪烁特性"]},{"i":38379,"as":"提出了一种由选择性轨道耦合（SOC）理论指导的配位工程策略，用于设计高性能电容去离子（CDI）的氯离子捕获电极。成功合成了具有四面体铁和八面体钴共存位点的Fe₂CoSe₄/Ti₃C₂异质结构。这种独特的双位点几何结构引发了显著的电荷转移和电子调制，从而实现了氯离子的高效选择性捕获。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[Fe2CoSe4/Ti3C2异质结构]: 采用选择性轨道耦合（SOC）理论指导的配位工程策略设计高性能捕获电极"]},{"i":38380,"as":"本研究提出了一种靶向导向策略，用于开发人类15-脂氧合酶-1（15-LOX-1）的光控抑制剂。15-LOX-1是炎症信号传导、铁死亡和癌症中的关键酶。基于已知配体的结构特征，研究开发了三类互补的光开关化合物：可逆偶氮苯、偶氮杂芳烃和共价偶氮双炔。这些化合物展现出高效的E/Z光致异构化能力和高双稳态特性，实现了对生物过程时空的精准控制。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[15-脂氧合酶-1抑制剂]: 采用偶氮基光开关结构，实现对肠道炎症信号的时空光控调节"]},{"i":38381,"as":"本文探讨了生物分子凝聚体对蛋白质聚集（如淀粉样原纤维形成）的双重调节机制。生物分子凝聚体具有与周围环境不同的浓度和特性，能够调控生化过程。文章指出，与直觉相反，即使在局部蛋白质浓度升高的情况下，凝聚体本体内的蛋白质聚集也可能被抑制而非加速。理解这种相分离与原纤维形成之间相互作用的分子机制，对于认识神经退行性疾病等病理条件具有重要意义。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[生物分子凝聚体]: 能够调控蛋白质聚集，同时具备加速和抑制淀粉样原纤维形成的双重作用"]},{"i":38382,"as":"研究受自然现象启发，开发了一种在“脏水”上进行钯催化胺化形成C-N键的新方法。该方法通过向水中加入一定量的氢氧化钾（即“脏物”）产生高碱性条件，从而快速引发胺化反应，并自带所需碱性，简化了反应过程。高浓度的氢氧化钾水溶液（如30% KOH）的粘度阻止了有机偶联组分的溶解，因此能够有效容纳酯基、腈基等对碱敏感的官能团，避免了副反应的发生。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[“脏水”钯催化胺化]: 利用添加KOH产生的强碱性条件在水中实现快速C─N键偶联"]},{"i":38383,"as":"为解决无阳极锌金属电池（AZMBs）中界面副反应和阴阳极交叉对话导致的性能下降问题，研究采用数据科学引导策略，通过分子描述符筛选开发了一种不对称双相分离器。该分离器在阳极侧设计有Zn²⁺供应界面（ZSI）。与传统单一界面策略不同，这种数据驱动的双相分离器有效克服了系统性的界面问题，提升了水系电池的能量密度和循环寿命。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["能量密度[无阳极锌金属电池]: 最高水平(水系电池家族中)","性能限制因素[水系锌金属电池]: 界面副反应和阳极-阳极交叉对话","常规策略局限性[单一界面]: 无法解决系统性问题"]},{"i":38384,"as":"针对结晶过程过快限制有效手性诱导的难题，研究提出了一种预交联网络介导的双重交换策略，用于构建β-酮烯胺连接的共价有机框架。该方法首先将单体固定在非晶亚胺预交联网络中，通过同步的胺和醛交换双重交换过程进行结晶，有效延缓了反应动力学并延长了手性诱导窗口。该策略成功在COFs中实现了放大的手性光学活性和解耦的多级手性构建。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["策略机制[β-酮烯胺共价有机框架合成]: 预交联网络介导的双重交换","手性响应[结晶共价有机框架]: 增强的手性光学活性和解耦的多级手性"]},{"i":38385,"as":"针对锂金属阳极由于聚合物涂层开裂和无机组分脱落导致的人工固体电解质界面（ASEIs）保护性能退化的问题，研究开发了一种动态交联含氟聚合物（DCF）人造界面。该界面由尿苷嘧啶酮交联的聚丙烯酸三氟乙酯构成，其可逆四重氢键实现了聚合物网络的快速自修复和界面裂缝的有效闭合。同时，其富含氟的成分能够持续补充无机SEI组分，从而稳定锂金属阳极。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["人造固体电解质界面[锂金属阳极稳定]: 动态交联氟聚合物","自修复机制[聚合物涂层]: 自发聚合物裂纹愈合","界面补充[无机SEI成分]: 循环过程中的持续补充"]},{"i":38386,"as":"研究报道了一种由B(C6F5)3催化的氢化硅烷化脱氧聚合新策略，用于合成具有多功能结构的聚硅氧烷。在该反应过程中，聚醚和聚酯等含氧聚合物同时被降解并升级转化为烷烃，实现了废弃塑料的可持续升级回收。聚合物的空间位阻、溶解度以及反应条件直接影响硅氧键的构建效率和碳氧键的断裂程度，为复杂聚硅氧烷的合成和塑料循环利用提供了新途径。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["催化剂[聚硅氧烷合成]: B(C6F5)3","反应类型[脱氧及聚合物升级]: 催化氢化硅烷化脱氧"]},{"i":38387,"as":"研究提出了一种在FAPbBr3钙钛矿光催化系统中利用乙醛实现高效制氢和乙酸合成的工艺。针对光催化溴化氢（HBr）分解中溴产物积累导致反应动力学迟缓的问题，引入乙醛作为稳定且强还原剂。通过使用暴露出(100)和(111)晶面的铂单原子修饰的FAPbBr3钙钛矿，实现了高性能的氢气析出，同时将乙醛氧化升级为高附加值的乙酸。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["能量势垒[溴化氢氧化反应]: 1.09 V (vs NHE)","还原剂[钙钛矿饱和HBr体系]: 乙醛"]},{"i":38388,"as":"研究提出了一种由聚合动力学介导的策略，通过空间调节拓扑缠结和链间相互作用，实现了具有高对比度的水凝胶三维自变形。该方法利用聚合过程中链增长与质量传递之间的动力学竞争。与快速聚合不同，慢速聚合允许未反应单体大量向内扩散并形成互穿聚合物网络，从而产生高度缠结且溶胀率截然不同的局部区域，显著提升了自变形水凝胶的形态复杂性和功能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["调控机制[水凝胶3D自变形]: 聚合动力学介导的拓扑缠结","各向异性网络[水凝胶]: 空间编程的高对比度溶胀梯度"]},{"i":38389,"as":"为解决有机太阳能电池中背靠背二聚体受体分子间相互作用弱和堆积不良的问题，研究采用不对称端基策略，开发了一种新型不对称二聚体受体DQx-FCl。打破DQx-FCl的结构对称性改变了分子的静电表面电势，从而增强了分子间的π-π相互作用。同时，这种不对称设计减少了单线态激发态中电子和空穴的重叠，促进了电荷分离，有效提升了高效可拉伸有机太阳能电池的性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["分子结构[有机太阳能电池受体]: 不对称封端二聚体(DQx-FCl)","电荷传输通道[二聚体受体]: 三维(3D)传输"]},{"i":38390,"as":"研究使用结构和位点确定的分子模型催化剂（一系列酞菁钴CoPc衍生物）作为测试平台，揭示了电子自旋状态是主导氧还原反应（ORR）选择性的决定性因素。实验发现，Co的自旋状态与ORR生成过氧化氢（H2O2）的选择性之间存在明确的关联。该研究阐明了自旋状态在调控电催化氧还原为过氧化氢中的核心机制。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["决定因素[氧气电还原为过氧化氢(ORR)选择性]: 电子自旋态"]},{"i":38391,"as":"针对金属有机框架（MOF）光催化剂中存在的体相电荷严重复合和表面活性位点不足的核心挑战，本研究创新性地构建了界面供体-受体（D-A）系统。通过纳米约束、光解、重捕获和重排的自优化过程，具有不同配位环境的PtL受体通过酰胺键锚定在NH2-MIL-125上。这些受体不仅能在光照下发生自激发，还能作为电子受体捕获并汇聚MOF主体提供的电子，实现了协同自激发与外部电荷利用的高效光催化析氢。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["供体-受体系统[MOF光催化剂]: 界面D-A体系","活性位点[MIL-125锚定]: 配位环境不同的PtL受体"]},{"i":38392,"as":"研究利用包含469次扫描的静息态功能磁共振成像数据集，探讨了受试者在扫描仪内的内心体验对功能连接（FC）测量的直接影响。研究通过回顾性经验注释发现，扫描过程中的内在体验（即受试者的想法和感受）的总结性描述具有跨次可重复性和受试者特异性，表现出类似特质的特征。研究表明，在识别临床人群功能连接异常模式时，必须考虑受试者内在体验的系统性差异，以减少解释的不确定性。","scd":null,"kp":[]},{"i":38393,"as":"研究揭示了下丘脑视上核（SON）的精氨酸加压素（AVP）神经元是驱动雄性小鼠衰老相关生理稳态失调的关键机制。单核RNA测序显示，Avp是随年龄增长上调幅度最大的神经元转录本之一。衰老的SONAVP神经元体积增大且兴奋性高度活跃。化学遗传学激活年轻小鼠的SONAVP神经元重现了低体温、能量消耗减少和饮水受抑等衰老表型；而在衰老小鼠的SON中敲低Avp，则有效恢复了其水平衡并部分改善了体温调节。","scd":null,"kp":["神经元类型[雄性小鼠衰老相关水平衡和体温调节缺陷]: 视上下丘脑精氨酸加压素(AVP)神经元","转录特征[衰老SONAVP神经元]: Avp为上调最显著的神经元转录本之一","细胞特征[衰老SONAVP神经元]: 体积增大且兴奋性增强"]},{"i":38394,"as":"为解决无细胞系统mRNA表达量低无法进行RNA测序的问题，研究结合贝叶斯优化和自动化高通量实验开发了主动学习工作流，在160万种缓冲液组合中筛选出最佳的mRNA优化缓冲液（产量提升20倍）和权衡缓冲液（产量提升13倍且维持蛋白生产）。利用直接RNA-seq技术，研究对无细胞系统中的T7噬菌体转录组进行了分析，并与纯化的T7-RNAP转录系统及噬菌体感染细菌系统进行了对比，揭示了渐进的基因组调控层次。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":8.0,"t":6.0},"kp":["空间探索范围[无细胞系统缓冲液]: 160万种成分","实验测试规模[高通量验证]: 653种成分","mRNA表达水平[优化后缓冲液]: 提升20倍"]},{"i":38395,"as":"研究发现复合蛋白（Cpx）在不存在突触结合蛋白的情况下，依然能够独立调节胞吐作用。在脂肪细胞中由激素触发、自然缺乏Syt的葡萄糖转运蛋白胞吐途径中，Cpx作为纯粹的正向调节因子发挥作用，在不影响基础融合的情况下加速了诱发阶段的胞吐。机制上，这种独立于Syt的调节活性依赖于Cpx的中心螺旋结构。该发现证明了Cpx在进化上具有比Syt更古老的独立调控功能。","scd":null,"kp":["关键特征[复合蛋白(Cpx)调节胞吐作用]: 具有不依赖于突触结合蛋白的原始独立功能"]},{"i":38396,"as":"为解决全基因组关联研究（GWAS）中祖先群体不平衡导致的单一种族多基因风险评分（PRS）在非欧洲人群中准确性受限的问题，研究开展了涵盖76,953名病例和1,886,372名对照的肺癌多祖先GWAS荟萃分析。研究利用PRS-CSx方法开发了优于现有32种PRS的多祖先肺癌PRS（PRSMA），并结合CatBoost算法整合32个跨性状PRS，成功构建了具备更高预测能力的多性状PRS（PRSMT）。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":9.0,"t":6.0},"kp":["全基因组显著基因座[肺癌多祖先多性状GWAS荟萃分析]: 87个条件独立基因座(含2个未报告的细胞遗传学带)","样本量[肺癌多祖先GWAS荟萃分析]: 76953个病例和1886372个对照","评估方法[多祖先多基因风险评分]: 使用PRS-CSx方法构建多祖先PRS(PRSMA)"]},{"i":38397,"as":"研究提出了一种名为电催化原电池的电化学能量转换新范式。该技术能够利用可再生和废弃原料，在实现化学物质自发合成的同时协同产生电能。该技术重新定义了电化学能量转换的过程。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":4.0,"t":6.0},"kp":["电催化原电池[反应机制]: 自发协同生产化学品和电力"]},{"i":38398,"as":"研究开发了两种泛TEAD转录因子抑制剂GNE-8025及其体内脑渗透衍生物GNE-2181。这两种小分子化合物能够与脂质口袋中的保守半胱氨酸发生共价结合，阻断致癌共调节因子YAP和TAZ的活性。实验表明，这两种抑制剂在体内和体外均能显著抑制YAP驱动的肿瘤细胞生长。此外，GNE-8025能显著增强MAPK通路抑制剂和KRASG12C抑制剂的疗效，且GNE-2181能在体内有效抑制颅内肿瘤模型的生长。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["抑制剂靶点[共价泛TEAD抑制剂]: 结合于脂质口袋中保守的半胱氨酸","抑制剂类型[泛TEAD抑制剂]: GNE-8025及其脑穿透性衍生物GNE-2181","药效[YAP驱动的肿瘤细胞]: 表现出体外生长抑制作用"]},{"i":38399,"as":"研究报道了使用个性化噬菌体疗法成功治疗一例多重耐药、无法手术且常规抗生素和多次外科治疗均告失败的铜绿假单胞菌假体关节感染病例。在长达两年的治疗期内，仅采用间歇性噬菌体治疗（不使用抗生素）实现了感染的临床消退，尽管未达到微生物学上的彻底根除。噬菌体疗法主要通过改变细菌的毒力特性来控制感染，为多重耐药细菌引发的医疗植入物感染提供了新的干预途径。","scd":{"b":6.0,"i":4.0,"r":8.0,"d":5.0,"t":6.0},"kp":["[多重耐药铜绿假单胞菌慢性抑制性假体关节感染]: 采用个性化噬菌体疗法成功治疗"]},{"i":38400,"as":"脑型疟疾（CM）由疟原虫感染引起，其病理机制由以脾脏为中心的体液自身免疫回路驱动。蛋白质组学分析显示，感染的红细胞富含宿主源性抗原CD36，会诱导产生抗CD36自身抗体。这些抗体虽能清除感染红细胞，也会靶向其他表达CD36的细胞，导致血小板减少、内皮损伤和巨噬细胞激活，放大系统性炎症。在机制上，疟原虫感染通过CCL2-CCR2轴招募Ly6c+Glut1hi巨噬细胞至脾脏。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":6.0},"kp":["关键抗原[脑型疟疾系统性自身免疫样病理学]: 感染红细胞中富集的宿主源性CD36抗原","致病机制[脑型疟疾]: 脾脏巨噬细胞-B细胞轴驱动产生抗CD36自身抗体并靶向攻击"]},{"i":38401,"as":"纹状体中的纹状体区室控制皮层向多巴胺神经元的输入，构成决策、学习和运动的基础。多巴胺信号与奖励预测误差（RPE）相关，但许多响应与RPE不一致。研究证明，这种表观RPE相关性在数学上源于行动策略的信息增益（Policy-IG）。Policy-IG用于量化新到达的信息如何改变选择。在简单的奖励任务中，策略信息增益表现出显著的相关性。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":5.0,"t":6.0},"kp":["多巴胺信号响应[非奖励预测误差任务(如高成本、新奇、厌恶刺激、实时运动引导)]: 不符合RPE(奖励预测误差)规律"]},{"i":38402,"as":"视网膜色素变性（RP）是最常见的遗传性视网膜变性疾病，表现为光感受器和视网膜色素上皮（RPE）的进行性丧失。单细胞RNA测序、透射电镜和酶联免疫吸附测定表明，RP大鼠的光感受器和RPE细胞中线粒体异常，且烟酰胺腺嘌呤二核苷酸（NAD+）代谢水平下降。这证实线粒体功能障碍和NAD+代谢降低与RP的发病机制和视网膜脆弱性密切相关。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":5.0,"t":6.0},"kp":["线粒体功能障碍[视网膜色素变性(RP)等神经退行性疾病]: 疾病始动因素"]},{"i":38403,"as":"细胞外铁蛋白水平升高与急性呼吸窘迫综合征（ARDS）的不良预后相关。ARDS患者及高氧诱导的急性肺损伤小鼠模型的血清、血液单核细胞和肺泡巨噬细胞中铁蛋白重链（FTH1）和轻链（FTL）显著富集。髓系特异性敲除FTH1可减轻肺损伤，减少巨噬细胞铁死亡，改变气道炎症反应，降低细胞外铁水平并引起FTL细胞外铁蛋白的补偿性分泌。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["细胞外铁蛋白(ex-ferritin)水平[急性呼吸窘迫综合征(ARDS)患者血清]: 显著升高","血清/单细胞/肺泡巨噬细胞中的FTH1和FTL[急性呼吸窘迫综合征(ARDS)]: 显著富集"]},{"i":38404,"as":"术后硬膜外纤维化（EF）缺乏有效的靶向治疗方法。椎板切除术后患者的手术部位富集FAP+成纤维细胞。研究开发出一种 decorated 双特异性抗体细胞外囊泡，能够重定向内源性T细胞以原位清除FAP+成纤维细胞。在临床前模型中，该囊泡选择性清除病理性成纤维细胞，减少纤维化胶原积累，有效预防术后硬膜外纤维化，且在测试条件下未检测到全身毒性。单细胞RNA测序表明FAP+成纤维细胞是一个转录独立的亚群。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":6.0,"t":6.0},"kp":["双特异性抗体装饰的细胞外囊泡[预防术后硬膜外纤维化]: 重定向内源性T细胞以原位消除FAP+成纤维细胞"]},{"i":38405,"as":"人类钠依赖性多维生素转运蛋白（SMVT）介导生物素、泛酸和硫辛酸等重要代谢因子的细胞摄取，其功能障碍与神经疾病、代谢异常和癌症相关。研究利用冷冻电子显微镜解析了SMVT在封闭、向外开放和向内开放三种构象下的结构。这些结构捕获了完整的运输周期，揭示了一个位于弯曲跨膜螺旋（TM1）附近的保守底物结合口袋，底物的羧基被静电锚定，特定化学部分与极性相互作用。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":6.0},"kp":["人类SMVT(SLC5A6)底物[细胞摄取]: 生物素、泛酸和硫辛酸等必需代谢辅因子","构象状态[冷冻电镜下的人类SMVT结构]: 封闭、向外开放和向内开放三种状态"]},{"i":38406,"as":"光系统II（PSII）天线中过剩的激发能会对光合器造成损害。非光化学猝灭（NPQ）作为一种反馈机制，可将多余的激发能以热能形式安全耗散。研究对缺乏LHCII三聚体和所有外周天线的拟南芥天线突变体进行了时间分辨荧光测量。结合稳态荧光实验结果，研究定量描述了拟南芥中不同PSII超复合体区室对非光化学猝灭的具体贡献程度。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[非光化学猝灭(NPQ)]: 在高光强度下作为反馈机制诱导猝灭剂形成，将PSII天线中过剩的激发能以热能形式安全耗散"]},{"i":38407,"as":"同源六倍体Tripidium arundinaceum（海南92-105，2n=6x=60）具有极强的抗逆性。研究发布了其高质量的单倍型分型参考基因组。该物种约在131万年前起源于二倍体祖先，在多倍化后经历了两次主要的长末端重复逆转录转座子爆发。系统发育分析表明，甘蔗与双色高粱的亲缘关系比与T. arundinaceum更近，表明这两个谱系的多倍化是独立发生的。群体基因组学分析揭示了其适应性进化特征。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["染色体倍性[同源六倍体Tripidium arundinaceum]: 2n = 6x = 60","起源时间[二倍体祖先]: 约131万年前","基因组特征[Tripidium arundinaceum]: 具有高抗逆性且含有来自两个主要重复序列的丰富片段"]},{"i":38408,"as":"细胞在应激反应中会形成突起进行环境探索和引导迁移。通过名为ReGenT-seq的筛选方法，研究发现Cbx3是表皮祖细胞突起形成的关键决定因素。CBX3除了在细胞核内发挥作用外，还具有细胞质“兼职”功能，控制特定mRNA在迁移的表皮祖细胞极化突起以及鳞状细胞癌细胞的侵袭伪足中的亚细胞定位。这种CBX3依赖的mRNA运输促进了局部微型细胞质的建立，从而实现应激诱导的细胞激活。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":4.0,"t":5.0},"kp":["Cbx3[控制表皮祖细胞激活与突起形成]: 关键决定因素","高通量基因筛选方法[研究染色质因子]: ReGenT-seq"]},{"i":38409,"as":"SARS-CoV-2的免疫逃逸变异株凸显了开发变异特异性疫苗的需求，但先前的病毒暴露造成的免疫印迹限制了特异性抗体的产生。研究评估了在初始接种武汉-1刺突蛋白mRNA或黑猩猩腺病毒载体疫苗的雌性小鼠中，使用奥密克戎匹配疫苗进行加强的策略。改变肌肉注射部位对变异特异性血清抗体反应影响不大；但增加加强针的抗原剂量、进行重复接种以及鼻内接种，均可增强针对变异株的特异性反应。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["初始免疫印迹[先前的SARS-CoV-2暴露]: 限制了变异特异性抗体的生成"]},{"i":38410,"as":"研究基于包含846个森林流域的全球森林生物多样性计划数据集及遥感产品，探讨了森林树种丰富度对流域生态多功能性的影响。评估指标包括碳汇、碳储存、供水、水文调节和土壤保持。结果发现，在考虑这些关键生态功能时，流域的生态多功能性与森林树种丰富度之间始终呈现正相关关系。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[流域生态多功能性]: 随着森林树种丰富度的增加而增强（涉及碳汇、碳储、供水和水源调节等多重生态功能）"]},{"i":38411,"as":"低维材料表现出由纳米级限域和量子效应引发的奇异特性。研究将稀土氯化物封装在单壁碳纳米管内，形成了包含有序一维原子纳米线的稳定LnCl3@SWCNTs杂化物。通过结合扫描透射电子显微镜、反应分子动力学和密度泛函理论，提出了一种对称引导的结构筛选策略。该策略成功解析了受限的一维材料局部原子结构，克服了长程周期性受限时传统晶体学方法的局限。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[受限一维材料局部原子结构解析]: 结合扫描透射电子显微镜与对称性引导筛选策略"]},{"i":38412,"as":"植被恢复力是指植被在外界干扰后的恢复速度。研究综合气候、地形、岩性、土地覆盖等数据集，评估了全球山脉中岩石圈和构造对植被恢复力的调节作用。植被类型和温度主导了全球模式（恢复力从高到低依次为树木、草本、灌木），解释了86%的空间变异性。在消除气候和人为因素影响后，各植被类型的恢复力受到岩石圈途径的强烈调节。树木的恢复力在特定岩石类型中达到峰值。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[植被恢复力调节]: 岩石圈（岩性与构造）作为全球山地系统的自下而上调节器，影响植被在受到外部扰动后的恢复速度"]},{"i":38413,"as":"研究在Quantinuum的H1量子计算机上实验探测和表征了开放量子系统中的混合态相位。以临界横场伊辛模型为例，使用两种度量指标：Rényi相关器和量子纠错码的解码保真度。首先，利用阴影层析成像提取了两种不同退相干噪声通道下的Rényi相关器，观察到衰减速度的差异。其次，研究评估了相关量子误差校正码的变分解码性能，证明了这两种指标在探测混合态相位特征中的有效性。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":5.0,"t":5.0},"kp":["[混合态相位探测]: 在Quantinuum H1量子计算机上实验利用Renyi相关器和量子纠错码的变分解码性能进行表征"]},{"i":38414,"as":"气候变暖加速了青藏高原永久冻土的突然融化和碳排放。研究综合了4728次退缩性融滑（RTS）事件和1862次原位测量，估算到2100年RTS易发区面积将比2022年扩大17-19%。与对照区相比，塌陷区的生态系统呼吸速率降低了14.4%，而甲烷释放速率增加了20.0%。2016年至2022年间，与RTS扩张相关的二氧化碳和甲烷总释放量增加了1.1倍。","scd":{"b":5.0,"i":4.0,"r":8.0,"d":9.0,"t":7.0},"kp":["研究样本量[青藏高原退化融滑塌(RTSs)]: 4728起RTS事件及1862个原位CO2和CH4测量数据","易损区扩张预测[2100年相对于2022年]: 17–19%"]},{"i":38415,"as":"二维共轭金属有机框架是电致变色器件的新兴平台，但受限于颜色单调且机制不清。研究提出金属中心电子亲和力机制对电致变色性能至关重要。通过无监督机器学习筛选二价金属-儿茶酚（CAT）系统，确定了锌、镍和铜为最优候选。这三种系统均表现出从绿色到蓝色再到紫色的多色转变。Zn-CAT-1和Ni-CAT-1的切换速度（4.8/5.4秒）比Cu-CAT-1（14.4秒）快三倍，且着色效率更高。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[多色电致变色机制]: 金属中心电子亲和力机制对二维共轭金属有机框架的电致变色性能起关键调节作用","筛选方法[二价金属-儿茶酚体系]: 采用无监督机器学习进行材料筛选"]},{"i":38416,"as":"准确预测分子性质对化学和药物发现至关重要。研究提出了一种名为双图变压器（DGT）的自注意力架构，通过联合建模原子图和化学键图来实现全面的分子编码。DGT在其自注意力模块中融合了原子与化学键特征、图拓扑结构以及立体几何信息。在多项分子性质预测基准数据集中，DGT的表现显著优于当前最先进的方法，展现了双图表示在性能提升中的关键贡献。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["[分子特性预测模型]: 提出双图变压器(DGT)自注意力架构，联合建模原子图和化学键图以实现全面的分子编码"]},{"i":38417,"as":"序列定义的寡聚体在数据存储、认证和防伪方面具有应用潜力，但其受限于规模小、热稳定性差及分析方法复杂。研究引入了一种基于非生物序列定义的低聚酰胺的分子标签策略。这些寡聚酰胺可以以超低浓度掺入到真实的塑料材料中。该策略作为高度稳健的分子信息载体，克服了以往热弹性差的问题，成功实现了塑料材料的可追溯性。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[塑料分子标签]: 开发基于非生物序列定义的低聚酰胺的分子标签策略，以超低浓度掺入以实现材料可追溯性"]},{"i":38418,"as":"研究从信息论角度探究了量子系综克隆的基本定律，建立了一个针对任意系综的通用不可克隆定理。该定理指出，即使假设系综的纯化存在多个副本，量子系综也无法被克隆。这一基本定律阐明了非线性性质测量的局限性，为现代量子物理中控制个体轨迹量子系统、研究非平衡现象（如深度热化和测量诱导纠缠）面临的核心挑战提供了理论依据。","scd":{"b":8.0,"i":1.0,"r":5.0,"d":4.0,"t":4.0},"kp":["非线性性质测量[量子系综表征的核心挑战]: 等同于细粒度克隆"]},{"i":38419,"as":"将高密度聚乙烯废料转化为芳烃原料在无贵金属体系中面临巨大挑战。研究开发了一种蒸汽辅助合成的沸石（SA-HZSM-5），在260°C下实现了高密度聚乙烯转化为芳烃，转化率和选择性分别高达85.4%和49.2%，超越了Ru-HZSM-5等贵金属催化剂。生成的芳烃主要由有价值的单环芳烃组成（约占85%）。该合成方法赋予了特定的路易斯和布朗斯特酸位点分布，通过双位点吸附机制促进反应。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":8.0,"t":5.0},"kp":["转化率[高密度聚乙烯制芳烃]: 85.4%","选择性[高密度聚乙烯制芳烃]: 49.2%","反应温度[高密度聚乙烯制芳烃]: 260 °C","催化剂[无贵金属体系高密度聚乙烯转化]: SA-HZSM-5（蒸汽辅助结晶合成的沸石）","[性能对比]: 优于相同条件下的Ru-HZSM-5等贵金属催化剂"]},{"i":38420,"as":"研究团队实验探究了从排斥态淬火到不稳定吸引态的简并准一维玻色气体的一阶和二阶相干性。通过原位密度和物质波干涉成像监测发现，系统展现出相位相干的密度波演化。这一动态演化特征与此前在吸引相互作用中观察到的经典孤子 Train 明显区分开来，为非平衡量子多体物理系统中的多体相干性探测提供了直接实验证据。","scd":{"b":8.0,"i":1.0,"r":5.0,"d":4.0,"t":4.0},"kp":["相干性探测[动态不稳定状态下的简并准一维玻色气体]: 一阶和二阶相干性"]},{"i":38421,"as":"研究提出了一种利用纳米晶体中多电子激发产生的时空受限热电子，实现金属三维纳米打印的新技术。传统的多光子聚合技术难以应用于金属材料，因为金属形成过程中的能量驱动反应难以在空间上精确局域化，导致分辨率受损。该技术突破了这一局限，成功实现了具有极高深度和横向分辨率的三维金属纳米结构打印。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["多电子激发[纳米晶体中产生时空受限的热电子]: 金属3D纳米打印驱动力"]},{"i":38422,"as":"研究提出了一种用于可拉伸射频电子器件的双端口多向应变不敏感天线（DP-MSiA）。可穿戴设备中的天线在自然运动中会承受多向面内应变，导致失谐。该研究建立了系统性的方向机械-电磁分析框架，设计出的天线在2.45 GHz频率下、承受高达45%的多向面内应变时，谐振频率偏移始终小于或等于40 MHz，解决了传统设计方向受限及辐射性能受损的问题。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[可拉伸射频电子器件]: 多向应变不敏感"]},{"i":38423,"as":"研究提出利用介电超表面对的互补色散工程，实现了对宽带辐射传热的有效抑制。传统金属反射体或常规热光子方法受限于材料兼容性或Bode-Fano极限。研究人员通过随机梯度下降（SGD）优化算法，共同设计了非周期分布的布拉格反射镜（DBR）对，使其通带在目标热波段内发生刻意错位。该方法在极小的厚度和制造成本下实现了超越传统方法局限的宽带热解耦。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["辐射传热抑制策略[介电超表面对]: 互补色散工程"]},{"i":38424,"as":"研究通过调整镧系元素组成和壳层沉积速率，在掺镧系元素核-壳-壳纳米晶格中实现了对界面晶格应变的可控调节。研究证实，晶格失配主导了镧系元素跨异质界面的迁移，进而决定了晶体的生长和光学性质。在六方相NaErF4@NaYF4@NaLnF4纳米晶格中，当晶格失配超过5.1%时，镧系离子可发生长达13纳米的迁移。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["调控机制[纳米结构中长距离镧系元素迁移]: 界面晶格应变调控","材料体系[界面晶格应变调控]: 镧系元素掺杂核-壳-壳纳米晶格"]},{"i":38425,"as":"研究受企鹅羽毛纤毛启发，开发出一种用于激光雷达防护的等离子体纳米复合螺旋结构。该结构通过斜角共沉积技术将铜纳米颗粒嵌入三维二氧化硅纳米螺旋中。铜纳米颗粒提供可见光等离子体加热实现被动防雾，同时在905 nm波长处保持85%以上的透射率；螺旋结构则赋予材料分级粗糙度，使其具有143°接触角的疏水防液性能，从而有效清除大小尺度的水滴干扰。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["材料结构[天气自适应激光雷达除水滴]: 等离子体纳米复合螺旋","清除机制[多尺度水滴]: 被动光热防雾与抗压疏水 repellence（排斥）的耦合","[仿生设计]: 仿企鹅羽毛小支结构"]},{"i":38426,"as":"研究开发了一种界面吡啶鎓-炔点击聚合策略，用于原位制备大面积、无缺陷的自支撑有机聚合物薄膜。以吡啶鎓盐为受体、三羰基苯活化炔烃为供体，在空气-DMSO界面成功制备出厚度可精确调控（数十至数百纳米）的薄膜。该薄膜在连续紫外线照射下表现出优异的光致变色特性，发生100纳米的蓝移和5倍的荧光增强，并伴随自由基薄膜的形成，可用于视觉传感领域。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["合成方法[吡啶鎓-炔薄膜]: 界面点击聚合策略","受体材料[吡啶鎓-炔薄膜]: 吡啶鎓盐 (HDPP-BF4)","给体材料[吡啶鎓-炔薄膜]: 三羰基苯活化炔烃 (TFB-3EK)","薄膜特征[吡啶鎓-炔薄膜]: 均匀、无缺陷的大面积自立式薄膜 (Film #1)，厚度可精准调控"]},{"i":38427,"as":"研究提出了一种用于具身智能主体的受大脑启发的空间认知导航框架（BSC-Nav）。针对现有多模态大语言模型缺乏结构化空间记忆和反应迟钝的问题，该框架构建并利用了结构化空间记忆，将空间知识划分为显著地标、运动路线和地图式表征三种形式。BSC-Nav为主体构建了中心化空间记忆模型，有效提升了智能体在复杂真实环境中的泛化和适应能力。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[具身智能空间认知缺陷]: 现有多模态大语言模型缺乏结构化空间记忆","空间知识形式[受大脑启发的空间智能]: 显著线索地标、运动轨迹路线知识、类地图表征的测量知识"]},{"i":38428,"as":"研究结合古大西洋经向翻转环流（AMOC）敏感指标、多重气候模型和古数据同化技术，重现了AMOC在过去千年的演化历史。研究表明，在公元850至1850年间，AMOC流量呈现出缓慢下降的趋势，减少量约为0.7±0.4 Sv（约4%）。这种减弱主要由爆炸性火山喷发驱动。火山喷发后的头十年AMOC会短暂增强，随后在百年尺度上因深层储冷效应而出现缓慢减弱。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":7.0,"t":5.0},"kp":["AMOC流量变化[小冰河期前]: -0.7±0.4 Sv"]},{"i":38429,"as":"研究针对高硅流纹岩岩浆的起源提出了“动态糊状系统模型”。结合巴西Campo Alegre-Corupá系统的结构分析和热力学建模，发现高硅熔体由上地壳结晶分异形成，残留花岗岩并触发了破火山口喷发。正长岩和暗色正长岩作为其互补的堆晶岩，在相对较低的结晶度（约16-33体积%）下形成。与静态模型不同，该模型证明了大量间隙熔体提取在堆晶岩形成中起到了关键作用。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":7.0,"t":5.0},"kp":["高硅流纹质岩浆SiO₂含量[晶体熔体分离]: ≥ 75 wt.%","高硅熔体成因[动态糊状系统]: 上地壳结晶分异"]},{"i":38430,"as":"针对高温环境下聚合物电介质难以同时保持结构稳定和高储能密度的难题，研究开发了超支化聚合物网络。传统方法中密集的分子链会加剧高温高电场下的电荷转移，而超支化拓扑结构将线性聚合物链转化为坚固的网络以承受热应力，同时扩大了链间距以有效抑制电荷转移。结果表明，该网络在高达250℃的高温下依然展现出巨大的电容能量存储密度。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["能量存储密度[超支化介电聚合物网络在250°C]: 巨大","结构完整性[耐热聚合物设计]: 分子链紧密堆叠","电荷转移[高于200°C高电热场]: 严重","分子结构[聚合物]: 超支化介电聚合物网络"]},{"i":38431,"as":"研究开发了一种用于声源检测的智能声电超材料（IAM）。该器件由独特的三维微架构压电水听器组成，通过几何结构而非化学成分来动态编程压电特性。这种结构的多样性赋予了器件独特的机电响应，使得单一设备能够对海洋野生动物、潜水艇等多种水下目标进行实时的自动化声音定位。该技术推动了下一代声学传感技术的发展。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["压电性编程机制[智能声电超材料]: 通过几何结构而非化学成分动态编程","功能特性[压电水听器]: 实时自动定位多种水下目标的声源"]},{"i":38432,"as":"该研究探讨了材料挤出增材制造过程中分辨率与吞吐量（打印速度）之间的根本冲突。文章通过多尺度路径直观展示了材料特性、传输过程与打印架构之间的相互作用，并强调了新兴的系统级方法在解耦制造精度与打印速度方面的潜力。这些进展为在不同材料和尺度下实现稳健的微结构特征与大尺寸结构的高效一体化打印提供了技术路径。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["工艺特征[材料挤出增材制造]: 分辨率与吞吐量之间存在根本性权衡","制造策略[材料挤出增材制造系统级方法]: 解耦精度与速度以实现跨尺度坚固制造"]},{"i":38433,"as":"研究提出利用离子束沉积（IBD）技术调控涂层的固有微结构，以解决锂金属电池中锂枝晶不可控生长和固体电解质界面（SEI）不稳定的问题。该技术在商业铜箔和锂箔表面构建了具有非晶纳米晶复合微结构的ZnMgSn薄膜。该人工界面层具有极强的亲锂性，显著降低了锂原子的扩散势垒，从而协同实现均匀的锂沉积，有效提升了长周期锂金属电池的性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["界面涂层材料[锂金属电池离子束沉积工艺]: ZnMgSn薄膜","涂层微观结构[ZnMgSn复合薄膜]: 非晶纳米晶复合结构","中间层特性[锂电池定制涂层]: 具有亲锂性和快速动力学特征"]},{"i":38434,"as":"该内容为学术期刊或出版物的主编致辞，可能涉及期刊发展方向、本期亮点或行业致辞。","scd":null,"kp":[]},{"i":38435,"as":"研究使用M3D-K代码，探究了中性束注入（NBI）与离子回旋频率范围（ICRF）波协同加热产生的快离子对鱼骨不稳定性的影响。若忽略这种协同快离子引起的平衡改变，快离子对鱼骨模起稳定作用，且该效应随垂直温度和β值增加而增强；超过阈值时还会激发高频鱼骨分支。若考虑快离子对平衡的改变，在参数较大时起净稳定作用，参数较小时则起失稳作用。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["快离子能量[NBI与ICRF波协同加热]: 显著高于束离子能量","鱼骨模不稳定性影响[忽略平衡改变时的NIS快离子]: 起到稳定作用"]},{"i":38436,"as":"研究使用数值李变换回旋动理学代码，模拟了HL-2A托卡马克中离子内部输运垒（ITB）的动力学，重点分析了漂移波湍流与带状流（ZF）的相互作用。模拟发现了一个维持ITB的自调节循环：离子温度梯度湍流驱动带状流，进而抑制湍流。关键结论是，带状流主要由湍流离子能通量驱动，而非经典模型中的极向雷诺应力。这合理解释了实验中观察到的湍流雷诺应力对径向电场影响微弱的现象。","scd":{"b":7.5,"i":3.0,"r":6.5,"d":6.0,"t":5.0},"kp":["ITB维持机制[HL-2A托卡马克离子内部传输堡]: 离子温度梯度湍流驱动带状流从而抑制湍流的自调节循环","湍流抑制因素[HL-2A等离子体静电湍流]: 带状流"]},{"i":38437,"as":"研究基于HL-2A托卡马克边缘等离子体湍流实验，利用双点测量法和双谱分析，探究了多尺度波动之间的非线性能量传递过程。在湍流系统中观察到了逆能量级联、能量级联和双重级联现象。在边缘等离子体中，能量通常从小尺度（高频区）向大尺度结构（低频区）传递，这种逆能量转移能够触发或强化大尺度结构，为理解等离子体边缘的湍流输运行为提供了全面视角。","scd":{"b":7.0,"i":3.0,"r":6.5,"d":6.5,"t":5.0},"kp":["湍流系统现象[HL-2A托卡马克边缘等离子体]: 逆能量级联、能量级联和双级联","测试方法[边缘等离子体湍流谱数据]: 双点测量法"]},{"i":38438,"as":"研究提出将过氧化氢（H2O2）电合成与阳极升级相集成，实现无需外部供电的自发运行。通过微电极系统的高速成像发现，电解液中的有机底物可作为界面气泡成核调节剂，降低液气表面张力并显著降低产物气泡的成核势垒。这使得阳极反应中微气泡的生成频率大幅提升并减少停滞附着，有效克服了工业级电流密度下的界面动力学瓶颈，实现了节能的电合成过程。","scd":{"b":7.0,"i":4.0,"r":6.5,"d":7.0,"t":5.0},"kp":["工艺特征[H2O2电合成与阳极升级结合]: 自发的无电操作","界面气泡成核调节剂[微电极系统电解液]: 有机基底","气液表面张力[添加有机基底的电解液]: 降低"]},{"i":38439,"as":"研究提出一种基于商业化氯化聚烯烃（PP-Cl）的无合成增韧策略，用于制造本质可拉伸有机光伏器件（IS-OPVs）。该材料成本低、可溶液加工，且与高性能的给受体共混物广泛兼容。在最优负载下，基于PM6:BTP-eC9的刚性器件不仅保持了光电压性能，实现了可重现的能量转换效率提升，同时赋予了器件极高的机械韧性和抗变形能力，解决了高效率与强机械变形性难以兼顾的难题。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["增韧策略[本质可拉伸有机光伏IS-OPVs]: 基于氯化聚烯烃的无合成增韧策略","材料属性[商业化PP-Cl]: 低成本、可扩展、溶液可加工","机械形变能力[IS-OPVs]: 稳健的可拉伸性"]},{"i":38440,"as":"大型螺旋装置（LHD）作为全球最大的超导螺旋系统，配备了先进的加热和诊断工具。研究利用实时汤姆逊散射系统进行电子温度控制，虚拟LHD环境揭示了逃逸的高能氚离子会撞击偏滤器板后部。此外，通过滴落锂颗粒的实时壁面处理技术，改善了体离子能量和粒子输运，同时增强了重杂质输运。研究还在理解湍流驱动的等离子体输运方面取得进展。","scd":{"b":6.0,"i":5.0,"r":6.0,"d":6.5,"t":5.0},"kp":["温度控制方法[大型螺旋装置LHD电子温度]: 使用实时汤姆逊散射系统和实时预测代码进行数据同化","高能氚离子行为[LHD逃逸高能氚离子]: 虚拟环境可视化显示其撞击偏滤器板背面"]},{"i":38441,"as":"斑马鱼少突胶质细胞通过表达抑制性突触后支架蛋白Gephyrin（Gphn），介导特定轴突类的选择性髓鞘化。Gphn在GABA能和甘氨酸能轴突的髓鞘中显著富集。在Gphnb缺陷的幼体少突胶质细胞中，髓鞘鞘的形成与生长受到直接影响。该机制揭示了突触后蛋白在协调特定类型轴突髓鞘形成中的关键作用。","scd":{"b":6.5,"i":1.5,"r":5.0,"d":5.0,"t":4.0},"kp":["髓鞘化调控机制[GABA能轴突]: 利用突触后蛋白Gephyrin限制髓鞘生长"]},{"i":38442,"as":"研究人员基于一维碲纳米线与二维纳米片的互补集成，提出了一种智能偏振计算范式。该异质结构利用本征光学各向异性及偏置调制下相反的二次谐波产生行为，实现了信息的协同处理。在信息安全领域，其光学各向异性可作为物理不可克隆函数的熵源构建加密单元；在偏振图像处理中，该机制被用于滤除干涉信号，实现高效的图像处理与计算。","scd":{"b":8.0,"i":3.0,"r":6.5,"d":7.0,"t":5.0},"kp":["集成架构[碲偏振计算]: 低维碲纳米线和纳米片的互补集成","非线性光学特性[碲纳米线与纳米片]: 本征光学各向异性及偏置调制下相反的二次谐波产生行为"]},{"i":38443,"as":"研究人员将特斯拉流体二极管重构为反向特斯拉阀调制的体效应蒸发系统（BEES），以解决液-气界面边界层阻力导致蒸发速率受限的问题。BEES利用结构诱导的涡流气流破坏热质传递边界层，在内部液-气界面解锁极高的蒸发动力学。该系统实现了21.29 kg m−2 h−1的极高蒸发速率，大幅提升了太阳能蒸汽生成和蒸发冷却等工业应用的效率。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[太阳能蒸汽产生与蒸发冷却场景]: 传统蒸发器因液-气界面未解决的边界层阻力导致蒸发速率难以满足实际需求","[高效水蒸发和冷却]: 将Nikola特斯拉流体二极管改造为反向特斯拉阀以调制体效应"]},{"i":38444,"as":"研究提出一种水辅助的离子解锁策略，可从Pb(Zr,Ti)O3/Pt/Mica体系中快速剥离出厘米级的独立式铁电薄膜。计算表明，水诱导钾离子从Mica基底中浸出是关键界面弱化途径，大幅降低了Pt/Mica界面结合能，从而实现裂纹扩展驱动的薄膜剥离。该技术工艺简单且成本低，满足了柔性电子器件对大尺寸、器件级厚度及规模化制造的产业需求。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":7.5,"t":5.0},"kp":["[水辅助离子解锁策略]: 实现厘米级独立式铁电Pb(Zr,Ti)O3薄膜的快速剥离","[牺牲层常规应用]: 阻碍大面积、器件可扩展厚度和低成本的工业化需求"]},{"i":38445,"as":"研究全面调查了富锂锰基正极在硫化物全固态电池中的界面演化机制。研究发现，高电位下不可逆的晶格氧氧化还原会引发严重的硫化物电解质分解，生成多孔含氧副产物，导致界面阻抗增加并阻碍阴离子氧化还原反应。在2.6-2.0V放电区间驱动的副产物还原，可通过掺锂促进界面重构，显著增强电池的电化学性能和循环稳定性。","scd":{"b":7.5,"i":3.5,"r":6.5,"d":7.0,"t":5.0},"kp":["[硫化物全固态电池]: 使用Li6PS5Cl硫化物电解质系统","[富锂锰基正极界面演变]: 高电位下不可逆的晶格氧氧化还原引发严重的界面演化","[晶格氧氧化还原与界面稳定性]: 二者相互作用对发挥富锂正极全部潜能至关重要"]},{"i":38446,"as":"全金属芳香性颠覆了传统芳香性概念，但在锕系元素中较为罕见。研究报道了单电子和双电子三钍原子簇，它们均表现出增强的抗磁性，展示了开壳层和闭壳层的胶体芳香性。研究证实，这些胶体芳香化合物具有非线性磁响应特征，不满足环电流计算的基本假设，为以往实验与计算结果的冲突提供了解释，深化了对金属团簇电磁特性的理解。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":5.0,"t":6.0},"kp":["[全金属Jellium σ-芳香族化合物]: 展现出非线性磁场响应","[单电子三钍超原子团簇]: 表现出增强的抗磁性并引发开壳层Jellium芳香性"]},{"i":38447,"as":"研究设计了一种采用三体异质结结构的有机适应光电晶体管（OTAT），将运动视觉分析与运动物体提取两项功能集成于单一器件中。该器件引入半导体-绝缘体异质结作为光敏渗透通道，在跨越六个数量级的光照强度范围内提供精细的光适应能力。成像实验表明，该器件实现了高对比度的传感器内运动物体提取（高光比达45.3%），性能接近人类视觉系统，满足自动驾驶等高效应用需求。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":5.0,"t":6.0},"kp":["[有机三体异质结适应光电晶体管(OTAT)]: 在单一器件中集成运动分析与移动目标提取功能","[运动视觉应用]: 解决传统传感器任务分离导致的计算和存储需求过高问题","[OTAT结构设计]: 结合了邻近栅极的半导体-绝缘体结构"]},{"i":38448,"as":"研究以金属钨为模型系统，揭示了氢杂质对材料中辐照缺陷演化的影响机制。研究发现，氢在空位团簇内表面的吸附会显著抑制空位与自间隙原子的复合，从而阻碍缺陷的湮灭。其核心机制是氢的吸附通过应力介导作用改变了空位团簇的局部应力场，削弱了其对间隙原子的吸引力。该结论对微电子工业和先进核系统的抗辐照材料设计具有重要指导意义。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":5.0,"t":6.0},"kp":["[金属中间隙空位团簇复合]: 氢改变了缺陷湮灭的关键过程（空位-间隙复合）"]},{"i":38449,"as":"研究人员开发了一种快速、高灵敏度的气相碰撞诱导解折叠（CIU）分析方法，用于工程化人IgG2单克隆抗体的结构-功能预测。该技术揭示了气相蛋白质解折叠特性与hIgG2抗体激动剂活性之间的预测关系。研究证实，通过抗体铰链区的工程化修饰，可以精准调节单克隆抗体的结构-功能关系，为未来生物治疗药物的开发与优化提供了关键技术手段。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[气相展开(CIU)分析]: 快速预测工程化抗体(hIgG2)的结构-功能关系并具备调节灵活性","[hIgG2单克隆抗体]: 其铰链区内的二硫键重排赋予其强效激动剂特性"]},{"i":38450,"as":"石榴电解质（Li7La3Zr2O12）中的晶界偏析严重影响固态电池性能。研究发现，传统烧结过程中Al、Ta和La元素在晶界处发生偏析，导致局部锂耗尽并形成空间电荷层，降低了总离子电导率。同时，晶界处偏析引发的高电子电导率促进了锂金属在晶界边缘的成核，大幅增加了枝晶生成的风险。该研究阐明了晶界偏析的底层机制，为消除有害偏析、开发高性能固态电池提供了方向。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[石榴石Li7La3Zr2O12电解质]: Al、Ta和La元素在常规烧结中于晶界发生偏析","[晶界偏析影响]: 导致局部Li耗尽并产生空间电荷层，严重损害固态电池性能"]},{"i":38451,"as":"中子源具有多色和低亮度的特性，导致现有复合折射透镜和菲涅尔波带片等中子光学器件在多色光束下存在严重的色差，限制了高分辨率中子显微技术的发展。研究成功开发出一种消色差中子透镜，适用于全视场中子显微镜。该透镜克服了多色光束带来的色差物理限制，实现了高效聚焦，显著提升了中子成像的分辨率，为中子材料科学分析提供了重要的硬件支持。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":4.0,"t":5.0},"kp":["[消色差中子透镜]: 克服中子源多色和低亮度的限制，实现优异的材料穿透力和成分敏感性"]},{"i":38452,"as":"研究引入了一种统计过滤器，通过将节点级别的二分网络聚类与保留度数的随机化模型进行基准对比，将节点划分为几何信号节点或度约束噪声节点。在已知真实参数的合成网络中，该过滤器实现了高分类精度并锐化了潜在几何参数的推断。应用于代谢、植物-传粉者相互作用等四个实证系统时，该算法成功提取了紧凑的几何传递性主干网络，有效去除了普遍存在或微弱共现的噪声实体。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":4.0,"t":5.0},"kp":["节点分类[二分网络度保持随机化基准]: 几何(信号)或度约束噪声"]},{"i":38453,"as":"电催化硝酸盐还原制氨受限于缓慢的表面氢迁移过程。研究人员通过在La0.4Sr0.6FeO3-δ钙钛矿上进行电化学还原辅助的选择性锶离子浸出，构建了富含羟基的纳米空腔。该结构利用纳米腔羟基间的分子内氢键，开辟了无势垒的氢转移路径，极大促进了活性氢的生成与跳跃以实现NO3-加氢。实验和理论均证实该机制能高效催化硝酸盐还原为氨，显著提升了反应速率。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[硝酸盐电还原为氨(NITRR)]: 克服表面缓慢的氢迁移这一主要瓶颈，实现高效电还原","[氢转移机制]: 沿富含羟基的纳米腔分子内氢键进行近乎无障碍的分子内氢转移"]},{"i":38454,"as":"研究揭示了平移对称晶格中的波动力学本征执行卷积运算，其色散关系可唯一定义复值卷积核。基于这一通用原理，研究人员在可编程光子合成晶格中构建了极低复杂度的卷积架构。该系统在图像处理方面实现了每秒13.5万亿次操作（TOPS）的高吞吐量多功能处理。卷积核的复数特性还使其能够进行不可逆衍射的光子模拟，为信号处理和光学神经网络的硬件实现提供了新范式。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":4.0,"t":6.0},"kp":["[卷积处理机制]: 揭示平移对称晶格中的波动力学本征执行卷积，并由色散关系定义复数值核，通过波演化构建极低复杂度的卷积架构"]},{"i":38455,"as":"为提升准固态钠金属电池的寿命与安全性，研究提出了一种由超亲钠性离子/电子混合导体构成的人工界面层。该界面层内嵌高电子导电和强Na+吸附能的Na3Sb合金相，提出并实现了“顶部”均匀沉积机制。这种混合导体界面显著加速了界面离子扩散与成核动力学，确保了快速且无枝晶生成的钠阳极剥离/电镀过程，形成光滑致密的沉积层，大幅改善了电池的界面稳定性和循环寿命。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[准固态钠金属电池]: 提出由超亲钠离子/电子混合导体界面促发的表面诱导“顶部”沉积机制","[混合导体界面]: 具有强Na+吸附特性和超高亲钠性"]},{"i":38456,"as":"水系锌离子电池的发展受限于锌负极的界面不稳定性。研究提出一种单体诱导的原位界面工程策略，利用丙烯酰胺单体在锌表面的优先吸附形成局部高浓度区，在电化学循环中协同触发构建了稳定的水合网络界面（HNI）。该界面通过三重协同机制精确调控锌沉积：路易斯酸碱配位提供固定成核位点，动态锚定效应优化了离子分布。该技术从根本上提升了锌负极界面稳定性，实现了超长循环寿命的水系电池。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[水系锌离子电池]: 创新单体诱导原位界面工程策略，构建具有动态负电荷微区的水合网络界面"]},{"i":38457,"as":"","scd":null,"kp":[]},{"i":38458,"as":"蛇纹石化作用产生的极端碱性（pH>11）流体为微生物群落提供了生存环境。研究在阿曼萨麦尔蛇绿岩体系中，提供了极端嗜碱甲烷氧化作用的同位素、地球化学和基因组证据。同位素分析表明，流体混合过程中13CH4的富集无法仅通过非生物过程解释。宏基因组测序揭示了与产甲烷和甲烷氧化相关的基因序列。该研究证实了在极端碱性且富含氢气和甲烷的海洋环境（如土卫二）中存在高效的微生物甲烷消耗过程。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[甲烷氧化环境]: 极端碱性条件 (pH > 11)","[嗜碱甲烷氧化]: 在阿曼萨马伊尔蛇绿岩中鉴定出极端嗜碱甲烷氧化过程"]},{"i":38459,"as":"研究人员利用液态金属辅助策略，直接合成并转移了大面积单晶超薄β-Ga2O3。该薄膜达到了4英寸晶圆级尺寸和7.5纳米的极限厚度，且具备柔性转移能力。基于该材料制备的日盲紫外光电探测器实现了16.3 A W−1的高响应度和极快响应速度。此外，受日晷启发，研究人员利用该探测器开发了高维光电元系统，能够同时探测入射光的方向、强度和空间分布，为短波光电系统集成提供了创新平台。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[单晶氧化镓尺寸]: 4英寸","[超薄β-Ga2O3合成]: 液态金属辅助策略实现直接合成与转移"]},{"i":38460,"as":"","scd":null,"kp":[]},{"i":38461,"as":"研究开发了一种组织粘附水凝胶光纤（TAHOFs），用于解决内脏外周光遗传学中组织粘附力差和光照不稳定的问题。该光纤集成了折射率为1.429的聚(HEMA)光导芯和折射率为1.343的生物粘附包层，通过0.086的折射率差实现高效光限制，传播损耗低至0.534 dB/cm。该结构在30%的拉伸应变下仍能保持空间靶向保真度，并具有11.5 kPa的稳固组织结合力，已成功植入自由活动的生物体内。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":8.0,"t":6.0},"kp":["[水凝胶光纤折射率]: 光导芯 ncore = 1.429 ± 0.004","[水凝胶光纤折射率]: 生物粘附包层 ncladding = 1.343 ± 0.002"]},{"i":38462,"as":"","scd":null,"kp":[]},{"i":38463,"as":"","scd":null,"kp":[]},{"i":38464,"as":"研究通过液相色谱-质谱联用技术对52名宇航员在国际空间站（ISS）任务前、中、后的血浆代谢组进行了纵向分析。结果表明，太空飞行影响了约40种循环代谢化合物。这些代谢变化在宇航员升空后不久即出现，并在着陆后几天内消退。其中，飞行诱导的代谢物变化反映了微重力及太空驻留环境下，人体肠道微生物的蛋白质发酵过程显著增加。","scd":{"b":5.0,"i":4.0,"r":7.0,"d":8.0,"t":5.0},"kp":["[国际空间站宇航员样本量]: n = 52","[太空飞行代谢影响]: 微重力及太空飞行环境显著增加肠道微生物的蛋白质发酵"]},{"i":38465,"as":"研究提出了一种基于扫描光场显微镜的实时稳健自动对焦方法（AFsLF），无需更改硬件即可实现连续多天的持续高速3D成像。该方法利用光场角度测量的固有视差来估计焦平面，在500微米的深度范围内估计误差小于2微米，且计算完成时间仅需0.1秒，速度比现有方法快300倍，有效解决了活体成像中样本振动和组织变形带来的失焦难题。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[扫描光场显微成像]: 提出实时稳健的自动对焦方法，实现长时间高速三维活体成像"]},{"i":38466,"as":"研究对新生儿脐带血和成人血液中的MR1T细胞进行了单细胞RNA测序和TCR库分析。与成人MR1T细胞相比，新生儿MR1T细胞具有更丰富的TCR多样性，但其细胞毒性和促炎基因表达降低，对细菌的识别能力减弱，且与MR1/5-OP-RU的结合力下降。结构分析表明，新生儿MAIT TCR的β链变化减少。这揭示了新生儿抵抗细菌感染能力较低的细胞学机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[新生儿MR1T细胞]: 具有更多样化的TCR库但细菌识别能力较低"]},{"i":38467,"as":"研究报道了拟南芥干胚中积累了组蛋白变体H2B.8，该变体通过形成空间簇结构来塑造3D核空间并维持染色质的高级组织。H2B.8主要组装成异型核小体，富集于常染色质转座子和低表达基因区域，并在种子吸胀过程中调节这些基因的转录激活。水分吸收会触发H2B.8转录水平下降及其从染色质中被驱逐，这一染色质重编程过程不依赖于DNA复制。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[组蛋白变体H2B.8]: 形成空间簇以构建3D核空间并主导染色质高级结构"]},{"i":38468,"as":"研究利用多种单分子技术直接测试了HSV-1起源结合蛋白UL9的DNA环化假说。结果显示，UL9并不能有效地使起源序列oriS发生环化。然而，UL9却能在非起源序列上非常高效地形成大的分子内DNA环和分子间DNA链。这一意想不到的发现修正了关于UL9介导起源环化以促进复制启动的传统观点，揭示了其全新的DNA相互作用机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[HSV-1复制机制]: 起源结合蛋白UL9介导DNA成环以促进基因组复制"]},{"i":38469,"as":"研究针对粘细菌生物勘探开发了高效遗传工具包，构建了稳健的异源表达底盘。研究鉴定了一对源自粘球菌的重组酶MxRecET，能在模式菌株中实现高效基因组编辑。将MxRecET重组工程与转座子相关核酸酶TnpB结合后，可在两周内完成长达200 kb的无缝大片段删除、双基因座串联编辑和灵活的单核苷酸替换等多种基因操作。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[粘细菌基因组编辑工具]: 鉴定出源自粘球菌的重组酶MxRecET"]},{"i":38470,"as":"研究发现，在缺乏功能性BRCA1 BRCT域的小鼠胚胎干细胞中，缺失Shld2或Shld3（而非53bp1）能够赋予细胞对PARP抑制剂的耐药性。与53bp1缺失不同，删除Shld2或Shld3能在复制偶联双链断裂时部分恢复同源重组，减少插入/缺失特征，并促进RAD51的装载。这种不依赖53BP1的功能需要CST复合物，并能对抗残留的BRCA1活性。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[复制偶联双链断裂修复]: 存在不依赖53BP1的Shieldin-BRCA1拮抗作用"]},{"i":38471,"as":"研究证实，雄性小鼠下丘脑室旁核（PVH）中表达一氧化氮合酶1（Nos1）的神经元是控制全身脂肪消耗的关键枢纽。这些神经元约占PVH神经元的30%，通过多突触途径向骨骼肌、棕色和白色脂肪组织传递信号。激活PVH中的Nos1神经元可通过交感神经系统诱导白色脂肪分解和其他外周组织的脂肪氧化，从而增加全身脂肪消耗。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["细胞占比[雄性小鼠PVH神经元中Nos1神经元]: 约30%","[Nos1神经元]: 通过多突触途径传递信号至骨骼肌和棕色脂肪等外周组织以控制全身脂肪消耗"]},{"i":38472,"as":"研究提出了一种基于最优传输的时空轨迹推断方法SOCS，专门用于时间序列空间转录组学数据分析。现有方法在处理空间连续的组织单元（如卵巢滤泡或肾小管）时，常产生无法保持结构完整性的生物学不连贯轨迹。SOCS方法通过保留相邻生物结构在发育过程中的完整性，能够准确推断单细胞分子谱和发育轨迹之间的关系，生成结构连贯的时空轨迹。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[时间序列空间转录组学轨迹推断]: 引入结构约束的最佳传输方法以解决现有轨迹生物不相干的问题"]},{"i":38473,"as":"一项在智利进行的全国性回顾性队列研究涵盖超360万例确诊SARS-CoV-2感染的成人，评估了COVID-19严重程度与结核病发病风险的关联。结果表明，因严重COVID-19住院的患者，其一年内发生结核病的风险是非重症患者的八倍以上。接种SARS-CoV-2疫苗可改变这种关联，未接种疫苗个体的结核病超额风险显著高于已接种者。","scd":{"b":4.0,"i":6.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[严重COVID-19后遗症]: 显著增加结核病发病风险"]},{"i":38474,"as":"一项为期10年的医院感染监测研究对1513株临床分离的耐碳青霉烯类肺炎克雷伯菌（CRKP）进行了全基因组测序。研究鉴定出一种在中国及国际广泛传播的优势亚系ST11-KL64。该亚系在流感高峰期更为常见，携带编码高毒力因子的质粒，但并未增加患者死亡率，而是表现出增强的侵袭力和转移能力。该亚系在侵袭性增强而非致死性上的优势促进了其广泛分布。","scd":{"b":6.5,"i":5.0,"r":7.0,"d":8.0,"t":5.0},"kp":["测序规模[院内CRKP感染监测]: 1513个临床分离株的10年监测与全基因组测序","基因组分析范围[非本地肺炎克雷伯菌]: 60724个公共可用基因组","耐药亚系[广泛传播]: ST11-KL64亚系"]},{"i":38475,"as":"研究揭示了板块构造历史和海洋氧化对深海热液喷口化能自养微生物全球生物地理学的塑造作用。这些微生物群落（特别是厌氧菌）在形成较早的太平洋、北冰洋和地中海中极为丰富，而在晚近形成的、完全含氧的大西洋和印度洋中极为稀少。这一分布模式归因于海洋形成的时代及其与全球氧化还原演化的相互作用，分子氧的毒性和能量源的枯竭共同构成了双重大坝。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["群落丰度[早期起源海洋]: 厌氧等化能自养微生物在太平洋、北冰洋和地中海显著更丰富","群落丰度[晚期形成海洋]: 在大西洋和印度洋显著稀缺"]},{"i":38476,"as":"研究解析了HIV-2病毒感染因子与人类APOBEC3H（A3H）及宿主蛋白CBFβ复合物的冷冻电镜结构。结构显示，A3H通过双链RNA介导形成二聚体，每个A3H单体直接与一个HIV-2 Vif和CBFβ相互作用。这两个关键界面的结合对于A3H的泛素化降解至关重要。值得注意的是，HIV-2 Vif-A3H的结合界面与已知的HIV-1 Vif-A3H复合物界面完全不同。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["复合物结构[HIV-2 Vif拮抗人APOBEC3H]: HIV-2 Vif、人A3H和CBFβ复合物的冷冻电镜结构","结构特征[A3H二聚体]: 由dsRNA介导形成二聚体"]},{"i":38477,"as":"研究为陆地昆虫开发了一款可穿戴“潜水服”，将其转化为两栖半机械机器人。该微型潜水服集成了微型氧气生成模块和柔性防水外壳，能够持续供氧并隔绝周围水分。蟑螂穿戴该潜水服后，可在水下缺氧环境中维持呼吸和运动长达3小时。这一突破扩展了半机械昆虫的操作范围，使其能够跨越水陆两栖环境执行任务。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[机器人昆虫潜水服]: 集成微型氧气生成模块与柔性防水外壳，支持连续供氧及水隔离","[水陆两栖航行时间]: 支持长达数小时"]},{"i":38478,"as":"研究收集了123例出生后十年内的儿童胰腺样本，结合共聚焦显微镜和全玻片多重成像技术，绘制了人类出生后早期内分泌胰腺的发育与成熟图谱。研究构建了包含内分泌细胞类型异质性、细胞丰度、增殖以及胰岛血管化和神经支配的完整模型，精确定义了出生后人类胰岛细胞团形成、形态发生及功能成熟的关键事件和时间线。","scd":{"b":6.0,"i":3.0,"r":8.0,"d":8.0,"t":7.0},"kp":["样本规模[出生后早期内分泌胰腺]: 123个儿童胰腺样本","研究跨度[组织学和功能成熟]: 从出生到出生后前十年的时空变化"]},{"i":38479,"as":"研究开发了一种3D扩散自动编码器，从71,017名英国生物库参与者的时间分辨心脏MRI数据中提取了数百个潜在表型。这些表型具有可重复性和遗传性（遗传度在4%至18%之间），且与心脏代谢特征显著相关。全基因组关联分析确定了42个基因座上的89个显著常见变异（包括7个新基因座）。这些变异通过共享的遗传结构共同影响着心脏表型。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":8.0,"t":7.0},"kp":["[心脏MRI影像表型]: 3D扩散自动编码器提取的隐式表型具有遗传性 (h2 = 4-18%)","[英国生物样本库参与者数]: 71,017"]},{"i":38480,"as":"研究开发了一种钴催化的末端炔烃、酮亚胺和非活化烷基碘化物的不对称三组分自由基还原加成反应。该方法通过多组分自由基途径，高效构建了带有拥挤四取代立体中心的多取代烯丙基胺衍生物。这一催化方案成功解决了有机化学中直接对映选择性合成含有复杂四取代立体中心的无环烯烃的长期难题。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[多组分自由基途径]: 直接对映选择性构建带有空间拥挤的四取代立体中心的多取代无环烯烃","[催化不对称三组分还原加成]: 解决了有机化学中长期未解决的挑战"]},{"i":38481,"as":"研究表明，大气等离子体诱导的还原反应能够产生奇数汞的质量无关分馏（MIF），其特征和幅度与传统的光化学过程显著不同。等离子体反应产生的Δ199Hg跨度为−78‰至+28‰，创下了最负值的Hg-MIF记录。此外，Hg-MIF的符号会随溶液pH值发生反转：当pH值≥3.0时呈现强负值，当pH值≤2.0时呈现正值，这一现象源于等离子体生成物质间的竞争。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":7.0,"t":7.0},"kp":["同位素分馏特征[大气等离子体诱导化学反应]: 产生远大于光化学过程的奇数Hg质量无关分馏(MIF)特征"]},{"i":38482,"as":"作者对探讨奇偶校验-时间对称性及电子电路中异常点的相关研究论文进行勘误更正。","scd":null,"kp":[]},{"i":38483,"as":"该研究提出了一种通过2,3-丁二醇生产生物航空燃料的优化工艺。针对2,3-丁二醇难以与水分离的挑战，研究采用反应萃取技术，利用原位生成的异丁醛将其转化为二氧戊环，从而免除了对外部醛源的需求。技术经济分析和生命周期评估表明，该燃料和化学品生产场景能够实现58%的二氧化碳减排，具备经济与环境双重可行性。","scd":{"b":5.0,"i":4.0,"r":7.0,"d":8.0,"t":7.0},"kp":["分离方法[2,3-丁二醇水溶液]: 反应萃取形成二氧戊环","[异丁醛原位生成]: 消除了对外部醛源的需求，提升经济与环境可行性"]},{"i":38484,"as":"本研究建立并验证了一个理论框架，解释了电池能量与容量两个关键指标在生命周期中发生背离的原因。传统电池健康状态主要通过容量进行监测，但实际应用中能量才是核心指标，两者的背离会导致寿命预测不准确并引发安全隐患。研究证实，这种分歧与特定的降解模式相关，并受电极化学性质、运行机制、动力学以及放电深度等因素的具体影响。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[电池健康状态评估]: 实际应用中能量是关键指标，常因容量与能量指标发散导致寿命预测不准","[理论框架建立]: 将指标发散与特定降解模式关联(涉及电极化学、运行机制、动力学和放电深度)"]},{"i":38485,"as":"研究发现一种卡宾锰(II)配合物能够在141K（溶液中）和112.5K（固态下）发生光诱导激发自旋态捕获。光照可使其定量从低自旋态切换至高自旋态。实验数据外推显示，在77K温度下，该亚稳态高自旋态的寿命可超过100万年。实现超长寿命的关键在于高金属-配体键共价性带来的高重组能。","scd":{"b":7.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["光诱导激发态自旋捕获温度[卡宾锰(II)配合物溶液]: 141 K","光诱导激发态自旋捕获温度[卡宾锰(II)配合物固态]: 112.5 K"]},{"i":38486,"as":"研究展示了一种无金属的活性模板反向合成轮烷的新路线。柔性低聚乙二醇轴能够通过氢键作用加速酰胺键形成，促使大环分子在其周围自组装。该方法用简单构建块合成[2]轮烷的产率高达70%。更长的轴链可实现高级[n]轮烷的迭代组装，例如在八乙烯二醇链上穿入四个大环。其X射线晶体结构揭示了由芳环堆叠和氢键稳定的拥挤螺旋堆叠结构。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[轮烷反向无金属活性模板合成]: 柔性低聚乙二醇轴促进大环围绕其自身形成","产率[[2]轮烷合成]: 最高达70%"]},{"i":38487,"as":"研究采用拓扑合成子方法，通过扩展和环化“反手结”，实现了闭环三叶状聚合物的高产率合成，其具有窄多分散性和可调的拓扑参数。利用相同的构建块，研究制备了化学组成一致的线性、环状和三叶状拓扑异构体。低温超真空扫描隧道显微镜解析了三叶状聚苯乙烯的三种构象异构体（高、中、低对称性），其种群分布受手性影响，直接揭示了聚合物的拓扑-性质关系。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[拓扑合成子方法]: 通过三叶结的扩展与大环化高收率合成闭环三叶状聚合物","[聚合物特性]: 具有窄多分散性且拓扑参数可调"]},{"i":38488,"as":"半硫靛蓝分子马达由可见光驱动旋转，被称为“阳光动力”装置。通过在其分子结构中进行微小的改变，研究人员偶然发现了一种能够生成“超级充电”中间体的机制，该中间体能够有效地存储太阳能量，从而将该分子马达的能量存储潜力转化为现实。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[半硫靛蓝分子马达]: 结构微调产生“超级充电”中间体以储存太阳能量"]},{"i":38489,"as":"《科学进展》发表的文章报道了一种完全可生物吸收的电子绷带。该绷带采用基于MXene的电极，能够直接收集生化能量（葡萄糖发电），并用于恢复糖尿病组织中的伤口边缘电场，从而有效加速糖尿病伤口的修复。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":8.0},"kp":["[基于MXene的生物可吸收绷带]: 收集生化能量并恢复糖尿病组织中的伤口边缘电场"]},{"i":38490,"as":"","scd":null,"kp":[]},{"i":38491,"as":"","scd":null,"kp":[]},{"i":38492,"as":"学者Marisa Chrysochoou和Keivan Stassun提出，人工智能工具可以帮助神经分歧（如自闭症等）学生更好地掌握学术界那些不成文的隐性规则。通过利用AI技术，能够有效协助这些学生顺利驾驭复杂的学术环境，从而为其打开所谓的“隐藏课程”。","scd":null,"kp":["AI工具应用[神经分歧学生]: 帮助学生应对学术界不成文的规则（隐藏课程）"]},{"i":38493,"as":"","scd":null,"kp":[]},{"i":38494,"as":"美国政府正大力推进人工智能和量子科学领域的宏伟计划。负责落实这些目标的科学家Darío Gil深知，许多研究人员对这一大规模的人工智能推进计划持怀疑态度。他目前的工作是呼吁科研界保持开放心态，共同致力于将这些前沿科学雄心转化为现实。","scd":null,"kp":["[美国人工智能与量子技术发展]: 研究人员对大规模推进持怀疑态度，官方呼吁保持开放态度"]},{"i":38495,"as":"","scd":null,"kp":[]},{"i":38496,"as":"菱面体多层石墨烯因其优异的材料质量和栅极可调的强关联效应，成为探索非常规超导的理想平台。研究团队对菱面体四层和五层石墨烯的传输测量证实了一系列纯净极限超导性，并在五层结构中发现了三种不同类型的磁场增强和磁场诱导超导现象。这些超导状态在面对高达8特斯拉的面内磁场时依然保持稳定。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":7.0,"t":8.0},"kp":["[菱面体石墨烯]: 具有优异的材料质量和栅极可调的强关联效应，是探索磁场增强/诱导超导的理想平台"]},{"i":38497,"as":"","scd":null,"kp":[]},{"i":38498,"as":"此前理论认为碘酸盐还原先于硝酸盐还原，但最新研究证实，在两种代表性菌株中，异化碘酸盐还原滞后于硝酸盐还原。功能基因idrABP1P2广泛分布于全球海洋最低氧区（OMZs）发生硝酸盐还原的深度剖面中，且异源表达成功。这表明异化碘酸盐还原微生物（DIRMs）实际栖息于海洋最低氧区，并在碘离子（I−）的产生和积累中发挥关键作用。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":8.0},"kp":["[异化碘酸盐还原微生物]: 碘酸盐(IO3−)还原滞后于硝酸盐(NO3−)还原"]},{"i":38499,"as":"","scd":null,"kp":[]},{"i":38500,"as":"等离子体纳米颗粒阵列是增强纳米尺度光与物质相互作用的多功能平台。研究人员在镜面增强的等离激元晶格中实现了超高品质因数（高Q）的非局部共振。这种高Q值共振对于无标记生物传感、低阈值激光和量子信息处理等光谱选择性应用具有至关重要的意义。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":8.0},"kp":["[镜面增强等离激元晶格]: 展现出超高Q值（品质因子）的非局部共振"]},{"i":38501,"as":"受近期扫描隧道显微镜实验在FeTe0.55Se0.45片中观察到对密度调制（PDM）的启发，研究人员开发了一种朗道理论来阐明其物理起源。该理论通过分析和解释螺旋对称性和滑移对称性，深入揭示了这种特殊对密度调制的形成机制。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":8.0},"kp":["[FeTe0.55Se0.45]: 存在由螺旋和滑移对称性解释的对密度调制现象"]},{"i":38502,"as":"","scd":null,"kp":[]},{"i":38503,"as":"","scd":null,"kp":[]},{"i":38504,"as":"","scd":null,"kp":[]},{"i":38505,"as":"","scd":null,"kp":[]},{"i":38506,"as":"","scd":null,"kp":[]},{"i":38507,"as":"","scd":null,"kp":[]},{"i":38508,"as":"","scd":null,"kp":[]},{"i":38509,"as":"本文研究了过渡金属硫族化物家族（特别是2H-NbSe2和2H-TaS2）在少层极限下的超导性质。尽管此前的隧道测量显示这些材料中存在单一的超导能隙，但该研究通过实验证实了少层两能带超导材料中复杂的超导机制，深化了对超薄极限下二维材料超导特性的理解。相关成果发表于《物理学评论快报》。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":5.0,"t":8.0},"kp":["[2H-NbSe2与2H-TaS2超薄极限]: 隧道测量显示出单超导能隙特征"]},{"i":38510,"as":"","scd":null,"kp":[]},{"i":38511,"as":"本文报道了在全连接、耦合可调的超导量子处理器上对量子姆潘巴效应的观测与调制。量子姆潘巴效应描述了在特定非平衡条件下，温度较高的系统能比温度较低的系统更快地冷却到基态的现象。该研究利用超导量子硬件在微观量子层面证实了这一反常弛豫现象，并展示了对其的主动调制能力。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":4.0,"t":8.0},"kp":["[超导量子处理器]: 实现了全连接、可调耦合架构，成功观测和调制了量子Mpemba效应"]},{"i":38512,"as":"本文报道了在量子处理器上实现由测量和反馈操作驱动的非平衡相变。中途测量和基于测量结果的反馈操作是实现量子纠错的关键硬件要求。当这些操作被整合到量子多体动力学中时，可以在单体和多体自由度上引发新型的非平衡相变。该研究为量子模拟和量子控制提供了新的物理机制。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":4.0,"t":8.0},"kp":["[量子多体动力学]: 线路中途的测量与基于结果的反馈操作可以引发非平衡相变"]},{"i":38513,"as":"","scd":null,"kp":[]},{"i":38514,"as":"本文在马氏体纳米级位移相变合金中观察到了一种史无前例的埃林瓦尔效应。铁弹性合金在相变前会发生模量软化，在马氏体相变完成温度以下表现出正常的冷却硬化现象。然而该研究发现，通过引入马氏体纳米级位移相变，马氏体态可以表现出几乎与温度无关的弹性模量，即优异的埃林瓦尔效应。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[铁弹性合金马氏体相变]: 展现出近乎与温度无关的弹性模量（埃林瓦尔效应）"]},{"i":38515,"as":"本文提出了一种针对异构有限尺寸组件自组装的通用逆向设计框架。该框架利用基于梯度的优化算法反转了解析产率的计算过程，能够精确调控系统以达到设定的平衡产率目标。研究成功设计了从简单二聚体到复杂组件等多种自组装系统，解决了软物质和生物领域中异构系统设计的核心挑战。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":8.0},"kp":["[异构自组装系统]: 建立了基于梯度优化的逆向设计框架，可调控系统达到目标平衡产率"]},{"i":38516,"as":"为解决水系锌离子电池中锌阳极缺乏稳定固体电解质界面（SEI）的挑战，本文提出在电解液中添加Na2TeO3，从而在锌阳极表面原位形成仿生细胞壁状SEI。该界面中无定形的碲基基质能有效适应锌离子传输时的体积变化，嵌入的功能性纳米晶体提升了SEI硬度并提供丰富的离子通道，实现了高性能无枝晶锌电池。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[水系锌离子电池锌阳极]: 引入Na2TeO3电解液添加剂，原位形成具有优异力学和电化学性能的仿生细胞壁状固体电解质界面(SEI)"]},{"i":38517,"as":"为解决水系锌离子电池中凝胶电解质与电极界面接触不良和电荷分布不均导致的问题，本文提出一种面对面电子通道调控策略。通过热压工艺将聚丙烯酰胺凝胶电解质与商用导电碳布集成，加速了电极表面不均匀电荷的移动，促进了电子和离子通道的高效接触，从而有效均化了界面电场，降低了局部电流密度，实现了高可逆的锌电池。","scd":{"b":6.5,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["凝胶电解质改性策略[水系锌离子电池]: 聚丙烯酰胺凝胶电解质与商用导电碳布结合的面对面电子通道调控策略","制备工艺[电子通道调控策略]: 简单且可大规模生产的热压工艺"]},{"i":38518,"as":"受海洋褐藻调节碘元素的启发，本文开发了一种含有褐藻多糖（FUC，一种硫酸化多糖）的藻类水凝胶电解质，用于构建稳定的锌碘电池。FUC中的硫酸基团通过静电排斥作用将多碘化物限制在正极界面，从源头抑制穿梭效应；聚合物网络中的酰胺基团则进一步捕获逃逸的多碘化物。这种协同机制有效抑制了锌枝晶和副反应。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["水凝胶电解质成分[水系锌碘电池]: 聚(N-羟乙基丙烯酰胺)网络与含硫酸基团的岩藻多糖相结合","电解质作用机制[抑制多碘化物穿梭]: 利用硫酸基团介导产生对多碘化物的排斥作用"]},{"i":38519,"as":"本期每日简报主要聚焦于三大前沿科技进展：一是CRISPR技术的下一阶段应用，即通过编辑表观基因组来治疗相关疾病；二是最新诞生的“全球最快超级计算机”；三是关于如何克服生命科学领域面临的重大挑战（如比喻为点球大战）的探讨与分析。","scd":{"b":4.0,"i":3.0,"r":3.0,"d":2.0,"t":7.0},"kp":["技术开发方向[CRISPR技术]: 表观基因组编辑用于疾病治疗"]},{"i":38520,"as":"本文研究了Hedgehog信号通路中的关键G蛋白偶联受体——Smoothened（SMO）的配体激活机制。研究通过分析G蛋白和胆固醇（CHL）配体结合SMO的路径序列，提出了SMO的“G蛋白优先”激活模型：胆固醇先结合失活SMO的富含半胱氨酸结构域，随后G蛋白自发结合形成预偶联复合物。当膜上的Patched蛋白脱落，SMO即可被激活。该机制为理解基底细胞癌等癌症提供了靶点理论基础。","scd":{"b":8.0,"i":1.0,"r":6.0,"d":6.0,"t":5.0},"kp":["激活路径[SMO G蛋白偶联受体]: G蛋白优先结合激活通路"]},{"i":38521,"as":"本文结合大规模生物信息学分析和实验病毒学，评估了SARS-CoV-2弗林蛋白酶切割位点（FCS）的RRAR序列源自小鼠适应型MERS冠状病毒（MERS-MA30）RRVR序列的假说。对超1700万个SARS-CoV-2基因组的分析表明，S:684V（对应RRVR）突变偶发且未成为系统发育基底。反向遗传学实验证实，携带RRVR序列的病毒变体其进入细胞的效率和竞争力均持续降低，否定了这一演化假说。","scd":{"b":6.0,"i":1.0,"r":7.0,"d":8.0,"t":5.0},"kp":["分析样本量[SARS-CoV-2基因组]: 超过1700万"]},{"i":38522,"as":"受自然界形态发生启发，研究提出了可编程形态发生设计框架RDGenCAD，通过将生长规则转化为反应-扩散动力学，生成可直接用于CAD建模的自组织架构。该研究构建了包含12万个结构的数据集，证明尽管几何呈现不规则性，其弹性性能仍具连续可调性。此外，这些不规则架构通过应力区隔化表现出对缺陷的不敏感性与裂纹偏转能力，在强度与韧性上超越传统规则晶格。该成果打破了基于晶胞拼接的传统设计局限，将自组织确立为生成式设计的新原理，为开发高适应性、高韧性的异质建筑材料开辟了新路径。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["形态发生设计框架[建筑材料的可编程形态发生]: RDGenCAD","架构生成机制[形态发生设计框架]: 将可编程生长规则转化为反应-扩散动力学以生成自组织架构"]},{"i":38523,"as":"研究构建了人类屏状体的三维组织学“金标准”模型，并以此系统评估了三个7特斯拉超高场MRI数据集。结果显示，基于MRI的屏状体形态差异主要源于分辨率依赖效应，而非对比度限制。这一发现解释了活体MRI文献中存在巨大且往往难以置信的差异的原因，解决了形态学研究中存在的问题。","scd":{"b":5.0,"i":1.0,"r":7.0,"d":7.0,"t":5.0},"kp":["屏状体表征模型[人类活体MRI研究]: 组织学三维“金标准”模型"]},{"i":38524,"as":"WIP转录因子在陆地植物中高度保守，在被子植物中与根和花发育相关。研究以模式苔藓小立碗藓为对象，剖析了PpWIP1和PpWIP2基因的功能。研究展示了这些基因在调节苔藓配子体和孢子体两个生命周期阶段发育进程中的具体作用，揭示了进化保守基因家族如何伴随不同植物谱系机体计划的多样化。","scd":{"b":5.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":["转录调节因子[苔藓生命周期发育调节]: WIP转录因子，调节两个生命周期阶段的发育进程"]},{"i":38525,"as":"研究引入了一种双人觅食范式，旨在探讨两人共同决策中的风险偏好、妥协及责任归因问题。该范式要求两名参与者共同选择能带来奖励但伴随风险的地点，并评估彼此对共享结果的责任。通过两项研究（包含250名参与者的探索性研究），深入分析了人们在联合决策中妥协的时机与原因及其计算和心理学基础。","scd":{"b":4.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":["风险决策计算机制[二元觅食任务]: 关联妥协行为与责任归因的数学框架"]},{"i":38526,"as":"","scd":null,"kp":[]},{"i":38527,"as":"","scd":null,"kp":[]},{"i":38528,"as":"","scd":null,"kp":[]},{"i":38529,"as":"","scd":null,"kp":[]},{"i":38530,"as":"为理解光合细菌太阳能收集的量子效率，需明确光合膜各复合体之间的功能连接性。研究利用二维电子光谱（2DES）技术，通过在光谱的“第二维度”解析激发能量来区分不同子系统并解开其响应。该方法有效克服了完整细胞在室温下因系统高度复杂性而导致的光谱极度拥挤问题，成功绘制了体内紫色细菌的光捕获能量传递图谱。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["研究核心目标[体内紫色细菌光捕获图]: 揭示完整细胞内各复合物之间的功能连接以理解太阳能收集的量子效率"]},{"i":38531,"as":"","scd":null,"kp":[]},{"i":38532,"as":"","scd":null,"kp":[]},{"i":38533,"as":"","scd":null,"kp":[]},{"i":38534,"as":"","scd":null,"kp":[]},{"i":38535,"as":"","scd":null,"kp":[]},{"i":38536,"as":"","scd":null,"kp":[]},{"i":38537,"as":"研究开发了一种名为RUNA（可逆尿苷腈介导加成）的可逆共价化学技术，通过N3去质子化及与腈离子中间体反应，选择性修饰天然RNA和DNA中的尿苷和胸苷残基。利用膜渗透性不同的试剂，研究成功证实了DNA定位于外泌体表面，揭示了外泌体表面存在DNA分子，解决了其内部核酸分布定位不明确的问题。","scd":{"b":7.5,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["核酸标记化学[RUNA技术]: 可逆尿苷腈介导的加成反应，通过N3去质子化及与腈𬭩离子反应选择性修饰尿苷和胸苷残基","化学标记特性[RNA和DNA标记]: 可逆的、无序列依赖性的共价化学标记"]},{"i":38538,"as":"","scd":null,"kp":[]},{"i":38539,"as":"","scd":null,"kp":[]},{"i":38540,"as":"","scd":null,"kp":[]},{"i":38541,"as":"","scd":null,"kp":[]},{"i":38542,"as":"","scd":null,"kp":[]},{"i":38543,"as":"","scd":null,"kp":[]},{"i":38544,"as":"","scd":null,"kp":[]},{"i":38545,"as":"","scd":null,"kp":[]},{"i":38546,"as":"","scd":null,"kp":[]},{"i":38547,"as":"","scd":null,"kp":[]},{"i":38548,"as":"","scd":null,"kp":[]},{"i":38549,"as":"","scd":null,"kp":[]},{"i":38550,"as":"","scd":null,"kp":[]},{"i":38551,"as":"","scd":null,"kp":[]},{"i":38552,"as":"","scd":null,"kp":[]},{"i":38553,"as":"对比风电与传统化石能源的健康影响，指出风力发电不会危害健康，凸显化石燃料的弊端。","scd":{"b":2.0,"i":3.0,"r":4.0,"d":2.0,"t":4.0},"kp":["[风力发电]: 不会危害健康"]},{"i":38554,"as":"","scd":null,"kp":[]},{"i":38555,"as":"","scd":null,"kp":[]},{"i":38556,"as":"规定火灾产生的烟雾带来全球健康风险，主要源于PM2.5排放。研究开发了一个数学框架，评估规定火灾与减少野火排放之间的权衡。对73个研究点的分析表明，规定火灾产生的排放量极少能被减少的野火排放量抵消。因此，在当前全球大多数条件下，实施规定火灾会增加整体的PM2.5净排放量，且以往研究中关于净排放量减少的报告通常存在误差。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["PM2.5净排放量影响[规定火烧策略]: 规定火烧不太可能减少大多数地点的PM2.5净排放量"]},{"i":38557,"as":"研究利用验证模型，在洛杉矶Palisades地区量化了开放空间植被管理与家庭点火区(HIZ)缓解措施对城市火灾损失的影响。开放空间管理通过减少特定比例的植被密度来模拟间伐和计划燃烧；HIZ缓解涉及强化建筑特征和清除防御空间燃料。研究通过随机和针对性策略，量化了这些干预措施的空间分布对控制火势蔓延边界和减少建成环境损害的有效性。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[城市火灾干预]: 开放空间植被管理与家庭点火区缓解联合管理的空间分布能有效影响火势边界并减少建筑环境损坏"]},{"i":38558,"as":"","scd":null,"kp":[]},{"i":38559,"as":"","scd":null,"kp":[]},{"i":38560,"as":"","scd":null,"kp":[]},{"i":38561,"as":"外周膜蛋白(PMP)通过动态的膜相互作用介导细胞表面信号传导。研究以布鲁顿酪氨酸激酶(BTK)为例，开发了一种天然质谱平台，用于直接研究脂质双分子层介导的PMP招募过程。该平台揭示了BTK的膜招募和激活依赖于一种两步机制。这种机制涉及高亲和力相互作用和微弱、瞬时的低亲和力相互作用，为理解PMP在细胞信号传导中的功能提供了直接的分析方法。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":7.0,"t":5.0},"kp":["膜招募机制[布鲁顿酪氨酸激酶]: 通过高亲和力相互作用或与膜的瞬态低亲和力相互作用分两步进行"]},{"i":38562,"as":"纠正生态学领域引入人工智能的观点，指出当前生态学基础尚不足以支撑AI的全面应用。","scd":null,"kp":[]},{"i":38563,"as":"Junctophilin-2 (JP2) 在产热棕色脂肪组织(BAT)中高表达，营养过剩会使其下调。在脂肪细胞中特异性敲除JP2会加剧冷不耐受和对饮食诱导肥胖的易感性。机制上，缺失JP2的棕色脂肪细胞表现出钙处理功能障碍，基线胞质钙水平升高，去甲肾上腺素诱导的钙瞬变减弱。这表明JP2协调的钙信号体在调节棕色脂肪细胞产热和能量代谢中起着关键作用。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["调控靶点[棕色脂肪细胞产热与能量代谢]: Junctophilin-2 (JP2) 协调的钙信号体","表达变化[营养过剩条件]: 产热棕色脂肪组织(BAT)中的JP2表达下调"]},{"i":38564,"as":"","scd":null,"kp":[]},{"i":38565,"as":"泛北极（北纬60至90度）自然甲烷排放对气候变暖的敏感性缺乏观测约束。长期大气测量显示，由于秋季至冬季的甲烷积累时间（秋季零交叉日期）提前，泛北极甲烷积累呈现早期趋势。这种提前趋势是由7、8、9月气候变暖引起的北极自然甲烷排放增长所解释的。在1998年至2020年期间，甲烷排放的增长率为每年0.14 ± 0.04 Tg。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":8.0,"t":6.0},"kp":["观测区域[泛北极自然甲烷排放]: 60至90°N","关键特征陈述[气候变暖]: 秋季零交叉日期提前趋势反映了北极自然甲烷排放的增长"]},{"i":38566,"as":"","scd":null,"kp":[]},{"i":38567,"as":"神经元由于其有丝分裂后的长寿特性，极易受蛋白质稳态崩溃的影响。研究利用人类兴奋性神经元和小鼠胶质细胞的双物种共培养模型，结合数据非依赖性LC-MS/MS蛋白质组学，量化了细胞类型特异性的蛋白质稳态网络成熟变化。通过监测ATF6、IRE1/XBP1等下游效应蛋白，研究揭示了未折叠蛋白反应(UPR)分支的激活状态和细胞特异性的成熟动力学。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[人类神经元/小鼠神经胶质细胞]: 双物种共培养模型"]},{"i":38568,"as":"食欲素神经元调节能量稳态和动机行为。在转基因大鼠中使用化学遗传学发现，激活食欲素神经元会增加对奖励的动机。光纤光度法和光遗传学操作显示，在动机行为期间食欲素神经元活动呈现动态变化：在预测奖励时活动增加，在收到奖励后活动减少。当发生未获得预期奖励的意外事件时，神经元活动同样表现出增加反应。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[行为与神经元活动关联]: 使用细胞类型特异性光纤测度和光遗传学操作在转基因大鼠中选择性激活/失活食欲素神经元输入","[动机行为机制]: 食欲素神经元活动在动机行为期间编码奖励预测"]},{"i":38569,"as":"在苔原天鹅中鉴定出三种SARS-CoV-2变异株的近乎全长的病毒基因组序列。这些序列被命名为IMCAS_M1、IMCAS_M2和IMCAS_M3。其中，IMCAS_M1和IMCAS_M3在病毒刺突蛋白的受体结合域(RBD)上具有与Beta变异株相同的突变（K417N、E484K、N501Y）；IMCAS_M2则与Gamma变异株具有相同的RBD突变（K417T、E484K、N501Y）。这表明候鸟携带了SARS-CoV-2。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":7.0,"t":6.0},"kp":["[SARS-CoV-2变异株宿主]: 在苔原天鹅中鉴定出三个近乎全长的病毒基因组序列(IMCAS_M1, IMCAS_M2, IMCAS_M3)"]},{"i":38570,"as":"二维过渡金属二硫化物(TMDCs)的相变通常被描述为马氏体过程，但巨大的能量壁垒限制了其实验研究。为解决精确调控材料性质的挑战，研究探讨了二维MoTe2材料中的一维多米诺骨牌相变。这种机制突破了传统相变理论在低维度下所面临的障碍，使得对二维MoTe2材料进行结构编程成为可能。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["相变机制[二维MoTe2材料]: 一维多米诺骨牌式相变"]},{"i":38571,"as":"量子自旋霍尔(QSH)效应是一种二维拓扑相，其边缘态受时间反转对称性保护，具有无耗散特性。由于无需磁场、本征自旋动量锁定以及电可调拓扑结构，QSH状态是超低功耗电子学、自旋电子学和拓扑量子计算的理想平台。然而，目前基于QSH功能的实验实现仍局限于少数材料系统和器件几何形状，且通常在低温和受限长度尺度下运行。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":3.0},"kp":["量子自旋霍尔效应[二维拓扑绝缘体]: 受时间反演对称性保护的无耗散、自旋极化螺旋边缘态","[技术应用潜力]: 适用于超低功耗、超快电子学、自旋电子学和拓扑量子计算"]},{"i":38572,"as":"高熵过渡金属硫化物(HES)是极具潜力的钠离子电池负极材料，但多组分不兼容引发的相分离限制了其性能。研究通过调控元素化学相容性，提出了一种低混合焓策略。该策略成功合成了单相Co-Fe-Ni-Mn-Cr HES固溶体(HES-Cr)，而相容性较差的Co-Fe-Ni-Mn-Mo HES(HES-Mo)则发生相分离。HES-Cr中的电子离域增强了导电性，实现了超高容量和超快动力学的稳定储钠。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["材料体系[钠离子电池负极]: 高熵过渡金属硫化物(HESs)","合成策略[高熵硫化物相工程]: 调节元素化学相容性的低混合焓策略，以解决多组分不兼容导致的相分离问题"]},{"i":38573,"as":"水系锌离子电池因锌枝晶生长和寄生反应面临可逆性差的问题。基于布拉维定律的晶面调控常导致无保护晶面易受寄生反应攻击。研究提出一种解耦电解液设计，结合甲酰胺(FA)共溶剂和特定添加剂，同步实现了晶面选择性织构控制和全局水活性抑制。该策略消除了传统织构策略的权衡问题，制备出高度可逆的(101)织构锌阳极，适用于安时级电池。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["核心条件[水系锌离子电池锌阳极]: 将寄生反应从基于布拉维定律引导的电氧化还原中解耦","关键特征陈述[锌阳极织构]: 具有高度可逆的(101)织构，适用于Ah级电池"]},{"i":38574,"as":"深海极端环境与传感器分离的信号处理导致系统体积庞大、能耗高且延迟大。研究开发了一种神经形态浮栅晶体管(NFT)，集成了电学和光学记忆功能。该器件能够在单一单元内模拟视觉和听觉突触行为，实现视觉-听觉信号的内存双模态处理。在电学性能上，实现了约14微秒的快速开关和10^6的高开关比，为水下实时智能感知系统提供了新方案。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["核心器件[海洋视觉听觉感知神经形态计算]: 神经形态浮栅晶体管(NFT)","[核心条件]: 集成了电学和光学信号，克服了深海极端条件下的分离信号处理导致的系统庞大、高能耗和高延迟问题"]},{"i":38575,"as":"热固性聚氨酯废料难以回收且造成环境问题，再生产品的机械性能固定，应用受限。研究提出一种化学回收策略，通过在聚氨酯中嵌入热触发网络拓扑结构转化开关，将废料转化为智能材料。这种转化开关赋予再生材料按需可编程的机械性能，其模量可实现54倍的提升。该策略实现了聚氨酯废料向具有终端按需可编程特性的智能材料的升级改造。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["回收策略[废旧热固性聚氨酯]: 化学回收将其转化为智能材料","材料特性[转化后智能材料]: 具有最终用户按需可编程特性和适应性应用"]},{"i":38576,"as":"针对血栓性疾病缺乏实时监测技术的问题，研究开发了一种无试剂、可穿戴的电化学检测平台。该平台集成了芯片上的普鲁士蓝(PB)氧化还原换能器、信号关闭型分子印迹聚合物(MIP)层和用于间质液(ISF)采样的生物相容性水凝胶微针(HMN)阵列。该系统能够直接对血栓炎症生物标志物进行电化学检测，实现微创的体内连续监测。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[血栓炎症生物标志物监测]: 通过集成分子印迹聚合物的水凝胶微针实现无试剂、可穿戴电化学实时监测"]},{"i":38577,"as":"倒置钙钛矿太阳能电池中钙钛矿与电子传输层(ETL)之间的界面缺陷是限制其效率和稳定性的瓶颈。研究开发了一种多功能集成聚合物半导体材料P4N-Cl作为界面中间层。聚合物骨架中的羰基、氯原子和sp2-N原子等多种官能团，通过协同配位机制有效钝化钙钛ite界面缺陷，显著抑制非辐射复合。该界面工程实现了倒置钙钛矿太阳能电池的高性能。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":7.0,"t":6.0},"kp":["界面工程材料[倒置钙钛矿太阳能电池]: P4N-Cl共轭聚合物半导体","界面缺陷[钙钛矿与电子传输层之间]: 工业化进程中制约高效率与稳定性的瓶颈"]},{"i":38578,"as":"皮肌炎病理上的干燥皮肤阻碍了使用表面肌电(sEMG)进行非侵入性肌肉无力定量评估。研究通过分子工程开发了一种顺应性神经运动电极接口。该接口具有超软模量（约2.13 kPa）、低阻抗（在1 kHz时约0.9 kΩ）及7天的稳定电保持能力。它能从皮肌炎患者中采集高保真sEMG信号，基线噪声低且信号相关性高，实现了对神经运动信息的稳健分解。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["电极模量[超软神经运动电极]: ~2.13 (单位略)","[干燥皮肤兼容性]: 通过分子工程开发出适用于皮肌炎病理性干燥皮肤的非侵入性共形神经运动电极接口"]},{"i":38579,"as":"为解决无机钙钛矿中卤化物空位缺陷和离子迁移影响光伏性能的问题，引入了2,3-二巯基-1-丙磺酸钠（DPS）作为多功能分子螯合钳。与传统单齿钝化剂不同，DPS采用双齿螯合策略，利用其两个巯基与欠配位的Pb2+位点配位结合，形成稳定的五元环。其柔性三碳连接体使分子能够自适应异质晶界，从而同时解决上述缺陷和离子迁移问题。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":7.0,"t":6.0},"kp":["缺陷钝化策略[无机钙钛矿]: 分子螯合钳策略","钝化剂[卤化物空位缺陷]: 2,3-二巯基-1-丙磺酸钠 (DPS)"]},{"i":38580,"as":"在TbScO3(110)衬底上外延生长BiFeO3薄膜的研究揭示了薄膜厚度对自旋摆线稳定性的影响及晶体、铁电畴和磁序的复杂演化规律。当薄膜厚度大于约5 nm时，结构保持菱形，晶格失配通过形成71°铁弹性闭合畴（而非失配位错）及随后的109°畴来适应；当薄膜厚度小于约5 nm时，则出现极性类菱方相与其他相共存的现象。","scd":{"b":8.0,"i":2.0,"r":5.0,"d":7.0,"t":5.0},"kp":["薄膜厚度[外延生长BiFeO3维持菱方结构]: >~5 nm"]},{"i":38581,"as":"为解决环境条件下电化学硝酸根还原合成氨过程中水分解与硝酸盐氢化动力学不匹配的限制，设计了Ag/CoNiS异质结构。通过调控Ag的负载密度来编程界面限域效应，调节氢溢流，使氢从CoNiS水分活化域有效传递至Ag相关的硝酸盐/氮氧化物中间体，成功将活性氢（*H）的生成、传递与深度氢化耦合，显著提升电催化合成氨效率。","scd":{"b":8.0,"i":3.0,"r":5.0,"d":7.0,"t":6.0},"kp":["催化剂[电化学硝酸盐还原合成氨]: Ag/CoNiS异质结构"]},{"i":38582,"as":"Ag2Se因带隙窄、本征晶格热导率低及具有室温塑性，被认为是柔性可穿戴n型热电材料的优选。综述系统总结了Ag2Se基热电材料的最新进展，涵盖了决定其半导体和超离子传输行为的基础晶体结构、缺陷化学及电子能带特征，并详细探讨了包括纳米结构化、化学计量比调整、掺杂以及引入无机/有机第二相等提升热电性能的先进策略。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":7.0,"t":3.0},"kp":["热电材料[柔性可穿戴应用]: Ag2Se"]},{"i":38583,"as":"为解决无阳极锂电池采用超厚正极时面临的副反应和锂储库受限问题，开发了一种采用120 mg cm⁻²的3D打印超厚正极与双盐/双溶剂电解质的无阳极软包电池。该电解质形成富阴离子的溶剂化结构，生成弹塑性固体电解质界面层，在裸铜集流体上实现高度可逆的锂沉积/剥离及低温下的稳定循环。该电池配置实现1308 Wh/L和424 Wh/kg的能量密度。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":8.0,"t":6.0},"kp":["能量密度[无阳极锂电池]: 1300 Wh/L","面密度[3D打印超厚阴极]: 120 mg/cm²","溶剂化结构[双盐/双溶剂电解液]: 富阴离子溶剂化结构"]},{"i":38584,"as":"均相催化和多相催化长期独立发展，二者在活性、选择性和可回收性上具有互补性。打破两者壁垒、构建集高活性、优异选择性、稳定性和易回收性于一体的新型催化体系成为重要目标。均相-多相集成催化作为新兴策略为此开辟了新途径，该综述系统总结了这一前沿领域的最新尖端进展。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[均相-多相集成催化系统]: 结合高活性、高选择性与可回收性的新型催化体系"]},{"i":38585,"as":"卤化锂超离子导体因高Li⁺电导率、优异的正极兼容性和机械可变形性，成为全固态锂电池极具前景的固态电解质。然而，这些导体在与还原性负极接触时表现出化学和电化学不稳定性，阻碍了高比容量锂金属负极的直接应用。因此，提升卤化物固态电解质的负极兼容性已成为全固态电池发展的关键任务。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":5.0,"t":5.0},"kp":["固态电解质[全固态锂电池]: 卤化物超离子导体","兼容性[卤化物固态电解质]: 对阴极具有极佳兼容性，但在还原性阳极接触时存在化学和电化学不稳定性"]},{"i":38586,"as":"受超分子和动态共价相互作用主导的自修复聚合物正在重塑材料结构设计。氢键等可逆超分子基元能实现快速界面重建，而双硫键等动态共价键则提供了坚固且可重构的网络架构。两者的协同整合赋予了材料可重复自修复、高强度力学性能和多重响应能力。这些进展已成功应用于柔性电子领域，特别是在电容传感方面。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[柔性传感器自修复聚合物]: 基于氢键等超分子 motifs 实现快速界面重建与损伤容忍","[动态共价键]: 基于Diels-Alder、二硫键提供机械鲁棒性、可重构和可回收的网络结构"]},{"i":38587,"as":"通过机器学习的指导，在钛酸锶基陶瓷中实现了高效且热稳定的电容储能。结合局部结构工程优化的制造工艺，材料表现出增强的极化强度、降低的磁滞损耗和提升的击穿强度。最终设计的材料实现了10.69 J/cm⁻³的超高能量密度，以及接近97%的理想储能效率。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":6.5,"t":5.0},"kp":["[钛酸锶基陶瓷]: 机器学习引导实现高效和热稳定的电容储能"]},{"i":38588,"as":"氧化还原酶类纳米酶是最广泛应用的纳米酶之一，但其复杂的催化机制限制了进一步发展。该综述打破了单纯按材料类型分类的常规，沿反应途径深入剖析其催化机制，详细探讨并对比了纳米酶催化过程中的电子转移序列、底物吸附、活性中间体生成/转化以及产物解吸等关键步骤。","scd":{"b":5.0,"i":2.5,"r":6.5,"d":4.0,"t":3.0},"kp":["催化机制分析[氧化还原酶类纳米酶]: 深入反应途径剖析（活性、特异性和可持续性）"]},{"i":38589,"as":"针对分子半导体自旋输运效率（约5%）低的问题，开发了具有垂直不对称纳米柱通道的分子自旋电子器件。该结构通过相分离形成，能够限制自旋并产生内建电场，将室温下的自旋输运效率提升至20%，创下目前最高纪录，且为无结构薄膜的五倍以上。同时，纳米柱通道还表现出显著的偏压依赖不对称性。","scd":{"b":8.0,"i":2.5,"r":7.0,"d":7.0,"t":5.0},"kp":["自旋输运效率[分子半导体]: ∼5%","[纳米柱分子半导体]: 形成垂直不对称通道以限制自旋并产生内建电场"]},{"i":38590,"as":"针对体异质结有机光催化剂因结晶度差和易受分子振动影响导致载流子复合严重的缺陷，开发了甲氧基官能化电子受体ITIC-OMe。该材料展现出增强的结晶度和更紧密的分子排列，有效抑制了晶格对分子振动的敏感性。通过提高分子结晶度和减少电子-声子耦合，成功抑制了载流子复合，从而实现了高效的可见光析氢反应。","scd":{"b":7.0,"i":3.0,"r":5.5,"d":5.0,"t":5.0},"kp":["[体异质结有机光催化剂]: 提高分子结晶度和减少电子-声子耦合以抑制载流子复合，实现高效析氢"]},{"i":38591,"as":"基于光动力学的光免疫疗法结合了光动力疗法的精准性和免疫疗法的持久疗效。通过合理的供体-受体工程开发了一系列A-D-A结构的有机光敏剂。该分子策略通过精细调节分子内电荷转移强度，实现了对光动力路径的精确控制（I型和II型），从而构建了系统比较不同类型光动力疗法引发免疫原性细胞死亡（如免疫原性焦亡）潜力的平台。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["光敏剂[光免疫疗法]: 采用A-D-A结构有机光敏剂诱导免疫原性焦亡"]},{"i":38592,"as":"在SnTe基合金中构建了熵驱动的分层缺陷结构，实现了热电和机械性能的双重增强。该结构引导了从0D置换簇到1D位错和3D共格纳米析出物的分层缺陷演化，实现声子传输的多尺度调控与强化。宽带声子散射将873 K下的晶格热导率降至0.26 W·m⁻¹·K⁻¹，同时共格纳米析出物强化了材料力学完整性，解决了高转化效率与机械鲁棒性难以兼顾的挑战。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["分层缺陷结构[SnTe合金]: 熵驱动的0D取代簇到1D位错和3D缺陷演化","[SnTe合金]: 热电性能与机械性能双重增强"]},{"i":38593,"as":"为了弥补自下而上微纳加工在多层、3D制造中缺乏光刻胶级再现性和通用性的不足，探索了表面选择性成核（SSN）效应。通过双端丙烯酸单体在预图案化衬底上的溶液聚合，并利用吸附抑制剂和链终止剂建立区域依赖性成核势垒，协同调节表面和体相自由能，成功制备出具有纳米级分辨率、低缺陷密度、易剥离且适用于多种加工平台的聚合物抗蚀剂图案。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["聚合物抗蚀剂图案[表面选择性成核效应]: 具有纳米级分辨率、低缺陷密度和易剥离特性"]},{"i":38594,"as":"含STAG1或STAG2亚基的黏连蛋白复合物决定了真核基因组的3D结构。STAG2被确定为有丝分裂后基因组重折叠的主要协调者。有丝分裂退出后，STAG1耗竭对基因组重折叠影响微弱，而STAG2则以阶段和染色质环境依赖的方式调节基因重塑：在G1早期促进小常染色质环、增强子-启动子接触；在G1晚期则限制STAG1的进程，抑制大环形成。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[基因组重折叠机制]: STAG2是有丝分裂后基因组重塑的主要调节因子，且依赖于阶段和染色质环境发挥作用"]},{"i":38595,"as":"PARG的抑制会严重影响DNA复制。FET家族蛋白（FUS、EWS和TAF15）以依赖PAR的方式被招募至复制叉，形成缩合物，减缓复制叉前进并促进复制叉逆转。FET蛋白控制细胞对部分复制应激的反应，而FUS失活会通过RECQ1和PRIMPOL引发不受控的复制叉前进，破坏基因组稳定性。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":4.5,"t":4.0},"kp":["[复制叉逆转与基因组稳定性]: FET蛋白(FUS, EWS, TAF15)在PARG抑制时形成PARylation依赖性缩合物以促进复制叉逆转"]},{"i":38596,"as":"","scd":null,"kp":[]},{"i":38597,"as":"前列腺癌中的SPOP突变和CHD1缺失决定了细胞对铁死亡的敏感性。SPOP突变增强了靶向GPX4的铁死亡诱导剂的疗效，而CHD1缺失则削弱了其疗效。机制上，SPOP和CHD1通过拮抗调节MYC-ACSL4轴对铁死亡产生相反的作用。这揭示了针对铁死亡的上下文相关基因漏洞，为癌症的精准靶向治疗提供了新方向。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[前列腺癌铁死亡易感性]: SPOP突变和CHD1缺失是决定前列腺癌对铁死亡易感性的关键遗传因素"]},{"i":38598,"as":"利用商业可得的配体镍催化剂，成功实现了两种不同生物质来源醇的连续交叉偶联/异构化和交叉偶联/脱氢反应。该方法实现了三取代烯烃（27个实例，E/Z比高达98:2）和1,3-二烯（23个实例，E/Z比大于20:1）的立体选择性合成。反应展现出精确的催化控制能力，并成功应用于D-半乳糖、α-生育酚等复杂分子的后期功能化。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[可再生醇合成]: 配体镍催化醇的顺序交叉偶联/异构化和交叉偶联/脱氢反应","[合成产物]: 模块化合成三取代烯烃和1,3-二烯"]},{"i":38599,"as":"6-硫鸟嘌呤(6-TG)是FDA批准的抗代谢药物。研究开发了具有细胞活性的NUDT5选择性降解工具包，并表征了其靶点结合、三元复合物形成、降解动力学和蛋白质组选择性。该降解剂结合CRISPR技术，揭示了NUDT5作为一种NUDIX水解酶，是介导6-TG细胞毒性的关键调节因素。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[NUDT5降解技术]: 靶向蛋白质降解NUDT5，从而将6-硫鸟嘌呤响应中的催化抑制与蛋白质损失分离开来"]},{"i":38600,"as":"角稠合多环系统是药物和生物活性天然产物中的重要骨架。研究报道了一种可见光诱导的脱芳构化方案，通过苯并噻吩/吲哚衍生物与N-芳基环丙胺的分子间反应，直接构建角稠合四环支架。该反应机制包含光催化脱芳[3+2]环加成和随后的环化级联过程，展示了合成复杂多环框架的可行性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[可见光诱导]: 分子间脱芳构化环加成构建角稠合四环支架"]},{"i":38601,"as":"手性烷烃合成通常步骤繁琐。研究提出了一种基于多醇完全脱氧烷基化的“外围编辑”新概念。在引入烯烃并将醇转化为酯后，通过多米诺SN2'反应，能够以催化方式对所有羟基进行顺序且立体选择性的编辑。该方法利用易得的生物基多醇，可合成含有高达六个连续手性中心的手性烷烃。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[手性烷烃合成]: 多元醇外围编辑与完全脱氧烷基化","[催化机制]: 多米诺SN2'反应"]},{"i":38602,"as":"尽管金红石型IrO2-TiO2和IrO2-SnO2体系符合Hume-Rothery准则，但其混溶性却出奇地有限。研究发现，d0和d10态的M阳离子（如Ti4+和Sn4+）形成主要呈离子性的M-O键，而IrO2中的Ir-O键则具有高度共价性。在共边金红石结构共享氧位点上，这两种不同的键合类型导致了几何受挫的电子密度，从而决定了溶质混溶性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[铱基氧化物体系]: 键合特征和八面体几何形状是决定溶质混溶性的关键因素"]},{"i":38603,"as":"针对船舶脱碳难题，研究评估了海上与岸上溶剂再生途径。对16条航线和4种溶剂的分析表明，将溶剂再生从船转移到岸可以提高海上碳捕集的实用性和成本效益。采用实际载荷限制（约20%）比固定捕集率更为合理。船上再生偏好低再生能溶剂，而岸上再生则优选具有高二氧化碳吸收能力的溶剂。","scd":{"b":5.0,"i":6.0,"r":6.0,"d":8.0,"t":6.0},"kp":["溶剂再生路径[海洋碳捕获]: 由船上转移至岸上进行再生可提升实用性与成本效益","[船舶碳捕获评估]: 对比了16条航线和4种捕获溶剂在不同船载负荷限制下的表现"]},{"i":38604,"as":"自然杀伤(NK)细胞在实体瘤微环境中面临渗透性差和免疫抑制等挑战。空间和单细胞转录组学分析表明，Nur77在NK细胞抗肝细胞癌(HCC)免疫中起关键作用。编码Nur77的NR4A1表达与NK细胞增殖、免疫刺激及更好的生存率相关。在小鼠中敲除NK细胞内的Nr4a1会加速肿瘤进展，而Nur77激动剂能有效增强NK细胞对肝癌的免疫力。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[肝细胞癌NK细胞免疫]: 激动Nur77(NR4A1)可激发自然杀伤细胞对肝细胞癌的抗肿瘤免疫并克服实体瘤微环境抑制"]},{"i":38605,"as":"","scd":null,"kp":[]},{"i":38606,"as":"Plk1激酶调节细胞和中心体周期的多个步骤，其活性依赖于不同辅因子。研究表明，人类细胞中的不同Plk1辅因子控制着各异的周期转换。在S期，Cep192和Aurora A控制Plk1促进复制起点激活；Bora是驱动G2期有丝分裂进入、DNA损伤恢复和中心体成熟的主要激活剂；而Cenexin则负责中心体解聚。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["[Plk1依赖性细胞和中心体周期转换]: Bora、CEP192和Cenexin作为不同辅助因子差异性调节有丝分裂进入、DNA损伤恢复、中心体成熟和中心体分离等过程"]},{"i":38607,"as":"在植物中，异染色质的区域特异性形成机制此前尚不明确。研究发现，互斥的组蛋白H2A变体H2A.W和H2A.Z在引导异染色质形成中起拮抗作用：H2A.W促进异染色质建立，而H2A.Z起抑制作用，特别是在含有分散转座子(TEs)的染色体臂区域。相反，近着丝粒TEs表现出自主的异染色质形成，从而塑造了植物的表观基因组模式。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["[植物异染色质形成]: 由拮抗组蛋白H2A变异和自主途径以RdDM非依赖性方式建立H3K9me和非CpG甲基化"]},{"i":38608,"as":"在慢性感染期间，单核细胞衍生的肺细胞亚群限制结核分枝杆菌(Mtb)的能力存在差异。最允许Mtb生存的CD11clo单核衍生细胞表达较低水平的干扰素-γ(IFNγ)信号蛋白，导致其对IFNγ反应减弱。此外，I型IFN信号会抑制IFNγ介导的MHC II类分子表达，损害抗原特异性CD4 T细胞激活。已控制的Mtb感染所赋予的先验免疫力则能增强这些细胞的IFNγ反应。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["[慢性结核分枝杆菌感染免疫响应]: CD11clo单核细胞衍生细胞表达IFNγ信号蛋白水平低，限制了对Mtb的生长限制能力"]},{"i":38609,"as":"为理解癌细胞在治疗压力下的进化与耐药机制，研究开发了一种分层动态谱系追踪技术FLARE。利用该技术追踪了急性髓系白血病(AML)细胞系在体内外接受阿糖胞苷治疗的过程，成功绘制了易于产生阿糖胞苷耐药的不同细胞谱系。研究识别出了在治疗前就已存在、并导致后续耐药产生的细胞群体。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[阿糖胞苷耐药性追踪]: 开发了一种名为FLARE的分层动态谱系追踪方法，用于追踪AML细胞系在治疗压力下的耐药进化途径"]},{"i":38610,"as":"研究探讨了酵母中染色质重塑复合物Swi-Snf与全局共抑制因子Tup1-Cyc8的拮抗调节作用。鉴定出受Tup1-Cyc8抑制和Swi-Snf激活的基因。这两种复合物同时存在于活性和非活性基因启动子上，其中SNF2对Tup1-Cyc8的完全占据是必需的。它们对核小体定位的影响因具体的共调节基因而异，表现出上下文依赖性。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[酵母拮抗基因染色质和转录调节]: Swi-Snf复合物破坏启动子核小体激活转录，Tup1-Cyc8复合物定位核小体阻断转录，二者相互作用受上下文依赖"]},{"i":38611,"as":"多倍化是植物进化的重要驱动力。通过组装阿拉伯芥的两个亲本基因组，并分析自然和人工合成四倍体的表观基因组，研究了多倍化对DNA甲基化的短期影响。异源多倍化后立即发生最显著的甲基化变化，随后的世代中变化较小。在不同环境生长的后代中表现出甲基化模式的趋同与趋异，表明多倍化与环境共同影响表观遗传响应。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["[新多倍体表观基因组重塑]: 多倍化后短期内发生DNA甲基化和基因表达模式的趋同与趋异响应"]},{"i":38612,"as":"针对金属蛋白结合位点识别困难、现有计算方法受限于准确性和数据稀缺的问题，研究引入了混合深度学习框架PRIME。该框架结合进化与结构信号，利用蛋白质语言模型和预训练结构模型从序列和结构中提取信息，并通过探针生成算法桥接基于序列和结构的预测，从而高效、准确地识别金属结合位点。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[金属蛋白结合位点识别]: 开发了一种名为PRIME的混合深度学习框架，结合进化和结构特征来识别金属结合位点"]},{"i":38613,"as":"昆虫复眼的全景视觉依赖于微米级的曲率变化，但其发育编码机制未知。在果蝇中发现，发育中视网膜的基底表面被组织成超细胞三角网格，其大小呈物种特定的二维分布。遗传扰动和计算模型证实，该网格图案决定了成虫复眼的局部三维曲率。果蝇不同物种中的类似图案表明这是一种控制复眼曲率的自然可编程超材料机制。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["视网膜基面组织[果蝇复眼发育]: 呈现超细胞三角形网格结构","[凸面复眼视觉]: 依赖微米级的曲率变化形成特定视觉区域"]},{"i":38614,"as":"光子学具有环境隔离和易于单量子位操作的优势。研究采用可扩展的时分复用方法，构建了一个完全可重构的光子处理器架构，实现了保真度为(93.8 ± 1.4)%的后选择量子C-NOT门。研究进一步证明，该时分复用平台能够将C-NOT门与单量子位门结合，成功生成四种贝尔态，为量子电路提供了关键组件。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["量子C-NOT门构建[时分复用光子处理器]: 采用可扩展的时分复用方法实现完全可重构","[光子学量子门]: 具有极佳的环境隔离和单量子比特级易于操控的双重优势"]},{"i":38615,"as":"针对陶瓷基复合材料强度与韧性难以兼顾的权衡问题，受珍珠层“矿物桥”结构启发，研究提出一种含有纳米孔的新型反向界面设计。多尺度表征和模拟显示，纳米孔降低了界面脱粘强度并诱发裂纹偏转以保护纤维；同时，粗糙的断裂路径增强了界面摩擦应力与载荷传递。这种不对称调制在保持纤维完整性的同时最大化能量耗散。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["复合材料界面设计[陶瓷基复合材料]: 采用含有纳米孔的反向界面设计","双增强机制[纳米孔界面]: 降低界面脱粘强度并诱发裂纹偏转以保护纤维"]},{"i":38616,"as":"集成光子器件因储能容量小而难以实现高光功率。研究将大模场(LMA)技术引入芯片级硅光子放大器，实现了瓦级直接放大。该放大器具有高饱和功率、低噪声系数以及零偏振依赖性(PDG)。这一成果满足了长距离光通信和光传感等应用领域对高功率、低噪声及低偏振依赖性放大器的关键需求。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[集成硅光子放大器]: 具有高饱和功率、低噪声系数和零偏振依赖性(PDG)特征"]},{"i":38617,"as":"现代深度学习地震探测器能识别大量微小事件，但由此产生的高速率到时序列难以关联，尤其是在波速异构时。研究引入了HARPA相位关联框架，将观测和预测的到时序列表示为概率分布，并使用最优传输度量进行比较。该框架能够联合估计地震位置、发震时刻以及波速场的低维表示，有效解决了高速率相位关联问题。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":5.0,"t":6.0},"kp":["相位关联挑战[地震学高到达率序列]: 波速局部高度不均匀或未知时，高到达率序列的关联难度显著增加"]},{"i":38618,"as":"二维范德华铁电材料是超紧凑纠缠光子源的候选者。研究比较了NbOBr2和NbOI2中的自发参量下转换(SPDC)过程，成功实现了近红外偏振纠缠光子的产生，并将其性能与晶体结构关联。结果表明，NbOI2特别适合近红外SPDC，可直接产生并发度为0.90 ± 0.05的偏振纠缠态，扩展了非线性量子光源的波长范围。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["纠缠光子光源[范德华铁电NbOX2]: 通过自发参量下转换(SPDC)实现近红外偏振纠缠光子的生成","[性能关联机制]: 光源性能与其晶体属性直接相关"]},{"i":38619,"as":"研究人员开发了一种具有机械加固界面的统一双层膜，用于阶段性骨再生。该膜采用同分异构原位制造策略，在阻挡层和多孔层之间形成增强的双交联界面。其表现出卓越的机械强度（干态约156 MPa，湿态约8.6 MPa），确保了体内长期降解稳定性和生物活性。结合顺序释放的生物活性成分，该双层膜能够发挥抗菌、免疫调节、神经血管化和成骨作用，在老鼠模型中实现了阶段适应性骨再生。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["机械强度[双层骨再生膜干态]: ~156 MPa","机械强度[双层骨再生膜湿态]: ~8.6 MPa","膜界面设计[引导骨再生]: 阻挡层和多孔层之间具有增强的双交联界面"]},{"i":38620,"as":"针对单糖分子中多羟基团难以区分和结构复杂的挑战，研究人员提出了一种有机催化方法，实现了微保护单糖的位点选择性磺酰化。该方法利用N-杂环卡宾（NHC）衍生的磺酰唑鎓中间体，通过经典SN2反应实现糖类羟基的立体反转和官能团交换。不同的NHC骨架控制着区域选择性，为单糖的结构选择性编辑提供了一种稳健的模块化途径。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["立体反转策略[单糖多羟基]: 利用卡宾催化的位点选择性磺酰化和模块化版本进行处理"]},{"i":38621,"as":"受骨骼肌运作机制启发，研究人员开发出一种具有低压氧化还原触发和自发收缩功能的仿生电化学人造肌肉。该肌肉在低于0.4V的电压下充电触发，实现I3⁻的注入并随后氧化为I2。随后，通过I2 + I⁻ → I3⁻的反应实现自发收缩，这一过程类似于骨骼肌中三磷酸腺苷水解的作用。该机制与传统电化学人造肌肉有本质区别，并在原始碳纳米管纱线肌肉中得到验证。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["触发电位[仿生电化学人造肌肉]: 0.4V以下","[收缩机制]: 通过电化学充电实现I3⁻注入并自发氧化为I2，引发自发收缩"]},{"i":38622,"as":"为解决分子模拟中原子相互作用力场在物理可靠性、计算效率和未知分子准确性之间的权衡，研究人员开发了残差学习力场（Residual Learning Force Field）。这是一种混合机器学习力场，将简单的基于物理学的键合相互作用描述与学习到的能量效应校正相结合。两部分的联合训练使其能够提供互补信息。在类药物分子、分子二聚体和生物分子模拟等测试中，该力场有效降低了上述权衡带来的性能限制。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[分子力场平衡权衡]: 结合基于简单物理学的成键相互作用描述与机器学习的修正项以缓解可靠性、计算效率和精度间的权衡"]},{"i":38623,"as":"研究人员开发了一种负载量高达66.5 wt%的Ni-Ce-Al三元催化剂，用于高效催化氨分解。由氧化铝框架连接的Ni纳米颗粒周围包围着丰富的原子分散Ce物种（单原子和团簇）。这种设计克服了传统二氧化铈负载Ni催化剂因烧结导致的活性-稳定性权衡。在600°C下，该催化剂实现了324.0 mmol gcat⁻¹ min⁻¹的高产氢率。原子分散的Ce物种作为氢清除剂，有效缓解了氢中毒现象，从而促进氨活化和氢气解吸。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":8.0,"t":6.0},"kp":["Ni负载量[Ni-Ce-Al三元催化剂]: 66.5 wt%","Ce物种分布[Ni纳米颗粒催化剂]: 以原子级分散的Ce单原子和团簇形式存在并作为氢清除剂"]},{"i":38624,"as":"研究演示了一种通过时空神经场表示实现的视频速率无透镜叠印术，成功打破了成像科学中的十亿像素空间带宽积（SBP）视频速率壁垒。该方法协同设计了光学、传感和计算：编码表面对动态物体进行编码，时间序列传感将信息分散到不同帧中，时空神经场框架则利用时空相关性恢复动态。该技术实现了厘米级覆盖下的视频速率十亿像素成像，可分辨308纳米线宽，SBP吞吐量高达每秒20.8千兆像素。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[视频速率无透镜叠印术]: 克服空间带宽积（SBP）视频速率障碍","[时空神经场]: 恢复动态物体信息"]},{"i":38625,"as":"为实现高效CO2电还原制乙烯，研究人员利用C-C耦合和C-O断裂能量变化作为描述符，合成了一种锚定在铜上的不饱和MgO1-x催化剂。在流动池中，该催化剂在300 mA cm⁻²的电流密度下实现了78.2%的乙烯法拉第效率。机制表明，MgO1-x具有双功能：其与铜域的化学相互作用稳定了Cu+并形成不对称的Cu+···Cu0对，从而促进了*CO-CHO的耦合反应。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[CO2电还原制乙烯催化剂]: 不饱和MgO1-x锚定在Cu上","[催化剂合成方法]: 电化学诱导相分离法"]},{"i":38626,"as":"研究揭示了TRPC4和TRPC5离子通道是雄性小鼠经颅聚焦超声（tFUS）神经元调节的关键介质。对小鼠脾后皮质应用tFUS会脱敏机械和热敏感性，并诱发早期生长响应1（Egr1）的表达。抑制tFUS诱导的Egr1神经元集群会阻断上述躯体感觉效应。转录组分析显示，在tFUS激活的Egr1阳性细胞中富含Trpc4。药理抑制和基因敲低TRPC4均会彻底消除tFUS介导的感觉调节作用。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["受体靶点[雄性小鼠脾后皮质经颅聚焦超声调节]: TRPC4和TRPC5通道","神经调节效应[小鼠脾后皮质施加经颅聚焦超声]: 脱敏机械和热敏感性并诱导早期生长反应"]},{"i":38627,"as":"研究发现Runx2通过调节Ctsk转录直接驱动破骨细胞分化，而Ip6k2作为其相互作用蛋白，特异性增强破骨细胞中依赖于Runx2的Ctsk转录。在破骨细胞中敲除Ip6k2基因可抑制破骨细胞生成并增加骨量，且不影响成骨细胞功能。靶向Ip6k2-Runx2轴能够有效破坏成骨细胞与破骨细胞之间的偶联，为治疗骨质疏松症提供了一种不干扰成骨作用的潜在新策略。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.5,"t":5.0},"kp":["调控靶点[破骨细胞分化]: Runx2直接驱动Ctsk转录","分子机制[破骨细胞中Runx2依赖性]: Ip6k2作为Runx2相互作用蛋白增强其活性"]},{"i":38628,"as":"为解决Richardson-Lucy反卷积算法易过度拟合噪声并产生高频伪影的问题，研究人员提出了一种名为DeBayes的严格贝叶斯反卷积框架。DeBayes建立在物理精确的图像形成模型基础上，在空间域执行反卷积，精确联合模拟噪声源，并推断潜在物体的完整后验分布。该框架无需假设稀疏性或连续性，能产生严格为正的重构结果，且在没有用户调整的正则化参数或迭代截止标准的情况下也能稳定收敛。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[Richardson-Lucy反卷积物理替代方案]: DeBayes贝叶斯反卷积框架，无需手动截止标准"]},{"i":38629,"as":"研究表明，地球上的生命已进化出适应重力的形式，线粒体利用重力来激活其内部的蛋白质合成。全基因组核糖体分析显示，在微重力条件下，哺乳动物细胞和秀丽隐杆线虫的线粒体翻译会减少。这一现象是由层粘连蛋白-整合蛋白相互作用引起的细胞粘附减弱所致。线粒体翻译由胞质中的FAK、RAC1、PAK1、BAD和Bcl-2家族蛋白，以及基质中的线粒体脂肪酸合成（mtFAS）途径所传递的信号激活。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["蛋白质合成效应[微重力下的哺乳动物细胞和秀丽隐杆线虫]: 线粒体翻译减少","感知机制[重力激活线粒体蛋白质合成]: 层粘连蛋白-整合素相互作用介导的细胞粘附"]},{"i":38630,"as":"研究人员利用不同尺寸的胶体量子点进行相分离自组装，成功制备出Janus（双面）微环。这种微环结构能够有效抑制能量转移，并在单一微腔内实现稳定的双波长激光发射。这种可扩展的一步合成策略还有望应用于高密度光学编码和制备大面积全彩色激光阵列，为集成光子学领域提供了重要的技术支持。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.5,"t":5.0},"kp":["[单微腔双波长激光]: 胶体量子点相分离自组装Janus微环","[Janus微环功能特性]: 抑制能量转移并实现稳定双波长激射"]},{"i":38631,"as":"该研究阐明了一种高能全固态锂硫电池的设计原则：微小孔隙决定了硫的反应空间，而较大的碳颗粒则负责引导离子流动。将这两种跨尺度的结构结合在一个主体中，使得正极同时具备了所需的反应活性和离子传输能力。这种设计实现了高硫利用率和持久的循环性能，为推进下一代全固态锂硫电池的实用化提供了有效途径。","scd":{"b":5.5,"i":4.0,"r":5.5,"d":6.0,"t":5.0},"kp":["[全固态锂硫电池设计原则]: 微孔塑形硫反应，大碳粒导向离子流（结合反应性和传输需求）"]},{"i":38632,"as":"一项深入的分析对仅仅依靠追求经济增长就能实现国家长期繁荣的传统观点提出了挑战。文章探讨了卢旺达在科技领域迅速崛起的可持续性问题，并指出除了单纯的经济增长之外，还需要其他相关要素的支持，才能确保国家维持长久的繁荣与科技发展。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":2.0,"t":4.0},"kp":[]},{"i":38633,"as":"","scd":null,"kp":[]},{"i":38634,"as":"研究描述了一种新型靶向种系HIV-1 Env（CAP256.OPT4），与野生型相比，它将V2顶端广泛中和抗体（bNAb）前体的引发效率提高了30至400倍。在恒河猴模型中，该设计在超过90%的个体内诱导了包含N130病毒的中和广度。通过持续复制的SHIV病毒、蛋白质纳米颗粒和mRNA三种递送平台，研究发现B细胞引发最早在免疫或感染后4周发生，血浆中和广度在12周出现，14只感染猕猴的中和广度最高达90%。","scd":{"b":8.5,"i":3.0,"r":6.5,"d":7.0,"t":5.0},"kp":["引发效率[V2顶端广谱中和抗体前体引发]: 较野生型HIV-1 Env提高30-400倍","免疫反应[广谱中和抗体诱导]: 在超过90%的猕猴中诱导包含N130病毒的广谱中和"]},{"i":38635,"as":"该研究更正说明涉及NSD2靶点，探讨靶向逆转前列腺癌可塑性和耐药性的机制，属于肿瘤靶向治疗领域。","scd":{"b":2.0,"i":1.0,"r":2.0,"d":1.0,"t":5.0},"kp":[]},{"i":38636,"as":"","scd":null,"kp":[]},{"i":38637,"as":"研究利用带有动量选择的扫描透射电子显微镜振动光谱，探测了LaAlO3/SrTiO3界面超导相图中的晶格振动和原子结构。结果表明，在掺杂系列中，超导性与反演对称性破缺和高频局部声子的出现密切相关。在铁电量子临界点附近，量子限域和对称性破缺产生的二维电子气中，这些局限于界面附近的可调谐极性振动为电子配对提供了直接证据，揭示了超导性与铁电性之间的内在联系。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[LaAlO3/SrTiO3界面特性]: 量子限域和反演对称性破缺产生二维电子气"]},{"i":38638,"as":"","scd":null,"kp":[]},{"i":38639,"as":"","scd":null,"kp":[]},{"i":38640,"as":"通过在器件、阵列和系统三个层级深入理解忆阻器的固有物理特性并进行协同设计，可以有效突破现有的技术瓶颈，从而实现基于忆阻器的高精度计算。这种多层次协同的方法是发挥忆阻器计算潜力的核心途径。","scd":{"b":5.0,"i":4.0,"r":4.0,"d":4.0,"t":5.0},"kp":["[基于忆阻器的计算]: 协调器件、阵列和系统级的固有特性实现高精度计算"]},{"i":38641,"as":"针对传统脂肪酸酯工业生产依赖不可持续石化催化和植物提取的问题，研究团队以非常规产油酵母圆红酵母为底盘，构建了全新的微生物从头合成平台。通过筛选特定途径酶并进行模块化代谢途径工程，无需添加醇或脂质前体即可成功重塑原生脂质代谢，实现结构多样化脂肪酸酯的高水平生物合成。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[脂肪酸酯从头合成平台]: 圆红酵母"]},{"i":38642,"as":"介绍可用于核磁共振成像的深脑光纤电极，探讨其在深部脑区神经调控中的应用，属于神经工程方向。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":4.0,"t":5.0},"kp":["电极特性[核磁共振成像环境]: 可用于MRI-safe的深脑光纤电极"]},{"i":38643,"as":"气候变化正导致咖啡植物面临极度濒危的严峻生存威胁。为解决这一危机，研究人员正在积极探索和寻找有效的科学解决方案，以保护咖啡植物免于灭绝，从而持续为科学家提供研究所需的发现动力。","scd":{"b":3.0,"i":4.0,"r":5.0,"d":4.0,"t":4.0},"kp":[]},{"i":38644,"as":"人工智能（AI）代理系统能够通过相互协作，自主生成生物医学假设并进行数据分析。这一技术进展推动实验室研究向全新的周期演进，在发现过程的每一步骤中均实现了人工智能的深度参与，大幅提升了科研自动化程度。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["协作模式[生物医学AI智能体]: 协同生成假设和分析数据","实验室发现循环[人工智能介入]: 全流程参与"]},{"i":38645,"as":"","scd":null,"kp":[]},{"i":38646,"as":"研究发现了本质上无序的蛋白质ALMS1在中心体生物发生中的关键机制。ALMS1作为外部辅助因子引发软骨轮结构的形成，但自身并不整合入结构中。在细胞有丝分裂进入时，ALMS1参与软骨轮种子（CS）的解体。ALMS1基因的亚效突变会导致软骨轮发生异常扩增并从其生长的中心体脱落，进而形成异位结构。","scd":{"b":8.5,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["外部辅助因子[中心粒生物发生/支架形成]: 本质上无序的蛋白质 ALMS1","核心蛋白复合体[间期软骨轮种子(CS)形成]: CEP15致密复合体"]},{"i":38647,"as":"研究利用CXCR3报告小鼠证实，在甲型流感病毒（IAV）感染后，典型的1型炎症趋化因子受体CXCR3在反应性B细胞中被高度诱导。与次级淋巴器官相比，诱导性支气管相关淋巴组织（iBALT）中异位肺生发中心的B细胞表现出更高的CXCR3水平。B细胞特有的CXCR3被证明是驱动针对病毒感染产生有效异位肺生发中心反应的关键因素。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["趋化因子受体[甲型流感病毒感染反应-B细胞固有]: 原型1型炎症趋化因子受体 CXCR3"]},{"i":38648,"as":"ESCRT（运输所需的内体分选复合物）机制通过早期复合物的组合结合被招募以重塑多种细胞膜。晚期起作用的ESCRT-III复合物亚基与VPS4 AAA ATP酶共同形成膜相关丝，介导膜的重塑、收缩和分裂。研究描述了两类不同的螺旋ESCRT-III丝，这些丝能够包围并处理由特定磷脂酰肌醇二磷酸（PIP2）结合所引导的膜结构。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["膜招募机制[ESCRT机器-不同细胞膜重塑]: 通过ESCRT-I和ESCRT-II与PIP、泛素化修饰等进行组合结合"]},{"i":38649,"as":"在果蝇模型中，神经元表达人类tau蛋白并结合损伤，会显著触发雄性果蝇攻击行为的增加，且该行为发生时并未伴随神经退行性病变。这种表现源于多巴胺能神经环路的激活。磷酸化的tau蛋白虽然保持与微管的结合能力，却丧失了抑制微管灾难的效能，从而增加了微管的动力学活跃度，而未被磷酸化的tau蛋白则通过降低灾难频率来稳定微管。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["行为学表型[果蝇神经元表达人tau蛋白伴损伤]: 雄性果蝇攻击行为显著增加","致病机制[非磷酸化tau蛋白表达及损伤]: 激活多巴胺能回路但不伴随神经退行性变"]},{"i":38650,"as":"针对人类朊病毒难以在分裂细胞中增殖、只能依赖昂贵缓慢的动物实验这一限制，研究团队开发出名为EKV的类人源细胞模型。该模型能够强健且无限期地传播散发性克雅氏病（sCJD）朊病毒。实验证实，这些细胞培养物裂解液能诱发人源化小鼠发生致命的神经退行性病变，其临床和神经病理学特征与接种天然人类朊病毒的表现无异。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["细胞模型[人类散发性克雅氏病(CJD)朊病毒]: EKV细胞（一种人源化细胞模型）","细胞特性[朊病毒在人源分裂细胞中增殖]: 支持稳健且无限传代的扩增与定量"]},{"i":38651,"as":"研究在拟南芥中证实，钙依赖性蛋白激酶CPK3、CPK8和CPK10（CPK3/8/10）在脱落酸（ABA）诱导的气孔关闭过程中扮演关键角色。这些CPKs通过增强由OST1蛋白启动的钙离子流入，参与钙离子信号的编码。该机制依赖于主要由CNGC5/6/9/12构成的钙离子通道的激活，从而有效促进气孔关闭的生理过程。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["激酶[拟南芥ABA诱导的气孔关闭]: Ca2+非依赖性激酶OST1与Ca2+依赖性蛋白激酶","钙离子通道[OST1介导的磷酸化激活]: 主要由CNGC5/6/9/12构成"]},{"i":38652,"as":"针对软凝胶微球与平坦刚性基底间的界面相互作用，研究跨越多个数量级的弹性刚度测量了它们完全的粘附接触几何形态。结果揭示了连续的弹性毛细转变过程，证明了软材料的界面相互作用是由连续弹性力学、类流体表面力学以及内部孔隙弹性流之间的复杂相互竞争机制共同主导的，材料越软其表面粘附特性表现越强。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["软材料粘附机制[固体粘合剂]: 软凝胶微球的弹性毛细粘附源于连续弹性、类流体表面力学和内部孔隙弹性流的竞争效应"]},{"i":38653,"as":"研究通过脑电图（EEG）结合多类梯度提升树模型和SHAP解释器，分析了参与者对自然主题俳句与情感主题川柳的审美评价。结果显示，基于振荡神经特征训练的模型能够有效预测各项评分，且不同主题的神经编码具有高度的内容特异性。大脑中的预期神经振荡和特定主题的神经特征直接预测了人们对诗歌的审美评价。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[审美评价维度]: 审美吸引力、意象生动性、感动、原创性和创造力（5个维度）","[神经基础测量]: 使用多类梯度提升进行脑电(EEG)分析"]},{"i":38654,"as":"向列液晶在受限条件下会自发组装以最小化自由能并产生拓扑缺陷。利用掺铕（Eu3+）的磷酸镧（LaPO4）纳米棒组成的胶体液晶，研究观察到从传统的向列微滴向独特花状形态的形态发生过程。该研究克服了传统分子液晶在衍射极限以下空间尺度和亚毫秒时间尺度的观测限制，成功展示了三维结构的拓扑演化与动力学特征。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["三维结构与动力学研究受抑原因[受抑向列液晶拓扑演化]: 受限于亚衍射极限长度尺度和亚毫秒时间尺度特征"]},{"i":38655,"as":"通过几何分析量化运动轨迹形状，研究证实手臂优势（利手现象）是终身练习执行复杂轨迹任务的自然结果，而非单纯由内在的大脑半球优势决定。在使用工具或面临惯性挑战的三维触及任务中，非优势手臂的运动控制能力表现出明显的劣势。这一缺陷直接源于非优势侧在长期日常生活中缺乏对复杂工具和物体操作轨迹的足够练习。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[优势肢体表现机制测试任务]: 具有惯性挑战的3D伸展任务以及训练后任务"]},{"i":38656,"as":"在线虫和小鼠模型中发现，缺乏Tau蛋白或其同源物会导致线粒体的动力学状态向促融合方向转变。这种缺失不仅增强了线粒体的代谢活性和抗压能力，还改变了细胞的氧化还原稳态。这表明，除了病理突变会损害线粒体外，野生型Tau蛋白在维持线粒体稳态和正常动力学调节方面同样发挥着重要的生理调节作用。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[Tau缺乏症模型]: 秀丽隐杆线虫（缺乏PTL-1）和小鼠（缺乏Tau）","[Tau缺乏核心特征]: 促进向融合（pro-fusio）状态的转变"]},{"i":38657,"as":"动力蛋白激活蛋白复合体对神经元的胞内运输和突触稳态至关重要。研究在智力障碍家系中鉴定出DCTN4亚基的有害变异。在小鼠模型中，敲除DCTN4会导致神经祖细胞凋亡及神经元位置异常，而携带该变异的小鼠表现出认知缺陷和树突发育受损。DCTN4的缺乏或变异会降低多种动力蛋白激活蛋白亚基水平，破坏复合体功能从而引发智力障碍。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["患病人数[智力障碍全球预估]: 约2亿人","致病基因[智力障碍家系]: 动力蛋白激活蛋白亚基4 (DCTN4) 的有害变异","[DCTN4消融小鼠表征]: 神经元定位改变和神经细胞凋亡"]},{"i":38658,"as":"研究引入了一种基于大型语言模型（LLM）的可扩展分析框架，直接从口头文字报告中识别人类在风险条件下进行决策的特定原因。经验证的LLM在95%的测试中准确识别出了预定义的决策原因，与受试者的实际选择高度一致。基于文本报告提取的原因比传统行为数据更具简约性，揭示了人类决策更多由问题结构而非个体差异驱动。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["决策原因识别框架[大型语言模型]: 使用大型语言模型分析口头报告以识别货币彩票选择背后的决策原因"]},{"i":38659,"as":"植物气孔的排列依赖于最终对称细胞分裂（SCD）产生成对的保卫细胞。研究证实，这种对称分裂的定向受亚细胞和组织水平上的拉应力调控，从而形成追踪组织生长主轴的全局极化气孔场。KATANIN 1被确定为对称分裂定向的关键调节因子。相邻细胞的扩张以非自主方式控制着分裂的方向，将组织层面的机械应力与气孔形态发生直接关联。","scd":{"b":6.0,"i":1.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[气孔发育(对称细胞分裂)定向机制]: 受亚细胞和超细胞尺度的拉应力对齐，形成全局极化的气孔场"]},{"i":38660,"as":"通过测量瞳孔和脑磁图（MEG）响应，研究证实大脑在注意力发生转移时会主动抑制视觉敏感度。这种在注意力转移期间产生的敏感度降低或抑制现象，被证实并非由微眼球跳动引起，且在节律性状态下表现消失。这一机制类似于眼球快速运动时的跳视抑制，确保了大脑在没有明确动作输出时也能维持准确感知。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[注意转移研究方法]: 瞳孔测量法和脑磁图(MEG)"]},{"i":38661,"as":"","scd":null,"kp":[]},{"i":38662,"as":"研究利用19名癫痫患者的颅内神经记录，探讨了睡眠期间慢波、纺锤波和涟漪波等睡眠振荡的跨区域相互作用及其对运动记忆巩固的作用。结果表明，眶额叶皮层慢波能有效调节纺锤波和涟漪波；尽管多种振荡频率组合能正向预测运动任务隔夜表现变化，但癫痫尖峰会干扰并劫持这一支持记忆巩固的层级级联机制。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["患者样本量[人类癫痫睡眠节律研究]: 19名癫痫患者","[神经电生理记录位置]: 眶额皮质、丘脑和海马体","[睡眠振荡类型]: 慢振荡、睡眠纺锤波和涟漪波，以及癫痫尖波"]},{"i":38663,"as":"海洋浮游植物必须通过非光化学猝灭（NPQ）机制平衡高效捕光与抵御多余激发能。研究以中心硅藻为模型，证实光采集复合体（LHC）蛋白Lhcf2对能量依赖性猝灭至关重要。靶向敲除Lhcf2会通过阻止NPQ核心效应组分Lhcx1的稳定积累，彻底消除该硅藻的qE猝灭能力，揭示了Lhcf2在能量猝灭位点组装中的关键作用。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["关键调控蛋白[中心硅藻的非光化学猝灭(NPQ)]: 外围天线Lhcf2"]},{"i":38664,"as":"布氏锥虫的螺旋运动由侧向附着的鞭毛驱动。高速离焦成像与三维流体力学模拟揭示，鞭毛顺时针拍打产生右手螺旋波，推动细胞如开塞钻般前进；而较慢的逆时针细胞体旋转则用于平衡主动扭矩。鞭毛下方细胞的弯曲形状将这两种手性运动叠加在不同径向距离上，从而在横截面上形成独特的花瓣状表面运动轨迹。","scd":{"b":4.0,"i":1.0,"r":5.0,"d":4.0,"t":5.0},"kp":["运动驱动机制[布氏锥虫螺旋运动]: 鞭毛顺时针跳动产生右旋螺旋波，以螺旋钻方式推进细胞"]},{"i":38665,"as":"A2AR是抑制炎症或缺氧微环境中CD8+ T细胞活化的关键免疫调节受体。研究利用A2AR-eGFP报告小鼠发现，在慢性抗原暴露和缺氧条件下，A2AR的持续表达通过经典的Gαs-cAMP-PKA通路导致T细胞末端耗竭。然而矛盾的是，A2AR缺失并不能缓解T细胞耗竭，反而会加速其向耗竭状态的分化进程。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":[]},{"i":38666,"as":"","scd":null,"kp":[]},{"i":38667,"as":"","scd":null,"kp":[]},{"i":38668,"as":"针对难熔高熵合金（RHEAs）在极端温度下强度与延展性难以兼顾的问题，研究提出“高熵+稀释”设计策略。该策略通过反向本征应变溶质配对法则，将具有相反局部体积应变的溶质结合。具体而言，在基体中加入1.5 at.%的替代型铼（局部收缩）和0.3 at.%的间隙型硼（局部膨胀），协同放大了局部晶格畸变，使合金在77 K至1373 K的宽温域内保持坚固且具有延展性。","scd":{"b":9.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["适用温度范围[“高熵+稀释”策略设计的耐火高熵合金]: 77 至 1,373 K","[单相体心立方耐火高熵合金]: 传统强化通常以牺牲延展性为代价","结构强化与延展机制[高熵+稀释策略]: 结合高熵基体与目标微合金化，细化为相反本征应变固溶强化机制"]},{"i":38669,"as":"","scd":null,"kp":[]},{"i":38670,"as":"NASA啮齿动物研究20任务评估了42天太空飞行对雌性生殖系统及跨代后代的影响。结果显示，返回地球后5天交配的雌性虽成功怀孕，但繁殖力略有下降。更重要的是，太空飞行母鼠的F1代后代在生长、功能和行为上与对照组存在显著差异，且这些异常表现延续到了F2代，表明长期太空飞行对雌性生殖及跨代发育存在实质性影响。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["太空飞行暴露时间[NASA Rodent Research 20任务]: 42 天","[长期太空飞行(42天)]: 对雌性生殖系统及F1/F2后代的行为、代谢和功能结果产生跨代影响"]},{"i":38671,"as":"时空晶体是一种在空间和时间上自发形成周期性有序状态的物质相。研究首次在宏观实验中直接观察到了经典连续时空晶体的三阶段熔化过程。实验利用2+1维时空中的宏观活性颗粒圆盘，通过自发形成可维持近一天的刚性二维三角晶格旋转实现时空晶体。通过调节噪声等因素，研究揭示了时空晶体熔化的底层物理机制。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":5.0,"t":6.0},"kp":["[连续时空晶体维度]: 2+1时空维度","[晶格结构类型]: 二维三角晶格","[相干刚体旋转状态]: 持续近一天","[抗噪能力]: 对噪声保持显著鲁棒性","[可调控制参数]: 圆盘堆积分数"]},{"i":38672,"as":"","scd":null,"kp":[]},{"i":38673,"as":"为解决活体生物内快速动力学过程成像的难题，研究提出一种单次宽视场红外显微光谱技术。该技术利用红外共振三阶和频过程将红外光转换为可见光信号，每一帧图像仅由一对持续约一皮秒的激光脉冲捕获。该方法有效最小化了运动模糊，实现了高达1 kHz帧速率的单次生化成像，成功展示了活体状态下的单次成像能力。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":6.0},"kp":["成像帧速率[单次宽视场红外微光谱]: 1 kHz","激光脉冲持续时间[单次成像]: 约 1 皮秒"]},{"i":38674,"as":"","scd":null,"kp":[]},{"i":38675,"as":"","scd":null,"kp":[]},{"i":38676,"as":"在极端电解质约束下，传统的局部电中性假设失效，导致空间电荷积累和缓慢的静电弛豫主导界面动力学。研究引入了一种固定电荷选择性的中间相，利用不动的阴离子电荷替代移动的电解质阴离子作为主要电荷补偿物。使用葡萄糖衍生网络模型证实，这种局部固定电荷机制确立了化学编码的静电边界条件，实现了阳离子选择性传输，并成功抑制了纳升约束下由空间电荷驱动的低效率问题。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["空间电荷效应触发条件[极端电解液约束下的界面离子传输]: 特征传输长度接近德拜屏蔽长度","离子传输抑制机制[纳升级约束界面]: 引入固定电荷选择性的中间相（含有不可移动离子）来同步离子传输"]},{"i":38677,"as":"受生物系统瞬时激活态调节光化学功能的启发，研究开发了一种基于时间门控的分子平台。该系统整合了质子响应的电荷转移复合物（CTC）敏化剂和二芳基乙烯光开关。CTC的可逆质子化实现了对三线态敏化光致变色的化学门控，并与耗散的pH调节网络耦合产生瞬时激活窗口。这使相同的物理光学刺激在化学演变的不同阶段能产生不同的结果，有效实现了自适应光化学响应的化学门控。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["光化学时间门控机制[瞬时激活分子平台]: 由动态pH演化控制质子响应电荷转移络合物（CTC）敏化剂以实现可见光化学的门控"]},{"i":38678,"as":"研究合成并表征了一种基于[3]索烃架构的多组分分子机器。该系统由两个冠醚大环和一个带有三个识别位点（铵基、联吡啶基和三唑基）的轴组成。通过施加特定的化学和电化学输入序列，能够精确控制两个大环的位置，使其在相邻站点、同一站点或轴的两端分布。这一精密控制机制实现了分子机器的精准开关切换与耦合运动。","scd":{"b":7.5,"i":1.5,"r":6.0,"d":5.0,"t":5.0},"kp":["[3]索烃分子机器体系组成[动态耦合运动]: 两个冠醚大环和一个包含铵、联吡啶、三唑鎓三个识别位点的轮轴","分子开关机制[[3]索烃分子机器]: 两个冠醚大环在三个不同识别位点上的精确定位与可控切换"]},{"i":38679,"as":"烷基取代的内部炔烃在合成与药物化学中极具价值，但直接利用广泛存在的脂肪族伯胺作为烷基化试剂受限于强C(sp3)-N键。研究开发了一种在无金属条件下，利用N-杂环酰胺作为脱氮试剂，直接对脂肪族伯胺进行脱氨基炔基化的方法。该技术以炔基溴化物为偶联配偶体，无需对胺进行预活化即可实现C(sp3)-C(sp)键的高效形成。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["合成挑战与限制[脂肪族伯胺作为烷基化试剂]: 受限于C(sp3)─N键的键能强度","[脱氨基炔基化反应]: 实现了脂肪族伯胺的直接脱氨基炔基化以制备烷基取代的内炔烃"]},{"i":38680,"as":"开发动态有机磷光聚合物面临难以精确可逆控制凝聚态结构的挑战。研究提出利用离子驱动的聚合物链缠结作为通用策略，以直接重构分层结构并实现高可调谐的有机磷光。具体而言，钾离子可编程地桥接κ-卡拉胶内部的醚基和磺酸基，引发聚合物缠结和发色团聚集。这一方法有效控制了聚合物的分层重组，从而实现动态有机磷光发射。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[动态有机磷光聚合物调控]: 离子驱动的聚合物链缠结作为引导结构重组的通用策略"]},{"i":38681,"as":"水系锌离子电池中高效的锌离子去溶剂化与快速传质存在竞争关系。研究设计了一种基于C3对称三角形羧酸配体的氢键有机框架作为离子筛分界面，通过精确控制孔径与定制化学环境来调节锌离子去溶剂化行为。这种结合了缺电子三嗪核心的柔性HOF成功消除了去溶剂化与传质之间的权衡，从而稳定了锌负极。","scd":{"b":8.5,"i":2.5,"r":6.0,"d":5.0,"t":5.0},"kp":["[水系锌离子电池锌负极]: 利用基于C3对称三羧酸的氢键有机框架(HOF)解决离子去溶剂化与快速传质之间的权衡"]},{"i":38682,"as":"研究开发了一种稳健的含氟吡啶氢化方法。该方法利用廉价的多相Pd/C催化剂，在耐受空气和湿度的条件下，对带有CF3、CF2H和CF2CO2Et基团的多种吡啶进行催化加氢，合成高度功能化的氟化哌啶。反应实现了良好的非对映选择性，最高产率达98%，并已通过克级规模制备验证了其合成实用性。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["催化剂[含CF3、CF2H或CF2CO2Et基团的吡啶氢化反应]: 非均相Pd/C","[合成条件]: 空气和水分耐受（无需严苛无水无氧环境）"]},{"i":38683,"as":"针对电合成过氧化氢面临的反应动力学迟缓和竞争性4电子路径选择低的问题，研究通过液相纳秒脉冲激光烧蚀技术设计了一种多金属气凝胶。以CrMnFeCoNi高熵合金纳米颗粒为模型，并对比了三种四元体系。结果表明，CrMnFeCoNi高熵合金气凝胶展现出最高的电催化性能，其H2O2选择性达到95%，可有效用于生产H2O2和水脱色。","scd":{"b":8.0,"i":2.5,"r":6.0,"d":6.0,"t":5.0},"kp":["催化剂[H2O2电合成与水脱色]: 纳秒脉冲激光烧蚀合成的CrMnFeCoNi高熵合金(HEA)气凝胶纳米颗粒","[H2O2电合成抑制]: 竞争性的4e-反应路径"]},{"i":38684,"as":"针对锂硫电池中多硫化物穿梭效应和缓慢的氧化还原动力学问题，研究开发了一种蛋黄-蛋壳结构的MoO3/Co3O4@C纳米反应器。该材料利用氧桥诱导的轨道振荡打破溶剂化势垒，加速界面转化。Mo-O-Co氧桥的动态振动通过4d轨道引导电子流，实现了无溶剂化势垒的硫氧化还原反应动力学，显著提升了电池性能。","scd":{"b":8.5,"i":2.5,"r":6.0,"d":6.0,"t":5.0},"kp":["[锂硫电池穿梭效应与迟缓动力学]: 开发蛋黄-壳结构的MoO3/Co3O4通过氧桥诱导自旋态工程消除溶剂化势垒"]},{"i":38685,"as":"研究开发了一种镍催化未活化烯醇的1,2-芳基烯基化方法。该方法以烯基硼酸酯和芳基碘化物为反应物，直接利用底物固有的羟基作为导向基团，无需预先安装辅助基团。反应条件温和，具有广泛的官能团耐受性和优异的区域选择性，能够高效构建结构多样的烯醇衍生物。机理研究与DFT计算揭示了Ni(0)/Ni(I)/Ni(II)的催化循环过程。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["催化剂[未活化烯烃的1,2-芳基烯基化反应]: 镍","[催化机制]: 利用天然羟基作为固有定位基团，无需预装辅助基团"]},{"i":38686,"as":"为解决熔融加工聚合物中酶易失活的难题，研究提出一种金属有机框架（ZIF-8）门控的生物催化策略。将酶封装在ZIF-8中，使其在180°C下处理2分钟后仍能保留85%以上的活性，并能调节底物的进入。该生物复合材料日产量可达50公斤，已成功通过双螺杆挤出机混入PCL、PBAT和PLA等聚酯中，所得颗粒适用于标准热成型，并能引发解聚。","scd":{"b":8.0,"i":7.0,"r":8.0,"d":9.0,"t":8.0},"kp":["[熔融加工聚合物触发解聚]: 金属有机框架(MOF)门控生物催化（将酶封装于ZIF-8中）","酶活性保留[酶@ZIF-8生物复合材料在180°C熔融挤出2分钟后]: >85%","生产规模[酶@ZIF-8生物复合材料]: ~50 kg/天"]},{"i":38687,"as":"研究开发了一种串联催化系统，将CO2加氢生成的中间体与二元羧酸进行原位酯化，直接生成聚酯单体（如PET的合成原料），目标产物选择性超过99%。该系统采用金属有机框架衍生的催化剂，其特征是碳限域的单原子Cuδ+位点锚定在约1.8纳米的四方相ZrO2纳米颗粒上，成功在一锅中实现了CO2加氢与酯化反应的高效耦合。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":7.0,"t":8.0},"kp":["选择性[CO2加氢与原位酯化一锅法串联制备聚酯单体]: >99%","催化剂[CO2加氢与原位酯化反应]: 单原子Cuδ+掺杂的T-ZrO2","特征尺寸[单原子Cuδ+掺杂的T-ZrO2]: 1.8 Nm"]},{"i":38688,"as":"室温钠硫电池受限于迟缓的硫氧化还原动力学，特别是后期Na2S4转化为Na2S2及Na2S的阶段。研究提出一种阶梯靶向的串联催化策略，在导电碳载体中整合了原子级分散的Fe-N4位点与极性ZrO2纳米域。该催化剂设计有效克服了速率决定步骤的动力学限制，加速了多步硫转化级联反应，显著提升了室温钠硫电池的性能。","scd":{"b":7.0,"i":4.0,"r":8.0,"d":7.0,"t":8.0},"kp":["[室温钠硫电池动力学限制]: 串联催化用于克服后期决定速率的硫转化级联(Na2S4→Na2S2→Na2S)"]},{"i":38689,"as":"针对复杂笼状结构计算设计中的无偏预测需求，研究在cgx软件中引入了探索算法和低成本最小模型，开发了无偏结构预测工作流。该工作流仅需实验构建块类型、特征及其化学计量比作为输入，即可预测所有可能的结构候选。与实验数据对比表明，该方法能够在进行昂贵的实验之前预测笼状结构，为高效、自动化的新材料发现提供了解决方案。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":5.0,"t":7.0},"kp":["[复杂笼状结构预测]: cgx软件中利用探索算法和低成本最小化技术实现无偏结构预测工作流"]},{"i":38690,"as":"研究报道了质量数在160附近的钬（Z=67）和铒（Z=68）同位素的高自旋结构。在原子核实验可达到的最高自旋状态下，集体激发和单粒子激发模式相互竞争以产生角动量。能级图的实验分析揭示了这些同位素中多价空间和核心激发导致的能带终止现象。","scd":null,"kp":[]},{"i":38691,"as":"本文是对此前发表于《Physical Review C》第112卷第034614期（2025年）题为“高能中子发射和短程核子-核子相关性”一文的勘误表修订。作者为R. Wada、Q. Hu等人。该勘误仅对原文中的部分内容进行了修正。","scd":null,"kp":[]},{"i":38692,"as":"研究提出了一种物理嵌入式贝叶斯神经网络（PE-BNN）框架，用于预测具有精细结构的能量依赖性裂变产物产量（FPY）。该框架将先验核物理知识与已有的FPY数据相结合，通过引入与壳相关的现象学输入特征和激发能参数进行训练。该方法有效提升了预测的准确性，揭示了裂变产物产量随能量变化的精细特征。","scd":null,"kp":["预测框架[裂变产物产量能量依赖性]: 物理嵌入式贝叶斯神经网络(PE-BNN)","[精细结构预测]: 结合裂变产物产额(FPYs)与先验核物理知识(如壳相关的唯象输入特征)"]},{"i":38693,"as":"在核多体理论中，大规模特征值问题的求解至关重要，因为哈密顿量矩阵的维度极大。量子计算为解决此类问题提供了新途径。研究探讨了利用D波量子退火器，通过求解运动方程的声子法特征值问题，来处理核物理中的大规模特征值问题，展示了量子退火技术在处理复杂大规模哈密顿量矩阵方面的潜力与应用。","scd":null,"kp":["[大规模特征值问题求解]: 采用量子相位估计算法在D波量子退火器中求解哈密顿矩阵","[核多体理论]: 涉及超大维度的哈密顿矩阵处理"]},{"i":38694,"as":"传统观点认为原子核的八极形变主要归因于相反宇称的单粒子轨道之间强烈的Δl=3耦合。本研究表明，常被忽略的Δl=1模式同样发挥着重要作用。通过分析八极幻数附近的单粒子轨道，研究证明了Δl=1单粒子轨道的耦合对核八极形变的形成具有显著贡献，深化了对核形变微观机制的理解。","scd":null,"kp":["[八极变形核机制]: 揭示了常被忽视的Δl=1单粒子轨道耦合同样起重要作用"]},{"i":38695,"as":"侏儒偶极子共振（PDR）的同位旋特性和集体性是核结构研究中的长期未解之谜。研究利用Skyrme粒子-振子耦合模型，详细考察了Pb-208中PDR状态向低能级2+态的γ衰变现象。通过对衰变过程的分析，揭示了侏儒偶极子共振态的同位旋属性与其集体行为特征，为理解核结构的复杂性提供了新见解。","scd":null,"kp":["[侏儒偶极子共振(PDR)结构探测]: 通过γ衰变探测PDR状态的同位旋性质和集体的相关性"]},{"i":38696,"as":"自1980年以来，全球强烈热带气旋的季节持续时间正在延长。统计显示，所有海域的强烈气旋季节长度每十年增加9.9至13.8天，相当于每十年增加7.4%至21.9%。这一现象的主要原因是气候变暖使得季外热带气旋发生快速增强的概率显著提升。这一趋势对人类生命财产安全及社会经济的长期影响值得警惕。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[强烈热带气旋季节]: 受气候变暖影响在全球范围内呈现延长趋势"]},{"i":38697,"as":"地下水硝酸盐污染严重威胁饮水安全。模型显示，截至2020年，浅层含水层累积了162±6 Tg的硝酸盐氮，全球10%的陆地面积超标。这是由于包气带存在高达4037±214 Tg氮的庞大硝酸盐库，形成了持续数十年的“长尾”淋溶效应。即使立即实现氮零排放，仍有4%的区域在2100年后无法达标。研究将全球农田分为四种类型以指导治理。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":9.0,"t":6.0},"kp":["浅层地下水硝酸盐累积量[截至2020年]: 162 ± 6 Tg N","包气带硝酸盐储层[全球地下水]: 4037 ± 214 Tg N","饮用水安全超标面积[全球超过WHO限值的陆地面积比例]: 10%"]},{"i":38698,"as":"中更新世过渡期（约1200-650ka）地球冰期循环转变为10万年周期。伊比利亚边缘西南部的高分辨率花粉记录结合气候模型表明，该过渡期经历了三个阶段。受夏季日照幅度影响，西风带发生南北移动：早期北移促进冰雪消融；中期因风化层流失及极端天气减弱而南移，引发大干旱并加速冰川累积；晚期北移最终确立了长期冰川周期。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["[中更新世过渡期气候演变]: 呈现受北半球夏季日照幅度驱动的三阶段演化"]},{"i":38699,"as":"研究设计了一种模块化的手性螺环单膦配体，巧妙结合了吸电子基团、季碳部分和刚性螺环支架，解决了C(sp3)杂化碳负离子配体金属络合物不稳定的长期难题。该配体成功实现了β,β-二取代丙烯酸盐的直接不对称氢化反应。这一合理设计有效调节了配体的空间和电子性质，具有优异的催化性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[手性配体设计]: 采用C(sp3),P-螯合铱环形成模块化手性螺环支架以克服C(sp3)-金属络合物的固有不稳定性","[β,β-二取代丙烯酸盐]: 实现直接不对称氢化反应"]},{"i":38700,"as":"针对固态锂金属电池中传统固态电解质离子传导缓慢及界面不稳定的缺陷，研究提出构建基于乙烯基连接的共价有机框架多孔复合聚合物电解质。TFP-COF中强极性的-C≡N和-F部分与锂离子形成多重强离子-偶极相互作用，降低了锂盐解离势垒，引导锂离子定向传输并形成稳定的SEI层，显著加速了离子传输过程。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[固态锂电池复合电解质]: 采用乙烯基连接的共价有机框架（TFP-COF@PNFs CPEs）构建","[离子-偶极相互作用]: 利用TFP-COF中强极性的-C≡N和-F部分形成多重强离子-偶极相互作用以加速离子传输"]},{"i":38701,"as":"该研究开发了一种由催化剂控制的立体选择性开环聚合方法，用于合成含有乙烯基、烯丙基和炔丙基等官能团的聚羟基脂肪酸酯（PHA）。该技术合成的高间同立构聚合物，其间同立构规整度（Pr）最高可达0.95，且具备宽泛的玻璃化转变温度和熔融转变温度范围，玻璃化转变温度（Tg）可低至-31°C。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[功能化聚羟基脂肪酸酯(PHA)]: 通过催化剂控制的立体选择性开环聚合和定制后转化合成","[聚合单体]: 使用功能化的丙内酯进行开环聚合"]},{"i":38702,"as":"针对偏置电压下有机光电探测器（OPD）暗电流密度（Jd）难以抑制的挑战，研究团队开发了一种短波红外有机光电探测器（SWIR-OPD）。该器件采用新型窄带隙p型聚合物作为短波红外吸收材料，使器件在高偏置电压下实现了超低暗电流密度，为构建高性能短波红外光电探测器提供了新的材料平台。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[短波红外有机光电探测器]: 需在偏置工作条件下实现超低暗电流密度(J_d)以获得高探测率"]},{"i":38703,"as":"研究报道了一种由3,3'-亚甲基二苯二胺（3,3-MDPDA2+）构建的二铵基非Dion-Jacobson（DJ）相二维钙钛矿。这种材料打破了传统认为有机二铵必然形成DJ相二维钙钛矿的认知。该新型二维钙钛矿具有高耐久性，被成功应用于构建高效且稳定的二维/三维钙钛矿太阳能模块。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[二铵基非Dion-Jacobson相2D钙钛矿]: 打破常规有机双铵必然形成DJ相钙钛矿的认知，表现出高耐久性","[2D/3D钙钛矿太阳能模块]: 具备高效和高稳定性"]},{"i":38704,"as":"研究设计并合成了一种用于对映纯二硫代内酯立体选择性开环聚合的共价硼烷-硫脲有机催化剂。传统催化剂常因α-氢酸性导致单体消旋，从而阻碍高有规立构结晶材料的合成。该新型催化剂通过引入强路易斯酸有效克服了这一立体化学挑战，为合成化学可回收的高性能聚硫酯提供了方法。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[开环聚合有机催化剂]: 采用共价硼烷-硫脲催化剂实现高立体选择性","[聚硫酯合成]: 克服因α-氢酸性引起的单体消旋问题，实现化学可回收的高性能材料合成"]},{"i":38705,"as":"研究开发了一种差分图像传感器（DIS），利用解耦的差分和隧穿模式，在传感层级完整获取并解耦静态（亮度）与动态（振幅和极性）输出。这些模式可通过常规读出集成电路读取，实现了如640×512规模的阵列集成。该传感器通过按需激活后端视觉功能，优化了机器视觉的能耗与性能平衡。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[差分图像传感器架构]: 结合低功耗待机前端和按需激活后端的分级处理架构","[传感层级特征提取]: 实现静态（亮度）和动态（幅度与极性）输出的完全采集与解耦"]},{"i":38706,"as":"为解决CO2电还原为正丙醇过程中C1-C2耦合缓慢及中间产物不稳定的问题，研究提出了一种基于富含缺陷的非晶ZrO2的准串联催化策略。这种非晶氧化物-金属界面环境能够促进*CO的生成、稳定含氧C2中间体（*OCCOH），并促使后续C-C键耦合形成正丙醇，展现出优异的催化效果。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[CO2电还原C3产物]: 利用跨界面准串联催化策略引导生成正丙醇","[非晶氧化物-金属结]: 使用富含缺陷的非晶ZrO2结构解决C1-C2耦合迟缓和含氧中间体不稳定的问题"]},{"i":38707,"as":"研究将一种基于串联动态键的单体（ADM）引入钙钛矿薄膜中，通过原位交联控制薄膜的成核和结晶。ADM与钙钛矿晶格通过路易斯碱配位和氢键实现多模式钝伏。交联网络内的动态键分布于晶界处，赋予了柔性钙钛矿薄膜在温和条件下的瞬时自修复能力，从而实现了稳定且可扩展的柔性钙钛矿太阳能电池及模块。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["自修复支架[柔性钙钛矿太阳能电池]: 具有定制动态键的串联动态键基单体（ADM）","薄膜特性[钙钛矿薄膜交联]: 原位交联控制成核和结晶，实现多模态钝化"]},{"i":38708,"as":"研究提出了一种可持续的电催化策略，用于升级处理富含亚硫酸盐的工业废水。该系统在环境条件下，使用商业镍催化剂并以甲醇为代表性原料，将废水中的亚硫酸根（SO3^2-）直接电化学转化为高附加值的磺酸盐类分子，克服了传统处理方法效率低、二次排放和硫资源流失的缺陷。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":6.0},"kp":["电化学 valorization[工业废水亚硫酸盐]: 可持续电化学转化为磺酸盐基分子"]},{"i":38709,"as":"研究提出了一种基于化学气相沉积（CVD）的选择性非均匀成核策略，实现了对室温铁磁性CrTe纳米片的受控非均匀生长。该策略利用厚度分布与磁化反转之间的强关联，实现自下而上的磁畴演化控制。多厚度纳米片中的阶梯式磁化反转赋予了CrTe多重磁状态，成功实现了可调的多态磁阻。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["材料体系[核心条件]: 室温铁磁CrTe纳米片","器件应用[核心条件]: 高密度自旋电子存储器（多状态存储器）","制备工艺[核心条件]: 化学气相沉积（CVD）选择性非均匀成核策略","生长机制[核心条件]: 受控的非均匀生长与自下而上的畴演化控制"]},{"i":38710,"as":"研究报道了一种基于手性连接体交换构建的金属有机框架（MOF）发光传感策略，用于对映选择性识别。该方法在框架中同步引入了手性和缺陷位点，构建的发光手性缺陷MOF具有受限的纳米孔环境，能对对映体产生截然不同的发光响应。构建的一对对映异构MOF对R-型和S-型底物表现出完全相反的选择性识别性能。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["对映选择性识别[发光传感策略]: 非手性MOF通过手性连接体交换引入手性和缺陷位点"]},{"i":38711,"as":"研究开发了单片三维集成的全固态离子门控碳纳米管晶体管（CNT sIGTs），完全兼容晶圆级薄膜工艺。通过薄膜中的离子含量工程及厚度缩减至亚微米级，实现了离子电导率的宽范围调节，使离子时间常数涵盖微秒至毫秒级。该器件在低离子含量下实现了稳健的直流操作，可用于多时间尺度的储备计算。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["成核策略[室温铁磁性CrTe纳米片]: 通过化学气相沉积实现选择性非均匀成核","[二维磁体多状态存储器]: 自下而上控制畴演变和厚度工程生长"]},{"i":38712,"as":"研究通过约翰逊-科里-柴可夫斯基反应，由环丁烷、氧杂环丁烷和氮丙啶取代的锍盐与氮丙反应，合成了一类新型“超应变”螺杂环化合物——螺环1-氮杂双环[1.1.0]丁烷。该类超应变螺环是制备高度官能化的1-氮杂螺[3.3]庚烷衍生物的合适前体。此类衍生物在药物化学中可作为构象受限的三维生物电子等排体。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":4.0,"t":6.0},"kp":["螺杂环化合物[药物化学构象刚性]: 一类新型超应变1-氮杂螺[3.3]庚烷衍生物","[生物等排体验证]: 哌啶生物等排体"]},{"i":38713,"as":"研究报道了两种具有不同空腔结构（三棱柱空腔和碗状空腔）的咪唑鎓功能化阳离子共价有机笼，作为限域平台用于无氧化剂的Hofmann–Löffner–Freytag（HLF）/环化串联催化反应。这两种有机笼均能在温和条件下，高效介导N-氯代酰胺一锅法转化为吡咯烷衍生物，实现了高位点选择性的自由基级联过程调控。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":4.0,"t":6.0},"kp":["限域催化[自由基级联过程]: 咪唑鎓功能化阳离子共价有机笼调控高位点选择性","催化反应[Hofmann−Löffner−Freytag/环化序列]: 无氧化剂条件"]},{"i":38714,"as":"研究通过拓扑转化策略在掺硫且含碳空位的空心碳基质上合成了铁单原子催化剂（Fe SAs/NSCv）。原位光谱分析证实，FeN4位点第二配位壳层的硫杂原子及相邻的碳空位通过配位和电荷调节实现了轨道杂化，加速了反应动力学。该催化剂表现出卓越的氧还原（ORR）活性和稳定性，配备于水系锌空气电池中展现出极高的功率密度。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["催化剂[氧还原反应(ORR)]: S掺杂空心碳基质上的铁单原子(Fe SAs/NSC_V)","合成策略[拓扑转变]: 引入碳空位实现配位和电荷调节的轨道杂化"]},{"i":38715,"as":"研究报道了一种化学可编程的视黄质GaN p-n二极管，能够在超紧凑器件平台上支持脉冲响应、光适应以及化学可调谐性。该器件的机制由内部p-n结的光电载流子分离以及半导体/电解质界面的电化学载流子消耗共同主导。该二极管有效克服了传统视觉传感器缺乏化学可编程性的局限，适用于多模态视觉传感。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["视觉传感器[多模视觉传感]: 化学可编程视黄质GaN p-n二极管"]},{"i":38716,"as":"研究采用操作发光测温法（LT）测量了甲烷氧化偶联（OCM）反应过程中的局部催化剂温度。分析显示，在惰性条件下催化剂的局部温度比反应炉温度高出近250°C。该技术成功揭示了OCM反应的剧烈局部放热效应，证实了局部温度对反应产热量的依赖关系，为理解该反应过程提供了温度参数。","scd":{"b":5.5,"i":2.5,"r":6.0,"d":5.5,"t":4.5},"kp":["测温方法[甲烷氧化偶联(OCM)局部放热效应]: 操作发光测温法"]},{"i":38717,"as":"针对硫化物固体电解质（SEs）对水分敏感的问题，研究提出了一种简单低成本的癸酸脂肪酸（DA）涂层策略。该涂层使得Li6PS5Cl（LPSCl）在39%的相对湿度下暴露长达2小时后，仍能保持结构完整和离子电导率，并提高了其阳极稳定性。使用2 wt% DA涂层的LPSCl作为正极电解质，搭配NCM85正极和Li-In负极的电池，容量达到175 mAh/g。","scd":{"b":6.5,"i":3.5,"r":6.0,"d":6.5,"t":4.5},"kp":["涂层策略[硫化物固体电解质]: 癸酸脂肪酸涂层","[Li6PS5Cl表面改性]: 提升水分稳定性并改善与高压正极的氧化稳定性"]},{"i":38718,"as":"研究提出了一种协同控制反向系间窜越（rISC）和激子循环的策略，打破了热激活延迟荧光（TADF）在动力学上的限制。该策略在保持反向系间窜越速率远大于磷光和非辐射衰减速率的前提下，同步减缓了rISC速率。这种方法成功实现了寿命长达1.0秒的持久型热激活延迟荧光。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.5},"kp":["热激活延迟荧光寿命[p‐TADF体系]: 1.0 s","[激子循环与反向系间窜越]: 协同控制策略减缓rISC过程并克服动力学权衡"]},{"i":38719,"as":"研究引入了偏压触发电导率弛豫（BCR）作为一种新颖的工具，用于同时研究混合离子-电子导体（MIEC）薄膜中氧还原反应的热力学、动力学和静电效应。常规技术难以在同一样品测量中揭示全貌，而BCR技术克服了这一局限，能够同步获取离子/电子缺陷浓度等热力学属性、动力学过程及静电表面效应。","scd":{"b":5.5,"i":2.0,"r":6.0,"d":4.5,"t":4.5},"kp":["[偏压触发电导率弛豫(BCR)]: 可同时解析MIEC薄膜中氧反应的热力学、动力学和静电效应"]},{"i":38720,"as":"研究开发了一种分步组装协议，通过六价阳离子笼（TPBCage^6+）与葫芦[8]脲（CB[8]）的非共价结合，构建了一种深红色发光的“笼中环”复合生物成像探针（TPBCage^6+⊂3CB[8]）。该复合物在热力学上具有优势，兼具生物相容性、长波长发射和固有的靶向选择性，成功应用于溶酶体成像。","scd":{"b":5.5,"i":2.0,"r":6.0,"d":4.5,"t":4.5},"kp":["发射波段[生物成像探针]: 深红区发射","探针结构[溶酶体成像]: 环笼复合物"]},{"i":38721,"as":"研究采用胶体合成技术制备了UOS、UOSe和β-US2纳米材料，这是首批含铀硫属元素纳米材料。研究通过分析金属、硫属源和溶剂试剂来理解溶液中的相形成机制，并利用消化熟化这种合成后修饰方法实现了β-US2纳米粒子尺寸的控制。粉末X射线衍射和Rietveld精修分析确认了产物物相。","scd":{"b":6.0,"i":1.5,"r":6.0,"d":5.0,"t":4.5},"kp":["合成技术[锕系纳米材料]: 胶体溶液合成法","[铀硫属化合物]: 首次成功合成UOS、UOSe和β-US2纳米材料并有效抑制二氧化铀的生成"]},{"i":38722,"as":"研究通过在新型及中性镍催化剂中引入Ni…O相互吸引作用，解决了乙烯与一氧化碳非交替共聚生成酮基聚乙烯时催化剂对一氧化碳耐受性有限的问题。该技术成功实现了长波长响应的光开关，为减少聚乙烯废物的环境影响并提升其可回收性提供了有效途径。","scd":{"b":7.0,"i":2.5,"r":6.0,"d":5.5,"t":4.5},"kp":["[催化共聚反应]: 利用Ni...O相互作用实现非交替的乙烯-一氧化碳共聚"]},{"i":38723,"as":"研究提出了一种电子结构导向的金属有机框架孔工程策略，用于分离物理尺寸极为相似的六氟丙烯(C3F6)和八氟丙烷(C3F8)。该策略利用Jahn-Teller活性的Cu2+离子引导框架重构，实现微量C3F6的精准去除，从而生产出高纯度的氟化电子气体。","scd":{"b":6.5,"i":2.5,"r":6.0,"d":5.5,"t":4.5},"kp":["[金属有机框架孔工程]: 电子结构导向的孔工程策略实现C3F6/C3F8的高效分子筛分"]},{"i":38724,"as":"研究利用拓扑受限的超分子相互作用，改善了靛蓝光开关在机械互锁结构中的性能。这种策略克服了传统分子间相互作用在稀释或复杂环境中受限的缺陷，成功实现了光开关向长波长（红光/近红外光）响应的红移，并有效提升了其热半衰期。","scd":{"b":6.0,"i":1.5,"r":6.0,"d":4.0,"t":4.5},"kp":["响应波长[光电开关]: 长波长（红光/近红外光）响应","[靛蓝光电开关]: 采用机械互锁结构实现红移并提升热半衰期"]},{"i":38725,"as":"针对钠离子电池硬碳阳极初始库仑效率低和不可逆容量损失的问题，研究提出一种软接触预沉积(SCP)钠补偿方法。该方法能够去除并回收残余钠源，不仅大幅提升了钠源的利用率和电池安全性，还使硬碳阳极的初始库仑效率提高了约30.0%。","scd":{"b":6.0,"i":3.5,"r":6.0,"d":6.0,"t":4.5},"kp":["[硬碳阳极预钠化]: 采用软接触预沉积策略实现吸附介导的钠补偿，有效避免表面残钠引起的安全与退化问题"]},{"i":38726,"as":"研究在基于多金属氧酸盐(POM)的生色团中首次实现了二阶非线性光学(NLO)响应的电化学开启。在POM-酰亚胺基芳基-NO2衍生物中，POM的还原过程引发了高达15倍的散射光倍频强度增加。计算与光谱研究表明，氧化态下相反方向的电荷转移导致了低净响应。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["倍频光散射强度增强[硝基芳基酰亚胺多金属氧酸盐]: 最高提升15倍","[非线性光学响应]: 首次实现基于多金属氧酸盐的电化学控制二阶非线性光学开关"]},{"i":38727,"as":"研究开发出一种可编程的生物电子接口，实现了两种活体微生物间光驱动的直接种间电子转移(IET)。该界面利用整合在蓝藻包膜中的PED O网络拦截并传递光合电子流，同时通过超分子主客体相互作用精准编程细胞间的组装结构，突破了非生物材料的局限。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":5.0,"t":6.0},"kp":["生物电子接口[光驱动微物种间电子转移]: 可编程活体电子接口支持直接电子转移"]},{"i":38728,"as":"研究构建了一个耦合光热蒸发与淡水电解的创新制氢平台。基于氢键交联和阴离子诱导的霍夫迈斯特效应，设计了涂有改性针状焦凝胶的球形蒸发器。该系统在3.5 wt%盐水中表现出2.32 kg m⁻² h⁻¹的连续脱盐性能和耐盐自清洁能力，有效解决了海水直接电解中的腐蚀和失活问题。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["制氢平台[光热蒸发耦合水电解]: 轻量化球形蒸发器集成系统","界面机制[抗腐蚀与催化剂防失活]: 氢键交联与阴离子诱导的霍夫迈斯特效应"]},{"i":38729,"as":"","scd":null,"kp":[]},{"i":38730,"as":"","scd":null,"kp":[]},{"i":38731,"as":"这是针对2026年发表于《物理评论快报》第136卷176901期的《金属中非互易等离激元阻力的横向热光伏发电》一文的更正信息。","scd":null,"kp":[]},{"i":38732,"as":"提高反应堆中子学模拟的准确性需要精确掌握堆芯中子群的动力学行为。研究利用γ射线符合光谱技术，测量了中子在238U上发生的非弹性散射(n,xn)反应。该反应会改变中子数量并降低其能量，直接驱动反应堆中子群的演化。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":6.0,"t":6.0},"kp":["核反应[(n,xn)反应]: 改变中子数量并降低中子能量","[核反应堆中子学模拟精度]: 依赖于对堆芯中子群特性的深入了解"]},{"i":38733,"as":"研究探讨了转录因子NANOG的流变学特性，发现其在高浓度下会组装成具有自限性的老化胶束。这种胶束结构能够驱动体系发生溶胶-凝胶转变，并对DNA的动力学行为进行调节。该特性对维持胚胎干细胞的多能性具有关键作用。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":4.0,"t":6.0},"kp":["NANOG蛋白[高浓度自组装]: 形成自限制性老化胶束","流变学特性[驱动溶胶-凝胶转变]: 呈现非牛顿流体特征并调节DNA动力学"]},{"i":38734,"as":"研究提出了“轨道交变磁性”概念，这是一种由对称性保护的纯轨道自由度磁有序。其特征是在真实空间中具有有序的反平行轨道磁矩，但在动量空间中表现为依赖动量的轨道能带劈裂，这一物理现象与自旋交变磁性高度类似。","scd":{"b":9.0,"i":1.0,"r":7.0,"d":5.0,"t":6.0},"kp":["轨道交变磁性[纯轨道自由度]: 受对称性保护的磁序","轨道磁矩[实空间]: 呈有序反平行排列","能带劈裂[动量空间]: 表现出动量依赖的轨道能带劈裂"]},{"i":38735,"as":"交变磁性材料具有依赖动量的自旋能带劈裂和净磁化强度为零的特性，是下一代自旋电子学应用的重要候选者。研究利用Andreev反射技术，在交变磁性候选材料CrSb中直接探测到了依赖于动量的自旋极化现象。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["交变磁性[材料特性]: 动量依赖的自旋劈裂能带结构与零净磁化","探测方法[CrSb自旋极化态]: Andreev反射"]},{"i":38736,"as":"研究利用微聚焦角分辨光电子能谱(ARPES)技术，直接可视化了扭曲双双层石墨烯中莫尔微型能带在变化载流子浓度和位移场下的演化过程。该实验直接观测了门可调谐平带的微观物理机制。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":9.0},"kp":["[扭曲双双层石墨烯莫尔微带演化]: 载流子密度和位移场变化可通过微聚焦角分辨光电子能谱直接可视化"]},{"i":38737,"as":"在动能被淬灭的平带系统中，与能带色散相关的常规长度尺度大多失效。研究指出，尽管可定义量子度量长度等几何长度尺度，但这些尺度具有嵌入依赖性。研究详细阐述了平带系统中这种独立长度尺度的本质特性。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":5.0,"t":9.0},"kp":["动力学能量[平带系统]: 被猝灭","[平带系统特征长度尺度]: 传统色散特征长度失效，量子度量长度受嵌入依赖性影响"]},{"i":38738,"as":"手性破坏了对自然的左右对称性。研究在中心对称的2M-WS2材料中，探测到了由量子几何诱导的反常手性输运现象，如电子磁手性各向异性。该研究揭示了在宏观中心对称体系中隐藏的对称性破缺。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":9.0},"kp":["量子几何[反常手性输运]: 诱导反常手性输运并揭示中心对称破缺","非线性响应[手性材料]: 存在电子磁手性各向异性"]},{"i":38739,"as":"声子晶体中的耗散通常被认为对波传输有害。研究通过实验证实了一种反直觉现象：在声子晶体中刻意引入的耗散（固有材料吸收或向环境泄漏）不仅没有阻碍传输，反而显著增强了拓扑谷输运。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":9.0},"kp":["[声子晶体拓扑谷输运]: 耗散增强现象实验证实"]},{"i":38740,"as":"可扩展的量子信息处理要求以最少资源实现量子态读取。中性原子阵列依赖荧光读出，但短曝光会导致单光子级别的信号丢失。研究开发了一种神经网络辅助的贝叶斯量子比特读出方案，有效解决了单光子极限下的读取难题。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":7.0,"t":9.0},"kp":["读出平台[可扩展中性原子阵列]: 荧光读出","[单光子级量子位读出]: 神经网络辅助贝叶斯读出方案"]},{"i":38741,"as":"扩展版的平均场理论能够准确捕捉生物神经元网络中观察到的活动模式。该研究成果已发表于《物理评论快报》（Phys. Rev. Lett. 137, 018401），发表于2026年6月30日。","scd":{"b":5.0,"i":2.0,"r":7.0,"d":4.0,"t":9.0},"kp":["[真实神经元网络活动模式]: 扩展平均场理论精确捕捉"]},{"i":38742,"as":"本研究提出缺陷工程策略，合成了富含硫空位的Cu4SnS4-x纳米片。该纳米片具有优异的热电性能，并负载了小分子抑制剂NLG919。球差校正透射电子显微镜和X射线吸收精细结构揭示了其精细结构特征，使其具备高达64.7%的超高光热转换效率，可用于协同铜死亡、光热电催化和免疫治疗。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[PPECT治疗瓶颈]: 热电活性受限与肿瘤复发","催化剂[光热电催化及免疫治疗]: 富含硫空位的Cu4SnS4−x纳米片"]},{"i":38743,"as":"本研究引入了一种新型的ZnHfOx催化剂，用于二氧化碳加氢制备甲醇。在锌含量为20 mol%的条件下，该催化剂的本征甲醇生成速率超过了传统的ZnZrOx参考催化剂。此类混合金属氧化物在300°C以上的高温下仍能保持超过70%的甲醇选择性和良好的催化稳定性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["甲醇选择性[传统混合金属氧化物如ZnZrOx]: >70%","催化稳定性[传统混合金属氧化物如ZnZrOx]: 高温(>300°C)下保持稳定","催化剂[CO2加氢合成甲醇]: 新型ZnHfOx"]},{"i":38744,"as":"为克服单原子催化剂在氧还原反应（ORR）中受限的线性比例关系，研究受自然铁硫簇启发，设计了S桥连的Fe-Fe双原子催化剂（Fe2N6-S/SNC）。该催化剂中的硫桥充当了内在的电荷转移通道，实现了两个铁中心之间的强电子耦合，从而有效解决了缺乏直接电子桥和3d轨道局域化阻碍电子调控与轨道重叠的问题。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["催化剂[氧还原反应(ORR)]: S桥Fe-Fe双原子位点(DACs)","[打破线性比例关系]: 仿生电子耦合实现直接电子桥连与有效轨道重叠"]},{"i":38745,"as":"针对三维细胞培养中难以规模化制造超过毫米尺寸细胞球体的挑战，研究开发了一种毫米级刚性多孔胶囊（RPC）。该平台具有高机械稳定性和渗透性，通过施加外部几何限制促进细胞间聚集和三维增殖。RPC通过热处理由可熔的聚丙烯酸十八烷基酯（PODAc）微粒和不可熔颗粒组成的复合液体弹珠混合物制备而成。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["细胞3D培养平台[克服大尺寸球体制备瓶颈]: 复合液体弹珠模板化毫米级刚性多孔胶囊(RPC)"]},{"i":38746,"as":"受DNA碱基配对结构启发，研究开发出首个基于核苷的氢键有机框架（N-HOF-1）。该框架采用多氢键策略，仅需将2-氨基-2'-氟-2'-脱氧腺苷（2FA）和三聚氰酸（CA）在水中简单混合即可完全在水相中合成，成功克服了水分子竞争氢键导致水相HOF结构不稳定的挑战，解决了传统HOF依赖有机溶剂限制其生物医学转化的问题。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["材料框架[生物医学应用]: 亲水稳定核苷基氢键有机框架(N-HOF)"]},{"i":38747,"as":"高能锂金属电池（LMBs）对新一代储能和电动汽车技术至关重要，但传统电解质的化学限制和不良的界面动力学阻碍了其能量密度突破500 Wh kg-1。这些限制会导致锂枝晶形成、正极结构退化、电解质持续分解和界面恶化，损害电池性能。该综述总结了限制LMBs发展的基本挑战，并概述了理想电解质材料应具备的基本特征。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["能量密度[高能锂金属电池]: >500 Wh kg−1"]},{"i":38748,"as":"固态电热冷却技术的实际应用受限于无法在宽温度范围内实现大绝热温变（ΔTad）。本研究通过在弛豫铁电多层陶瓷电容器（MLCC）中进行B位中熵工程设计克服了此限制。设计的Pb(Sc0.25Ta0.25In0.25Nb0.25)O3 MLCC在不需要过高电场的情况下，展现出了巨大的直接测量温变效应。","scd":{"b":8.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["[弛豫铁电多层陶瓷电容器]: B位中熵工程实现巨宽温电热冷却"]},{"i":38749,"as":"水系锌电池（AZBs）的大规模储能应用受限于水系电解液中锌的自发腐蚀引起的日历老化。本研究提出一种悬浮电解质策略，仅在常规ZnSO4电解液中分散3 wt.%的Al2O3纳米颗粒，即可显著改善AZBs的日历老化性能。在日历老化测试方案下，添加Al2O3的Zn||Cu电池表现出更好的性能。","scd":{"b":7.0,"i":4.0,"r":4.0,"d":6.0,"t":5.0},"kp":["悬浮电解质策略[水性锌电池日历老化抑制]: 分散3 wt.%的Al","体系优势[大规模储能水性锌电池]: 高安全性与成本效益"]},{"i":38750,"as":"采用硫族化物阴极的全固态电池具有高理论能量密度，但受限于缓慢的固态反应动力学。具有丰富活性位点、多样原子环境和强电子协同效应的高熵合金（HEA）催化剂是解决此问题的有效策略。本研究提出一种d-p能级匹配策略，通过将HEA催化剂的d带与硫族阴极的p带对齐，有效增强了催化性能。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":5.0,"t":5.0},"kp":["应用策略[全固态电池硫族阴极迟缓动力学]: 采用高熵合金(HEA)催化剂提供丰富活性位点和强电子协同效应","[d-p能级匹配]: 实现高熵合金催化剂与硫族阴极之间的能级匹配"]},{"i":38751,"as":"全无机钙钛矿CsPbI3是具潜力的光伏吸收体，但其溶液沉积常用的碘化二甲基铵（DMAI）在结晶时难以去除并会导致高缺陷密度。本研究引入基于2,2,2-三氟乙基三氟乙酸酯（TFTF）的反应引导结晶策略，TFTF在退火过程中与DMAI发生快速的酯-胺酰胺化反应，将DMAI转化为高挥发性物质，从而加速CsPbI3的形成并减少缺陷。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":5.0},"kp":["结晶工艺痛点[CsPbI3钙钛矿溶液沉积]: 移除二甲胺碘化物(DMAI)面临挑战，易引入残留"]},{"i":38752,"as":"细胞能量代谢破坏是导致多种人类疾病的核心因素。由线粒体和类囊体工程化改造而成的人工生物能细胞器，通过恢复细胞能量稳态提供了一种变革性治疗方法。它们作为自主代谢模块，能够在原位生成ATP、还原当量和氧气，同时调节氧化还原平衡、氧张力和免疫代谢信号传导，以恢复细胞稳态。","scd":{"b":8.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["人工生物能细胞器[细胞能量代谢失衡干预]: 由线粒体和类囊体工程化构建以恢复细胞能量稳态"]},{"i":38753,"as":"发光分子晶体中的固态相变是将分子水平的微小相互作用转化为宏观功能响应的重要平台。研究人员设计了带有溴和甲氧基侧链的氰基-β-取代二苯乙烯基苯衍生物，其具有竞争性的同源和异源非共价相互作用。单晶分析表明，分子间相互作用层次排列的细微差异会导致多晶型结构-性质切换行为。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["发光分子晶体[多晶型结构-性质切换行为]: 由竞争性分子间相互作用驱动"]},{"i":38754,"as":"生物系统利用亚稳态来实现相分离。研究表明，当热力学稳定的构建单元与其热力学活化前体的放热降解过程相耦合时，能够发生相分离。纯粹的热力学稳定产物无法直接形成液滴，这种化学转化是实现路径控制的相分离的关键，并且该相分离过程反过来对化学转化起到催化作用。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["相分离机制[热力学稳定最小结构单元]: 与放能降解反应耦合，实现逆热力学转变"]},{"i":38755,"as":"针对非均相光催化二氧化碳还原制合成气面临的高反应能垒和低效电荷分离问题，研究在共价有机框架（COF）催化剂中引入N原子，并使用两个负一价双齿配体提高Co(II)位点的电子密度。通过增强光电子转移效率，最优催化剂Triazine-COF-Co-SA实现了创纪录的超高合成气产率和极高的H2/CO摩尔比。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":5.0},"kp":["光生电荷分离[共固定亚胺COF光催化CO2还原]: 引入N原子增强光电子转移效率"]},{"i":38756,"as":"自充电水系锌离子电池（SC-AZIBs）是一项集能量收集与存储于一体的前沿技术，能利用光和机械振动等环境能源实现自主运行。该综述系统分析了气、光、热和机械等多种自充电机制，深入探讨了正极材料和集成器件的设计策略，并总结材料本身局限性、系统耦合效率等关键科学挑战。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["自充电机制[自充电水系锌离子电池]: 涵盖空气、光、热和机械自充电"]},{"i":38757,"as":"在JET-ILW的氘-氚（D-T）等离子体实验中，核心离子温度达到10-12 keV。模拟表明，在富氚等离子体中注入能量约120 keV的氘（D）束离子比在50:50的D:T等离子体中产生更大的14 MeV聚变产额。此外，对D离子进行基础离子回旋共振加热（ICRH）可显著提高净聚变反应性，实验证实了这一效果。","scd":{"b":8.0,"i":7.0,"r":8.0,"d":8.0,"t":7.0},"kp":["核心离子温度[D-T聚变等离子体]: 10-12 keV","加热条件[T富集等离子体中注入D束离子]: 能量约120 keV","聚变产额[T富集等离子体]: 产生比50:50 D:T等离子体更高的14 MeV聚变产额"]},{"i":38758,"as":"实现氚自给是未来核聚变电站面临的关键挑战。麻省理工学院LIBRA项目下的BABY 1 L实验，旨在在氘-氚（DT）中子辐照下对熔盐增殖系统中的氚增殖与释放进行基准测试。实验体积扩大至1升，使用了包含质子反冲望远镜在内的改进中子诊断系统。通过液闪计数测量确定的氚增殖比（TBR）与OpenMC中子学模拟结果吻合良好。","scd":{"b":8.0,"i":4.0,"r":9.0,"d":7.0,"t":8.0},"kp":["氚育种容量[BABY 1L熔盐系统DT中子辐照实验]: 较初始100 ml活动增加十倍"]},{"i":38759,"as":"使用ORB5粒子模拟程序对ADITYA-U托马克进行了包含碰撞在内的全局电磁回旋模拟，分析了从磁轴到分离面的等离子体。线性模拟表明，有限β效应使离子温度梯度（ITG）的生长率降低了约10%。由于ADITYA-U等离子体的电子温度较低导致碰撞率相对较高，捕获电子模式（TEM）的生长率被强烈抑制。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["湍流模拟方法[ADITYA-U托卡马克]: 包含碰撞的全局电磁回旋模拟"]},{"i":38760,"as":"在JET L模式条件下进行的氘-氚等离子体配对实验表明，氚等离子体的能量约束时间比氘等离子体提高了13%-16%。这种有利的同位素比例效应主要源于电子热传输通道和等离子体边缘区域。气体脉冲调制响应显示，核心等离子体粒子运输通道中不存在显著的同位素比例效应。EDGE2D-EIRENE模拟也发现两者径向电离分布非常相似。","scd":{"b":6.0,"i":6.0,"r":7.0,"d":8.0,"t":6.0},"kp":["能量约束时间改善[JET L-mode氘氚脉冲匹配]: 13%–16%","同位素尺度效应来源[等离子体热/粒子传输]: 主要源于电子热传输通道及等离子体边缘区域"]},{"i":38761,"as":"研究评估了聚变反应堆结构材料EUROFER97的氚保留机制。样品在不同温度下暴露于低能氘等离子体和氘气中，并利用核反应分析和热解吸光谱测量氘的深度分布及保留量。实验显示两种暴露方式存在显著差异：等离子体负载产生单一主要的低温脱附峰，而气体负载则产生额外的高温脱附峰。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["氘深度测量范围[EURORFER97暴露后]: 表层7微米内"]},{"i":38762,"as":"研究系统分析了转座元件（TEs）与人类不同细胞类型染色质组蛋白标记之间的关系。基于国际人类表观基因组联盟4867个ChIP-seq实验数据，发现TEs在不同组蛋白标记中的富集水平差异极大。TEs通常呈现耗竭状态，但在特定情况下（如L1s在H3K9me3标记中）显著富集。研究还识别出456个细胞类型特异性的组蛋白-TE关联。","scd":null,"kp":["数据集规模[人类表观基因组联盟ChIP-seq分析]: 4867个统一处理的样本"]},{"i":38763,"as":"甲病毒M1被证明对骨肉瘤具有溶瘤活性。其抗肿瘤作用不仅依赖于内质网应激诱导的细胞凋亡，还通过病毒非结构蛋白NSP2直接破坏超级增强子激活因子。蛋白质组学和ChIP-seq分析显示，RNA聚合酶II亚基RPB1是致癌超级增强子活性的关键，M1病毒的溶瘤效力与超级增强子区域内RPB1的转录依赖性呈正相关。","scd":null,"kp":["溶瘤机制[甲病毒M1感染骨肉瘤]: 非依赖于经典的内质网应激诱导凋亡","作用靶点[甲病毒M1破坏超级增强子驱动转录]: DNA导向RNA聚合酶II亚基RPB1"]},{"i":38764,"as":"研究揭示了硫化氢（H2S）在抗菌肽（AMP）抗感染功能中的关键作用。人类抗菌肽LL-37及其小鼠同源物CRAMP主要通过3-巯基丙酮酸硫转移酶（3MST）在大肠杆菌和产气荚膜梭菌中诱导H2S的产生。生成的H2S进一步促进活性氧（ROS）的积累，从而导致细菌死亡。这一机制在多种动物物种中具有保守性。","scd":null,"kp":["生理调节作用[气体信号分子H2S介导抗菌肽抗感染]: 跨物种介导并增强抗菌肽的抗感染功能"]},{"i":38765,"as":"球孢子菌的不同发育阶段会引发宿主不同的免疫反应。关节孢子激活TLR2并诱导NLRP3-吡啶炎症小体，铁死亡信号促进其被杀灭；破裂的球孢子通过NLRP3和GSDMD-GSDME孔触发IL-1β产生；内孢子仅激活NLRP3炎症小体。巨噬细胞中的TLR2-NLRP3-吡啶-IL-18轴会促进球孢子生长，而Caspase-1缺陷型小鼠显示出改善的疾病耐受性。","scd":null,"kp":["免疫激活机制[巨噬细胞响应关节孢子]: 激活TLR2并诱导NLRP3-吡啶炎症小体，铁死亡信号促进杀伤","免疫逃逸机制[球孢子菌发育转变为球囊阶段]: 仅引发细胞破裂而不激活上述杀伤及炎症通路"]},{"i":38766,"as":"为解决现有空间多组学数据集成方法丢失单一组学独特信息的问题，研究人员开发了SpaMV（空间多视图）表示学习算法。SpaMV能够明确捕获不同组学间的共享信息以及特定组学独有的信息，从而提供更全面、更具可解释性的空间多组学数据表征，克服了传统方法将所有数据投影到单一统一潜在空间的局限性。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":["降维集成算法[空间多组学数据分析(SpaMV)]: 保持不同组学数据特征的独立可解释性，避免投射于单一统一潜空间导致信息丢失"]},{"i":38767,"as":"研究发现细胞核内存在直接连接代谢与基因调控的机制。线粒体酶ACO2和IDH2定位于细胞核，催化α-酮戊二酸的还原羧化反应合成柠檬酸，扩大核内乙酰辅酶A池。核内IDH2和ACO2与KAT2A/GCN5形成复合物，促进组蛋白乙酰化，进而增加染色质可及性并激活细胞增殖基因。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["代谢调控机制[细胞核内组蛋白乙酰化]: 线粒体酶ACO2和IDH2在细胞核内发生定位并催化α-酮戊二酸的还原羧化"]},{"i":38768,"as":"研究发现干扰素调节的CD34+肺成纤维细胞通过激活VLDLR介导的脂蛋白代谢重塑肺部免疫抑制微环境。脂质摄取增加促使成纤维细胞表达CD155，强效诱导细胞毒性CD8+T细胞和NK细胞耗竭，形成转移前生态位。遗传破坏干扰素-VLDLR-CD155轴可恢复免疫监视并抑制肿瘤肺转移，这表明基于干扰素的疗法具有促转移风险。","scd":{"b":8.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["微环境重塑机制[干扰素调控的CD34+肺成纤维细胞]: 通过VLDLR介导脂蛋白代谢激活，增加胞内脂质积累并上调CD155表达，重塑免疫抑制性肺微环境"]},{"i":38769,"as":"研究在微米级TiB2陶瓷中实现了接近理论值的强度和高弹性极限。通过钢中原位共晶凝固制备的微米级TiB2，在微观拉伸测试中，超过4立方微米的体积能够承受约13 GPa的均匀拉伸应力而不断裂，弹性应变高达9%。这一现象打破了缺陷敏感性将此类力学行为限制在纳米级样品中的传统认知。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["尺寸与力学性能[微米级TiB2陶瓷]: 接近理论强度与高弹性拉伸应变","制备工艺[钢中原位共晶凝固]: 原位生成具有特定结晶学取向的微米级TiB2"]},{"i":38770,"as":"研究揭示了呼吸复合物I中长程能量转换的耦合机制。通过冷冻电镜（分辨率2.6-2.8 Å）、定点突变和多尺度模拟，在复合物I功能核心的羧酸通道（E通道）中识别出一个保守的羧酸盐开关点（D79NuoA）。该位点通过建立动力学门控介导质子转移，并将氧化还原化学反应与质子泵送直接耦合。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["长程能量转换距离[呼吸复合物I质子耦合电子转移(PCET)]: >300 Å","结构分辨率[呼吸复合物I冷冻电镜分析]: 2.6-2.8 Å","能量偶联机制[呼吸复合物I中心E通道]: 受控于特定的羧酸盐开关点"]},{"i":38771,"as":"研究提出了一个区分儿童和成人癌症的统一模型。早期生活中的致癌事件主要促进短暂的胚胎-胎儿转录和表观遗传程序的保留与稳定；而晚生活中的突变则通常需要重新布线，通过渐进的转录和染色质重塑重新激活被抑制的癌胎状态。发育时间维度的引入有助于解释具有相同基因病变的儿童与成人癌症为何呈现不同的轨迹和治疗反应。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["致病机制[早期生命致癌事件]: 促进并稳定短暂的胚胎-胎儿转录和表观遗传程序(保留机制)","致病机制[晚期生命突变]: 通过逐步转录和染色质重塑重新激活被抑制的致癌胎儿状态(重新布线机制)"]},{"i":38772,"as":"研究阐明了多梳抑制复合物1的核心催化亚基Ring finger protein 2 (RNF2) 在结肠炎中的调控作用。溃疡性结肠炎患者未成熟结肠和循环单核细胞中RNF2高表达。髓系特异性RNF2缺失可减轻小鼠结肠炎并恢复单核/巨噬细胞平衡。机制上，RNF2通过组蛋白H2A赖氨酸119位单泛素化抑制Runt相关转录因子3的表达，从而阻滞单核细胞向巨噬细胞的转变。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["分子机制[多梳抑制复合物1核心催化亚基RNF2]: 介导H2A泛素化","病理作用[RNF2在结肠炎单核-巨噬细胞转变期间]: 抑制单核细胞向巨噬细胞的转变从而促进结肠炎"]},{"i":38773,"as":"研究提出了一种用于高效病理图像分析的深度学习框架EAGLE。该框架模仿病理医生的选择性分析模式，结合了与任务无关的切片选择和精细特征提取。在涵盖9种癌症类型的43项形态学、生物标志物预测、治疗反应和预后任务中，EAGLE的性能比传统的图像块聚合方法高出23%，有效解决了现有方法计算效率低下且存在大量冗余处理的问题。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[病理图像深度学习框架EAGLE]: 模拟病理医生选择性分析信息区域，结合任务无关的分块选择以提高计算效率"]},{"i":38774,"as":"研究揭示了植物响应机械刺激的顺序MAPK激酶级联调节机制。机械刺激在60秒内激活MAPKKK3/4/5-MKK4/5-MPK3/6级联，诱导约800个早期触觉反应基因表达。这些基因大部分与CAMTA1/2/3调节的触觉反应基因重叠，表明MAPKs与CAMTA转录因子存在相互作用。失去MKK4/5会导致触觉调节的蛋白质磷酸化发生全面障碍。","scd":{"b":8.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["激酶级联响应时间[植物感受机械刺激激活MAPKKK3/4/5-MKK4/5-MPK3/6级联]: 60秒内","转录调控规模[机械刺激诱导的早期触摸反应基因]: 约800个基因"]},{"i":38775,"as":"研究在Kleefstra综合征患者中鉴定出7个EHMT2基因的新生变异。这些变异编码的G9a蛋白结构稳定，但由于与组蛋白H3尾部或S-腺苷甲硫氨酸的异常相互作用，导致G9a甲基转移酶催化活性丧失。这证明了EHMT2新生变异伴随G9a甲基转移酶活性的丧失，是导致常染色体显性EHMT2相关Kleefstra综合征的致病原因。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["致病基因[常染色体显性EHMT2相关Kleefstra综合征]: EHMT2新生变异","病理机制[EHMT2相关Kleefstra综合征]: G9a甲基转移酶活性丧失"]},{"i":38776,"as":"研究发现溶酶体双孔通道2（TPC2）能够控制钙调蛋白依赖性的STIM1失活。TPC2的激活通过强制STIM-Orai激活区域（SOAR）发生快速且持久的钙-钙调蛋白依赖性失活来抑制钙库操控的钙内流（SOCE）。NAADP和TPC2-A1-N等TPC2激活剂触发了溶酶体Ca2+释放和内质网Ca2库动员，但同时阻止了RFP-STIM1向TIRF层面的招募。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["调控机制[钙调蛋白依赖性STIM1失活]: TPC2激活通过增强SOAR的快速和持久Ca2+-CaM依赖性失活来抑制SOCE"]},{"i":38777,"as":"研究阐明了锂硫电池中硫还原反应的完整级联催化途径。以铁、氮、硫共掺空洞石墨烯为模型催化剂，密度泛函理论计算及实验证实，Fe位点优先结合并活化长链多硫化物，而掺杂的N/S位点则负责后续短链中间体的转化。这种级联催化机制有效平衡了多种多硫化物中间体的不同吸附与活化需求，抑制了严重的穿梭效应。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[多硫化物级联催化途径]: 通过精确设计催化路径以平衡多硫化物转化并缓解穿梭效应"]},{"i":38778,"as":"研究利用2.2埃分辨率的单颗粒冷冻电镜，解析了苏云金芽孢杆菌Vpb4Aa2蛋白的孔道结构。Vpb4亚类作为单组分挑战了传统的双组分AB毒素机制。结构显示，与其他家族成员相比，Vpb4Aa2缺少分子瓶颈且具有电中性的β桶结构。电生理研究证实，与典型家族成员PA相比，Vpb4Aa2具有更大的离子通量。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["结构解析分辨率[Vpb4Aa2插入孔结构]: 2.2 Å","技术手段[Vpb4独立孔结构解析]: 单颗粒冷冻电子显微镜","蛋白功能[苏云金芽孢杆菌Vpb4]: 单组分穿孔机制"]},{"i":38779,"as":"研究开发了一种无需操作员即可进行乳腺成像的便携式实时3D超声系统（3D PURE）。该系统通过阵列换能器设计、声学材料和自适应波束成形技术的进步，克服了体积乳腺成像的局限。其盒式阵列设计将峰值串扰抑制了3.73分贝，支持高达24伏的发射电压；定制的流动背衬层（阻抗6.12 MRayl）有效保护了脆弱的引线键合。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[便携式3D超声系统(3D PURE)]: 采用盒子状阵列设计、声学材料和自适应波束成形技术实现无需操作员的乳腺实时体积成像"]},{"i":38780,"as":"研究揭示了靶向HDAC的缩酚肽杂合化合物（如romidepsin）组合生物合成的分子基础。这类分子由保守的Zn2+结合药效基团和可变肽帽融合而成。研究人员通过基因邻近搜索在假单胞菌中鉴定了FR-901375生物合成基因簇，并比较了由该基因簇编码的PKS-NRPS与组装相关化合物的酶系统，阐明了聚酮化合物的混合组装逻辑。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["生物合成机制[缩酚肽HDAC抑制剂]: PKS与NRPS融合的组合生物合成"]},{"i":38781,"as":"研究开发了2010至2023年中国二氯甲烷（CH2Cl2）和三氯甲烷（CHCl3）的底-up排放清单，并预测至2035年。结果显示两种物质排放量均呈上升趋势，其中CH2Cl2排放量自2010年以来增加一倍以上。在常规情景下，预计到2035年排放量将大幅增长。应用最佳可行技术可减少约5%的累计排放量。这些不受蒙特利尔议定书管制的短寿命物质排放增加可能延迟臭氧层恢复。","scd":{"b":5.0,"i":5.0,"r":7.0,"d":8.0,"t":7.0},"kp":["排放量对比[中国臭氧层消耗物质]: 氯化极短寿命物质的CFC-11当量排放量超过了HCFC","排放清单时间范围[中国CH2Cl2和CHCl3]: 2010至2023年（并预测至2035年）"]},{"i":38782,"as":"研究结合大气传输模型和因子模拟评估2100年CO2季节性循环变化。在高排放情景（SSP5-8.5）下，陆地碳汇主导并放大CO2季节变化，地面观测仍可靠反映陆地碳动态。但在低排放情景（SSP1-2.6）下，主导驱动因素发生根本转变，化石燃料排放成为北半球CO2季节性循环趋势的主导因素，改变了传统上由陆地生态系统主导的格局。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["主导驱动因素[缓解情景下北半球二氧化碳季节性循环趋势]: 化石燃料排放"]},{"i":38783,"as":"","scd":null,"kp":[]},{"i":38784,"as":"铁作为海洋生物限制性营养元素发挥关键作用。通过对邻近斯瓦尔巴-巴伦支海冰盖的耶马克高原沉积记录分析发现，在过去13.5万年期间，冰盖后退或前进时期至少发生5次脉冲式活性铁输出。富铁层保存了高含量的活性铁相，其中部分在沉积时具有生物可利用性。结果表明冰川系统不稳定性是向海洋输送生物可利用铁的重要机制。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":6.0,"t":7.0},"kp":["铁输送效应[斯瓦尔巴-巴伦支海冰盖不稳定性]: 增强向海洋输送活性铁（生物可利用铁）"]},{"i":38785,"as":"","scd":null,"kp":[]},{"i":38786,"as":"","scd":null,"kp":[]},{"i":38787,"as":"","scd":null,"kp":[]},{"i":38788,"as":"通过研究者调查、全球公民科学记录和中国高分辨率数据集，研究发现野生动物-车辆碰撞不均衡地影响低收入和中等收入国家的生物多样性。标准化物种库和采样努力后，低收入和中等收入国家承受更重的路杀负担，受威胁脊椎动物的差异最显著，达2-4倍。这反映了受威胁动物碰撞率升高而非受影响物种范围更广。中国数据呈现相同模式。","scd":{"b":4.0,"i":4.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[野生动物车辆碰撞风险]: 在标准化物种库和采样努力度后，碰撞风险负担不成比例地集中在低收入和中等收入国家"]},{"i":38789,"as":"","scd":null,"kp":[]},{"i":38790,"as":"","scd":null,"kp":[]},{"i":38791,"as":"","scd":null,"kp":[]},{"i":38792,"as":"","scd":null,"kp":[]},{"i":38793,"as":"","scd":null,"kp":[]},{"i":38794,"as":"","scd":null,"kp":[]},{"i":38795,"as":"研究通过化学引导策略将萜烯类生物质转化为真正可石墨化的沥青。松树脂衍生的萜烯通过脱氧-芳构化和控制性寡聚反应依次转化，产生杂原子含量低的芳香族沥青。热分析和偏光显微镜证明加热过程中表现出热塑性行为和中间相形成。该方法解决了生物质衍生碳因缺乏能够在碳化过程中形成中间相的分子结构而无法石墨化的基本限制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[萜烯基生物质向可石墨化沥青转化]: 采用化学引导的分子重构策略，使缺乏芳香缩合的生物质形成能在碳化过程中形成中间相的真可石墨化沥青"]},{"i":38796,"as":"研究报道了具有快速充电能力的高倍率单晶富锂层状氧化物。该材料在5C快速充电条件下0.2C放电容量达248 mAh/g，5C快速放电容量达179 mAh/g。富锂层状氧化物比容量超过280 mAh/g，比能量超过1000 Wh/kg。快速充电性能通过表面相中复杂阳离子排序的协同排列得以解决，克服了传统富锂层状氧化物倍率性能差和难以制备体积能量密集型单晶的挑战。","scd":{"b":7.5,"i":2.0,"r":4.0,"d":7.0,"t":5.0},"kp":["比容量[锂锰富集层状正极]: >280 mAh g⁻¹","比能量[锂锰富集层状正极]: >1000 Wh kg⁻¹","[高倍率单晶富锂层状氧化物]: 克服了单晶材料差的倍率性能，实现了兼具高体积能量密度与高倍率性能的单晶正极"]},{"i":38797,"as":"研究建立了黎曼ζ函数非平凡零点与两个人工工程量子多体系统中动态量子相变之间的直接对应关系。这两个系统分别以平均累积相位因子和Loschmidt振幅为特征。这种对应关系将黎曼假设重新表述为在特定温度下发生相变的现象，并将其识别为一种新的相变机制。研究在量子处理器上进行了原理验证实验，并提出了一种量子验证方法。","scd":{"b":9.0,"i":1.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[黎曼猜想的物理体现]: 黎曼Zeta函数的非平凡零点与 engineered 量子多体系统中的动态量子相变（以平均累积相位因子和Loschmidt振幅为特征）建立直接对应关系"]},{"i":38798,"as":"研究开发了超长自旋光子光纤技术用于可穿戴偏振增强传感。采用离散螺旋锚定策略在挤出过程中自主将圆偏振材料嵌入光纤，生产出连续长度超过1300米的自旋光子光纤。所得核-鞘珠状光纤发光不对称因子达0.41。该技术实现了多变量干扰的高效解耦，解决了动态多变量环境中信号重叠、耦合和质量退化问题。光纤编织织物可实现动态实时信号采集。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[偏振增强传感技术]: 利用超长自旋光子光纤实现多变量干扰的高效解耦","[螺旋锚定策略]: 在挤出过程中自主将圆偏振材料嵌入纤维内部"]},{"i":38799,"as":"研究探索通过在介观尺度工程化电子能带结构增强光学非线性的策略。具体证明了结晶银膜在厚度减少至仅几个原子单层时二次谐波产生（SHG）增强。这些超薄薄膜在体相和二维系统边界工作，SHG随厚度减少而显著增强。该增强机制不同于传统纳米光子学通过调节纳米结构尺寸和形貌来操纵光学近场的方法，为基础光子技术发展提供了新途径。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[非线性光学增强机制]: 通过在介观尺度下调控电子能带结构实现光学非线性增强","[少原子厚银膜]: 显著提升非线性光学响应"]},{"i":38800,"as":"研究确定了质子交换膜水电解槽铱基阳极催化剂层中电化学非活性死区的主要成因：离聚物破坏IrO2纳米催化剂导电网络导致的有限面内电子导电性。开发了顺序喷涂策略，将原始导电催化剂层沉积与离聚物沉积解耦，保持连续电子传输路径。该方法有效激活面内死区，提高了质子交换膜水电解槽的性能和铱基催化剂的利用率。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["死区主导因素[PEMWE铱基阳极催化剂层]: 离聚物破坏IrO2纳米催化剂导电网络导致面内电子电导率受限"]},{"i":38801,"as":"研究提出了首个利用标准半导体工艺直接实现的可重构智能表面（RIS）系统。STARE架构将定制的选择性重叠二极管（SOD）集成到高阻硅中，实现可调的导通电阻和关断电容，保持低功耗运行。采用磁耦合的无通孔透射型单元消除了硅通孔需求，简化制造并降低基板损耗。实验验证了该系统在6G波束成形中的应用潜力，克服了液晶、PIN二极管或变容管方案响应慢、损耗高和集成成本高的问题。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[6G波束成形RIS系统]: 首次直接采用标准半导体工艺实现","STARE架构[可重构智能表面]: 将定制选择性重叠二极管(SOD)集成到高阻硅中"]},{"i":38802,"as":"研究利用持久性氮氧自由基TEMPO作为模型系统，在超音速分子射流中报告其自由基对的旋转表征。实验采用同位素敏感的高分辨率微波光谱，揭示了两种避免电子转移的中性配对模式。在每个自由基对中，氮氧分子建立非共价范德华相互作用，N···O距离分别为3.38和4.93 Å，已由18O标记实验证实。电子自旋超精细效应的缺失与量子力学密度泛函理论预测一致，支持意外的开壳层单重态基态。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[中性自由基对旋转表征]: 采用同位素敏感的高分辨率微波光谱技术在超音速分子射流中进行观测","[TEMPO自由基对配对模式]: 存在两种避免电子转移的明显中性配对模式"]},{"i":38803,"as":"导电二维共价有机框架因晶界和无定形区限制了薄膜的电荷传输性能。研究提出一种可扩展策略，利用分子级分散的共轭聚合物桥接多晶COF区域。在电子排列、几何兼容性和链长标准的指导下，发现特定的COF-CP组合在形成异质结构时导电性显著增强。研究证实，这种导电性能的提升仅在低于共轭聚合物结晶阈值时发生，表明桥接共轭聚合物需要处于短程有序或无定形状态才能发挥效用。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[2D COFs多晶畴搭桥策略]: 利用分子级分散的共轭聚合物桥接消除晶界和非晶区的电荷传输阻碍"]},{"i":38804,"as":"为提升弹性体的韧性，研究提出一种通过顺序激活多途径能量耗散来增韧弹性体的策略。该策略在单一聚合物中同时整合了机械互锁网络、可切割的机械力响应基团和编织网络。聚氨酯中由轮烷交联剂构建的机械互锁网络作为初级能量耗散途径，当轮烷交联剂的滑动达到极限时，嵌入轮烷大环中的三藜芦酸基机械力响应基团发生牺牲性断裂，作为次级能量耗散途径发挥作用。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[弹性体增韧策略]: 采用顺序激活的多途径能量耗散机制","[聚合物基体集成结构]: 同步集成机械互锁网络、可断裂力色团和编织网络"]},{"i":38805,"as":"源于人类病原体的Cas9蛋白具有免疫原性，带来安全性隐患。研究比较了源于人类致病菌的SaCas9、共生菌的AsCas12a以及噬菌体的CasΦ的免疫原性风险。体外实验表明，未免疫个体的抗体和T细胞对这三种蛋白的识别程度相似。通过质谱鉴定与MHC-I结合的肽段，发现这三种蛋白的肽段均呈现在9种MHC-I蛋白上。这表明非病原体来源的Cas直系同源物并未表现出更低的免疫原性。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[免疫原性风险比较]: 未感染个体对源自病原体的SaCas9、共生的AsCas12a及噬菌体的CasΦ具有相当的预存抗体和T细胞反应水平"]},{"i":38806,"as":"T细胞难以转染，研究假设靶向快速内吞的表面受体可改善纳米颗粒向T细胞的递送。通过区分标记细胞内和表面蛋白的内化实验，发现CD2和CD7的受体内吞率显著高于CD3或CD4。靶向CD2和CD7提高了未激活的原代CD4+ T细胞对纳米颗粒的内化，并增强了特异性结合。用靶向CD2或CD7的抗体修饰mRNA脂质纳米颗粒，在体外成功增强了向CD4+ T细胞的mRNA递送效率。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":[]},{"i":38807,"as":"倒置钙钛矿光伏器件中使用的聚(三芳胺)(PTAA)在氧化铟锡上易发生纳米级结晶和聚集，导致薄膜不连续并限制模块稳定性。研究表明，4-氟苄基膦酸(4FBPA)能修饰氧化铟锡表面，诱导PTAA发生纳米级非晶化，形成均匀的亚10纳米空穴选择层。该分子通过脱水反应与基底结合，调节功函数和表面自由能，改善能级排列。这种非晶层有效提升了钙钛矿光伏器件的效率和稳定性。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[PTAA纳米级非晶化改性]: 利用4-氟苄基膦酸(4FBPA)修饰氧化铟锡表面，改善PTAA纳米级结晶与团聚以提升薄膜连续性"]},{"i":38808,"as":"大脑皮层沿着从感觉运动到关联区域的主导轴组织。研究提出了多模态诱导-排除网络发展(MIND)模型，通过多物种证据阐明了S-A轴图案化的发育机制。该发育模式由两种在转录组上截然相反的程序（“中央周围”程序）驱动的诱导和排除竞争过程控制。“中央周围”程序在额颞极周围被诱导，并逐渐向未分化组织的中心区域向内推进，从而塑造了大脑皮层的功能网络结构。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":[]},{"i":38809,"as":"肌肉乙酰胆碱受体的突变会引发通道开启受损（快通道）或延长（慢通道），导致先天性肌无力综合征，出现严重的肌肉无力甚至瘫痪。结合冷冻电子显微镜、化学生物学和电生理学技术，研究确定了这些致病性受体缺陷背后的结构机制。同时，研究揭示了对这些乙酰胆碱受体缺陷进行药理学纠正的具体原理，为纠正先天性肌无力相关的缺陷提供了直接的分子基础。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":38810,"as":"锂金属固态电池常因锂枝晶的萌生和蔓延而在低充电率下短路失效。关于枝晶萌生发生在固体电解质内部还是表面存在争议。研究开发了一种面内双轴压缩方法，在表面短路机制失效的情况下，提供了直接证据表明，在长期循环过程中，枝晶在石榴石型Li6.6La3Zr1.6Ta0.4O12固体电解质内部萌生。这一双轴应力研究直接揭示了固态电解质内部的枝晶生长行为。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["短路失效阈值[固态电池锂枝晶生长]: 即使在低于1 mA cm-2的低充电速率下也会发生"]},{"i":38811,"as":"关于螯肢动物及其书鳃的起源演化一直存在争议。有假说认为螯肢动物的螯肢由寒武纪大爪动物的短巨大附肢演化而来，书鳃则起源于其躯干附肢。研究利用X射线微断层扫描技术，揭示了早寒武世真节肢动物Urokodia aequalis的三维解剖结构。这一来自澄江生物群的化石证据，为阐明大爪动物样附肢向真正的螯肢和书鳃演化的形态转变提供了关键的解剖学线索。","scd":{"b":8.0,"i":1.0,"r":6.0,"d":4.0,"t":4.0},"kp":["螯肢[螯肢动物起源]: 由寒武纪巨爪动物的短大附肢(SGAs)演化而来","书鳃[螯肢动物起源]: 由躯干附肢演化而来"]},{"i":38812,"as":"透明细胞肾细胞癌主要由转录因子HIF-2α驱动。在ARC-20研究中，口服选择性HIF-2α抑制剂Casdatifan在难治性转移性ccRCC患者中表现出具有临床意义的持久抗肿瘤活性，且安全性可控。每日一次100毫克剂量组的确认客观缓解率为35%，总体队列（127人）为31%。因不良事件停止治疗的比例较低（3%），常见的类别效应毒性包括贫血和缺氧。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":8.0,"t":7.0},"kp":["药物类型[Casdatifan]: 口服生物可利用的强效选择性HIF-2α抑制剂","给药剂量[ARC-20研究剂量扩展队列]: 100 mg 每日一次(QD)","临床疗效[难治性转移性透明细胞肾细胞癌]: 产生有意义且持久的抗肿瘤活性","安全性[Casdatifan单药治疗]: 毒性可控"]},{"i":38813,"as":"","scd":null,"kp":[]},{"i":38814,"as":"","scd":null,"kp":[]},{"i":38815,"as":"在研发通用疟疾疫苗的过程中，研究人员已经确定了进化上高度保守的靶标。这些靶标不仅在不同的疟原虫物种及其各个生命阶段中共享，而且能够被人类免疫系统有效识别。针对这些保守靶标的设计，为开发能够广泛抵御多种疟原虫感染的通用型疟疾疫苗提供了重要的方向和现实可能性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":5.0},"kp":["疫苗靶点[普遍的疟疾疫苗]: 跨疟原虫物种及其生命阶段共享且被人类免疫系统识别的进化保守靶点"]},{"i":38816,"as":"研究通过结合单神经元电生理记录与人工智能技术，成功识别出参与人类语言生成的特异性脑细胞。这些神经元广泛分布于大脑中，负责编码特定的语义和语法特征，并反映出词汇是如何组合成短语和句子的。该研究证实，单个神经元的活动能够精确编码词汇含义、语法规则或高阶的句子结构，揭示了人类语言产生的微观神经机制。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[语言生成相关脑细胞]: 广泛分布于大脑中，编码特定语义和语法，反映词汇组装成短语和句子的方式","[单个神经元活动]: 编码词义、语法或高阶句子结构"]},{"i":38817,"as":"","scd":null,"kp":[]},{"i":38818,"as":"研究通过量化318个高分辨率复杂食物网（涵盖海洋、湖泊、溪流和土壤生态系统）中的能量流动，探讨了食物网复杂性如何调节生物多样性与生态系统功能之间的关系。研究测量了初级消费和捕食两种主要功能。结果显示，在所有营养级中，生态系统的功能均随着分类群丰富度的增加而持续增强，证实了食物网复杂性是生物多样性影响生态系统功能的基础。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["营养级数量[大多数生态系统]: 2至6个"]},{"i":38819,"as":"","scd":null,"kp":[]},{"i":38820,"as":"","scd":null,"kp":[]},{"i":38821,"as":"高温环境会导致植物细胞膜变得脆弱并发生渗漏。为了应对这种热应激反应，水稻能够通过迅速调整其细胞膜的脂质成分来抵消高温带来的负面影响。通过改变周围的脂质含量，水稻维持了细胞膜的坚固性和稳定性，从而使其能够在热浪等极端高温条件下正常生长并保持生理机能。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[水稻耐热机制]: 通过迅速调整膜脂含量来抵消高温导致的细胞膜变弱和渗漏，从而抵御热浪"]},{"i":38822,"as":"","scd":null,"kp":[]},{"i":38823,"as":"","scd":null,"kp":[]},{"i":38824,"as":"","scd":null,"kp":[]},{"i":38825,"as":"直接成像技术证实，随着晶体管尺寸不断缩小，其电极也在相应缩减。电流流入原子级厚度晶体管的触点长度已可按比例缩小至仅几纳米。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["接触点/电极尺寸[原子级薄层晶体管]: 缩小至仅几纳米长"]},{"i":38826,"as":"","scd":null,"kp":[]},{"i":38827,"as":"纳米金刚石可承载原子级光发射器用于量子传感与成像。研究人员利用边缘带有氢原子的平面碳“纳米石墨烯”分子，开发出单步合成工艺，成功制备出尺寸仅为3至4纳米且尺寸分布狭窄的分子纳米金刚石，产量可达毫克级。该工艺经调整后还可用于生成荧光纳米金刚石，解决了以往难以制造微小、结晶且均匀的纳米金刚石的难题。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["纳米金刚石尺寸[单步法合成]: 3至4纳米","制备规模[3至4纳米纳米金刚石]: 毫克级","[合成原料]: 边缘带有氢原子的平面碳“纳米石墨烯”分子"]},{"i":38828,"as":"锰氧化物对微量金属和营养物质的循环至关重要。研究人员在相同溶液条件下孵化了三种粒度和结晶度不同的层状锰氧化物，观察到它们转化成了不同的隧道状锰氧化物。这表明，与结晶度相关的矿物结构特性（特别是空位密度和表面能）调节了Mn(II)的吸附几何结构及随后的电子转移与结构重排，在锰氧化物转变机制中发挥着关键作用。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":5.0,"t":6.0},"kp":["锰氧化物矿物类型[自然界鉴定]: 超过30种","[层状锰氧化物转变机制]: 纳米级矿物特性（特别是颗粒尺寸和结晶度）决定在相同溶液条件下形成不同的隧道状锰氧化物"]},{"i":38829,"as":"中村荣一教授分享了他在化学研究中的经历、成就与愿景，并详细阐述了他的个人人生哲学。","scd":{"b":3.0,"i":3.0,"r":5.0,"d":3.0,"t":4.0},"kp":[]},{"i":38830,"as":"生活在蚜虫细胞内的Buchnera细菌会分泌一种名为SyeA的蛋白质，这种蛋白质对细菌在宿主体内的定植至关重要。由于SyeA在结构上与致病菌分泌的蛋白质相似，这表明Buchnera与蚜虫之间有益的共生关系实际上起源于致病性。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":4.0,"t":6.0},"kp":["共生细菌[蚜虫宿主定植]: 分泌SyeA蛋白","有益共生关系[起源]: 具有致病性起源"]},{"i":38831,"as":"合成mRNA疗法常使用N1-甲基假尿苷来提高翻译效率并降低免疫原性，但最新研究发现其会损害翻译保真度，导致提前终止和核糖体移码等错误。研究揭示了N4-乙酰胞苷作为m1Ψ的一种功能性替代方案，在多种培养细胞系和原代人单核细胞中展现出优异的性能，能够有效提高合成mRNA的翻译产量和保真度。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[合成mRNA加帽或核苷酸修饰]: N4-乙酰胞苷提高翻译产量和保真度，N1-甲基假尿苷（m1Ψ）作为工业标准促进翻译并降低免疫原性"]},{"i":38832,"as":"","scd":null,"kp":[]},{"i":38833,"as":"","scd":null,"kp":[]},{"i":38834,"as":"气相沉积是制造钙钛矿发光二极管的可行方法，但易产生混合维相和纳米级不均匀性。研究人员开发出一种热力学引导的X型准二维钙钛矿气相合成方法。通过引入一种卤化物位点取代的有机间隔物分子，使其在沉积过程中与Pb2+共价结合，成功实现了具有可控纳米级相分布和界面相干性的准二维钙钛晶体的选择性结晶。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[气相沉积合成准二维钙钛矿]: 采用卤化物位点取代间隔物进行热力学导向的气相合成，以克服动力学驱动的结晶问题并提高器件效率"]},{"i":38835,"as":"阿马尔·卡斯里探讨了量子科学向量子技术的转变。他警告称该领域面临结构性分化的风险，并强调必须立即采取行动，以确保量子技术能够为全社会带来共同繁荣。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":3.0,"t":5.0},"kp":["量子科学[技术发展趋势]: 向量子技术转变"]},{"i":38836,"as":"通过组装对应变不敏感的弹性体电子器件与水凝胶粘合剂，研究人员成功构建出无缝的湿组织粘合生物电子学设备。这种具有无缝湿组织界面的设备能够实现闭环治疗调节。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["生物电子界面[组合架构]: 应变不敏感弹性体电子器件与水凝胶粘合剂集成","治疗调控[闭环系统]: 无缝湿组织粘附生物电子学"]},{"i":38837,"as":"二维材料正被集成到超微型电子器件中，但其漏电流机制尚不明确。研究人员测试了不同厚度的六方氮化硼、二硫化钼和二硫化钨的漏电流情况，并与工业级SiO2/n++Si样品进行了对比。结合纳米级到器件水平的分析以及计算建模，研究证明了表面粗糙度等物理特性对二维材料漏电流的具体影响。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["漏电流[二维材料]: 六方氮化硼、二硫化钼和二硫化钨中普遍存在且机制尚不明确"]},{"i":38838,"as":"感音神经性耳聋影响全球约3%人口。研究团队开发出一种能够与哺乳动物传入神经混合的人工神经形态接口，用于重建听觉通路。该设备利用WO3纳米线进行动态可逆的质子插入和提取，结合8×8突触晶体管阵列进行矩阵向量乘法，成功实现了三维声音定位和空间映射，具备宽范围的序列声音处理能力。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":8.0,"t":8.0},"kp":["发病率[感音神经性听力损失]: 约3%","听觉受体[人工神经形态接口]: 自供电声学器件","动态可逆质子插入与提取[突触器件]: WO3纳米线","注意力集中机制[人工神经回路]: 侧抑制逻辑的可重构星形电路"]},{"i":38839,"as":"针对呼吸道合胞病毒（RSV），研究人员构建了一个尺寸可控的DNA纳米载体文库，系统评估了几何特性对鼻内驻留的影响。通过精确控制表面抗原排列模式以最大化B细胞激活，基于DNA纳米载体的优化疫苗在小鼠中诱发了与临床批准的肌肉注射疫苗相当的体液免疫反应。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":7.0,"t":8.0},"kp":["B细胞激活[呼吸道疫苗递送]: 依赖于载体的几何特性和表面抗原展示特性","鼻内保留率[DNA纳米载体]: 受控且系统优化的尺寸和维度"]},{"i":38840,"as":"","scd":null,"kp":[]},{"i":38841,"as":"霍金辐射连接了引力、量子力学和热力学，但尚未在天文学中观测到。研究人员在光纤事件视界类似物中，从实验和理论上证实了霍金辐射的生成过程。研究纠正了以往关于复杂级联物理机制的假设，识别出了一种更简单的量子产生机制，揭示了辐射对引力场的逆反应效应。","scd":{"b":9.5,"i":2.0,"r":8.0,"d":6.0,"t":8.0},"kp":["霍金辐射[物理机制]: 场量子通过反作用机制生成霍金量子的能量转化过程"]},{"i":38842,"as":"","scd":null,"kp":[]},{"i":38843,"as":"提出了一种AI驱动的“虚拟酵母”智能体，用于计算模拟真核细胞的生命活动。该系统以酿酒酵母为模型，整合多模态生物数据、机制推理和主动实验。它将细胞复杂性分解为遗传、代谢和结构等八个功能模块，每个模块由基于大语言模型的编排层协调特定领域的AI工具。系统建立在机制知识、亚细胞结构和动态状态三大数据支柱上，并在闭环学习流程中结合了表征学习与生成建模。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":8.0},"kp":["虚拟酵母[真核细胞模型]: AI驱动的多模态生物数据与主动实验智能体集成","功能模块[细胞复杂性分解]: 涵盖遗传、代谢和结构系统的八个领域特定模块"]},{"i":38844,"as":"针对蓝色钙钛矿发光二极管工作电压高导致八面体不稳定的问题，研究者利用异构分子构建钙钛矿内部及界面的氢键网络，实现了高效稳定的饱和蓝色发光。具体而言，在空穴传输层和发光体之间使用O-苯甲基羟胺盐酸盐（OBCl）作为氢键供体，与钙钛矿无机骨架结合，有效提升了蓝光PeLED的器件性能与稳定性。","scd":{"b":7.5,"i":4.0,"r":7.0,"d":7.0,"t":8.0},"kp":["电致发光性能[蓝色钙钛矿LED]: 滞后于其他颜色，受限于高工作电压下的八面体不稳定性","异构多氢键[钙钛矿稳定策略]: 实现高效且稳定的饱和蓝光发射"]},{"i":38845,"as":"针对不可培养的内共生菌如何进入宿主细胞并抑制免疫的机制，研究揭示了一种存在于蚜虫内共生菌Buchnera祖细胞中、被命名为SyeA的分泌蛋白。该蛋白与病原体分泌效应因子同源，被分泌到宿主细胞质中。实验证明，SyeA对于Buchnera从特化母细胞排出并被胚胎摄取的垂直传播过程至关重要，是内共生菌成功定植宿主的秘密所在。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":8.0},"kp":["内共生菌入侵机制[宿主细胞定植]: 依赖非典型分泌蛋白SyeA以进入细胞并抑制细胞免疫"]},{"i":38846,"as":"研究揭示了复制应激诱导染色质环形成以保护复制叉稳定性的机制。在应激下，停滞的复制叉在汇聚的CTCF基序处发生停滞，触发CTCF富集限制环挤压，形成包含新生DNA的瞬时染色质环。该环的稳定依赖于CTCF锚定和G9a依赖性异染色质（H3K9me3）在环体内的沉积。这种染色质环作为保护性支架，能保护停滞和逆转的复制叉免受多种核酸酶的降解。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["染色质结构[复制应激诱导]: 形成包围停滞复制叉的瞬时染色质环","复制叉[稳定性维持机制]: 停滞在汇聚的CTCF基序处并触发CTF富集以限制环挤压"]},{"i":38847,"as":"为突破疟疾疫苗发展中T细胞靶点缺乏的瓶颈，研究者利用免疫肽组学，在感染间日疟原虫的网织红细胞表面寻找HLA-I类分子递呈的抗原肽。由于网织红细胞保留了宿主蛋白合成能力且能表达HLA-I，该研究成功鉴定出453种独特的疟原虫抗原衍生多肽，并将其映射到166种蛋白质上，为开发跨阶段、跨物种的疟疾CD8+ T细胞表位疫苗提供了重要靶点。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":[]},{"i":38848,"as":"针对基于二维材料的亚1纳米逻辑技术节点晶体管，研究开发了一种直接探测二维材料晶体管中载流子传输长度的方法。基于二维材料超薄和无缺陷表面的物理特性，该测量技术能够确定接触电极的缩放限制。这一物理通道长度有望降至2纳米以下的探测手段，为未来超微缩电子器件的研发与接触工程提供了关键的设计信息。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["物理沟道长度极限[二维材料晶体管]: 最终可能达到2纳米及以下尺度","载流子传输长度[测试方法]: 针对极大规模微缩电子器件的直接探测技术"]},{"i":38849,"as":"亨廷顿病（HD）作为一种单基因运动障碍疾病，其皮层功能障碍的下游机制尚不明确。研究利用R6/2转基因小鼠模型，通过纵向活体双光子钙成像技术，持续观察了运动皮层中三种抑制性神经元亚型及皮层纹状体投射神经元的钙活动。结果发现，小鼠的运动缺陷伴随着特定神经元亚型在运动相关活动中的异常，表明恢复皮层去抑制作用能够有效改善HD的疾病表型。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":[]},{"i":38850,"as":"为解决卤化锡钙钛矿中Sn2+位点因内在氧化还原不稳定性导致的自掺杂和快速降解问题，研究提出一种挥发性辅助配位策略。该策略利用瞬态醋酸配位和挥发作用重构钙钛矿表面，将高活性的SnI2终止面转化为化学平衡且缺陷减少的界面。这种方法有效抑制了未配位Sn相关的陷阱态并稳定了局部化学计量比，成功实现了稳定的p型锡钙钛矿晶体管。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["氧化降解[锡基卤化物钙钛矿]: 由未配位Sn2+位点的本征氧化还原不稳定性导致","表面重构[配位策略]: 挥发性辅助配位技术抑制不受控的自p型掺杂"]},{"i":38851,"as":"研究通过高精度的钕（Nd）同位素测量，揭示了地球深部地幔化学异常的古老起源。在科摩罗群岛海底Fani Maoré火山的熔岩中，发现了显著的正142Nd异常。同位素证据表明，驱动现今海洋岛屿火山活动的地幔源区，保留了可追溯至地球冥古宙时期的布里奇曼石成分。这一发现为理解地幔复杂动力学演化与早期地球物质的长期保存提供了关键的地球化学约束。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[地幔化学非均质性]: 确定其年龄和起源是关键挑战"]},{"i":38852,"as":"结直肠癌肝转移患者的预后受组织病理异质性影响，其中“替代型”转移瘤患者的5年生存率远低于“包裹型”。研究发现，患有肝脂肪变性的未接受治疗结直肠癌患者更容易发生“替代型”肝转移。机制上，脂肪变性促进的脂肪酸氧化通过乙酰化作用增加了MYC蛋白的稳定性，从而加速了替代型肝转移瘤的形成，揭示了脂质代谢在重塑转移瘤异质性及决定预后中的关键作用。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["5-year overall survival[replacement metastases]: <44.2%","5-year overall survival[encapsulated metastases]: 73.4%","occurrence of replacement metastases[liver steatosis]: increased","fatty acid oxidation[steatosis-promoted]: increases formation of replacement metastases","MYC stability[through acetylation]: increasing"]},{"i":38853,"as":"为解决将单细胞转录组身份与长程轴突投射相联系的难题，研究采集了小鼠视觉皮层的两组数据集：包含1,528个兴奋性神经元的Patch-seq数据（整合了局部形态、电生理和转录组数据），以及341个兴奋性神经元的全神经元形态数据。通过对这些数据的深入分析，研究成功定义了17种特定的细胞类型，建立了转录组特征与远距离投射组之间的映射联系。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":[]},{"i":38854,"as":"针对胶质母细胞瘤中抗原表达不均一及免疫微环境抑制导致CAR-T疗法易失败的难题，研究利用多组学靶点发现平台，鉴定出GPNMB蛋白作为一个双重靶点。该靶点不仅在肿瘤细胞中表达，也存在于占据微环境主导地位且维持免疫抑制的肿瘤相关巨噬细胞中。靶向GPNMB的CAR-T细胞能够同时攻击肿瘤实质和骨髓微环境这两个紧密偶合的恶怂数据区，从而克服单一靶向的局限性。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":[]},{"i":38855,"as":"研究揭示了细胞应对热应激引起细胞膜过度流动化的早期保护机制。在水稻中，P4-ATPase OsALA5及其β亚基OsALIS2介导了一种热响应的磷脂翻转过程。热暴露会在数分钟内诱导OsALA5转运活性发生转变，选择性地将饱和磷脂酰胆碱富集到细胞质侧的质膜小叶中。这种由OsALA5介导的脂质翻转作用有效防止了热应激下的细胞膜过度流动化，从而稳定了膜的物理性质。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["响应条件[热胁迫诱导]: 血浆膜过度流体化（hyperfluidization）","响应时间尺度[热暴露诱导的转运活性转变]: 分钟级（minute-timescale）","P4-ATPase OsALA5[互作β亚基]: OsALIS2","OsALA5转运活性[核心功能]: 介导热响应的饱和磷脂酰胆碱（saturated phosphatidylcholines）翻转","饱和磷脂酰胆碱[热应激下空间分布]: 在细胞质血浆膜小叶（cytoplasmic plasma membrane leaflet）发生选择性富集"]},{"i":38856,"as":"","scd":null,"kp":[]},{"i":38857,"as":"该研究开发了一种氧化还原介导的水流电化学系统，用于直接空气捕获（DAC）二氧化碳。系统结合了固体质子-电子载体（SPEC），在生成捕获所需的碱性溶液的同时，使SPEC与空气隔离。这一设计解决了氧化还原活性物质对氧气高度敏感的问题，实现了高达99.9%的库伦效率。其模块化的架构为低能耗、可扩展的电化学DAC技术提供了一条合理且可调的路径。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":7.0,"t":7.0},"kp":["库仑效率[氧化还原介导的水流系统]: 99.9%","质子电子载体[类型]: 固体(SPEC)","[系统设计]: 解决了氧化还原活性物质的氧敏感性，实现模块化和低能耗电化学直接空气捕获"]},{"i":38858,"as":"聚焦中国五个最大的工业排放源，研究发现加速清洁技术的开发与应用（而非等待），能触发更快的“干中学”效应，降低技术成本，并最终节省约8%的累计系统成本。研究指出，2035至2040年间存在一个关键时间窗口，如果在此之后延迟减排行动，将导致高碳基础设施锁定，进而带来代价更为高昂的减排路径。这一结论为全球工业气候政策制定提供了直接参考。","scd":{"b":5.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["累计系统成本节省[加速清洁技术发展路径]: 约8%","关键行动窗口期[中国重工业脱碳]: 2035-2040年"]},{"i":38859,"as":"","scd":null,"kp":[]},{"i":38860,"as":"二维硼烯（硼烯）因具有金属性、轻元素单层和高频声子等独特性质备受关注，但电子关联效应较弱且制备困难。该研究通过在三元硼化物表面暴露出六方蜂窝状硼晶格，成功实现了一种强关联的二维电子态。这一成果克服了传统s和p电子系统内禀弱关联的局限性，为基于硼烯的高密度态及涌现量子现象研究提供了一个优异的物理平台。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[二维硼烯]: 具有本征金属性、最轻元素单层结构和高频声子特征"]},{"i":38861,"as":"研究开发了一种为物联网设备供电的无毒薄膜电池。该电池利用先进的水分收集技术，将环境湿气作为电解质，兼具能量收集器和传统电池稳定高功率输出的优点。它在多种环境中开路电压约为1.6伏，比容量约52毫安时/克，比能量约81毫瓦时/克。其独特的仿生穿山甲鳞片结构设计赋予了电池极高的柔韧性、可拉伸性和机械稳定性。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[薄膜电池]: 无毒、利用环境湿气作为电解质"]},{"i":38862,"as":"研究构建了一种大面积的光可编程二维半导体平台。该平台将厘米级的单层WS2和WSe2与光响应偶氮苯分子覆盖层相集成。利用波长选择性的偶氮苯反式-顺式光致异构化反应，可以可逆地改变二维原子层沟道的电学特征。这一突破克服了以往仅限于微米级单器件的尺寸限制，为可重构电子学的发展和全新计算范式提供了高度可扩展的技术途径。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[大面积光可编程二维半导体]: 突破了微尺度单层器件限制，实现大面积可扩展技术"]},{"i":38863,"as":"","scd":null,"kp":[]},{"i":38864,"as":"本文揭示了恒星反馈在低质量星系重子物质缺乏现象中的关键作用。基于暗能量光谱仪（DESI）约40万个星系光谱的叠加分析，研究人员通过Mg II吸收线探测到了由恒星形成驱动的冷气体外流。计算表明，在仅有引力作用的前提下，低质量星系（恒星质量小于100亿倍太阳质量）产生的强大气体外流足以克服引力束缚逃逸至暗物质晕之外。这一发现为恒星反馈将重子物质驱散到星系外部提供了关键的直接观测证据，完美解释了为何低质量星系中缺乏重子物质，证实了恒星反馈是驱动星系内部与外部重子物质循环的核心机制。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["[低质量星系恒星反馈]: 驱动了冷气体外流并导致暗物质晕内重子物质匮乏"]},{"i":38865,"as":"大脑功能侧化是大脑组织的标志。研究应用多变量机器学习技术和大规模数据集，研究了全球大脑不对称性变化及其与认知、衰老及相关疾病的关联。结果揭示了此前未知的大脑半球间结构差异，建立了结构不对称与侧化功能间的联系，并识别出半球差异的衰老轨迹及阿尔茨海默病和帕金森病患者的特异性结构变化。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[全球大脑不对称性]: 存在显著的、此前未知的结构差异，并与认知、衰老及相关疾病有关"]},{"i":38866,"as":"缺血性脑卒中的高频无创监测对精准干预至关重要。为克服单模态检测局限，研究提出一种双模式概念验证方法，结合患者的尿液表面增强拉曼(SERS)光谱（微观分子指纹）和颈动脉B超（宏观器官病理），利用机器学习整合跨维度数据，成功将确诊的缺血性脑卒中患者与健康对照组区分开来。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[缺血性脑卒中监测]: 建立尿液中微观分子指纹与宏观器官病理事件间的精确相关性，实现无创双模态分析"]},{"i":38867,"as":"","scd":null,"kp":[]},{"i":38868,"as":"针对植入式和可穿戴设备对微型高效天线的需求，研究开发了泛音超宽带磁电(OUWB-ME)天线。该天线利用抛光硅基板中的高阶声学模式，在3至4GHz范围内实现了22.6GHz的-10dB带宽。封装成“μBots”后，在生物负载下仍保持稳定运行。体外实验证实了其生物相容性，离体大鼠和人体组织测试显示了可重复的光谱重塑。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["带宽[-10dB]: 22.6吉赫兹(GHz)","频段[磁电天线泛音能力]: 3-4吉赫兹(GHz)","[天线特点]: 利用硅基底的高阶声学模式，实现小型化、高效率的超宽带和抗方向敏感性"]},{"i":38869,"as":"","scd":null,"kp":[]},{"i":38870,"as":"传统光伏器件能量转换结论多通过测量激子动态的光学手段间接获得，这往往会高估长寿命激子的作用。使用新型超快光谱仪对比碳纳米管薄膜和器件发现，光吸收检测严重高估了长寿命激子对光伏性能的重要性。激子跨纳米管扩散时间仅为皮秒级，而光电流主要由这些短寿命激子产生，激子扩散对器件效率贡献极小。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["激子扩散[碳纳米管器件效率]: 贡献甚微"]},{"i":38871,"as":"有机阳离子（特别是FA+）的迁移是限制钙钛矿太阳能电池长期稳定性的主要因素。研究开发了一系列基于吡啶的配体，在相同加工条件下构建了结构明确的低维/三维异质结。平台对比表明，2D/3D构型能够独特地将几何限制与多向氢键结合，有效固定FA+阳离子并阻止其迁移，从而解决钙钛矿光伏材料的稳定性问题。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["配体尺寸设计[阻止钙钛矿光伏阳离子迁移]: 采用吡啶基配体实现统一尺寸设计"]},{"i":38872,"as":"","scd":null,"kp":[]},{"i":38873,"as":"","scd":null,"kp":[]},{"i":38874,"as":"本情报介绍了一种由同种金属元素组成的Nb4CuC3/Nb4C3Tx同质异质结，其因晶格匹配和低界面电阻，在锂离子电池中展现出卓越的循环稳定性，在10000次循环后容量几乎无衰减。为解决异质结构建与位点化学关联的难题，研究团队结合同步辐射核心级光谱和扫描透射电子显微镜，成功解析出该异质结内存在四种不同的铌配位环境。该研究通过先进表征技术精准定位了坚固异质结中的电化学活性位点，为高性能电化学应用材料的结构设计与机理研究提供了重要见解。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["同种金属元素构成的异质结[电化学应用]: 具有本征晶格匹配和低界面电阻"]},{"i":38875,"as":"","scd":null,"kp":[]},{"i":38876,"as":"脂质纳米颗粒(LNPs)在mRNA疫苗开发中被成功应用，但细胞内吞后的内体滞留限制了疫苗效力。研究提出一种“可编程机械运动”新机制，利用可移动脂质在特定信号输入下产生机械运动，破坏内体屏障并使其不稳定。该物理机制突破了优化脂质pKa和空间构成的传统方法瓶颈，有效增强了m疫苗的治疗效果。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["可移动脂质产生的机械运动[脂质纳米颗粒增强mRNA治疗效果]: 打破内体屏障"]},{"i":38877,"as":"细胞的镁离子转运机制一直未被充分阐明。研究鉴定出内质网Mg2+ ATP酶(ERMA)是驱动Mg2+进入内质网腔的转运蛋白，确立了内质网作为双离子细胞内储库的地位。靶向内质网的MagFRET生物传感器显示，ERMA介导了依赖ATP的Mg2+吸收，浓度达15至30毫摩尔。人和小鼠ERMA的冷冻电镜结构揭示了其作为ER储库看门人的作用机制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["ERMA[内质网Mg2+转运机制]: 驱动Mg2+进入内质网腔的ATP酶和储库看门人"]},{"i":38878,"as":"B7-H4是一种在实体瘤中广泛过表达而在正常组织中极少存在的免疫检查点。研究开发了一种B7-H4靶向的放射性诊疗抗体，分别用89Zr标记进行PET成像，用177Lu或225Ac标记进行β或α粒子靶向治疗。89Zr-immunoPET实现了B7-H4表达的定量全身可视化，准确区分了不同表达水平的肿瘤；放射性核素治疗有效抑制了肿瘤生长。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[89Zr]标记[实体瘤B7-H4靶向]: PET成像","[177Lu]或[225Ac]标记[实体瘤B7-H4靶向]: β或α粒子放射治疗"]},{"i":38879,"as":"","scd":null,"kp":[]},{"i":38880,"as":"着丝粒功能依赖于Scm3/HJURP伴侣蛋白沉积CENPA，但许多后生动物似乎缺乏该基因直向同源物。结合远程同源检测、基于AlphaFold的结构建模及功能遗传学，研究在斑马鱼和秀丽隐杆线虫中鉴定出此前未知的Scm3/HJURP直向同源物。这些蛋白定位于着丝粒，缺失会导致有丝分裂灾难。此外，果蝇中的CAL1被证实是其高度同源的直向同源物。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["Scm3/HJURP[后生动物着丝粒功能]: 沉积CENPA的深度保守直向同源物"]},{"i":38881,"as":"植物释放的挥发性化合物能调节生态互作，但多数缺乏特异性。研究发现，水稻在遭受褐飞虱攻击时，会通过由茉莉酸直接激活的O-甲基转移酶级联反应（BSMT1-MSOMT），合成并释放特定的水杨酸二甲基化分解产物——水杨酸二甲酯(DMSA)。与无特异性的水杨酸甲酯不同，DMSA作为一种未被充分认识的挥发性警报物质，介导了水稻特异性的生态反应。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["DMSA[水稻抵御褐飞虭特定挥发性警报]: O-甲基转移酶变异介导产生的二甲基化水杨酸分解代谢物"]},{"i":38882,"as":"突触传递的速度远超普通囊泡融合，而SNARE蛋白如何协作实现这一同步释放一直是谜。在一个完全明确且经过基因验证的系统中重建了快速突触小泡释放（小于7毫秒），并实现了释放前停靠囊泡中分子的单分子计数。结果显示，每个准备释放的突触囊泡含有约12个（±0.3）SNAREpin复合体，这表明存在一个规则的结构用于驱动超快的神经递质释放。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["SNAREpin数量[重建突触小泡快速释放]: 12个"]},{"i":38883,"as":"反式钙钛矿太阳能电池受限于镍离子引发的界面氧化还原反应和隐埋界面缺陷。研究提出一种界面锁定双分子接触策略，将Me-4PACz与CzOTf共组装，通过π-π共面堆积稳定分子取向并增强界面电子耦合，实现高效空穴提取。磺酸盐端基提供更广泛的铅相关缺陷配位，有效缓解界面缺陷。该技术成功将器件光电转换效率提升至27.3%。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":9.0,"t":7.0},"kp":["光电转换效率[反式钙钛矿太阳能电池界面锁定双分子接触]: 27.3%"]},{"i":38884,"as":"自主机器人辅助手术（RAS）的微型化发展催生了微机器人辅助手术（μ-RAS），有望实现微创、部分或完全自动化的手术程序。该技术旨在缩短患者康复时间并降低医疗成本。文章重点介绍了RAS在血管内、腔内、腹腔镜、眼科和骨科五个外科领域的微缩化进展，并指出了推动这些手术领域发展的关键技术创新需求。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":3.0,"t":4.0},"kp":["[自主机器人辅助和微型机器人手术]: 微型化辅助手术可减少创伤，实现部分或完全自动化手术程序，有望缩短患者恢复时间、降低医疗成本"]},{"i":38885,"as":"衰老与协调能量产生、生物合成和分子周转的代谢途径重编程密切相关，但在时空背景下可视化这些代谢动态是一项重大挑战。代谢成像作为一种变革性方法，能够在分子、细胞和生物体水平上对代谢动态进行空间分辨可视化。本文重点综述了多模态非线性光学成像技术及其在探索衰老生物学模型中的最新应用进展，为揭示衰老机制提供了独特见解。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":4.0,"t":3.0},"kp":["[多模态光学代谢成像]: 能够在分子、细胞和生物体水平上实现空间分辨的代谢动力学可视化"]},{"i":38886,"as":"","scd":null,"kp":[]},{"i":38887,"as":"自组装单层（SAM）推动了钙钛矿太阳能电池（PSCs）效率的提升，但其实际运行稳定性仍面临挑战。研究开发了一种基于酞菁的SAM，其结构坚固且化学键稳定，显著增强了光稳定性。通过四磷酸化修饰将酞菁牢固锁定在界面处，提升了热稳定性、电荷提取能力和组装均匀性。基于该技术制备的钙钛矿太阳能模块在20.3平方厘米孔径面积上实现了23.1%的认证效率（稳定效率22.9%），并展现出优异的户外稳定性。","scd":{"b":7.0,"i":4.0,"r":8.0,"d":7.0,"t":7.0},"kp":["自组装单层材料[钙钛矿光伏电池]: 基于四磷酸化酞菁，具有结构稳固的骨架和化学稳定键以增强光稳定性，四磷酸化使酞菁在界面处牢固锁定并提升热稳定性"]},{"i":38888,"as":"修复超长周围神经缺损是临床重大挑战，需要再生平台能够整合空间引导和时间生化线索。研究开发了一种全合成、临床可转化的神经导管，通过分层微拓扑工程和阶段特异性分子传递来模拟自然再生原则。其神经解剖学启发核心模拟了神经内膜和神经束膜，提供细胞级接触引导以促进轴突对齐和成束；双层鞘结构则确保了机械完整性和代谢渗透性，创造了促进再生的微环境。","scd":{"b":7.0,"i":5.0,"r":8.0,"d":7.0,"t":7.0},"kp":["[跨物种超长神经连续性修复]: 开发了临床可转化的全合成神经导管，结合分层微拓扑工程和阶段性分子递送，整合空间引导与时间分辨的生化线索"]},{"i":38889,"as":"将铁电体的单磁滞回线与反铁电体的双磁滞回线结合形成多重磁滞回线，对储能、电卡制冷等技术具有重要意义。研究提出一种低温制备锆酸铅（PbZrO3）薄膜的策略，在反铁电体中引入稳定的铁电态，在大电场下实现了三重磁滞回线。微观结构特征揭示了如何通过有意稳定连接铁电体非易失性和反铁电体场诱导相变行为的中间态，解决了基础物理挑战。","scd":{"b":7.0,"i":4.0,"r":8.0,"d":7.0,"t":7.0},"kp":["[反铁电薄膜]: 嵌入铁电开关环以产生巨大的负电热效应"]},{"i":38890,"as":"","scd":null,"kp":[]},{"i":38891,"as":"在析氧反应（OER）中，附着气泡通常被视为阻碍离子和质量的传输。研究利用集成多模态原位表征的透明芯片电解槽发现，对于离子聚合物涂层电极，气泡生长时三相接触线表现出钉扎-脱钉行为。当气泡尺寸超过临界值（约420微米）时，水分子从离子聚合物中释放到气泡-电极接触区域，形成微滴（<20微米）。这表明OER中存在复杂的泡内微滴和纳米气泡动态耦合演化机制。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":7.0,"t":7.0},"kp":["[析氧反应中的离子聚合物电极]: 揭示了微滴和纳米气泡在活性位点上复杂的泡内耦合演化动力学"]},{"i":38892,"as":"","scd":null,"kp":[]},{"i":38893,"as":"为了填补细菌基因组变异与代谢功能连接的图谱空白，研究构建了全基因组基因-蛋白质-反应关联，并将其应用于2377株大肠杆菌基因组，重建了泛基因组规模代谢模型（panGEM）。该模型在生长预测中达到约0.99的精度。研究鉴定出超过11000个罕见代谢基因，但仅对应35个罕见代谢反应。深入分析表明，这种不匹配是因为大多数罕见基因是通过水平基因转移获得的假基因或趋异直系同源物。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["分析样本量[泛基因组规模代谢模型]: 2377株大肠杆菌基因组"]},{"i":38894,"as":"","scd":null,"kp":[]},{"i":38895,"as":"从飞行器到生物系统，反馈系统稳定性的维持依赖于持续的行为监测和输入调整。微小损伤的累积会使得系统控制变得脆弱，传统依赖精确系统模型计算安全操作指令的工程方法在受损系统偏离模型时便会失效。研究演示了一种通过弹性动态指标监测反馈系统是否逼近不稳定状态的方法。这种整体系统安全监视器不依赖系统模型，而是基于系统的动力学响应来实时评估稳定性。","scd":{"b":5.0,"i":4.0,"r":7.0,"d":4.0,"t":7.0},"kp":["[复杂反馈系统稳定性]: 累积损伤会使系统控制变得脆弱，在微小扰动下易诱发失稳，传统依赖精确系统模型的工程方法在此时会失效"]},{"i":38896,"as":"溶酶体通过降解蛋白质和循环构建块来维持细胞稳态，溶酶体贮积症（LSDs）会影响多种溶酶体功能。为了促进不同LSD基因类别的分子表型分析，研究开发了一种人类胚胎干细胞文库，这些细胞被工程化改造为缺乏特定的23个LSD基因之一。该干细胞工具包涵盖了与鞘脂贮积症和神经元蜡样脂褐质沉积症相关的大多数基因，并成功用于生成皮质样和中脑多巴胺能样诱导神经元的蛋白质组学资源，实现了深入的丰度和相关性分析。","scd":{"b":6.5,"i":2.5,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":38897,"as":"同位素分馏是矿物从水溶液中沉淀机制的指示剂，但现有理论未考虑成核效应。研究以重晶石（BaSO4）为模型晶体，通过在有机薄膜上沉淀晶体使成核主导晶体生长，从而分离出成核效应。实验从有机基底上提取了约1.5纳米的纳米微晶，并在本体溶液中提取了生长主导的大微晶。基于138Ba/137Ba等同位素比率的测量，揭示了成核过程中的同位素分馏特征，这对非经典生长机制和生物结晶研究具有重要指导意义。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["模型晶体[同位素分馏测量]: 硫酸钡(BaSO4)"]},{"i":38898,"as":"丝状蓝细菌通过分化出称为异形胞的专门固氮细胞来实现固氮。基于系统遗传分析和转录系统重构，研究确定了HetZ是异形胞分化基因调控网络的核心激活因子。生化分析和冷冻电镜进一步证实HetZ是一种σ因子（σHetZ）。σHetZ中独特的结构域插入对于介导固氮细胞的特化和图灵样模式形成至关重要，揭示了调控细胞分化和空间模式化的分子机制。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["N2固定细胞特化[丝状蓝细菌]: 通过独特的σ因子协调细胞分化和类图灵模式"]},{"i":38899,"as":"钴胺素是多数生物的必需营养素，但仅由少数类群通过有氧或无氧途径合成。研究结合贝叶斯分子钟分析和系统发育协调，确定了钴胺素生物合成基因和生产者的出现时间框架。研究揭示，四吡咯前体和钴啉环的部分生产者的出现时间早于最古老的钴胺素完整生产者。这表明在从头合成钴胺素的生物出现之前，可能已经存在类钴胺素化合物，揭示了辅酶生物合成与早期生态系统代谢协同进化的历史时间尺度。","scd":{"b":4.5,"i":2.0,"r":6.0,"d":5.0,"t":3.0},"kp":["[钴酰胺生物合成进化尺度]: 利用贝叶斯分子钟确定了生物合成基因和生产者出现的时间框架"]},{"i":38900,"as":"类鼻疽伯克霍尔德菌的双功能血红素过氧化物酶（BpKatG）利用血红素和三个色氨酸残基作为独特的氧化还原辅因子。本研究利用共价连接的硝基氧化物非扰动自旋探针，直接探测了Trp153自由基与高价铁血红素中间体之间的长程多步电子隧穿途径，证实该过程由Trp94和Trp95介导。研究同时演示了高价铁中间体[Fe(IV)=O]与相关自由基中间体之间的电子转移平衡机制。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["[BpKatG双功能过氧化物酶]: 利用血红素和三个色氨酸(Trp139, Trp153, Trp330)作为独特氧化还原辅因子","[非扰动自旋探针]: 硝roxide战略连接物用于直接探测多步电子隧道"]},{"i":38901,"as":"对湍流环流波动的最新研究揭示了流动结构的统计组织和湍流间歇性的几何特征。环流概率分布函数可以用超统计学方法表示，即基于“玻尔兹曼-吉布斯系综”的集合来描述。该方法的一个基础唯象要素依赖于耗散场与基本环流承载结构（即小尺度涡旋）空间分布之间的强相关性。通过超统计学的语言，可以对湍流中的环流波动进行有效建模和特征描述。","scd":null,"kp":["环流概率分布函数[湍流环流波动]: 允许超统计表示（基于玻尔兹曼-吉布斯系综的集合）"]},{"i":38902,"as":"","scd":null,"kp":[]},{"i":38903,"as":"法国科学家Pierre Chambon是真核生物分子生物学和基因调控领域的先驱。他在基因表达和激素调控的基本机制方面做出了重大发现，并开发了突破性的小鼠基因技术，极大地推动了现代生物学和医学的发展。此外，他还确立了斯特拉斯堡作为欧洲生命科学研究领先中心的地位。他于2026年5月5日逝世，享年95岁。","scd":null,"kp":[]},{"i":38904,"as":"研究利用基因组学方法调查了广泛分布于美洲的斑马蝴蝶的局部适应性。尽管该物种在形态和基因上表现出高度同质性，但基因组分析揭示了三个地理范围受限的染色体倒位。这些倒位在近期的物种范围扩张中幸存下来，解释了基因组其余部分的同质性，证明了它们在局部适应性中的潜在作用，揭示了隐藏的遗传多样性。","scd":null,"kp":[]},{"i":38905,"as":"高维光子纠缠在提升量子通信、计算和计量学能力方面具有巨大潜力。针对全态层析成像成本过高且难以实现测量的问题，该研究展示了一种免扫描的时频域高维纠缠表征方法。该方法实现了创纪录的5.70 ± 0.07 ebits纠缠比特数和65.4 ± 0.4%的保真度，在1021维局部维度下成功认证了668维的纠缠态。","scd":{"b":7.0,"i":3.5,"r":7.0,"d":7.0,"t":6.0},"kp":["[大字母量子通信协议]: 具有增强的抗噪性和高信息容量","[多维纠缠态表征]: 演示了免扫描与低测量成本的光谱和时间频率可扩展光子纠缠释放"]},{"i":38906,"as":"","scd":null,"kp":[]},{"i":38907,"as":"血红素铜氧化酶是电子传递链的末端复合物，利用氧气还原的能量泵送质子以驱动ATP合成。研究通过位点选择性光谱方法克服了其他氧化还原中心严重重叠的光谱特征干扰，揭示了活性位点铜及其交联酪氨酸残基的直接作用。这一发现从分子层面阐明了血红素铜氧化酶质子泵送的机制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[血红素铜氧化酶活性位点]: 存在独特的交联酪氨酸且电子离域的铜酪氨酸态","[质子泵送机制]: 铜酪氨酸态在跨膜质子泵送以驱动ATP合成中发挥关键作用"]},{"i":38908,"as":"研究在槐豆胶水凝胶中发现了一种反直觉的现象：高压处理会导致水凝胶软化而非硬化。在高达1.2 GPa的反复压缩-减压循环下，水凝胶的弹性模量逐渐下降至初始值的约31%。与此相反，反复的冻融循环会使其弹性模量增加约2.3倍。扫描电子显微镜观察揭示了这种软化现象背后的结构转变。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[高压处理对水凝胶的影响]: 引起常规交联增强(硬化)，但在角豆胶(LBG)水凝胶中引发反常软化","[弹性模量G']: 用于精确量化水凝胶机械性能的关键参数"]},{"i":38909,"as":"研究利用超快二维红外光谱电化学方法，探测了普鲁士蓝这种兼具电致变色和储能特性的材料内部的电子传递过程。实验测量了随着材料逐渐从普鲁士白氧化为普鲁士蓝时，沉积在电极上的薄膜内部电子转移率与施加偏压电位的关系。该材料固有的CN伸缩模式被用作探测铁氧化态和溶剂化动力学的局部探针。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["电子转移[普鲁士蓝皮秒级]: 受限于受限水动力学","结构演变[逐渐氧化过程]: 普鲁士白向普鲁士蓝渐进转变"]},{"i":38910,"as":"","scd":null,"kp":[]},{"i":38911,"as":"","scd":null,"kp":[]},{"i":38912,"as":"","scd":null,"kp":[]},{"i":38913,"as":"","scd":null,"kp":[]},{"i":38914,"as":"","scd":null,"kp":[]},{"i":38915,"as":"探讨环境科学家为何比以往更需要接受伦理培训，强调环境科学研究中的伦理规范与职业操守问题。","scd":null,"kp":[]},{"i":38916,"as":"研究发现小麦中的蔗糖非发酵1相关蛋白激酶1的α催化亚基TaSnRK1α1是赋予小麦热胁迫耐受性并增加粒重的关键调节因子。转录因子TaMYB55直接结合TaSnRK1α1启动子激活其表达。该启动子上的A到G碱基替换增强了TaMYB55的结合亲和力，并与小麦耐热表型共分离。此外，TaSnRK1α1还与下游蛋白发生互作并使其磷酸化。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[小麦热胁迫]: TaMYB55直接结合TaSnRK1α1启动子激活其表达，提升耐热性并增加粒重"]},{"i":38917,"as":"在逆转录病毒（如HIV-1）感染的早期阶段，宿主的核心组蛋白和连接组蛋白H1被迅速沉积到未整合的病毒DNA上，使其转录沉默。这种沉默伴随着高水平的H3K9三甲基化和低水平的H3乙酰化等组蛋白翻译后修饰。研究证实，同时敲除相关组蛋白H1能够揭示其在促进未整合病毒DNA沉默和染色质压缩中的关键调节作用。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[未整合HIV-1 DNA转录抑制]: 宿主核心组蛋白(H2A,H2B,H3,H4)和连接组蛋白H1迅速沉积，通过组蛋白翻译后修饰沉默病毒DNA"]},{"i":38918,"as":"研究综合单通道平面双分子层电生理、基于纳米盘的双电子-电子共振光谱、原子建模和纳米盘递送策略，探究了跨膜蛋白BsYetJ的门控机制。研究解析了一种由具有不同物理作用的双盐桥控制的分层静电门控机制。该机制阐明了局部静电信号如何转化为门控的钙离子渗透以及控制跨膜和活细胞中的钙离子泄漏。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["[质子门控与钙离子泄漏调控]: BsYetJ通过双盐桥结构进行调控"]},{"i":38919,"as":"VHL基因缺失及随之而来的HIF2α激活是透明细胞肾细胞癌发病的关键驱动因素。研究揭示了TRAIL（肿瘤坏死因子相关凋亡诱导配体）在VHL缺陷型ccRCC中的合成必要性。受VHL-HIF2α轴调控上调的TRAIL通过激活p38 MAPK通路并促进G1/S期转换，选择性地促进癌细胞增殖。耗竭TRAIL有效抑制了肿瘤细胞增殖，为联合靶向治疗提供了新机会。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[VHL缺陷型肾细胞癌]: VHL-HIF2α轴为主要驱动因子，可通过belzutifan共靶向HIF2α及相关脆弱性进行控制","[ccRCC靶点合成必要性]: TRAIL/TNFSF10在VHL缺失下表现出合成必要性"]},{"i":38920,"as":"研究构建了包含346个新增RNA-seq数据集、覆盖43种单一碳源培养条件下的大肠杆菌881条件转录组图谱（PRECISE-NP881）。利用独立成分分析量化了137个独立基因表达模块的活性，鉴定出25个碳分解代谢模块。通过总结这些模块在43种底物上的活性模式，将其划分为四个由活性定义的底物组，揭示了基因表达模式与生长速率的关联。","scd":{"b":6.0,"i":2.0,"r":8.0,"d":9.0,"t":5.0},"kp":["转录图谱数据集[E.coli碳响应]: PRECISE-NP881（包含881个条件转录组，346个RNA-seq图谱，43种单一碳源）"]},{"i":38921,"as":"研究揭示了二价组蛋白读取器EBS在氮缺乏响应和控制植物开花转变中的关键作用。EBS能识别H3K27me3和H3K4me3标记，通过改变结合偏好来调节从营养生长到生殖生长的转换。氮营养和TOR信号通路通过直接的TOR-EBS相互作用调控EBS蛋白丰度。TOR在S195和S196位点磷酸化EBS，从而促进其稳定性并抑制下游基因转录。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[缺氮响应与花的转变]: EBS（二价组蛋白读取器）通过改变对H3K27me3和H3K4me3组蛋白标记的结合偏好进行调控"]},{"i":38922,"as":"研究证明了多组分流体可以被设计成将不同的凝聚物招募到具有不同组成的表面上，通过凝聚过程执行表面分类。类比于机器学习中的多维分类，研究探索了类似隐藏节点的隐藏物种如何扩展这些相互作用集合的表达能力和容量，从而在拥挤且嘈杂的环境中促进组合决策。揭示了表面生物分子凝聚体在信息处理网络中的物理决策机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":38923,"as":"","scd":null,"kp":[]},{"i":38924,"as":"","scd":null,"kp":[]},{"i":38925,"as":"","scd":null,"kp":[]},{"i":38926,"as":"提出一种全高斯且实验可行的方案，用于同时估算双通道光网络的四个实数参数。该方案使用双模压缩探针和双输出端口平衡零差检测来实现海森堡极限标度表征。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":9.0},"kp":["[双通道光网络]: 采用两端口平衡零差检测和双模压缩探针实现四个实参数的海森堡标度同时估计"]},{"i":38927,"as":"利用双振荡器红外自由电子激光器的双色运行，成功控制并表征了超流氦纳米液滴内离子的异构体数量。两台激光器在时间上高度同步，且频率可独立调节。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":9.0},"kp":["[双振荡器红外自由电子激光器]: 实现双色操作且两台激光器在时间上高度同步、频率可调谐","[超流氦纳米液滴内离子]: 实现异构体数量的控制与表征"]},{"i":38928,"as":"结合远红外振动光谱技术与计算模拟，能够更精确地测定小阳离子铁簇的几何结构和自旋磁矩，从而解决其自旋态差异问题。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":9.0},"kp":["[小阳离子铁簇测量]: 结合远红外振动光谱与计算模拟技术精确测定其几何结构和自旋磁矩"]},{"i":38929,"as":"提出利用光镊对显微里德伯电子轨道进行局部操纵和时空雕刻。该方法将原子势中的激光冷却捕获与里德伯原子激发相结合，以诱导长程相互作用。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":5.0,"t":9.0},"kp":["[里德伯电子轨道操纵]: 利用光镊实现显微里德伯电子轨道的局域操纵和时空雕刻"]},{"i":38930,"as":"在变形密度泛函理论和自洽Hartree-Fock-Bogoliubov计算的框架下，研究了质子数在82至126之间的超重核的α衰变性质，并采用了SkM*和SLey4 Skyrme相互作用参数化。","scd":{"b":4.0,"i":1.0,"r":6.0,"d":6.0,"t":9.0},"kp":["质子数范围[超重核衰变性质研究]: 82≤Z≤126","理论框架[超重核衰变性质研究]: 形变密度泛函理论和自洽Hartree-Fock-Bogoliubov计算","Skyrme相互作用[α衰变计算]: SkM* 和 SLy4"]},{"i":38931,"as":"通过在双层光子晶体中设计各向同性带间耦合，构建了拓扑保护的单向引导谐振连续环。该结构能够将涡旋激光发射锁定在单一方向。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":6.0,"t":9.0},"kp":["[双层光子晶体]: 通过设计各向同性带间耦合构建连续环","[单向引导谐振(UGR)]: 具有拓扑保护特性且能将涡旋激光发射锁定在单一方向"]},{"i":38932,"as":"将迭代多体方案中的误导性收敛问题与Luttinger-Ward泛函的分支问题解耦，提供了一种严格的、不依赖于模型的程序，确保其收敛于物理真实的解。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":4.0,"t":9.0},"kp":[]},{"i":38933,"as":"提出了一种物理一致的公式体系，通过从约束从头算分子动力学轨迹中计算有限温度下的耦合离子-电子转移自由能表面，为电化学电流-过电位关系提供了一条第一性原理计算途径。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":5.0,"t":9.0},"kp":["[耦合离子电子转移的电流-过电位关系]: 通过计算有限温度下的约束从头算分子轨迹自由能表面提供第一性原理物理一致性框架"]},{"i":38934,"as":"通过将理论计算与质子和反质子的横向动量谱及产额比值进行对比，限制了介质内质量修改的范围。基于此约束和具有径向流的高斯源模型进行了数据分析。","scd":{"b":4.0,"i":1.0,"r":6.0,"d":5.0,"t":9.0},"kp":[]},{"i":38935,"as":"结合原位偏压加热透射电子显微镜与基于第一性原理的计算模拟，直接观察到了BaTiO₃铁电晶体临界点附近的结构无序现象，揭示了非弛豫系统的结构起源。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":9.0},"kp":["[铁电材料临界点附近的结构无序]: 结合原位偏压加热透射电子显微镜与第一性原理计算进行观察"]},{"i":38936,"as":"探讨利用脉冲电解技术从丰富的小分子（如水、二氧化碳、氮气等）中合成碳-杂原子（C-X, X=N, S, P）键，以解决传统静态电解中产品范围窄和电流效率低的问题，构建清洁化工技术平台。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["产物范围[常规静态电解C-X耦合反应]: 较窄（以尿素为主）","电流效率[常规静态电解C-X耦合反应]: 中等"]},{"i":38937,"as":"介绍基于脂质封端的晶体管技术，探讨其在心脏床旁快速检测中的应用，属于生物传感器与医疗电子技术。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":4.0,"t":5.0},"kp":["技术特征[心脏床旁检测]: 脂质封端晶体管"]},{"i":38938,"as":"构建了一种由双(亚氨基)萘啶支撑的N-杂环卡宾衍生的有机氧化还原系统，具备两个可逆分离的氧化还原过程。其自由基阳离子在可见光区域具有强吸收，适用于连续可见光光催化等领域。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[有机氧化还原系统衍生前驱体]: 双亚胺苝","[连续可见光光催化有机氧化还原系统]: 退火N-杂环卡宾衍生"]},{"i":38939,"as":"提出一种基于大面积触觉耦合的人机物理交互连续耦合范例。通过在腰部和腋下等机械意义区域进行安全交互，机器人可直接参与调节人机耦合动力学，提供步行辅助和稳定性支持。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[步行辅助物理人机交互]: 采用人体躯干大面积触觉耦合实现意图对齐和全身动力学稳定支撑"]},{"i":38940,"as":"","scd":null,"kp":[]},{"i":38941,"as":"","scd":null,"kp":[]},{"i":38942,"as":"报道了一种利用季铵调节网络制备抗冲击水凝胶的方法。该方法无需繁琐的后处理或高能耗，通过将含有极性基团的聚合物中的刚性结构域转化为动态结构，显著提升了水凝胶的机械性能和环境稳定性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[抗冲击结构水凝胶网络调节机制]: 季铵盐调节"]},{"i":38943,"as":"","scd":null,"kp":[]},{"i":38944,"as":"报道了稀土半赫斯勒化合物中的卓越热电性能。其晶格框架软化引发了4c亚晶格内的剧烈原子振动，增强了晶格非谐性和声子阻尼，从而产生本征低晶格热导率，且重元素占据4c亚晶格时该效应进一步增强。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[稀土半赫斯勒热电材料性能优化机制]: 亚晶格软化诱导产生本征低晶格热导率"]},{"i":38945,"as":"固态锂电池（SSLBs）通过使用固态电解质消除了漏液问题，提升了热稳定性，并允许使用高压阴极和锂金属阳极，从而满足对更高能量密度、安全性和使用寿命的储能系统需求。高镍层状氧化物被视为极具潜力的候选阴极材料，有助于克服传统液态锂离子电池中电解液易燃和不稳定带来的发展限制。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[高镍正极固态锂电池]: 解决液态电解液易燃性和电化学不稳定性，提升能量密度、安全性和使用寿命"]},{"i":38946,"as":"本研究提出一种平面度-位阻平衡策略，开发了具有最小吸收蓝移的反平行堆积H-聚集体，用于I型光动力治疗（PDT）。该策略利用π桥平面化驱动H型组装，同时通过对供体位点的空间位阻调节来控制蓝移程度，有效解决了传统平行堆积H-聚集体由于强烈的激子耦合导致的大幅吸收蓝移（通常>100 nm）及组织穿透力差的问题。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[I型光动力疗法反平行H-聚集体开发策略]: 平面度-位阻共平衡"]},{"i":38947,"as":"本研究在倒置钙钛矿太阳能电池的电子传输层（ETL）界面构建了由4-氨基苯甲酸盐酸盐（4AA）和二苯并-18-冠-6（DB18C2）组成的共组装混合中间层。4AA分子嵌入DB18C6聚集体中使单分子层均匀化，将表面覆盖率从0.57提升至0.79，界面偶极矩从2德拜增强至7德拜。该中间层通过4AA的─NH3+和─COOH基团中和离子缺陷，实现双钝化效果，提升界面稳定性。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[倒置钙钛矿太阳能电池电子传输层界面工程]: 4-氨基苯甲酸盐酸盐(4AA)与二苯并-18-冠-6(DB18C6)共组装构建混合中间层"]},{"i":38948,"as":"研究人员开发出一种具有分级结构的玉米醇溶蛋白-铈杂化微粒，能够实现超过40天的持续活性氧（ROS）清除和供氧，并释放骨诱导因子。该微粒利用疏水性玉米醇溶蛋白核心稳定氧源并抑制暴发性释放，同时结合铈纳米酶，有效克服了传统释氧生物材料初期突发性释放氧气及伴随高水平氧化应激的问题，用于骨组织微工程。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[常规释氧生物材料]: 存在短期内暴发式释放并伴生高水平活性氧(ROS)导致氧化应激的技术瓶颈","[Zein-Ceria杂化微颗粒]: 实现长效活性氧清除与持续供氧，用于成骨微组织工程"]},{"i":38949,"as":"该研究为无阳极电池中间层的合理设计建立了设计过滤器，结合了依赖于粗糙度的闭合模型与活性金属库存核算。分析表明，中间层的可行性取决于形态、化学和沉积物理学的严格交集：涂层必须在实际电池基板上保持连续，同时需与有限的源自阴极的金属库存兼容。低摄取合金中间层在中等厚度下仍具库存效率，而转化氧化物和氮化物通常需要超薄设计。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[无阳极电池中间层设计]: 涂层必须在实际电池基底上保持连续性，受形貌、化学性质与沉积物理学的严格交集控制"]},{"i":38950,"as":"研究在DIII-D托卡马克装置上设计并应用了基于机器学习的预测与控制通用算法（PACMAN）。该架构覆盖从诊断处理到最终执行指令的端到端高级控制实验，成功实现了传统控制器难以达到的控制状态，如撕裂模（TM）抑制、无边缘局域模（ELM-free）以及稳定的高级托卡马克运行，包括强化学习控制实验。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[DIII-D托卡马克装置AI控制]: 部署基于机器学习的PACMAN通用算法，实现传统控制失效的撕裂模式抑制、无ELM等先进运行场景"]},{"i":38951,"as":"研究在设备相关的高真空环境（约10^-7 mbar）下，应用皮秒激光诱导击穿光谱（ps-LIBS）对W7-X仿星器偏滤器的死后石墨瓦片进行了异位分析。该技术成功获取了碳（C）、硼（B）、氢（H）和氧（O）的极向分辨二维分布图和深度剖面，为评估面向等离子体部件的等离子体-壁相互作用（PWI）驱动的杂质源提供了定量、空间分辨的近表面成分测量数据。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":7.0,"t":4.0},"kp":["[W7-X偏滤器表面元素分布]: 采用皮秒激光诱导击穿光谱在真空环境下进行异位定量与空间分辨测量"]},{"i":38952,"as":"WEST装置在2023至2025年间实现了超过1000秒（最高纪录1337秒）的稳健长脉冲放电。该装置配备了完全主动冷却的ITER级偏滤器，产生了高达12 MW/m²的热通量和超过10^27 D/m²的粒子注量。偏滤器单体顶部出现裂纹但未影响功率排气能力。此外，偏滤器磁场高通量侧沉积的厚层易剥落导致等离子体杂质增加，现已采用激光清洗工艺进行处理。","scd":{"b":5.0,"i":6.0,"r":6.0,"d":8.0,"t":5.0},"kp":["长脉冲放电持续时间[WEST托卡马克]: 1337 s","热流密度[WEST托卡马克]: 12 MW m−2","粒子通量[WEST托卡马克]: 超过 1027 D m−2","[全主动冷却偏滤器]: 单块顶部表面出现裂纹但不影响排气功率"]},{"i":38953,"as":"研究人员在东北亚地幔过渡带发现了一个长约1000公里的连续弧形板片间隙。通过地震层析成像和三维波形建模等联合分析，确认该间隙是由停滞板片内的机械撕裂形成。间隙边界狭窄且温度与环境上地幔相当，比地幔柱温度低200°C以上，没有异常的热证据。该平面形态与三联 junction 的迁移路径一致，表明其是由板块撕裂形成的非热结构。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":8.0,"t":4.0},"kp":["几何尺度[东北亚地幔过渡带板片间隙]: 约1000公里长连续弧形","热力学状态[东北亚板片间隙]: 无异常热证据的非热状态"]},{"i":38954,"as":"研究开发了一种名为TEMPER的可编程一锅法聚合酶介导的DNA合成平台，仅通过温度控制即可实现任意DNA合成，无需溶液交换。该平台利用发夹DNA作为温度响应性构建模块，通过发夹的长度设计来设定特定的DNA合成温度范围，从而调节DNA分子间的热力学相互作用，实现单反应体系内的选择性和连续性DNA合成，大幅简化了多步工作流程。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[恒温介导引物交换反应]: 仅通过温度控制实现无溶液交换的任意DNA可编程合成"]},{"i":38955,"as":"研究结合固态核磁共振（ssNMR）、多变量统计分析和分子建模，对13种富含13C的杨树基因型的纳米级结构进行了分析。结果揭示了植物次生细胞壁高度保守的大分子架构，其组成、结构和聚合物间的邻近度表现出细微但协调的变异。原子尺度模型重现了这些特征，分子动力学模拟支持了纤维素与木质素之间存在微弱但明确的侧向共存缔合。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["[杨树次生细胞壁大分子结构]: 13C固态核磁共振结合原子模型揭示其具有跨物种的保守纳米级结构特征"]},{"i":38956,"as":"超闪寒事件（短时间内剧烈降温）在全球变暖背景下呈现出分歧趋势：在欧亚大陆逐渐减弱，但在北美洲却显著增强。这种由特定大气环流机制驱动的差异，主要归因于北美洲阿拉斯加-北极反气旋的日益频繁。这类能在数小时内冻结能源电网和基础设施的极端寒冷事件打破了全球变暖将使冬季温和的传统假设，如2021年北美寒流造成了超200亿美元的损失。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[超闪寒事件]: 在全球变暖背景下于北美显著增强，表现为可在数小时内使电网与基础设施瘫痪的剧烈骤降温"]},{"i":38957,"as":"研究表明，Schlafen核酸酶在哺乳动物中通过切割RNA抵御病毒感染，但其在原核生物中的免疫机制尚不明确。最新研究发现了一类与CRISPR相关的Cash蛋白，它由Schlafen结构域和Csx15传感器融合而成。在III型CRISPR免疫期间，Cash会被产生的环四腺苷酸（cA4）激活，随后通过切割tRNA（主要在T环部位）引发细胞毒性，从而发挥抗病毒作用。\n\n冷冻电镜结构解析进一步揭示了Cash与cA4结合后的组装及切割tRNA的分子基础。此外，研究还发现了大量与不同抗病毒防御系统相关的原核Schlafen蛋白家族。这项工作表明，利用Schlafen核酸酶耗竭tRNA是生物进化中一种高度保守且反复出现的抗病毒免疫策略。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[Cash蛋白激活]: III型CRISPR干扰期间产生的cA4激活","[细胞毒性诱导机制]: 切割tRNA（主要在T-loop）","[Cash蛋白结构]: Schlafen结构域与Csx15（Rossmann样核苷酸结合传感器）融合"]},{"i":38958,"as":"本研究通过古基因组学揭示了过去1.2万年来东亚西南部（特别是此前存在数据空白的贵州地区）的复杂人群演化史。结合广西和云南的数据，研究发现旧石器时代晚期该地区人群表现出高度的遗传异质性，包含一种新发现的基底东亚祖先成分（Xingyi_EN）与东亚北方祖先成分的混合。到青铜时代，这种神秘的基底祖先成分在该地区已完全消失。约从1200年前起，贵州与广西人群间的基因交流显著增强。该成果为了解早期人类迁徙及西南地区跨区域基因互动提供了关键证据。","scd":{"b":7.0,"i":2.0,"r":8.0,"d":6.0,"t":5.0},"kp":["[古基因组研究时间跨度]: 过去12000年","[贵州古人类样本(>10000年)]: 5个个体"]},{"i":38959,"as":"研究开发了一种柔性、无电池的水凝胶生物电子贴片，集成生物功能与无线信号传输，用于牙周炎的监测和局部微小核糖核酸（miRNA）免疫调节。该水凝胶由明胶和可被基质金属蛋白酶（MMPs）裂解的生物活性肽序列合成，能够特异性响应与牙周疾病进展相关的蛋白酶活性，通过酶促降解实现无线定量信号传导与药物释放。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[生物电子贴片特性]: 柔性、无线无电池水凝胶基","[牙周炎局部治疗干预]: 局部递送miRNA"]},{"i":38960,"as":"探讨狗与人类在演化过程中的趋同进化现象，提出利用狗作为研究人类社会行为与心理健康的新模型系统。","scd":{"b":4.0,"i":2.0,"r":3.0,"d":2.0,"t":4.0},"kp":["[人类社会行为与心理健康研究]: 提出利用狗作为新模型系统"]},{"i":38961,"as":"本研究以马里亚纳海沟为代表，通过三维模型探讨了地幔环形流对大洋内海沟弯曲和热化学传输的调节机制。当俯冲板块沿海沟存在明显的密度变化及大型浮力块体（如加罗林板块）时，地幔楔中会产生剧烈的动态压力波动，引发从浮力段延伸超过1000公里的强烈环形流。这一机制即使在非线性地幔流变学下依然显著，控制了海沟几何形态和深部地幔状态。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[大洋海沟弯曲现象]: 超过1000公里","[海沟弯曲与地幔楔热化学变化诱因]: 俯冲板块存在急剧密度变化并伴随洋内海沟大幅后撤"]},{"i":38962,"as":"研究构建了两种半翅目物种（长翅型和短翅型）替代翅膀发育的单细胞转录组图谱，鉴定出6种保守细胞类型。基因沉默实验表明，翅膀图案基因En（上皮样细胞）和bs（气管细胞）以及细胞周期基因Anln、CycB3和cdk1（神经元细胞）对长翅发育至关重要。流式细胞术证实，长翅型的形成主要依赖于细胞周期持续时间的延长，而非细胞增殖速率的提升。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[替代翅膀发育测序]: 长翅型和短翅型定向翅芽单细胞RNA测序","[翅型分化保守细胞类型]: 6种","[RNA干扰沉默标记基因数量]: 51个"]},{"i":38963,"as":"2021年美国《两党基础设施法》为安全饮用水项目拨款307亿美元，并规定49%的资金必须以拨款或可免除贷款形式提供给“弱势社区”。各州被赋予自行定义“弱势社区”的权限。研究分析了2019至2023年的资金分配情况，指出尽管各州广泛更新了弱势社区的定义，但在饮用水资金分配上依然存在普遍的种族和民族差异。","scd":{"b":2.0,"i":8.0,"r":6.0,"d":9.0,"t":7.0},"kp":["[美国饮用水基础设施投资]: 307亿美元","[弱势社区拨款及可豁免贷款比例]: 49%"]},{"i":38964,"as":"研究发现L型脓毒素通过抑制细菌表面的β-桶组装机器（BAM）复合物来杀死铜绿假单胞菌，且在此过程中无需进入细胞内部。冷冻电镜结构显示，L型脓毒素结合BamA的表面暴露区域，并通过其C端肽竞争性抑制BAM复合物，从而阻断外膜蛋白组装。这证明了抗生素的杀菌活性不依赖于细胞内化，为应对革兰氏阴性菌的天然防御机制提供了新途径。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[L型脓毒素杀菌机制]: 细胞表面抑制BAM复合物（阻止外膜蛋白组装，无需进入细胞）"]},{"i":38965,"as":"《能源研究与社会科学》上发表的文章指出，在制定氢能管道决策的过程中，公众参与意愿与现行法律框架之间存在明显差距。该研究强调了在推进氢能基础设施项目时，现有的法律和监管机制未能充分满足公众参与决策的实际需求。","scd":{"b":2.0,"i":4.0,"r":4.0,"d":2.0,"t":4.0},"kp":["[氢能管道决策]: 存在公众参与偏好与现行法律框架之间的差距"]},{"i":38966,"as":"","scd":null,"kp":[]},{"i":38967,"as":"","scd":null,"kp":[]},{"i":38968,"as":"","scd":null,"kp":[]},{"i":38969,"as":"","scd":null,"kp":[]},{"i":38970,"as":"","scd":null,"kp":[]},{"i":38971,"as":"Nanna Myllys 和 Dominika Pasik 探讨了异戊二烯分子如何将生物圈与大气圈联系起来。文章重点介绍了异戊二烯在连接植物与全球气候系统中所起的关键作用，并详细论述了该分子在植物生态、人类生理、材料科学以及气候调节等多个不同领域中发挥的多种重要功能。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["[异戊二烯]: 作为关键物质纽带将生物圈与大气圈相联系，并对植物、人类、材料及气候产生广泛影响"]},{"i":38972,"as":"能够围绕中心轴进行360度旋转的分子有望驱动纳米级机器的运动与功能。本期内容收录了多篇专题文章，集中展示了旋转分子马达领域的最新技术进展，并深入探讨了该领域在未来研究和实际应用中所面临的技术挑战与发展方向。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["旋转角度[分子马达]: 360°"]},{"i":38973,"as":"","scd":null,"kp":[]},{"i":38974,"as":"值此Ben Feringa荣获诺贝尔化学奖（表彰其在分子机器设计方面的贡献）十周年之际，他接受了《自然-化学》的专访。在访谈中，他回顾了自己的学术职业生涯，详细分享了他关于分子马达和光开关的最新研究进展，并为年轻科研人员提供了宝贵的职业发展建议。","scd":{"b":3.0,"i":2.0,"r":4.0,"d":2.0,"t":4.0},"kp":[]},{"i":38975,"as":"","scd":null,"kp":[]},{"i":38976,"as":"","scd":null,"kp":[]},{"i":38977,"as":"该作者更正声明针对原文章，原研究提出利用生物催化去消旋化技术，合成对映体富集的阻转异构体化合物。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":4.0,"t":5.0},"kp":[]},{"i":38978,"as":"防止自组装分子（SAMs）脱落并增强对钙钛矿材料的钝化作用是提升钙钛矿太阳能电池性能和稳定性的关键。研究采用电沉积法替代传统溶液处理工艺，利用循环电位电沉积促进分子的重排与重新锚定，在氧化铟锡（ITO）基底上生成了覆盖均匀且锚固密集的SAM层。基于该基础层，通过电化学氧化偶联生长出定制化偶联咔唑膦酸SAMs，显著提高了器件的能量转换效率。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["自组装分子[钙钛矿光伏电池]: 电沉积自组装分子","[钙钛矿电池]: 防止自组装分子脱落并增强对钙钛矿的钝化作用"]},{"i":38979,"as":"地衣是真菌与光合共生体形成的互利共生体，能在贫营养环境中繁衍。研究解析了地衣真菌Xanthoria parietina的铁获取系统，发现该真菌共生体能够产生铁载体，并具备铁载体合成、还原性铁同化、解毒及调节的完整基因库。其合成铁载体的非核糖体肽合成酶具有地衣特有的紧凑结构，且在异源表达时功能保持完好。这表明真菌通过产生铁载体来支持其微藻共生体的铁需求。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["铁载体[地衣真菌 Xanthoria parietina]: 铁色素 (Ferrichrome)"]},{"i":38980,"as":"研究制备了一种Ru-NiMn/NF-IH催化剂，揭示了其通过改善底物吸附能力、促进去质子化过程以及调节反应路径（–CHO/–CH2OH途径），有效提升了析氢反应（HER）和生物质衍生分子电氧化（HMFOR）的催化活性。该发现将催化反应机制与催化剂设计紧密结合，为提升电氧化催化剂的活性与耐久性提供了重要设计思路。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["催化剂[生物质衍生分子电氧化]: Ru-NiMn/NF-IH","[Ru-NiMn/NF-IH催化剂]: 提高底物吸附、促进去质子化并调节反应路径(–CHO/–CH2OH途径)"]},{"i":38981,"as":"","scd":null,"kp":[]},{"i":38982,"as":"晶格失配产生的表面应变可提升电催化活性，但厚膜易发生不可逆的应变弛豫。以电化学氧还原反应的外延铂薄膜为例，研究证明存在一个避免不可逆应变弛豫的厚度依赖性临界应变值。第一性原理计算表明，临界应变范围为-8.2%（压应变）至2.7%（拉应变），并在厚度约3纳米以内的铂膜中维持了-2.5%的最优应变值。这一发现界定了优化催化剂稳定性和活性的最佳厚度区间。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["表面应变状态[外延铂电催化剂]: 厚度依赖的临界应变(低于该值发生不可逆应变弛豫)"]},{"i":38983,"as":"","scd":null,"kp":[]},{"i":38984,"as":"","scd":null,"kp":[]},{"i":38985,"as":"","scd":null,"kp":[]},{"i":38986,"as":"将非生物催化辅因子引入蛋白质骨架构建的人工酶，在催化无天然对应物的反应中展现出潜力。研究提出一种细胞内人工酶组装策略，通过将表达目标蛋白的细胞与合成催化辅因子共孵育，利用二硫键形成实现位点半特异性共价锚定。这种在细胞内高效组装的人工酶，能够以极高的对映选择性催化细胞质环境中的不对称Mannich反应。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["人工酶[胞内组装]: 引入非生物催化辅因子并通过共价锚定的蛋白质支架","[胞质内: 提高细胞内复杂环境下的立体选择性生物合成能力"]},{"i":38987,"as":"研究发现酮类异构酶(KSI)在催化类固醇生物合成的关键异构化步骤外，具有混杂催化活性，能将环烯酮高效转化为同源和异源加成产物。KSI变体的晶体结构和诱变实验表明，其同源二聚体交界面是一个新的活性中心。分子动力学模拟和量子力学计算揭示了一种单酶级联催化机制：异构化发生在单体口袋中，而加成反应优先发生在二聚体交界面。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["催化混杂性[酮类异构酶(KSI)]: 高效转化环烯酮生成同型和异型加成产物"]},{"i":38988,"as":"本文提出了仿生协同限制催化概念，通过统一化学环境和空间架构来突破传统催化剂设计的限制。通过解构限制机制并提出基于瓶颈的部署策略，为材料科学家和化学家提供了一个设计框架，旨在构建能够媲美天然酶卓越效率和选择性的高性能、多尺度催化系统。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[仿生协同限制催化]: 统一化学环境与空间架构以突破传统催化剂设计局限"]},{"i":38989,"as":"纳米限制工程能够同时调节单原子催化剂中的配位数和位点间距，从而改变催化路径，促使反应高选择性地形成高价铁氧（FeIV=O）物种。该技术通过纳米尺度的微环境调控实现了对催化反应选择性的精确导向。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["纳米限制工程[单原子催化剂]: 同时调节配位数和位点间距","[单原子催化剂催化路径]: 重定向至高选择性生成高价铁氧(FeIV=O)物种"]},{"i":38990,"as":"由内部化学振荡器驱动的空心水凝胶胶囊能够在平缓的形状波动和大规模屈曲之间自主切换。这种模式选择由化学和机械时间尺度之间的单一无量纲比率控制。该缩放框架将不同的材料和反应条件整合为一个预测性相图，为主动软材料的自主变形编程确立了设计原则。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[活性软胶囊自主形状选择]: 由化学与机械时间尺度之间的单一无量纲比值控制","[化学机械缩放定律]: 将不同的材料和反应条件统一为预测性相图"]},{"i":38991,"as":"药物释放动力学可通过内部细丝结构进行编程，无需反复改变配方。多材料3D打印将载药、无药和阻挡细丝组织成设计的传输路径。同时，可解释的机器学习和PBPK模型将结构设计与可调释放及疾病相关的暴露控制联系起来，实现了超越材料限制的释放动力学调控。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[药物释放动力学编程途径]: 依赖内部细丝结构而非重复改变配方","[多材料3D打印]: 将载药、无药和屏障细丝组织成设计的传输路径"]},{"i":38992,"as":"被动冷却技术可减少建筑物和公共空间的热量及太阳辐射吸收并散发多余热量，从而降低机械空调带来的环境影响和电网压力。综述讨论了智能太阳辐射控制、通风以及辐射、蒸发和混合散热系统的进展。通风、辐射和蒸发冷却具有低能耗特点，各技术均处于不同的发展和应用阶段。","scd":{"b":4.0,"i":6.0,"r":5.0,"d":5.0,"t":3.0},"kp":["[被动冷却技术核心机制]: 通过智能太阳能控制、通风以及辐射、蒸发和混合散热系统减少热量和太阳增益并散发多余热量"]},{"i":38993,"as":"高角环形暗场高分辨率扫描透射电子显微镜（HAADF-HRSTEM）是一种先进的成像技术。该技术被专门应用于催化剂活性位点的表征与分析，能够帮助研究人员在原子尺度上深入理解催化剂的微观结构和作用机制。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":3.0},"kp":["[高角度环形暗场高分辨率扫描透射电子显微镜(HAADF-HRSTEM)]: 用于理解和表征催化剂活性位点"]},{"i":38994,"as":"研究整合了28名乳腺导管原位癌(DCIS)和浸润性乳腺癌(IBC)患者的单细胞RNA测序、空间转录组学和基因组学数据，揭示了过渡期的空间分子层级。浸润主要由预先存在的DCIS亚克隆扩增驱动，强调转录重编程和肿瘤微环境(TME)重塑而非获得额外驱动因子改变。IBC细胞表现出显著的上皮-间质转化和代谢重编程，并发现了侵袭前沿的动态TME重塑及关键配体-受体相互作用。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["样本量[乳腺癌演进研究]: 28例同步性DCIS和IBC患者","整合技术[空间-分子层级解析]: 单细胞RNA测序、空间转录组学和基因组学","[乳腺导管原位癌向浸润性癌转变机制]: 主要由预先存在的DCIS亚克隆扩增驱动，伴随转录重编程"]},{"i":38995,"as":"半矮化绿色革命品种积累DELLA蛋白，虽提高了抗倒伏性和收获指数，却降低了生物量和单株产量，且高度依赖氮肥。研究显示，结合赤霉素(GA)的GID1蛋白会诱导DELLA蛋白发生多层次构象变化，影响其N端结构。这一结构引导的机制为重新编程DELLA蛋白周转、提高氮肥利用效率(NUE)并实现水稻可持续绿色革命提供了新途径。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[半矮化绿色革命品种特征]: DELLA蛋白积累量升高，在增加抗倒伏性和收获指数的同时牺牲了生物量和谷物产量"]},{"i":38996,"as":"B细胞恶性肿瘤对BTK抑制剂(BTKi)产生耐药性的核心机制是染色质重塑因子BRG1介导的铁死亡抑制。在套细胞淋巴瘤中，异常的BRG1依赖性转录程序通过限制活性氧(ROS)和不稳定铁来保护细胞免受BTKi诱导的铁死亡。BRG1通过诱导MEF2B上调非典型线粒体复合物I亚基NDUFAL2，限制细胞呼吸并预先减少线粒体ROS，从而引发耐药。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["耐药机制[BTK抑制剂耐药]: BRG1介导的铁死亡抑制","[BRG1异常转录保护细胞机制]: 限制活性氧（ROS）和不稳定铁池"]},{"i":38997,"as":"研究提出一种触觉编码的脑机接口(BCI)，通过触觉诱发的P300范式解码运动意图，实现对自然肢体和机器人肢体的同时控制。该接口利用感觉传入途径，在不干扰自然自主运动的情况下可靠解码多重运动指令。在为期多天的实验中，该系统实现了对四个额外自由度运动意图的实时可靠解码。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[触觉编码脑机接口]: 利用触觉诱发的P300范式，在叠加自主运动时仍能可靠解码多余运动意图"]},{"i":38998,"as":"植物生物碱喜树碱是多种抗癌药物半合成的重要前体。在其生物合成中，关键步骤是6/5/6四氢-β-咔啉环系统向6/6/5吡咯并喹啉支架的复杂转变。研究发现，该骨架转换可在黄素单核苷酸等黄素辅因子的催化下，通过光氧化过程高效完成。研究验证了先前假设的大环酮内酰胺中间体的存在，并证明该转化仅需氧气、光照和黄素即可在植物叶片中发生。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[喜树碱骨架重排机制]: 6/5/6四氢-β-咔啉环系统向6/6/5吡咯并喹啉支架转变","[光氧化骨架重组催化剂]: 黄素辅因子"]},{"i":38999,"as":"氢气和氧气直接环氧化烯烃的串联催化效率受限于中间体双氧水(H2O2)在扩散过程中的快速分解。研究通过将疏水性聚合物与双功能Au/TS-1催化剂进行物理混合，构建了疏水传输通道。这种微环境工程加速了H2O2的传质过程，使大部分钛活性位点能够被有效利用，从而突破了该反应长期存在的性能上限。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[H2和O2直接烯烃环氧化限制]: 原位生成的H2O2在扩散过程中快速分解，导致大多数Ti活性位点在动力学上无法接近"]},{"i":39000,"as":"电解质设计通常由体相溶剂化描述符指导，而双电层(EDL)直接控制局部电解质富集和固体电解质界面(SEI)的演化。研究设计了一种不对称室温鏻离子液体PMEP以促进阴离子增强的双电层。分子不对称性降低了PMEP的熔点，并促进了PF6-阴离子参与以Li+为中心的溶剂化结构。分子动力学模拟和密度泛函理论计算证实了其在锂电池中的应用潜力。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[双电层(EDL)调控作用]: 控制局部电解质富集和还原途径，从而指导固体电解质界面(SEI)的成核与演化","[不对称离子液体材料]: 设计不对称室温鏻离子液体以促进阴离子增强的双电层"]},{"i":39001,"as":"本研究通过剪切流和磁场诱导组装技术，设计出分层磁性水凝胶用于细胞排布。通过两种方法（对静止样品施加非稳态磁场、将稳态磁场与剪切流叠加），磁性颗粒在水凝胶基质中发生定向自组装，形成层状结构并随凝胶固化得以保存。这种非单向各向异性赋予了水凝胶刺激响应性和复杂的可编程运动能力。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[水凝胶非单向各向异性构建途径]: 通过施加非稳态磁场或叠加稳态磁场将磁性粒子悬浮液结构化为层状结构"]},{"i":39002,"as":"为可持续生产过氧化氢(H2O2)，研究合成了界面酸位点介导的ZnSe/ZnO异质结电催化剂，用于高选择性的双电子氧还原反应(ORR)。实验和理论结果表明，表面硒化诱发了结构重构，形成了具有内建电场的协同界面。基于此开发的可充电Zn-H2O2电化学电池实现了高效、可持续的双途径H2O2生产。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["电催化剂[可持续双途径H2O2生产]: 界面酸位介导的ZnSe/ZnO异质结","反应机制[氧还原]: 高选择性两电子途径"]},{"i":39003,"as":"挪威斯瓦尔巴群岛已成为北极科学研究的重要前哨基地。然而，日益加剧的地缘政治紧张局势正在使该地区的科学研究工作变得复杂化，给科研人员的探索与合作带来阻碍和挑战。","scd":{"b":2.0,"i":2.0,"r":5.0,"d":2.0,"t":4.0},"kp":[]},{"i":39004,"as":"探讨生物多样性采样领域的竞争现状，呼吁停止过度采样和工具堆砌的军备竞赛，优化生态学研究策略。","scd":{"b":3.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":[]},{"i":39005,"as":"一种内置于计算机存储芯片中的人工神经网络，能够利用物理机制在内存中直接进行计算。该技术实现了对人类大脑皮层的高精度实时重建，展示了存算一体架构在处理复杂神经形态计算任务时的高效性。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":5.0,"t":7.0},"kp":["执行任务[内置在计算机内存芯片中的人工神经网络]: 高精度实时重建人类大脑皮层","计算架构[物理内存计算]: 存算一体"]},{"i":39006,"as":"","scd":null,"kp":[]},{"i":39007,"as":"","scd":null,"kp":[]},{"i":39008,"as":"","scd":null,"kp":[]},{"i":39009,"as":"","scd":null,"kp":[]},{"i":39010,"as":"","scd":null,"kp":[]},{"i":39011,"as":"纤锌矿Al1-xScxN铁电体具有优异的极化和热稳定性，但阳离子取代降低切换能垒和矫顽场的原子级机制尚不明确。研究利用球差校正透射电子显微镜发现，阳离子-阴离子间距沿极化方向存在周期性调制，形成交替的原子偶极层。这种调制源于铝和钪原子在相邻层之间能量有利的化学排序，伴随着层分辨的不对称性，从而降低了材料的切换能垒。","scd":{"b":9.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["物理特性[纤锌矿Al1-xScxN铁电体]: 具有优异的极化和热稳定性","阳离子取代效应[降低反转能垒]: 导致反转能垒降低从而减小矫顽场"]},{"i":39012,"as":"","scd":null,"kp":[]},{"i":39013,"as":"","scd":null,"kp":[]},{"i":39014,"as":"相比于自旋电流，轨道电流具有大几个数量级的效应。在以轨道角动量（OAM）为主的磁体中，氧化钴/铜（CoO/Cu*）结构的轨道霍尔磁阻比氧化钴/铂（CoO/Pt*）结构的自旋霍尔磁阻高出70倍。这源于表面氧化铜的动态OAM与反铁磁绝缘体CoO中的静态OAM之间的相互作用。研究证明，利用以OAM为主的材料可以发挥巨型轨道电流的优势。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":8.0,"t":6.0},"kp":["轨道霍尔磁阻增强[CoO/Cu体系]: 相比自旋磁阻提升70倍"]},{"i":39015,"as":"研究使用量子处理器探究(2+1)D晶格规范理论中的无序定位现象。为降低无序采样成本，量子电路被初始化为覆盖所有无序构型的可调叠加态。在无外在无序度的情况下，系统在1维和2维中均观察到扰动未能扩散的定位现象。然而，熵测量表明，这种叠加制备的态与直接无序采样获得的态存在根本差异。该研究提出了一种降低晶格规范理论采样成本的分析方法。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":7.0,"t":6.0},"kp":["初始化方法[量子处理器格点规范理论]: 形成所有无序构型的可调谐叠加态以降低采样成本","无序定位观察[无序系统(2+1)D晶格规范理论]: 在缺乏无序性的情况下观察到定位现象"]},{"i":39016,"as":"回顾美国科学发展的250年历程，总结科学历史与技术演进。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":2.0,"t":3.0},"kp":[]},{"i":39017,"as":"基于嵌入式神经网络和自适应步长积分的神经动力系统（NDS）在物理建模中表现出色，但存在百毫秒级的延迟。研究利用相变忆阻器的精确电导漂移和多级存内计算能力，开发出延迟低于10毫秒的NDS硬件。团队制造了40纳米制程的NDS芯片用于复杂的表面重建任务。与现有硬件相比，该单次迭代NDS计算延迟仅为2.12毫秒，且满足10的误差容忍度。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["系统延迟[相变忆阻器神经动力学系统硬件]: 小于10毫秒","硬件机制[相变忆阻器]: 利用精确控制的电导漂移和多级存内计算能力"]},{"i":39018,"as":"关注非洲地区的环保议题，探讨终止以“可重复使用”为名进行废物倾倒的政策。","scd":{"b":3.0,"i":4.0,"r":4.0,"d":3.0,"t":4.0},"kp":[]},{"i":39019,"as":"","scd":null,"kp":[]},{"i":39020,"as":"科学相关机构的成熟反映了创新架构的转变，创新体系正从爱迪生时代的发明工厂模式向全新的创新组织架构演进。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":2.0,"t":3.0},"kp":[]},{"i":39021,"as":"某篇已发表学术文章或报告的撤稿声明。","scd":null,"kp":[]},{"i":39022,"as":"美国的研究型大学在美国的历史进程中留下了不可磨灭的印记，对其国家的发展轨迹产生了深远影响。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":2.0,"t":3.0},"kp":[]},{"i":39023,"as":"","scd":null,"kp":[]},{"i":39024,"as":"","scd":null,"kp":[]},{"i":39025,"as":"","scd":null,"kp":[]},{"i":39026,"as":"本文聚焦二战对美国联邦科研经费演变的影响。二战期间，美国制定了许多基础性的创新政策，这些政策不仅满足了当时的战时需求，更对后世产生了深远影响。时至今日，尽管历经岁月变迁，这些在二战时期确立的科研资助机制与创新政策依然以不同形式被保留并延续下来，持续在塑造美国国家科研体系中发挥着关键作用。","scd":{"b":2.0,"i":2.0,"r":3.0,"d":2.0,"t":2.0},"kp":["[基础创新政策]: 源于二战并部分持续至今"]},{"i":39027,"as":"介绍在齐柏林山上部署传感器监测俄罗斯空气质量的技术应用与情报搜集活动。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[先进科学仪器/环境监测]: 在齐柏林山部署传感器以监测空气质量及搜集情报"]},{"i":39028,"as":"美国自建国伊始便高度重视科学，开国元勋们深知新知识和科学知识的重要性。本杰明·富兰克林在铸就新民主国家基础时，充分体现了对自然世界法则和政治哲学理念的广泛好奇心。独立战争前新英格兰已建立起私立大学；而在南方，公立大学则与国家的建立同步形成，托马斯·杰斐逊在卸任后也致力于在夏洛茨维尔创建新机构。","scd":{"b":0.0,"i":1.0,"r":2.0,"d":2.0,"t":2.0},"kp":[]},{"i":39029,"as":"生物钟赋予生物体适应环境日常变化的生理和行为优势。果蝇偏好有规律的生活：持续光照会降解核心生物钟蛋白Timeless，导致生物钟停滞和运动行为无节律。在光照环境中，如果果蝇能在暗区和亮区之间自由移动，它们能够维持或恢复节律行为模式。这种主动行为引发了驱动行为节律的时钟神经元的分子节律。相比无节律的果蝇，恢复节律的果蝇睡眠质量更高。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[核心生物钟蛋白Timeless]: 持续光照会引发其降解并停止生物钟","[昼夜节律干预机制]: 果蝇通过在光照与暗区之间主动移动来重启生物钟"]},{"i":39030,"as":"","scd":null,"kp":[]},{"i":39031,"as":"实验室成功创造出名为“SpudCells”的新型合成细胞。这些合成细胞具备生长和分裂的能力，但在功能和机制上仍存在重大的局限性，需进一步研究突破。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["生命特征[新型合成细胞SpudCells]: 能够生长和分裂但存在重大局限性"]},{"i":39032,"as":"施普林格·自然（Springer Nature）撤下了量子力学先驱马克斯·普朗克（Max Planck）的两篇研究论文。据推测，一个自动化机器人程序（bot）可能是造成此次不当撤稿事件的主要原因。","scd":{"b":3.0,"i":2.0,"r":5.0,"d":3.0,"t":6.0},"kp":["撤稿事件[Max Planck论文]: 可能归因于机器人的干预"]},{"i":39033,"as":"尽管面临延期和人员短缺问题，美国国立卫生研究院（NIH）仍有望全额支出其2026财年预算。然而，预计该机构批准的新科研拨款数量将继续低于历史同期水平。","scd":{"b":2.0,"i":3.0,"r":3.0,"d":4.0,"t":5.0},"kp":["[科研经费拨款预测(2026)]: 尽管存在延误和人员短缺，机构应能全额支出预算，但新资助将可能低于历史水平"]},{"i":39034,"as":"地幔波与构造拉伸作用导致极地山脉隆升，进而使其进入极寒状态并最终冰冻。这一机制解释了古代大陆分裂如何引发地形变化，促使南极地区形成深度的冰冻环境，最终催生了巨大的南极冰盖。","scd":{"b":5.0,"i":1.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[南极冰盖成因机制]: 地幔波与构造拉伸将极地山脉抬升至极寒状态"]},{"i":39035,"as":"霍华德·休斯医学研究所（HHMI）宣布启动一项投资额达10亿美元的宏大神经科学计划，曾经默默无闻的“丹尼氏鱼”（Danionella）将成为该项目的核心研究对象。这种独特的鱼类因身体完全透明而具有极高的科研价值，能够帮助科学家在无创条件下直接观察活体大脑的神经活动。作为新兴的模式生物，丹尼氏鱼将在这项雄心勃勃的倡议中占据核心地位，有望在脑功能探索与神经科学研究领域带来重大突破。","scd":{"b":3.0,"i":4.0,"r":4.0,"d":4.0,"t":6.0},"kp":["[神经科学倡议资助]: 10亿美元","[神经科学核心研究对象]: 透明Danionella鱼(原为冷门物种)"]},{"i":39036,"as":"鲁宾望远镜启动了为期10年的宇宙观测计划。该望远镜配备的巨型相机将对天空进行反复扫描，在探测各种瞬变天文现象的同时，构建包含数十亿个星系的深层宇宙地图。","scd":{"b":8.0,"i":8.0,"r":7.0,"d":6.0,"t":8.0},"kp":["观测周期[Rubin望远镜]: 为期10年的宇宙电影拍摄","功能目标[巨型相机]: 重复扫描天空以发现瞬变现象并构建数十亿星系的深度地图"]},{"i":39037,"as":"","scd":null,"kp":[]},{"i":39038,"as":"","scd":null,"kp":[]},{"i":39039,"as":"探讨非洲人工智能外交的制度化进程，涉及AI技术合作与地缘政治战略。","scd":{"b":2.0,"i":2.0,"r":3.0,"d":3.0,"t":5.0},"kp":[]},{"i":39040,"as":"","scd":null,"kp":[]},{"i":39041,"as":"研究开发了TranscriptFormer，这是一系列基于深度学习的生成式基础模型。这些模型基于跨越15.3亿年进化、涵盖12个物种的1.12亿个细胞数据训练而成。该模型在细胞类型分类和人类细胞疾病状态零样本识别中达到了领先性能。发育轨迹和系统发育关系在模型表征中自然显现，无需对这些注释进行显式训练，为单细胞定量分析提供了强大框架。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":8.0,"t":7.0},"kp":["训练数据规模[TranscriptFormer生成式基础模型]: 高达1.12亿个细胞跨越15亿年进化的12个物种","分类性能[细胞类型]: 即使是进化上分离超过6.85亿年的物种也能实现最先进的分类及零样本疾病预测"]},{"i":39042,"as":"针对跨膜蛋白因强疏水性导致的生产与分析难题，本研究开发了一种基于深度学习的通用设计方法。该技术利用AI设计了全新水溶性双亲蛋白（WRAPs），能紧密包裹膜蛋白的疏水表面，在不使用去垢剂的情况下保留其天然结构与功能特征，并提升其热稳定性与水溶性。研究为多种跨膜蛋白成功设计了WRAPs，并通过冷冻电镜解析了高分辨率结构，证明了该技术在膜蛋白结构测定中的有效性。该成果已应用于生成梅毒疫苗所需的可溶性靶点，为膜蛋白相关药物与疫苗研发提供了创新解决方案。","scd":{"b":9.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["溶解机制[膜蛋白质]: 遗传编码的从头设计水溶性RFdiffused两亲性蛋白质(WRAPs)","保护特性[溶解过程]: 保留原生序列、折叠、活性位点及配体结合特性"]},{"i":39043,"as":"","scd":null,"kp":[]},{"i":39044,"as":"","scd":null,"kp":[]},{"i":39045,"as":"","scd":null,"kp":[]},{"i":39046,"as":"针对柔性水系锌金属电池中复杂的锌枝晶问题，研究开发了基于氧功能化碳纳米管纤维（OCNTF）的纤维状锌电极。通过定制的连续化工艺，制备出米级长度的器件。OCNTF与锌之间的低晶格错配度显著缓解了枝晶形成。致密排列的结构使新型碳纳米管纤维在实现米级制造的同时，解决了圆柱形几何体上锌沉积动力学复杂的问题。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["[无枝晶锌纤维负极]: 连续制造工艺解决了圆柱形几何结构上锌沉积动力学导致的枝晶形成问题"]},{"i":39047,"as":"在JT-60SA托卡马克装置中进行了ITER相关的低感应电场等离子体启动实验。研究发现，欧姆场零位形（FNC）启动受限于高杂质含量，而电子回旋（EC）辅助启动受限于设备模型误差引起的等离子体外移。相比之下，捕获粒子位形（TPC）通过施加有限的垂直磁场，成功克服了这些限制，实现了可靠的等离子体击穿与启动。","scd":{"b":6.0,"i":6.0,"r":4.0,"d":6.0,"t":6.0},"kp":["等离子体启动限制[欧姆场零位构型]: 高杂质含量","等离子体启动限制[EC辅助FNC]: 对装置模型不确定性的敏感性"]},{"i":39048,"as":"研究提出使用非线性谐振器进行双量子点电荷状态的读出。实验与数值计算表明，在非线性区域驱动谐振器，即使不满足传统线性谐振器所必须的阻抗匹配条件，也能实现接近100%的高信噪比电荷读出信号。这种信号增强源于传感器耗散改变了非线性谐振器响应的起始点，从而突破了传统阻抗匹配对读出带宽的上限限制。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":6.0,"t":4.0},"kp":["电荷读出信号[非线性谐振器驱动耗散传感器]: 接近一致"]},{"i":39049,"as":"金属间化合物Ru2Sn3（诺特尼烟囱梯晶体）在8-14K的热容中表现出类似玻色峰的玻璃态异常。第一性原理和分子动力学模拟表明，该现象源于烟囱梯结构中产生的低能光学声子。这些声子与声学声子强烈耦合导致杂化和避免交叉，直接重塑了振动光谱。热电测量证实这些非常规的声子散射机制导致了其固有的低热导率和优异的热电传输性能。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":6.0,"t":4.0},"kp":["热容玻璃状异常温度[Ru2Sn3金属间化合物]: 8-14 K","本征热导率[Nowotny烟囱梯晶体]: 极低"]},{"i":39050,"as":"通过流体诱导排列和致密化方法，利用高速乙醇喷射冲刷并收缩预制的碳纳米管纤维。持续的致密化作用显著提升了碳纳米管的排列度和堆积密度，增大了范德华力。优化后的新型碳纳米管纤维比拉伸强度达到7.5×10^6 N·m·kg⁻1，绝对拉伸强度达到12.5 GPa，接近单根碳纳米管强度的下限，且杨氏模量达370 GPa，电导率为3×10^6 S·m⁻1。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":8.0,"t":5.0},"kp":["拉伸强度[碳纳米管宏观纤维]: 12.5 GPa","致密化与取向工艺[碳纳米管纤维]: 喷射高速乙醇流体诱导排列和致密化"]},{"i":39051,"as":"为解决单波长激光拉曼光谱在气体检测中灵敏度不足的问题，研究开发了不对称光纤谐振腔理论框架及同轴嵌套组件。该不对称结构平衡了激光功率增强和高反射率引起的腔内损耗，使拉曼信号强度相比单根空芯光纤增强了170倍，相比几何谐振腔增强了36倍，实现了对毫升体积内多成分气体或溶解气体的高灵敏动态检测。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":6.0,"t":4.0},"kp":["[气体/溶解气体拉曼检测]: 建立了光纤谐振腔内拉曼信号生成的理论框架及同轴嵌套组件"]},{"i":39052,"as":"通过微波冲击合成技术，成功制备了二维六方YMnO3系统，集成了热稳定性、蓝色可见光伪装和中红外透明度。该材料克服了电子过程与晶格极化耦合导致的红外透明窗口不稳定的长期难题。非易失性相变特性使其在高温环境下仍能有效隐藏目标表面的热辐射边界，满足航空航天领域对可见光与中红外双重隐蔽的严苛要求。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["热稳定性[二维YMnO3材料]: 高温","伪装特性[可见光与中红外兼容]: 蓝色可见伪装和中红外透明度"]},{"i":39053,"as":"在室温下构建了由铁磁性Fe3GaTe2电极和黑磷或紫磷间隔层组成的全范德华自旋阀异质结构。该器件实现了创纪录的103%室温磁阻比，并表现出与磁场角度无关的磁阻和与角度相关的各向异性矫顽力。这种独特的特性源于畴壁运动驱动的磁化反转以及材料强烈的垂直磁各向异性，为高效自旋电子存储器件提供了新方案。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":8.0,"t":4.0},"kp":["室温磁阻[全范德华Fe3GaTe2/磷自旋阀]: 最高达103%"]},{"i":39054,"as":"研究发现基于E(3)等变的机器学习原子间势模型（如Allegro神经网络）在无需直接监督键属性的情况下，能够自发学习局部的化学键信息。通过开发一种边缘能量涌现分解框架，成功从训练好的模型中提取出各键的能量贡献。研究证明随着训练数据和模型容量的增加，这些大规模机器学习模型确实获得了类似于化学键解离能的、可解释的化学直觉与能力。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["[大规模机器学习原子间势]: 无需直接监督键属性即可学习局部化学键解离能直觉信息"]},{"i":39055,"as":"通过高温煅烧策略合成了引入无定形钛物种的铁矿石基催化剂FeTiOx。该催化剂系统表现出对高级醇的固有偏好，通过调节铜物种的分散性，在保持42.5%的二氧化碳转化率下，将高级醇选择性提升至30.2%。原位X射线衍射和红外光谱监测表明，反应过程中催化剂相结构经历了从Fe2O3到Fe3O4再到Fe5C2的动态演化，并成功检测到CO、CHx等关键中间体。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":7.0,"t":5.0},"kp":["高级醇选择性[CO2还原反应Cu改性的FeTiOx催化剂]: 30.2%","催化剂合成策略[高温煅烧引入无定形Ti]: 构建Fe3O4-Fe5C2-Cu催化界面并形成无定形Ti骨架"]},{"i":39056,"as":"利用硫(S)介导的靶向钝化策略设计了具有原子级定制活性位点的Pt-CeO2催化剂，用于逆水煤气变换(RWGS)反应将CO2转化为CO。该策略有效解决了Pt基催化剂在高温下因Pt边缘位点过度吸附CO而导致的CO选择性和耐久性不足的问题，在消除活性、稳定性和选择性权衡方面表现出优越性。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":6.5,"t":6.5},"kp":["CO选择性[高温逆水煤气变换(RWGS)反应硫钝化的Pt簇/CeO2催化剂]: 消除Pt边缘位点对CO的过度吸附，提升高温选择性与耐久性"]},{"i":39057,"as":"报道了一种控制多相烯烃聚合催化剂活性位点核数的液体聚合策略。通过惰性正己烷在催化颗粒上周期性的润湿和干燥，引导双核钛物种的形成。光谱学表明，流体环境促进了双核活性中心的形成，大幅提高了共聚单体的掺入效率，生成了具有更均匀短链支化分布的聚乙烯。","scd":{"b":8.0,"i":3.5,"r":6.0,"d":6.0,"t":6.5},"kp":["活性中心核数控制[多相Ziegler-Natta催化剂聚合过程]: 依托惰性正己烷周期性干湿交替流体环境形成双核钛活性中心"]},{"i":39058,"as":"本研究提出了一种基于光偏振的新型非易失性电光存储器。研究人员研发了由二维二硫化铼（ReS2）与铁电氧化铪锆（HZO）构成的铁电场效应晶体管。该器件利用界面光生载流子的重分布调制铁电畴，从而实现偏振分辨的信息编码。此外，晶格失配产生的界面压应力增强了器件的各向异性。当集成于光子神经网络阵列时，该器件在Transformer模型中实现了超过93%的识别准确率。此项技术为光通信、计算及成像解锁了全新的光子信息通道。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.5,"t":6.5},"kp":["光偏振存储器件[二维电光存储器]: 二维二硫化铼(ReS2)/铪锆氧化物(Hf0.5Zr0.5O2, HZO)铁电场效应晶体管","[光偏振存储机制]: 电场驱动电荷分离实现极化分辨存储及光生载流子再分布"]},{"i":39059,"as":"提出了一种低温、无水的制造策略，用于制造热管理用的镁基微型热电冷却器。通过磁控溅射冷键合方法，制造出基于n型Mg3(Bi,Sb)2和p型MgAgSb的紧凑型12对微型器件，尺寸为2.95×4.35×1.4立方毫米，热电臂长约3微米，克服了传统Bi2Te3基材料的毒性及机械强度不足问题。","scd":{"b":7.0,"i":3.5,"r":6.0,"d":6.0,"t":6.5},"kp":["微型热电冷却器材料[热管理替代方案]: 镁基热电材料替代传统碲化铋(Bi2Te3)基材料","微型热电冷却器制造路线[镁基器件]: 低温、无水制造工艺"]},{"i":39060,"as":"介绍了穿有特殊印花套装的“机器人”蟑螂，使其能够潜入水下探索长达三个小时。此外，简报还提到虚假的癌症研究获得了大量引用，以及科学家如何通过认识到自身的偏见来建立公众信任。","scd":{"b":6.5,"i":3.0,"r":4.0,"d":3.0,"t":6.5},"kp":["[机器人蟑螂水下探索]: 可持续长达3小时"]},{"i":39061,"as":"","scd":null,"kp":[]},{"i":39062,"as":"开发了一种超导序层析成像技术，利用扫描隧道显微镜(STM)探测由成对原子杂质作为分束器产生的杨氏准粒子干涉图案。该技术克服了传统STM无法获取超导间隙节点序参数相位缠绕的限制，成功揭示了具有不同于底层晶格对称性的奇异超导相的相位信息。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":6.5},"kp":["探测手段[超导序参量对称性与拓扑检测]: 扫描隧道显微镜(STM)近原子杂质实空间成像"]},{"i":39063,"as":"提出了一种系统发育地理学模型，利用传染病爆发期间的访客动态来推断流行病学参数。该模型通过宿主短暂访问其他人群后返回的移动模式，结合流行病学 compartments 模型的平稳特性，精确区分并量化了患病旅行者感染健康居民与患病居民感染健康旅行者带来的病原体传播比例。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.5},"kp":["系统发育地理学模型[传染病传播路径推断]: 结合访客动态与流行病学动力学建模"]},{"i":39064,"as":"通过纵向功能性磁共振成像研究了从学龄前到小学二年级儿童大脑对数学陈述的神经反应。结果显示，学龄前儿童已具备类似成人的皮质网络，并在几何方面具有部分特异性。在入学的前两年，数学相关的激活总体增加，招募了额外的神经区域，且对掌握程度更深的事实激活减弱。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":7.0,"t":5.5},"kp":["大脑发育追踪[学龄前至小学低年级儿童数学认知响应]: 采用大规模纵向功能磁共振成像(fMRI)评估数学神经网络构建及发育规律"]},{"i":39065,"as":"","scd":null,"kp":[]},{"i":39066,"as":"开发了一种人工呼吸链，将其直接整合到无细胞代谢系统中以改善代谢。该人工呼吸链为含有16种酶的CO2固定催化循环提供快速电子传递，并利用伴随的电子流进行ATP再生。成功将中心氧化反应与能量保存相耦合，克服了合成生物学中无细胞网络的动力学和热力学限制。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["能量守恒机制[无细胞代谢网络重构]: 通过自下而上直接整合人工呼吸链，实现中心氧化反应与能量保存的耦合"]},{"i":39067,"as":"","scd":null,"kp":[]},{"i":39068,"as":"为解决皮肤界面可穿戴设备稳固贴合与温和摘除的矛盾，建立了吸盘设计在完全显式形式下的变形和受力分析模型。该模型覆盖了吸盘机制，为提供强力、可逆且无粘合剂的物理附着提供了理论指导，深入解析了其在出汗和潮湿环境下的底层力学表现。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":5.0,"t":4.0},"kp":["皮肤界面可穿戴设备[稳定贴附与温和移除]: 基于吸盘的安装设计"]},{"i":39069,"as":"揭示了膜蛋白通过弱非共价相互作用自发组装成高阶瞬态结构(HOTS)的机制。HOTS作为10至100纳米尺寸的瞬态信号枢纽，其组装条件及与生物分子凝聚相形成的 thermodynamic 关系被详细阐明。HOTS独特的物理特性使其在膜信号传导中发挥重要作用，并可能广泛存在于三维细胞区室中。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["空间尺寸[高阶瞬态结构(HOTS)]: 10至100纳米","组装驱动力[膜蛋白高阶瞬态结构(HOTS)]: 蛋白类型特异性的弱非共价相互作用"]},{"i":39070,"as":"","scd":null,"kp":[]},{"i":39071,"as":"探讨人工智能的进化能力，分析为何当前的驯化AI不构成达尔文式的生存威胁。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["可进化人工智能[达尔文式生存威胁评估]: 受驯化机制限制暂不构成威胁"]},{"i":39072,"as":"探讨可进化人工智能的潜在威胁，分析为何不能仅凭直觉应对相关技术风险。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["可进化人工智能[技术风险应对]: 威胁严重不可仅凭直觉"]},{"i":39073,"as":"脂质代谢途径介导了戊型肝炎病毒(HEV)的复制。在HEV感染的细胞和孕兔模型中，油酸显著上调。油酸通过与HEV ORF1多聚蛋白中的预测脂肪酸结合域(FABD)相互作用，大幅增强病毒复制。研究揭示了脂肪酸调节和磷脂酰乙醇胺生物合成在病毒复制中的关键作用。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["脂质代谢途径[戊型肝炎病毒(HEV)感染复制]: 油酸上调与磷脂酰乙醇胺生物合成"]},{"i":39074,"as":"提出哺乳动物毛囊的空间图案动态主要由趋化自组织机制驱动。与传统简单的膨胀诱导过程不同，基于表皮和真皮信号的反应-扩散-趋化细胞相互作用解释了毛囊前体的形成。趋化自组织框架足以描述具有截然不同毛囊分布的胎盘插入动态。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["空间图案化机制[哺乳动物毛囊前体发育]: 趋化自组织捕捉动态"]},{"i":39075,"as":"结合理论与实验证明，裂殖酵母中功能上等同的配子在合子发育中表现出不对称投入。尽管形态相同，P型和M型配体贡献了不同数量的减数分裂粘连蛋白Rec8。这种 Rec8 对配子施加适应性成本，推动了亲本偏向的基因表达进化，进而促进了配体差异和性别的进化。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":[]},{"i":39076,"as":"使用超高分辨率fMRI(7T，0.6毫米分辨率)研究了人类初级视觉皮层(V1)中方向调整的环绕抑制。通过分析跨皮质深度的BOLD信号，揭示了不同层流(前馈、反馈和侧向)神经通路在空间上下文调节中的特定贡献。结果表明，环绕抑制在V1皮层中表现出独特的层流特征。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":[]},{"i":39077,"as":"为支持球形托卡马克(ST)中非感应电流提升场景的开发，使用自由边界TRANSP模拟开展了NSTX-U当前提升研究。由于紧凑型ST反应堆无法配备全尺寸螺线管，必须通过中性束和自举电流组合非感应地驱动大部分电流，以维持持续运行，满足了 MA 级别 100% 非感应电流驱动的挑战。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["运行特征[球马克(ST)紧凑型反应堆]: 高归一化环向比压与高自举电流分数，且需实现MA级别100%无感电流驱动及非感应电流爬升"]},{"i":39078,"as":"首次基于漂移约化Braginskii方程，使用GBS代码对优化的HSX仿星器中的等离子体湍流进行了全三维双流体模拟。模拟结果与实验测量数据吻合良好，在时间平均密度、电子温度和静电势分布，以及湍流波动频率谱和空间相关性测量方面均表现出一致性。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["湍流模拟维度[HSX仿星器等离子体边界(GBS代码)]: 首次实现三维、双流体(基于漂移约化Braginskii方程)模拟"]},{"i":39079,"as":"研究了动力学和全局效应对传统及低纵横比托卡马克理想气球第二稳定基座的影响。EPED模型结合动力学气球模式(KBM)和剥离-气球(PB)约束来描述基座结构。工作指出，在低纵横比下，局部理想MHD与回转动能(GK)气球稳定性之间的定量差异更大，并应用简化模型计算了KBM的稳定性。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["理论评估[托卡马克台基结构(EPED模型)]: 探究动力学与非局部效应(使用理想气球模阈值)对传统及低纵横比托卡马克第二稳定基座的定量影响"]},{"i":39080,"as":"为解决工业NOx排放控制中催化剂的效率和稳定性挑战，研究提出一种氧化物-沸石（OXZEO）混合设计策略。该策略通过孤立的沸石B酸位点，在空间上分离NH3的存储与氧化还原功能。机制研究表明，沸石B酸位点作为高度调控的NH3存储库，吸附的NH3以分子和NH4+形式解吸并迁移至氧化物活性位点，从而实现独特的脱硝机制。","scd":{"b":8.0,"i":5.0,"r":7.0,"d":7.0,"t":6.0},"kp":["NH3-SCR催化剂[核心功能要求]: 高效、稳定且宽温","催化设计策略[氧化物-沸石(OXZEO)双功能]: 空间分离NH3存储和氧化还原功能","NH3存储位点[分离机制]: 孤立的沸石Brønsted(B)酸位点"]},{"i":39081,"as":"地球内辐射带的高能电子对航天器构成严重威胁，其中低地球轨道的最强辐射通常局限于南大西洋异常区。基于澳门科学卫星一号的观测数据，研究发现了SAA辐射环境的瞬态扭曲现象，其特征是在传统SAA辐射区域外出现高能电子通量增强。这种扭曲现象由大尺度电场扰动引起，电场扰动会绝热改变电子的镜像高度。","scd":{"b":7.0,"i":4.0,"r":8.0,"d":8.0,"t":8.0},"kp":["辐射环境[南大西洋异常区(低轨最强辐射)]: 呈现显著瞬态扭曲与高能电子通量增强"]},{"i":39082,"as":"针对高质量二维纳米片量产面临的收率与质量权衡难题，研究提出基于多环芳烃自由基阴离子介导的有机碱插层策略，实现秒级高效剥离。该方法具有可调还原电位和电子转移能力，可超快实现层状材料的碱金属离子插层。在处理石墨时，仅需约1秒即可形成一阶插层化合物，随后经11秒水解剥离得到石墨烯。该方法石墨烯产率超88%，单层比例超50%，且缺陷密度无明显增加。","scd":{"b":9.0,"i":6.0,"r":8.0,"d":9.0,"t":7.0},"kp":["二维晶体剥离[多环芳烃自由基阴离子(PAH•-)介导插层]: 高质量、秒级(~12 s)生产","插层驱动力[PAH•-特性]: 可调的还原电位和电子转移能力"]},{"i":39083,"as":"关于一种具有钉扎和宽横向复合特性的超低压电化学有机发光晶体管的文章出版商更正。","scd":{"b":3.0,"i":3.0,"r":2.0,"d":3.0,"t":4.0},"kp":[]},{"i":39084,"as":"二维磁性半导体为研究长程磁序与强束缚激子的共存提供了平台。激子态和磁矩源于相同电子轨道并通过内禀交换相互作用耦合，使得系统中的光学激发对磁序表现出高度敏感性。近期实验发现该系统具有异常强的磁光响应和直接的激子-自旋耦合，确立了利用自旋自由度控制光物质相互作用的新途径。本文综述了代表性材料体系、实验特征及理论框架。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":4.0},"kp":["光学激发态[二维磁性半导体]: 对磁序表现出显著的敏感性","磁光耦合机制[同源电子轨道]: 激子态与磁矩通过内在交换相互作用耦合，表现出直接激子-磁子耦合"]},{"i":39085,"as":"为在稳定的晶体框架中精确控制局部化学环境，研究利用网状化学策略对三唑酸金属有机框架进行局部限制编程。该框架由Kuratowski型Zn5Cl4节点构建，连接体几何结构引导形成ith-d拓扑，末端锌结合基团指向内部，生成具有化学可寻址性的受限孔隙。通过合成NU-6000和NU-6001两种孔笼尺寸不同但拓扑相同的框架，并进行合成后氯到羟基的离子交换，在晶体无损失的情况下向内部引入密集排列的Zn-OH基团。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["多孔晶体框架[Kuratowski型Zn5Cl4节点的三唑唑金属有机框架]: ith-d拓扑结构","局部限制环境[网状化学编程]: 终端Zn结合基团向内指向以生成受限和可调的化学微环境"]},{"i":39086,"as":"分数量子陈绝缘体（FCI）将朗道能级的分数量子霍尔效应推广到无外加磁场的晶格系统中，其形成源于电子间强相互作用与非平凡拓扑的相互作用。由于对能带平整度、拓扑和量子几何要求严苛，在现实材料中实现本征FCI长期面临巨大挑战。二维莫尔超晶格的进展克服了这些障碍，成功在莫尔材料中实现了分数陈绝缘体状态并观测到分数量子反常霍尔效应。","scd":{"b":9.5,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["内在实现条件[分数量子反常霍尔效应(无外加磁场)]: 对能带平坦度、拓扑和量子几何有严苛要求"]},{"i":39087,"as":"针对高性能聚合物半导体多尺度结构排序难以控制从而限制载流子迁移率的问题，研究提出一种自模板梯度组装策略。该策略基于溶解度参数与蒸汽压的耦合框架选择溶剂体系，触发超分子有序组装。利用新设计的聚合物，优化了溶液态聚集体并实现了多尺度结构排序。该方法大幅提升了聚合物半导体的电荷迁移率，实现了类似单晶的高迁移率特性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["聚合物半导体[自模板梯度组装策略]: 可控调制多尺度排序与排列，实现超高载流子迁移率"]},{"i":39088,"as":"研究在扭曲单层-多层菱面体石墨烯中发现了高陈数轨道磁性。磁输运测量表明，当系统极化偏离莫尔界面时，在每莫尔单元胞1个和3个电子的情况下表现出明显的反常霍尔效应。通过Středa轨迹和量化霍尔电阻揭示出明确为C=n（n为层数）的拓扑等级，这一实验结果得到了自洽平均场计算的支持。此外，该体系能够实现电学和磁学开关切换。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["陈绝缘体[扭曲单层-多层菱面体石墨烯]: 具有高陈数(C>1)的轨道磁性","反常霍尔效应[每个莫尔单胞中填充三个电子]: 显著"]},{"i":39089,"as":"","scd":null,"kp":[]},{"i":39090,"as":"针对无机固态电解质严重依赖高浓度锂导致电化学稳定性受限的问题，研究提出一种界面渗透策略。通过将Ta2O5纳米晶嵌入非晶基质中构建典型渗透型固态电解质，证明了绝缘分散体能降低锂浓度同时提高离子电导率。该策略打破了离子电导率对高含锂量的传统依赖，在实现低锂含量下高离子电导率的同时，允许对电解质的高压稳定性等性能进行调控。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["固态电解质[界面渗透策略]: 低锂含量下实现高离子导率，打破传统对高锂含量的依赖"]},{"i":39091,"as":"为解决非水系镁氧电池由于缺乏合适电解质和阴极反应不可逆导致的充电性能差问题，研究开发出一种可充电非水系镁氧电池。该电池采用定制电解质，通过改变醚溶剂链长并结合三齿螯合剂，协同形成动态溶剂化微反应器。这种独特的笼状Mg2+溶剂化环境与阴极可逆生成纳米晶过氧化镁的反应过程相兼容，同时保持了与镁负极可逆沉积溶解的兼容性。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["非水系Mg-O2电池[定制电解液]: 具有笼状Mg2+溶剂化环境，实现可充性","电池体系[性能定位]: 高比能、低成本且本征安全"]},{"i":39092,"as":"针对纳米尺度下向光子结构电注入载流子会破坏光学环境的难题，研究开发出一种单片制造的电可寻址准悬浮纳米光子孔径架构。该架构利用由连续域束缚态（BIC）电磁场节点位置的亚波长纳米柱阵列支撑的光子晶体孔径，在保持半导体与空气全折射率对比度及光学腔对称性的前提下，实现了单元胞级别的电注入。该设计能够在数百个单元胞中实现均匀的载流子注入。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[电注入光子结构]: 采用准悬浮纳米光子孔径单片架构实现晶胞级电注入并保持半导体-空气折射率对比度与对称性"]},{"i":39093,"as":"研究利用玻色-爱因斯坦凝聚体中的量子物质波，实验验证了非绝热非阿贝尔编织操作。在此框架下，有效编织链由动量态编码，而模拟的编织变换源于非绝热非阿贝尔和积。实验通过证明将不同顺序的和积操作应用于物质波会产生不同的最终态，成功验证了非阿贝尔代数。该机制避免了传统绝热过程本质上速度慢的限制，为实现拓扑量子门操作提供了新途径。","scd":{"b":8.5,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[拓扑量子门操作]: 利用量子物质波（玻色-爱因斯坦凝聚）实现非绝热非阿贝尔编织，克服了绝热过程本征速度慢的限制"]},{"i":39094,"as":"针对选择氧化驱动的污染物聚合过程中催化剂存在的竞争吸附导致自抑制问题，研究提出微环境解耦策略，将单原子Sn锚定在氨基功能化碳纳米管上。氨基将Sn稳定为Sn(II)-N4结构，通过形成双齿Sn-PDS复合物选择性活化过硫酸盐（PDS）并维持电子转移主导路径。同时，碳纳米管表面富集酚类底物并促进其聚合转移，避免了氧化还原平衡破坏，实现了污染物去除与碳回收的同步高效进行。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[催化剂结构]: 氨基功能化碳纳米管锚定单原子Sn(II)-N4","[微环境解耦策略]: 氨基优先稳定Sn(II)并选择性活化过硫酸盐，避免污染物与氧化剂的竞争吸附"]},{"i":39095,"as":"研究合成了一种由柔性四面体与刚性四面体构建模块组成的柔性三维共价有机框架。该框架具有热响应性的单键，能实现随温度变化的构象切换，表现出对氙气的温度依赖性选择吸附。其自适应孔隙结构能够产生氙触发的开门效应，使氙气吸附量增加4倍。在298K和1bar条件下，其表现出高达36.9的Xe/Kr选择性，超越了大多数金属有机框架材料，突破了实验验证。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[选择性吸附]: 柔性三维共价有机框架（FCOF-XJ）展现温度依赖的氙气吸附选择性","[柔性结构特点]: 具有热响应的-O-C-C-C-O-单键，可发生温度依赖的构象转变"]},{"i":39096,"as":"研究实现了基于全溶液加工的全介质有机微腔的极化子激光器。有机半导体具有激子结合能大、非线性强等特点，适用于极化激元学。传统有机极化激元激光器的光学腔通常依赖真空沉积，限制了低成本和规模化制造。该全溶液加工工艺打破了这一限制，在强光-物质耦合状态下，实现了室温下的低阈值激光和强光学非线性。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[半导体激光器]: 完全溶液加工的有机微腔激光器可实现室温下的低阈值激射和强光学非线性"]},{"i":39097,"as":"为研究离子插入和电压控制下材料中间态的性质，研究利用固态电化学泵对钛酸锶（SrFeO3-δ）薄膜中的氧非化学计量进行精细调控。该调控方法揭示了完全氧化态和完全还原态之间多种稳定中间相的共存。这种对氧化学计量比的精确控制克服了拓扑相变中间氧化态的探索限制，为神经形态晶体管和智能显示器等自适应器件的模拟调谐提供了强大策略。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[拓扑相变材料]: 电压控制氧离子嵌入可解锁SrFeO3-δ中稳定的中间氧化态"]},{"i":39098,"as":"研究在硅光子晶体平台中，利用热光非线性与非厄米简并性之间的相互作用，成功实现了三态光学存储器。该发现证实了近异常点简并性在多级光学数据存储领域的应用潜力。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":4.0,"t":5.0},"kp":["[光学存储器]: 利用热光非线性与非厄米简并性的相互作用，在硅光子晶体平台中实现三态光存储"]},{"i":39099,"as":"为探究活性位点结构对水解离路径的影响，研究使用氧化锡量子线作为模型催化剂，发现表面羟基结构决定了双极性膜的水解离活性。与桥接氧空位相关的羟基基团能促进质子转移，加速膜界面的碱性水解离路径。通过受控合成增加此类羟基结构的丰度，双极性膜实现了优异的质子传输性能，克服了驱动快速水解离的高能垒，提升了电解和燃料电池技术的可持续性。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[水解离机制]: 表面羟基结构主导双极性膜的水解离活性","[催化剂模型]: 氧化锡量子线"]},{"i":39100,"as":"针对硬碳负极在钠离子电池中由于去溶剂化动力学迟缓和界面不稳定导致的应用受限问题，研究提出熔融涂层策略，利用金属有机框架玻璃包覆硬碳颗粒。该玻璃涂层含有亚纳米通道，有效降低了去溶剂化活化能并加速钠离子传输。在循环过程中，该涂层诱导形成富含NaF的薄层固体电解质界面，促进硬碳闭孔内准金属钠团簇的形成，激活高容量钠存储机制，提供持久的钠离子存储。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[钠离子电池负极]: 熔融涂层策略在硬碳颗粒表面包覆金属有机框架玻璃","[界面修饰]: 玻璃涂层含亚纳米通道，可降低脱溶剂化活化能并加速钠离子传输"]},{"i":39101,"as":"海水中含有全球约99%的溴储量，但浓度极低（约60 ppm）。传统电化学提取法无法直接提取。研究开发了一种电解驱动的苯乙烯富集工艺，通过筛选以碳纳米管为载体的金属酞菁催化剂加速溴析出反应并抑制副反应，其中镍酞菁/碳纳米管催化剂表现出最高活性，实现了从海水中高效回收溴。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[溴化物浓度]: ~60 ppm（海水）","[海水提溴]: 电解驱动的苯乙烯富集工艺实现低浓度溴离子的有效回收"]},{"i":39102,"as":"细胞单层在集体运动中会自发形成持久空穴。研究开发了包含内部耗散和驱动细胞形状各向异性的主动偶极力的连续多相场模型。模拟表明，在低基底摩擦区域，减少摩擦可增强细胞间的速度相关性。此外，拓扑缺陷会生成螺旋流模式，导致局部应力集中，从而触发细胞单层自发空穴的形成。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":[]},{"i":39103,"as":"研究开发了一种集成多种加密算法的DNA多层加密设备，用于安全通信。该系统利用矩形DNA纳米结构在空间上的可寻址性创建纳米摩斯密码模式。在基于密码本的对称加密框架内，通过共享密钥传输加密信息，结合矩形与管状DNA纳米结构之间的转换机制，在单一的DNA折纸通信工作流程中实现了多重加密协议。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[多重加密DNA设备]: 集成多种密码算法的单器件","加密系统[DNA折纸通信]: 利用纳米结构可寻址性进行编码"]},{"i":39104,"as":"无阳极钠电池具有高能量密度和低成本优势，但存在库仑效率低和容量衰减快的问题。研究确认集流体表面的d带中心是控制钠成核行为的统一电子结构描述符。测试和计算表明，d带中心与钠成核过电位之间呈火山型关系。处于中等d带中心的表面能够有效优化钠的初始沉积，提升电池性能与安全性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["电池架构[钠金属电池]: 无阳极构型","调控机制[钠沉积与成核]: d带中心电子结构驱动亲水性"]},{"i":39105,"as":"","scd":null,"kp":[]},{"i":39106,"as":"","scd":null,"kp":[]},{"i":39107,"as":"热电材料β-Zn4Sb3在外部电场下存在严重的锌离子迁移问题。研究利用粉末原子层沉积技术构建了原子级氧化锌界面，以抑制锌离子迁移并增强声子散射。通过精确控制50到200周期的ZnO涂层形成连续阻挡层，固定了间隙锌离子并抑制了相分解。经过优化的100周期涂层通过强烈的边界声子散射使晶格热导率降低了20%以上。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["界面工程[β-Zn4Sb3热电材料]: 粉末原子层沉积制备原子级ZnO界面","关键效应[原子级界面]: 同时抑制Zn离子迁移并增强声子散射"]},{"i":39108,"as":"为克服传统无电力辐射冷却技术在夏季冷却功率受限且在冬季抵消节能效果的缺陷，研究开发了动态蒸发和辐射冷却（DERC）设备。该设备能够根据环境温度变化自适应地调节水蒸发速率，并显著调节太阳能和热辐射（ΔA_sol），最大化炎热夏季的冷却功率，实现全年动态热管理，提升整体能效。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["工作机制[动态蒸发与辐射冷却装置]: 最大化夏季冷却功率并消除冬季负面影响以实现全年节能"]},{"i":39109,"as":"","scd":null,"kp":[]},{"i":39110,"as":"","scd":null,"kp":[]},{"i":39111,"as":"","scd":null,"kp":[]},{"i":39112,"as":"","scd":null,"kp":[]},{"i":39113,"as":"","scd":null,"kp":[]},{"i":39114,"as":"研究综合评估了146项关于热带潮湿森林扰动后地上碳（AGC）变化的研究。部分人为干扰造成的即时AGC损失排序为：森林火灾（49%）、择伐（34%）和边缘效应（31%）。干扰频率和强度增加会显著增加碳损失。经过20年再生，退化森林的AGC恢复率达41%至117%，显著高于完全砍伐后次生林的1%至74%。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":8.0,"t":4.0},"kp":["地上碳损失[部分人为干扰-森林火灾]: 49±26%","地上碳损失[部分人为干扰-选择性采伐]: 存在显著碳流失"]},{"i":39115,"as":"小麦淀粉颗粒大小受空间和底物限制的影响。为增加A型淀粉颗粒的大小，研究突变了质体分裂组分PARC6以增加淀粉体尺寸和颗粒生长空间，同时突变了BGC1以减少颗粒起始并降低底物竞争。这种靶向颗粒起始和淀粉体结构的双重突变策略打破了原有的限制，成功在小麦中实现了淀粉颗粒尺寸的大幅增加。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["靶向调控[A型淀粉颗粒尺寸]: 突变质体分裂组件ARC6旁系同源物解除空间与底物限制"]},{"i":39116,"as":"研究开发了一种在深共晶溶剂电解质中协同集成气相（Cl2 ↔ Cl−）、液相（Cu2+ ↔ Cu+）和固相（S ↔ CuS ↔ Cu2S）氧化还原反应的级联电池。这种气-液-固三相耦合策略解锁了七电子转移过程。富氯电解质从根本上改变了铜的氧化还原热力学，实现了可逆的液相转化，突破了传统双电子反应的限制，大幅提升了电池能量密度。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[多电子级联电池]: 协同整合气液固三相氧化还原反应（Cl2↔Cl-, Cu2+↔Cu+, S↔CuS↔Cu2S）"]},{"i":39117,"as":"活跃星系核（AGN）反馈是解决星系团冷却流问题的方案。研究使用MACER框架进行了流体动力学模拟，结合了受广义相对论磁流体动力学模拟和观测约束的射流与风。结果显示，射流和风的组合反馈成功重现了冷气体质量、恒星形成率、热力学径向分布和黑洞增长等关键观测数据，而仅靠单一射流或风模型则无法实现，有效解决了冷却流问题。","scd":{"b":7.0,"i":1.0,"r":7.0,"d":6.0,"t":5.0},"kp":[]},{"i":39118,"as":"在DNA复制应激期间，类GSK3激酶BIN2通过一种独立于ATR的未知机制被激活。激活的BIN2在T244和T249位点磷酸化SOG1蛋白，从而增强SOG1的稳定性和转录活性，进而激活DNA损伤反应（DDR）。这一发现揭示了植物中不依赖于ATR、由BIN2-SOG1分子模块介导的复制应激响应新通路。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":7.0,"t":5.0},"kp":["BIN2[作用靶点]: SOG1","BIN2[磷酸化位点]: T244, T249","SOG1[翻译后修饰]: 提高稳定性和转录活性","BIN2[激活机制]: 独立于ATR的未知机制","BIN2-SOG1[调控通路]: 激活DNA损伤反应(DDR)动态调节复制应激反应"]},{"i":39119,"as":"研究开发了一种依赖流速的毛细管棘轮机制。在高流速条件下，界面流和毛细管力的相互作用使漂浮物体产生稳健的单向旋转。模拟显示界面流取决于驱动方向，导致了迟滞现象。利用该原理，研究通过控制界面流和毛细管力，成功实现了手性微结构的可控单向旋转，并完成了微尺度导线的编织与微装配。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[毛细管棘轮机制]: 依赖于流速并在高流速状态下启动"]},{"i":39120,"as":"研究发现小鼠在觅食和进食时，能以毫秒级的时间精度和钟表般的灵巧性，将单次吸气与快速的头部和手部动作同步，实现非节律性的单次嗅觉。这种孤立的嗅探行为伴随呼吸节律的突然重置，与典型的节律性嗅探不同，且会根据食物特性进行行为调节。对嗅觉和运动回路的操作表明，这种单嗅依赖于运动皮层，而非反射性神经控制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[单次嗅觉动作]: 毫秒级时间同步单次吸气与快速头部及手部运动"]},{"i":39121,"as":"底丘脑（STN）是深部脑刺激治疗帕金森病左旋多巴诱导运动障碍（LID）的重要靶点。研究揭示了STN中两个不同神经元亚群在调节LID中的功能差异：投射至脚内核（EP）的STN神经元呈现U型激活模式，激活该亚群可缓解运动障碍，但会恶化帕金森状态下的运动机能减退；而投射至被盖网状核的STN神经元主要表现为抑制性反应，单独激活不会诱发运动过度。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":39122,"as":"在果蝇的恶病质和非恶病质肿瘤模型中，脂肪体来源的储存蛋白（Hexamerins）通过选择性摄取过程在肿瘤中积累，作为营养源支持肿瘤进展。阻断该蛋白摄取会显著减少肿瘤生长。此外，该摄取过程支持肿瘤表达果蝇胰岛素样蛋白8（Dilp8），进而抑制蜕皮激素产生并延长肿瘤生长期，确立了营养摄取与肿瘤生长周期之间的耦合机制。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":39123,"as":"胰腺α细胞仅在代谢应激下对葡萄糖耐量起关键作用。在小鼠α细胞清除模型（GluDTR）中，添加模拟膳食的氨基酸会显著降低葡萄糖耐量。使用微电极阵列分析发现，α细胞的清除在仅存在葡萄糖时对β细胞分泌和电活动影响甚微，但在加入氨基酸后导致其大幅减少。α细胞通过维持不同位置引导区域的功能性β细胞网络特性来调节营养稳态。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":[]},{"i":39124,"as":"无义介导的mRNA降解（NMD）是由提前终止密码子（PTC）触发的翻译偶联降解途径。通过实时成像技术同时检测表达野生型或NMD靶标的β-球蛋白报告基因转录位点，发现含有PTC的β-球蛋白mRNA的转录发生动态变化。这种变化依赖于翻译、NMD过程以及细胞核蛋白输入，证实了在转录位点存在基于转录反馈的PTC检测机制。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[PTC检测]: 使用高时空分辨率的实时成像方法研究转录位点的检测机制"]},{"i":39125,"as":"研究通过单细胞RNA测序和多重免疫组化，分析了甲状腺癌原发灶与匹配的转移淋巴结微环境。结果显示，在淋巴结定植后，甲状腺细胞和肿瘤相关巨噬细胞会下调多种炎性细胞因子受体（如TNFRSF12A和CX3CR1）的表达。同时，淋巴结微环境中诱导了调节性T细胞的产生，揭示了影响甲状腺癌淋巴结扩散与定植的免疫决定因素。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[肿瘤微环境分析]: 使用单细胞RNA测序结合多重免疫组织化学验证方法鉴定原发甲状腺肿瘤和匹配的转移性淋巴结中的肿瘤浸润白细胞"]},{"i":39126,"as":"在小鼠幼崽的活体成像中发现，即使在耳孔打开前，自发声也能引发听觉皮层（ACtx）活动，且该活动强于纯音诱发的活动，这种自发声关联活动在失聪小鼠中同样存在。这表明活动源于自上而下的皮质内通路，即来自前扣带皮质（ACC）和次级运动皮质（M2）的投射驱动。失活ACC/M2会减少自发声及相关的ACtx活动。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":6.0},"kp":["皮质活动[听觉皮层发育]: 自发声通过皮质内自上而下通路激活"]},{"i":39127,"as":"","scd":null,"kp":[]},{"i":39128,"as":"表达P物质受体和神经元一氧化氮合酶的生长抑素Tac1受体阳性神经元（Tacr1神经元）对脑血流（CBF）具有巨大的调节作用。双光子成像表明，Tacr1神经元通过释放一氧化氮（NO）和SP受体信号传导调节CBF，星形胶质细胞的钙离子瞬变是对血管扩张的次级反应。病毒映射显示，体感皮层中的P物质由局部的Tac1阳性神经元等提供，以此介导神经血管耦合。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["神经血管耦合调控[体感皮层Tacr1神经元]: 通过释放一氧化氮和P物质受体信号大幅调节脑血流"]},{"i":39129,"as":"在高熵合金设计中，降低热导率往往会降低载流子迁移率，从而限制热电性能。研究表明，在半Heusler合金中，系统且大幅增加构型熵会导致晶格热导率的渐近降低。由原子级化学无序引起的声子群速度降低和声子散射增强，使得室温下晶格热导率低至2 W/(m·K)，特定条件下最低可达约1.48 W/(m·K)，有效提升了热电器件性能。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[高熵半赫斯勒合金]: 构型熵大幅增加导致晶格热导率渐近降低","挑战[高熵合金设计]: 降低热导率的同时常削弱载流子迁移率"]},{"i":39130,"as":"创伤性脑损伤（TBI）后患者及小鼠模型中的星形胶质细胞抗肌萎缩蛋白71（Dp71）表达降低。在小鼠中，实验性下调星形胶质细胞Dp71可减轻继发性血脑屏障（BBB）破坏，并减少星形胶质细胞激活、炎症细胞浸润和基质金属蛋白酶-2（MMP2）释放。机制上，细胞核内的Dp71与Wilms肿瘤1相关蛋白（WTAP）相互作用并影响其泛素化，进而通过WTAP相关的m6A修饰调节MMP2表达。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["靶向治疗[创伤性脑损伤后血脑屏障破坏]: 敲低星形胶质细胞Dp71并依赖WTAP相关的m6A修饰调节MMP2"]},{"i":39131,"as":"与大多数通过快速重复嗅闻采集气味的哺乳动物不同，人类通常采取单次长嗅。高精度神经记录显示，在缺乏快速嗅闻的情况下，人类嗅球利用theta范围的神经振荡来设定气味编码的节奏。气味的吸入会引发并暂时对齐嗅球内的theta振荡。这一发现表明theta振荡是嗅球中组织气味处理的基本单位，不依赖于快速的嗅探节律。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[气味采样行为]: 人类通常采取单次长嗅闻，而多数其他哺乳动物通过快速重复嗅闻进行采样","[气味编码]: 快速嗅闻节律构成了气味编码的组织原则"]},{"i":39132,"as":"","scd":null,"kp":[]},{"i":39133,"as":"","scd":null,"kp":[]},{"i":39134,"as":"高分辨率实时触觉传感在机器人执行复杂任务时至关重要，但现有触觉传感器技术在空间分辨率和响应速度之间存在固有权衡。基于触觉单元的传感器虽能实时运行，但分辨率受尺寸和布线限制（约1毫米）；基于视觉的传感器分辨率更高，但将原始图像转换为三维接触形貌和压力分布的计算量极大。该研究旨在解决这一矛盾，提出新型高分辨率、实时力致变色触觉传感器技术。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[触觉传感技术]: 存在空间分辨率和响应速度之间的基本权衡","[触觉传感器(Taxel-based)]: 受限于触觉单元数，本质上分辨率受限"]},{"i":39135,"as":"","scd":null,"kp":[]},{"i":39136,"as":"半胱氨酸代谢对非小细胞肺癌（NSCLC）的生长和存活至关重要。研究发现RNA去甲基化酶FTO是驱动NSCLC半胱氨酸代谢的治疗靶点。抑制FTO会降低胱氨酸摄取和转硫化作用，导致细胞内谷胱甘肽耗竭、活性氧（ROS）升高以及DNA损伤介导的细胞死亡。机制上，FTO通过促进胱氨酸摄取转运蛋白SLC7A11及转硫化酶CBS和CTH的表达，维持NSCLC细胞的胱氨酸摄取、代谢和存活。","scd":{"b":7.5,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[治疗靶点(非小细胞肺癌)]: RNA去甲基化酶FTO驱动半胱氨酸代谢","[抑制FTO的效应]: 降低胱氨酸摄取和转硫化活性，导致细胞内谷胱甘肽耗竭和活性氧(ROS)升高"]},{"i":39137,"as":"","scd":null,"kp":[]},{"i":39138,"as":"神经形态工程旨在通过模拟大脑生物效率来克服传统冯·诺依曼架构的局限。该研究基于机械剥离的二硒化钨（WSe2）场效应晶体管构建了光电突触器件，无需复杂的异质结构，仅利用内在缺陷介导的电荷捕获机制即可实现神经形态功能。光刺激通过持续光电导性诱导长效化，电脉冲则引发抑制，实现了通道电导的可逆调制，成功模拟了巴甫洛夫条件反射等神经形态行为。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[光电器件材料]: 二维材料具有优异的光-物质相互作用，是新一代光电人工突触的理想候选者","[光电突触器件]: 基于机械剥离的二硒化钨(WSe2)场效应晶体管"]},{"i":39139,"as":"研究利用表面活性剂模板法合成了锚定在介孔二氧化硅中由镁稳定的钴单原子催化剂（600CoMg/MS）。该方法实现了5.97 wt%的高钴负载量，同时保持了457.359 m²/g的高比表面积。表征证实硅酸镁在稳定Co-O键和提高比表面积方面发挥关键作用。该催化剂在活化过一硫酸盐（PMS）降解5-氟尿嘧啶时表现出色，30分钟内去除率超过97%，且多次循环后去除率保持稳定。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":8.0,"t":5.0},"kp":["Co负载量[Mg稳定的介孔二氧化硅负载Co单原子催化剂(600CoMg/MS)]: 5.97 wt %","比表面积[600CoMg/MS]: 457.359 m²/g","[合成策略]: 采用表面活性剂(CTAB/TMB)模板法合成并具有坚固的Co-O键以激活过一硫酸盐"]},{"i":39140,"as":"将DNAzyme与CRISPR/Cas系统结合以增强分子诊断面临多步工作流程复杂的挑战。该研究开发了一种RNA触发的DNAzyme电路，并将其与CRISPR/Cas12a结合，实现了通用、一锅法且均相的核酸检测预扩增。靶标分析物的识别可解除对DNAzyme催化活性的抑制，激活的DNAzyme切割发夹底物释放多个CRISPR/Cas12a激活子。该级联放大系统实现了简单、特异且灵敏的等温RNA诊断。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[核酸检测系统]: RNA触发的DNAzyme电路与CRISPR/Cas12a集成，实现等温、一锅法RNA诊断"]},{"i":39141,"as":"介绍开发合金化Au-Cu/Ga2O3纳米棒催化剂，用于将CO2高效光热催化转化为MeOH（甲醇）。","scd":{"b":5.5,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[CO2光热催化转化]: 开发合金化Au-Cu/Ga2O3-纳米棒催化剂以高效转化为甲醇"]},{"i":39142,"as":"针对复杂周围神经缺损修复的临床挑战，研究人员设计了一种受创可贴启发、具有组织粘附性的免缝合压电神经修复膜。该Janus双分子层膜采用静电纺丝技术制备：内层为包含明胶甲基丙烯酰基和单宁酸的定向粘附水凝胶纤维，外层为提供屏障和结构支撑的压电丝素蛋白纤维。这种设计能够适应各种神经直径和分支结构，体内实验证实了其在恢复神经形态与功能方面的有效性。","scd":{"b":6.5,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[神经缺损修复材料]: 受创可贴启发设计的组织粘附Janus膜（通过静电纺丝制备），适配各种神经直径和分支结构"]},{"i":39143,"as":"为解决金属有机框架（MOF）粉末可加工性受限的问题，研究将高内相乳液聚合物泡沫与MOF材料UiO-66-NH2结合，通过一锅法合成了复合材料。该材料利用聚泡沫形成大孔结构，结合MOF的吸附特性，构建了用于去除有毒化学气体和蒸汽的多功能平台。研究详细考察了MOF负载量及其复合基体对反应活性的影响。","scd":{"b":5.5,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[宏观成型策略]: 将高内相乳液衍生聚合物泡沫与反应性金属有机框架结合，构建用于有毒化学物质吸附和反应消除的互联互通大孔结构"]},{"i":39144,"as":"针对传统水凝胶智能窗耐候性和可加工性差的问题，研究人员开发了一种由丙烯酸丁酯（BA）和二元离子液体组成的热致变色离子凝胶油墨。该前驱体材料可通过紫外光快速固化，支持3D打印、涂层和卷对卷固化等大规模工业生产工艺。材料内部富离子液体微区的动态分布赋予了其出色的太阳能调节能力和可调的低临界溶解温度。","scd":{"b":6.0,"i":5.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[热致变色离子凝胶墨水]: 由丙烯酸丁酯(BA)和二元离子液体组成，可被紫外光快速固化且适用于3D打印"]},{"i":39145,"as":"针对细胞表面聚糖与凝集素相互作用机制难以在分子层面解析的问题，研究引入了一种基于核磁共振（NMR）的19F标记凝集素技术。通过将19F探针结合到凝集素中，该方法能够有效探测从纯化糖蛋白到细胞表面糖萼的复杂聚糖结合过程，从而深入解码不同凝集素在多重聚糖表位存在下的竞争机制和选择性识别机制。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[分子识别机制]: 凝集素通常对广泛分布的聚糖表现出重叠的结合选择性和相似的亲和力"]},{"i":39146,"as":"为深入理解固体电解质中的离子传输机制，研究团队提出了一种“弛豫匹配”分析框架。该方法结合了中子或X射线散射函数与解卷积时间分辨的范霍夫分析，用于探测石榴石（如Li7La3Zr2O12及Ga掺杂型）固体电解质中的锂离子动力学。该框架揭示了空间和时间相关性如何控制离子传输，为设计高性能超离子导体提供了关键理论依据。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[超离子导体设计]: 离子电导率源于迁移势垒、跳跃频率和移动亚晶格特征扩散长度尺度的耦合相互作用"]},{"i":39147,"as":"研究开发了一种基于单一前体的“二合一”可转化金属有机框架（MOF）光催化纳米平台。通过微波辅助原子级工程，将单原子分散的Pt锚定在In2O3修饰的UiO-66-NH2上（Pt1/In2O3/UiO-66-NH2）。该材料在可见光下实现高效的H2析出（速率达2749.6 μmol g−1 h−1），其氢吸附能接近理想值（ΔGH* = −0.39 eV）。此外，该纳米平台还能通过结构转化实现CO2还原反应。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[光催化纳米平台设计]: 通过微波辅助原子级工程实现从原子分散位点到受限纳米颗粒的可控结构演变","[双功能光催化策略]: 基于单一前体（可转化金属有机框架）的两条独立太阳能燃料途径（光催化析氢和CO2还原）","[纳米结构复合材料]: Pt1/In2O3/UiO-66-NH2"]},{"i":39148,"as":"为解决非苯环芳烃薁在缺电子七元环上选择性官能化的难题，研究首次引入了薁炔中间体前体。计算表明，5,6-和4,5-薁炔前体具有可控的环应力和显著的亲电性。利用这些中间体，研究人员开发了一个模块化平台，能够将多种官能团直接、高效且具位点选择性地引入薁的七元环中，为新型光电材料的合成提供了关键途径。","scd":{"b":8.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[Azulene功能化]: 首次引入实际的azulyne中间体前体，实现电子缺陷的七元环的选择性功能化"]},{"i":39149,"as":"研究突破了简单芳烃去芳构化中固有1,2-加成选择性的限制，首次通过η6-配位实现了未活化简单芳烃的分子间去芳构化1,4-加成。该反应使用双亲核试剂，并通过易变的碘占位基阻断内球还原消除，成功实现了去芳构化1,4-二烷基化和1,4-氢烷基化。该方法具有极广的芳烃底物适用性和优异的官能团耐受性。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[芳烃脱芳香1,4-加成]: 首次实现使用双亲核试剂通过铬/钼η6-配位对简单未活化芳烃的分子间脱芳香1,4-加成，覆盖固有的1,2-选择性"]},{"i":39150,"as":"研究开发了一种含有钌（Ru）的层状MEL沸石催化剂（Ru@MEL），用于聚乙烯的高效升级回收。该催化剂在270°C、4小时的条件下，实现了超过99%的聚乙烯转化率，且对C5-C9液体烯烃的选择性高达92%。其优异性能归因于在结晶过程中Ru的引入促使骨架铝迁移至MEL沸石的直通道中，从而在无外部氢源的条件下高效解构聚乙烯。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[聚乙烯升级循环催化剂]: 具有受限Ru物种的层状MEL沸石 (Ru@MEL)","[聚乙烯升级循环]: 在无外部氢源条件下定量转化为液体烯烃"]},{"i":39151,"as":"研究利用原位拉曼光谱结合X射线和SEM技术，揭示了锂介导的电化学氮还原反应（Li-NRR）中固态电解质界面（SEI）的动态演化机制。研究发现，随着反应进行，SEI的成分会从溶剂衍生的有机物自发转变为含锂盐的无机物。此外，作为质子供体的乙醇通过调节LiF和LiBO2化合物的含量，对SEI的化学组成和物理形貌起着关键控制作用。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[原位表征Li-NRR过程]: 利用原位拉曼光谱结合X射线和SEM揭示Li-NRR过程及SEI动态演化","[SEI结构动态演化]: 具有乙醇依赖性"]},{"i":39152,"as":"研究在范德华铁电材料CuInP2S6中发现了压力诱导的超导性。结合高压拉曼光谱、光吸收测量和第一性原理计算，揭示了该材料的一系列压力诱导相变过程。电学测量表明，在压力超过58 GPa时材料出现超导电性，且超导转变温度（Tc）随压力增加而上升，在215 GPa时达到15 K。这是MPX3材料家族中目前报道的最高Tc值。","scd":{"b":8.0,"i":1.0,"r":6.0,"d":7.0,"t":5.0},"kp":["超导性出现[范德华铁电CuInP2S6]: >58 GPa","[压力诱导相变]: 呈现级联压力诱导相变"]},{"i":39153,"as":"研究通过串联Pinner和席夫碱不可逆级联反应，构建了一种由恶嗪键锁定的二维共价有机框架。该设计将框架结晶与永久性化学键形成相结合，赋予了COF在强酸和强碱条件下的高化学稳定性。该材料被证明是高效的人工光合作用光催化剂，能够实现H2O2的光合生成，为构建稳定的光催化COF材料提供了通用合成路线。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[共价有机框架连接设计]: 通过不可逆串联Pinner/席夫碱反应构建恶嗪锁定的二维COFs","[化学稳定性[恶嗪锁定COFs]]: 在酸性和碱性条件下具有高化学稳健性"]},{"i":39154,"as":"研究开发了一种由镍介导的（杂）芳烃18F-氘代单氟甲基化交叉偶联方法。与基于SN2反应的传统放射化学方法相比，该方法具有前体稳定性高、无需定制前体合成、官能团耐受性广等优势。该一步法反应可同时引入氟-18和氘，已成功应用于30多种底物（包含复杂生物活性分子）。结合半自动化协议，该技术加速了PET配体的早期发现。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[18F,D2-单氟甲基化方法]: 镍介导的（杂）芳烃与（伪）卤化物偶联伴侣交叉偶联","[放射化学优势]: 前体稳定性提高、官能团耐受性广、单步实现氘和氟-18的后期引入"]},{"i":39155,"as":"研究揭示了反溶剂温度结晶法（ITC）生长FAPbI3单晶过程中的溶剂依赖性重新溶解现象。尽管γ-丁内酯（GBL）和2-甲氧基乙醇（2ME）混合溶剂有助于在常温下生成α-FAPbI3，但FAPbI3会促使这两种溶剂发生酯化反应，破坏配位环境并导致材料在持续加热下失稳。研究发现，通过碘化铅（PbI2）的化学计量缺失可有效延缓重溶过程，减少δ-FAPbI3杂相生成。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[溶剂体系[常温生长FAPbI3单晶]]: γ-丁内酯(GBL)和2-甲氧基乙醇(2ME)混合溶剂","[反温度结晶(ITC)现象]: 揭示出意想不到的溶剂依赖性FAPbI3重新溶解现象"]},{"i":39156,"as":"针对钙钛矿量子点（PQDs）固态薄膜手性诱导效率低的问题，研究提出了一种空间位阻约束的表面配位策略。通过在基底上直接合成具有专属手性配体覆盖的CsPbBr3薄膜，实现了明确的配体-表面相互作用。密度泛函理论计算表明，不对称相互作用的强度由配体配位几何构型决定，而非配体密度。该策略显著提升了固态量子点的手性光学感应性能。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[固体薄膜手性钙钛矿量子点]: 采用空间约束表面配位策略及基底合成法实现手性感应和晶格不对称性增强","材料体系[手性薄膜]: CsPbBr3钙钛矿量子点"]},{"i":39157,"as":"研究通过将氨基功能化的金属有机框架与亚稳态光酸共组装，构建了高效的光驱动CO2捕获与释放系统。该系统利用光能在温和条件下调节酸度：在光照3分钟内，每摩尔光酸可从烟气中释放12 mL CO2；而在避光5分钟内即可恢复CO2捕获能力。基于此技术开发的U型连续流原型装置，进一步验证了其结合可再生能源进行碳捕获的可行性。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[光驱动CO2捕获与释放系统]: 氨基功能化金属有机框架与亚稳态光酸共组装实现温和光控条件下高效捕集与可逆释放"]},{"i":39158,"as":"研究通过还原基于s-茚并烯的氯硝基鎓离子，合成了三种第15族卡宾类似物，并发现了截然不同的氢化反应路径，分别生成了中性二氢化砷、单阳离子氢化锑和三核铋双阳离子。其中，锑阳离子表现出质子化锑宾（I）的特性，可与三甲基铟/镓及二苯基二硫族化物反应，形成含Sb-E双键的化合物。三核铋双阳离子则展现出显著的2电子-3中心键特征。","scd":{"b":6.0,"i":1.0,"r":7.0,"d":5.0,"t":5.0},"kp":["[第15族氯络鎓离子]: 还原反应因元素差异化路径生成中性二氢化砷、单阳离子氢化锑及三核铋双阳离子"]},{"i":39159,"as":"研究开发了一种由手性配体调控的镍催化方法，实现了碳水化合物非端基位置的立体选择性自由基迁移C2-芳基化。该方法直接使用易得的1-卤代糖和芳基硼酸，通过一类新型手性2-(氨基甲基)吡啶配体实现催化剂介导的立体控制。反应具有广泛的底物适用性和官能团耐受性，支持复杂分子架构的克级规模合成，为糖类化合物的精准修饰提供了新途径。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["催化剂体系[碳水化合物C2-芳基化]: 镍催化剂结合手性2-(氨甲基)吡啶配体实现非端基碳的高非对映选择性自由基迁移交叉偶联"]},{"i":39160,"as":"硫化物基全固态锂金属电池因硫化物电解质的高离子电导率和高容量电极成为高能量密度储能的首选。然而，要实现400 Wh/kg的目标，必须克服界面不稳定性、材料机械脆性等挑战。这依赖于从材料界面、电极制造到电芯集成的多尺度协同设计和精密制造。文章系统总结了界面失效机制，并探讨了向大面积软包电池集成的关键工艺路径。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["目标能量密度[硫化物基全固态锂金属电池]: 400 Wh/kg"]},{"i":39161,"as":"研究通过在共价有机框架的主链中引入炔基基团以实现连续的π共轭，从而提升可见光光催化性能。在TpBD-COF基础上合成了TpEDD-COF和TpBDD-COF两种β-酮烯胺COF。DFT计算证实，炔基的引入提高了分子的平面度，显著放大了COFs中的π电子离域。光电性能测试表明其光催化特性得到增强，能够有效活化氧气分子，促进选择性电荷转移。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["[β-酮烯胺共价有机框架]: 骨架中引入乙炔或二乙炔基团提供连续π共轭以增强可见光光催化选择性电荷转移效能"]},{"i":39162,"as":"通过化学共沉淀法合成了二元至四元等摩尔多组分稀土磷酸盐粉末，并在1500°C下通过火花等离子烧结（SPS）致密化。研究系统表征了其热导率、热膨胀系数（CTE）及抗CMAS腐蚀性能，以评估其作为碳化硅陶瓷基复合材料环境屏障涂层（EBC）的潜力。结果显示，所有成分的CTE均与SiC/SiC-CMC相近，且热导率取决于阳离子尺寸无序度和成分复杂性。在成分元素数量恒定时，阳离子尺寸无序度增加可降低热导率。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["烧结温度[稀土磷酸盐环境障涂层]: 1500 °C","成分体系[环境障涂层]: 二元到四元等比例混合稀土磷酸盐(REPO4)","[环境障涂层性能评估]: 测试表征热导率、热膨胀系数及抗CMAS(钙镁铝硅酸盐)腐蚀能力"]},{"i":39163,"as":"基于先前构建的40个单倍体组装构建的荷斯坦泛基因组（H20D），研究人员对1571头牛进行全基因组测序，鉴定了93059个结构变异（SV），并开发了名为HolPIP的泛基因组变异插补参考面板。借助HolPIP，成功为50299头公牛插补了86.65%的结构变异。利用这些插补数据和43个复杂性状的表型进行全基因组关联分析（GWAS），识别出1225个SV-性状关联，并通过精细映射优先确定了32个高置信度候选基因位点。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":8.0,"t":5.0},"kp":["[泛基因组单倍型组装数]: 40个 phased haploid assemblies 构建 H20D","[结构变异基因分型数]: 从1571头牛的全基因组序列中基因分型了93,059个结构变异","[变异插补参考面板]: 开发了名为 HolPIP 的荷斯坦泛基因组变异插补参考面板"]},{"i":39164,"as":"为解决3D医学图像中血管手动分割耗时且计算精度有限的问题，举办了一场全球机器学习竞赛，吸引1401名参赛者开发针对分层相差断层扫描图像的深度学习血管分割方法。对顶尖方案的荟萃分析揭示了趋同的方法学创新，包括利用数据分布的伪标签方法，以及针对形态学分析和提升分割精度而优化的度量指标与损失函数。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[3D血管分割深度学习模型]: 举办全球机器学习竞赛开发针对3D分层相差断层扫描图像脉管分割的高效算法"]},{"i":39165,"as":"研究发现，COPII介导的囊泡运输受到依赖于磷脂酸（PA）的Opi1-Ino2/Ino4调节回路的转录控制。Ino2/Ino4的靶基因YIP3对COPII介导的囊泡运输产生负向调节作用。Ino2/Ino4能够调节COPII囊泡形成初期的Sar1激活，而Yip3则阻碍该过程。揭示了脂质代谢的内质网传感通过PRA家族依赖性途径精确调节COPII囊泡运输的新机制。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":4.0,"t":5.0},"kp":["[COPII囊泡运输调节]: COPII介导的囊泡运输通过磷脂酸(PA)依赖性的Opi1家族进行转录控制"]},{"i":39166,"as":"研究利用冷冻电子显微镜技术，解析了E. coli K12来源的Wza-Wzc复合物在野生型自磷酸化状态和非磷酸化突变状态下的两种结构。结构表明，Wza和Wzc组装形成了一个横跨整个细菌被膜的连续通道，共同介导细菌荚膜酸的易位。该发现完善了Wza-Wzc复合物的整体架构认知，并阐明了调控荚膜酸 export 的分子机制。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["[Wza-Wzc复合物]: 采用冷冻电子显微镜解析其整体结构以阐明革兰氏阴性菌细胞膜上荚膜酸易位与外排调节机制"]},{"i":39167,"as":"本研究利用空间转录组学技术全面分析了侵袭性骨肉瘤，揭示了其高度异质性。尽管存在这种异质性，研究仍发现并验证了一个具有诊疗潜力的九基因细胞表面标记物，支持多靶点治疗策略。对肿瘤免疫微环境的分析表明，骨肉瘤中存在系统性的淋巴细胞排斥、不同模式的髓系细胞浸润，以及I型干扰素反应特征，这可能解释了早期IFN-α补充治疗试验失败的原因。此外，研究还在人骨肉瘤肺转移灶内发现了单核细胞来源的破骨细胞分化现象，并确定了相关的细胞前体群。该成果为骨肉瘤的诊断与靶向免疫治疗提供了重要依据。","scd":{"b":7.5,"i":3.0,"r":6.5,"d":7.0,"t":4.0},"kp":["细胞表面标记特征[侵袭性骨肉瘤]: 九基因特征","靶向与诊疗潜力[骨肉瘤]: 具有诊疗一体化潜力"]},{"i":39168,"as":"研究利用来自硫化叶菌的pRN1质粒引物酶作为模型，结合核苷酸类似物捕获瞬态中间体，通过核磁共振（NMR）和建模揭示了DNA引物酶起始二核苷酸形成的机制。引物酶的辅助结构域同时结合DNA模板和两个起始核苷酸。其中，仅第二个核苷酸与模板配对，首个核苷酸保持未配对状态，引起模板碱基翻转和连接子相互作用，促使复合物形成闭合构象以完成合成。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["研究模型[引物合成机制]: pRN1质粒编码的引物酶（来自嗜酸热古菌）","研究方法[捕获二核苷酸形成中间体]: 使用核苷酸类似物减缓反应","结构表征技术[引物酶辅助结构域]: 核磁共振（NMR）与结构建模"]},{"i":39169,"as":"通过对环境及临床相关的子囊菌酵母进行基因组分析，发现其具有强烈的遗传结构分化。其基因组具有高度的染色体不稳定性，这与两种在所有谱系中广泛存在的DNA转座子（Dici1和Dici2）密切相关，在模式菌株中Dici1拷贝数高达96个。实验证实这两个转座元件在实验室条件下保持活性并发生动员。高序列保守性表明，近期发生的持续转座爆发正在重塑该物种的基因组可塑性。","scd":{"b":5.5,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["基因组不稳定性原因[Diutina catenulata酵母]: 与两个DNA转座子（Dici1和Dici2）相关","群体遗传结构[Diutina catenulata]: 深度分歧的演化支且基因交流受限"]},{"i":39170,"as":"在青藏高原冰川消退的130年时间序列上开展多组学调查，发现冰川退缩重塑了病毒和微生物群落。在退缩初期的1至5年内，特异性富集了编码氧化异化亚硫酸盐还原酶（Dsr）操纵子的硫氧化细菌。相关病毒主要采用“搭便车”策略。结论表明，病毒调节的硫氧化细菌在消融生态系统初级演替过程中驱动了有机碳汇的形成。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":8.0,"t":4.0},"kp":["[冰川退缩消融区初级演替]: 硫氧化细菌的病毒调节驱动有机碳汇形成","研究跨度[青藏高原冰川前缘]: 130年时空序列","群落规模[冰前生态系统病毒]: 61,394个病毒分类单元","群落规模[冰前生态系统微生物]: 40类(分类群)"]},{"i":39171,"as":"本研究通过高温高压实验表明，在水未饱和的俯冲板块中，含水矿物在地幔过渡带会逐步脱水，并将水分转移至瓦兹利石等名义上无水的矿物中，而冷板片核心则保持干燥。研究指出，下地幔顶部的快速脱水可能产生与最深地震相关的流体。大多数深源地震可能是由无水橄榄石相变而非脱水脆化引发的。此外，名义无水矿物中的水合变化会影响板片在660公里深度上方的变形与停滞，且岩石的整体镁硅比控制着含水矿物的稳定性。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":7.5,"t":4.0},"kp":["实验体系[板块俯冲带水交换过程]: MgO-SiO2-H2O系统","含水量[实验体系]: ~2 wt% H2O","相变机制[地幔过渡带含水矿物]: 含水矿物渐进脱水并将水转移给名义上无水矿物"]},{"i":39172,"as":"通过卫星植被指标量化全球半干旱地区的植被恢复力发现，56.6%的半干旱植被区表现出滞后1年时序自相关增加，且2001至2024年间的平均值呈持续上升趋势，表明恢复力正在下降。使用象限框架分析显示，47.5%的植被区在变绿的同时伴随着恢复力下降。结论证实热浪等极端气候加剧了半干旱地区植被恢复力的严重减缓。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.5,"t":4.0},"kp":["植被恢复力下降比例[热浪加剧的半干旱地区]: 56.6%","量化评估指标[半干旱植被恢复力]: 滞后一阶时间自相关"]},{"i":39173,"as":"文章评估了相间调节作为激活纳米复合材料多尺度增韧的核心机制。在纳米相间中，聚合物链表现出与本体截然不同的断裂力学机制，是抵抗弯曲变形增韧的决定性因素。综述指出，天然结构材料通过跨越纳米到宏观的复杂分层结构实现高强度和高韧性，借鉴此原理，结合相间调节机制和可扩展制造技术，将推动结构工程增韧纳米复合材料的研发。","scd":{"b":6.5,"i":4.0,"r":6.0,"d":7.0,"t":4.0},"kp":["增韧机制[合成聚合物纳米复合材料]: 相间调节是驱动的决定性因素"]},{"i":39174,"as":"通过水热合成SrTiO3并将其与g-C3N4机械混合后煅烧，制备了g-C3N4/SrTiO3 II型异质结纳米复合材料。该材料应用于柔性催化过氧化氢（H2O2）生产，通过氧还原途径显著提升了催化效率。优化后的异质结在机械化学驱动下，H2O2的产率达到了645.1 μmol·g⁻¹·h⁻¹，有效克服了传统压电材料的对称性限制和活性位点不足的问题。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["催化机制[g-C3N4/SrTiO3 II型异质结]: 氧还原途径增强柔性催化H2O2生产"]},{"i":39175,"as":"针对传统紫外纳米压印光刻（UV-NIL）光刻胶存在体积收缩大、耐热性差和氧抑制严重等缺陷，设计了一种具有可调分支结构的Vi-T系列硅氧基硫醇烯光刻胶。研究阐明了化学计量比和拓扑结构双重调控光聚合动力学、流变行为及图案保真度的机制。在精确优化的非化学计量比（C═C/–SH = 1:1.x）条件下，该光刻胶实现了极佳的图案分辨率和保真度。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":4.0},"kp":["光刻胶体系[紫外纳米压印光刻]: Vi-T系列硅氧烷基硫醇烯光刻胶（具备可调分支结构）"]},{"i":39176,"as":"探索了在光化学上转换中，利用开壳层有机自由基作为敏化剂，与其闭壳层加氢类似物作为消灭剂的应用。分子将三苯甲基自由基的光学跃迁与蒽基组分的三重态结合，而仅差一个氢原子的闭壳层对应物则将自旋光学性质转变为能够介导高效上转换的消灭剂。这一发现突破了传统闭壳层敏化剂系间窜越造成能量损失的限制。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["敏化剂[光化学上转换]: 开壳层有机自由基","消灭剂[光化学上转换]: 闭壳层加氢类似物"]},{"i":39177,"as":"隐藻藻胆蛋白PC645是位于光合膜腔侧的光 harvesting 复合物。利用高效密度泛函紧束缚（DFTB）框架进行多尺度模拟，研究了光合作用导致腔内pH值下降（最多降低两个单位）时PC645复合物的光谱和激发能转移过程。结论表明，pH依赖性的振动动力学是驱动PC645复合物激发态猝灭的关键机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["pH变化幅度[光合作用发光侧]: 最多降低2个pH单位","激发态猝灭机制[藻胆蛋白PC645]: pH依赖性振动动力学驱动"]},{"i":39178,"as":"开发了一种由LiTFSI和磷酸锆（ZP）层间结晶水之间氢键介导的原位聚合方法。该氢键作用诱导质子转移，提升ZP的布朗斯特酸度，实现了1,3-二氧戊环的可控聚合。所得PDOL-ZP电解质具有均匀的长链大分子结构，电压窗口高达5.0V，有效解决了传统路易斯酸催化难以适应高压正极的问题，适用于高压固态锂电池。","scd":{"b":7.5,"i":3.5,"r":7.0,"d":7.0,"t":6.0},"kp":["聚合机制[基于PDOL的高压固态锂电池]: 氢键介导的原位聚合（通过LiTFSI与磷酸锆层间结晶水的氢键诱导质子转移）"]},{"i":39179,"as":"报道了一种通过前体扩散控制实现克级规模合成单分散碘化物钙钛矿胶体量子点的策略。利用配体介导调控延缓单体形成并抑制连续成核，成功分离了结晶阶段，无需合成后尺寸筛选即可获得均匀的CsPbI3量子点。该策略成功扩展至甲脒（FA）阳离子的掺入，可直接合成具有高光伏性能的钙钛矿量子点。","scd":{"b":7.0,"i":3.5,"r":7.0,"d":7.0,"t":6.0},"kp":["合成规模[碘化物钙钛矿胶体量子点]: 克级规模","合成策略[单分散碘化物钙钛矿量子点]: 前体扩散控制分离结晶阶段"]},{"i":39180,"as":"探讨了利用结合几何与物理的增强网络理论来建模和设计具有受控不规则结构的超材料。尽管当前超材料多采用规则结构以保持可控性，但结合机器学习和自组装技术，不规则超材料网络能够展现出增强或全新的物理性质。该领域的研究不仅推动了新型超材料的开发，也为更广泛的物理网络研究开辟了新方向。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["设计框架[不规则超材料网络]: 结合几何与物理的增强网络理论"]},{"i":39181,"as":"","scd":null,"kp":[]},{"i":39182,"as":"","scd":null,"kp":[]},{"i":39183,"as":"","scd":null,"kp":[]},{"i":39184,"as":"","scd":null,"kp":[]},{"i":39185,"as":"","scd":null,"kp":[]},{"i":39186,"as":"导致遗传性肌病的遗传变异类型、大小和序列背景多种多样，包括小序列变异、大型结构变异、重复扩增等复杂事件。使用传统的二代测序技术难以对这些变异进行表征。为此，研究开发了一种靶向长读长测序测定方法和生物信息学分析框架，能够捕获目前与遗传性肌病相关的所有基因、变异和表观遗传特征。在肌病患者队列中的应用证明了该方法的分析有效性及其在检测上的准确性提升。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[遗传性肌病致病变异]: 涵盖小序列变异、大结构变异、重复扩增以及D4Z4大卫星收缩和低甲基化等复杂事件","[靶向长读长测序]: 可克服二代测序等传统分子技术在表征复杂遗传变异上的挑战"]},{"i":39187,"as":"结直肠癌通常表现出抑制性肿瘤微环境，伴随谷氨酰胺代谢升高和免疫抑制性巨噬细胞诱导。研究将谷氨酰胺拮抗剂DON与巨噬细胞靶向部分青蒿素偶联，开发出WGF-T17（T17），可阻断巨噬细胞中的谷氨酰胺代谢。T17在体外能将巨噬细胞代谢重编程为糖酵解，诱导乳酸积累和组蛋白乳酸化，增强线粒体分裂和吞噬活性，使其重编程为炎症状态。体内实验表明，T17通过巨噬细胞介导的机制控制肿瘤生长的效果优于JHU-083。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[谷氨酰胺拮抗剂前药]: 6-重氮-5-氧代-L-正亮霉素(DON)及其前药JHU-083","[巨噬细胞靶向拮抗剂偶联物]: DON与青蒿琥酯偶联形成WGF-T17(T17)","[WGF-T17(T17)作用机制]: 特异性阻断巨噬细胞内的谷氨酰胺代谢"]},{"i":39188,"as":"非洲马瘟病毒（AHSV）是一种致命的马类病原体，目前除减毒活疫苗外无其他安全疫苗。研究解析了AHSV血清型4型全长VP2蛋白的3.11埃分辨率冷冻电镜结构，揭示了其天然三叶草架构及锚定核心的α螺旋结构域。基于结构的图谱分析确定了VP2的一个亚基是中和抗体的关键靶点。使用SpyCatcher/SpyTag技术将该结构域展示在纳米颗粒上，可提供针对病毒的完全保护。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[非洲马瘟病毒(AHSV)4型全长VP2冷冻电镜结构分辨率]: 3.11 Å","[全长VP2蛋白天然构象]: 采用天然三斜构型并具有α-螺旋结构域"]},{"i":39189,"as":"单核细胞是血管稳态和免疫的关键效应物。单核细胞和巨噬细胞表达CSF1R（CD115），它是谱系特异性生长因子CSF1和IL-34的受体。研究表明，急性阻断CSF1R或其基因缺失会干扰单核细胞的细胞内代谢，并通过抑制经典单核细胞的分化，导致血液中非经典单核细胞数量减少。基于谱系特异性敲除谷氨酰胺-果糖-6-磷酸转氨酶1的实验进一步证实了代谢调节在其中的作用。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["[经典单核细胞亚群]: Ly6Chigh(动员至血液循环)","[非经典单核细胞亚群]: Ly6Clow(巡逻型单核细胞)","[单核细胞/巨噬细胞谱系特异性生长因子受体]: CSF1R(CD115)"]},{"i":39190,"as":"理解植物热形态发生机制对于培育气候适应型作物至关重要。研究鉴定出同源异型结构域转录因子BLH1是热形态发生的关键负调节因子，能够调节BZR1-PIF4热形态发生调控模块。过表达BLH1或其同源物会赋予植物高温不敏感性，而blh高阶突变体表现出高温敏感性。BLH1的表达直接受到BZR1的抑制，并受高温下调。研究阐明了BLH1直接结合相关基因并抑制PIF4转录活性的分子机制。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["[热形态发生负调控因子]: BEL1-LIKE HOMEODOMAIN(BLH1)转录因子","[拟南芥热形态发生核心调节模块]: BZR1-BLH1-PIF4反馈模块(起分子放大器作用)"]},{"i":39191,"as":"三阴性乳腺癌（TNBC）缺乏有效的靶向治疗。尽管PARP抑制剂对BRCA1/2突变的TNBC有效，但在BRCA野生型肿瘤中疗效有限。研究发现，锌指蛋白689（ZNF689）在TNBC中调节同源重组（HR）修复。响应DNA损伤时，ZNF689被ATM磷酸化，通过E3连接酶SKP2促进NBS1泛素化，稳定MRN复合物并激活ATM，从而促进HR修复。ZNF689缺失会显著增强TNBC对PARP抑制剂的敏感性，尤其是与PD-L1抑制剂联合使用时。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[ZNF689在三阴性乳腺癌中的功能]: 调节同源重组(HR)修复","[ZNF689缺失的增敏治疗]: 使三阴性乳腺癌对PARP和PD-L1联合抑制敏感"]},{"i":39192,"as":"调节RNA剪接是一种重要的治疗策略。小分子剪接修饰剂（如Risdiplam和Branaplam）能够诱导由于5'剪接位点较弱而被跳过的外显子包含。Risdiplam优先诱导3'端具有N-3G-2A-1序列的外显子，而Branaplam倾向于A-3G-2A-1末端的外显子。为了探究其特异性的决定因素，研究利用生化分析、转录组分析和遗传扰动，确定了序列依赖性和非序列依赖的顺式作用元件和反式作用因子，共同决定了这些小分子对外显子的靶向空间。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[Risdiplam特异性靶向外显子序列]: 优先诱导3'端含有N-3G-2A-1序列的外显子","[Risdiplam和Branaplam作用机制]: 诱导包含因弱的5'剪接位点而被跳过的外显子"]},{"i":39193,"as":"皮肤发育是由非神经外胚层上皮与下方间充质细胞的串扰引发的。关于间充质细胞在正常皮肤生理状态下是否有助于角质形成细胞形成仍不清楚。研究通过谱系追踪、单细胞转录组和表观基因组分析表明，小鼠毛囊间表皮大部分由间充质谱系细胞组成。胚胎活体成像和谱系追踪显示，这些表皮祖细胞起源于外胚间充质，在发育过程中通过间充质向上皮转化（MET）的过程对表面外胚层做出贡献。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["[表皮干细胞形成机制]: 外源间充质细胞通过间充质到上皮的转变(MET)途径参与"]},{"i":39194,"as":"识别大量熟悉物体的视觉学习过程涉及下颞叶皮层（IT）活动的变化，该过程跨越从分钟到数天的多个时间尺度。研究结合实验与理论方法，通过记录猕猴在会话内和跨会话的熟悉度学习过程中的IT皮层活动，推断潜在的突触可塑性机制。研究确定了跨越分钟到数天的两个学习时间尺度，这与不同的突触和细胞机制一致。跨会话期间，平均反应随着熟悉度增加而逐渐降低，这符合突触可塑性机制。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["学习机制[灵长类动物颞下皮层]: 由独特可塑性规则驱动的快/慢时间尺度视觉学习"]},{"i":39195,"as":"序列到功能的神经网络能够学习驱动基因组数据的顺式调控序列规则，但解释这些模型并将其与生物过程联系起来仍具挑战。研究引入了序列归因的成对影响（PISA），通过归因组合解码哪些碱基对特定基因组坐标处的读取结果做出了贡献。PISA能够可视化转录因子基序的影响，检测未发现的复杂贡献基序，并揭示实验偏差。通过学习MNase-seq的偏差，PISA实现了空前的核小体预测模型，揭示了转录因子结合影响核小体定位的规则。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["解释模型[深度学习解码顺式调控代码与核小体组织]: 成对序列归因影响（PISA）组合解码碱基贡献"]},{"i":39196,"as":"物种的海拔迁移是对气候变化有据可查的反应，但其方向和速率差异很大。研究通过分析全球845种动植物物种的记录，探讨了海拔迁移如何依赖于地理区域、气候生态位、全球普遍性以及进化历史。结果发现，这些驱动因素对分布上限和下限的影响不同。热带物种的分布下限向上迁移速度比温带物种快；具有更温暖和湿润最佳气候生态位的物种表现出更快的上缘迁移速率。研究揭示了气候和进化在物种分布变迁中的作用。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[气候变化下物种分布的海拔变化]: 整体呈现向高海拔迁移的趋势，但其方向和速率因地理地带、气候生态位、全球流行度和进化历史而存在显著变异"]},{"i":39197,"as":"海马尖波涟漪重放与记忆回忆、巩固和规划有关，但传统分析依赖于空间微调并排除了非位置细胞。无模板的模型分析通常依赖预定义参数，容易产生偏差。为此，研究开发了一种基于在主动行为期间观察到的成对放电顺序概率来估计尖峰序列似然的分析方法。该方法通过模拟、大鼠单细胞记录和小鼠钙成像数据进行了验证，结果显示其与传统的重放指标高度一致，具有广泛的适用性。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[海马体尖峰序列重放识别新方法]: 基于似然性估计的分析方法","[新方法的优势]: 解决了传统分析依赖空间微调、排除非位置细胞、依赖预定义参数和模式定义受限的问题"]},{"i":39198,"as":"儿童数学和阅读能力个体差异的神经化学机制尚不明确。研究在两个独立队列（共991名儿童）中，探讨了神经递质系统与支持这些能力的大脑结构组织的关系。通过将全脑结构表型映射到包含19种神经递质受体和转运体的PET图谱上，发现在两个领域和队列中，NMDA谷氨酸能受体分布与支持学术能力的大脑结构组织表现出最一致的关联（复制贝叶斯因子数学>9e4，阅读>4）。NMDA受体密度与数学能力的多个功能网络相对应。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["神经递质受体和转运体图谱[学术表现相关全脑结构表型映射]: 涵盖19种","样本量[探究儿童学术能力神经化学机制]: N = 991"]},{"i":39199,"as":"自发神经活动的波动会影响行为决策。研究开发了一种闭环颅内脑机接口，能够检测宽频伽马活动（BGA，70-150 Hz）的瞬时波动，并基于高或低神经状态触发刺激呈现。利用该系统，研究发现前岛叶皮层的高BGA活动与基于价值决策中的接受/拒绝选项相关。前岛叶高BGA能够引导决策行为，揭示了自发的局部神经活动状态对复杂多属性决策的因果影响机制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":5.0},"kp":["BGA信号频段[闭环颅内脑机接口]: 70–150 Hz","控制机制[闭环脑机接口]: 实时检测宽带伽马活动瞬态波动以触发依赖高低神经状态的刺激呈现"]},{"i":39200,"as":"将线粒体DNA（mtDNA）与复杂性状联系起来的研究常受限于样本量小或表型单一。研究利用百万退伍军人计划中超过60万名参与者的数据，对欧洲、非洲、混血美洲和东亚人群进行了mtDNA变异与心脏代谢表型的多祖先分析。在验证了248个mtDNA位点后，鉴定出10个特定祖先的单变异关联，并在性别和2型糖尿病分层分析中发现了23个额外信号。研究明确了标记单倍群J的四个变异（包括D环和MT-ND3等）与心脏代谢特征的关联。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":9.0,"t":5.0},"kp":["验证位点线粒体DNA变异[多祖先心脏代谢特征关联分析]: 248个位点","样本量[多祖先心脏代谢表型线粒体DNA变异分析]: >600,000名参与者","研究人群涵盖 ancestry[百万退伍军人计划]: 欧洲(EUR)、非洲(AFR)、美洲混血(AMR)和东亚(EAS)人群"]},{"i":39201,"as":"社交凝视是灵长类动物交流的基本渠道。尽管先前研究已描绘了社交凝视在前额叶-杏仁核回路中的行为相关性，但其相互作用的因果架构尚不清楚。研究开发了一种算法，将独立记录的猕猴实验环节整合为“超级会话”，实现了对匹配凝视序列的多区域同时记录重建。将动态贝叶斯网络分析应用于这些数据，揭示了杏仁核、眶额皮层、背内侧前额叶皮层之间在时间上结构化且依赖行为的因果相互作用动态。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["算法核心功能[雄性猕猴独立记录会话数据]: 集成为“超级会话(super-sessions)”","算法验证方法[社交凝视因果动力学重建]: 基于真实数据的合成数据验证"]},{"i":39202,"as":"研究提出一种以氯化钠为绿色氯源的电化学驱动对映选择性半频哪醇重排方法，无需化学氧化剂。该方法采用双有机催化剂相转移系统协同管理相转移和对映体诱导。实现交流电（AC）的交替极性电解是该方法的核心，这对于防止催化剂在电极上沉积至关重要。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["氯源[对映选择性氯化]: NaCl（可持续且无需化学氧化剂）","驱动方式[对映选择性氯化]: 电化学原位氧化（首个电力驱动的工艺）"]},{"i":39203,"as":"研究通过淡水注入实验表明，与北大西洋冰山崩解事件同期发生的东北太平洋冰山崩解事件，能通过将淡水输送到北大西洋深水形成区来触发大西洋经向翻转环流（AMOC）减弱。这种初始减弱随后被不列颠及劳伦泰冰盖释放的额外融水放大，为Heinrich Stadial 1的气候事件奠定了先决条件。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["AMOC减弱时间线[Heinrich事件]: 早于Heinrich事件发生"]},{"i":39204,"as":"研究在金表面实现了丙烯氧化电催化碳碳偶联反应，生成2,5-己二酮和3-己烯-2,5-酮两种C6化合物。在温和条件下，C6产物的总法拉第效率达到36%。结合红外光谱、实验和密度泛函理论计算证实，该氧化偶联过程是通过*Pr和*PrOH中间体之间的不对称偶联实现的，填补了丙烯电化学阳极转化中缺乏C-C偶联过程的空白。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["电催化底物与产物[Au表面丙烯氧化]: 丙烯转化为两种C6化合物（2,5-己二酮和3-己烯-2,5-二酮）","反应路径[丙烯电氧化偶联]: 首次实现电驱动C-C偶联过程"]},{"i":39205,"as":"研究提出一种“溢出-储存-弛豫”氢化机制，以克服高电流密度下电催化加氢反应中活性与选择性的相互制约。以乙炔加氢制乙烯为例，采用负载在铜上的原子级分散WOx（WOx/Cu）催化剂，界面处的Cu形成*H，WOx作为*H储库。实验表明，该催化剂实现了约1.43 A的乙烯分电流密度，有效缓解了高电流密度下的析氢和过度加氢问题。","scd":{"b":9.0,"i":3.0,"r":7.0,"d":8.0,"t":5.0},"kp":["反应电流密度[乙炔电化学加氢制乙烯]: 安培级","核心机制[克服高电流密度下活性-选择性比例关系]: 溢出-储存-弛豫氢化机制"]},{"i":39206,"as":"研究利用镁苯基氟硼酸络合物（MPFBC）电解质，系统合成了MPFBC-Cl、MPFBC-Br等对比电解质，阐明了氯离子和溴离子如何影响可充镁电池中的镁电镀/剥离动力学。溴离子具有与氯离子相当的溶解度和质量效率，为解耦卤化物特性对反应动力学的影响、建立系统的卤化物化学理论提供了理想的研究平台。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["Br-特性[可充镁电池硼基电解液卤化物化学]: 具有与Cl-相当的适中溶解度和质量效率（优于F-和I-）","研究目标[可充镁电池电解液设计]: 解耦卤化物阴离子特性对反应动力学的影响"]},{"i":39207,"as":"研究利用原位环境扫描透射电子显微镜（ESTEM），在原子尺度上揭示了铁氧化过程中从α-Fe到Fe3O4的全新氧化路径。实验在具有原子级平整度的金属α-Fe(001)表面上进行，发现亚稳态的FeO在氧化过程中的两种中间状态里发挥了动态持续的介质作用，加深了对气固反应与固态相变耦合机制的理解。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["关键技术[铁氧化气固反应研究]: 原子分辨率环境扫描透射电子显微镜（ESTEM）","核心机制[Fe3O介导的氧化物生长]: 揭示了耦合气-固表面反应与固态相变的原子尺度结构动力学"]},{"i":39208,"as":"研究在生长于Si(111)基底上的原子级厚度铅单层中，发现了一种由界面机制驱动并本征稳定存在的高阶范霍夫奇点（II型HOVHS）。结合角分辨光电子能谱、扫描隧道光谱和第一性原理计算，证实该奇点形成于布里渊区非规则点处。该发现证明了二维Rashba超导体中无需外部调节即可实现HOVHS的本征涌现。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["稳定机制[二维Rashba超导体高阶范霍夫奇点]: 界面驱动机制本征稳定II型高阶范霍夫奇点","物理效应[高阶范霍夫奇点]: 在态密度中产生发散并增强电子关联效应"]},{"i":39209,"as":"为解决理论计算与实验性能间的偏差，研究团队提出了一种统计人工智能方法，用于多元素催化剂的精确筛选。该研究引入统计描述符“φ”，通过分析多种结构的活性分布而非单一模型，精准量化宏观催化活性。团队开发了结合LSTM与EquiformerV2的图神经网络模型，成功预测了2.5亿种掺杂CoOOH的结构过电位，并计算出各元素组合的φ值。最终，研究精确锁定了六种最优的高活性掺杂组合，其中领先的组合为MnFeNiCu，有效弥补了计算模型与实际合成材料之间的差异。","scd":{"b":6.5,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["统计描述符φ[多元素催化剂精确筛选]: 特定元素组合中高活性构型的比例","计算模型修正[多结构活性分布评估]: 考虑多种结构的活性分布以替代单一模型结构，准确量化材料性能"]},{"i":39210,"as":"研究开发了一种基于N'-烷基腙酰胺（NAHA）试剂的还原和成环羰基去除方法。该方法通过连续断裂两个碳碳键，能将多种环酮高效转化为开环或缩环类似物。此策略具有广泛的官能团耐受性和高化学选择性，不仅适用于复杂生物活性分子的后期修饰，还可用于合成缺乏极性官能团的全碳季碳中心。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["关键试剂[后期羰基去除]: N'-烷基腙酰胺（NAHA）试剂","反应路径[环酮分子后期修饰]: 通过连续双C-C键断裂实现还原和环化羰基去除"]},{"i":39211,"as":"研究提出了一种布朗斯台德酸与路易斯酸（三氟甲磺酸镝）双酸协同催化策略，成功实现了尺寸达50μm以上的三维共价有机框架（COFs，XNU-375-X系列）单晶的受控轴向生长和形态演变。通过调节路易斯酸浓度显著抑制了晶体孪生现象，实现了对COFs宏观形态和拓扑结构的精准调控。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["单晶尺寸[三维共价有机框架]: ≥50 μm","催化策略[三维共价有机框架可控轴向生长]: 协同的Brønsted和Lewis双酸催化策略"]},{"i":39212,"as":"研究提出利用锆离子掺杂策略来改善X射线探测器用LiYMo2O8（LYMO）单晶的载流子传输，以克服其超高本征电阻率限制检测灵敏度的问题。通过顶部籽晶溶液法成功生长了纯相与Zr掺杂的LYMO晶体。研究发现，Zr掺杂有效降低了纯相LYMO沿a轴和c轴的高电阻率（9.96×10^13和1.44×10^14 Ω·cm），提升了光电性能。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["掺杂策略[X射线探测器LiYMo2O8单晶载流子传输及灵敏度]: Zr4+掺杂","瓶颈机制[氧化物单晶光电流产生与探测灵敏度]: 超高本征电阻率限制"]},{"i":39213,"as":"超晶格凭借其独特的周期性结构，通过结构设计和界面修饰能够实现材料性质的精细调节。在热电领域，超晶格界面引发的额外声子散射、电荷转移和能量过滤效应，成功解耦了热传输与电传输，使其同时具备极低的热导率和优异的电导率，成为替代传统热电材料的极具潜力的候选者。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":5.0,"t":3.0},"kp":["超晶格特性[热电材料]: 独特的周期性结构","核心机制[超晶格热电学]: 解耦热传输与电传输","超晶格功能[热电材料研究]: 提供额外的声子散射"]},{"i":39214,"as":"研究开发了一种由特异性抗体功能化的电容传感电极，用于同时无标记检测乳酸脱氢酶（LDH）和白细胞介素6（IL-6）。该技术基于蛋白质钝化的石墨烯界面，克服了传统LDH比色检测法依赖复杂仪器、难以在资源受限环境中应用的缺陷，为细胞代谢和免疫调节提供了高效的病理检测手段。","scd":{"b":5.5,"i":3.0,"r":5.0,"d":5.0,"t":5.0},"kp":["检测靶标[无标记电容免疫传感]: 乳酸脱氢酶(LDH)和白细胞介素6(IL-6)","传感界面[蛋白质钝化石墨烯]: 无标记电容免疫传感"]},{"i":39215,"as":"研究利用单层Ca2Nb3O10纳米片作为外延模板，生长织构化SrRuO3薄膜。研究发现，单层纳米片组装中固有的纳米级间隙并非结构缺陷，而是可作为可调谐元件来控制薄膜的晶体生长环境。这些间隙暴露出基底区域，从而有效决定并调控了薄膜的电传输和磁各向异性。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["外延模板[任意基底上生长高质量氧化物薄膜]: 单层Ca2Nb3O10纳米片","技术缺陷[单层纳米片组装]: 本征间隙源于不规则几何形状和随机沉积过程"]},{"i":39216,"as":"研究开发了一种由808nm近红外光驱动的光致变色液晶弹性体（LCE）致动器。该系统将偶氮苯交联LCE与掺钕的上转换纳米颗粒结合，将近红外光转化为紫外/蓝光发射，驱动偶氮苯分子发生反式到顺式的异构化，引起薄膜宏观弯曲。该微槽致动器基底成功应用于心肌细胞的空间排列，避免了紫外光的光毒性。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["驱动光源[液晶弹性体光异构化致动器]: 808nm近红外光","致动材料[近红外光驱动致动器]: 偶氮苯交联液晶弹性体集成NaYF4:Yb/Tm@NaYF4:Yb/Nd@NaYF4","应用优势[心肌细胞对齐微槽基底]: 克服紫外光的光毒性并改善组织穿透性"]},{"i":39217,"as":"研究通过大地电磁成像技术揭示，在二叠纪峨眉山大火成岩省外区的华蓥山断裂带下方存在高电阻率、高地震波速和高密度的垂直结构。结合地动力学模拟证实，该结构是古代地幔羽流柱衍生玄武岩熔体的结晶产物。这些古代羽流强化的岩石圈残留物直接控制并调节了当今地壳流体的迁移和构造变形过程。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["地壳结构[华蓥山断裂带大地电磁成像]: 垂直广泛的高电阻率结构且伴随高地震波速","机制解析[古代地幔羽流残留]: 调节岩石圈结构并影响构造变形"]},{"i":39218,"as":"研究揭示了铁锰基聚阴离子磷酸盐（如Na4FeMn(PO4)3）存在异常电化学惰性的物理根源：PO4多面体在空间上隔离了MO6氧化还原单元，d电子构型在时间上阻碍了电荷传输，形成了“电子时空限域效应”。通过引入具有空3d轨道的钒和钛作为异金属桥连策略，成功解除了这一限制，实现了高能量密度和超宽温钠离子存储。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["惰性机制[铁锰基聚阴离子磷酸盐电化学性能]: 内在电子“时空限制效应”（PO4四面体在空间上隔离氧化还原活性）","材料体系[低成本钠离子电池正极]: Na4FeMn(PO4)3"]},{"i":39219,"as":"研究开发了一种经强酸改性改性的高性能水凝胶，用于高效渗透能转换。利用强酸高度解离和水合的特性，该水凝胶实现了高电导率、低内阻和强保水性能的协同作用。在50倍浓度梯度的氯化钠盐度差条件下，该水凝胶显著提升了离子传输、电力输出和电能转换效率，解决了传统逆电渗析 membranes内阻大和选择性低的关键挑战。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["材料特性[渗透能转换水凝胶]: 高电导率、低内阻和强保水性","改性策略[水凝胶渗透能转换]: 强酸改性引发解离和水合的协同作用"]},{"i":39220,"as":"介绍一种通过铜催化实现的反式选择性芳基烯丙基化反应，涉及非常规的跳跃二烯路线。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["催化剂类型[Ynamide反式选择性芳基烯丙基化]: 铜催化","反应路线[Ynamide反式选择性芳基烯丙基化]: 非常规的跳跃二烯路线"]},{"i":39221,"as":"研究内亥姆霍兹平面反应机制，为高能量密度的锂金属软包电池设计坚固的阳极。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["能量密度[锂金属软包电池]: 500 Wh/kg","机制[坚固的锂金属阳极设计]: 内亥姆霍兹平面反应"]},{"i":39222,"as":"研究开发了一种结合镍催化脱氰和钌催化乙烯醇解的串联催化降解策略，可处理含腈废弃塑料和橡胶。该通用工艺利用乙烯作为氰基受体和复分解伙伴，在一锅中实现高效降解。不仅将含腈聚合物中的氰基去除并回收为高附加值腈化合物，且整个过程不释放剧毒氰化物，具备极高的工业应用潜力。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["催化降解策略[含腈塑料和橡胶]: 镍催化脱氰与钌催化乙烯醇分解串联过程","产物去向[含腈聚合物升级回收]: 去除氰基并回收为高附加值腈化合物，不释放剧毒"]},{"i":39223,"as":"研究开发了一种柔性系双金属铬催化剂，用于催化环氧丙烷立体选择性聚合制备全同立构聚环氧丙烷。该催化剂展现出极高的对映选择性（相对速率常数约100）和前所未有的催化活性（转化频率约50000 h-1）。机制表明，提高水杨亚胺邻位的空间位阻增加了不利过渡态中的空间排斥，从而显著提升了催化剂效率。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":8.0,"t":5.0},"kp":["对映选择性[双金属铬催化剂催化环氧丙烷聚合]: krel ~ 100","催化活性[双金属铬催化剂催化环氧丙烷聚合]: TOF ~ 50,000 h-1","目标材料[海洋应用高强度可光降解材料]: 全同立构聚环氧丙烷"]},{"i":39224,"as":"研究人员开发了一种结合功能化离子液体与具有促进扩散通道的蒽基MOF的复合材料。得益于空间限域离子液体的有序相变，该复合材料在298K和1bar下表现出独特的“S型”氨气吸附等温线，且体积氨吸附量高达455.81 cm³/cm³。该材料同时具备高吸附容量、优异选择性和快速吸附动力学，并建立了额外的离子传输路径。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["复合材料[NH3高效捕集]: 高亲和性离子液体负载于具扩散促进特征的蒽基金属有机框架(MOF/IL)","吸附剂要求[NH3高效捕集]: 高容量、优异选择性和快速吸附动力学"]},{"i":39225,"as":"探讨固相糖脂合成技术在加速脂质体功能化方面的研究进展与具体应用。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[固相糖脂合成]: 加速脂质体功能化"]},{"i":39226,"as":"研究揭示了海水微滴界面能够维持自由基级联反应，显著增强其氧化能力。海水微滴界面自发生成的羟基自由基（·OH）与大量溴离子和碳酸氢根离子发生协同反应，生成包括活性溴（·Br）和碳酸根（·CO3-）在内的次级自由基网络。这种自持的界面循环反应机制极大提升了海水微滴的氧化能力。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":8.0},"kp":["[海水微滴气-水界面]: 自发产生羟基自由基并维持自由基级联反应，其氧化能力显著超越纯水微滴"]},{"i":39227,"as":"通过将静电纺丝与同步光交联相结合的单步制造工艺，成功制备了液晶弹性体（LCE）执行器。研究人员设计合成支化低聚物以平衡可纺性和交联度，并优化光引发系统和静电纺丝装置，实现了液晶域的长程排列。该纤维材料表现出优异的无应力热响应和光响应驱动特性，可应用于软体机器人、人工肌肉等领域。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[液晶弹性体(LCEs)执行器制造]: 结合静电纺丝与同步光交联的单步制造工艺，实现了介晶单元的预定排列"]},{"i":39228,"as":"研发一种基于外场调制Weyl半金属薄膜的太赫兹传感器，用于检测液体中的痕量铅离子。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":7.0},"kp":["传感材料[痕量铅离子太赫兹传感器]: 外场调制的Weyl半金属薄膜","[太赫兹传感器应用]: 检测液体中的痕量Pb2+"]},{"i":39229,"as":"研究高工作电位条件对富锂硫属化物材料转化反应过程及性能的诱导作用。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":3.0,"t":7.0},"kp":["[富锂硫属化物]: 高工作电位诱导其发生转化反应"]},{"i":39230,"as":"提出使用三(二甲基硅氧基)苯基硅烷（TDSPS）作为多功能电解质添加剂，提升4.8V富锂氧化物（LRO）/锂电池的电化学循环性能。加入1 vol% TDSPS的电池在25°C下循环200次后容量保持率高达81.6%，而基准电解质电池仅为34.3%。TDSPS在正极表面优先氧化形成保护层，从而改善了电极-电解质界面并消除了氟化氢。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":8.0,"t":7.0},"kp":["电池体系[LRO/Li锂电池]: 4.8 V","电解液添加剂[种类]: 三(二甲基硅氧基)苯基硅烷(TDSPS)","电解液添加剂[添加量]: 1 vol%","容量保持率[添加1vol% TDSPS在25℃下循环200次]: 81.6%"]},{"i":39231,"as":"设计并制备了基于二维薄膜与氧化物量子点的多维界面结构半导体器件。该架构显著增加了有效界面面积，大幅提升了光生载流子分离和界面电荷注入效率。器件在紫外光照射下实现了无需电刺激的全光驱动可逆操作，展现出极高的运行效率与稳定性，为下一代神经形态计算和人工视觉系统提供了关键技术支持。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[多维界面结构半导体器件]: 基于2D薄膜/氧化物量子点结构，采用柔性溶液工艺制备，实现高效、稳定且可逆的全光控制"]},{"i":39232,"as":"通过金属有机框架（MOF）衍生策略，构建了嵌入导电碳基体中的SnO2-NiO/Ni-碳复合材料。富界面的结构设计实现了转化/合金化反应和界面锂离子存储的协同调节，有效缓解了首圈循环中锂的不可逆消耗。优化后的复合电极展现出1102 mAh g⁻¹的初始放电容量和1035.1 mAh g⁻¹的初始充电容量，显著提高了锡基负极的初始库仑效率。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":8.0,"t":7.0},"kp":["[SnO2基复合阳极设计]: 通过MOF衍生策略构建SnO2纳米颗粒与嵌入导电碳基体中的NiO/Ni异相界面的复合材料，实现对转化/合金反应的协同调控"]},{"i":39233,"as":"提出利用超分子方法合成三种基于支柱[5]芳烃的自组装有机纳米片（SONs），以解决固态导体离子电导率与机械强度之间的矛盾。研究发现，增加氢键位点和亲水性有助于实现最高韧性（66328±424 kJ/m³）；而提高疏水性并减少氢键位点则有利于优化杨氏模量（659.1±22 MPa）。该纳米片复合薄膜在机械和离子传导性能上表现出优异的调控效果。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[超分子固态电解质设计]: 采用基于支柱[5]芳烃的自组装有机纳米片(SONs)，其力学与离子导电特性受控于氢键位点数量、-H···π相互作用等超分子作用"]},{"i":39234,"as":"关于利用环形纳米传感器阵列进行化学流出成像以原位检测膀胱癌的出版商更正声明。","scd":{"b":2.0,"i":2.0,"r":1.0,"d":3.0,"t":4.0},"kp":[]},{"i":39235,"as":"报道了一种利用反应激光烧结（RLS）超快制备石榴石型Li6.4La3Zr1.4Ta0.6O12（LLZTO）固态电解质的策略。RLS技术实现了同步反应和致密化，使电解质的相对密度达到约95%，同时有效减少了锂损耗并抑制了二次相的形成。与常规烧结相比，RLS促进了晶粒生长，使离子电导率提升至0.36±0.08 mS cm⁻¹。","scd":{"b":7.0,"i":5.0,"r":8.0,"d":8.0,"t":8.0},"kp":["[石榴石型LLZTO固体电解质]: 采用超快反应激光烧结(RLS)工艺，实现同步反应与致密化，相对密度达约95%且最小化锂损失"]},{"i":39236,"as":"针对宽带隙金属卤化物钙钛矿在富溴状态下引起的开路电压损耗和相分离问题，提出了一种基于甲酸铯和甲脒的双添加剂策略。引入的甲酸根离子在调控过程中发挥了关键的双功能作用，有效改善了由高溴掺入引起的碘相关氧化还原失衡和未配位Pb²⁺缺陷，抑制了非辐射复合和离子迁移，从而显著提升了电池性能。","scd":{"b":8.0,"i":3.0,"r":5.0,"d":6.0,"t":7.0},"kp":["[宽带隙钙钛矿太阳能电池]: 面临富含Br组分导致的加速结晶、大量缺陷态及光致卤化物相分离问题，引发显著的开路电压损失和不稳定性"]},{"i":39237,"as":"受生物构象多重性启发，利用单一荧光两性离子单体实现了对超分子离子聚合物聚集形态的选择性自组装控制，使其能够形成结晶、凝胶或无定形状态。该极简设计方法不仅实现了凝胶化过程的实时可视化，还开发出一种高性能的水系锌离子电池负极保护材料，为功能超分子材料的开发提供了广阔潜力。","scd":{"b":8.0,"i":3.0,"r":5.0,"d":6.0,"t":7.0},"kp":["[超分子离子聚合物调控]: 利用单一荧光两性离子单体实现选择性自组装，可生成晶态、凝胶或无定形态，用作水系锌离子电池的高性能阳极保护材料"]},{"i":39238,"as":"","scd":null,"kp":[]},{"i":39239,"as":"评估了碳硅烷树枝状聚合物（G3Si PEG6000）及其siRNA复合物作为药物递送平台在阿尔茨海默病（AD）治疗中的效果。在细胞层面，该树枝状聚合物有效增强了siRNA的胞内信号并降低了基因毒性；在三培养血脑屏障（BBB）模型中，有效维持了屏障功能并展现出良好的渗透性；在AD小鼠模型中改善了学习能力，展现出优越的传输性能。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":7.0},"kp":["[碳硅烷树枝状聚合物(G3Si PEG6000)]: 作为递送平台用于siRNA递送，可实现血脑屏障(BBB)的高效渗透并用于阿尔茨海默病治疗行为评估"]},{"i":39240,"as":"综述静电纺丝素纳米纤维在设计策略上的研究进展及其在组织工程领域的新兴应用。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":[]},{"i":39241,"as":"关于肝素胶 micelles 同时作为载体和药物表现出抗肿瘤与抗转移活性的相关文章更正。","scd":{"b":2.0,"i":2.0,"r":3.0,"d":2.0,"t":5.0},"kp":[]},{"i":39242,"as":"提出了一种具有局部导热复合岛的“岛桥”结构架构，用于解决可拉伸电子器件的热积累和刚软界面不匹配问题。通过在软基板特定区域掺入立方氮化硼（c-BN），构建了面内和面外热导率分别达2.327 Wm⁻¹K⁻¹和2.596 Wm⁻¹K⁻¹的导热岛。该设计使峰值温度降低12.8°C，基于此构建的可拉伸计算平台在实际运行中工作温度保持在40°C以下。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":8.0,"t":7.0},"kp":["热导率[面内和面外]: c-BN复合岛提供高导热特性","[软基板热管理]: 采用岛桥架构与定向热传导复合岛解决热积累与刚软界面不匹配问题"]},{"i":39243,"as":"","scd":null,"kp":[]},{"i":39244,"as":"研究通过全基因组CRISPR敲除筛选结合AI语言模型框架，寻找银屑病角质形成细胞中IL-17受体A（IL17RA）的调节因子。成功验证了5-脂氧加氧酶（ALOX5）和催产素受体（OXTR）这两个此前与IL17RA联系极小的调控基因。这一发现为开发靶向IL-17/IL-17RA轴的局部外用小分子替代药物提供了关键理论依据。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["患病基数[银屑病]: 超过1.25亿人","[靶点筛选机制]: 运用全基因组CRISPR敲除筛选揭示原代人表皮角质形成细胞中IL17RA的调节因子"]},{"i":39245,"as":"","scd":null,"kp":[]},{"i":39246,"as":"","scd":null,"kp":[]},{"i":39247,"as":"","scd":null,"kp":[]},{"i":39248,"as":"研究探讨了学习动作时机过程中新皮质细胞类型特异性可塑性的互补作用。在小鼠学习运动计时任务时，前运动皮层中两条锥体束（PT）神经元亚型的CaMKII依赖性可塑性是学习过程所必需的，而 IT 神经元则不是。PT亚型中CaMKII的瞬时失活不影响动作执行，但会损害学习过程，证实了特定神经元可塑性在塑造新皮质动力学中的因果作用。","scd":null,"kp":["[学习与行为机制]: 瞬时抑制前运动皮层中的CaMKII会损害运动时机学习，但不影响已习得行为的执行"]},{"i":39249,"as":"","scd":null,"kp":[]},{"i":39250,"as":"","scd":null,"kp":[]},{"i":39251,"as":"瞬时受体电位香草酸亚型1（TRPV1）通道是痛觉感知的关键受体。研究通过计算技术与化学库靶向设计，发现了对TRPV1具有高亲和力和功效的苯并噻吩取代型激动剂。体外实验表明，长时间或重复暴露于这些化合物会诱导TRPV1发生依赖钙离子的脱敏作用，使其对有害刺激失去敏感，从而发挥长效镇痛作用。研究还解析了人类TRPV1与最优激动剂MSP20复合物的冷冻电镜结构。","scd":null,"kp":["[药物发现策略]: 结合计算技术与化学库靶向设计，发现具有高亲和力和效能的苯并噻吩取代TRPV1激动剂","[药效特征]: 体外功能实验证实具有长效镇痛作用"]},{"i":39252,"as":"","scd":null,"kp":[]},{"i":39253,"as":"","scd":null,"kp":[]},{"i":39254,"as":"","scd":null,"kp":[]},{"i":39255,"as":"","scd":null,"kp":[]},{"i":39256,"as":"人类大脑皮层神经回路发育周期较长，这与认知能力有关。研究发现，抑制人类特有的微小RNA（miR-1229-3p）会改变人类神经元的成熟轨迹，并增强兴奋性突触的传递。转录组分析显示，miR-1229被敲低后，线粒体DNA（mtDNA）编码的基因表达下调。miR-1229能够调节线粒体形态、mtDNA丰度及线粒体自噬，表明其通过调控线粒体功能控制了兴奋性突触发生的时间。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["靶点分子[控制兴奋性突触发生的时间及人类神经元成熟轨迹]: 人类特异性微小RNA miR-1229-3p","[抑制miR-1229-3p]: 改变人类神经元成熟的轨迹"]},{"i":39257,"as":"鼠伤寒沙门氏菌通过向宿主细胞质转导效应分子来操纵细胞过程。在新生儿感染模型中，沙门氏菌外蛋白B（SopB）能抑制早期黏膜组织炎症并延长宿主存活时间。在机制上，SopB阻止了ADAM17的激活和膜易位，阻碍了肠上皮细胞释放膜结合型TNFα，并通过mTOR控制的分泌自噬作用减少了IL-18的上皮分泌。这消除了早期的上皮转录反应，减少了免疫细胞募集。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["效应蛋白[抑制转录后调节的细胞因子释放及早期黏膜组织炎症]: SopB","作用机制[SopB延缓疾病进展]: 阻止ADAM17（解聚素和金属蛋白酶17）激活"]},{"i":39258,"as":"研究通过双亲本遗传作图和诱变技术，鉴定出了被小麦串联激酶蛋白WTK4识别的小麦白粉病效应子AvrWTK4。AvrWTK4是一种RNase样效应子，其基因突变或表达量降低会导致对含有WTK4植株的毒性增强。将无毒性的AvrWTK4变异体转染至表达WTK4的粗山羊草原生质体中，会特异性诱导细胞死亡。无毒变体与WTK4的N端HMA样整合域相互作用更强，从而触发免疫反应。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["识别结构域[小麦串联激酶WTK4]: HMA样整合域","识别靶标[WTK4识别的小麦白粉病病原体效应子]: RNase样效应子AvrWTK4"]},{"i":39259,"as":"慢性伤口由持续炎症、蛋白水解失衡、微生物定植和组织再生受损驱动，是重大的临床挑战。本文评估了静脉腿部溃疡、糖尿病足溃疡和压疮的2D与3D体外模型。现有的系统缺乏重现非愈合表型关键特征所需的生化复杂性。基于临床伤口渗出液数据，文章提出了一种以特征为驱动、以病因为分层的新框架，为体外模型和慢性伤口模拟培养基提供了模块化的设计考量。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":4.0,"t":3.0},"kp":["[当前2D和3D体外模型]: 缺乏重现慢性伤口不愈合表型关键特征所需的生化复杂性"]},{"i":39260,"as":"精准营养的核心在于利用多模式数据为个体差异量身定制干预措施。人工智能（AI）和机器学习（ML）在建模复杂数据方面展现出巨大潜力，但仍受限于数据质量、可解释性、验证和因果推断等挑战。文章综合了当前精准营养中的AI/ML方法，阐明了其与多组学及营养数据（如成分性、偶发性、依赖上下文和易出错的特性）的相互作用，并制定了实现稳健、可解释且具临床实用性的AI整合的营养特定最佳实践。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":4.0,"t":3.0},"kp":["[人工智能和机器学习在精准营养中的应用]: 受限于数据质量、可解释性、验证和因果推断的挑战"]},{"i":39261,"as":"FLOWR.ROOT是一个SE(3)-等变流匹配基础模型，在单一骨干网络中统一了口袋感知3D配体生成与多终点结合亲和力预测（pIC50、pKi、pKd、pEC50）及基于pLDDT的置信度估计。该模型支持从头生成、相互作用条件采样、骨架跃迁和片段生长替换。模型训练分三阶段进行：基于数十亿配体构象的大规模预训练、在共晶数据上精调，以及通过参数高效的LoRA微调进行特定项目适配。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":7.0,"t":6.0},"kp":["基础模型[联合口袋感知3D配体生成与多终点结合亲和力预测]: FLOWR.ROOT (SE(3)-等变流匹配模型)","亲和力预测指标[3D配体结合]: pIC50、pKi、pKd、pEC50","置信度估计[生成的配体]: 基于pLDDT的置信度估计","[FLOWR.ROOT单模型支持]: 从头口袋条件生成、基于药效团和相互作用条件的采样、骨架跃迁、片段生长或替换"]},{"i":39262,"as":"研究开发了一种掺杂铕基复合物(Et4N)[Eu(nta)4]的透明聚甲基丙烯酸甲酯（PMMA）薄膜，兼具发光太阳能聚光器（LSC）和发光温度探针的功能。nta配体能在近紫外光谱范围内有效吸收阳光并敏化铕离子发光，实现高达50%的总体发射量子产率和90%以上的敏化效率。制备的PMMA薄膜保持高度透明（透光率90-100%），在下一代智能窗户中具有同时收集太阳能和监测环境温度的应用前景。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["发光太阳能聚光器材料[智能窗]: 掺杂EuIII基络合物的透明聚甲基丙烯酸甲酯(PMMA)薄膜","[多功能机制]: 兼具太阳能聚集与发光温度探针功能"]},{"i":39263,"as":"长时间体外扩增会导致间充质干细胞（MSCs）衰老，限制其治疗功效。为改善细胞衰老，研究人员开发了一种惯性聚焦辅助的液滴微流体平台，用于在单细胞水平上高通量、高效率且定量控制线粒体转移。该平台实现了29.2%的单细胞液滴包裹率，克服了共培养和微注射等传统方法定量控制差、通量低及易损伤细胞的缺点，成功将年轻MSCs的线粒体转移至衰老的MSCs中。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["线粒体转移策略[改善细胞衰老]: 液滴微流体介导的从年轻间充质干细胞到衰老间充质干细胞的转移","[传统线粒体转移方法(共培养和微注射)]: 存在定量控制能力差和效率低的局限性"]},{"i":39264,"as":"研究报道了一种远程等离子体辅助方法，成功合成了氮掺杂无定形碳（NDAC）单片膜。该膜的厚度可实现从亚1纳米到几纳米的连续可调，结合了二维几何形状和结构无序的双重优势。研究展示了该NDAC薄膜在电子透射和铜扩散阻挡层领域的应用前景。这项工作使NDAC成为需要极端厚度、连续性和各向同性的下一代电子器件和阻挡涂层的候选材料。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["膜厚度[氮掺杂无定形碳]: 亚纳米至数纳米连续可调","[制备工艺]: 远程等离子体辅助合成法","[应用特性]: 适用于电子透射和铜扩散阻挡层领域"]},{"i":39265,"as":"METTL3-METTL14（M3/M14）异二聚体是催化N6-甲基腺苷（m6A）沉积的核心。研究利用高速原子力显微镜（HS-AFM）首次实现了M3/M14单分子动态可视化。观察发现，底物RNA结合诱导M3/M14从开放刚性状态转变为紧凑的催化活性状态。基于此动态机制，通过体外筛选策略鉴定出两种强效DNA适配体抑制剂M3B和M3L，它们能构象捕获M3/M14异二聚体从而抑制m6A的沉积。","scd":{"b":7.0,"i":2.0,"r":8.0,"d":6.0,"t":5.0},"kp":["[构象动力学机制]: 底物RNA结合诱导METTL3-METTL14异二聚体发生构象转变","[表征技术]: 利用高速原子力显微镜(HS-AFM)实现单分子水平的动态可视化"]},{"i":39266,"as":"研究有机电化学晶体管的氧化还原动力学，探讨其在高性能并行储层计算中的应用。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["氧化还原动力学[有机电化学晶体管]: 可调谐","[有机电化学晶体管]: 适用于高性能并行储层计算"]},{"i":39267,"as":"细胞方向对组织形成和功能至关重要。研究在起皱的聚二甲基硅氧烷基底上，构建了由高度有序金纳米球（AuNSs）线性组装体组成的各向异性表面纳米结构。该结构提供的纳米形貌线索能够诱导RSC96施万细胞沿着AuNS链发生显著的定向延伸和对齐，这种引导作用覆盖了底层褶皱形貌的导向。免疫荧光分析表明，该效应与灶性黏附的定向组织和肌球蛋白II介导的张力依赖性机械转导有关。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["基底材料[各向异性表面纳米结构]: 皱褶聚二甲基硅氧烷基底上的高度有序金纳米球线性组装体","[细胞方向调控]: 提供纳米形貌线索诱导RSC96施万细胞的显著伸长和定向排列"]},{"i":39268,"as":"为解决被动辐射冷却（PRC）材料易受环境污染老化及夜间过度冷却的问题，研究设计制备了一种具有抗紫外线（UV）和储热能力的新型无机核壳散射体（ICSS）。通过硅烷化改性和蒸发驱动组装，开发出一种超疏水涂层，成功将抗紫外线、辐射冷却与热能储存功能集成于一体。该涂层有效提升了材料的耐用性，并缓解了夜间持续冷却导致的时间敏感性过冷问题，实现了稳定连续的零能耗冷却。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[技术痛点]: 辐射冷却材料易受环境污染老化影响且夜间易过度冷却导致冷却时效受限"]},{"i":39269,"as":"CuInS2/ZnS胶体量子点因其吸收光谱广、斯托克斯位移大和光致发光量子产率（PLQY）高，是发光太阳能聚光器（LSC）的理想发光体。然而，使用特定原料生长ZnS壳层时会产生可共分散的残留杂质（CDRI）。这些杂质在提纯时会与量子点共沉淀，降低胶体稳定性并限制油墨配方的开发。研究引入了极性调节沉淀技术，在保留CQDs发光效率的同时去除了CDRI，有效提高了胶体稳定性和配方的多样性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["发光量子产率[发光太阳能聚光器]: 高","[杂质生成机制]: ZnS壳生长过程中的原位硫酯化反应产生可共分散残留杂质(CDRI)","[杂质影响特征]: 模拟胶体量子点分散/沉淀行为影响器件性能"]},{"i":39270,"as":"研究提出了一种基于杯[6]芳烃介导的反硫化方法，为天然橡胶/炭黑（NR/CB）复合材料构建了机械互锁的多硫化物交联剂。缺乏可聚合基团的叔丁基杯[6]芳烃（TBC6）在橡胶-填料界面形成聚轮烷结构，增强结合胶的形成并实现界面滑移；而带有烯丙基官能团的ATBC6则参与共交联。这种网络与界面的协同强化策略，显著提升了复合材料的撕裂阻力、耐久性及抗老化性能。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["交联策略[天然橡胶/炭黑复合材料]: 杯[6]芳烃介导的反硫化","交联结构[天然橡胶/炭黑复合材料]: 机械互锁多硫化物"]},{"i":39271,"as":"针对生物质糠醛直接电催化氢解制2-甲基呋喃过程中的复杂四电子转移导致活性与选择性不佳的问题，研究人员开发了一种由碳基质包裹的混合价态铜簇催化剂。该策略通过碳基质营造了减少H+吸附的有利环境，利用Cu+位点轻松活化Fur-CH2OH*中的C-O键，同时Cu0的参与显著加速了氢化过程。实验表明，该方法在动力学和热力学上均具有双重优势，成功促进了向2-甲基呋喃的高效电子转移。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["电催化氢解目标产物[生物质糠醛]: 2-甲基呋喃","电子转移数[2-甲基呋喃生成过程]: 四电子转移","催化剂设计[糠醛氢解]: 碳基质包裹的混合价态铜簇","调控机制[电子转移]: 中间体覆盖诱导策略"]},{"i":39272,"as":"光致环状有机分子的开环反应是众多光化学过程的基础。尽管超快技术取得了一定进展，但对超快核运动的直接、明确成像仍是一项重大挑战。研究展示了利用时间分辨库仑爆炸成像结合分子动力学模拟，成功识别并映射了气相呋喃在紫外光激发后的环化开环反应。通过直接成像瞬态碳骨架结构，该研究揭示了相关反应机制，解决了以往针对该原型系统广泛存在的矛盾预测与观察结果。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["表征技术[光化学开环反应]: 时间分辨库仑爆炸成像"]},{"i":39273,"as":"针对传统提锂方法耗时、耗资源且破坏环境的问题，研究人员提出了一种基于电渗析的直接从海水中提取碳酸锂的方法。该方法将固体锂离子传导膜与锂-空气化学相结合，以环境中的二氧化碳为碳源，无需添加额外的沉淀剂，即可在单一步骤中实现锂的富集和碳酸盐的形成。这种锂-空气配置通过热力学驱动的置换反应赋予了系统固有的离子选择性，为可持续的锂资源提取提供了新策略。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":5.0,"t":6.0},"kp":["提取方法[海水提锂]: 受锂-空气化学启发的电渗析法","产物[海水提锂]: 碳酸锂","碳源[碳酸锂提取]: 环境二氧化碳"]},{"i":39274,"as":"受墨鱼骨壁隔结构启发，研究人员利用逐层冷冻技术开发了一种轻质蜂窝状环氧树脂材料。在密度为0.55 g cm−3的条件下，该材料展现出高达34.5 J g−1的特定能量吸收率和高抗压强度。其多孔壁层之间的致密隔板增强了结构稳定性，有效抵抗屈曲并在压缩过程中提供横向约束。这种结构还显著提升了高应变率下的抗冲击强度，动态性能分别提升了190%和66%，成功打破了材料密度与能量耗散之间的权衡限制。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["比能量吸收[墨鱼骨启发蜂窝材料]: 34.5 J/g","制造工艺[轻质蜂窝环氧树脂]: 逐层冷冻技术"]},{"i":39275,"as":"为解决现有黑盒模型缺乏人类可解释推理的问题，本研究为自主系统提出了一种具身认知驱动的轨迹预测分层框架。该框架集成了用于威胁优先级排序的场景注意机制、基于社会影响理论的意图推断图，以及符合物理规律的社会力模型。实验表明，在ETH和UCY数据集上，平均位移误差和最终位移误差分别降低了42%和40%，同时实现了0.003秒的近实时推理，显著提升了密集交通环境下的模型可解释性与预测精度。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["轨迹预测范式[自主系统]: 具身认知驱动","层级框架组成[可解释轨迹预测]: 场景注意力机制、社会影响理论驱动图、物理模型"]},{"i":39276,"as":"高体积分数的稳定乳液体系在食品、化妆品等行业中至关重要，其生产过程涉及高剪切流、弹性及空间相互作用下的液滴聚结与破碎。研究探讨了乳液内部多种复杂相互作用对微观液滴形态和宏观流变特性的决定性作用。研究指出，当达到临界体积分数时，乳液会失去稳定性，发生一种流体组分相互交换角色的极速过程，即灾难性相变。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["分散相特征[稳定浓缩乳液]: 高体积分数液滴","稳定机制[浓缩乳液]: 空间相互作用","动力学行为[流动浓缩乳液]: 非互易聚结破碎"]},{"i":39277,"as":"细胞内（主要由中性脂质组成的脂滴）的低极性环境对超分子组装的调节作用尚不明确。研究证实，三油酸甘油酯可作为动力学控制超分子聚合的有效介质。一种基于丙氨酸的二酰胺功能化荧光团在三油酸甘油酯中，通过“成核-生长”机制形成超分子聚合物。尽管其热力学稳定性与常规溶剂相似，但该过程揭示了中性脂质环境在调控细胞内超分子聚合反应路径中的关键作用。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["组装介质[细胞内超分子聚合]: 三油酸甘油酯（中性脂质）","聚合调控方式[中性脂质环境]: 动力学控制"]},{"i":39278,"as":"研究人员在室温下成功实现了一种抗磁悬浮毫米级宏观转子的自由旋转。该转子在轴对称永磁体陷阱中稳定悬浮，并能在高真空中通过非接触式静电驱动达到930 RPM的转速。其测量的耗散率极低，仅为3.85 μHz，对应自由旋转时间超过10小时。利用该转子的低阻尼率和大角动量，研究实现了一种高精度陀螺仪，其测量灵敏度达到6.5 × 10−3 °/s，估计的极限热稳定性为5.7×10^-7°/h。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":8.0,"t":7.0},"kp":["耗散率[悬浮宏观转子]: 3.85 μHz","自由旋转时长[室温下悬浮宏观转子]: 超过10小时","转子尺寸[低耗散悬浮转子]: 毫米级","悬浮机制[宏观转子]: 抗磁性悬浮"]},{"i":39279,"as":"评估全球重点企业的生物多样性保护承诺，探讨企业在自然生态保护中的责任与实际表现。","scd":{"b":2.0,"i":3.0,"r":4.0,"d":2.0,"t":4.0},"kp":[]},{"i":39280,"as":"通过打破鲁德尔斯登-波普尔铁电材料的对称性，研究人员成功制备出一种具有高可调谐性和低损耗的平面外介电材料。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["制备策略[鲁德尔斯登-波普尔铁电体]: 打破材料对称性","介电性能[平面外介电材料]: 高可调谐性与低损耗"]},{"i":39281,"as":"针对大官能团引起的空间位阻阻碍反应进行的难题，研究人员提出了一种空位约束策略，通过实现具有压缩金属键的催化剂深能级轨道离域来打破这一限制。以负载在缺陷型CeO2上的铋原子为例，构建了‘O4-Bi-Bi-O4’集成体。这种离域的深能级轨道展现出极强的穿透力，通过增强活性位点与底物之间的电荷转移过程，成功克服了大官能团带来的空间位阻效应。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["催化剂设计策略[打破空间位阻限制]: 空位约束策略结合压缩金属键","轨道特征[催化剂深层能级]: 离域的深层能级轨道"]},{"i":39282,"as":"研究揭示了儿茶酚胺神经元在清醒期间增强大脑皮层点火（与意识觉察密切相关的过程）的作用机制。化学遗传学实验表明，激活腹侧被盖区（VTA）的多巴胺神经元会增加视觉皮层（V1）刺激引发的扣带回前部（ACA）兴奋幅度，反之则抑制该活动。氯胺酮和异氟烷等常用麻醉剂会大幅降低V1到ACA的活动传播，证实了儿茶酚胺在调节不同意识状态下神经信号传播中的核心作用。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["神经元活动[睡眠与清醒状态]: 儿茶酚胺神经元在清醒时活性高于非快速眼动睡眠","皮质点火[儿茶酚胺激活]: 增强与意识觉醒相关的皮质点火过程"]},{"i":39283,"as":"为解决3D打印骨组织工程中光控释药分子设计的难题，研究人员开发了一种波长选择性染料（QC7CN）作为光响应‘染料墨水’。该染料在紫外光聚合打印过程中具有高透明度以保证稳定性，同时具备强大的第二近红外（NIR-II）吸收能力，可实现深层组织的光热响应。利用NIR-II光热驱动，该智能材料能够实现脉冲甲状旁腺激素（PTH）的时空控制释放，用于骨质疏松的骨修复治疗。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["光响应分子设计要求[3D打印光固化与深组织激活]: 需同时具备高紫外稳定性及强长波（近红外二区）吸收能力","治疗策略[NIR-II光热驱动]: 脉冲式释放PTH（甲状旁腺激素）用于骨质疏松骨修复"]},{"i":39284,"as":"","scd":null,"kp":[]},{"i":39285,"as":"该文分析了计算机芯片的发展历史及其相关的控制权竞赛，探讨了超越软件和加州企业家范畴的更广泛计算技术演变史。","scd":{"b":2.0,"i":2.0,"r":3.0,"d":2.0,"t":3.0},"kp":[]},{"i":39286,"as":"科技公司宣称其提供的服务能够识别由AI生成的写作内容，但实际应用中，这些检测软件在技术和质量上存在明显差异。","scd":{"b":3.0,"i":5.0,"r":4.0,"d":2.0,"t":5.0},"kp":[]},{"i":39287,"as":"该文分析了克隆羊多莉曾引发的社会关注与争议，指出其经历可以为当前关于生殖技术的讨论提供历史经验和借鉴。","scd":{"b":4.0,"i":2.0,"r":3.0,"d":2.0,"t":2.0},"kp":[]},{"i":39288,"as":"研究展示了通过设计主族化合物来实现通常与过渡金属相关的多电子转移化学。通过将锗与氧化还原活性配体配对，该分子能够在一个位点同时表现出电子供体和电子受体的行为，并精准引导两电子或四电子转移路径。这一设计原理为主族化学中构建更通用、储量丰富的氧活化及相关转化系统提供了简单有效的方法。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["转移路径[锗配体氧化还原协同体系]: 两电子或四电子转移途径","化学行为[主族锗化合物]: 在同一位点表现出给电子和受电子的双重行为","应用目标[主族化合物氧激活]: 构建储量丰富且多用途的催化系统"]},{"i":39289,"as":"基于自旋缺陷的量子显微镜凭借高灵敏度、高空间分辨率和优异的测量模态，在凝聚态物理前沿研究中取得了变革性进展。文章综述了扫描探针氮-空位（NV）量子传感研究的最新进展，及其在以纳米级空间分辨率研究新兴量子材料物理特性方面的应用。这种量子传感器因其量子力学特性，具备了传统经典传感器无法实现的功能。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["传感机制[量子材料扫描探针]: 基于自旋缺陷的量子显微镜","性能特征[量子自旋缺陷传感器]: 高灵敏度、高空間分辨率及多模态测量"]},{"i":39290,"as":"在氮化硼（BN）封装的双层石墨烯系统中观察到反常门控效应（如无效静电控制和强电阻磁滞）。研究使用双栅极动态可旋转范德华异质结构发现，决定这些反常效应的关键参数是两层BN之间的角度对齐，而非与石墨烯形成的莫尔超晶格。要在室温下观察到反常门控效应，两层BN之间的相关对齐角度需在约15°至45°之间，且没有表现出预期的60°周期性证据。","scd":{"b":7.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["反常门控效应起源[双层石墨烯/BN异质结构]: 取决于两层BN之间的角度对齐而非其他因素"]},{"i":39291,"as":"Kai Purnhagen和Justus Wesseler探讨了工程活体材料的市场准入瓶颈，指出必须对欧盟相关法律进行改革以完善对此类复合材料的监管。","scd":{"b":1.0,"i":2.0,"r":4.0,"d":2.0,"t":4.0},"kp":[]},{"i":39292,"as":"锂镧锆氧(LLZO)固态电解质的晶界处具有升高的电子电导率，是电池循环中锂金属成核的优先位点。研究表明，LLZO晶界带有离子内置电荷，锂空位在界面处积累并产生局部电势（20°C时为-0.15 V）。该电势改变了载流子分布，阻碍离子传输，并使电子电导率比块体提高30倍。这种不平衡在电池运行期间引发内部锂金属成核并加速性能衰减。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":7.0,"t":7.0},"kp":["短路耐受性限制因素[石榴石固态电解质]: 带电晶界引发的局部电子电导升高导致金属锂成核","微观机制[锂镧锆氧晶界]: 锂离子空位在界面聚集产生局部电子态"]},{"i":39293,"as":"研究团队成功构建了一种名为Tumbleweed(TW)的人工蛋白质分子马达。TW采用模块化设计策略，结合了具有明确性质的蛋白质以产生定向运动功能。该马达包含三个“腿”，每个腿都带有配体门控的DNA结合域，能够与DNA轨道上的特定位点发生选择性相互作用，从而实现受外部控制的分子步进运动。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[人工蛋白质行走器]: 模块化设计且受外部控制的蛋白质马达(Tumbleweed)","[运动机制]: 配体驱动并沿着DNA轨道进行计时步进"]},{"i":39294,"as":"利用扫描隧道光谱技术，研究揭示了激子绝缘体Ta2Pd3Te5中杂质诱导的电子-空穴对断裂现象。单个碲空位会在激子能隙内产生一对光谱峰，其能量对缺陷构型高度敏感，且可通过针尖电场进行连续调节。光谱图显示了亚间隙态在空间上呈现各向异性，且电子-空穴组分在电子上相互耦合。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[Ta2Pd3Te5中的杂质激子对断裂]: 单个碲空位能够在激子能隙内产生一对光谱峰"]},{"i":39295,"as":"名为Tumbleweed的人工蛋白质行走器在DNA轨道上展示了配体驱动的步进行为。这一成果标志着合成生物学在迈向模块化、定制设计自主运动蛋白方面取得了关键进展。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[人工蛋白质行走器(Tumbleweed)]: 在DNA轨道上表现出配体驱动的步进运动，标志着向模块化、定制设计的自主运动蛋白迈进"]},{"i":39296,"as":"研究通过克服四个关键的递送瓶颈，成功利用脂质纳米颗粒(LNP)实现了在小鼠体内的高效、安全且具有治愈效果的引物编辑。这项工作提供了一种非病毒的引物编辑递送途径。","scd":{"b":8.5,"i":4.0,"r":6.0,"d":5.0,"t":7.0},"kp":["递送途径[实现小鼠治疗性体内引物编辑]: 脂质纳米颗粒的非病毒递送途径","[体内引物编辑]: 解决四个递送瓶颈实现高效且安全的编辑"]},{"i":39297,"as":"提出不对称光催化中的中继策略，突破传统Dexter能量转移的距离限制，优化光化学反应。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":3.0,"t":6.0},"kp":["光催化策略[不对称光催化]: 中继策略","[中继策略]: 突破传统Dexter能量转移的距离限制并优化光化学反应"]},{"i":39298,"as":"预测中国未来地下水压力趋势，指出当前措施不足，需采取更严格的气候适应与水资源管理策略。","scd":{"b":3.0,"i":2.0,"r":6.0,"d":3.0,"t":5.0},"kp":["[中国未来地下水压力趋势]: 当前措施不足，需采取更严格的气候适应与水资源管理策略"]},{"i":39299,"as":"马凡综合征(MFS)主动脉疾病的上游机制被发现。研究指出，由多聚蛋白聚集驱动的纤连蛋白(FN)积累会激活αVβ3-PI3K-PIP3-PDK1-ILK信号级联反应，导致AKT-NOS2上调和主动脉疾病。破坏FN组装或抑制该信号通路（如抑制αVβ3、PI3K、PDK1或ILK）可有效阻止FN诱导的AKT激活和NOS2上调，恢复血管收缩力，并限制MFS小鼠的主动脉扩张。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["致病上游机制[马凡综合征主动脉疾病]: 多聚糖驱动的纤连蛋白积累激活αVβ3-PI3K-PIP3-PDK1-ILK信号级联","下游病理机制[马凡综合征主动脉疾病]: AKT-NOS2表达上调"]},{"i":39300,"as":"研究提出了一种基于呼吸热量型金属有机框架的气体响应热能存储(TES)解决方案。以MOF-508b为例，在等压条件下，通过将周围CO2压力从5 bar调节至25 bar，其相变温度可在-30°C至120°C（243K至393K）范围内进行宽泛调节。该方法使得单一材料能够在不同环境条件下动态调整充放电温度，无需使用多种TES材料。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[相变材料热能存储系统]: 通过气体响应型金属有机框架实现充放电温度(Tcharge, Tdischarge)的动态可调性，以适应不同环境条件"]},{"i":39301,"as":"研究报道了一种用于大型碱性水电解槽(AWE)的时间电位诱导调节方法。在不改变催化剂和电解槽结构的前提下，该方法通过优化供电策略显著延长了AWE在功率波动条件下的使用寿命。该工作将电气工程与电化学相结合，为可再生能源整合到氢能基础设施中提供了可规模化且有效的途径。","scd":{"b":7.0,"i":6.0,"r":7.0,"d":7.0,"t":8.0},"kp":["[大型碱性水电解槽(AWE)]: 时间电位诱导调节方法无需改变催化剂和电解槽结构即可通过优化电源延长其使用寿命"]},{"i":39302,"as":"利用振动探针技术，监测聚合物电化学掺杂过程，揭示极化子与阴离子之间的相互作用机制。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":3.0,"t":6.0},"kp":["[聚合物电化学掺杂过程]: 利用振动探针技术揭示极化子与阴离子之间的相互作用机制"]},{"i":39303,"as":"研究发现，在保持纳米颗粒尺寸和电子态相似的情况下，优化铂纳米颗粒密度可显著增强其内在催化活性。在环己烷催化脱氢反应中，调节Pt纳米颗粒密度使Pt效率提高了9.6倍，实现了24,217 molC6H6 molPt-1 h-1的苯生成速率，优于现有催化剂。该密度优化催化剂在连续800小时的测试中保持了良好的耐久性。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":8.0,"t":7.0},"kp":["铂纳米颗粒效率[环己烷催化脱氢]: 提高9.6倍","苯生成速率[环己烷催化脱氢]: 24217 molC6H6 molPt-1 h-1","[催化活性增强机制]: 在保持颗粒尺寸和电子态相似的情况下，优化铂纳米颗粒的密度"]},{"i":39304,"as":"研究首次发现了由极性原子层堆叠而成的二维范德华极性金属MoOBr2。单晶X射线衍射和原子分辨率扫描透射电子显微镜表明，MoOBr2结晶于非中心对称空间群C2，其极性源于不对称的[MoO2Br4]八面体。该材料结合了长程极性有序和金属导电性，展现出非互易电荷传输和非线性光学效应等特性。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[二维范德华极性金属MoOBr2]: 具有长程极性有序与金属导电性，表现出非互易电荷传输和非线性光学效应"]},{"i":39305,"as":"研究开发了一类荧光原报告基因，用于在活细胞中对特定亚细胞区室（包括线粒体、溶酶体、内质网和高尔基体）内的酶活性进行时空分辨率成像。这些报告基因由罗丹醇荧光团组成，其荧光被酶特异性底物和生物正交笼蔽基团淬灭，只有在特定酶的存在下信号才会恢复，从而实现细胞器水平的酶活性精确成像。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[活细胞亚细胞酶活性成像]: 工程细胞器门控报告基因可在特定亚细胞区室中实现时空分辨的酶活性成像"]},{"i":39306,"as":"研究揭示了在高熵金属有机框架中，金属异质性会在三核二级结构单元(SBU)内引起明确的、依赖于成分的构型扭曲。这些扭曲相干传播，产生可测量的晶格级别结构变化。通过使用拓扑结构保守的TCPP框架，并在单金属到五金属组分中改变金属种类，研究建立了金属种类、局部配位几何与晶格响应之间的定量关系。","scd":{"b":8.5,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[高熵金属有机框架中的金属异质性]: 诱导了明确的局部配位不对称性，并定义其体相结构行为"]},{"i":39307,"as":"该文章综述了原位和操作工况下的光谱及电化学工具，作为氧化还原液流电池(RFB)、氧化还原靶向和电化学CO2捕获系统的机械诊断工具箱的最新进展。重点介绍了UV-vis-NIR、NMR/EPR、振动光谱、X射线技术、荧光显微镜、中子成像和扫描电化学显微镜(SECM)等先进技术，用于精确解析电解质形态、传输过程及系统演化。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":4.0},"kp":["体系特性[氧化还原液流电池]: 具有内在不燃性和能量与功率解耦架构","[长时储能系统]: 需要精确且状态可分辨的诊断方法以应对多小时运行和数十年寿命的挑战"]},{"i":39308,"as":"研究采用形状伪装导向(SCG)策略解决了低密度超晶格组装的挑战。通过在纳米颗粒上外延生长牺牲壳层，解耦了晶格对称性与核心形态。壳层定义的有效几何结构指导组装，并在移除壳层后转化为目标非密集结构。选择性地蚀刻壳层留下了由直接颗粒间接触稳定的自支撑三维框架，成功避免了传统方法中常见的结构坍塌。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[低密度超晶格组装]: 采用形状伪装引导(SCG)策略，利用形状熵和耗尽熵成功制备开放型低密度超晶格"]},{"i":39309,"as":"研究提出了一种利用α螺旋肽支架调节分子内质子耦合电子转移(PCET)的仿生策略。将罗丹明染料接枝到设计的肽骨架上形成明确的α螺旋结构，该结构提供了与PCET过程中的质子转移路径一致的固有偶极场。光谱、电化学和理论分析表明，α螺旋的偶极场能够显著加速PCET过程，其性能优于非螺旋的小分子和聚合物类似物。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["调控机制[分子内质子耦合电子转移]: 仿生α螺旋肽支架提供固有偶极场实现加速定向转移","支架特征[罗丹明染料嫁接肽骨架]: 构建具有明确α螺旋结构的Pep-Rh"]},{"i":39310,"as":"研究利用掺铈(Ce3+)的CaS纳米晶体成功演示了光学检测磁共振(ODMR)，实现了直接的自旋-光学界面。CaS宿主具备高对称性、低磁噪声、红移光致发光光谱以及进一步功能化的开放性。该系统通过圆偏振光激发直接将角动量注入自旋载流子，为在化学体系中实现自旋极化和读出提供了新的途径。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["自旋极化与读取手段[自旋-光学界面化学体系]: 圆偏振光激发直接注入角动量","材料体系[实现直接自旋光学界面通用性]: CaS:Ce3+纳米晶体"]},{"i":39311,"as":"研究合成了两种含有六[7]环烯核心的负曲率手性纳米石墨烯(1和2)。在结晶状态下，两者均形成双层结构，并分别采取重叠和位移构象。这种双层堆叠由层间π-π和C-H···π相互作用驱动。核磁共振研究证实了化合物1在溶液中具有明确的双层结构。循环伏安法测量证明了双层结构中存在层间耦合，并使用圆二色性光谱研究了手性异构体的反转行为。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["核心结构[双层纳米石墨烯]: 六苯并[7]环烯为核心构建负曲手性结构","晶体构象[结晶态双层堆叠]: 呈现重叠式和位移式构象"]},{"i":39312,"as":"深入分析Ir基催化剂的机理，实现胺-硼烷的受控脱氢聚合反应，推动新型高分子材料合成。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["催化剂[胺-硼烷受控脱氢聚合]: Ir(tBu-POCOP)H2","[胺-硼烷脱氢聚合]: 基于对铱基催化剂机理的深入分析实现受控反应，推动新型高分子材料合成"]},{"i":39313,"as":"研究使用苯酚和苯乙酮等极性芳香族无卤溶剂作为重结晶溶剂，成功生长出毫米级的Y6非富勒烯受体(NFA)单晶。该晶体表现出比以往任何Y6晶体更致密的新型结构。通过功率依赖性荧光和荧光显微镜技术，证实了其增强的激子扩散长度（70±15 nm）以及优异的新型光物理特性。该结晶技术同样适用于其他NFA分子。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["晶体尺寸[非富勒烯电子受体Y6]: 毫米级（通过极性无卤芳香溶剂重结晶生长）"]},{"i":39314,"as":"通过第一性原理计算，研究揭示了卤化物钙钛矿Cs4Au3Cl12中非常规氧化态Au2+的稳定机制。稳定化是通过形成极化子晶体实现的。其键合网络可视为[Au2+Cl4]2-和[Au3+Cl4]1-平面正方形基元的集合。由于晶格中缺乏平滑的歧化路径，且Au的电子态被局域在每个AuCl4基元内部，使得Au2+状态能够在体相中稳定存在而不发生歧化。","scd":{"b":8.5,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["稳定机制[卤化物钙钛矿Cs4Au3Cl12体相中Au2+]: 极化子晶体的形成","价态特征[晶体中的金离子]: 突破常规稳定于非常规的+2氧化态"]},{"i":39315,"as":"研究开发了一种光诱导的钯催化烯丙基Heck反应，实现了烯丙基亲电试剂与烯烃的直接偶联，生成密集功能化的跳跃二烯和共轭二烯。该转化通过混合型的钯-烯丙基自由基中间体进行，不仅保证了高效的区域选择性C-C键形成，还展现出广泛的底物范围和优异的官能团耐受性，为复杂1,4-和1,3-二烯的合成提供了通用平台。","scd":{"b":7.5,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["反应特征[光诱导钯催化烯丙基Heck反应]: 经历混合型钯-烯丙基自由基中间体","产物选择性[烯丙基电亲核试剂与烯烃直接偶联]: 高区域选择性地形成跳跃二烯和共轭二烯"]},{"i":39316,"as":"报道了首个交流电驱动的电化学氢同位素交换（HIE）方案，成功实现了环状和非环状脂肪胺底物的有效氘（D）标记。该技术克服了传统α-氨基自由基不稳定且易过度氧化的应用障碍。其核心创新在于使用1,3-丙二硫醇作为氢原子转移（HAT）催化剂，该催化剂能够通过交流电原位生成强效的HAT试剂——巯基硫自由基。该成果为医药行业中含烷基胺类药物的药代动力学和药效学研究提供了同位素标记新方法。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":4.0,"t":7.0},"kp":["氢同位素交换试剂[交流电驱动脂肪胺C-H键标记]: 1,3-丙二硫醇作为高效氢原子转移试剂","技术突破[不稳定α-氨基自由基防过氧化]: 首次实现交流电驱动的电化学氢同位素交换"]},{"i":39317,"as":"报道了一种工程化的依赖硫胺素二磷酸的自由基酶，用于催化两个亲电C(sp3)前体发生氧化还原中性且立体发散的交叉偶联。该反应通过光加速的单电子转移，从未知的酶促乙烯基Breslow中间体中产生两个不同的前手性自由基，并实现立体选择性重组形成C(sp3)-C(sp3)键。通过蛋白质工程开发出四种酶变体，能够以高效率（产率高达82%、对映体过量99%和非对映异构体比>20:1）提供全部四种立体异构体。","scd":{"b":9.0,"i":3.0,"r":6.0,"d":4.0,"t":7.0},"kp":["催化特征[苯甲酰甲酸脱羧酶]: 硫胺素依赖性且受光加速","反应机制[前手性自由基C(sp3)-C(sp3)键构建]: 酶促乙烯基Breslow中间体发生单电子转移产生两个不同前手性自由基","反应特性[双亲电前体氧化还原中性交叉偶联]: 立体发散性"]},{"i":39318,"as":"直接证明了黄素在光激发下发生质子化位点转换的现象。此前研究仅通过计算预测光激发会使三环芳香黄素环的优先质子化位点转移至对侧，但一直缺乏实验证据。研究人员结合低温离子阱红外光谱和受控水分子微溶剂化技术，以质子化光黄素为典型模型，证实了S1 ← S0光激发触发了质子化位点的转换。这一结果为黄素作为可见光光感受器的光反应机制提供了直接的实验确证。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":3.0,"t":6.0},"kp":["机制确认[黄素光反应性起源]: 直接实验证明光诱导质子化位点转换至三环芳香环对侧","激发响应[可见光光受体]: 光激发改变首选质子化位点"]},{"i":39319,"as":"","scd":null,"kp":[]},{"i":39320,"as":"","scd":null,"kp":[]},{"i":39321,"as":"","scd":null,"kp":[]},{"i":39322,"as":"","scd":null,"kp":[]},{"i":39323,"as":"","scd":null,"kp":[]},{"i":39324,"as":"","scd":null,"kp":[]},{"i":39325,"as":"通过重建加拿大东部北方森林长达204年的火灾历史，揭示了火灾燃料负反馈的空间特征。研究发现，大火内部区域（距离边缘大于8公里）在短时间内再次燃烧的可能性远低于边缘区域（距离边缘小于2公里），表明大火内部的负反馈机制得到了强化。这种由火灾引起的生物量减少有效限制了早期植被恢复期间的重新燃烧，尽管气候变暖导致火灾活动增加，但燃料的空间配置对火灾复发间隔仍具有显著的缓冲作用。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["反馈机制[火灾后早期植被恢复]: 火灾导致的生物量减少限制了再次燃烧的可能性，形成负反馈"]},{"i":39326,"as":"结合鸡胚模型、全肠三维成像和短间隔的单核转录组学，对早期肠神经元亚型的出现进行了时间分辨形态学和转录组学分析。成像结果显示轴突网络生长具有高度动态性，其密度迅速增加且空间方向呈现多样化。转录组层面将这些形态变化与特定轴突导向基因集的细胞状态转变相关联。跨物种分析揭示了人类、小鼠和鸡胚胎在肠道细胞谱系轨迹和特定亚型的轴突导向程序上具有全球保守性。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[雏鸡早期肠神经元]: 结合全肠三维成像与单核转录组学进行时间分辨分析","轴突网络生长[成像观察]: 具高动态性，伴随轴突密度快速增加和空间取向多样化"]},{"i":39327,"as":"利用遥感地表温度和物种分布图，研究了热带树种接近阻碍光合作用的关键温度阈值的程度。研究重点考察了热安全裕度（TSM，即临界光合作用温度与最高冠层温度之间的差值）的时空变化。在全球热浪愈发严重和频繁的背景下，该研究量化了热带森林面临的临界温度暴露风险，揭示了热带森林树种在高温环境下维持光合作用活动所面临的挑战与风险极限。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["热安全裕度(TSM)[热带树种]: 叶面温度与阻碍光合作用的临界温度阈值之差"]},{"i":39328,"as":"揭示了真核生物基因调控中通过不变非平衡动力学优化信息流的机制。基因调控依赖于基因在转录活跃和非活跃状态之间的随机切换。尽管过程复杂，但“切换相关时间”（即启动子活性波动自相关函数的特征衰减时间）在不同基因表达水平下表现出惊人的不变性。研究证明，这种经验约束对最小转录调控模型提出了严格要求，为基于非平衡动力学优化基因表达信息流的物理机制提供了生物物理学解释。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["开关相关时间(TC)[真核生物基因调控的启动子切换]: 在不同基因表达水平间呈现不变性"]},{"i":39329,"as":"论文撤回声明：撤回关于衰老大脑中脑膜淋巴结构变化的神经科学研究内容。","scd":{"b":4.0,"i":1.0,"r":6.0,"d":2.0,"t":5.0},"kp":[]},{"i":39330,"as":"展示了一种通过4D力学模式空间控制血管生成的新技术。研究开发了磁驱动的人体血管芯片平台，将可灌注的内皮微通道整合至胶原蛋白基质中，能在三维空间和时间（4D）上进行无创且可调的机械刺激。利用自动3轴驱动器，系统研究了动态图案化机械力如何实现对血管出芽的精确时空控制。该方法克服了传统生化生长因子递送难以实现持续时空控制的局限，为组织工程构建有组织的微血管网络提供了新途径。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[微血管网络构建]: 开发磁驱动水凝胶平台实现动态力模式，对血管生成出芽进行精确的时空控制"]},{"i":39331,"as":"提出了一种碱性热处理（ATT）技术，可直接从混合塑料废物（包括PET、PE和PP）中高效制取绿氢。与传统气化相比，NaOH辅助的碱性热处理能够在低温和常压下分解塑料，免除了传统回收中繁琐的预分拣步骤。该技术在显著降低分解温度的同时，能产生高纯度氢气并最小化碳排放，结合其固有的碳储存能力，为混合塑料废弃物的化学回收和清洁能源转化提供了高效低成本的策略。","scd":{"b":7.0,"i":4.0,"r":8.0,"d":7.0,"t":7.0},"kp":["化学回收策略[混合塑料废物(包含PET、PE等)]: 碱性热处理","技术优势[混合塑料废物]: 免除预分选要求，降低处理难度与成本"]},{"i":39332,"as":"通过将物理一致的损伤力学引入冰盖模型，评估了裂缝对南极西部冰损失的物理影响。针对目前南极质量损失最大的阿蒙森海海湾，模型准确再现了当前卫星观测到的损伤模式。模拟预测至2300年时，允许裂缝损伤动态演化会显著放大未来的冰损失，使海平面上升贡献量增加高达约4.5倍。即使损伤程度保持在当前固定水平，冰架对冰流的稳定支撑作用也因裂缝驱动的减弱而遭到破坏。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[南极西部冰盖质量损失预测]: 将物理一致的损伤力学纳入冰盖模型中，模拟裂缝形成降低冰粘度并加速冰排放"]},{"i":39333,"as":"结合高分辨率原位转录组学、组织学、蛋白质组学和功能检测，绘制了小鼠出生后第3天至第21天子宫发育的空间转录组图谱。该研究确定了所有主要子宫细胞类型的时间出现和空间排列，证明了子宫内膜腺体是通过渐进式转录重编程起源于腔上皮，而非预定的祖细胞群。空间分析揭示了子宫发育过程中上皮细胞分化、腺体形成和基质组织在空间转录程序上的精确整合机制。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[小鼠产后子宫发育]: 绘制出生后第3天至第21天的空间转录组图谱"]},{"i":39334,"as":"鉴定出一种在链霉菌中起下调作用的信号分子——烷基恶唑（AOX）。与链霉菌中大多数来源于γ-丁内酯（GBL）合成酶的上调诱导因子不同，AOX在生物合成上具有独特性，能够下调链霉菌的孢子形成和抗生素生产。其分子结构特征为包含一个恶唑头部并侧接一个烷基尾部。这一发现填补了链霉菌中非典型且具负调控作用的信号分子研究空白。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["信号分子[链霉菌形态发育与次级代谢下调]: 烷基恶唑"]},{"i":39335,"as":"","scd":null,"kp":[]},{"i":39336,"as":"确定了组蛋白伴侣HIRA作为脂肪组织功能的表观基因组调节因子。在小鼠中特异性敲除脂肪组织中的Hira基因，会损害胰岛素敏感性并抑制高脂饮食诱导的肥胖过程中的脂肪扩张。机制上，HIRA是编码脂联素的Adipoq基因及脂质代谢基因表达的必需条件。基因组图谱显示，HIRA结合在Adipoq和脂质代谢基因的启动子和增强子上，通过促进RNA聚合酶II（Pol II）的暂停释放来调节基因转录表达。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[脂肪组织特异性敲除Hira基因(小鼠)]: 损害胰岛素敏感性并抑制高脂饮食诱导肥胖过程中的脂肪扩张","[机制-HIRA]: 促进RNA聚合酶II(Pol II)暂停释放以调节脂联素表达"]},{"i":39337,"as":"","scd":null,"kp":[]},{"i":39338,"as":"名为MZ-8的磁驱动微型机器人系统用于根除生物膜并促进组织再生。该系统采用受脊柱启发的结构进行机械破坏，表面涂有pH响应的ZIF-8涂层以释放免疫调节的锌离子（Zn2+），并在第二近红外荧光引导下进行闭环驱动。在大鼠假体周围关节感染模型中，MZ-8成功清除了生物膜，并通过将巨噬细胞极化为M2表型诱导了促进再生的免疫反应。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["微型机器人系统[MZ-8]: 集成实时人工导航与微环境响应自主治疗功能以根除生物膜","涂层材料[生物膜微环境响应与免疫调节]: pH响应型ZIF-8（释放Zn）"]},{"i":39339,"as":"癌细胞在面临氧化应激时，通过应激颗粒（SGs）选择性抑制CD63+细胞外囊泡（EV）的释放，以协调细胞间信号传导与存活所需的胞内程序。临床化合物YM155能够有效抑制多种肿瘤细胞的CD63+ EV分泌。其机制是YM155迅速使抗氧化转录因子FOXO3a失活，降低关键解毒酶的表达，导致应激颗粒延迟但持续地积累。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[氧化应激下癌症细胞]: 应激颗粒(SGs)作为RNA分类中心选择性抑制CD63+细胞外囊泡(EV)的释放","[临床化合物YM155]: 具有调控相关应激-适应性机制的作用"]},{"i":39340,"as":"约2.52亿年前的二叠纪末期，全球气候剧变引发了地球史上最大规模的动物群演替。随着海水变暖、缺氧和酸化，以腕足动物为代表的古生代动物群大量灭绝，而以双壳类为代表的现代动物群趁机崛起。研究表明，动物对环境变暖的生理耐受性差异是决定其灭绝选择性的核心机制。基于代谢需氧量模型的推演及呼吸实验证实，不同物种在应对温度依赖性缺氧时的耐受能力差异，直接导致了这一生物大灭绝期间不同分类群截然不同的存活命运。","scd":{"b":4.0,"i":1.0,"r":5.0,"d":6.0,"t":3.0},"kp":["[二叠纪末期海洋变暖与缺氧酸化]: 古生代动物群(如腕足动物和海百合)灭绝率显著升高","[二叠纪-三叠纪过渡期]: 现代动物群(如双壳类和腹足类)崛起并取得生态优势"]},{"i":39341,"as":"编码GCN2的基因发生双等位基因突变会导致肺静脉闭塞病（PVOD），这是一种致命的肺动脉高压。为研究GCN2缺乏导致肺血管病变的机制，研究人员开发了两种小鼠模型：一种是通过基因消融Gcn2模拟基因突变阳性的PVOD，另一种是使用丝裂霉素C构建的药物模型。通过对野生型和Gcn2缺陷小鼠的肺部进行单细胞RNA测序分析，证实白细胞介素-6（IL-6）在Gcn2缺陷小鼠肺血管疾病的发展中具有关键作用。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":5.0,"t":6.0},"kp":["致病基因[肺静脉闭塞病(PVOD)]: EIF2AK4基因(编码GCN2)的双等位基因突变","[肺血管病理发生机制]: 白细胞介素-6(IL-6)在Gcn2缺陷小鼠的疾病发展中起至关重要作用"]},{"i":39342,"as":"波形蛋白中间丝在维持细胞完整性和调节依赖肌动蛋白动力学的细胞过程（如迁移、分裂和机械感知）中发挥重要作用。利用体外重构、理论建模和全内反射荧光显微镜技术，研究证实了波形蛋白与肌动蛋白之间存在直接的蛋白质-蛋白质相互作用。波形蛋白通过直接结合并稳定倒刺末端的ATP-肌动蛋白亚基来促进肌动蛋白的组装。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":6.0,"t":6.0},"kp":["作用机制[波形蛋白调节细胞骨架]: 通过稳定倒刺末端的ATP-肌动蛋白亚基来促进肌动蛋白组装"]},{"i":39343,"as":"通过联合反演近断层强地面运动、大地测量和远震数据，确定了2025年缅甸MW 7.7级地震的详细破裂过程。破裂在震中附近启动，最大滑移量约5米。局部的断层几何复杂性和应力非均匀性导致了小规模的滑移分段和间歇性的超剪切破裂。向北的破裂以亚剪切速度为主，延伸约80公里后迅速停止；而向南的破裂延伸了约380公里，穿越了自1839年以来未破裂的地震空区。","scd":{"b":8.5,"i":5.0,"r":8.0,"d":8.0,"t":8.0},"kp":["最大同震滑动量[2025年缅甸7.7级地震震中附近]: 约5米","破裂特征[局部断层几何复杂性与应力非均质性]: 介导了小尺度滑动分段与间歇性超剪切破裂"]},{"i":39344,"as":"昆虫是否具备情感评估能力此前一直未有明确的行为学标记。研究发现，大黄蜂会表现出与哺乳动物在功能上类似的离散口面部反应。在摄入奖励性溶液后，大黄蜂会吐出舌头（舌突）；而在接触到厌恶的味道时，它们会摇头并擦拭嘴部。这些口面部反应为昆虫具有情感评估能力提供了直接的行为学证据。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":4.0,"t":6.0},"kp":["[昆虫情感状态评估]: 大黄蜂的口面部味觉反应(如对甜味的伸舌反应)可作为其正面享乐影响的可靠行为标记"]},{"i":39345,"as":"","scd":null,"kp":[]},{"i":39346,"as":"","scd":null,"kp":[]},{"i":39347,"as":"","scd":null,"kp":[]},{"i":39348,"as":"强调小型水体在全球碳循环中的关键作用，指出其在碳储存和温室气体排放中的巨大生态影响。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":[]},{"i":39349,"as":"","scd":null,"kp":[]},{"i":39350,"as":"","scd":null,"kp":[]},{"i":39351,"as":"","scd":null,"kp":[]},{"i":39352,"as":"","scd":null,"kp":[]},{"i":39353,"as":"为控制疟疾传播，科学家开发了基于Cas9/guide RNA的基因驱动系统，旨在蚊群中传播抗寄生虫效应基因。在按蚊中测试了三种基因驱动品系（两种库蚊的AcTP13和AcTP43，以及一种冈比亚按蚊的AgTP13）。结果显示，这些携带自主基因驱动系统并连接多个抗寄生虫效应基因的品系，在整个实验期间表现出显著的长期稳定性，能够有效维持驱动和抑制寄生虫的特性。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["基因驱动策略[按蚊疟原虫传播控制]: 基于Cas9/guide RNA传播显性抗寄生虫效应基因"]},{"i":39354,"as":"人类JC多瘤病毒（JCPyV）会导致进行性多灶性白质脑病（PML）。PML患者体内的JCPyV常发生突变，特别是在病毒聚糖受体结合位点形成“抗体识别漏洞”，以逃避抗体反应。研究通过X射线晶体学，分析了从健康捐赠者和PML康复者体内分离出的JCPyV VP1特异性人源单克隆抗体。结构分析表明，在测试的四种单克隆抗体中，有三种能够通过表位扩展有效识别并结合多种PML相关的JCPyV突变株。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["抗体逃逸机制[PML患者JC多瘤病毒突变]: 聚集于病毒聚糖受体结合位点建立“抗体识别空洞”","结构表征方法[人中和抗体]: X射线晶体学"]},{"i":39355,"as":"科研人员提出了一种电可调的宇称-时间（PT）对称磁振子激光与反激光机制。该器件由位于磁性平面波导中的电流偏置区域构成。在偏置区域内，承载直流电荷电流的几根重金属线能够调控并产生磁激元的激射与相消干涉效应。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":8.0},"kp":["激光与反激光机制[PT对称磁振子]: 电流偏置区域内的重金属导线施加直流电荷电流实现电可调性"]},{"i":39356,"as":"在弓激波脉冲星风云（如吉他星云、灯塔星云等）附近观测到的X射线细丝结构，挑战了宇宙射线扩散的标准图景。研究探讨了磁化星际等离子体中相对论正负电子对光束的自约束机制。该物理机制成功解释了脉冲星X射线细丝的形成以及脉冲星周围慢扩散区域的存在。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":[]},{"i":39357,"as":"提出了一种精确测量轻过渡元素（原子序数23至30）绝对电四极矩的新方法。该方法基于对2s-2p流形（即兰姆位移）进行高精度的Muonic原子X射线光谱测量。通过这些精密的光谱学数据，提取并获得了过渡元素的参考四极矩。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":8.0},"kp":["测量方法[轻过渡元素绝对电四极矩(23≤Z≤30)]: 精密介子原子X射线光谱学(2s-2p流形/兰姆位移)"]},{"i":39358,"as":"基于手征有效场理论的真实核力，采用从头算价空间在介质相似重整化群方法，研究了N=Z核中rp-过程等待点核素（72Kr、68Se和64Ge）的β衰变特性。该研究详细探究了这些原子核的β衰变性质及核子配对效应。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":5.0,"t":8.0},"kp":[]},{"i":39359,"as":"探讨了稠密不对称核物质状态方程对核物质不可压缩性K的敏感性，并评估了其对中子星结构性质的影响。研究采用了六种相对论平均场模型以单独隔离不可压缩性K的影响。结果表明，核物质不可压缩性显著影响不对称系统的状态方程及中子星的宏观结构特征。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":6.0,"t":8.0},"kp":[]},{"i":39360,"as":"中子星内壳层中超流体中子比例的测定对于理解脉冲星自转频率突跳的角动量来源至关重要。研究首次采用完全自洽的Hartree-Fock-Bogoliubov方法，计算了超流体中子穿过核团簇周期晶格的流体流动。计算结果表明，超流体比例可达90%，这证实了内壳层能够提供足够的超流体角动量来驱动脉冲星突跳。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":5.0,"t":8.0},"kp":[]},{"i":39361,"as":"研究了使用杰斐逊实验室提出的SoLID（螺线管大强度）设备从氦-3（3He）靶测量半单举深度非弹性散射（SIDIS）非极化截面的预期物理影响。这类数据在大Bjorken xbj、中等Q2以及小横向动量转移条件下收集，对研究核子结构具有重要科学意义。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":6.0,"t":8.0},"kp":["横截面测量影响研究[3He目标SIDIS非极化]: 使用SoLID设备在大Bjorken x、中等Q²和小横向动量下收集数据"]},{"i":39362,"as":"研究了有限温度对介子-介子散射（即ππ和DD*或D*D散射）阈值尖点的影响。研究利用在有限温度下获得的生产率和传播子进行分析，揭示了温度变化对介子散射阈值附近线形和生产率的显著影响。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":5.0,"t":8.0},"kp":["散射阈值尖点温度效应[ππ和DD*介子散射]: 有限温度下利用产生率和传播子研究其对阈值尖点的影响"]},{"i":39363,"as":"光子对飞秒技术是研究高能核碰撞的重要工具。随着探测技术的进步和数据统计量的增加，克服了以往实验应用的局限性，研究详细论述了在一维、二维和三维几何下进行光子飞秒检查的原理和未来应用前景。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":8.0},"kp":["飞秒检查工具[高能核碰撞]: 光子对飞秒检查（1D、2D和3D）"]},{"i":39364,"as":"本研究利用具有动态势能表面的双核系统模型，调查了生成超重核297Og的重离子聚变反应中的中子-质子比平衡和核子转移动力学。通过研究一系列反应，揭示了复合系统形成过程中的核子转移与重新分配的物理机制。","scd":{"b":6.0,"i":1.0,"r":5.0,"d":6.0,"t":8.0},"kp":["超重核生成产物[N/Z平衡与核子转移动力学]: 生成超重核297Og","理论计算模型[双核系统]: 带有动态势能表面的双核系统模型(DNS-DyPES)"]},{"i":39365,"as":"本研究探讨了19F与100Mo重离子碰撞中的质子剥离传输通道。重离子碰撞中的核子转移反应对壳层结构、配对关联和集体激发高度敏感。该研究提供了检验和发展理论模型所需的重要实验数据，加深了对核结构和反应动力学的理解。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":6.0,"t":8.0},"kp":["核子转移反应[19F与100Mo相互作用]: 探测质子剥离传输通道"]},{"i":39366,"as":"利用微观核密度泛函理论获取哈密顿量参数，并在相互作用玻色子模型框架内，分析了Ra和Th同位素的八极关联对低能激发态和双中子转移强度的影响。研究证实了八极关联在决定锕系核素激发性质及中子对转移过程中的关键作用。","scd":{"b":6.0,"i":1.0,"r":3.0,"d":4.0,"t":8.0},"kp":["相互作用玻色子模型参数[Ra和Th同位素激发0+态]: 基于微观核密度泛函理论计算获取哈密顿量"]},{"i":39367,"as":"基于布鲁克纳-哈特里-福克(BHF)理论，开发了一种用于核子-核子散射的微观光学势(MOP)。该理论在描述对称和不对称核物质性质方面表现出高度成功。研究对微观光学势的能量和密度依赖性进行了参数化，为核反应计算提供了可靠的理论基础。","scd":{"b":5.0,"i":1.0,"r":3.0,"d":4.0,"t":8.0},"kp":["微观光学势(MOP)[核子-核子散射]: 基于布鲁克纳-哈特里-福克(BHF)理论开发","[BHF理论参数化]: 针对能量和密度依赖性进行参数化"]},{"i":39368,"as":"研究探索了重离子聚变激发函数的一种新表示方法。在适当的标度变换下，所有重离子聚变激发函数的σE实验谱表现为水平曲线。这些曲线在y轴上的位置对应于参数Rg的平方与Wg的乘积，其中Rg和Wg由单高斯势垒分布拟合得出。","scd":{"b":5.0,"i":1.0,"r":3.0,"d":5.0,"t":8.0},"kp":["标度拟合参数[重离子聚变激发函数]: Rg和Wg通过单高斯势垒分布拟合获得"]},{"i":39369,"as":"该研究通过使用12C和9Be的中子散射作为参考标准，精确测量了252Cf自发裂变产生的瞬发裂变中子能谱(PFNS)。PFNS反映了裂变释放中子的能量分布，数十年来一直被视为核物理中子数据的标准，对中子发射反应的测量至关重要。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":8.0},"kp":["标准参考测量[252Cf自发裂变]: 利用12C(n,n)和9Be(n,n)中子散射测量瞬发裂变中子能谱(PFNS)"]},{"i":39370,"as":"光核反应在基础与应用物理中扮演关键角色。13C(p,γ)14N反应可提供能量为9.17 MeV的准单能γ射线源。研究团队通过共振吸收法重新测定了14N中9.17 MeV能级的宽度，为解决光致裂变等相关光核数据中的分歧提供了有效途径。","scd":{"b":6.0,"i":1.0,"r":3.0,"d":5.0,"t":8.0},"kp":["准单能γ射线源[13C(p,γ)14N反应]: 能量为9.17 MeV","能级宽度测定[14N的9.17 MeV能级]: 采用共振吸收法重新测定"]},{"i":39371,"as":"采用连续介质中变形相对论Hartree-Bogoliubov理论(DRHBc)，系统研究了中子数在74到186之间的钬同位素的基态性质。研究发现在整个同位素链中存在显著的形变现象。相比于球形相对论连续Hartree-Bogoliubov理论，该模型能更精确地描述核形变演化。","scd":{"b":5.0,"i":1.0,"r":3.0,"d":4.0,"t":8.0},"kp":["同位素研究范围[钬同位素基态性质]: 中子数N=74–186","核形态演化特征[连续介质形变相对论Hartree-Bogoliubov理论]: 发现同位素链存在显著形变"]},{"i":39372,"as":"基于依赖于同位旋的Boltzmann-Uehling-Uhlenbeck输运模型，系统研究了重离子碰撞中核子-核子(NN)截面的介质效应。研究中使用了从Brueckner-Hartree-Fock理论推导出的微观截面，分析了这些介质效应对碰撞中核子和介子可观测量产生的具体影响。","scd":{"b":5.0,"i":1.0,"r":3.0,"d":4.0,"t":8.0},"kp":["核子-核子截面介质效应[重离子碰撞]: 基于BHF微观截面并利用IBUU输运模型系统研究其对核子和π介子可观测量的影响"]},{"i":39373,"as":"针对硅基光电阴极中金属修饰材料导致强光反射、阻碍底层硅光吸收的问题，研究人员设计出采用空间限制策略的高性能硅基光电阴极。铂助催化剂被限制在金字塔顶部的钛保护层作为催化活性位点，其余区域由二氧化硅覆盖以透光。该设计有效抑制了寄生光吸收，显著增强了光电化学制氢性能。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":7.0},"kp":["光电阴极设计[硅基光电化学制氢]: 采用空间限制策略，将Pt助催化剂限制于金字塔顶部的Ti保护层"]},{"i":39374,"as":"研究团队开发了一种超快等离子体纳米腔热循环仪(PNT)，用于护理点水平的直接实时逆转录PCR。该设备集成了由金、二氧化硅和金薄膜组成的纳米腔以及微型透镜阵列荧光摄像头。在白光LED照射下，PNT实现了20.4°C/s的加热速率和7.5°C/s的冷却速率，仅需269秒即可完成40个热循环。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["等离子体纳米腔结构[实时逆转录PCR热循环仪]: 聚集态Au、SiO2与Au薄膜","[护理点直接实时逆转录PCR]: 解决核酸提取缓慢与热循环受限的瓶颈"]},{"i":39375,"as":"研究揭示了等离子体诱导的界面电荷转移在表面增强拉曼光谱(SERS)和等离子体介导化学反应(PMCR)中的选择性路由机制。直接电子转移被证实为控制化学增强机制的核心过程，转移电子的数量和寿命是关键描述参数。SERS的化学增强机制与PMCR的化学界面衰减之间存在着相互竞争关系。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["[等离子体诱导界面电荷转移]: 揭示增强拉曼光谱与化学反应中等离子体界面电荷转移的选择性路由主导机制"]},{"i":39376,"as":"研究利用多齿氧化膦配体调节钙钛矿量子点的表面配位与电子耦合，以提升无机太阳能电池的光伏性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":7.0},"kp":["配体[钙钛矿量子点表面配位与电子耦合]: 多齿氧化膦配体"]},{"i":39377,"as":"针对天体物理X射线暴中的rp过程，最新模型指出59Cu(p,γ)60Zn和59Cu(p,α)56Ni反应之间的竞争会形成镍铜循环。本研究在放射性不稳定核素59Cu上进行了单核子转移反应实验，旨在探测和约束这一决定X射线暴中物质流动路径的关键NiCu循环的具体机制。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":7.0,"t":8.0},"kp":["反应路径[核心条件]: 59Cu(p,γ)60Zn 与 59Cu(p,α)56Ni 反应之间的竞争","天体物理过程[核心条件]: 形成镍铜循环并截留56Ni与60Zn之间的物质流"]},{"i":39378,"as":"研究计算了伴随轻子喷流产生的顶夸克对过程的高阶量子色动力学(QCD)修正。顶夸克是目前已知最重的基本粒子，该伴随产生过程是检验粒子物理标准模型的重要途径，对精确测定顶夸克质量以及寻找潜在的新物理信号具有极高的敏感度和关键作用。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":7.0,"t":8.0},"kp":["[研究对象]: 与喷射相关的顶夸克对产生的高阶QCD校正","[相关粒子]: 顶夸克对（已知最重的元素粒子）伴随轻喷流产生","[研究意义]: 是研究粒子物理标准模型属性的关键过程，对顶夸克质量具有相当的敏感性","[文献出处]: Phys. Rev. Lett. 137, 021901","[发布时间]: Mon Jul 06, 2026"]},{"i":39379,"as":"通过对引力波观测数据的深入分析，研究人员发现了存在一个由重复合并产生的巨大质量双黑洞独特群体的证据。GWTC-4引力波数据集中的分析结果表明，这些黑洞并非全部由恒星塌缩原生形成，其中包含了属于分层合并层级结构的特定黑洞亚群。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":8.0},"kp":["[引力波观测的不同分析结果]: 正在趋同于证明存在一个由重复并合产生的独特大质量双黑洞群体"]},{"i":39380,"as":"对引力波观测结果的不同分析汇聚成证据，表明宇宙中存在一个由反复合并形成的巨大质量双黑洞群体。该研究进一步在双黑洞合并事件中找到了基于不同原始质量划分出的三个不同亚群的证据，揭示了双黑洞系统的多样化起源。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":8.0},"kp":["发表期刊[文献标识]: Phys. Rev. Lett. 137, 021403","发表时间[出版日期]: Mon Jul 06, 2026"]},{"i":39381,"as":"研究计算了广义相对论中两个非自旋物体的保守径向作用量和散射角。计算精度达到了牛顿常数的第五阶(G^5)，并包含了二阶自力效应。研究在标度微扰理论框架下完成，成功实现了无自力截断的高精度散射振幅与保守二元动力学计算。","scd":{"b":9.0,"i":1.0,"r":9.0,"d":7.0,"t":8.0},"kp":["[计算精度(牛顿常数阶数)]: 精确到第五阶 (fifth order in Newton’s constant)","[计算精度(自力效应阶数)]: 包含二阶自力效应 (second-order self-force effects)","[物理系统条件(研究对象)]: 广义相对论中两个非自旋物体的保守径向作用量和散射角","[物理系统条件(自旋状态)]: 非自旋 (nonspinning bodies)"]},{"i":39382,"as":"研究对比了两个孤子玻色子星引力散射的有效单体解析描述与数值相对论模拟结果。通过分析固定能量并改变碰撞参数的四组模拟序列，解析模型成功整合了引力效应（质点与潮汐）以及短程标量场相互作用，实现了理论与数值计算的高度吻合。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":8.0},"kp":["分析对象[核心条件]: 两个玻色星（Solitonic Boson Stars）的引力散射","模拟序列参数[核心条件]: 固定能量并改变碰撞参数下的四组数值相对论模拟","分析方法[核心条件]: 结合引力效应（质点与潮汐）及短程标量场的有效单体解析描述与数值模拟的对比","期刊与期号[核心条件]: Phys. Rev. Lett. 137, 021401","发布时间[核心条件]: Mon Jul 06, 2026"]},{"i":39383,"as":"自由概率理论为描述希尔伯特空间遵循最大熵分布的复杂量子系统中非对易可观测量间的关联提供了框架。本研究检验了在该框架中引入最小偏差（即单个量子比特的耦合）时的鲁棒性，探讨了单一量子位如何影响和控制复杂系统自由度之间的相互作用。","scd":{"b":7.0,"i":2.0,"r":8.0,"d":5.0,"t":8.0},"kp":["[最大熵分布量子系统]: 自由概率框架描述非对易可观测量之间的关联","[复杂量子系统]: 最小偏差下（单量子位耦合）检验自由概率框架的鲁棒性"]},{"i":39384,"as":"ATLAS合作组利用质心能量为13 TeV的140 fb^-1质子-质子碰撞数据，结合矢量玻色子衰变道的测量结果，精确测量了希格斯玻色子与电弱规范玻色子相互作用的CP性质。该测量对验证希格斯玻色子是否为标准模型预言的标量玻色子及其CP破坏机制具有重要意义。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":8.0,"t":8.0},"kp":["质心能量[ATLAS探测器质子-质子碰撞]: 13 TeV","积分光度[ATLAS探测器质子-质子碰撞]: 140 fb⁻¹"]},{"i":39385,"as":"作者探讨了晶格模型中内部对称性是否可以“在位化”（onsiteable）。该概念指通过引入辅助量子比特并经过有限深度线路共轭操作，将对称性解纠缠为在位作用。传统观点认为，在位化等价于无反常，这一结论对有限0-形式对称性有效。该研究发表于《物理评论快报》。","scd":{"b":8.0,"i":1.0,"r":8.0,"d":5.0,"t":8.0},"kp":["[晶格模型内部对称性]: 通过引入辅助比特和有限深度电路共轭解耦为在位作用的能力"]},{"i":39386,"as":"研究提出一种在细胞水平上量化细菌动态的方法。通过将单个细菌捕获在微型液晶乳液液滴的拓扑缺陷上，实现细菌适应性的量化。该乳液液滴由向列相液晶和碳氟化合物组成，具有不对称的质量分布。细菌的主动运动会导致液滴陷阱发生倾斜和方位旋转，这一运动会受到作用在液滴重心上的重力的反向阻碍。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["细菌适应性量化[细胞水平]: 利用微尺度液晶乳液滴拓扑缺陷捕获单细胞","液晶乳液滴[组成与特性]: 向列液晶与碳氟化合物相分离，呈现不对称质量分布"]},{"i":39387,"as":"研究报道了室温生长的富铜非晶YBa2Cu3Ox (YBCO)薄膜器件中的新型电阻切换行为。在Nb:STO基底/YBCO薄膜(约200 nm)/Cu(15 nm)/Pt(15 nm)的结构中，通过改变沉积靶材及薄膜中的Cu含量，可以在YBCO/电极界面扩展区域机制和单点细丝机制之间实现电阻切换的调节。该技术在计算机内存和神经形态计算领域具有应用潜力。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":7.0,"t":4.0},"kp":["非晶薄膜厚度[室温生长富铜YBa2Cu3Ox]: ≈200 nm","金属层厚度[器件结构]: 金属Cu 15 nm / 金属Pt 15 nm","[阻变切换机制]: 室温生长非晶薄膜中可调谐的界面至丝状电阻切换"]},{"i":39388,"as":"研究开发了一种表面修饰有叶酸的交联二硒化物纳米囊泡(FA@cSeLAV)，用于治疗急性肝损伤。该纳米囊泡能够有效靶向肝巨噬细胞，将症状水平的活性氧(ROS)消除与内源性ROS产生的抑制无缝结合，解决现有疗法仅强调消除ROS而忽略抑制其内源性产生的问题，从而显著提升治疗效率。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[急性肝损伤治疗策略]: 利用交联二硒化物纳米囊泡实现活性氧消除与源抑制的无缝整合"]},{"i":39389,"as":"研究开发了一种由两个DNA四面体通过桥链连接构成的DNA纳米桥修饰的石墨烯场效应晶体管(g-FET)，用于综合监测呼吸道感染。目标病毒核酸的识别会触发桥链解离，释放探针检测炎症细胞因子IL-6。这种级联逻辑操作可同时检测病毒核酸和评估炎症反应，病毒核酸检测限低至3.9 × 10^-16 M。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["场效应晶体管[呼吸道感染综合评估]: 石墨烯场效应晶体管","DNA纳米桥结构[g-FET修饰]: 两个由桥连链连接的DNA四面体","[病毒核酸识别]: 触发桥连解离并执行级联操作逻辑"]},{"i":39390,"as":"针对纳米压印光刻(NIL)在工业规模化中面临的模具断裂、结构变形和脱模效率低等界面挑战，研究采用保形分子/原子层沉积(MLD/ALD)策略主动调节粘附、摩擦和应力演化。研究系统考察了MLD/ALD生长的石墨烯、Al2O3和聚脲作为NIL模具的模型界面层，并结合分子动力学模拟和有限元分析来优化界面力学性能。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[纳米压印光刻界面力学]: 采用仿真引导的原子层沉积构建确定性界面，协同控制粘附、摩擦与应力演变"]},{"i":39391,"as":"研究利用脉冲激光沉积技术在SrTiO3基底上制备了厚度为250 nm的无铅(BiFeO3)0.65Λ/(BaTiO3)0.35Λ超晶格。通过X射线衍射、原子力显微镜和扫描透射电子显微镜分析证实，薄膜具有纯相和良好的外延质量及纳米级化学调制。该巨界面应变梯度驱动了材料的自极化和零偏置压电特性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["薄膜厚度[BiFeO3/BaTiO3超晶格]: 250 nm","调制周期[(BiFeO3)0.65Λ/(BaTiO3)0.35Λ超晶格]: 24 ~ 195 Å","[无铅氧化物超晶格]: 巨界面应变梯度驱动的自极化与零偏置压电特性"]},{"i":39392,"as":"研究利用角度分辨表面增强拉曼散射(SERS)技术，揭示了在超高数值孔径激发下胶体超表面中低损耗混合等离子体-光子模式的色散与简并特性。通过模板辅助自组装技术制备了不同纳米颗粒浓度和晶格周期的超表面，证实了该模式对缺陷和周期性波动的鲁棒性，并发现了纳米颗粒浓度、结构有序度与场增强之间的直接相关性。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["数值孔径[超高通量激发]: ≈ 1.0 (空气)","检测技术[等离子体-光子模式探测]: 角度分辨SERS (通过独立扫描极化和方位角)"]},{"i":39393,"as":"为满足先进飞行器在极端环境下的隐身需求，研究通过前驱体衍生陶瓷(PDC)方法制备了一种多孔层状HfC陶瓷。该材料具备近3900°C的高熔点，通过凝胶冷冻干燥过程构建的多孔微观结构显著改善了HfC陶瓷的阻抗匹配问题，从而赋予其优异的耐高温性能和电磁波吸收能力。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["熔点[HfC陶瓷]: 近3900 °C"]},{"i":39394,"as":"针对柔性压电传感器在高压缩载荷下易产生响应饱和的问题，研究通过溶剂交换诱导自组装工艺制备了一种具有仿珍珠层分级界面结构的柔性压电复合薄膜。氧化石墨烯片层排列在压电陶瓷骨架和热塑性聚氨酯基体界面，构建了可承受兆帕级高压缩载荷的坚固结构，有效促进了应力传递和界面极化，实现了宽范围压力传感。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["制备工艺[柔性压电复合薄膜]: 溶剂交换诱导自组装"]},{"i":39395,"as":"开发基于微结构PVDF-HFP/TPU的离子凝胶材料，用于宽范围离子电子压力传感，涉及柔性可穿戴电子技术。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.5,"t":4.0},"kp":["材料体系[宽范围离子电子压力传感]: 微结构PVDF-HFP/TPU离子凝胶"]},{"i":39396,"as":"研究提出将二维片状聚吡咯包覆的二硒化钒(VSe2@PPy)纳米复合材料作为高性能锂硫电池正极的硫宿主。该设计结合了金属VSe2的高导电性和催化活性，以及PPy涂层提供的优异导电网络、吸附能力和机械柔韧性。两者之间的界面电子耦合效应有效促进了多硫化物的转化，实现了稳定的高倍率锂硫电池。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["材料结构[锂硫电池硫载体]: 二维片状VSe2@PPy (聚吡咯包覆二硒化钒) 异质结构"]},{"i":39397,"as":"为解决碳基电流变(ER)流体在强极化下易发生漏电流和电压崩溃的问题，研究设计了二氧化钛表面修饰的碳纳米颗粒(CNPs@TiO2)。内部富含sp2的碳纳米颗粒提供强极化能力，而表面非晶态TiO2界面及Ti-O-C键限制了长程电荷传输并促进界面极化。阻抗谱和漏电流测试证实该设计有效解耦了极化效率与导电渗流，实现了高阻抗和电学稳定性。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["[电流变液]: TiO2表面修饰碳纳米颗粒(CNPs@TiO2)实现极化效率与导电渗流的解耦"]},{"i":39398,"as":"质子陶瓷燃料电池(PCFCs)的阴极材料PrBa0.5Sr0.5Co1.5Fe0.5O5+δ (PBSCF)经过高价位Mo掺杂后，显著促进了氧空位的形成并加速了阴极反应。这种钼掺杂策略有效改善了氧还原反应(ORR)动力学，在600°C下，掺杂后的PBSCFM01极化阻抗降低至0.052 Ω·cm²，大幅提升了电池的阴极活性。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["[质子陶瓷燃料电池阴极]: 钼掺杂的三重导电(H+/O2-/e-)层状双钙钛矿(PBSCF)"]},{"i":39399,"as":"研究开发了一种兼具止血、抗氧化和抗菌特性的多功能水凝胶(CBOS)，用于感染和糖尿病伤口的再生。该水凝胶由甜菜碱修饰的壳聚糖和氧化海藻酸钠通过席夫碱反应交联，并掺入聚乙烯醇和硼酸钠以增强网络稳定性。该水凝胶具有均匀多孔微观结构、稳健的粘弹性、高溶胀能力，且细胞毒性极低，展现出优异的生物相容性和治疗潜力。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["合成反应[多功能水凝胶]: 席夫碱反应","成分[多功能水凝胶]: 甜菜碱修饰的壳聚糖、氧化海藻酸钠、聚乙烯醇和硼酸钠"]},{"i":39400,"as":"研究开发了一种仿生菱形图案化二氧化钒(VO2)超表面智能热辐射装置(RITD)，用于自适应全天候建筑热管理。通过调控VO2的金属-绝缘体相变与法布里-珀罗腔及亚波长周期阵列的共振耦合，在大气窗口(8-14 μm)内实现了0.65的动态发射率调节(0.27至0.92)。其仿生结构保持极低的太阳能吸收率(0.23)，有效抑制了过度的太阳加热。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["[自适应建筑热管理]: 仿生菱形图案化VO2(二氧化钒)超表面智能热辐射器件"]},{"i":39401,"as":"通过双诱导晶格顺应性机制提升TiNb2O7材料的锂离子嵌入速度与稳定性，涉及高性能锂离子电池负极材料。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["机制[提升TiNb2O7锂离子嵌入]: 双诱导晶格顺应性","应用材料[高性能锂离子电池负极]: TiNb2O7"]},{"i":39402,"as":"研究使用脑磁图追踪人类在视觉运动任务中学习噪声环境的神经动态。结果表明，学习是由两种机制支持的：神经预测活动迅速出现，在刺激前产生特定模式；表征变化随后缓慢建立，增加了非相邻元素之间的神经模式相似性。这两个过程由一个分布式的大脑网络共同支持。","scd":null,"kp":["[学习非相邻时间依赖性]: 由神经预测活动和表征变化这两种时间上可分离的机制支持","[神经预测活动]: 迅速出现并在刺激前表现出特异性模式"]},{"i":39403,"as":"研究通过分析降水梯度上的土壤放射性碳、有机质理化组成和微生物碳利用效率，并结合全球数据集，探讨了土壤有机碳(SOC)与有机质(SOM)持久性的关系。结果显示，随着SOC含量增加，其持久性在全球和区域尺度上均呈下降趋势。高SOC土壤主要由周转较快的年轻碳主导，植物碳输入是SOM持久性的强预测指标。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[土壤有机碳]: 随着土壤有机碳含量的增加，其持久性(放射性碳特征反映)下降"]},{"i":39404,"as":"研究通过虚拟导航任务测试了环境几何形状（梯形和正方形）与路线导航序列效应如何相互作用影响空间记忆。结果揭示了内嗅皮层网格细胞模型预测的几何效应和路径整合模型预测的序列顺序效应。关键发现表明，这两种效应以相加方式结合，位置记忆在环境几何和序列顺序的共同作用下发生扭曲。","scd":null,"kp":["[环境几何形状]: 包括梯形和正方形，与路线导航中的系列效应相互作用以影响空间记忆"]},{"i":39405,"as":"研究结合临床分析、人体组织检测和小鼠模型发现，非小细胞肺癌(NSCLC)脑转移瘤具有免疫排斥表型，其细胞毒性T淋巴细胞(CTLs)和三级淋巴结构少于原发肿瘤。与纳武利尤单抗单药治疗相比，纳武利尤单抗联合伊匹木单抗（抗PD-1加抗CTLA-4阻断）能够增强CD8+ T细胞反应，促进三级淋巴结构形成，从而克服免疫排斥并抑制肿瘤生长。","scd":null,"kp":["[非小细胞肺癌脑转移临床颅内疾病控制]: 与纳武单抗单药治疗相比，纳武单抗联合伊匹木单抗得到改善","[联合阻断作用机制(抗PD-1+抗CTLA-4)]: 增强CD8+ T细胞反应并促进三级淋巴结构形成，从而克服免疫排斥"]},{"i":39406,"as":"","scd":null,"kp":[]},{"i":39407,"as":"","scd":null,"kp":[]},{"i":39408,"as":"","scd":null,"kp":[]},{"i":39409,"as":"","scd":null,"kp":[]},{"i":39410,"as":"研究提出了一种名为EmulatRx的代理智能框架，利用电子病历等大规模真实世界数据（RWD）增强临床试验设计（CTD）。该框架通过不同角色智能体间的迭代对话与分析，自主从RWD中提取真实世界证据（RWE），进而优化并完善试验方案，最终生成包含稳健协议和实用数据的报告，有效减少领域专家的沟通成本。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[临床试验设计]: 结合大规模真实世界数据(RWD/电子健康记录)与机器学习提取真实世界证据(RWE)以增强设计"]},{"i":39411,"as":"研究开发了一种机器学习框架，从欧洲600家大型企业的报告中提取了近290万条ESG（环境、社会和治理）观测数据。评估发现，企业ESG透明度存在显著差距：处于ESG评级最高十分位的企业比最低十分位的企业多披露22%的指标。该框架基于欧洲可持续发展报告标准（ESRS）有效量化了企业的ESG透明度及绩效表现。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["ESG数据观测点[欧洲600家大型企业(2014-2023)]: 290万个","提取框架[ESG指标提取]: 机器学习框架"]},{"i":39412,"as":"研究提出一种自下而上的蒸汽辅助胶体策略，成功以金属铅（Pb0）为前驱体合成高性能钙钛矿太阳能电池。针对Pb0难以转化为Pb2+的挑战，该工艺使Pb0先与碘反应生成均匀分散的碘化铅（PbI2）胶体，再与甲脒碘化物蒸汽发生气固反应完全转化为钙钛矿。基于该Pb0器件的能量转换效率达到22.65%，在效率和稳定性上均显著优于商用PbI2制备的器件。","scd":{"b":7.0,"i":5.0,"r":6.0,"d":7.0,"t":6.0},"kp":["钙钛矿前驱体[Pb0向Pb2+转化]: 与I2在N,N-二甲基甲酰胺和二甲基亚砜中反应生成均匀分散的PbI2胶体","合成策略[高性能太阳能电池]: 自下而上蒸汽辅助胶体策略"]},{"i":39413,"as":"为解决富镍层状氧化物阴极材料的结构不稳定性，研究采用Ti/Sr梯度掺杂与SrTiO3涂层对LiNi0.9Co0.05Mn0.05O2（NCM90）进行表面到内部的体积工程改性。Ti/Sr梯度掺杂降低了锂离子扩散势垒，抑制了长期循环中的Li/Ni混排并缓解应力积累；SrTiO3涂层则阻止了氧负离子向外迁移，稳定了电极-电解质界面，大幅提升了电池的循环稳定性。","scd":{"b":6.0,"i":6.0,"r":6.0,"d":7.0,"t":5.0},"kp":["阴极材料[Ti/Sr梯度掺杂与SrTiO3涂层]: LiNi0.9Co0.05Mn0.05O2 (NCM90-2TS)","体相到表面工程[富镍阴极改性]: 降低Li+扩散势垒，缓解应力应变积累和层间滑移"]},{"i":39414,"as":"","scd":null,"kp":[]},{"i":39415,"as":"研究将预训练的组织病理学基础模型（hFM）专门应用于侵袭性肿瘤组织。通过知情的扩展预训练，通用模型成功转化为编码更丰富语义信息的肿瘤专业化模型。研究识别出具有异常基因表达程序的肿瘤原型，这些形态学和分子特征高度一致的原型共存于肿瘤内。该模型成功发现了在多患者间复发的特征性肿瘤原型，为乳腺癌诊断提供了新视角。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["基础模型扩展预训练[浸润性肿瘤组织]: 将通用模型转化为肿瘤特异性模型","预后预测[乳腺癌RNA剪接原型]: 通过组织病理学基础模型识别"]},{"i":39416,"as":"作者对利用无铅压电材料消除雾化治疗中的铅暴露风险这一研究的勘误更正，涉及医疗材料安全性改进。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[雾化治疗压电材料]: 无铅压电材料，用于消除铅暴露风险"]},{"i":39417,"as":"研究提出了一种利用光响应共价有机框架（COF）进行动态机械锁定酶的策略。通过四氟偶氮苯工程化的COF，在可见光介导的异构化下实现孔径精确可逆变化，将酶自适应地限制在孔内。该方法显著提升了辣根过氧化物酶、细胞色素c和漆酶的保留率（分别提高6.7倍、9.7倍和1.8倍）。连续流测试中，机械锁定的甲酸脱氢酶在5次循环后仍保留99.2%的活性，大幅延长了催化寿命。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["酶固定化策略[共价有机框架COFs]: 动态孔机械锁定(可见光介导的异构化实现可逆孔径变化)","框架修饰材料[光响应纳米手]: 四氟偶氮苯工程化COFs"]},{"i":39418,"as":"研究通过将渗透膜蒸馏（OMD）与碱性水电解（AWE）集成，实现了直接从海水原位制氢。该系统在热梯度和渗透梯度的双重驱动下输送无盐水蒸气，连续运行500小时稳定实现60 kg m-2 day-1的产氢率。为消除能耗，研究提出了热共生架构，利用AWE废热为OMD提供热驱动力，同时OMD为AWE提供冷却，有效解决了盐交叉和产水量不足的问题。","scd":{"b":7.5,"i":4.0,"r":7.0,"d":8.0,"t":7.0},"kp":["H2产率[OMD-AWE系统]: 60","水蒸气传输驱动力[无盐水生成]: 双重热梯度和渗透梯度"]},{"i":39419,"as":"研究在分子束外延生长的磁性拓扑绝缘体异质结构中证实了非线性输运的边界体相互作用。实验发现，包括二次谐波霍尔效应和非互易纵向响应在内的非线性输运，在样品稍微偏离量子反常霍尔态和轴子绝缘体态时达到最大值。非线性响应的符号和幅度取决于电极配置、磁序和载流子类型，揭示了边界模式在非线性响应中的关键作用。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["拓扑材料[非线性输运研究]: 分子束外延生长的磁性拓扑绝缘体异质结构","非线性响应[边界体相互作用]: 二次谐波霍尔效应和非互易纵向响应"]},{"i":39420,"as":"研究设计了一种具有不对称非金属双活性位点的全有机电催化剂。通过工程化羟基构建不对称活性位点，触发了罕见的“不对称氧化物路径机制”。该路径降低了对双活性位点吸附能的严格平衡要求，打破了传统机制对吸附物演化机制的线性比例关系限制。该无金属电催化剂表现出优异的析氧反应性能，过电位为364.3 mV。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["电催化剂[全有机析氧反应]: 构筑具有羟基工程的不对称非金属双活性位点","反应路径[析氧机制]: 触发罕见的不对称氧化物途径(AOP)机制"]},{"i":39421,"as":"为解决高温介电储能问题，研究将一系列萘四甲酸二酐引入聚醚亚胺（PEI）骨架中以调制电荷传输行为。通过陷阱和二面角的协同调控，有效提升了PEI的击穿强度。在200°C高温下，该优化介电薄膜在90%效率下的放电能量密度达到6.00 J cm-3。这克服了传统双轴取向聚丙烯薄膜在恶劣环境下能量密度低和可靠性差的缺陷。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["介电薄膜[高温储能改性]: 引入萘四甲酸二酐(NTDA)调节深陷阱与二面角","电荷传输行为[聚合物介电材料]: 通过优化陷阱和二面角进行调制"]},{"i":39422,"as":"研究将散射视为时空中的演化过程，解析了散射异常点（EP）的时空动力学。研究建立了从动量-频率域到空间-时间域的跨域映射，将静态异常点与动态散射奇点联系起来。通过将酉散射矩阵投影到低维子空间，异常点的拓扑结构被成功印记到波包中，展现为时空特征，从而揭示了被稳态观测隐藏的异常点拓扑丰富性。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[散射异常点]: 在非厄米系统中为自由空间波控制重构输入-输出响应","[异常点拓扑特性]: 利用时空演化过程来解析稳态观测中隐藏的拓扑性"]},{"i":39423,"as":"研究提出一种直接反应捕获（DRC）策略，通过破坏氢键网络在有机电解质中将稀释气流中的CO2高效转化为CO。研究证实，氢键供体能力（HBD）是控制析氢和氧还原竞争反应的决定性参数。使用低HBD电解质能够破坏氢键网络，有效抑制杂质气流中高浓度O2引起的寄生反应，在中等压力下实现接近100%的法拉第效率。","scd":{"b":7.5,"i":4.0,"r":7.0,"d":8.0,"t":7.0},"kp":["直接反应捕获策略[稀释杂质气流中CO2转化]: 在有机二元溶剂电解液中实现近定量的法拉第效率","局部反应环境[抑制寄生氧还原反应]: 双溶剂电解质调节"]},{"i":39424,"as":"研究开发了一类在介位引入吸电子基团的五次甲基花青分子，成功实现了大反斯托克斯位移的蓝色发光三重态-三重态湮灭上转换。这种修饰有效缩小了单重态-三重态能隙，抑制了光异构化并促进了系间窜越。该敏化剂具有更高的三重态能级，与苝结合后，在保持高上转换量子产率的同时，将激发波长延长至远红光区域，打破了位移与产率之间的固有制衡。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[介位吸电子基团修饰的五次甲基花菁]: 缩小单重态-三重态能隙，抑制光异构化，促进系间窜越","[无金属三重态-三重态湮灭上转换系统]: 实现远红光激发并产生高效蓝光发射"]},{"i":39425,"as":"研究通过精准优化双锥体[PXZDPPQ]2Cu4I4的激发态，实现了外量子效率超过40%的红色电致发光器件。其配体结合了共轭延伸的DPPQ与强给电子的PXZ，促使高度放射性的外层配体间电荷转移态在能量和空间上有利于捕获载流子，有效避免了非辐射损耗。这克服了传统红色簇发光分子因非辐射衰减导致效率低下的瓶颈。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":8.0,"t":6.0},"kp":["外量子效率[红色团簇发光二极管[Cu4I4]]: 超过40%","[双锥体 [PXZDPPQ]2Cu4I4 配体结构]: 集成共轭延伸的二苯基膦酰基喹啉(DPPQ)与强给电子的吩恶嗪(PXZ)以优化激发态"]},{"i":39426,"as":"研究开发了一种无需金属催化剂的接触电化学路线，利用机械能从盐水中生成氯消毒剂。在超声驱动下，氟化乙丙烯（FEP）颗粒与液体接触分离在固液界面产生羟基和氯自由基，进而生成活性氯（次氯酸和次氯酸根），且不产生氯气。使用天然海水时，活性氯产量达到208.8 μmol g−1 h−1。这确立了接触起电驱动化学反应的新范式。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[接触起电(CE)引发自由基]: 构建无金属催化剂的电化学接触(CE-Chemistry)转化途径","[盐水制备氯消毒剂]: 通过氟代乙烯丙烯(FEP)颗粒在盐水中超声驱动的接触-分离产生自由基"]},{"i":39427,"as":"研究将阳离子碳纳米管（CCNTs）作为通用添加剂，实现了强酸性条件下的高效电化学二氧化碳还原（CO2RR）。在pH≤1的电解液中，以铋、银和氧化铜为催化剂，甲酸、一氧化碳和乙烯的法拉第效率分别达到95%、100%和67%。CCNTs有效克服了有机阳离子通常存在的质子屏蔽差和选择性低的问题，通过调节表面场为酸性CO2还原提供了高稳定性的电解质环境。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[阳离子碳纳米管(CCNTs)]: 作为通用添加剂调节表面场，在强酸介质中有效抑制析氢反应(HER)并实现高效二氧化碳还原反应(CO2RR)","[催化体系]: 铋、银和氧化铜催化剂"]},{"i":39428,"as":"研究开发了一种基于相变材料集成的二维像素级可寻址中红外超表面空间光调制器。该器件采用标准硅光子代工工艺与后端互连工艺制造，利用多层后端金属互连实现交叉开关寻址方案。每个像素集成了硅二极管选择器，有效抑制了寄生漏电流，实现了首个透射式中红外振幅型空间光调制器，为大规模阵列扩展奠定基础。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[像素化中红外振幅型空间光调制器]: 基于相变材料集成的超表面架构，首次实现二维电可寻址透射式调制"]},{"i":39429,"as":"研究制备了面积达到毫米级的单晶三氧化钼（α-MoO3）作为二维晶体管的范德华电介质材料。测试表明，该单晶材料厚度均匀，介电常数高达约18.5。在3.0 MV cm−1的电场下，栅极漏电流极低（约10−2 A cm−2），且击穿场强高达约26.75 MV cm−1，为二维晶体管的大规模高质量介电层集成提供了解决方案。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[大面积二维α-MoO3]: 作为高κ范德华电介质用于二维晶体管集成"]},{"i":39430,"as":"研究开发了一种用于即时单核苷酸多态性（SNP）基因分型的一锅法CRISPR平台。通过热力学设计DNA引物，构建了具有顺序反应的两阶段扩增过程，在不需物理分离的条件下延迟CRISPR激活，直到扩增子积累充足。此外，通过引物引入PAM序列，去除了对原生靶标序列的依赖，在保持单碱基区分精度的同时扩大了靶标可及性。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[热力学编程一锅法CRISPR诊断平台]: 通过引物结合强度差异创建两个连续的扩增阶段，延迟CRISPR激活直至积累足够扩增子"]},{"i":39431,"as":"研究报道了一种通过参量泵浦产生磁自发振荡的新机制。在钇铁石榴石延迟线中施加泵浦音激发传播的自旋波，利用四波混频效应将其转化为两个相位独立的传播磁振子模式。该机制能够生成具有极锐特性的自旋波动态，且频率可通过泵浦和磁场进行宽带调谐。该自发模式还可与探测音实现相位锁定，表现出自振荡器的特性。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[参量泵浦激发]: 通过四波混频将泵浦模式转换为两个相位自主的传播磁振子模式，产生磁自发振荡","[实验材料体系]: 钇铁石榴石延迟线"]},{"i":39432,"as":"研究提出了一种利用双折射诱导相位延迟滤波器测量全振动光谱的方法。该滤波器具有高消光比和超窄带宽，能够高效抑制激光频率附近的强弹性散射，从而实现了从0.1到超过3500 cm−1的宽频段覆盖。这种多模态无标记检测技术能够同步采集布里渊散射、超低频拉曼及常规拉曼光谱，实现对样品力学、结构和化学特性的同时分析。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[全振动光谱测量方法]: 通过分析不同频率范围的全振动光谱，同时获取并反演力学、结构和化学属性"]},{"i":39433,"as":"研究在水稻中发现了偏向GC的基因转换（gBGC）现象。非编码区的GC含量与重组频率高度相关，而编码区的GC含量则受到重组与高翻译效率选择的共同塑造。观测表明，水稻及其野生近缘种的GC含量出现下降，完全异交并未导致GC含量的净增加，表明相关突变在进化选择中受到了其他机制的抵消。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[偏向GC的基因转换(gBGC)]: 影响水稻中非编码序列与编码序列的GC含量快速进化","[重组频率]: 与非编码序列的GC含量高度相关"]},{"i":39434,"as":"研究发现OsMYB4转录因子在水稻胚乳中特异性表达，对提高产量和品质具有关键协调作用。敲除OsMYB4基因会导致稻米垩白增加，直链淀粉和蛋白质含量下降，且产量降低。OsMYB4通过直接结合淀粉和贮藏蛋白合成相关基因的启动子激活转录，并与其他转录因子形成复合物，协同调控水稻胚乳中营养物质的合成与积累。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["靶标基因[水稻胚乳]: OsMYB4","蛋白功能[水稻胚乳]: 特异性表达的MYB转录因子","表型特征[OsMYB4功能丧失]: 谷粒垩白增加"]},{"i":39435,"as":"研究利用冷冻电镜技术解析了人源质子偶联氨基酸转运蛋白1（hPAT1）的apo状态及其与D-丝氨酸、烟酸和D-环丝氨酸结合的复合物结构（分辨率3.4–3.5 Å）。结构分析显示，尽管这三种底物具有不同的化学结构，但均在蛋白内部呈现出空间趋同的结合模式，阐明了hPAT1广泛识别不同氨基酸类似物及药物的分子机制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["底物谱[人质子偶联氨基酸转运蛋白1(hPAT1)]: 广谱两性离子氨基酸类似物（含中枢神经系统活性化合物）","表征技术[SLC36家族成员结构解析]: 冷冻电子显微镜(cryo-EM)","结构状态[hPAT1解析]: apo状态及其结合状态"]},{"i":39436,"as":"研究发现拟南芥纯富亮氨酸重复（LRR-only）蛋白基因LRIP1的等位基因变异能够赋予植物对两类不同病原体的双重抗性。抗旱地区的等位基因通过水杨酸信号通路提供针对细菌（番茄丁香假单胞菌）的抗性；高降水地区的等位基因则通过激活樟素生物合成提供针对真菌（灰葡萄孢菌）的抗性。两个等位基因启动子和编码序列的差异决定了不同的空间表达和抗病功能。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[仅LRR蛋白(LRIP1)等位基因变异]: 赋予拟南芥针对双重病原体的抗性","[抗旱地区的等位基因]: 赋予特定抗性"]},{"i":39437,"as":"研究开发了一种集多价识别、逻辑门计算与精准给药于一体的智能DNA纳米装置。该装置由三个变构适配体臂、胆固醇膜锚定物以及载有阿霉素的四面体DNA骨架组成。当三个适配体臂同时结合目标细胞表面受体触发“AND”逻辑门时，会在细胞膜原位精确释放药物。这种定点感知与靶向给药机制最大限度地减少了脱靶效应，提升了治疗精准度。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":8.0,"t":6.0},"kp":["[膜锚定智能DNA纳米装置(DND)结构特点]: 集成多价识别、逻辑门计算和空间精确给药于单一纳米结构","[药物负载载体]: 阿霉素负载的DNA四面体框架"]},{"i":39438,"as":"研究揭示了IL-6是驱动滤泡调节性T（Tfr）细胞分化的关键调节因子。IL-6信号通路通过诱导转录因子C/EBPα的表达，促使其结合Tfr细胞中的Bcl6和Cxcr5启动子，从而调节Treg向Tfr分化。在小鼠中敲除C/EBPα会导致Tfr分化受损、生发中心反应过度活跃，并加剧系统性红斑狼疮等病理症状。在人类细胞模型中验证了该分子机制的一致性。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[Tfr细胞分化驱动机制]: IL-6/IL-6Rα信号通过诱导C/EBPα(结合Bcl6和Cxcr5启动子)促进调节性T细胞向Tfr细胞分化"]},{"i":39439,"as":"研究结合单细胞mRNA测序、空间转录组学等技术，对比了原发性硬化性胆管炎并发溃疡性结肠炎（PSC-UC）与普通UC患者的结肠粘膜特征。PSC-UC结肠表现出与健康人或普通UC患者不同的区域性形态和生物学特征。尽管两者存在差异，但研究发现PSC-UC与普通UC共享一种特定的肥大细胞状态，揭示了其共发炎症的细胞学机制。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":8.0,"t":6.0},"kp":["[PSC-UC相比于单一UC的临床特征]: 疾病发作较轻，右半结肠为主，且患结直肠癌的终生风险更高"]},{"i":39440,"as":"研究基于大规模森林生物多样性实验，将生物多样性与稳定性的关系从单一种群扩展到了跨营养级（植物-食草动物）的元群落系统。研究发现，生物多样性不仅在单一营养级内具有稳定作用，对跨营养级之间的稳定性同样起到正向调节。食草动物的物种多样性削弱了自上而下的调节效应，进一步加强了群落的整体稳定性。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[森林大规模生物多样性实验]: 将时间稳定性的尺度从种群扩展到群落和跨营养级元群落"]},{"i":39441,"as":"研究开发了一种无需滋养层、12天内高效将人类始发态多能干细胞转化为类初始态的实验方案。多组学分析表明，转化过程中染色质发生了重塑，OCT/KLF位点可及性增加，同时上调了miR-372/373。功能实验证实，炎症转录因子NFκB/RELA通过激活着床后屏障基因阻碍初始态转变，而过表达特定miRNA可抑制NFκB/RELA，促进多能性的重编程。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["转化时间[从primed hPSCs转化为naïve-like态的无饲养层方案]: 12天内","染色质重塑特征[转化过程]: OCT/KLF基序可及性增加，ZIC/RFX/NFκB位点关闭"]},{"i":39442,"as":"为了解决人工神经网络中反向传播和对比赫布学习所面临的“权重传输”对称性难题，研究提出了一种基于突触局部的尖峰对齐学习规则（SAL）。该规则利用神经元噪声实现权重对齐，能够与其他功能性学习规则并行运作。SAL在学习过程中维持了网络必要的对称性，确保梯度的局部准确表示，并有效克服了模拟物理神经网络中广泛存在的神经元和突触变异性问题。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["算法名称[解决重量传输问题]: 尖峰对齐学习(SAL)","算法机制[局部计算]: 利用噪声进行权重对齐的突触局部学习规则"]},{"i":39443,"as":"研究提出通过调节局部化学有序性来增强高熵陶瓷电磁波吸收性能的新策略。将该机制应用于高熵碳化物，通过热处理调控，实现了创纪录的11.2 GHz有效吸收带宽。原子级化学图谱及理论模拟表明，主导电磁波吸收机制的是局部化学有序结构，而非原子空位。该策略被证明具有通用性，可广泛应用于其他高熵材料的电磁波吸收设计。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":8.0,"t":6.0},"kp":["材料体系[宽带电磁吸收]: 高熵碳化物","改性策略[局部化学顺序调控]: 简单热处理","性能表现[高熵陶瓷]: 宽带电磁波衰减与破纪录的吸收效能"]},{"i":39444,"as":"研究提出一种溶剂介导增强的电解液设计策略，以实现高比能锂金属电池。通过量化设计的极性指数探讨溶剂环境对溶剂化态和阴离子还原的影响。该策略利用纳米尺度下分离的溶剂表面电荷产生的分子间静电场，增强了对溶剂化锂离子的容纳能力，降低了阴离子的还原能垒，促进了有效界面膜的形成，实现了安时级高能软包电池的稳定运行。","scd":{"b":8.0,"i":5.0,"r":8.0,"d":8.0,"t":7.0},"kp":["电解液设计策略[高比能锂金属电池]: 介质增强的溶剂化化学静电调节","核心机制[溶剂化状态]: 介质环境对溶剂化状态和阴离子还原的影响"]},{"i":39445,"as":"研究通过调控可电离脂质尾部的烷基链长度和数量，设计并筛选出一种能在酸性肿瘤微环境（aTME）中激活的溶瘤脂质纳米颗粒。研究发现脂质纳米颗粒的pH依赖性细胞毒性与疏水尾部的总碳原子数存在明确相关性。这种肿瘤酸度激活纳米颗粒将对正常细胞的膜破坏作用精准限制在肿瘤微环境内，实现了具有高选择性的溶瘤治疗效果。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[肿瘤酸度激活的可电离脂质纳米颗粒]: 通过结构调制将膜破坏活性质子化选择性限制在酸性肿瘤微环境以实现选择性溶瘤"]},{"i":39446,"as":"研究开发了一种不依赖特定外部刺激的可转化纳米光敏剂（SITNPS），解决了纳米药物穿透深度与滞留时间难以平衡的瓶颈。该光敏剂以纳米球形态深入穿透肿瘤组织，随后逐渐转化为纳米棒形态以延长滞留时间。SITNPS可通过双光子激光或智能手机闪光灯激发，单次注射即可支持多次重复光动力治疗，为实用化癌症光疗提供了便捷路径。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["纳米光敏剂形态转换[肿瘤穿透至滞留阶段]: 以纳米球形态穿透肿瘤后逐渐转化为纳米棒以延长肿瘤驻留时间","光激活条件[SITNPS]: 可由双光子激光或智能手机手电筒激发"]},{"i":39447,"as":"多金属增材制造能将异种金属结合成具备特定区域性能的整体构件，但界面原子级结合不良及微观结构不均仍是其面临的主要挑战。本文系统阐述了控制异质界面形成的热力学混溶规律，深入剖析了金属间化合物、孔隙及元素偏析等缺陷的产生机理，并揭示了“界面-微观结构-性能”之间的内在关联。为此，本文提出了一套涵盖相容性评估、工艺决策与缺陷控制的系统框架，为推动多金属3D打印结构的工业化应用奠定了坚实的材料科学基础。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[多金属增材制造]: 将异种金属集成到具有位点特异性性能的单片组件中","[异质界面形成]: 受热力学混溶性规则支配","[界面缺陷来源]: 包括金属间化合物、孔隙和元素偏析"]},{"i":39448,"as":"《能源与环境科学》发表文章，提出一种亚纳米级钌团簇催化剂，用于提高阴离子交换膜水电解槽中绿色制氢的效率。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["催化剂[阴离子交换膜水电解槽绿氢生产]: 亚纳米级钌簇催化剂"]},{"i":39449,"as":"《环境科学与技术》发表文章，对肯尼亚的绿色氢气生产进行了建模研究，探讨其在当地电网整合方面的潜力与实施方案。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":[]},{"i":39450,"as":"利用接触电催化产生的静电场极化效应提升单原子催化剂性能。以Ru1/SiO2为例，通过氟化处理增强基底接触起电能力，不仅加速了水分子解离，还建立了强电场增强还原活性，使产氢量提升了7.62倍。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":8.0,"t":6.0},"kp":["氢气产率提升倍数[接触电催化极化单原子催化剂Ru1/SiO2]: 7.62倍","[单原子催化剂性能提升策略]: 利用接触电催化（CE）产生的电场诱导静电极化"]},{"i":39451,"as":"解决空气环境制备钙钛矿太阳能电池的难题。通过引入小分子添加剂，在初期引导晶体生长并在退火期间稳定材料，实现脱离手套箱的高效器件制备。该策略同时控制了加工过程与稳定性，为低成本、可扩展的钙钛矿太阳能电池制造提供了可行路径，使效率接近27%。","scd":{"b":7.0,"i":6.0,"r":6.0,"d":7.0,"t":6.0},"kp":["光电转换效率[空气处理钙钛矿太阳能电池]: 接近27%","[空气处理钙钛矿器件制备]: 采用小分子添加剂在起始阶段引导晶体生长并在退火期间稳定材料，从而克服空气中水分和热量的干扰"]},{"i":39452,"as":"概述原位光学表征技术的研究进展与应用。这些技术作为实时探测成核、相变和中间态形成的有力工具，被系统回顾其在钙钛矿结晶研究中的发展，旨在为研究人员提供全面的技术指南。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[钙钛矿结晶原位监测]: 实时探测成核、相变及中间态形成过程"]},{"i":39453,"as":"通过二维到三维的拓扑缩合反应，成功合成出一种新型三维大孔高硅沸石JU-68。研究开发了富含环己基的有机结构导向剂以稳定末端bea结构单元，先形成新型二维大孔前驱体JU-67，经焙烧后发生拓扑转化，突破了此类方法以往只能生成中小孔结构的限制。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[新型沸石材料合成]: 通过二维到三维的拓扑缩合（topotactic condensation）技术首次合成出具有三维大孔结构的新型高硅沸石"]},{"i":39454,"as":"结合光化学卤素原子转移（XAT）与镍介导的类氮烯转移，首创直接催化合成α-三氟甲基酰胺的平台。在温和条件下，易得的α-溴代三氟甲基烷烃与二唑酮反应，生成具有广泛官能团耐受性的C(sp3)-N键。该催化体系还支持三组分烯烃三氟烷基酰胺化，机理研究证实涉及光化学产生的α-CF3烷基自由基。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[温和条件下的C(sp3)-N键构建]: 结合光化学卤素原子转移(XAT)和镍介导的类氮烯转移，实现α-三氟甲基酰胺的直接催化合成"]},{"i":39455,"as":"开发模拟生物转运蛋白的MXene材料，用于高效捕获和检测生物流体中的尿酸，涉及纳米生物传感器技术。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[尿酸捕获与传感材料]: 开发模拟生物转运蛋白的MXene材料用于生物流体分析"]},{"i":39456,"as":"研究利用同分异构共价有机框架构建光催化提取铀的空间解耦捕获-转化架构。实验表明，位点解耦的TpBpy6有效抑制了UO22+捕获与氧还原反应间的相互干扰，维持了原位光催化生成H2O2，并成功将捕获的UO22+连续转化为不溶性的studtite。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["材料平台[光催化提取铀]: 同分异构共价有机框架(TpBpy4, TpBpy5, TpBpy6)","空间架构[位点解耦]: 将吸附基序与光催化单元进行空间解耦"]},{"i":39457,"as":"能够弯曲、扭转和适应连续变形的连续体机器人，在现代社会基础设施的检查和维护中具有应用潜力。但在产生实际影响之前，必须解决在力施加、形状估计、鲁棒性以及接触感知控制等方面的技术挑战。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["机器人类型[可持续基础设施维护]: 连续体机器人","技术挑战[连续体机器人实用化]: 力施加、形状估计、鲁棒性和接触感知控制"]},{"i":39458,"as":"提出一种将微结构非热表面放电直接耦合至气体扩散阴极的等离子体-电解膜电极组件。该组件原位生成并传递激发态氮气分子N2(ν)至催化界面。在室温常压下，银催化剂展现出最佳活性与选择性平衡，在-0.54 V（vs RHE）下实现氨产率7.7 nmol s-1 cm-2，法拉第效率达86%。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":8.0,"t":7.0},"kp":["最优催化剂[14种金属筛选-等离子体电催化氮还原]: Ag (银)","系统架构[环境条件下电化学合成氨]: 集成等离子体-电解的膜电极组件","核心技术[原位生成与传输]: 直接耦合非热表面放电以原位生成并传递振动激发态N2(ν)至气相扩散阴极"]},{"i":39459,"as":"针对I型光引发剂在光裂解、光聚合及光驱动3D打印中因环境变量差异导致难以跨系统直接比较的问题，讨论了光引发剂性能评估的最新进展。文章提出建立标准化的协议框架，以解决不同研究中产物收率和反应活性再现性差的难题。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["核心机制[I型光引发剂]: 光照下发生裂解生成高反应性自由基","应用场景[I型光引发剂]: 涂层、微电子图案化、光驱动3D打印"]},{"i":39460,"as":"结合高分辨率旋转光谱和量子化学计算，解析N,N-二乙酰氧基胺（DEAcA）的水合位点选择性。尽管孤立单体优先形成syn构型，但在微水合（1-3个水分子）状态下表现出对高碱性sp3氮位点的绝对偏好。14N核四极矩耦合常数提供了溶剂网络主导溶剂化过程的直接实验证据。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["分析对象[N,N-二乙酰氧基胺(DEAcA)水合]: sp3氮受体与羰基氧受体的竞争性位点选择性","表征方法[溶剂化位点选择性]: 高分辨率转动光谱结合量子化学计算","构型特征[孤立单体]: 受偶极矩驱动优先采取syn构型"]},{"i":39461,"as":"利用基于同步加速器的原位掠入射广角X射线散射（GIWAXS）和分子模拟证实，气液界面成核控制着氟芬那酸的多晶型选择，并表现出显著的浓度依赖性：低浓度生成晶型I，高浓度生成晶型III，中间浓度生成亚稳态晶型IV。研究揭示了三种与特定晶型出现相关的界面分子演化路径。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":8.0,"t":6.0},"kp":["多晶型选择[气液界面成核(氟芬那酸)]: 表现出显著的浓度依赖性（低初始浓度有利于I型成核，高浓度产生III型，中等浓度选择性产生其他型）"]},{"i":39462,"as":"在二维单晶共价有机框架（USTB-35-Cu）中发现异常多步电荷转移机制。结构解析表明其由亚胺连接的铜卟啉与苝酰亚胺层交错堆积而成。在形成光致电荷分离态后，激发态的苝酰亚胺阴离子自由基逆向将光生电子转移给周围的卟啉基元，复现了自然光合作用中的多电子转移化学。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["光催化剂[光催化多步电荷转移]: 二维单晶共价有机框架(USTB-35-Cu)","晶体结构[解析方法]: 连续旋转电子衍射(CRED)耦合理论模拟"]},{"i":39463,"as":"交变磁场下的自热铁磁Ru/Fe3O4催化剂通过动态调节自旋态打破了氨裂解反应的萨巴蒂尔限制。计算与实验表明，在交替磁场下，催化剂展现出高低自旋协同催化作用，有效平衡了氨分子强吸附与氮、氢原子弱吸附的需求，显著提升了氨分解效率。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["催化剂限制突破[交变磁场调控氨裂解]: 动态调节催化剂自旋态以破坏萨巴蒂尔限制(Sabatier constraints)"]},{"i":39464,"as":"研究坚固碳覆盖层作为氢溢出通道和共结合屏障，增强反向水气转移反应的催化效率，涉及催化材料科学。","scd":{"b":6.0,"i":2.0,"r":3.0,"d":3.0,"t":4.0},"kp":["[反向水气变换反应增强机制]: 采用坚固碳覆盖层作为氢溢出通道与共吸附屏障来提升催化效率"]},{"i":39465,"as":"成功制备出无需快速淬火的大块且可退火的铁磁二十面体准晶。在Au-Cu-Al-In-R（R = Gd, Tb, Dy）多组分合金中，通过电弧熔炼和受控退火获得了单相准晶。材料表现出锐利的准周期衍射和优异的热稳定性，首次实现了对磁临界行为的定量研究。","scd":{"b":9.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["铁磁二十面体准晶[材料制备状态]: 大块的、可退火的、无需快速淬火"]},{"i":39466,"as":"探讨利用硫氟化物交换反应在正极表面进行共价接枝，通过调节双电层结构来提升高镍三元正极材料稳定性的技术。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[高镍三元正极材料稳定性提升]: 利用硫氟化物交换反应在正极表面进行共价接枝以调节双电层结构"]},{"i":39467,"as":"关于一篇学术期刊的勘误声明，原研究主要涉及具备全连通架构的98量子比特囚禁离子量子计算机的研发。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":5.0,"t":5.0},"kp":["量子比特数[囚禁离子量子计算机]: 98","系统连通性[囚禁离子量子计算机]: 全连通架构"]},{"i":39468,"as":"一款名为“Humanizer”的工具通过引导文本生成系统，专门移除研究论文和基金申请中常见的人工智能书写痕迹与句式结构，以掩饰文本由AI生成的特征。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[文本生成系统]: 指示系统消除研究论文和资金申请中与人工智能相关的书写特征"]},{"i":39469,"as":"提出建立专利池和授权架构的方案。相比于仅依赖长达数十年的采矿和冶炼投资，该架构能够更广泛、高效地促进全球所需关键矿物的应用与普及。","scd":{"b":2.0,"i":4.0,"r":6.0,"d":3.0,"t":4.0},"kp":["[关键矿物应用]: 建立专利池和许可架构以实现比单纯增加采矿和精炼投资更广泛的普及"]},{"i":39470,"as":"","scd":null,"kp":[]},{"i":39471,"as":"哈勃太空望远镜具有独特的观测视野和广泛的社会公众支持。这些核心优势使其在人类理解宇宙的进程中持续发挥着至关重要的作用，目前保护该望远镜的拯救竞赛已经拉开帷幕。","scd":null,"kp":["[哈勃太空望远镜]: 独特的观测视觉和公众支持对理解宇宙持续发挥关键作用"]},{"i":39472,"as":"哈勃和詹姆斯·韦伯太空望远镜的合作正不断产出超乎天文学家想象的科学发现。这些联合观测任务正在持续提供极高的科学价值，使两大太空望远镜保持活跃的运行状态，并为天文学界带来突破性的研究成果。","scd":null,"kp":["[哈勃与韦伯太空望远镜]: 科学合作带来了超出预期的科学发现"]},{"i":39473,"as":"","scd":null,"kp":[]},{"i":39474,"as":"针对水系锌离子电池中的H+诱导副反应问题，研究开发了二维导电金属有机框架Cu3(HHTATP)2。该材料实现了电压分离的Zn2+和H+连续存储，其多位点氧化还原化学（包括胺/亚胺的可逆转化）有效抑制了层状双氢氧化物干扰。该技术具备高容量、快速离子扩散和优异的倍率性能。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["储能机制[二维导电金属有机框架Cu3(HHTATP)2]: 实现电压分离的连续Zn2+和H+存储","侧反应抑制[水性锌离子电池]: 通过可逆的H+介导的胺/亚胺转化抑制层状双氢氧化物(LDH)相关干扰"]},{"i":39475,"as":"本研究提出一种多电子水性钒电池，通过OH⁻介导的化学活化切断V-O键，成功将传统单电子离子插入反应转变为四电子转换反应。借助定制介孔结构富集局部OH⁻，该电池实现了V2O3与Na3VO4之间的可逆转换。这种转换型负极具有极高优势：比容量高达700 mAh g⁻¹，钒利用率达98%，氧化还原电位低至-0.95 V，且能稳定循环超3000次。该技术突破了传统钒化学的容量限制，极大提升了水系电池的能量密度，为高性能储能设备的研发提供了全新路径。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["反应机制转换[多电子水系钒电池]: OH−介导的化学活化促使V-O键断裂，驱动从单电子嵌入机制向多电子转换型机制转变"]},{"i":39476,"as":"研究如何通过抑制三卤化物中间体的形成，开发出具备抗偏析特性的宽带隙钙钛矿材料，多用于叠层光伏器件。","scd":{"b":7.5,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["宽带隙钙钛矿材料[叠层光伏器件]: 具备抗偏析特性，通过抑制三卤化物中间体的形成来开发"]},{"i":39477,"as":"该文对钙钛矿光伏领域中关于“热声子瓶颈”等流传较广的机理假设或学术神话进行了理论辨析与证伪探讨。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["[钙钛矿光伏机理]: 对热声子瓶颈等流传较广的学术假设进行了理论辨析与证伪"]},{"i":39478,"as":"探讨自组装单层膜在倒置钙钛矿太阳能电池中的应用，分析其作为界面偶极子促进电荷隧穿传输以提升器件效率的机制。","scd":{"b":7.5,"i":3.5,"r":5.0,"d":4.0,"t":6.0},"kp":["自组装单层膜[倒置钙钛矿太阳能电池]: 作为界面偶极子促进电荷隧穿传输以提升器件效率"]},{"i":39479,"as":"介绍一种新型液-液萃取技术，通过将固定电荷引入选择性氧化还原活性化合物，实现目标物质的直接带电与高效分离。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["液-液萃取技术[选择性氧化还原活性化合物]: 引入固定电荷实现目标物质的直接带电与高效分离"]},{"i":39480,"as":"综述或研究添加剂成分与结构灵活性在优化形貌及能级中的作用，强调其对实现高效有机太阳能电池的关键重要性。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["[高效有机太阳能电池]: 添加剂成分与结构灵活性在优化形貌及能级中起关键作用"]},{"i":39481,"as":"本期《自然》历史档案回顾了两项科学里程碑：首次成功固化第二轻的化学元素氦，以及秘鲁发现了一个古老的咸水湖遗迹。这些片段重申了历史上的重要科学探索与地质发现。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[第二轻元素]: 首次实现固态化（固化）"]},{"i":39482,"as":"研究发现脑毛细血管内皮细胞的Kir2.1通道在神经血管耦合中起关键作用。神经元活动产生的细胞外K+激活Kir2.1，引发血管舒张电信号。该通道功能依赖于脂质辅因子PIP2的持续生成，内皮Arf6通过PIP2依赖性机制维持电信号传导和脑血流。此机制受损与脑小血管病模型中的功能衰退直接相关。","scd":{"b":8.0,"i":1.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[神经血管耦合/脑血流维持]: 毛细血管内皮细胞内向整流钾通道（Kir2.1）被神经元活动衍生的细胞外K+激活，并依赖于内皮Arf6和PIP2"]},{"i":39483,"as":"为探明超导体中亚晶格熔化与快速离子传输的微观机制，研究提出包含刚性宿主晶格与软载流子亚晶格的二元模型。刚性斥力与软载流子间的长程瓦纳型作用力形成温差，引发亚晶格熔化中间相。分子动力学模拟显示载流子在熔化附近呈强烈的非谐运动，并伴随扩散率、结构相关性和动力学异质性的剧变。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[超离子导体微观模型]: 由短程空间排斥稳定的刚性主晶格和通过长程Wigner型力相互作用的软载流子亚晶格组成的化学中性最小二元模型","[亚晶格熔化相]: 形成鲜明对比的相互作用自然产生不同的熔化温度及载流子变为类流体状的中间亚晶格熔化相"]},{"i":39484,"as":"研究证实拖延症与非计划性冲动（NPI）具有共同的神经生物学基础。通过对154对双胞胎的纵向研究及两个独立队列（N=327, N=1543）验证，发现青少年晚期的NPI与成年后的拖延症前瞻性相关。加性遗传学双胞胎模型进一步揭示了拖延症作为冲动副产物的遗传和生物学机制，解开其对健康产生不良影响却依然遗传的悖论。","scd":null,"kp":["[探究拖延与非计划性冲动共同神经底物的纵向双胞胎队列]: 样本量N=154"]},{"i":39485,"as":"研究综合评估了全球102个森林群落中281种木本植物的非结构性碳水化合物（NSC）浓度。发现可溶性糖和淀粉具有不同的性状控制策略。针叶裸子植物和常绿物种始终维持较高的NSC水平。NSC作为渗透调节和防御缓冲剂，其系统发育信号和跨器官的种间特异性差异，是预测森林碳分配及气候变化下生存策略的关键基础。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["物种数量[非结构性碳水化合物浓度的跨物种综合分析]: 102个混合森林群落中的281种木本植物","调控策略[树木碳水化合物储存全球策略基础]: 对可溶性糖和淀粉的不同性状控制"]},{"i":39486,"as":"研究鉴定了艰难梭菌鞭毛蛋白（FliC）糖基化过程中的细胞中间体，揭示了其独特的A型糖结构生物合成途径。该结构通过磷酸二酯键连接N-甲基-L-苏氨酸修饰O-linked N-乙酰-β-d-葡糖胺。这种特殊的糖后修饰（PGM）由四个特定编码的酶合成，对细菌表面蛋白功能及病原体毒力具有重要作用。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":6.0},"kp":["[艰难梭菌鞭毛聚糖生物合成]: 鉴定出细胞中间体，揭示其由独特的酶催化，且鞭毛蛋白（FliC）修饰有包含O连接的独特Type A聚糖结构"]},{"i":39487,"as":"导致亚急性硬化性全脑炎（SSPE）等慢性神经系统感染的麻疹病毒（MeV）与动物麻疹病毒（如犬瘟热病毒CDV等）具有共同的基因型和表型特征。研究表征了在宿主中枢神经系统中潜伏数年的CDV、PDV和DMV毒株，揭示了这些跨物种麻疹病毒引发长期持续性致命脑部感染的关键共同机制。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[引起人类和动物慢性神经系统感染的麻疹病毒株]: 具有共同的关键基因型和表型特征"]},{"i":39488,"as":"研究发现海马体中存在依赖星形胶质细胞的跨区域化生现象。对海马CA1区卵圆层的刺激不仅抑制邻近放射层的长时程增强（LTP），该化生作用还跨越海马裂隙，在体内外均抑制齿状回中分子层突触的LTP诱导。此过程不依赖CA3区，证实了海马体内存在一种逆向、长距离的神经突触可塑性交叉对话机制。","scd":{"b":7.0,"i":1.0,"r":7.0,"d":4.0,"t":5.0},"kp":["[海马跨区域星形胶质细胞依赖性化生]: 缰核下区（SO）的启动刺激能抑制邻近放射层（SR）及跨区域的后续长期 potentiation (LTP) 诱导"]},{"i":39489,"as":"气候变化正改变动物的繁殖时间，但不同空中食虫动物种群在适应气候变暖时表现出截然不同的种群轨迹。尽管这些物种对温度变化的生理反应十分相似，其保持同步或滞后的敏感性差异仍导致了种群数量的不同走向。研究揭示了气候变化下物种响应机制与种群动态之间复杂的非线性关系。","scd":{"b":4.0,"i":1.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[空中食虫动物]: 对温度的反应相似，但种群数量随气候变暖的轨迹不同"]},{"i":39490,"as":"物理接触在海洋细菌群形成中施加了一致性与数量的权衡机制。以海洋细菌Vibrio splendidus 12B01为模型的实验和理论证实，较大的细菌群增加了接触资源颗粒的概率，但同时也提高了被裂解噬菌体感染的几率。这种基于大小的接触理论解释了多细胞群体行为在获取不可及底物、增强抗逆性时的生态优势边界。","scd":{"b":5.0,"i":1.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[海洋环境中物理接触形成的细菌群]: 物理接触对群落的形成施加了一致性与数量的权衡"]},{"i":39491,"as":"感觉神经元中共享变异性的结构反映了任务相关信息并与行为表现密切相关。神经回路模型显示，感觉信号与共享变异性对齐时，可在不损害编码保真度的情况下放大行为相关信息。多脑区神经群体记录分析表明，共享变异性的主轴与任务相关变量的编码轴精确对齐，揭示了电路连接如何同时塑造信号传播与变异性。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[感觉神经元中的相关变异性]: 其结构反映了与任务相关的信息，并由决定信号传播的神经回路连接性所塑造"]},{"i":39492,"as":"在果蝇脑癌模型中，肿瘤生长受宿主组织抵抗力与细胞竞争的双相互作调控。早期皮层胶质细胞渗入肿瘤并依靠内在机制抵抗其生长；随着肿瘤进展，细胞竞争机制最终克服了这一宿主抗性，释放肿瘤的侵袭性扩张。该研究揭示了中枢神经系统肿瘤微环境中复杂的时序动态和形态、分子层面的改变。","scd":{"b":7.0,"i":1.0,"r":7.0,"d":4.0,"t":5.0},"kp":["[肿瘤发展机制]: 细胞竞争能够克服宿主皮质胶质细胞网络的抵抗力从而释放并促进脑癌肿瘤生长"]},{"i":39493,"as":"线粒体与细胞核不一致（不匹配）会加速自然果蝇群体与年龄相关的线粒体功能衰退，增加活性氧（ROS）产生并缩短寿命。研究发现，通过早期饮食干预诱导的轻度线粒体应激可有效抵消这些负面影响，促进线粒体稳态并延长寿命。这揭示了基因间互作在自然种群衰老轨迹中的决定性作用。","scd":{"b":7.0,"i":1.0,"r":7.0,"d":5.0,"t":5.0},"kp":["[线粒体核不一致性]: 加速年龄相关的线粒体衰退并提升活性氧(ROS)水平"]},{"i":39494,"as":"利用单细胞和空间转录组学技术，研究定义了五种转录特征不同且空间分布离散的前庭神经节神经元（VGN）细胞类型。这些细胞类型展现出器官特异性的神经支配模式，靶向器官内的特定区域并形成特征性突触终端。针对每种细胞类型开发的遗传标记工具，进一步阐明了其在前庭系统视觉稳定和姿势平衡中的具体功能。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[前庭神经节神经元细胞]: 具有空间分辨特征的5种转录学上截然不同的细胞类型"]},{"i":39495,"as":"研究发现拟南芥中的三种BSU1-LIKE（BSL1-3）磷酸酶是合子极性建立的必需正向调节因子。它们通过调节促分裂原活化蛋白（MAP）激酶级联通路（YODA-MPK3/MPK6）控制合子的极性生长和不对称分裂。BSL1-3功能缺失会导致非极性胚胎。该调控通路独立于油菜素类固醇，而其家族创始成员BSU1在此过程中非必需。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":5.0,"t":5.0},"kp":["[合子极性与早期胚胎发生调节]: 拟南芥BSL1-3磷酸酶是MAP激酶信号传导途径中独立于油菜素类固醇的必需正向调节因子"]},{"i":39496,"as":"在莱茵衣藻中，GUN4蛋白及其配体藻蓝胆素（PCB）在镁螯合酶H亚基（CHLH1）降解和叶绿素合成中具有光保护作用。缺乏GUN4或血红素加氧酶HMOX1会导致镁螯合酶底物原卟啉IX（PPIX）大量积累。PPIX是单线态氧的有效产生源，该机制揭示了通过GUN4共价加合物防止光损伤的分子途径。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[叶绿素生物合成中的光保护机制]: 光胁迫下叶绿素合成的丧失与镁螯合酶H亚基(CHLH1)的降解密切相关","[GUN4蛋白及配体]: 植物胆素(PCB)配体或GUN4蛋白的缺失会加剧由光胁迫引起的CHLH1降解"]},{"i":39497,"as":"为量化神经元特性对单细胞功能复杂度的贡献，研究人员提出了一种基于深度学习的功能复杂度指数（FCI）框架。该框架专门用于评估神经元的输入-输出复杂性。通过运用该指标对比人类与其他物种（如啮齿动物）的皮质锥体神经元，旨在揭示人类皮质神经元在形态和生理特征上的独特性质，从而解释人类所具备的高级认知能力。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["[人类皮质神经元]: 其独特的树突形态和突触非线性特征显著增强了神经元的功能复杂性"]},{"i":39498,"as":"自身免疫性葡萄膜炎是由白细胞浸润视网膜引起的致盲性炎症，视网膜血管内皮细胞的早期激活是关键。研究发现小萜类化合物Costunolide (COS)能强效抑制视网膜内皮炎症并减缓疾病进展。蛋白质组学分析确定了内皮促炎特征。对337种萜类化合物的筛选证实，COS能显著抑制TNF-α诱导的粘附分子上调，其作用机制是通过直接靶向USP15来阻断T细胞的粘附与渗出。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[自身免疫性葡萄膜炎治疗]: Costunolide (COS)通过靶向USP15有效抑制TNF-α诱导的视网膜内皮细胞炎症"]},{"i":39499,"as":"HIV衣壳核心在进入细胞核前需穿过核孔复合体(NPC)，这一过程依赖衣壳蛋白(CA)与核孔蛋白中苯丙氨酸-甘氨酸(FG)重复序列的直接相互作用。FG重复序列分为三种典型基序并在NPC轴上呈差异化分布。研究证明，HIV衣壳与不同FG重复序列的结合亲和力存在显著差异。特别是位于中央通道的NUP98中的GLFG基序，其与CA的结合亲和力显著高于常规的FxFG基序，支持病毒通过亲和力梯度进入细胞核的机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[HIV-1核孔复合体进入机制]: HIV衣壳依赖于与核孔蛋白(NUPs)中FG重复序列相互作用产生的亲和力梯度进入细胞核"]},{"i":39500,"as":"内罗病毒是缺乏有效疗法的蜱传病原体，其核蛋白(NP)在病毒基因组包裹中发挥关键作用。对塔城蜱病毒1号（TcTV1）NP的研究发现，该NP以序列非特异性方式结合核酸，并结合后组装成基于四聚体的核糖核蛋白复合物，伴随显著的构象重排以促进其聚合。此外，TcTV1 NP除了具备包裹RNA的功能外，还表现出内在的核酸内切酶活性，揭示了其在病毒复制过程中的额外重要功能。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[内罗病毒核蛋白功能特征]: 代表性内罗病毒TcTV1的核蛋白表现出序列非特异性结合核酸的特征，且具备核酸内切酶活性"]},{"i":39501,"as":"研究提出利用交流驱动的原子约瑟夫森结作为量子流体中三维孤波的纯净可调源。根据结势垒高度的不同，发射的激子低速下表现为涡环，在声速附近则表现为无涡度的稀疏脉冲，涵盖了完整的Jones-Roberts孤子族。Shapiro阶梯现象使孤波的发射具有确定性：在第一、二、三阶梯上，每个驱动周期分别发射一、二、三个孤波激子，实现了对单激子和多激子状态的可控生成及其相互作用动力学的详细研究。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[3D涡流受控生成驱动机制]: 交流驱动的原子约瑟夫森结","[发射激发态与势垒高度的依赖关系]: 势垒高度低时表现为低速下的涡环，势垒高度在声速附近时表现为无涡度稀疏脉冲","[Shapiro台阶现象发射特征]: 在第一、第二、第三Shapiro台阶上，结的发射具有确定性"]},{"i":39502,"as":"细菌肽聚糖片段作为病原体相关分子模式，通过NOD2信号通路激活哺乳动物先天免疫系统。由于NOD2是胞内传感器，胞苷二磷酸胞壁酰二肽(MDP)一直被认为是最小的NOD2激动剂。近期研究表明，MDP需被哺乳动物N-乙酰氨基葡萄糖激酶(NAGK)进行细胞内磷酸化，这是激活NOD2的关键先决条件。本研究深入探讨了糖和茎肽结构不同的各种细菌PGN在哺乳动物细胞内是如何进行结构修饰，进而影响NOD2信号传导。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[NOD2信号激动剂]: 胞壁酰二肽(MDP)是引发NOD2免疫响应的最小天然肽聚糖片段激动剂","[NOD2信号前置修饰]: 哺乳动物细胞内会对MDP进行磷酸化修饰以调节后续的NOD2信号传导"]},{"i":39503,"as":"TMPRSS2:ERG基因融合在约50%的欧洲血统前列腺癌中通过过表达ERG转录因子驱动肿瘤发生。尽管ERG是关键的致癌驱动因素，但因缺乏酶活性和明显的配体结合口袋曾被认为是“不可成药”靶点。研究证实转移性前列腺癌对ERG存在持续依赖性，并在其N末端PNT结构域内发现了一个可成药口袋。利用shRNA系统证明耗竭ERG能显著抑制癌细胞生长，确立了ERG作为前列腺癌直接治疗靶点。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["基因融合发生率[欧洲血统前列腺癌患者]: 约50%","致癌驱动机制[TMPRSS2:ERG基因融合]: 通过ERG转录因子的异常过表达驱动肿瘤发生","靶点成药性挑战[ERG转录因子]: 缺乏酶活性且无明显可结合口袋，曾被认为是不可成药的"]},{"i":39504,"as":"体内测量表明，部分突触的动态变化可持续数月，这与某些记忆的终生持久性密切相关。在蛋白质水平上，大多数蛋白质在降解前仅能存在很短时间，但近期工作在突触部位识别出了一群寿命极长的蛋白质。这些长寿蛋白质被认为可能是维持特定突触长期稳定性和记忆持久性的关键分子基础。研究聚焦于探讨突触蛋白周转过程中的性别差异和经验依赖性调节机制。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["突触动态持续时间[体内测量]: 部分突触可持续数月","记忆持久性[生物体层面]: 可持续终生"]},{"i":39505,"as":"研究引入了系综瞬态密度泛函理论（ETDDFT）这一实用型理论框架。该理论将用于计算分子和固体光学激发的瞬态密度泛函理论（TDDFT）与处于发展中极具潜力的系综密度泛函理论（EDFT）相结合，对现有的理论方法进行了广义扩展，为相关量子物理与化学计算提供了新的工具。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":5.0,"t":7.0},"kp":["[计算光学激发的标准方法]: 使用时间依赖密度泛函理论(TDDFT)","[正开发的替代方案]: 使用系综密度泛函理论(EDFT)","[结合两者的实用理论]: 系综时间依赖密度泛函理论(ETDDFT)","[发表期刊及期号]: Phys. Rev. Lett. 137, 028002","[发布时间]: 2026年7月7日"]},{"i":39506,"as":"连续变量量子系统是量子计算、通信和传感的基础。传统的波函数或密度矩阵表示法在实际应用中往往不切实际。研究利用量子力学的层析图像作为一种易于处理的替代方案，提出了一种非参数学习方法，专门用于学习连续变量系统中的非高斯量子态，为复杂量子态的表征与分析提供了新的技术途径。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":5.0,"t":9.0},"kp":["[量子态层析表征方法]: 采用非参数学习来表征连续变量系统的非高斯量子态"]},{"i":39507,"as":"研究首次在实验上演示了利用相对论性空心拉盖尔-高斯(LG)激光器，在直接激光加速机制下实现电子的定向和准直加速。电子被有效限制在沿反射激光方向的中空场分布内。该实验结果为强激光等离子体相互作用和高能电子束的精确控制提供了重要的实验依据与技术突破。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":7.0,"t":9.0},"kp":["[电子加速激光器]: 相对论性空心拉盖尔-高斯(LG)激光器","[电子加速机制]: 电子被限制在沿反射激光方向的空心场分布内的直接激光加速机制"]},{"i":39508,"as":"研究探讨了在具有可调贝里曲率的单风味金属中，声子介导的配对现象。在无贝里曲率的情况下，研究发现了出人意料的物理现象：纯粹由延迟效应催生出p波超导性，而静态的Bardeen-Cooper-Schrieffer (BCS)近似无法预测这一现象。这为声子介导的超导机制提供了全新的理论视角。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":9.0},"kp":["超导类型[纯延迟效应及无Berry曲率单味金属]: p波超导性","[超导配对机制]: 声子介导的延迟效应"]},{"i":39509,"as":"热力学临界场(Bc)能够直接反映超导凝聚能，但对其随压力变化的研究少于临界温度。研究通过μ子自旋弛豫测量方法，获取了铅热力学临界场的压力依赖关系精确数据。该实验结果为压力驱动下弱耦合超导性的演化过程提供了直接且关键的热力学证据。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":9.0},"kp":["[热力学临界场测量方法]: μ子自旋旋转弛豫测量"]},{"i":39510,"as":"量子几何由量子度规和贝里曲率表征，是理解量子材料中诸多物理现象的强大框架，但其在非周期系统中的行为依然未知。研究利用重正化群方法，揭示了非周期准晶体系统中量子几何谱发散增强的普遍机制，并发现其中存在量子几何谱的层次结构，拓展了对复杂量子体系几何特性的认知。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":5.0,"t":9.0},"kp":["[量子几何发散增强机制]: 准晶体中量子几何谱的通用机制（重正化群研究）"]},{"i":39511,"as":"超对称共形场论是量子场论的一个独特子集，能为强耦合临界现象提供深刻见解。研究在模糊球模型上提出了一种微观且非微扰的物理实现方案，成功展示并证实了三维N=1超共形伊辛临界点的出现，为研究三维强耦合量子临界现象提供了新的非微扰平台。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":5.0,"t":9.0},"kp":["维度[临界现象]: 3维","超对称[共形场论]: N=1","临界点[模型类型]: 超共形伊辛临界点","实现方式[临界点研究]: 微观和非微扰"]},{"i":39512,"as":"p波磁体是一种新型磁性，在动量空间中表现出奇宇称和时间反演对称的自旋劈裂，在自旋电子学应用中极具前景。针对其基本物理机制理论认知不足的问题，研究构建了等效的p波磁体的量子自旋模型，为深入理解该类新型磁性材料的奇异性质提供了基础理论工具。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":5.0,"t":9.0},"kp":["自旋劈裂特性[等价p波磁体]: 动量空间中的奇宇称、时间反演对称自旋劈裂","[等价p波磁体]: 自旋电子学应用的有潜力的平台"]},{"i":39513,"as":"速度环流是研究湍流能量级联的核心基本量。近期理论与数值研究指出，环流作为一种几何观测量，通过面积法则和独特的双分形特性揭示了湍流的间歇性。研究在三维牛顿流体和聚合湍流中，成功完成了环流面积法则和双分形现象的实验观察，印证了此前的理论预测。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":5.0,"t":9.0},"kp":["[三维湍流(含聚合湍流)速度环流]: 实验观察到通过面积法则和双分形来捕捉间歇性的几何现象"]},{"i":39514,"as":"交变磁态和补偿亚铁磁态是两类零净磁化强度的磁有序，它们均结合了反铁磁补偿与类铁磁自旋劈裂。交变磁体的自旋劈裂源于晶体对称性并在动量空间交替；而补偿亚铁磁体则依赖不同子晶格。研究证明，通过化学对称性破缺机制，能够实现交变磁态与补偿亚铁磁态这两种零净磁化状态之间的相互转换。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":9.0},"kp":["调控机制[交变磁态与补偿亚铁磁态转换]: 化学对称性破缺","自旋劈裂机制[交变磁体]: 源于晶体对称性并在动量空间中交替","自旋劈裂机制[补偿亚铁磁体]: 表现出类似铁磁性的自旋劈裂"]},{"i":39515,"as":"研究描述了一种几何现象：由简并戈德斯通模组成的行波在传播过后，会留下一个转变后的基态。在三角海森堡反铁磁体中，一束圆偏振自旋波脉冲能够使面内的自旋发生旋转。通过求解非线性方程，研究为该几何自旋旋转现象提供了精确解，揭示了自旋波对磁体基态的几何操控机制。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":5.0,"t":9.0},"kp":["自旋面内旋转机制[三角海森堡反铁磁体]: 由圆偏振自旋波脉冲构成的退化Goldstone模行波引起的几何现象"]},{"i":39516,"as":"多铁性氧化物因同时具备铁电和磁有序而成为研究关联量子现象的核心。通常在厚度趋近二维极限时，去极化场等效应会强烈抑制其铁电性和磁性。然而，研究证实六方LuFeO3薄膜在趋近二维极限的条件下依然能够保持多铁性，打破了传统认知，为二维多铁性材料的设计与器件应用提供了重要依据。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":6.0,"t":8.0},"kp":["铁电与磁有序态[二维极限下的六方LuFeO3薄膜]: 在二维极限下共存（多铁性）"]},{"i":39517,"as":"本文提出了一种量子能量截断太赫兹相干断层扫描技术。该技术利用太赫兹能量与分子振动量子相匹配时的共振光子损失现象，能够实现分子物种特异性太赫兹响应的高局域化提取。通过分析反射的太赫兹辐射，该方法为三维宽带宽的相干断层扫描提供了一种全新的技术路径，并发表于《物理评论快报》。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":7.0,"t":8.0},"kp":["检测机制[量子能量截断太赫兹相干断层扫描]: 利用太赫兹能量匹配分子振动量子时的共振光子损失技术","[三维量子能量截断太赫兹相干断层扫描]: 实现对分子物种特异性的太赫兹响应的高度局部化提取"]},{"i":39518,"as":"本文研究了平均场Ising模型，在该模型中，耦合作用通过反馈函数依赖于磁化强度。研究识别出了“混合阶段”，并证明在绝对零度下，只要反馈足够强，这种混合阶段就可以保持稳定。此外，稳定的混合阶段始终处于超稳定状态，这意味着任何扰动都会以特定的方式发生衰减。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":6.0,"t":8.0},"kp":["耦合条件[基于反馈函数的磁化强度依赖]: 平均场伊辛模型","混合阶段稳定性[零温度且反馈足够强条件]: 稳定","扰动响应特性[稳定混合阶段条件]: 始终超稳定"]},{"i":39519,"as":"Ising模型和气液系统中的二阶相变具有相同的普适类和临界指数，但气液系统的哈密顿量中并不存在Z2对称性。研究探讨了临界现象中的核心问题：不对称性的影响。文章分析了超临界与亚临界之间的对应关系以及不对称效应，并着重研究了临界点附近的反对称校正现象，揭示了不对称性对系统相变的具体作用。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":5.0,"t":8.0},"kp":["[系统特征]: 二阶相变属于同一普适类","[系统特征]: 具有相同的临界指数","[系统特征]: 液气系统哈密顿量缺乏Z2对称性"]},{"i":39520,"as":"控制化学键的断裂是分子物理学的长期目标。本文研究了红外纳米空腔中分子的激光解离过程，旨在理解化学反应在腔量子电动力学（QED）强耦合机制下的行为。通过深入分析红外激光解离机制，该研究阐明了如何利用电磁真空环境来增强分子的红外激光解离效应，为在少分子体系中精确控制化学键断裂提供了理论基础。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[物理现象]: 利用电磁真空增强红外激光解离","[研究系统]: 红外纳米腔（Infrared nanocavities）","[耦合机制]: 少数分子与腔量子电动力学（cavity QED）的奇异耦合态","[研究对象]: 电磁真空增强环境下的化学键断裂控制与化学反应机理"]},{"i":39521,"as":"本文研究了具有Dzyaloshinskii-Moriya相互作用的二维磁性材料在周期性振荡磁场下的非平衡响应。通过大量蒙特卡罗模拟，研究揭示了一种动态重入斯格明子相。这一发现解决了受驱动拓扑物质领域的一个核心开放问题，展示了振荡磁场对拓扑磁结构动态演化的重要影响。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["拓扑物态响应[具有Dzyaloshinskii-Moriya相互作用的二维磁体在周期性振荡磁场下]: 发现动态重入斯格明子相"]},{"i":39522,"as":"连续变量量子微梳可为集成量子信息处理提供紧凑且频率复用的纠缠模式源。尽管目前已在芯片上实现了由克尔效应诱导的双模压缩，但实现均匀的光谱扩展仍具挑战。本文提出并验证了一种在高Q值微环谐振腔中生成光谱均匀且连续可变的量子微梳的技术方案，推动了集成量子光源的发展。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":7.0,"t":8.0},"kp":["光源特性[连续可变量子微梳]: 提供用于集成量子信息处理的紧凑型、频分复用的纠缠模光源","[高Q微腔]: 实现了光谱均匀的连续可变量子微梳"]},{"i":39523,"as":"携带轨道角动量(OAM)的微波激射在高容量通信、精密传感和雷达成像等领域具有巨大潜力，但传统微波激射器无法产生内置OAM发射。本文利用光子时间晶体的概念，提出并实现了一种产生微波涡旋束激光的新方法。该技术突破了传统微波激射的限制，成功生成了携带轨道角动量的微波激光束。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":8.0},"kp":["[微波涡旋束激光产生]: 通过光子时间晶体实现具有轨道角动量(OAM)的微波激射发射"]},{"i":39524,"as":"Floquet工程通过周期性驱动定制系统，是操控物质拓扑态和创造非平衡拓扑现象的强大工具。本文利用Floquet工程思想，在单光子干涉系统中理论预测并实验实现了拓扑复能带辫子。该研究展示了如何通过周期性驱动设计复杂的能带结构，成功在单光子干涉体系中构建出具有特定拓扑性质的复能带辫子结构。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["拓扑能带调控[Floquet设计]: 利用周期性驱动定制系统以创造超越静态情景的非平衡拓扑复能带辫子","[单光子干涉]: 实验实现了Floquet设计的拓扑复能带辫子"]},{"i":39525,"as":"基布尔-祖雷克机制（KZM）预测在以有限速率驱动的连续相变中会自发形成拓扑缺陷。本文提出在由热猝灭诱导的玻色-爱因斯坦凝聚（BEC）过程中，可以通过KZM产生自发量子湍流。通过数值模拟验证了这一机制，为在新生玻色-爱因斯坦凝聚态中研究量子湍流的形成和演化提供了新的理论框架。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[自发量子湍流产生机制]: 基于基布尔-祖雷克机制(KZM)通过热淬灭诱导玻色-爱因斯坦凝聚产生"]},{"i":39526,"as":"本文分析了不同形式的噪声对一维无相互作用费米子系统的影响。在强噪声极限下，研究在温和的假设条件下证明，在热力学极限下，费米子关联矩阵的统计规律遵循一种普适形式。这种普适形式由近期发展的理论所描述，揭示了无噪声费米子传输过程中普适性的出现，为理解噪声对费米子系统的整体影响提供了深刻见解。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":4.0,"t":8.0},"kp":["[费米子关联矩阵统计规律]: 在热力学极限和强噪声极限下遵循普遍形式"]},{"i":39527,"as":"量子多体系统中的纠缠动力学研究通常集中于初始乘积态。本文深入探讨了从初始纠缠态出发的更为丰富的动力学过程，揭示了跨越多体局域化（MBL）到随机量子电路等多种不同系统的普适模式。该研究将纠缠生成与传输统一起来，为理解初始纠缠态在复杂量子系统中的纠缠生长机制提供了统一的视角。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":4.0,"t":8.0},"kp":["[纠缠生长动力学特征]: 从初始纠缠态（而非纯态）演化出跨越多体局域化等系统的普适规律"]},{"i":39528,"as":"本文构建了参数化的等距张量网络状态（称为“骨架”），用于探索阿贝尔拓扑序的相，并可在量子处理器上高效实现。研究获得了弦网不动点的稳定有限关联长度形变，这些形变与阿贝尔拓扑序相对应。该成果提供了一种在量子处理器上模拟和研究拓扑相变的实用且高效的张量网络方法。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":8.0},"kp":["拓扑相变探索模型[阿贝尔弦网]: 等距张量网络骨架","[量子处理器实现]: 阿贝尔拓扑序相位的稳定有限关联长度形变可高效实现"]},{"i":39529,"as":"量子系统的高效模拟通常依赖于量子态的结构特性。受量子自旋系统高温吉布斯态中纠缠突然死亡相关结果的启发，本文研究了有界自旋系统的高温费米子吉布斯态。研究证明，高温费米子吉布斯态可以被表示为高斯态的混合。这一发现揭示了高温下费米子系统的量子态结构，为高温量子系统的高效经典模拟提供了理论依据。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":4.0,"t":8.0},"kp":["高温吉布斯态[有界算子费米子系统]: 表现为高斯态的混合"]},{"i":39530,"as":"尽管量子资源能够实现海森堡极限的传感精度，但现实噪声设备中的不可行定理表明这种极限通常无法达到。虽然量子纠错（QEC）可以抑制噪声，但其在量子传感中的应用受到严格限制。本文提出利用不定因果阶进行量子纠错，成功实现了抗噪的海森堡有限量子传感，突破了现实噪声环境下的传感精度限制。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":8.0},"kp":["[抗噪量子传感机制]: 利用量子纠错(QEC)并结合不定因果阶克服不可行定理限制","[量子传感精度]: 实现抗噪海森堡极限标度"]},{"i":39531,"as":"生成非高斯态并将其转化为传输波包对于可扩展的容错量子计算至关重要且充满挑战。本文提出了一种硬件高效的方法，通过将工程化的非线性耗散与线性传输相结合，同时实现了非高斯波包量子态的生成与传输。该方法为构建可扩展的量子计算系统提供了一种高效且实用的非高斯态制备和传输途径。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":8.0},"kp":["[非高斯态波包生成方案]: 结合工程化非线性耗散与线性变换的硬件高效方法"]},{"i":39532,"as":"引力波信号通常在真空假设下进行解释，即忽略天体物理环境的影响。对于诸如极端质量比螺旋（EMRIs）等低频引力波源，这种真空假设预期将会失效。本文提出了一种自洽的方法，用于测试EMRIs中天体物理环境的影响。该研究修正了传统真空假设的局限，为下一代空间引力波探测器（如LISA）的数据分析提供了包含环境效应的理论框架。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":4.0,"t":8.0},"kp":["[真空假设适用性]: 对于低频引力波源（如极端质量比螺旋）破裂，需进行天体物理环境的自洽测试"]},{"i":39533,"as":"","scd":null,"kp":[]},{"i":39534,"as":"","scd":null,"kp":[]},{"i":39535,"as":"","scd":null,"kp":[]},{"i":39536,"as":"本文通过研究全息热关联函数，在自旋链中定义了一种黑洞状态。研究聚焦于海森堡模型，通过计算这种黑洞状态的纠缠熵、真空形成概率和Krylov复杂度，深入探究了该状态的热力学性质与计算复杂度特性。该工作为在凝聚态物理（如自旋链）的框架下模拟和理解黑洞的物理特性提供了一种可行的量子信息视角。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[自旋链黑洞态表征]: 通过全息热关联函数定义，并展示纠缠熵、空虚形成概率及Krylov复杂度等特征"]},{"i":39537,"as":"相对论中弛豫过程通常被认为在洛伦兹变换下经历时间膨胀。该研究表明这一直觉在一般情况下是失效的。由于同时性的相对性，洛伦兹变换能将单一的弛豫模式分裂为连续的激发态，其展宽由特定的最大值决定。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[洛伦兹变换重塑弛豫谱]: 洛伦兹变换可以将单一弛豫模式分裂为连续激发态"]},{"i":39538,"as":"电磁阱中激光冷却的离子提供了一种可调的介观系统，其势场、非线性库仑相互作用与激光散射的相互作用能产生丰富的动力学。研究在金字塔库仑团簇中实现了对称控制的热激活切换，以此检验了克莱默-兰格理论。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[电磁阱中激光冷却离子]: 实现了对称控制的热激活转换"]},{"i":39539,"as":"腔量子电动力学通过光与物质相互作用产生非经典光态。由于谐振器要求相互冲突，在单个腔内同时实现珀塞尔增益和定制波前控制是一项重大挑战。该研究成功解决了这一问题，实现了超空腔量子电动力学的光物质相互作用调控。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[超空腔量子电动力学核心挑战]: 需同时实现珀塞尔(Purcell)增强与定制化的波包"]},{"i":39540,"as":"研究探讨了起皱Mylar（聚酯）薄膜在力和位移控制条件下的对数弛豫行为。通过循环弛豫实验，揭示了一族向平衡演化的连续力-位移曲线，这些曲线受限于瞬时极限和完全弛豫极限。","scd":{"b":5.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["对数弛豫行为[褶皱Mylar薄膜受力及位移控制条件]: 呈现连续演化的力-位移曲线并趋于平衡"]},{"i":39541,"as":"量子网络是构建大规模量子信息系统的基础设施。研究在1.2公里长的光纤上实现了时间多模的离子-离子纠缠。这是实现完全功能性量子网络和量子中继器的关键步骤，有助于分布式量子计算和长距离量子通信。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":8.0,"t":9.0},"kp":["传输距离[时间多模离子-离子纠缠分发]: 1.2公里光纤","[量子网络/中继器]: 分布式量子计算、远距离量子通信和量子传感的基础设施"]},{"i":39542,"as":"为解决全固态氟化物电池电解质的固有缺陷，研究设计了钾/锶双掺杂策略，通过固相反应合成了具有萤石结构的氟离子导体β-Pb0.88Sr0.08K0.04F1.96。KF掺杂引入了大量氟空位缺陷提高浓度，SrF2与PbF2形成连续固溶体分散了氟空位，从而同时增强了离子电导率和相稳定性。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["掺杂配方[β-PbF2基固态氟化物电解质]: β-Pb0.88Sr0.08K0.04F1.96","[K/Sr双掺杂策略]: 同步提升氟离子电导率和相稳定性"]},{"i":39543,"as":"针对冶金制造领域关于板坯撕裂及其表面信号受被动余量强度控制的研究论文发布作者更正声明。","scd":null,"kp":["[板坯冶金制造]: 撕裂及其表面信号受被动余量强度控制"]},{"i":39544,"as":"研究通过将巴西449个地区2000至2019年间1.845亿份患者级住院记录与每日特定野火PM2.5估算值相关联，量化了短期野火细颗粒物的医院负担。数据显示，野火PM2.5每增加1 µg/m³，全因、呼吸系统及心血管疾病的住院费用分别增加0.36%、1.59%和0.25%，住院时间也相应延长。","scd":{"b":4.0,"i":6.0,"r":8.0,"d":9.0,"t":6.0},"kp":["PM2.5浓度增量[野火短期暴露]: 每增加1 µg/m³","研究空间分辨率[巴西医院负担量化]: 0.25°","患者样本规模[巴西地区]: 1.845亿","研究时间跨度[巴西区域医院数据]: 2000–2019"]},{"i":39545,"as":"研究利用三氧同位素数据揭示了瑞典基鲁纳附近氧化铁-磷灰石（IOA）矿床磁铁矿中含有高浓度的源自蒸发硫酸盐的氧。研究表明，硅酸盐岩浆对蒸发岩的巨大同化作用导致硫酸盐氧化岩浆中的亚铁，促成了不相容的高铁熔体或磁铁的形成，进而分离形成矿床。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["氧同位素来源[Kiruna等氧化铁-磷灰石(IOA)型磁铁矿]: 蒸发硫酸盐","[成矿机制(硅酸盐岩浆同化)]: 大量同化蒸发岩引发IOA型矿床形成"]},{"i":39546,"as":"近期研究对澳大利亚皮尔巴拉克拉通31亿年前保存完好的火山岩序列进行了高分辨率地球化学分析。研究发现，该岩石记录了包括拉斑玄武岩、钙碱性岩和迄今最古老的大型玻安岩在内的现代弧火山岩典型特征。模型表明，产生这些多样熔岩需要具有不同亏损历史的多个地幔源，且导致流体辅助熔融的地幔含水量远超原始地幔水平，接近现代地幔楔的水饱和状态。由此推断，这种含水熔融是由“滴落俯冲”触发的，即短暂倾斜的含水岩石圈沉陷，且未形成横向连续的板块边界。这一发现为太古宙火山活动与板块俯冲的关联提供了新的见解。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["火山岩年龄[现代弧状含水量源头]: 31亿年前 (3.13-3.10 Ga)","原始岩浆系列[皮尔巴拉克拉通太古宙类似物]: 拉斑系列、钙碱性系列以及最早的大量真正玻安岩"]},{"i":39547,"as":"化学交联质谱（CXMS）是探测蛋白质结构动态及相互作用的重要方法。研究设计并合成了两种名为Togni交联剂（TR1和TR2）的新型双高价碘试剂。这些试剂两端具有高价碘-氟代烷基结构，可在天然条件下作为高效的共价蛋白质交联剂，实现分子内和分子间的交联。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[两栖双功能探针]: 提供明确的反应性、激活特性及天然条件兼容性，用于探测蛋白质结构、构象动力学及相互作用"]},{"i":39548,"as":"","scd":null,"kp":[]},{"i":39549,"as":"研究测量了镍同位素（67Ni、69Ni和70Ni）中νg9/2同核异能态的g因子。由于68Ni被提出为双幻核，N=40附近的镍同位素区域在实验和理论上都引起了广泛关注，该研究为解决实验证据的矛盾提供了新的测量数据。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["g因子测量目标[镍同位素 νg9/2 异构态]: $^{67,69,70}Ni$"]},{"i":39550,"as":"研究首次在162Er中鉴定出了高K能带结构。该结构基于Kπ=7(-)的同核异能态，发现其性质与在相同能带现象背景下对应的Kπ能带完全一致。这一发现填补了该同位素核结构研究的空白。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[高K能带结构]: 首次在 $^{162}Er$ 中观察到","异构态自旋宇称[$^{162}Er$高K能带]: K^π = 7^(-)"]},{"i":39551,"as":"研究计算了锕系裂变中钡（Ba）和氙链的同位素分辨发后中子产额，并与评估参考数据进行了基准比对。研究强调了固定裂片电荷Z下的同位素链Y(Nf)以及重轻裂片相关性的一致性。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":6.0,"t":6.0},"kp":["[锕系裂变产率]: 计算并评估了同位素分辨的反中子裂变产额及重轻碎片关联系统学（包含Ba和Xe同位素链）"]},{"i":39552,"as":"研究通过引入中子-质子双壳层和价核子校正作为主要结构效应，改进了α衰变的Geiger-Nuttall系统学框架。此外，研究还阐明了由势垒穿透率展开推导出的二阶能量相关项的作用，从而提高了预测精度。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":6.0,"t":6.0},"kp":["[Geiger-Nuttall系统学改进]: 引入中子-质子双壳层和价核子校正以优化α衰变理论框架"]},{"i":39553,"as":"117mSn和通过119mTe发生器产生的119Sb是用于骨关节炎和小质量肿瘤俄歇治疗的有前途的放射性核素。实验通过在劳伦斯伯克利国家实验室用质子轰击天然锑，生产了117mSn和119mTe，并为带电粒子反应建模提供了数据支撑。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[靶向俄歇治疗]: 有望用于骨关节炎和小体积肿瘤治疗","[放射性核素生产]: 利用质子轰击天然锑制备$^{117m}\\mathrm{Sn}$并通过$^{119m}\\mathrm{Te}$发生器制备$^{119}\\mathrm{Sb}$"]},{"i":39554,"as":"少数缺乏中子的稳定“p核”无法通过天体物理中子俘获过程产生，而是通过在现有的r和s过程种子上发生γ诱导反应产生。研究测量了天体物理p过程中102Pd(γ,p)和102Pd(γ,α)的直接截面，为理解p核的合成提供了关键数据。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[天体物理p过程研究]: 直接测量了$^{102}\\mathrm{Pd}(γ,p)$和$^{102}\\mathrm{Pd}(γ,α)$反应的横截面"]},{"i":39555,"as":"血吸虫病的发病率和死亡率主要由虫卵引发的肉芽肿及随后的纤维化驱动。研究结合单细胞RNA测序和多重免疫荧光技术，表征了小鼠肝肉芽肿的免疫细胞动态。研究发现虫卵改变了肝脏免疫细胞组成，特别是引起广泛的中性粒细胞募集和分化，并验证了两种中性粒细胞亚群的功能作用。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[单细胞RNA测序与多重免疫荧光结合]: 用于表征日本血吸虫感染小鼠肝肉芽肿形成和演化过程中的细胞异质性及免疫微环境"]},{"i":39556,"as":"为解决钙钛矿太阳能电池商业化中的稳定性问题，研究将亚磷酸三苯酯引入钙钛矿前驱体溶液中。该添加剂不仅能通过防止碘化物氧化和有机阳离子去质子化来稳定前驱体溶液，还能形成结晶度更高、缺陷密度更低的钙钛矿薄膜。优化后的n-i-p器件获得了26.6%的认证光电转换效率。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[三苯基亚磷酸酯添加剂]: 防止碘化物氧化，实现钙钛矿太阳能电池全生命周期（前驱体溶液至薄膜）的耐老化化学保护"]},{"i":39557,"as":"研究报道了一种由P桥接的铁铜双原子催化剂，形成了独特的N3Fe-P1-CuN3结构。Fe-P-Cu桥接键诱导了d-p-d梯度轨道耦合，建立了从铜（电子供体）到铁（电子受体）的定向电子转移通道。该催化剂能活化过硫酸根，高选择性地产生活性铁氧物种（稳态浓度达5.80×10⁻¹⁰ M），实现水污染物的超快降解和细菌灭活。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["配位结构[P桥接Fe-Cu双原子催化剂]: 形成独特的N3Fe-P1-CuN3结构","电子转移机制[Fe-P-Cu桥接键]: 诱导d-p-d梯度轨道耦合，构建定向电子转移通道"]},{"i":39558,"as":"","scd":null,"kp":[]},{"i":39559,"as":"本研究提出了一种基于Cas6f的便携式多重翻译抑制系统（MORTISE），用于革兰氏阴性菌中可编程的翻译抑制。该系统无需依赖宿主的Hfq蛋白或核糖核酸酶即可发挥作用，在大肠杆菌和恶臭假单胞菌中均能稳定运行。通过染色体报告基因检测证实，当向导RNA和靶标转录水平相匹配时，该系统在两种细菌中均能实现有效的基因抑制，为合成生物学中的多重基因调控提供了有效工具。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[MORTISE翻译抑制系统]: 基于Cas6f的紧凑、可编程平台，实现多路复用和正交的细菌翻译抑制"]},{"i":39560,"as":"","scd":null,"kp":[]},{"i":39561,"as":"","scd":null,"kp":[]},{"i":39562,"as":"","scd":null,"kp":[]},{"i":39563,"as":"","scd":null,"kp":[]},{"i":39564,"as":"研究结合稳态连续培养、功能基因组学和计算方法，对模式产乙酸菌自乙醇梭菌（Clostridium autoethanogenum）进行了全基因组范围的蛋白-RNA相互作用分析。目的是探究与自养生长相关的基因功能和代谢调控机制。分析结果检测到了有限且不耦合的转录和翻译现象，系统级分析预测该自养微生物中不存在与自养相关的蛋白-RNA相互作用。这为产乙酸菌细胞工厂的理性工程改造提供了数据参考。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[自发酵基因调控(梭菌属系统级分析)]: 预测自养相关蛋白-RNA相互作用网络中存在缺失/不存在的相互作用机制"]},{"i":39565,"as":"","scd":null,"kp":[]},{"i":39566,"as":"研究利用体内CRISPR删除筛选技术分析了小细胞肺癌（SCLC）化疗耐药的遗传基础。发现转录共激活因子SAGA复合物成分与耐药性高度相关。实验证明，在两种化疗敏感的PDX模型中，删除SAGA去泛素化酶USP22会导致对顺铂和依托泊苷产生耐药性。在携带USP22纯合截断突变的PDX模型中恢复其表达，可使肿瘤重新对化疗敏感。USP22缺失增加了基因H2AK119的单泛素化。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[基因筛选]: 使用体内CRISPR敲除筛选患者来源的异种移植(PDX)模型","耐药机制[小细胞肺癌化疗]: USP22去泛素化酶(及SAGA复合物组分)的缺失导致对细胞毒性化疗产生耐药性"]},{"i":39567,"as":"北极海冰减少从根本上改变了大气与海洋之间的动量传递。研究应用概率聚类框架对26年的状态估计进行分析，发现北极埃克曼抽吸被划分为七种不同的物理状态。这些状态反映了风、海冰和地缘强迫的不同组合。空间上，波弗特海频繁发生状态转换和持续的冰-地缘耦合状态；而北欧和欧亚海域则表现出不同的动力学特征。这些持久的状态使得北极动态变化具有可预测性。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":6.0,"t":4.0},"kp":["物理状态分类数[Eskman pumping]: 七种不同的物理状态","时间跨度[状态估计数据]: 26年"]},{"i":39568,"as":"研究汇总了1950至2020年间全球10,522座城市的数据，发现极端温度变率（ETV）的轨迹因城市发展水平（HDI）不同而产生差异。高发展水平城市的ETV加剧，而低发展水平城市的ETV缓慢减弱，导致两者间存在约1.66°C的差距。累积ETV主要由事件强度驱动。利用机器学习框架分析表明，在控制气候和地理因素后，气溶胶是与ETV关联性最强的城市因素，而蓝绿空间的作用则相对一致。","scd":{"b":5.0,"i":1.0,"r":6.0,"d":8.0,"t":4.0},"kp":["ETV差异[不同发展水平城市]: 约1.66°C"]},{"i":39569,"as":"研究证实了巴伦支海次表层水中颗粒相关固氮菌具有显著的固氮作用。与亚热带研究对比显示，巴伦支海次表层水中的主要固氮生物是颗粒相关的非蓝细菌，这与温暖海域中多样的固氮群落形成对比。随着北极逐渐向寡营养化演变，揭示颗粒相关固氮作用的规模及其控制因素，对于理解全球变暖下北冰洋维持初级生产力的未来氮供应至关重要。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":5.0,"t":4.0},"kp":["固氮菌类型[巴伦支海北极次表层水]: 颗粒结合型非蓝细菌固氮菌"]},{"i":39570,"as":"通过在山地草地进行为期两年的15N示踪实验，研究评估了高二氧化碳浓度、气候变暖和干旱对植物获取氮源的影响。结果显示，尽管进行了大量施肥，植物仍有82%至88%的氮来源于土壤，从土壤中获取的氮量是肥料的4.6至7.3倍。升高二氧化碳浓度和变暖增加了植物对土壤来源氮的吸收，未增加对肥料氮的吸收。这导致植物氮输出量超过肥料输入，引发生态系统氮赤字并消耗土壤氮库。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["植物氮获取比例[气候变化条件]: 82–88%","试验方法[高山草地]: 15N-示踪试验"]},{"i":39571,"as":"研究分析了两只雄性猕猴在执行空间听觉决策任务时，初级听觉皮层（A1）和背外侧前额叶皮层（PFC）的同步神经元记录。分析揭示了明确的时间层级：感觉信息从A1单向传递到PFC；而决策相关信息在A1和PFC之间呈现双向流动。这种流动模式打破了传统认为的严格序列处理机制，表明皮层在处理感觉和决策信息时具有更复杂的动力学和时序特征。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":5.0,"t":4.0},"kp":["皮层动力学[听觉决策过程]: 打破了经典序列处理模型"]},{"i":39572,"as":"冷冻电镜结构揭示了人胞质丝氨酸-tRNA合成酶与NAD⁺依赖性脱乙酰酶SIRT2形成的复合物。NAD⁺代谢物ADP核糖（ADPR）在两种酶之间充当分子桥，与SerRS上的K414残基结合。功能上，复合物的形成通过阻断底物通道抑制了SIRT2的脱乙酰酶活性，同时SIRT2的结合通过阻止tRNA结合抑制了SerRS的氨酰化活性。这实现了SerRS和SIRT2之间代谢与翻译控制网络的相互调节。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":7.0,"t":4.0},"kp":["分子桥[SerRS和SIRT2复合物]: ADP核糖","作用位点[SIRT2活性中心内的SerRS]: K414残基"]},{"i":39573,"as":"在囊性纤维化患者的铜绿假单胞菌临床分离株中，丙酮酸脱氢酶复合物的突变引发了一种由丙酮酸分泌介导的细菌持久机制。这种突变导致胞外丙酮酸升高，有效清除活性氧（如H2O2），抑制宿主气道上皮细胞的免疫激活，从而抑制炎症反应。类似的突变也在金黄色葡萄球菌、流感嗜血菌和嗜麦芽窄食单胞菌中被发现，有助于这些细菌逃避宿主免疫并维持长期感染。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["细菌持久性机制[丙酮酸交叉喂养]: 丙酮酸脱氢酶复合物突变导致丙酮酸分泌"]},{"i":39574,"as":"炎症性肠病（IBD）中，表达在骨髓细胞上的TREM1受体被PGLYRP1等配体激活后会放大炎症反应。研究确定了TREM1信号驱动中性粒细胞炎症的两个正反馈回路：首先，被激活的中性粒细胞释放PGLYRP1，与细菌肽聚糖结合后激活TREM1，增强中性粒细胞脱颗粒、产生活性氧和NETosis；其次，单核细胞上TREM1的激活促进趋化因子分泌，招募并激活更多中性粒细胞，从而持续加剧炎症。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["受体激活物[TREM1受体]: PGLYRP1配体复合物"]},{"i":39575,"as":"为提升勃起功能障碍治疗中间充质基质细胞（MSCs）的保留率和存活率，研究通过表面工程化技术，用结合了抗血管细胞粘附分子1抗体的聚多巴胺纳米颗粒对MSCs进行修饰。多价抗体引导细胞靶向发炎的海绵体内皮，而聚多巴胺能够有效减轻活性氧造成的损伤并改善炎症微环境。该方法显著增强了MSCs在海绵体内的滞留、存活能力及整体治疗效果。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["表面工程改造[间充质基质细胞]: 结合抗血管细胞粘附分子1抗体的聚多巴胺纳米颗粒"]},{"i":39576,"as":"研究利用冷冻电子显微镜技术，揭示了蓝细菌（Thermosynechococcus vestitus）中尺寸约为2.2埃分辨率、缺乏Mn4CaO5簇的天然二聚光系统II（PSII）中间体结构。这些结构包括缺乏放氧复合物（OEC）的失活二聚体以及只有一个单体含有OEC的半活性二聚体。这些数据详细解析了天然状态下Mn4CaO5簇的组装和拆卸过程是如何与PSII亚基的结合和释放相互协调的。","scd":{"b":8.5,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["分辨率[蓝细菌天然二聚体PSII中间体冷冻电镜结构]: 约2.2埃"]},{"i":39577,"as":"","scd":null,"kp":[]},{"i":39578,"as":"一种新型肺部mRNA-脂质纳米颗粒（mRNA-LNP）疫苗使用了专门设计的可离子化脂质，能在雌性小鼠体内针对细菌性肺部感染提供快速且持久的保护，有效填补了疫苗接种后的免疫脆弱期。通过气管内给药，该mRNA-LNP疫苗能迅速将肺部中性粒细胞和巨噬细胞引导至转录预激活状态，从而增强其吞噬活性以抵御细菌感染。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":6.0,"t":5.0},"kp":["[肺部mRNA-LNP疫苗]: 采用工程化可电离脂质实现局部高水平表达并引发快速持久免疫","[免疫特点]: 快速且持久地预防细菌感染"]},{"i":39579,"as":"","scd":null,"kp":[]},{"i":39580,"as":"研究鉴定了导致亚洲与非洲栽培稻杂种不育的S19位点机制，发现两个紧密连锁的非洲稻特有基因（S19A1和S19A7）构成了“杀手-保护者”模块。杀手基因S19A1的两种选择性剪接转录本编码线粒体靶向的细胞毒性蛋白，分别导致体细胞和/或配子细胞死亡。而S19A7蛋白能与这两种毒性蛋白相互作用，彻底阻断其细胞毒性效应，从而决定杂种雄性不育性。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[S19位点杂种不育机制]: 由非洲稻等位基因特异性编码的杀手-保护者模块（S19A1和S19A7）通过选择性剪接转录本介导","[S19基因座]: 紧密连锁的两个基因"]},{"i":39581,"as":"研究提出了一种动态可重构电池组架构，通过电池单体周围的开关硬件进行智能控制，以解决传统固定配置锂离子电池组因单体差异引起的过早失效和结构低效问题。基于单体建模的统计框架评估表明，在不依赖特定电池技术的前提下，可重构电池组能显著延长电池寿命（超过20%），这在电动卡车和长途客车等高压应用场景中尤为有效，具有显著的经济和寿命效益。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[动态可重构电池架构]: 通过智能控制单个电芯周围的开关硬件，克服传统固定配置电芯不一致性和过早失效的结构低效问题","[系统效益评估]: 与具体电池技术无关的全生命周期与经济性系统级评估"]},{"i":39582,"as":"研究证明了双层范德华磁体（如CrSBr）中的扭转可以诱导空间变化的层间交换相互作用，从而稳定复杂的磁响应。实验发现，双层CrSBr在扭转约3度时表现出稳健的磁滞现象，这可以通过场依赖光致发光测量中激子能量的演变来直接追踪。双亚晶格模型表明，扭转降低了层间交换作用，使得平行和反平行自旋态在较宽的磁场范围内保持稳定。","scd":{"b":8.5,"i":2.5,"r":7.0,"d":7.0,"t":5.0},"kp":["扭转角[双层CrSBr磁体]: ~ 3°","[莫尔超晶格物理机制]: 扭转诱导空间变化的层间交换相互作用，能够稳定复杂的磁响应并表现出稳健的磁滞"]},{"i":39583,"as":"","scd":null,"kp":[]},{"i":39584,"as":"研究利用冷冻电子显微镜技术解析了31个结构（43张图谱），成功捕获了酿酒酵母RNA聚合酶II（RNAPII）转录延长复合物在整个核苷酸添加循环（NAC）中的不同阶段，包括难以捕捉的过渡中间体。研究确立了NAC期间RNAPII的结构动态连续谱，并将其分为两个协调阶段：底物诱导的复合物收紧阶段和催化后的复合物松弛阶段，揭示了RNAPII驱动基因表达的详细机制。","scd":{"b":8.5,"i":2.0,"r":8.0,"d":8.0,"t":6.0},"kp":["结构数量[RNA聚合酶II核苷酸添加循环]: 31个冷冻电镜结构（含43张图谱）","[结构表征突破]: 捕获了酿酒酵母RNAPII延伸复合物NAC过程，包含此前难以解析的过渡态中间体"]},{"i":39585,"as":"研究构建了一种NiSS-COF/Pd ICs复合催化剂，通过将镍单原子位点（NiSS）和钯金属孤立簇（Pd ICs）精确结合到共价有机框架中，优化了对亚硝酸根（NO2-）和H*的吸附强度，从而增强电催化还原NO2-为氨（NH3）的性能。该催化剂在-1.0 V（vs RHE）下实现了95.5%的极高法拉第效率和20.9 mg h-1 mgcat-1的氨产率；在-1.3 V条件下，氨产率进一步提升至35.3 mg h-1 mgcat-1。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":6.0,"t":5.0},"kp":["[复合催化剂结构]: 共价有机框架中精确掺入孤立单Ni位点与分离的Pd簇合物","[催化机制优化]: 协同优化NO2-和H*的吸附强度，解决中间体活化与氢化动力学不匹配问题"]},{"i":39586,"as":"研究基于第一性原理量子输运模拟，评估了亚5纳米栅极长度的双层β-二氧化碲（β-TeO2）场效应晶体管（FETs）的性能。由于双层β-TeO2具有独特的各向异性，在y方向上，亚5纳米栅长的n型和p型β-TeO2 FETs均能满足未来互补金属氧化物半导体（CMOS）集成的严苛要求。这使得双层β-TeO2成为首个被预测具备对称亚5纳米NMOS和PMOS性能的氧化物半导体材料。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["亚5纳米CMOS器件[双层β-TeO2半导体]: 首个预计可实现对称的N沟道和P沟道场效应晶体管"]},{"i":39587,"as":"本研究探讨了基于硫辛酸（LA）的磁共振成像水凝胶的聚合反应、粘度及弛豫性能。研究发现，使用还原剂TCEP将惰性二硫化物转化为硫醇引发剂，并利用碱使LA去质子化，可显著提升其聚合效率。通过调整碱和TCEP的添加量，水凝胶粘度可在极大范围内调节，使其能够广泛适配外用软膏或可注射水凝胶等不同应用场景。此外，研究通过改变Gd3+螯合物的内层配位或引入硫原子实现了弛豫率的灵活调控，证实了Gd3+螯合物的内层配位结构与凝胶微观环境是决定其弛豫性能的核心因素。该材料在可调谐医学影像造影剂领域展现出巨大应用潜力。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[LA水凝胶聚合条件]: 使用TCEP还原剂将惰性二硫化物转化为硫醇引发剂，并需碱去质子化溶解LA以促进聚合"]},{"i":39588,"as":"研究详细调查了阴极气体扩散电极（GDE）的压缩比对零间隙CO2电解槽（CO2RR）电化学性能的影响。实验测试了三种本质不同的碳基阴极支撑材料，并结合电化学阻抗谱和微断层扫描技术解释了阴极被逐渐压缩至40%以下时电解性能的变化规律。研究强调了在技术放大过程中，合理控制和选择电池组件的压缩率对于实现零间隙CO2电解槽长期最佳性能的重要性。","scd":{"b":4.0,"i":6.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[阴极气体扩散电极]: 压缩比显著影响零间隙CO2电解槽的电化学性能和长期最优运行"]},{"i":39589,"as":"研究开发了一种稳健的晶种生长法，在α-氧化铝基底上成功制备了厚度约3微米的连续无缺陷A520（铝富马酸盐）多晶金属有机框架（MOF）膜。研究发现，合成后的活化过程对维持膜的结构完整性至关重要。在热活化之前进行甲醇交换（ME）预处理，可以有效抑制溶剂蒸发过程中毛细管应力引起的晶格畸变。测试表明，制得的A520(ME)膜在CO2/N2和CO2/CH4气体分离中表现出优异的分子筛分性能。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["膜厚度[α-氧化铝基底A520多晶膜]: 约 3 μm","[MOF膜制备与分离]: 采用稳健的晶种生长方案制备连续致密膜，合成后活化过程决定膜结构完整性与气体分离效能"]},{"i":39590,"as":"通过分子动力学模拟，研究考察了金属离子对三种结构相似但金属离子不同的M-MOF-74膜（M为Cu、Ni、Zn）脱盐性能的影响。结果表明，Ni-MOF-74和Zn-MOF-74膜允许Na+和Cl-通过，且离子通量随驱动压力增加而增大；而Cu-MOF-74膜表现出卓越的脱盐性能，在驱动压力低于50 MPa时能完全阻挡Na+和Cl-离子的传输，实现了100%的离子截留率。同时，这三种MOF膜的水通量保持相似。","scd":{"b":4.0,"i":1.0,"r":6.0,"d":7.0,"t":5.0},"kp":["透过性能[金属有机骨架膜]: Ni-MOF-74和Zn-MOF-74允许Na+和Cl-通过，且通量随驱动压力增加而提升"]},{"i":39591,"as":"通过在超高真空条件下利用分子束外延技术在加热的Ni(111)衬底上生长，结合扫描隧道显微镜、低能电子衍射、角分辨光电子能谱和密度泛函理论计算，证实了阶梯边缘辅助的大孔硼吩的存在。结果表明，硼原子最初并入Ni表面并优先在阶梯边缘成核。衬底与硼原子间良好的几何匹配与相互作用稳定了具有大孔洞的二维硼吩结构的复杂原子排列和电子能带特性。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["制备工艺[大孔硼吩]: 分子束外延技术在超高真空条件下于加热的Ni(111)衬底上生长"]},{"i":39592,"as":"研究系统调查了通过分子束外延技术生长的GaAsBi纳米线中生长模式、Bi掺入量与载流子动力学之间的关系。通过改变衬底温度和V/III束等效压力比，晶体生长可以从平面沉积转变为气-液-固（VLS）生长，再转变为气-固（VS）生长，从而确定了均匀轴向Bi掺入（高达2.4%）的工艺窗口。STEM-EDS分析证实，在稳定的VLS条件下能够实现均匀的轴向组分分布，而VS生长则导致组分差异。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["关键调控条件[GaAsBi线生长]: 改变衬底温度和V/III束等效压力比以控制Bi掺入"]},{"i":39593,"as":"为解决单细胞蛋白质组学检测灵敏度的局限性，研究提出了一种名为single-cell PAGE-PISA的超灵敏蛋白质组分析策略。该技术结合凝胶电泳与3D单分子荧光成像，对单细胞中的所有蛋白质进行荧光标记、电泳分离，并进行单分子分辨率的计数。该技术能够从单个哺乳动物细胞中定量超过1.07亿个蛋白质拷贝，具备检测低至10万个单分子拷贝的灵敏度，并能基于蛋白质组特征成功将单细胞划分为不同的细胞类型。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["检测技术[单细胞PAGE-PISA]: 结合凝胶电泳与3D单分子荧光成像的超灵敏蛋白质组分析策略"]},{"i":39594,"as":"研究提出了一种名为iERT的放射治疗技术，该技术对肿瘤大体体积施加低剂量放疗（LDRT），同时对其内部选定区域进行立体定向放疗（SBRT），并与免疫检查点抑制剂（ICI）联合使用。通过NK细胞和CD8+ T细胞的协同作用，iERT实现了对大体积肿瘤的有效控制。单细胞RNA测序表明，SBRT组分强烈诱导I型干扰素（IFN-I）表达，激活NK细胞分泌XCL1，进而招募交叉递呈抗原的XCR1+树突状细胞（DC）；同时SBRT促进携带新抗原的细胞外囊泡释放，增强了CD8+ T细胞的免疫反应。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["放疗策略[ bulky tumors治疗]: 低剂量放疗覆盖整个肿瘤体积(GTV)同时给予子体积立体定向放疗(SBRT)","免疫联合治疗[iERT方案]: 放疗技术与免疫检查点抑制剂(ICIs)联合，通过协调NK细胞和CD8+ T细胞的活性实现对巨大肿瘤的显著控制"]},{"i":39595,"as":"亚油酸（LA）是一种饮食中含量最高的必需脂肪酸。研究发现，LA会在老年个体和骨关节炎（OA）患者的血液、滑液及软骨组织中积累。在雄性大鼠模型中，LA不仅诱导软骨细胞发生铁死亡，还作为一种风险代谢物驱动OA的发生，并加速创伤性OA的恶化。机制上，LA直接结合铁硫簇组装酶（ISCU）诱导其自噬降解并抑制铁硫簇合成，随后激活由IRP1介导的翻译过程，从而促成软骨损伤。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["致病机制[亚硫酸软骨素]: 亚硫酸靶向软骨细胞铁硫簇，破坏铁稳态并诱发细胞铁死亡","风险代谢物[骨关节炎进展]: 亚硫酸(LA)作为危险代谢物并诱导软骨细胞铁死亡以加速疾病进程","病理积累[骨关节炎患者]: 亚硫酸在老年及骨关节炎个体的血液、滑液和软骨组织中发生大量积累"]},{"i":39596,"as":"为了探究真核生物中Kozak mRNA序列的识别机制，研究分析了数个人类48S起始前复合物在不同Kozak活性mRNA序列下的冷冻电镜结构。研究发现，密码子前三联体会呈扇形插入18S核糖体RNA中，而-3位的嘧啶会破坏三元复合物的稳定性。核糖体对+4位嘌呤的特异性识别不仅依赖单个残基，还通过eIF1A、mRNA和rRNA之间相互的构象适配来实现，其中rRNA解码残基A1825的插入和堆叠起到了关键的识别作用。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["识别基序[翻译起始]: -3和+4位点的嘌呤构成环绕AUG起始密码子的Kozak mRNA特征序列","构象识别机制[核糖体48S预起始复合物]: 密码子前三联体以扇形插入18S核糖体RNA(rRNA)中呈现不同的识别模式"]},{"i":39597,"as":"针对冯·诺依曼瓶颈对数据密集型计算的限制，研究基于混合卤化物钙钛矿（MHPs）在飞秒脉冲激发下的动态离子行为，开发出一种可重构的多态光学存储器。研究发现，光致发光（PL）发射波长能够将激发参数编码为易失性、可重写的存储态，这些状态不仅保持时间长，还能通过热脉冲快速擦除。通过精确调节激发功率和重复频率，实现了对PL波长的控制，进而表现出类似模拟突触的特性，具有空间分辨率的写入能力。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":7.0},"kp":["工作原理[混合卤化物钙钛矿光学存储器]: 利用飞秒脉冲激发下的动态离子行为，通过光致发光发射波长编码信息"]},{"i":39598,"as":"多囊蛋白复合物（由1个PC1和3个PC2组成）形成的阳离子通道与常染色体显性多囊肾病密切相关。该研究揭示了由特定膜脂质调节的PC1-PC2离子通道变构门控机制。在常规膜环境中，磷脂酰甘油（PG）和磷脂酸（PA）结合在孔洞中心使其保持关闭状态；这些脂质解离后，通道转变为预开放状态。此外，纤毛中富含的氧固醇7β,27-DHC通过变构机制使通道稳定在更开放但无导电性的构象。这种脂质介导的调节与通道的巨大构象变化相耦联。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["通道复合物[多囊肾病发病机制]: 由1个多囊蛋白-1(PC1)和3个多囊蛋白-2(PC2)组成定位于初级纤毛的阳离子通道","门控机制[典型膜环境]: 磷脂酰甘油(PG)和磷脂酸(PA)结合通道中心孔以维持其关闭状态","脂质变构调节[PC1-PC2通道]: 特异性膜脂质控制通道的变构门控机制"]},{"i":39599,"as":"本研究提出一种利用可编程光脉冲动态控制光子结构中激光驱动电子加速的技术。通过液晶掩模对红外激光脉冲的相位和振幅进行编程，并结合脉冲前沿倾斜方案，成功实现了对激光加速器的动态控制。该技术赋予了加速器束流动力学近乎无限的实时调节能力，不仅能够实现基于软件的光学和结构缺陷校正，还为精准控制介电光栅等光子加速结构中的电子动力学提供了全新手段。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["调控技术[激光驱动电子加速]: 施加液晶掩模版对红外激光脉冲的相位和振幅进行可编程动态控制"]},{"i":39600,"as":"研究团队利用扫描隧道光谱深入分析了范德华材料4Hb-TaS2中由填充控制的莫特态及其与超导的相互作用。4Hb-TaS2交替排列着强关联的1T-TaS2层和超导的1H-TaS2层。通过解析由层间电荷转移驱动的不同能级填充下的电子谱函数，研究定量捕获了莫特态的连续演化过程，其特征为莫特-哈伯德能带的出现和跃迁参数的系统性抑制，为探索莫特物理及相邻量子相提供了实验与理论依据。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["材料结构[4Hb-TaS2]: 交替插层强关联的1T-TaS2层和超导1H-TaS2层","物理机制[4Hb-TaS2]: 填充控制的莫特态及其与超导性的相互作用"]},{"i":39601,"as":"该研究开发了一种基于硒原子转移的[3+2+1]杂环加成反应，利用易得的芳胺、烯烃和二硒化物，快速模块化地合成含硒和氮的多种杂环化合物。这种无金属催化方法在温和简单的条件下进行，具有底物普适性好、官能团兼容性强、易于放大规模的特点，并成功应用于复杂分子的后期骨架多样化修饰。机理和计算研究揭示了该反应实现选择性单原子桥连环加成的内在机制。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["反应特征[单原子桥连环加成]: 硒原子转移介导的[3+2+1]杂环加成反应构建含硒和氮的杂环化合物","催化体系[烯烃-芳胺环加成]: 无金属催化方法"]},{"i":39602,"as":"聚烯烃的长期稳定性高度依赖抗氧化剂，但传统的物理共混或化学改性方法存在分散不均、易迁移和缺乏普适性等缺陷。该研究提出了一种催化剂赋能的抗氧策略（CEAS），利用酚羟基功能化的双功能催化剂，在无需聚合后添加抗氧化剂的情况下，直接催化聚合并赋予材料抗氧化能力。这一普适性策略成功实现了多种具有内在抗氧化性能的本征型聚乙烯的制备，有效解决了超高分子量聚乙烯等材料的抗氧化难题。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["改性策略[聚烯烃抗氧化]: 通过聚合反应直接合成具有本质抗氧化特性的聚烯烃，无需后处理改性"]},{"i":39603,"as":"为解决阴离子-π+光治疗剂结构受限及缺乏第二近红外（NIR-II）发射和光热性能的问题，研究提出了一种有机π共轭阴离子交换策略。通过合成带有不同阴离子的DTPAP-2B（Br-）和DTPAP-2P（五氰基环戊二烯阴离子），发现纳米化后的DTPAP-2P NPs表现出显著的吸收红移、强烈的NIR-II发射、大的斯托克斯位移（340 nm）以及优异的活性氧生成能力和高达72%的光热转换效率。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["结构设计策略[NIR-II光治疗剂]: 采用有机平面π-共轭阴离子交换策略构建先进的阴离子-π+光诊疗剂"]},{"i":39604,"as":"研究开发了一种兼容点击化学的七甲川花菁近红外荧光染料CETIF6a，可用于多种癌症靶向、术中组织病理学分析及全蛋白质组靶点鉴定。结果显示，该染料在多种癌症类型中的肿瘤边界划定与H&E染色的一致性超过90%。定量蛋白质组学表明，其靶向的肿瘤特异性蛋白数量是癌旁组织的5-15倍，并通过491个保守的肿瘤富集蛋白实现了协同的泛癌靶向，显著提升了肿瘤异质性标记的效果。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["材料属性[CETIF6a报告基因]: 具有点击化学兼容性的七甲川菁染料","应用功能[CETIF6a报告基因]: 实现明亮的多癌种全肿瘤标记及术中组织病理学分析"]},{"i":39605,"as":"针对锰基普鲁士蓝类似物因姜-泰勒效应畸变和低电导率导致电化学性能不佳的问题，研究提出钾取代与高熵协同策略，成功构建了K2(FeMnCoNiCu)[Fe(CN)6] (K-HEHCF)阴极。该材料展现出卓越的电容去离子性能，在1.4V电压下吸附容量高达104.92 mg g−1，且经过200次循环后容量保持率接近100%。在模拟循环冷却水样本中，该电极对阳离子表现出显著的去除效果，具备良好的实际应用潜力。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":8.0,"t":7.0},"kp":["吸附容量[K-HEHCF阴极在1.4V下电容去离子]: 104.92 mg/g","合成策略[抑制锰基普鲁士蓝类似物Jahn-Teller效应和低电导率]: 钾取代与高熵策略协同","分子式[构建高熵普鲁士蓝类似物]: K2(FeMnCoNiCu)[Fe(CN)6]"]},{"i":39606,"as":"针对复杂微结构表面上共形制造可拉伸导电薄膜的难题，该研究提出一种通用策略。通过精确调控液桥力与液态金属（LM）颗粒壳层的临界破裂强度，实现LM颗粒的自发融合，无需额外活化过程即可形成高性能导电薄膜。在拉普拉斯压差的驱动下，该导电薄膜能够共形沉积于复杂的微观结构表面。该技术克服了现有方法在拉伸性、导电性和几何兼容性方面的局限，为柔性电子制造提供了新途径。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["制造工艺[复杂微结构表面可拉伸导电薄膜]: 精确控制粒子间液桥力及临界破裂","技术特点[液态金属自发融合]: 共形制造与高几何兼容性"]},{"i":39607,"as":"室温红外光电探测长期受制于宽带热辐射产生的背景光子及确定的平均光电流偏移。本研究通过光谱极性反转，展示了一种传感器内背景偏移消除机制。通过工程化波长依赖的光电流反转，使来自不同光谱波段的光子在单个器件中产生相反符号的响应，从而有效抑制背景的平均光电流偏移。该机制成功突破了传统单极光谱积分导致的环境弱信号淹没限制，实现了灵敏的室温红外光电探测。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["背景限制成因[单极光谱积分导致室温红外光电检测受限]: 宽带热辐射响应波段光电流叠加产生确定性平均光电流偏移","技术策略[消除背景偏移]: 混合维范德华异质结构建传感器内背景消除"]},{"i":39608,"as":"研究利用三维粒子动力学模拟，开发了针对具有自引力内聚性风化层的抗拉强度通用标度框架，揭示了颗粒尺寸和形状如何共同控制宏观力学行为。研究表明，抗拉强度可通过等效颗粒直径或颗粒形状（通过球度及等效球形堆积标度）进行缩放。研究将该模型应用于OSIRIS-REx任务返回的小行星贝努样本数据，推导出的表面内聚强度与前人估计一致，为预测小行星演化和偏转策略提供了理论支撑。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":6.0,"t":5.0},"kp":["强度标度框架[颗粒状小行星凝聚力与自引力拉伸强度]: 基于3D粒子动力学模拟由粒径与形状联合控制宏观行为"]},{"i":39609,"as":"为解决分子组装体中单电子电荷状态控制的难题，研究通过扫描探针操纵技术构建了四溴四氮杂芘分子的三聚体和六聚体结构。研究发现，这些分子组装体内的非平衡多体电子动力学完全可以通过安德森杂质模型和主方程方法进行阐释。这种超越了标准单粒子图像的理论处理不仅定量重现了实验观测到的特征，也为深入理解和精准控制复杂分子体系中的电子关联动力学提供了可靠框架。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":["组装技术[精确控制分子组装体单电子电荷态]: 扫描探针操纵构建四溴四氮杂芘分子三聚体和六聚体","理论模型[分子多体非平衡电子动力学]: 完全基于明确的理论框架进行合理化"]},{"i":39610,"as":"针对传统体表电生理技术空间分辨率受限、布线复杂等缺陷，该研究开发了一套混合智能纺织电极阵列系统。该系统克服了性能、可穿戴性和数据传输等临床应用壁垒，能够同步绘制沿皮质-肌肉轴的电活动体表电位图。结合定制算法，该技术显著提升了皮肤电记录的诊断能力，为高空间分辨率评估大脑、心脏和肌肉等电活性器官提供了全新的非侵入式解决方案。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["空间分辨率[标准体表电生理技术]: 受限导致对特定病理特征敏感度降低","诊断增强技术[克服传统临床空间限制]: 智能纺织电极阵列绘制体表电位图"]},{"i":39611,"as":"本研究旨在评估碱性海水裂解中抗腐蚀催化剂对次氯酸盐的选择性。利用旋转环盘电极装置，研究对比了静电排斥和离子选择性策略在减少阳极氯化物氧化方面的效果。实验表明，在析氧反应催化剂中添加铬能够有效抑制次氯酸盐的生成，使其在5分钟内的生成量从2.362 mM降至0.670 mM。该发现为设计高选择性的海水制氢阳极催化剂提供了直接的定量对比依据。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["竞争机制[海水电解阳极反应]: 氢氧化物氧化与氯化物氧化竞争","抗腐蚀策略[降低海水中氯化物氧化]: 静电排斥与离子选择性的直接效能对比评估"]},{"i":39612,"as":"分析全球能源转型所需关键矿物供应链的系统性相互依赖、特定市场动态及政策格局演变下的潜在全球风险因素。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":4.0},"kp":["供应链风险[能源转型关键矿物]: 系统性相互依赖、特定市场动态与政策格局演变带来的潜在全球风险因素"]},{"i":39613,"as":"该文为半人工光合作用领域的入门或综述类文章，主要结合生物酶与人工半导体材料介绍太阳能到化学能的转化技术。","scd":{"b":3.0,"i":2.0,"r":4.0,"d":3.0,"t":2.0},"kp":["技术架构[半人工光合作用]: 结合生物酶与人工半导体材料实现太阳能到化学能的转化"]},{"i":39614,"as":"分析日本太阳能政策及其对供应链中强迫劳动风险的潜在激励机制。","scd":{"b":0.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["供应链风险[日本太阳能政策]: 政策激励机制对供应链中强迫劳动风险的潜在影响"]},{"i":39615,"as":"神经元极性的建立取决于将单一神经突起指定为轴突。该研究证实，神经极化不仅依赖于感知外部信号的生长锥，细胞体更是作为中心组织者发挥作用。通过活体成像和光遗传学等手段，研究揭示了一种由细胞体启动的振荡程序：细胞体中依赖于ARP2/3复合体的周期性肌动蛋白分支重塑了全局的肌动球蛋白网络，进而产生振荡，从而启动并决定了轴突的选择。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["极性建立机制[神经元不对称性发育]: 细胞体作为中心组织者及内在细胞骨架振荡器建立极性","作用机制[破除传统生长锥主导认知]: 光遗传学结合活体成像验证"]},{"i":39616,"as":"亚马逊地区拥有地球上超过10%的陆地生物多样性。研究汇编了包含90,536份报告的数据库，记录了人类利用的5,796种亚马逊本土植物物种。通过分析未来三种气候情景（SSP1-2.6、SSP3-7.0和SSP5-8.5）下的8,429个物种分布模型，研究证实气候变化与原住民语言的流失将同时对该地区的生物和文化遗产造成严重影响，气候变暖将导致植物物种分布范围的大幅缩减。","scd":{"b":4.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["生物多样性[亚马逊陆地生态系统]: 超过地球总量的10%","土著语言[亚马逊原住民群体]: 超过400个族群","数据库规模[亚马逊本土植物社会效益评估]: 700篇参考文献中的90,536份报告"]},{"i":39617,"as":"","scd":null,"kp":[]},{"i":39618,"as":"重建亚马逊原住民与自然之间以互惠关怀为导向的关系，是应对气候变化和生物多样性丧失的关键途径。这种传统生态关系的修复有助于提升生态系统的整体韧性，从而有效缓解气候变暖对亚马逊地区生物多样性造成的负面影响。","scd":{"b":3.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["应对策略[减缓亚马逊地区气候变化对生物多样性的影响]: 重建原住民与自然之间以互惠关怀为导向的关系"]},{"i":39619,"as":"诺贝尔化学奖得主Omar Yaghi已离开美国，前往中国领导一家人工智能材料实验室。这一人事变动发生在美国削减科研经费的背景下，同时也是中国积极招募顶尖国际科研人才战略的体现。","scd":{"b":6.0,"i":3.0,"r":8.0,"d":4.0,"t":8.0},"kp":["[顶尖人才招募与科研机构]: 诺贝尔化学奖得主离开美国前往中国领导人工智能材料实验室"]},{"i":39620,"as":"卫星观测与气候模型模拟显示，自2005年以来，中等强度的火山喷发与极端野火导致平流层湿度显著上升。这些事件通过气溶胶介导效应，大约解释了观测到的平流层水汽增长趋势的三分之一，其影响程度与地表变暖的效应相当。研究结果表明，除全球变暖外，火山与野火活动也是加剧平流层湿润化的重要驱动因素。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":8.0,"t":6.0},"kp":["平流层水汽趋势贡献率[2005年以来中等强度火山喷发和极端野火的气溶胶介导效应]: 约三分之一","平流层增湿效应[火山与野火气溶胶介导影响]: 与地表变暖的贡献相似"]},{"i":39621,"as":"","scd":null,"kp":[]},{"i":39622,"as":"科学家在实时观测中发现大洋中脊正在变宽，记录到了数米级别的海底运动以及伴随喷发的巨大熔岩流。这一观测直接证实了海底分裂及岩浆喷发的物理过程。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":5.0,"t":8.0},"kp":["海底运动范围[中洋脊实时扩张观测]: 数米级","[海底扩张事件]: 记录到大规模熔岩流出"]},{"i":39623,"as":"小鼠乳腺癌模型实验表明，染色体非整倍体不稳定性的背后存在一两种驱动癌症发生的主导基因。这些基因能绕过非整倍体积累的过程，但需要完整的微环境才能发挥作用。体内CRISPR筛选发现，这些驱动基因表达的改变在体外实验中并不会引起细胞行为的变化。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["乳腺癌驱动基因数量[非整倍体不稳定染色体 harboring]: 1至2个普遍基因","[体内CRISPR筛选鉴定的癌症驱动基因]: 需要完整的微环境才能发挥致癌作用，且其表达改变在体外实验中未必改变细胞行为"]},{"i":39624,"as":"大语言模型具备推进社会科学实验发展的潜力。然而，关于在科研中应如何具体应用大语言模型以提供有效支持，目前仍存在根本性的问题亟待解答。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":3.0,"t":5.0},"kp":["[大语言模型(LLM)]: 可加速社会科学领域的实验与研究进展"]},{"i":39625,"as":"一项海底观测站监测实验成功记录到两个构造板块之间正在生成新的洋壳。这是人类首次对海底扩张现象进行原位实地测量。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":5.0,"t":8.0},"kp":["[海底扩张监测实验]: 首次实现对两个构造板块之间洋壳生成的原位测量"]},{"i":39626,"as":"Kathleen Fisher介绍了她为英国先进研究与发明局（UK ARIA）引入的创新科学资助理念。该理念的核心要素包括追求高流动性、容忍高风险以及允许失败，以此推动革命性科学的发展。","scd":{"b":3.0,"i":2.0,"r":6.0,"d":3.0,"t":4.0},"kp":["[革命性科学推进机制]: 高流动性、高风险以及对失败的许可"]},{"i":39627,"as":"","scd":null,"kp":[]},{"i":39628,"as":"环绕地球轨道运行的核武器在与地球空间辐射环境相互作用时会发射中子。这些中子辐射能够被轨道上的卫星探测到，从而实现对太空中潜伏核武器的追踪。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["中子辐射[绕地轨道核武器与空间辐射环境相互作用]: 发射中子","[天基核武器探测]: 卫星可探测轨道核武器发射的中子"]},{"i":39629,"as":"燃料电池等电化学装置的商业化取决于电催化剂的稳定性。文章综述了纳米结构催化剂的稳定性机制，结合材料化学与工程学策略，探讨了如何在严苛的真实工况下设计维持高效催化性能的催化剂，以此保障电化学装置的可靠性、使用寿命与成本效益。","scd":{"b":5.0,"i":5.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[商业可行性条件]: 取决于电催化剂在实际苛刻条件下的高稳定性","[催化剂设计策略]: 需跨越纳米结构催化剂基础理解以维持苛刻实际条件下的高性能"]},{"i":39630,"as":"针对五对本地与外来植物物种及九种全球变化因素（GCF）的植物-土壤反馈（PSF）实验表明，随着GCF数量增加，本地物种的PSF由负转中性或正向，而外来物种的PSF始终保持正向且更强。这种正向增强源于共同作用的GCF之间的特定相互作用，促进了外来物种的入侵。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":5.0,"t":4.0},"kp":["实验物种数[植物-土壤反馈(PSF)全球变化因子实验]: 5对本地与外来物种","实验处理条件[植物-土壤反馈(PSF)全球变化因子实验]: 9种全球变化因子并发组合"]},{"i":39631,"as":"研究利用基因靶向技术将有机光催化染料整合到细胞表面或内部，实现了细胞类型特异性和空间定义的催化反应。在温和的绿光至红光可见光刺激下，光催化作用可局限于单个细胞内。该染料能催化交叉脱氢C-H官能化反应，将细胞作为独立的纳米反应器进行非生物有机分子的时空可控合成。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":6.0},"kp":["[生物兼容性催化合成]: 突破哺乳动物细胞原生能力限制，实现非生物有机化合物的原位合成","[细胞功能调控]: 将特定活细胞作为独立反应容器，实现时空控制和细胞行为调节"]},{"i":39632,"as":"探讨美国45V氢能税收抵免政策的层级、门槛机制与设计权衡。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":6.0},"kp":["[美国45V氢信用额度]: 包含层级、门槛机制与政策设计权衡"]},{"i":39633,"as":"研究实现了一种钯催化的C-H活化反应，成功完成了无向芳烃、杂芳烃与环戊烯衍生物的对映选择性偶联。在手性吡啶酮-恶唑啉配体的促进下，该反应高效实现了C(sp2)-H活化，生成的产物包含两个立体中心，具有优异的立体控制效果，对映体过量达96%，非对映比为40:1。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["催化剂[钯催化无向芳烃对映选择性C-H活化]: 手性吡啶酮-噁唑啉配体","[无向芳烃和杂芳烃]: 钯催化实现与环戊烯衍生物的对映选择性偶联"]},{"i":39634,"as":"研究构建了一种空心硫化镉@聚多巴胺（CdS@PDA）光催化纳米反应器，结合了仿生特征。聚多巴胺外壳中的动态邻苯二酚/邻苯醌氧化还原对作为质子继电器，加速了质子耦合电子转移（PCET）；纳米腔体结构创造了受限的微环境以促进物质扩散与光子捕获。这种协同机制有效促进了光催化氧还原和水的氧化反应。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["光催化纳米反应器[仿生氧化还原介导]: 空心硫化镉@聚多巴胺 (CdS@PDA)","质子继电器[聚多巴胺壳层]: 动态儿茶酚/邻苯醌氧化还原对"]},{"i":39635,"as":"研究提出一种氮掺杂策略，构建了二氧化钛负载的金（Au）催化剂，用于在温和水相条件下利用氧气选择性氧化甲烷为甲醇。优化的Au/N-TiO2催化剂在180℃下实现了98%的甲醇选择性，甲醇产率达3956 μmol gcat-1 h-1。分析表明，氮掺杂有效调节了Au的电子状态，从而抑制了甲醇的过度氧化。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":6.0},"kp":["甲醇产率[优化的Au/N-TiO2催化剂甲烷氧化]: 3956 μmol gcat-1 h-1","催化剂[TiO2负载阳离子金位点选择性氧化甲烷]: 氮掺杂构建的Au/N-TiO2"]},{"i":39636,"as":"研究开发了氨基功能化氢键有机框架（HOF-101-NH2）用于大气集水。氨基的引入创造了水分成核位点并形成氢键网络，使其在60%相对湿度下吸水量达0.46 g g-1。吸附水可在约50℃下3分钟内快速释放，实现低能耗再生。这种快速的吸脱附动力学每天可循环30次以上。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["吸附剂[低温再生快速大气水收集]: 氨基功能化氢键有机框架(HOF-101-NH2)","[HOF-101-NH2]: 通过氢键工程策略引入-NH2基团实现高效湿气捕获"]},{"i":39637,"as":"研究开发出从纳升级母液滴中按需释放皮升级子液滴的耦合富集技术。该方法利用电动驱动的液滴内黏度梯度来调控液滴动力学。通过海藻酸盐等带电黏度调节剂和目标带电物质的局部富集，实现了试剂富集与按 demand 分离，有效提升了微流控中的反应动力学和检测灵敏度。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[微流控液滴操作]: 实现纳升母液滴的耦合富集与按需释放转变为浓缩皮升子液滴","[微流控技术应用价值]: 提升反应动力学、测定灵敏度并实现纯化"]},{"i":39638,"as":"脂肪酸光脱羧酶（FAP）通过光驱动自由基化学将脂肪酸转化为碳氢化合物。多尺度量子力学/分子力学（QM/MM）计算表明，在快速脱羧后，产生的烷基自由基主要通过质子化的精氨酸R451和附近水分子介导的质子耦合电子转移机制被猝灭，而水辅助形成碳酸氢根的机制极少发生。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["[脂肪酸光脱羧酶(FAP)]: 光驱动自由基化学将脂肪酸转化为碳氢化合物","[催化自由基终止分子机制]: 通过经典和可极化QM/MM多尺度计算动力学的明确模拟解析"]},{"i":39639,"as":"报道了一种由钴催化、可见光促进的环氢羰基化策略，用于区域和立体选择性地合成饱和杂环化合物。该反应条件温和，底物范围广，可从烷基胺合成δ-内酰胺或哌啶，也可合成内酯。在氩气气氛下，增加催化剂用量可使钴羰基同时作为预催化剂和一氧化碳源。机理研究显示存在多个协同的催化途径。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["催化剂[温和条件可见光促进环烃羰基化]: 简单的钴催化剂","[烷基胺底物]: 区域和立体选择性的环氢羰基化合成δ-内酰胺或哌啶"]},{"i":39640,"as":"研究设计了四种蛋白质支架，通过预组织非经典氨基酸生成铜配合物。蛋白质作为机械活性配体结构，重塑了铜的经典配位偏好：显著减少了八面体Cu(II)的姜-泰勒畸变，构建了前所未有的八面体Cu(I)几何结构，并使Cu(II)/Cu(I)氧化还原电位发生明显负移。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["[铜配合物配位重塑]: 蛋白质骨架作为机械活性配体架构，可覆盖铜固有的电子与结构偏好(如Jahn-Teller效应)","[配体预组织策略]: 设计蛋白骨架预组织双(或三)联吡啶-丙氨酸非天然氨基酸以生成单核配合物"]},{"i":39641,"as":"核酸递送材料的发现正从经验筛选转向人工智能指导的预测性生成设计。研究重点已转向利用AI针对预定特性目标生成新材料，以解决同时优化竞争属性以及实现向肝外组织递送等更具挑战性的难题。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[核酸递送材料发现]: 从经验筛选向预测性、人工智能指导的生成式设计转变"]},{"i":39642,"as":"研究构建了由交替的Pt-I链和Pt-Pt-I-I双链组成的一维分子超晶格。链间的静电相互作用使电子配对过程从传统的局域机制重构为离域的多位点途径。这种转变稳定了首个碘桥接的Pt(III)电荷密度波（CDW）链，使得材料在该状态下的体电导率提升了约两倍。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["分子超晶格结构[调控电荷密度波链电子配对]: 一维交替的Pt-I和Pt-Pt-I-I双链","[电子配对与电荷有序态]: 链间静电相互作用可从根本上重新配置电子结构"]},{"i":39643,"as":"","scd":null,"kp":[]},{"i":39644,"as":"激光测距技术被用于在弱场状态下高精度测试引力，以验证爱因斯坦的广义相对论。研究利用新发射的LARES-2卫星及其优异的轨道和极低的面质比，结合LAGEOS和GRACE卫星，成功测量了地球周围的坐标系拖动效应。测量结果的相对不确定度达到千分之一水平，精度比以往的太阳系测量结果提升了一个数量级。","scd":{"b":9.0,"i":6.0,"r":8.0,"d":7.0,"t":8.0},"kp":["[LARES-2卫星测试坐标系拖动效应]: 极低面质比和高度均匀的后向反射器分布","[广义相对论弱场测试]: 优化的轨道设计实现极高精度的激光测距"]},{"i":39645,"as":"真核生物膜蛋白的基本单元是跨膜（TM）螺旋，具有锚定和核心功能作用。研究探讨了一类特殊的“条件性跨膜肽”，这类多肽在溶液和细胞膜中均能保持稳定。文章回顾了它们的发现过程（如pHLIP肽）、决定其插入细胞膜的因素，以及这些多肽作为变构调节剂在癌症治疗中的理论基础和热力学机制。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":[]},{"i":39646,"as":"研究将局部热力学测量与输运测量相结合，应用于扭曲三层石墨烯器件中，揭示了强相互作用特征之间的联系。实验表明，超导现象与电子压缩率的特征振荡同时出现，但超导性独立于相关绝缘相存在。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[扭曲三层石墨烯]: 超导性与电子压缩性的特征振荡同时出现","[超导性]: 独立于相关绝缘相"]},{"i":39647,"as":"研究埋入界面工程技术，实现高效柔性半透明钙钛矿及钙钛矿/硅串联电池。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["转换效率[柔性钙钛矿/硅四端子串联]: 27.7%","[埋入界面工程]: 实现高效柔性半透明钙钛矿及钙钛矿/硅串联电池"]},{"i":39648,"as":"探讨利用电化学技术将钢铁与煤炭废弃物矿化，并协同生成氢气的方法。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[钢铁和煤炭废物处理]: 利用电化学技术将废弃物矿化并协同生成氢气"]},{"i":39649,"as":"基于偶极效应筛选溶剂，开发用于高压钙金属电池的高性能氟硼酸钙盐电解质。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["电解质[高压钙金属电池]: 基于偶极效应辅助溶剂筛选的高性能氟硼酸钙盐电解质"]},{"i":39650,"as":"研究开发了一个城市尺度的建模框架，用于评估气候变化对水负担能力的影响，该框架整合了气候、公用事业决策和用水需求。以加州圣克鲁斯市为例，结果显示到本世纪中叶，气候变化可使水费翻倍，导致额外7%至16%的家庭面临无法负担水费的问题。","scd":{"b":2.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":39651,"as":"","scd":null,"kp":[]},{"i":39652,"as":"研究在预存了Mo和Si原子的Cu(111)箔上，实现了p型半导体单层MoSi2N4单晶晶圆级生长。Cu(111)表面的台阶引导了单层MoSi2N4结构域的成核与单向排列，使其无缝拼接成连续的单晶薄膜。该材料本征迁移率达到154 cm2 V−1 s−1，基于此制造的场效应晶体管阵列展现出优异的电学性能。","scd":{"b":8.0,"i":6.0,"r":7.0,"d":7.0,"t":5.0},"kp":["半导体材料[晶圆级p型单晶生长]: 单层MoSi2N4","[成核与取向机制]: Cu(111)上的台阶引导单层晶体单向取向","[生长基底]: 预储存Mo和Si原子的Cu(111)箔"]},{"i":39653,"as":"该研究提出了一种化学回收路线，可将基于二氧化碳的非异氰酸酯聚氨酯（NIPU）泡沫转化为环状碳酸酯构件，用于直接重新发泡。这种一锅法工艺结合了泡沫解构和重新功能化，重复利用所有主要解聚产物，无需中间纯化。由此产生的第二代泡沫中回收碳酸酯源比例高达100%，实现了NIPU泡沫的“从泡沫到泡沫”的实用化回收。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["循环碳酸酯含量[第二代非异氰酸酯聚氨酯泡沫]: 高达100%","回收路线[CO2基非异氰酸酯聚氨酯泡沫]: 泡沫到泡沫的化学回收","工艺特点[非异氰酸酯聚氨酯泡沫解聚]: 结合泡沫解构和重新官能化的逐步一锅法过程"]},{"i":39654,"as":"过渡金属催化在推动聚合物化学进步中发挥了核心作用。研究介绍了最初为小分子基底开发的催化反应，如何随后应用于聚合物的合成与修饰。这些应用主要体现在功能材料的制备，以及塑料的降解、回收或升级回收方面。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":3.0},"kp":["应用领域[过渡金属催化]: 聚合物的合成、改性以及塑料的降解、回收或升级回收"]},{"i":39655,"as":"一种鞋盒大小的探测器卫星具备识别隐藏核装置特征信号的能力。此外，报道还提及了原住民植物知识正面临威胁的现状。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":3.0,"t":6.0},"kp":["探测目标[鞋盒大小的探测器卫星]: 隐藏核装置的标志性信号"]},{"i":39656,"as":"通过时空调制，时间驱动系统能够在不产生机械位移的情况下合成有效运动。理论上，当波经历足够大的旋转多普勒频移时，会从旋转介质中提取能量。研究利用Floquet诱导旋转技术，在无需机械旋转的情况下，通过纯空间调制成功进入了由于机械旋转系统速度要求极高而难以实验达到的超快旋转状态。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["控制框架[时间驱动系统]: 通过时空调制控制波以合成无机械位移的有效运动","物理现象[行波调制]: 模拟运动介质并引发多普勒诱导的非互易性"]},{"i":39657,"as":"研究利用ATAC-seq技术对包含1563名急性髓系白血病（AML）近期确诊患者的队列进行了染色质可及性分析。基于染色质可及性特征，AML可被划分为16个亚组。多组学分析（涵盖基因突变、转录组、DNA甲基化和组蛋白标记）表明，这些ATAC亚组展现出截然不同的驱动突变模式。","scd":{"b":8.0,"i":5.0,"r":8.0,"d":9.0,"t":7.0},"kp":[]},{"i":39658,"as":"医疗保健领域面临人员短缺和护理需求激增的挑战，而医院的大量工作需要移动、操作及在人类环境中安全交互。仿人机器人凭借其形态优势，在辅助手术等实际临床任务中展现出独特潜力，打破了传统以数字和物流为主的自动化局限。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":5.0,"t":7.0},"kp":["应用领域[仿人机器人]: 医疗保健和外科手术","驱动因素[仿人机器人临床部署]: 执行、控制和学习的最新进展"]},{"i":39659,"as":"为了解决移植前基因毒性预处理的副作用，研究在KIT胞外区鉴定出了能够破坏两种治疗性单克隆抗体结合的氨基酸变化。这些突变在不影响KIT表达和功能的情况下削弱了干细胞因子（SCF）介导的信号传导。利用腺嘌呤碱基编辑或先导编辑技术，可高效引入这些突变，从而实现非基因毒性的移植和体内筛选。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":6.0,"t":7.0},"kp":["编辑靶点[基因工程改造]: KIT胞外区氨基酸","编辑靶点[基因工程改造]: BCL11A红系增强子","基因编辑技术[突变引入]: 腺嘌呤碱基编辑或先导编辑","突变效果[功能影响]: 破坏两种治疗性单克隆抗体的结合","突变效果[功能影响]: 损害SCF介导的信号传导，且不影响KIT的表达或功能"]},{"i":39660,"as":"产甲烷菌的Hdr–Vhu–Fwd超级组装体通过基于黄素的电子分岔将氢气氧化与二氧化碳还原相偶联。研究利用冷冻电子显微镜解析了其8 MDa的复合物结构，发现该结构包含252条多肽链和超过600个氧化还原辅因子。该架构由两个六聚体HdrABC–Vhu环通过四聚体FwdF核心连接，形成了一条连续的环形电子链。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":8.0,"t":7.0},"kp":["分子量[Hdr-Vhu-Fwd超级组装体]: 8 MDa","复杂组成[Hdr-Vhu-Fwd超级组装体]: 包含252条多肽链和超过600个氧化还原中心","能量代谢机制[I类产甲烷菌]: 通过基于黄素的电子分叉将H2氧化与CO2还原偶联"]},{"i":39661,"as":"量子纠错（QEC）是保护量子计算机免受环境干扰的关键策略，要求通过不断适应环境条件来降低错误率。研究将校准与计算相统一，将QEC过程中的错误检测事件作为学习信号，训练强化学习智能体持续调整控制参数，从而替代了会中断量子计算的传统重新校准方法。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":5.0,"t":7.0},"kp":["控制策略[量子纠错]: 强化学习控制","核心挑战[量子计算]: 必须不断适应控制参数以应对环境条件漂移"]},{"i":39662,"as":"研究构建了一个包含70项预注册、全国代表性调查实验的档案，涉及469种实验效应和119,330名参与者。通过让GPT-4模拟美国代表性人群对实验刺激的反应，研究比较了不同条件下的模拟响应来推断处理效应。结果表明，即使许多实验尚未包含在模型的训练数据中，大型语言模型依然能够成功预测社会科学实验的结果。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["预测能力[大型语言模型]: 能够预测社会科学实验的结果","实验数据集[社会科学预测]: 包含70项预注册且具全国代表性的调查实验、469个实验效应及119330名参与者"]},{"i":39663,"as":"通过对神经肽进行无偏倚药理学筛选，研究发现两种古老的进食调节因子——神经肽F（NPF）和食抑素A（AstA）能够调节克隆掠夺蚁的幼蚁护理行为。功能操纵实验证实，NPF能够增强对后代的护理行为，而AstA则在该过程中发挥不同的调节作用，揭示了社会性昆虫分工背后的神经和分子机制。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":7.0},"kp":["神经肽F(NPF)[对育幼行为的作用]: 增加育幼行为","Allatostatin A (AstA)[对育幼行为的作用]: 与NPF作用相反（抑制育幼行为）","NPF和AstA[随年龄变化的特征]: 脑内水平随蚂蚁年龄自然变化","NPF和AstA[对营养状态的响应]: 对营养状态保持敏感","营养状态[对育幼行为的影响]: 相应影响育幼行为"]},{"i":39664,"as":"研究首次利用原位地震大地测量方法（结合水声、直接路径测距、海底压力测量和重复海底地形测绘）观测了大洋中脊的断裂扩张事件。该事件于2024年4月26日在东南印度洋中脊轴线发生，表现为沿断层快速迁移的扩张性地震群，揭示了洋底板块边界在年度时间尺度上的系统运动机制。","scd":{"b":7.0,"i":3.0,"r":9.0,"d":7.0,"t":7.0},"kp":["监测技术[海底扩张事件]: 结合水声、直接路径测距、海底压力测量与重复海底测绘的原位地震大地测量法"]},{"i":39665,"as":"在新型数据集和灵活计算方法兴起的推动下，城市犯罪研究的方法论和实证分析发生了深刻变化。文章指出，计算方法不仅限于传统的预测任务，更为严谨的因果推断提供了广阔前景。文章还概述了确保新数据和计算方法在未来城市犯罪研究中发挥作用的三个关键研究方向。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":3.0},"kp":[]},{"i":39666,"as":"研究演示了集成了由二维六方氮化硼（hBN）制成的忆阻射频开关的可编程毫米波氮化镓MMIC微芯片。忆阻射频开关因制造简便和器件级电学性能优异，克服了在单片微波集成电路（MMICs）中集成高频开关在面积、成本和性能上的瓶颈，满足了5G及以上通信标准的性能需求。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["器件架构[可重构毫米波微芯片]: 在GaN上共集成hBN开关","核心优势[忆阻射频开关]: 因面积和成本优势克服高频开关集成瓶颈"]},{"i":39667,"as":"该研究通过气凝胶粘弹性相分离（VPS）策略，在高含水量的水凝胶中构建了不塌陷的富气网络。由于非极性气体在极性水介质中溶解度和扩散率低，传统水凝胶在生物医学接口中的气体交换受到极大限制。新方法成功克服了透气性与含水量之间的矛盾，实现了创纪录的185 barrer的氧气渗透率，解决了可穿戴健康监测器和组织工程等长期应用中的气体交换瓶颈。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["水凝胶[透气性]: 面临非极性气体在极性水介质中溶解度和扩散系数低的固有瓶颈","[气凝胶粘弹性相分离]: 制备透气水凝胶实现富含水环境下的有效气体交换（如O2、CO2）"]},{"i":39668,"as":"《外层空间条约》（OST）禁止在外太空部署核武器，但目前缺乏验证机制。针对近期关于俄罗斯测试天基反卫星核武部件的担忧，该研究提出了一种利用宇宙质子验证卫星是否遵守OST的概念和可行性研究。如果天基核武器发生爆炸，将摧毁大部分低地球轨道卫星。该验证方法填补了公开同行评审文献中OST核查方法学的空白。","scd":{"b":1.0,"i":1.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[《外层空间条约》]: 禁止在外层空间放置核武器","[天基核反卫星武器(ASAT)]: 一旦引爆将摧毁绝大多数卫星"]},{"i":39669,"as":"研究开发了名为CRISPR-KOALA的检测方法，能够在免疫功能正常的小鼠癌症模型中进行高通量双向遗传筛选，以探究非整倍体如何驱动肿瘤发生。针对由大规模拷贝数 alterations（CNAs）驱动的基底样乳腺癌（BLBC），研究人员汇编了10种最常见的人类染色体臂水平变化。通过对这些染色体臂上的3,752个小鼠同源基因进行筛选，成功鉴定出90个癌症驱动基因。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["高通量双向遗传筛选技术[免疫活性小鼠癌症模型]: CRISPR-KOALA","研究模型[人类染色体臂水平非整倍体]: 十种最频繁的染色体臂集合"]},{"i":39670,"as":"研究提出了通用细胞嵌入（UCE）基础模型，利用自监督学习在庞大的细胞数据语料库上进行训练，构建了能代表跨组织和物种细胞的统一生物潜在空间。基于单细胞转录组数据，UCE能在无需数据标记、无需模型训练的情况下嵌入新细胞，并有效克服实验噪声，精准捕获关键的生物变异。该模型为跨物种细胞生物学的分子多样性研究提供了变革性工具。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["通用细胞嵌入(UCE)模型[底层架构]: 基于单细胞转录组数据在大量细胞语料库上通过自监督学习训练","UCE模型[核心能力]: 建立跨物种细胞类型的通用表征空间"]},{"i":39671,"as":"为解决高电压全电池充电过程中电解液溶剂化和氧化分解加剧的问题，研究将靶向配体抗溶剂（TLAS）引入富含阴离子的醚类电解质中。在静态下，TLAS极弱地参与Li+的溶剂化；但在高压全电池的强电场下，TLAS的取向和分布发生变化。该方法有效改善了溶剂化结构，解决了长循环中成分持续消耗导致的氧化还原稳定性下降问题，从而显著稳定了锂金属电池。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[醚类电解液(高压全电池充电过程)]: 溶剂和阴离子的去溶剂化加剧电解液的氧化分解并破坏溶剂化结构","[单相梯度溶剂化电解质]: 稳定锂金属电池氧化还原稳定性的技术方案"]},{"i":39672,"as":"研究通过引入光作为独立且空间分辨的自由度，解耦了寻址与状态切换，建立了一种用于光伏系统的光电双场编程范式。现有单场调制技术受限于复杂的器件架构和空间选择性约束。该技术利用范德华材料ZnIn2S4中的反常光伏效应，实现了可编程的光伏功能，成功将能量转换与信息处理结合在简单的架构中，大幅提升了空间选择性和运行效率。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[可编程反常光伏]: 依赖异质结构设计或基于铁电性和离子迁移的无栅极架构存在单场调制局限性","[光电双场控制]: 解耦寻址与状态切换，实现可编程光伏的空间选择性与架构简单化"]},{"i":39673,"as":"提出N-k突发故障下的输配电负荷恢复策略，结合分布式优化与强化学习方法。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["负荷恢复策略[N-k突发故障]: 结合分布式优化与强化学习方法"]},{"i":39674,"as":"为逆转冷肿瘤的免疫抑制微环境（ITME），研究开发了具有光免疫原性的光响应纳米光笼，用于协同光免疫治疗。该纳米颗粒以光敏硼二吡咯亚甲基（BODIPY）连接STING激动剂（DMXAA）。实验表明，碘化的纳米光笼展现出最佳的光反应效率和时空可控性。在光照条件下，纳米光笼能精准激活STING信号通路，从而克服ITME障碍，实现对冷肿瘤的协同治疗。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["光免疫原性纳米光笼[冷肿瘤治疗]: 精准激活STING信号通路以逆转免疫抑制肿瘤微环境(ITME)","[协同光免疫治疗]: 利用光响应纳米光笼克服冷肿瘤免疫治疗障碍"]},{"i":39675,"as":"基于欧洲能源危机经验，分析发电多样性与可再生能源对缓解价格冲击的作用。","scd":{"b":1.0,"i":2.0,"r":5.0,"d":3.0,"t":3.0},"kp":["价格冲击缓解机制[欧洲能源危机]: 发电多样性与可再生能源"]},{"i":39676,"as":"提出一种基于双指数方法的降维框架，用于预测高湿度下PEMFC的阴极电压行为。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["阴极电压行为预测方法[高湿度下PEMFC]: 基于双指数方法的降维框架"]},{"i":39677,"as":"提出一种弹性感知方法，结合输电网承载力分析以优化数据中心选址与配置。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["选址与配置优化方法[考虑输电网承载力]: 弹性感知方法"]},{"i":39678,"as":"针对传统热熔胶（HMA）粘合强度低（<4.0 MPa）且不可降解的问题，研究利用地球储量丰富的镍催化剂，通过乙烯与α-烯烃的羰基化聚合制备了新型高性能聚酮热熔胶。研究阐明了聚酮组成与粘合性能的关系，发现丙烯/一氧化碳含量对粘合强度具有决定性影响，并通过简单的复合方法实现了材料的高粘附性与可降解性，成功将廉价烯烃原料转化为工程级环保粘合剂。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["粘合强度[传统热熔胶EVA]: <4.0 MPa","聚酮热熔胶[合成路径]: 镍催化羰基化聚合","聚酮热熔胶[核心性能]: 低成本且可降解的高性能热熔胶"]},{"i":39679,"as":"研究基于多目标优化的压差质子交换膜水电解系统跨级耦合技术，探讨其在制氢效率与系统性能方面的协同优化机制。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["跨级耦合技术[压差质子交换膜水电解系统]: 多目标优化驱动，实现制氢效率与系统性能的协同优化"]},{"i":39680,"as":"探讨聚合物电解质膜燃料电池在特定高温下的降解机制，涉及电堆硬件测试，旨在提升燃料电池的耐久性与稳定性。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["降解机制测试温度[聚合物电解质膜燃料电池结合电堆硬件]: 80°C和95°C"]},{"i":39681,"as":"研究多微电网配电系统的协调优化调度方法，提出在频率感知孤岛约束下的非迭代策略，以提升系统运行稳定性。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["协调优化调度策略[频率感知孤岛约束下多微电网配电系统]: 非迭代策略"]},{"i":39682,"as":"提出一种双层优化框架，结合地理空间分析与深度学习预测，规划混合共享储能以提升多能源互补系统的可靠性。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["混合共享储能规划框架[提升多能源互补系统可靠性]: 集成地理空间分析和深度学习预测的双层优化框架"]},{"i":39683,"as":"探讨全球不同城市形态对车载光伏发电潜力的影响，研究城市空间结构、建筑环境与光伏产能效率之间的关联。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":3.0},"kp":["[全球不同城市形态]: 探讨城市空间结构、建筑环境与车载光伏产能效率之间的关联"]},{"i":39684,"as":"分析大规模泛欧能源系统模型中水电灵活性的丧失问题，探讨水电能力下降对整体能源转型和电网调峰的影响。","scd":{"b":3.0,"i":2.0,"r":5.0,"d":3.0,"t":3.0},"kp":["[大规模泛欧能源系统模型]: 水电灵活性丧失且水电能力下降，影响整体能源转型和电网调峰"]},{"i":39685,"as":"提出基于中观移动性方法的纯电动汽车快充规划策略，重新评估空间单元在充电基础设施布局中的关键作用。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[纯电动汽车快充规划]: 基于中观级别移动性方法，重新评估空间单元在基础设施布局中的作用"]},{"i":39686,"as":"研究阴离子交换膜光电化学水分解反应器在聚光条件下的性能，重点分析光热协同效应与气泡动力学对制氢的影响。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[聚光条件下阴离子交换膜光电化学水分解反应器]: 具有光热协同效应，气泡动力学对制氢过程产生影响"]},{"i":39687,"as":"构建氢能基础设施演化规划模型，结合状态变迁与内生层级形成理论，以京津冀地区为例进行实证分析与布局研究。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[京津冀地区氢能基础设施]: 构建结合状态变迁与内生层级形成理论的演化规划模型并进行布局研究"]},{"i":39688,"as":"提出一种动态感知深度强化学习算法，用于解决带时间窗和分时电价的电动车路径规划问题，旨在提升调度效率。","scd":{"b":5.0,"i":4.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[带时间窗和分时电价的电动车路径规划]: 采用动态感知深度强化学习算法以提升调度效率"]},{"i":39689,"as":"研究通过解码路径依赖指纹，探讨第二次生命（梯次利用）电池的退化机制与安全控制路径。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":3.0,"t":4.0},"kp":["[梯次利用电池]: 通过解码路径依赖指纹来探讨和控制电池退化机制与安全路径"]},{"i":39690,"as":"综述CCUS供应链的多目标优化研究，旨在平衡经济、环境与安全三方面的综合表现。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[CCUS供应链]: 进行多目标优化以平衡经济、环境与安全综合表现"]},{"i":39691,"as":"从数据驱动的视角综合评述异质固体废物热解制氢技术的研究进展与发展前景。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":3.0},"kp":["[异质固体废物热解制氢]: 从数据驱动视角综合评述技术进展与发展前景"]},{"i":39692,"as":"探讨燃料电池技术在固定式发电和交通运输领域的可持续应用现状及未来发展前景。","scd":{"b":4.0,"i":4.0,"r":4.0,"d":3.0,"t":3.0},"kp":["[燃料电池技术]: 在固定式发电和交通运输领域提供可持续电力应用"]},{"i":39693,"as":"传统辐射冷却面临制冷极限低和环境条件限制。该研究提出了一种蒸发辅助辐射冷却技术，通过结合蒸发与辐射的协同热力学效应，成功打破了辐射冷却的功率上限。文章总结了相关材料的设计方案和多种应用场景，并讨论了该技术面临的关键挑战，为开发实现能源可持续性的下一代先进被动冷却技术提供了全面的研究指南和路线图。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[蒸发辅助辐射冷却(协同热力学)]: 打破传统辐射冷却的功率上限和环境限制"]},{"i":39694,"as":"研究利用弯曲碳点这一几何限域平台，将曲率与原子活性位点的第二壳层配位进行耦合。这种协同调控机制将镍原子位点置于最优的电子状态，使其本征尿素氧化活性提升了近20倍。该技术不仅能实现节能制氢，还能同步修复含尿素废水，为高效电催化剂的设计及环境污染物处理提供了创新方案。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["脲氧化活性[Ni基碳点原子活性位点]: 提升近20倍","[曲率配位耦合]: 将Ni位点调控至最优电子态以实现节能制氢与含尿素废水的协同修复"]},{"i":39695,"as":"提出基于跨部门碳排放流量模型的电力、氢能与交通一体化三阶段低碳规划框架。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[电氢运一体化]: 建立基于跨部门碳排放流量模型的三阶段低碳规划框架"]},{"i":39696,"as":"研究针对局部灵活性市场，提出大型建筑能源灵活性的评估方法与预测技术。","scd":{"b":4.5,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[大型建筑能源灵活性]: 提出针对局部灵活性市场的评估方法与预测技术"]},{"i":39697,"as":"研究构建了一个自主微流控平台，结合流动化学、实时光谱学和贝叶斯优化技术，成功实现了对高质量CsPbBr3纳米片的自主合成控制。该系统能够快速确定合成条件以精准控制量子限制、发射颜色和光致发光效率。优化后的条件可直接转化为稳态连续制造，展示了自动驾驶实验室在加速先进量子材料的发现和规模化生产方面的巨大潜力。","scd":{"b":6.5,"i":5.0,"r":6.0,"d":6.5,"t":6.0},"kp":["[CsPbBr3纳米片(自主微流控平台)]: 结合流动化学、实时光谱和贝叶斯优化以控制量子限制并发现目标光学性能","[合成条件优化]: 可直接转化为稳态连续制造工艺"]},{"i":39698,"as":"提出一种新型绿色能源流驱动的多维跨时空决策框架，以提升氢能区域综合能源系统的能源效率。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[氢能区域综合能源系统]: 提出新型绿色能源流驱动的多维跨时空决策框架以提升能源效率"]},{"i":39699,"as":"研究开发了一种四组分钯催化的Suzuki-Miyaura偶联反应变体，成功将传统用于碳碳键形成的反应物转化为合成酰胺。该反应利用Mo(CO)6作为一氧化碳（CO）源，O-(二苯基磷酰基)羟胺（DPPH）作为NH源，通过顺序插入反应，合成了包括烯酰胺、α,β-不饱和酰胺在内的多种含芳香族和烯烃基团的仲酰胺，并能快速组装类药物化合物及其“反向酰胺”衍生物。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["催化反应[Pd催化Suzuki-Miyaura偶联]: 四组分反应利用C-C键形成试剂实现羰基胺化合成酰胺","反应组分[CO来源]: Mo(CO)6","反应组分[NH来源]: O-(二苯基磷酰基)羟胺(DPPH)"]},{"i":39700,"as":"针对钙钛矿太阳能电池中残余碘化铅（PbI2）引起的界面能量空间不均与器件不稳定问题，研究提出了一种双齿配位策略。新设计的基于噻吩的双齿配体（MeXT）能选择性地将残余PbB2重构为角共享的PbI6八面体，同时保持体相钙钛矿晶格不受扰动。这种双位点配位不仅稳定了PbI6单元，还实现了空间均匀的界面能量分布，显著提升了器件效率。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["钝化策略[消除残余PbI2不利影响]: 双铵双齿配体选择性重建残余PbI2","钝化机制[传统单齿配体缺陷]: 相互作用力弱或破坏三维钙钛矿晶格"]},{"i":39701,"as":"氢-氘交换质谱（HDX-MS）能快速识别药物结合位点并提供分子机制，但传统方法空间分辨率较低，通常只能提供5个及以上氨基酸片段的平均信息。该研究展示了一种达到单氨基酸分辨率（即位点特异性）的HDX-MS高灵敏测量方法。利用5种针对癌症靶点WDR5的候选药物，研究验证了该方法在深入探索蛋白质-药物相互作用动态变化方面的增强分析能力。","scd":{"b":5.5,"i":6.0,"r":6.0,"d":6.0,"t":5.0},"kp":["表征分辨率[传统HDX-MS技术局限]: 空间分辨率显著低于其他结构表征技术，通常仅提供片段平均信息"]},{"i":39702,"as":"应变环烷烃的开环反应是构建复杂有机分子的重要方法，但目前对环丙烷的异常高反应性缺乏全面解释。研究通过对12种应变环烷烃与甲基自由基及六种不饱和双自由基反应的计算模拟发现，除了由Bell-Evans-Polanyi（BEP）关系量化的应变释放能加速反应外，断裂σ键的双自由基特征（通过y0量化）是加速开环反应的另一关键驱动因素。","scd":{"b":4.5,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["应变释放[Bell-Evans-Polanyi关系]: 导致开环反应速率加速","反应性[含环丙烷分子的应变环烷烃]: 比BEP原理预测的更具高反应性"]},{"i":39703,"as":"探讨在需求响应不确定的条件下，面向工业消费者的数据驱动型随机动态零售电价制定策略。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[零售电价制定]: 采用考虑需求响应不确定性的数据驱动型随机动态策略"]},{"i":39704,"as":"研究开发了一种铜/配体/碱介导的统一合成策略，实现了无保护糖苷的高立体选择性合成。该方法利用易得的糖基磺酰肼在铜介导下生成糖基自由基，随后通过加成到各种自由基或不饱和键上，成功合成出多立体中心的烯基C-糖苷、烷基C-糖苷、芳基硫苷和芳基硒苷等传统方法难以获取的无保护糖苷，为治疗药物基础骨架的高效构建提供了新途径。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.5,"t":6.0},"kp":["合成策略[无保护糖基磺酰肼的自由基转化]: 铜介导的高度立体选择性合成无保护基团的多种糖苷"]},{"i":39705,"as":"研究报道了谷黄苷A-E（Glutinosasins A-E）的发散性不对称合成路线。针对具有前所未见的8,14-断裂-对映-贝壳杉烷骨架的A-D，该合成包含两个关键步骤：利用Baran还原烯烃偶联构建含有C10季碳中心的反式十氢化萘框架；以及利用路易斯酸介导的脱保护/反Claisen缩合级联反应构建8,14-断裂骨架。研究还通过C7-sp3和C7-sp2底物实现了十氢化萘框架的立体发散性构建。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["合成结构[谷黄苷A-D]: 具有前所未有的8,14-seco-ent-kaurane骨架的新子家族","合成步骤[构建反式十氢化萘]: Baran还原烯烃偶联建立含C10季碳中心","合成步骤[构建8,14-seco骨架]: 路易斯酸介导的脱保护/逆克莱森缩合级联反应"]},{"i":39706,"as":"介绍一种利用模块化PMDA连接器实现无保护肽的赖氨酸选择性环化及大环化合物自动组装的新方法。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":5.0},"kp":["环化与组装方法[未受保护肽]: 利用模块化PMDA连接器实现赖氨酸选择性环化及大环化合物自动组装"]},{"i":39707,"as":"可持续航空燃料（SAF）是满足未来航空业脱碳需求的核心技术方案。该综述对比了26种合成途径的效率、经济性、环境影响和可扩展性。目前监管批准的成熟SAF技术仅利用了全球100亿吨可用生物质和废料的一小部分，无法满足全球需求。新兴途径通过液化、发酵或气化将丰富的生物质转化为中间体，为规模化生产匹配喷气燃料特性的SAF提供了可行的扩展路径。","scd":{"b":4.0,"i":5.0,"r":7.0,"d":8.0,"t":4.0},"kp":["合成路径[已报道的SAF生产]: 26条合成路径","评估维度[SAF开发关键方面]: 效率、经济性、环境影响和可扩展性"]},{"i":39708,"as":"探讨如何通过发展海上风电来支持加拿大新斯科舍省边缘社区的公平能源转型。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":2.0,"t":3.0},"kp":["[海上风电发展]: 支持边缘社区实现公平能源转型"]},{"i":39709,"as":"研究通过在3.5 K的氩基质中对亚稳态亚磺酸（HOSOH）进行254 nm光解，首次成功生成并表征了实验上未曾报道的硫族键合一氧化硫-水复合物（OS···OH2）。HOSOH是通过叔丁基亚磺酸在600℃下快速真空热解制备的。结合红外、紫外/可见光谱和同位素标记实验，以及焦点计算，证实该三线态复合物比单线态亚磺酸能量高8.1 kcal mol-1，是大气和星际化学中的关键中间体。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":8.0,"t":5.0},"kp":["光解波长[生成一氧化硫-水复合物]: 254 nm","光解温度[氩基质中生成复合物]: 3.5 K","前驱体制备[次磺酸制备]: 叔丁基亚磺酸600 °C下闪式真空热解"]},{"i":39710,"as":"研究荷兰浮动光伏系统社区接受度的影响因素，探讨如何将公众拒绝转化为政策反思，涉及新能源社会学方向。","scd":{"b":1.0,"i":2.0,"r":4.0,"d":2.0,"t":3.0},"kp":["[浮动光伏系统]: 研究社区接受度的影响因素并转化为政策反思"]},{"i":39711,"as":"利用计量功率数据对多设施MRI设备的能源消耗与公用事业账单成本进行量化分析，涉及医疗设备能效评估。","scd":{"b":3.0,"i":2.0,"r":5.0,"d":3.0,"t":3.0},"kp":["[MRI设备能效评估]: 利用计量功率数据对多设施能源消耗与公用事业账单成本进行量化分析"]},{"i":39712,"as":"探讨加速中国支持的南亚及东南亚燃煤电厂退役的金融工具设计，涉及能源转型投融资政策与机制。","scd":{"b":2.0,"i":4.0,"r":6.0,"d":3.0,"t":4.0},"kp":["[燃煤电厂退役]: 设计相关金融工具以加速南亚及东南亚地区电厂退出"]},{"i":39713,"as":"批判性回顾质子交换膜燃料电池双极板的最新增材制造加工方法、性能表现及可扩展性，涉及3D打印技术。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["制造方法[质子交换膜燃料电池双极板]: 采用增材制造（3D打印）技术"]},{"i":39714,"as":"综合调查深度强化学习在增强多能源系统弹性方面的应用，探讨人工智能技术在提升能源网络抗风险能力的作用。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":3.0,"t":4.0},"kp":["[多能源系统弹性增强]: 综合应用深度强化学习(DRL)技术","[能源网络抗风险能力]: 利用人工智能技术进行提升"]},{"i":39715,"as":"分析超级电容器集成电动汽车的拓扑结构与技术经济性，并规划该技术的未来发展路线图，涉及储能与汽车工程。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[超级电容器集成电动汽车]: 评估拓扑结构与技术经济性"]},{"i":39716,"as":"评估配电网中光伏、电动汽车与储能系统联合接入的托管能力，探讨相关图示标准，涉及电网承载力规划。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[配电网(PV-EV-ESS联合接入)]: 评估联合接入的托管能力与规划图示标准"]},{"i":39717,"as":"评估并网地热及地热太阳能混合系统的技术经济性与负荷跟踪能力，涉及多能互补发电系统的综合性能研究。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[并网地热及地热太阳能混合系统]: 评估技术经济性与负荷跟踪能力"]},{"i":39718,"as":"提出一种阶段适应性优化框架，旨在协调能源转型过程中的能量平衡与灵活性平衡，涉及电力系统规划理论。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[能源转型阶段适应性优化]: 提出旨在协调能量平衡与灵活性平衡的优化框架"]},{"i":39719,"as":"剖析伊朗面临的能源悖论，探讨国际制裁、外部地缘冲突及国内治理陷阱对其能源产业与政策的综合影响。","scd":{"b":2.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[伊朗能源产业与政策]: 受国际制裁、外部地缘冲突及国内治理陷阱综合影响而陷入悖论"]},{"i":39720,"as":"青藏高原是全球重要的生物多样性热点，农业环境恶劣。研究评估了该地区1990至2020年的粮食生产数据，并建立模型预测未来趋势及气候变化下的风险。结果显示，三十年间粮食产量增长了32.33%，每日提供2892.98千卡热量。针对陡坡种植和过度放牧威胁未来生产力的问题，研究评估了在气候变化情景下，青藏高原同时实现粮食生产与环境保护双重目标的可行性。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":7.0,"t":4.0},"kp":["食物生产[评估阶段]: 1990年至2020年","农业威胁[青藏高原现状]: 陡坡上的农作物生产和过度放牧"]},{"i":39721,"as":"","scd":null,"kp":[]},{"i":39722,"as":"","scd":null,"kp":[]},{"i":39723,"as":"","scd":null,"kp":[]},{"i":39724,"as":"","scd":null,"kp":[]},{"i":39725,"as":"研究采用结合经验性结构连接和来自转录组数据的毒蕈碱型胆碱能受体（CHRM）图谱的生物皮层模型，探讨空间异质性对大尺度神经元动态的影响。研究发现，根据CHRM的空间组织调节与适应相关的兴奋性，能够塑造从清醒到睡眠状态的皮层大尺度动态。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["模型约束参数[大规模皮层模型]: 经验性人类结构连接(SC)和区域胆碱能毒蕈碱受体","模型能力[产生不同大脑状态]: 能够生成从清醒到睡眠状态的动力学"]},{"i":39726,"as":"","scd":null,"kp":[]},{"i":39727,"as":"","scd":null,"kp":[]},{"i":39728,"as":"","scd":null,"kp":[]},{"i":39729,"as":"","scd":null,"kp":[]},{"i":39730,"as":"研究通过将蛛丝蛋白重复区域的聚丙氨酸基序替换为非天然淀粉样β16肽，设计了新型迷你蛛丝蛋白，大幅提升了表达产量和溶解度。此外，开发了基于NaCl诱导液-液相分离（LLPS）的无色谱纯化方法。该策略一步完成纯化，比传统亲和色谱降低高达99%的加工成本，每升摇瓶培养物可获得约300毫克纯化蛋白，用于生产高性能混合丝纤维。","scd":{"b":7.5,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["蛛丝蛋白-淀粉样蛋白混合丝纤维[纯化工艺]: 免色谱纯化","迷你蛛丝蛋白[聚丙氨酸基序替换非天然淀粉样β16肽]: 显著增强表达产量和溶解度"]},{"i":39731,"as":"","scd":null,"kp":[]},{"i":39732,"as":"","scd":null,"kp":[]},{"i":39733,"as":"利用光学光热红外显微光谱技术，以亚微米空间分辨率研究了活体肝细胞中棕榈酸（PA）的代谢。研究发现，PA饲养后酯羰基拉伸在形态异常的脂滴附近的内质网（ER）中呈时间依赖性局部集中，这归因于甘油-3-磷酸途径中的二酰甘油中间体。氘代PA的C-D拉伸结果支持了一个模型：ER中PA酰链的紧密排列降低了酶扩散，促进了脂肪酸酯化和脂毒性。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":7.0},"kp":["光学光热红外显微光谱技术[活细胞内质网脂肪酸酯化成像]: 亚微米级空间分辨率"]},{"i":39734,"as":"研究展示了在高Q值微谐振器中经典线性光学的突破。长时间的光子约束使得由量子真空介导的罕见量子电动力学（QED）事件能够发生，将耦合分析物的独特拉曼特征嵌入谐振器的线性透射光谱中。增加吸附的分析物样品量可放大这些拉曼指纹，使其远高于噪声水平，利用最先进的光子架构即可实现实验观测。","scd":{"b":8.5,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["量子电动力学稀有事件[高Q值微谐振器]: 延长的光子限制使量子真空介导的事件将耦合分析物的拉曼特征嵌入谐振器"]},{"i":39735,"as":"","scd":null,"kp":[]},{"i":39736,"as":"研究报道了一种能量转移催化策略，实现了高烯丙醇与磷(III)试剂之间直接的光化学双自由基重排。计算支持的研究证实了能量转移介导的双自由基机制。该可见光驱动的温和过程通过自由基加成、β-断裂和重组，高效构建了带有张力的磷酸化环丙烷，具有广泛的底物适用性。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":5.0,"t":5.0},"kp":["自由基磷酸化[能量转移催化策略]: 引导反应性转向未探索的途径，实现高烯丙醇和磷(III)试剂之间的直接光化学双自由基重排"]},{"i":39737,"as":"研究通过将聚乙二醇（PEG）与吲哚胺2,3-双加氧酶（IDO）缀合延长了其循环时间，开发出用于治疗炎症的PEG-IDO蛋白疗法。在五种自身免疫和炎症模型中证明，单剂量PEG-IDO治疗即可逆转后肢等病症，展现出显著的治疗效果，且未产生毒性或损害免疫功能。","scd":{"b":6.5,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":["PEG-吲哚胺2,3-双加氧酶疗法[炎症性疾病治疗]: 无毒性且不损害免疫功能"]},{"i":39738,"as":"研究开发了一种可训练的液晶低聚物网络（LCON），可将数字信息直接存储在其分子构型中。通过用光开关偶氮苯对LCON进行功能化，利用双态系统在材料中集成了基础逻辑和记忆功能。所设计的可训练自推进门（T-SPG）能够通过光子刺激调节记忆，赋予了软材料基于外部信息的学习行为。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["可训练软电子器件[材料体系]: 液晶低聚物网络(LCON)","液晶低聚物网络[分子构型]: 可将数字信息直接存储于其分子配置中以实现学习行为"]},{"i":39739,"as":"研究引入了一种植入式生物电子插座（IBO），这是一种柔软的、组织状电子接口，能够实现植入电子器件与外部设备之间的按需直接欧姆连接。IBO由导电聚合物涂覆的低密度聚合物基体和疏水弹性体外套组成，允许重复插入外部触点而不产生裂纹扩展。该器件在植入一年后功能依然正常，能够高保真双向传输低压神经生理信号和电能。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["植入式生物电子插座[材料构成]: 导电聚合物涂层低密度聚合物基质，外部带有疏水弹性体护套","植入式生物电子插座[接口特性]: 柔性、组织状电子接口，支持植入电子器件与外部设备间按需的直接欧姆连接"]},{"i":39740,"as":"研究引入了一种多功能多孔界面，通过工程微孔网络将3D柔性电子器件与皮肤连接。这种多孔设计增强了弹性拉伸率和电学可靠性，同时具备透湿性、热缓冲和冲击缓解功能。该界面有效克服了3D电子器件几何复杂和机械脆弱的挑战，满足了可穿戴设备长期舒适佩戴和健康监测的需求。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["3D电子器件与皮肤界面[多功能多孔界面]: 解决几何复杂性和机械不匹配问题，实现长期舒适贴合"]},{"i":39741,"as":"研究利用长期数值模型和观测数据，隔离了越南湄公河三角洲采砂活动的具体影响。结果表明，采砂量是自然沉积物供应量的6至15倍，导致约65%的河道河床受到侵蚀，平均下切速率约为每年0.10米（占总下切量的25%至30%）。这种河道加深改变了水流，减少了沉积物传输，并加剧了盐水入侵。仅采砂一项就贡献了每年16%至30%的盐度增加量，在旱季使盐水向内陆多入侵约1.5公里。","scd":{"b":4.0,"i":6.0,"r":8.0,"d":9.0,"t":5.0},"kp":["采砂量与自然沉积物供应量比值[湄公河三角洲]: 超出6至15倍","河床侵蚀范围[越南湄公河三角洲]: 覆盖约65%的河道","平均下切速率[越南湄公河三角洲]: 约0.10米/年"]},{"i":39742,"as":"2024年12月，约1.4立方公里岩浆在埃塞俄比亚裂谷下方侵入并持续了约3个月。大地测量和地震数据表明，该大型岩墙由深度在6至12公里之间的岩浆储层网络补给。深层岩浆储层中形成的负压条件导致了大量岩浆的排出。研究指出，构造应力和充足的岩浆不足以驱动巨型岩墙侵入，此类事件仅在岩浆储层连通性建立后才会发生。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":9.0,"t":9.0},"kp":["岩浆传播体积[埃塞俄比亚裂谷堤坝入侵]: 1.4立方千米","岩浆活动持续时间[埃塞俄比亚裂谷堤坝入侵]: 约3个月","岩浆源深度[岩浆储层网络]: 6至12千米"]},{"i":39743,"as":"研究提出了一种名为透皮全向靶向（TADT）的静态接触界面设计策略，可将被动的握持表面转化为主动触觉显示器。该策略将微纹理皮肤耦合接口与相位控制的振动触觉驱动相结合，增强了致动器间距下的能量传递，从而在皮肤下方生成可操纵的三维触觉焦点。这项技术允许用户在稳定抓取物体（如把手、鼠标和手机）的同时，在指尖接收空间和时间上不断演变的信息，支持超过200赫兹的振动。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["界面设计策略[透皮全向瞄准(TADT)]: 将静态接触界面转变为主动触觉显示通道"]},{"i":39744,"as":"研究揭示了植物响应碳饥饿的协调程序，整合了外周分裂介导的损伤隔离和大规模线粒体自噬。碳饥饿触发线粒体从对称的中区分裂转变为不对称的外周分裂，产生去极化小碎片和极化大线粒体。大规模线粒体自噬靶向中等大小的线粒体，以减轻负担和调动资源，同时排除外周分裂的小产物。研究鉴定了碳饥饿诱导的ER-线粒体系链蛋白ML1，其负责协调上述外周分裂与自噬过程。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["线粒体重塑机制[碳饥饿触发]: 协调外周不对称裂变与大规模线粒体自噬"]},{"i":39745,"as":"通过结合卫星观测和气候模型模拟，研究绘制了气溶胶受限机制（即云属性对气溶胶变化高度敏感的区域）的全球分布及演变。结果显示，过去20年中该区域以每十年4.8%的速度扩张，主要归因于人为排放减少导致的北半球气溶胶受限区每十年急剧增加约14.7%。在强减排路径下，预计关键海洋区域的气溶胶受限频率将增加两到三倍，这种系统性转变将推动海洋云层分布发生变化。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["气溶胶受限区扩张速率[海洋云区相互作用敏感区]: 4.8%/decade"]},{"i":39746,"as":"聚乙烯在理论上是优异的导热体，但非晶体结构会阻碍热量传输。研究发现，在高取向聚乙烯中，部分有序的非晶体过渡相不仅是加工的副产品，更是热传导的关键贡献者。基于此，研究人员开发了一种凝胶态间歇慢拉伸方法，用于引导聚乙烯纤维形成过程中的非晶体演变。该方法促进了通常被认为是非晶和界面区域的链松弛和结构重组，从而显著提升了非晶富集聚乙烯纤维的导热性能。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["导热贡献机制[高取向聚乙烯非晶相]: 部分有序的非晶过渡相是热传导的关键贡献者"]},{"i":39747,"as":"研究提出了一种基于流体的机械多轴软力传感器（ME-SOFS），通过流体直接将传感信号与流体驱动耦合，消除了对外部计算或能量输入的需求。该传感器通过流体转换将施加的力转换为机械信号，建立直接的传感器-执行器连接，从而最小化机器人的计算需求。ME-SOFS可轻松重构和集成，赋予机器人体感多轴力传感能力，作为反应式系统机械模拟的物理组件。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["多轴力传感器[流体驱动柔性器件ME-SOFS]: 传感与流体驱动器直接耦合以消除计算处理模块"]},{"i":39748,"as":"研究开发了一种软可穿戴近红外光谱（NIRS）系统，用于检测睡眠期间与类淋巴活动相关的脑水动态。该设备集成了多波长LED和光电探测器。针对多名受试者的活体研究表明，该系统能在自然家庭环境中进行整夜睡眠监测，成功捕捉到不同睡眠阶段脑水动态的连续变化。研究结果证实了睡眠阶段依赖性的脑水动态变化，解决了连续实时监测的难题。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["近红外光谱系统[睡眠期脑水动态监测]: 软性可穿戴设备，具有多通道集成特征用于实时检测类淋巴活动"]},{"i":39749,"as":"通过在上地壳应力条件下对花岗岩样品进行流体注入实验，研究同时追踪了流体压力和无震滑动的传播过程。实验表明，在低注入速率和低初始应力下，无震滑动滞后于压力锋；而在高注入速率或接近破坏的初始应力条件下，无震滑动会迅速超过压力锋。这种转变由一个结合了注入速率、断层强度和初始剪应力的无量纲载荷参数控制，为断裂力学模型提供了直接的实验验证。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["无震滑动[流体注入]: 滞后于流体压力锋传播"]},{"i":39750,"as":"研究使用芘标记的聚酰胺胺树枝状聚合物，证实了十二烷基硫酸钠(SDS)胶束聚集体内部存在特定的表面活性剂微区域。这些微区域是由同一胶束聚集体内部带电表面活性剂与被氯化钠部分中和的表面活性剂之间的局部相分离造成的。带电和部分中和的表面活性剂分别构成了聚集体的极性边缘和非极性中间区域，树枝状聚合物在其中进行空间分配。其荧光响应直接与这些微区域的体积分数相关。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["胶束聚集体微区特征[SDS离子表面活性剂内部局部相分离]: 展现出由带电和氯化钠部分中和的表面活性剂分离形成的特定微观结构域"]},{"i":39751,"as":"羟基自由基（OH）是驱动平流层臭氧损耗的关键物质，但自2009年以来全球卫星观测数据存在严重断层。为此，研究人员开发了一种融合化学知识的深度学习网络“DRCAT”，利用化学相关物质的卫星观测数据来预测平流层OH廓线。仅需两年的数据训练，DRCAT即可重建自2004年底至今连续且可靠的全球平流层OH数据集。结果显示，DRCAT的预测精度优于化学传输模型和稳态近似法。此外，它还成功预测了2022年洪加火山喷发后OH的异常增加，展现出在极端条件下的强大泛化能力，为填补大气化学关键数据空白提供了有效工具。","scd":{"b":6.5,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["深度学习网络[DRCAT化学先验模型]: 使用重合卫星化学观测数据来预测平流层OH自由基剖面，填补观测数据空白"]},{"i":39752,"as":"","scd":null,"kp":[]},{"i":39753,"as":"三维Chern绝缘体的标志性特征是拓扑陈向量，它将体-边对应关系从二维扩展到三维系统。以往陈向量仅局限于只有一个非零分量的最简单形式，这限制了手性表面态仅出现在四个侧面上，且沿陈向量方向不具备手性传输特性。本研究在光子系统中实现了光子任意陈向量，突破了现有结构限制，为三维拓扑绝缘体研究提供了新视角。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["拓扑属性[三维光子绝缘体]: 表现出将体-边对应关系从二维扩展到三维的拓扑陈向量(C1, C2, C3)"]},{"i":39754,"as":"受石蛾幼虫案例的启发，研究开发了一种具有高韧性和增强离子传输能力的凝胶聚合物电解质（CLC GPE）。该电解质将静电纺丝聚偏氟乙烯-六氟丙烯支架与剪切增稠流体相结合。CLC GPE实现了2.80×10^-3 S/cm的高离子电导率和0.89的锂离子迁移数，并表现出7.29 MJ/m^3的优异韧性和极强的抗穿刺能力，有效克服了锂金属电池中凝胶电解质离子导电性与机械强度之间的权衡问题。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["凝胶聚合物电解质[仿石蛾幼虫案例CLC GPE]: 结合高韧性与增强的离子传输能力，用于安全锂金属电池"]},{"i":39755,"as":"研究通过共递送CIITA、NLRC5、CD80和IL-2，将肿瘤细胞重编程为抗原呈递细胞，开发出具有全抗原谱覆盖的通用“一体化”癌症细胞衍生疫苗（UniCVac）。这种重编程模拟了专业抗原呈递细胞的表型，能够同时提供HLA-I和HLA-II抗原呈递。该方法克服了抗原覆盖有限、抗原呈递不足和免疫抑制微环境等临床开发挑战，有效引发或增强T细胞反应以降低肿瘤负荷。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["癌症疫苗[通用“一体化”工程改造]: 具备全抗原谱"]},{"i":39756,"as":"研究通过热冲击剥离萤石结构的Gd0.1Ce0.9O1.95，制备了Ce-Gd-O团簇。这些无序且被空位隔离的团簇在无需长程有序结构的情况下，形成了渗流氧离子传输路径。在400°C条件下，该材料实现了2.14 ± 0.09 S/cm的优异氧离子电导率，比以往大多数传统材料高出320倍以上，成功克服了传统氧离子导体工作温度过高和低温电导率不足的长期挑战。","scd":{"b":8.5,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[Ce-Gd-O团簇制备]: 热冲击剥离萤石Gd0.1Ce0.9O1.95","[无序空位隔离Ce-Gd-O团簇]: 实现优异的低温氧离子电导率，克服低温电导率瓶颈"]},{"i":39757,"as":"受微生物非神经处理自主性的启发，研究开发了具有胃肠道内具身记忆和逻辑功能的物理智能胶囊机器人（PI Capbots）。该系统在尺寸、电源和生物安全性受到严格限制的条件下，紧密集成传感、决策和驱动功能。它基于压力、温度和pH等生理指标阈值执行事件触发策略，无需复杂的闭环数字代码或外部计算，即可实现稳态监测和原位治疗。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":6.5,"t":7.0},"kp":["[胃肠道胶囊机器人生理监测阈值指标]: 压力、温度、pH"]},{"i":39758,"as":"研究提出了一个肺泡球筛选平台，用于研究肺干细胞与其成纤维细胞微环境之间的相互作用。通过对201个候选基因进行评估，并结合嵌合RNA测序分析，研究构建了表型-转录组图谱。该图谱揭示了调节增殖、代谢和免疫信号的细胞状态和通路。研究发现，肺干细胞能影响成纤维细胞的瘢痕形成和免疫程序，且该损伤反应依赖于特定的干细胞身份。","scd":{"b":6.5,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["候选基因数量[肺泡干细胞评估]: 201","[转录组分析]: 嵌合体RNA测序用于研究细胞自主与非细胞自主效应"]},{"i":39759,"as":"茧蜂科的寄生蜂依赖茧病毒来寄生鳞翅目宿主。尽管茧病毒编码了8个杆状病毒经口感染因子(PIF)的同源物，但由于茧病毒是由黄蜂直接注射入宿主体内的，其缺乏传统的经口感染途径，进入宿主细胞的机制此前尚不明确。本研究利用中红侧沟茧蜂及其宿主（粘虫和棉铃虫），证实了这些PIF同源物对于茧病毒在宿主体内的感染以及黄蜂的成功寄生是必不可少的。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["经口感染因子同源物数量[布拉科病毒]: 8个PIF同源物","[经口感染机制]: 布拉科病毒缺乏经口感染途径，由黄蜂直接将病毒粒子注射入宿主"]},{"i":39760,"as":"研究发现铁死亡相关的氧化应激是胰岛β细胞死亡的关键原因。为解决抗氧化药物胃肠转运差和胰腺靶向性不足的问题，研究人员通过将弯曲油酸嵌入有序的1,2-二硬脂酰-sn-甘油-3-磷酰乙醇胺中，制备了六种硬度梯度的纳米颗粒。具有中等硬度的纳米颗粒能够优化细胞膜包裹并最小化能量消耗，从而显著提高药物的生物利用度，有效促进受损胰岛β细胞的修复，用于糖尿病治疗。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[胰岛β细胞死亡关键诱因]: 铁死亡相关的氧化应激","[口腔纳米颗粒特性]: 硬度可调","[口腔纳米颗粒功能]: 促进受损胰岛β细胞修复"]},{"i":39761,"as":"补体级联反应是对抗病原体感染的核心固有免疫机制。C5a衍生多肽EP67是一种极具前景的免疫刺激候选物，在抗病毒和抗菌临床前研究中表现优异。药理学分析表明，EP67对人源C3aR具有优先激活作用。该研究揭示了EP67发挥作用的分子机制及其精确受体靶点。","scd":{"b":6.5,"i":3.5,"r":6.0,"d":6.0,"t":6.0},"kp":["免疫刺激先导候选物[C5a衍生]: EP67十肽","[研发状态]: 最先进候选物，处于临床前阶段"]},{"i":39762,"as":"路易斯·E·布鲁斯（1943-2026）是纳米科学领域的真正先驱与杰出的物理化学家。他一生淡泊名利，始终专注于以纯粹的好奇心去解决科学难题。他的职业生涯彰显了好奇心驱动型科学的巨大力量，是20世纪80至90年代贝尔实验室所孕育的极具影响力的科学精神的完美体现。作为一名极度注重合作的“贝尔实验室式”学者，布鲁斯不仅才华横溢，更以其卓越的指导能力和友善的品格著称。他的智慧、教诲与温和的精神将永远被朋友、学生及同事们深切缅怀。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":3.0,"t":3.0},"kp":["[科研环境]: 1980至1990年代贝尔实验室培育的好奇心驱动型科学"]},{"i":39763,"as":"对生物化学家Daniel Herschlag的专访，主要涉及其在RNA催化、蛋白质生物化学及分子相互作用机制等领域的学术见解与研究进展探讨。","scd":null,"kp":["[研究领域]: RNA催化、蛋白质生物化学及分子相互作用机制"]},{"i":39764,"as":"球粒陨石是太阳系早期形成的重要物质，其具体产生机制一直存在争议。研究发现，在类地行星形成的晚期阶段，原行星胚胎间的碰撞产生熔融物质，冷却后形成球粒。这些物质在胚胎周围碎片的盘中与未熔融物质混合，聚集形成小行星大小的卫星。随后由于与其他胚胎的引力作用，这些卫星被弹射至日心轨道。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[陨石母体形成途径]: 类地行星形成晚期通过胚胎-胚胎碰撞产生含球粒的陨星小行星"]},{"i":39765,"as":"海洋云增亮（MCB）是一种旨在减少长期变暖的太阳地球工程方法。模拟2019-2020年澳大利亚野火实验表明，东南太平洋的MCB可重现云层变亮及随后的拉尼娜响应。针对1997-1998和2015-2016年厄尔尼诺事件的模拟显示，在厄尔尼诺增长期实施MCB可破坏比耶克尼斯反馈机制，从而削弱随后的厄尔尼诺现象。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[2019-2020年澳大利亚野火烟雾]: 削弱了随后的厄尔尼诺现象，作为区域性海洋云增亮(MCB)的自然类似实验"]},{"i":39766,"as":"","scd":null,"kp":[]},{"i":39767,"as":"俯冲带是将地表硫带入地幔的主要途径。通过整合大洋钻探沉积物成分与地震数据导出的地壳厚度，研究揭示了俯冲硫通量的显著空间异质性。这种异质性由沉积物硫含量的大幅变化以及侵蚀型和增生型边缘的根本构造差异驱动。计算表明，板块到火山弧的硫循环效率平均为37%。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["[俯冲带]: 是地表硫进入地幔的主要通道，主导深部硫循环"]},{"i":39768,"as":"","scd":null,"kp":[]},{"i":39769,"as":"","scd":null,"kp":[]},{"i":39770,"as":"古罗马混凝土结构之所以能保持近两千年的耐久性，除了火山灰与石灰之间的火山灰反应外，长期的碳化作用同样起到了关键增强效果。对哈德良别墅遗址中混凝土的多尺度光谱和断层扫描分析证实，矿物化碳酸盐的生成不仅显著提升了材料的耐久性，还赋予了混凝土潜在的自修复特性。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[罗马混凝土千年耐久性增强机制]: 碳酸盐矿化（长期碳化）除了火山灰反应外，显著增强了耐久性和潜在的自愈合特性"]},{"i":39771,"as":"为克服传统丙烷脱氢高能耗及加氢甲酰化依赖化石合成气的局限，研究提出了一种二氧化碳辅助的氧化脱氢-加氢甲酰化（CO2-ODH-HF）级联工艺。该工艺通过CO2-ODH反应器替代传统脱氢过程，并循环利用CO2在系统内部生成一氧化碳和氢气。Aspen Plus模拟证实，该反应架构的重组实现了合成气的自给自足。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":7.0,"t":5.0},"kp":["[CO2-辅助氧化脱氢-加氢甲酰化(CO2-ODH-HF)级联工艺]: 替代传统丙烷脱氢，实现合成气自给自足及高效的丙烷升级"]},{"i":39772,"as":"","scd":null,"kp":[]},{"i":39773,"as":"","scd":null,"kp":[]},{"i":39774,"as":"传统理论预测非本征铁电体（由非极性结构畸变等主导序参量引发的电极化）不存在本征厚度极限，但实验中长期观察到其在薄膜厚度低于6个公式单位时铁电性消失。为突破该限制，本研究打破了主要关注面内晶格失配和化学键的传统外延设计范式，引入了面外方向的结构兼容性考量。基于此策略，研究人员成功在单层极限下实现了毫不减弱的非本征铁电性。该成果不仅证实了非本征铁电体不存在临界厚度的理论预测，还为未来设计更多超薄铁电材料提供了一种广泛适用的通用策略。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":5.0},"kp":["[非本征几何铁电性(单层极限下)]: 突破传统外延设计，在低于6个晶胞单元厚度下依然保持铁电性"]},{"i":39775,"as":"早产儿支气管肺发育不良（BPD）的分子机制尚不明确。研究开发了一种多模态成像工作流，结合质谱与非线性光学成像技术，在多个空间尺度上对肺组织进行详细的分子和代谢表征。同时建立的分层多模态配准网络，实现了不同模态数据的精确配准，为理解肺组织异质性及相关疾病的代谢改变提供了新方法。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":7.0,"t":5.0},"kp":["[肺组织多尺度代谢图谱绘制]: 结合配准质谱和非线性光学成像技术"]},{"i":39776,"as":"基于卫星热红外观测数据对美国287座大坝上下游河流表面温度的量化分析显示，71%的纵向河流剖面存在下游温度差异。这些变化中60%表现为温度升高，且平均升温状态在坝下20公里范围内持续或继续增加。不同类型大坝对河流热力状况的改变程度和频率存在差异，91%的极端温度事件由特定大坝类型造成。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["热力状况[美国大坝]: 卫星热红外观测量化上下游河流温差"]},{"i":39777,"as":"早期人类在采纳玉米作为主食时面临必需氨基酸赖氨酸缺乏的营养挑战。对伯利兹南部距今6100至1100年前人类骨骼氨基酸碳同位素数据的分析表明，早期人群通过食物链放大效应，从食用玉米的动物中获取了大量玉米来源的蛋白质和赖氨酸。这种动物蛋白补充策略有效弥补了单以玉米为碳水来源的营养缺陷。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":5.0,"t":2.0},"kp":["营养缺陷[玉米主食]: 缺乏必需氨基酸赖氨酸"]},{"i":39778,"as":"毒牙、毒刺和棘刺等生物穿刺结构在不同物种中趋同演化。工程学分析表明，将140多种生物的穿刺工具映射到力学性能景观中，其多样性受到抗屈曲能力和穿刺效率之间权衡的强烈影响。生物在这一权衡光谱上的位置与其生物学功能密切相关，但与该工具是否可替换关联不大。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":5.0,"t":2.0},"kp":["[生物穿刺工具]: 机械性能权衡影响其多样性"]},{"i":39779,"as":"多参数量子估计面临的核心挑战在于不同参数最优测量的不兼容性，导致复杂的精度权衡。该研究提出了一种新方法，能够精确量化这些权衡关系。该方法为理解多参数估计的量子极限提供了明确的理论工具，有助于在多参数量子估计系统中找到最优测量方案，相关成果发表于《物理评论快报》。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["精度权衡[多参数量子估计]: 提出精确量化最小权衡与最优测量的方法"]},{"i":39780,"as":"为提升量子传感器搜索波状暗物质的灵敏度，研究提出一种受量子纠错启发的噪声抑制协议。该协议利用多个传感器协同工作，能够有效抑制影响各个传感器的独立噪声，特别是有效滤除激发态噪声干扰，从而大幅提高暗物质探测的灵敏度和准确性，发表于《物理评论快报》。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":8.0},"kp":["噪声抑制[波状暗物质搜索量子传感器]: 利用量子纠错启发式协议抑制激发噪声"]},{"i":39781,"as":"研究重新审视了厄米特矩阵的SU(N)对称量子力学在N趋于无穷大时的极限。已知其单重态扇区可通过自由费米子精确求解，当费米能级接近势能最大值时，系统表现出对应于弦理论的临界行为。该工作深入探讨了此模型中伴随扇区的雷格轨迹（Regge trajectories）特性，为理解矩阵量子力学和弦理论的联系提供了新视角。","scd":{"b":9.0,"i":1.0,"r":7.0,"d":4.0,"t":8.0},"kp":["[厄米矩阵SU(N)量子力学]: 当费米能级接近势能最大值时呈现临界行为"]},{"i":39782,"as":"LHCb合作团队对中性B介子的罕见衰变过程进行了新的综合测量分析。这项关于B0→K*0μ+μ−衰变的新测量结果为探索超出标准模型的新物理现象提供了重要线索。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":["[B0介子]: 罕见衰变测量可能预示新物理"]},{"i":39783,"as":"LHCb合作团队利用第三期运行的探测器，首次成功观测到了双重魅力重子Ξcc+。该重子通过衰变为Λc+K−π+的末态被探测到，其统计显著性超过了七个标准偏差。这一重大发现基于质子-质子碰撞数据。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["观测显著性[双重魅力重子Ξcc+]: 超过七个标准差"]},{"i":39784,"as":"拉姆齐干涉测量是一种用于光谱学、时间频率精确测量以及现代原子钟的高分辨率技术。传统实验通常在光学稀薄原子样本中进行。本研究提出在光学厚原子系综中进行拉姆齐干涉测量，实现了指数级的线宽缩小和测量灵敏度的显著增强。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":5.0,"t":8.0},"kp":["[光学厚原子系综拉姆齐干涉]: 呈现指数线宽缩小和灵敏度增强"]},{"i":39785,"as":"经典涨落耗散定理将平衡态噪声与线性响应联系起来，是统计物理的基石。本研究将这一理论扩展至几何驱动的非线性输运领域，建立了一个全新的量子几何涨落-耗散关系，用于描述直流非线性输运现象。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":8.0},"kp":["涨落-耗散关系[非线性输运]: 建立量子几何驱动的非线性直流输运关联"]},{"i":39786,"as":"针对时间分辨角分辨光电子能谱(TR-ARPES)中解释激子引起的能带结构变化缺乏微观理论框架的问题，本研究提出了一个统一的第一性原理公式。该理论模型能够定量且微观地解释相干与非相干激子效应，并且其适用范围突破了传统低密度的限制。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":5.0,"t":8.0},"kp":["[解释激子诱导能带结构改变的微观理论框架]: 突破低密度限制的第一性原理定量公式"]},{"i":39787,"as":"在二硒化钨(WSe2)封装的单层石墨烯中实现了纯Valley-Zeeman自旋轨道耦合的定制。通过清晰分辨的朗道能级，实验揭示了由固定的Valley-Zeeman劈裂与依赖于磁场的回旋能之间的相互竞争所驱动的、由对称性强制决定的朗道能级重排现象。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":8.0},"kp":["[WSe2封装单层石墨烯]: 实现纯Valley-Zeeman自旋轨道耦合的定制","[对称性强制下的朗道能级重排机制]: 由固定谷-塞曼分裂与随磁场变化的回旋能竞争驱动"]},{"i":39788,"as":"这是一篇针对题为“1T-TiSe2中手性电荷密度波的光致动力学和动量分布”的学术论文的评论文章。文章针对原研究中关于1T-TiSe2材料的光致动力学过程和动量分布特征的结论或方法进行了探讨。","scd":{"b":4.0,"i":1.0,"r":3.0,"d":2.0,"t":8.0},"kp":["[1T-TiSe2]: 存在手性电荷密度波的光致动力学和动量分布特征"]},{"i":39789,"as":"这是针对上述关于1T-TiSe2材料中手性电荷密度波动力学研究评论的作者回复。邱(Qiu)等人对之前评论中提出的问题和质疑进行了正面的解答与学术探讨。","scd":{"b":4.0,"i":1.0,"r":3.0,"d":2.0,"t":8.0},"kp":[]},{"i":39790,"as":"传统观点认为扩散方程由于具有抛物线特性会导致物质瞬间空间分布，在洛伦兹变换下不稳定，这与狭义相对论在根本上是不可调和的。本研究证明了这种不相容性只是一种表象，并提出了使扩散方程与狭义相对论完全兼容的理论方法。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":4.0,"t":8.0},"kp":["[洛伦兹 boost 状态]: 扩散方程依然与狭义相对论兼容"]},{"i":39791,"as":"光子超晶格中的平带能够实现强光限制和增强的光与物质相互作用。本研究提出了一种通过M个子空间之间的耦合机制，在整个布里渊区内产生平带色散的实用方法，成功实现了由解耦子空间引起的光子平带。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":["[光子超晶格系统]: 通过解耦子空间耦合机制实现跨越整个布里渊区的平带"]},{"i":39792,"as":"重离子碰撞中的喷射淬火现象提供了探索夸克-胶子等离子体性质的微观途径。由于传统的全局观测量(如RAA)无法捕捉部分子与介质相互作用复杂动力学的全部信息，本研究采用监督学习算法，对重离子碰撞模拟中的喷射淬火现象进行了高效识别与分析。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":4.0,"t":8.0},"kp":["[重离子碰撞体系]: 采用监督学习识别喷射淬火以揭示夸克-胶子等离子体微观性质"]},{"i":39793,"as":"针对电池去离子化系统中由于相似碱金属离子竞争吸附导致锂提取选择性低的问题，本研究提出了一种分子离子门控策略。通过在LiMn2O4核外包裹功能化氧化石墨烯壳层构建核壳结构，成功实现了高选择性的锂离子传输，将选择性与容量解耦，显著加速了锂提取过程。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":7.0,"t":8.0},"kp":["[电池脱离子系统中的复杂盐水提锂]: 采用分子离子门控策略解耦选择性与插层动力学，抑制钠离子竞争通量"]},{"i":39794,"as":"针对关于视觉感知与最小曝光时间的学术论文的回复，探讨了视觉处理机制的临界时间参数及视觉认知模型的学术争议与延伸探讨。","scd":{"b":3.0,"i":1.0,"r":2.0,"d":2.0,"t":7.0},"kp":["[视觉感知处理]: 存在临界最小曝光时间参数限制"]},{"i":39795,"as":"为了体外构建仿生胰岛，研究人员结合谱系标记和单细胞多组学分析，揭示了人类干细胞衍生α与β细胞的命运分配机制。研究证实在人类细胞中存在特异性的转录因子Arx和Pax4调控网络，解决了人类α与β细胞命运分配机制的关键难题。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[人类干细胞衍生α与β细胞的命运分配机制]: Arx和Pax4转录因子在内分泌祖细胞中相互交叉抑制"]},{"i":39796,"as":"针对水面自主重构的挑战，研究团队开发了名为FloatForm的自重构模块化机器人船平台。这些微型机器人船能够克服非线性水动力和环境干扰，自主组装成物理连接的结构并进行重构，通过混合协调框架实现作为大型组装体的集体移动，可广泛用于海洋基础设施建设与搜救。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[水面二维自主重构]: 克服复杂非线性水动力学及环境干扰实现自主配置"]},{"i":39797,"as":"利用木材天然的层级结构，研究人员通过浸涂带正电或负电聚合物并经阳光诱导聚合，制备出环保型阴/阳离子选择性木膜。在脱硫废水调节液中，单个改性木质发电机产生了55 mV的电压和0 µA的电流，比未处理木材高出十倍，实现了从废水中连续发电。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["环保材料占比[木质离子选择性发电机]: 98%","[废水溶解性带电固体发电]: 采用2-(二甲基氨基)乙基甲基丙烯酸酯或带负电的丙烯酸浸涂制备表面包封的阴/阳离子选择性木膜"]},{"i":39798,"as":"对索尔顿海地热盐水大规模提锂项目的技术经济分析表明，地热盐水是一种极具潜力的替代资源。研究基于浓度变化和工艺配置(如碳酸盐转化或电解法)建模发现，其大规模生产成本约为每吨10000美元，在更高浓度或特定工艺下最高可能达到每吨22000美元，具有商业可行性。","scd":{"b":5.0,"i":6.0,"r":8.0,"d":9.0,"t":6.0},"kp":["[索尔顿海地热盐水提锂]: 开展设施级技术经济评估，以克服商业化进程阻碍"]},{"i":39799,"as":"硅自旋量子比特具备高相干性和CMOS可制造性。研究团队在300毫米CMOS代工厂工艺中制造了一个八点线性阵列硅自旋量子比特，成功实现了八个量子比特的调谐与相干控制。这些量子比特的拉姆齐退相干时间(T2*)最高达41微秒，哈恩回波相干时间(T2Hahn)达1.31毫秒。","scd":{"b":8.0,"i":6.0,"r":8.0,"d":8.0,"t":7.0},"kp":["量子位阵列[300mm SiMOS代工制造]: 八量子位线性阵列","控制能力[硅自旋量子位]: 成功实现相干控制"]},{"i":39800,"as":"为实现最高密度的数据存储，本研究展示了利用磁交换力显微镜对单原子进行读写操作。通过测量磁性针尖与镁氧化物薄膜上的钬原子之间的交换力实现信息的读取；通过将针尖靠近钬原子改变其自旋方向实现信息的写入。该力学读写机制具有低发热和高密度记录的优势。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":5.0},"kp":["信息读写机制[单原子磁体]: 基于磁交换力显微镜的机械相互作用","读写对象[MgO薄膜上的单个钬吸附原子]: 自旋取向","运行优势[机械交互读写磁器件]: 低发热与高密度记录"]},{"i":39801,"as":"为了突破传统DNA分子工程仅关注正交性的局限，研究人员开发了一种名为BINND的深度学习模型。该模型基于数百万次DNA-DNA相互作用测试数据进行训练，能够准确且快速地预测非正交的DNA分子间相互作用，准确率超过80%，为设计超连接网络和合成生物学提供了新工具。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["技术突破[深度学习预测DNA-DNA结合]: 准确快速预测非正交相互作用并设计超连接网络"]},{"i":39802,"as":"神经形态计算的核心挑战之一是模拟大脑的稳态可塑性。本研究发现，CuInP₂S₆(CIPS)忆阻器能够自然实现完整的Bienenstock-Cooper-Munro(BCM)规则。器件的固有结电容会产生反向尖峰，结合二阶离子动力学，成功复制了BCM规则中基于历史活动调整神经元敏感度阈值的关键特征。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["突触器件实现[BCM规则]: CuInP₂S₆忆阻器","仿生特性[BCM规则突触器件]: 自然实现稳定神经活动的稳态可塑性"]},{"i":39803,"as":"研究提出了一类结合长程周期性和自相似层次的分形启发晶格，实现拓扑边界态的指数级缩放。通过由科赫曲线单元构建的准一维晶格链和谢尔宾斯基三角形单元构建的二维周期性平铺晶格进行验证。结果表明，在适当的耦合参数下，拓扑边界态的数量和拓扑微间隙的数量均呈现指数级增长。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":4.0},"kp":["结构基元[分形启发晶格]: 结合长程周期性有序与自相似层级","缩放特性[拓扑边界状态]: 指数级缩放"]},{"i":39804,"as":"研究阐明了掺杂电荷转移绝缘体中的束缚态物理机制。研究提出基于局部张-莱斯单态和奈尔态的近似基态波函数，发现掺杂引入的局域空穴会在电荷转移能隙内部形成束缚态。通过基于矩阵乘积态的Lanczos计算，在4x4 CuO2单胞系统中证实了该束缚态的存在，并进一步探讨了其向金属态演化的过程。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":6.0,"t":4.0},"kp":["物理机制[掺杂电荷转移绝缘体]: 局域空穴产生能隙内束缚态","近似基态波函数[掺杂电荷转移绝缘体]: 基于一个局域Zhang-Rice单态和Néel态构建"]},{"i":39805,"as":"研究展示了一种可逆堆叠的单片三维互补场效应晶体管架构。该架构采用低温沉积的n型In2O3和p型Te半导体，突破了后端工艺温度必须低于400℃的热预算限制。此方法避免了高温生长或转移需求，解决了现有固定堆叠顺序的局限，为高密度、高能效的逻辑与存储系统提供了设计自由度。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["热预算限制[后端工艺(BEOL)]: 严格低于400℃","堆叠架构[单片3D集成电路]: 可逆堆叠顺序"]},{"i":39806,"as":"关于碳化钛MXene材料超快电荷传输研究的勘误，推测主要涉及光热效应在二维纳米材料中调控载流子动力学与光电性能的机制分析。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":2.0,"t":5.0},"kp":["[碳化钛MXene]: 光热效应主导超快电荷传输与载流子动力学调控"]},{"i":39807,"as":"研究提出全量子化框架，分析红外明亮压缩真空（BSV）脉冲在产生高次谐波气体介质中的宏观传播效应。研究发现，电离及其伴随的光子损耗会引起退相干，从而限制传播长度，降低辐射的量子特性并减少谐波发射。该理论弥补了以往仅关注单原子相互作用的不足，明确了BSV在非线性介质中的传播规律。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["光与物质相互作用[明亮压缩真空光(BSV)介观传播]: 揭示非线性介质中的宏观传播效应及其对辐射量子特性的影响"]},{"i":39808,"as":"","scd":null,"kp":[]},{"i":39809,"as":"研究证明横向力显微镜（LFM）可用于检测和分类二硫化钼（MoS2）中的原子空位。打破了以往认为LFM对最顶层原子层下方的结构特征不敏感的传统观念。通过悬臂的横向扭转测量摩擦力，LFM技术能够根据空位的深度对其进行精确识别和分类。这一成果为低维系统缺陷的表征提供了有效的新方法。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["表征技术[MoS2表面缺陷探测]: 测量摩擦力的横向力显微镜(LFM)","探测能力[二维低维材料]: 揭示表面和次表面原子空位"]},{"i":39810,"as":"研究针对扭曲双层石墨烯系统，提出了微观超导理论。理论模型揭示了一种具有凯库勒调制的谷内有限动量对密度波（PDW）配对机制。该超导态具有三大特征：自发打破C3旋转对称性产生向列序、三重态配对，以及准粒子态密度随吸引力增加从V型演化为完全带隙的U型光谱。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["超导配对机制[扭曲双层石墨烯]: 谷内有限动量的对密度波(PDW)","本征特征[有限动量超导对]: 内禀携带凯库勒(Kekulé)序"]},{"i":39811,"as":"研究利用金刚石压砧中的原位高压高温同步X射线衍射技术，在两种典型金属合金中揭示了液态和玻璃态多晶型之间的直接对应关系。在熔点以上观察到不同的液态，并在不同压力下熔体淬火形成相应的玻璃态，结构描述符表现出可重复的不连续变化。该研究阐明了平衡液体与非平衡玻璃之间的结构联系。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[致密金属合金]: 揭示了平衡态液体与非平衡态玻璃之间多晶型结构的直接对应关系"]},{"i":39812,"as":"研究成功构建了高度可逆的非水系氢氧化锂基锂-氧电池，采用铁钴镍层状双氢氧化物催化剂和环丁砜基电解液。研究证实，氢氧化锂分解释放氧气的过程涉及表面羟基和羟基自由基等活性氧物种，但不产生单线态氧。这些羟基物种会腐蚀电解液和碳载体，是导致寄生反应的主要因素。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["催化体系[非水LiOH基锂氧气电池]: 铁钴镍层状双氢氧化物","氧气析出反应[非水锂氢氧化物基锂氧气电池]: 可逆四电子转移过程"]},{"i":39813,"as":"关于扫描量子点显微镜技术的勘误，该研究涉及利用高分辨率量子传感手段在原子尺度上精确量化金属表面纳米结构的局部静电势。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":2.0,"t":5.0},"kp":["[扫描量子点显微镜]: 原子尺度精确量化金属表面纳米结构的局部静电势"]},{"i":39814,"as":"研究利用冷冻电镜技术解析了BAM-BepA复合物结构，揭示了BepA蛋白在外膜蛋白质量控制中的机制。BepA结合后会引起BAM复合物发生大范围构象变化，使其活性位点定位于BamA桶状结构下方。BepA的盖子具有动态性，将两个水溶性螺旋嵌入脂质双层深处，从而为错误折叠外膜蛋白的蛋白水解过程做好准备。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["机制[BAM-BepA复合物质量控制]: BepA诱导BAM复合物发生大幅构象变化并降解未折叠底物"]},{"i":39815,"as":"研究开发了一种名为“Phylo-Plex”的低成本扩增子测序平台，专为低资源环境下的高分辨率基因组流行病学设计。该技术通过选取信息丰富的基因组区域，最大化系统发育信息。针对梅毒螺旋体和淋病奈瑟菌设计了多重PCR测序方案。利用MinION Flongle对72份临床样本进行测试，成功实现了极端基因组变异病原体的谱系追踪。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["测序平台设计[Phylo-Plex]: 选取信息丰富的基因组区域以最大化系统发育信息并最小化靶标数量","技术特征[低成本扩增子测序]: 基于系统发育的多重PCR测序系统"]},{"i":39816,"as":"","scd":null,"kp":[]},{"i":39817,"as":"","scd":null,"kp":[]},{"i":39818,"as":"","scd":null,"kp":[]},{"i":39819,"as":"","scd":null,"kp":[]},{"i":39820,"as":"","scd":null,"kp":[]},{"i":39821,"as":"研究利用基于三重分选的方法，成功组装了北美 Silphium 属两个物种的阶段性基因组。基因组染色体长达1.8 Gb。基于基因组的低覆盖度和靶向测序策略，研究人员完善了该属的系统发育，揭示了自然种群的空间分布，并鉴定出81个与环境和驯化性状相关的基因位点，为分子育种奠定了基础。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":7.0,"t":4.0},"kp":["染色体大小[Silphium属间杂种基因组]: 1.8 Gb","组装策略[Silphium基因组]: 利用三重分选进行基因组分型组装"]},{"i":39822,"as":"","scd":null,"kp":[]},{"i":39823,"as":"关于水生生物生殖发育机制的勘误，研究了卵黄蛋白原受体在青蟹和斑马鱼卵母细胞发育过程中的关键作用，及其对环境热适应进化的影响。","scd":{"b":2.0,"i":1.0,"r":1.0,"d":2.0,"t":1.0},"kp":[]},{"i":39824,"as":"","scd":null,"kp":[]},{"i":39825,"as":"关于合成生物学与基因调控技术的勘误，介绍了一种利用蛋白酶特异性响应来控制构象变化，进而精准抑制人工转录因子活性的通用工程化方法。","scd":{"b":4.0,"i":2.0,"r":1.0,"d":2.0,"t":1.0},"kp":["抑制机制[人工转录因子]: 蛋白酶响应构象抑制通用方法"]},{"i":39826,"as":"关于RNA表观遗传学研究的勘误，探讨了通过表观转录组层面的RNA编辑机制，如何动态调控Mus81酶活性，以解除生物体耐热性与减数分裂之间的生存冲突。","scd":{"b":6.5,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":["酶活性调控[Mus81 DNA修复]: 表观转录组RNA编辑"]},{"i":39827,"as":"本文为一篇作者更正声明，涉及探讨线粒体β-氧化酶HADHA通过促进β-羟基丁酸生成，进而抑制肝脏胰高血糖素反应的代谢机制研究。","scd":{"b":6.5,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":[]},{"i":39828,"as":"研究设计了一种工程化两性离子聚羧基甜菜碱（PCB）纳米递送系统，用于脑转移瘤的精准靶向治疗。PCB靶向结合血脑肿瘤屏障上的BGT1转运蛋白，实现肿瘤血管内的选择性富集。其固有的机械柔韧性可激活内皮细胞中的Piezo1离子通道，引发钙离子内流，从而在无需外部刺激的情况下实现治疗药物的快速释放。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["递送载体[脑转移瘤靶向]: 两性离子聚羧基甜菜碱(PCB)","靶向机制[脑转移瘤血管]: 选择性结合甜菜碱-γ-氨基丁酸受体并实现无外部刺激下的药物快速释放"]},{"i":39829,"as":"","scd":null,"kp":[]},{"i":39830,"as":"为解决TSC2意义不确定变异体的分类难题，研究采用大规模平行测序技术测量了近9000个变异体的丰度，并结合基因组编辑开发了mTOR通路活性测定法。结果显示，14.17%的变异体会改变TSC2丰度，17.65%的变异体会改变mTOR通路活性。该集成方法有效解决了大量意义未知的TSC2错义变异的分类问题。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["变异体测定规模[TSC2错义变异功能评估]: 近9000种","技术方法[意义不确定TSC2变体集成分辨]: 大规模平行测序测量稳态丰度"]},{"i":39831,"as":"研究开发了基于mRNA展示的缩合物分配（CPmD）技术，用于量化蛋白质组规模上驱动本质无序蛋白质缩合物形成的相互作用。该技术通过测量多肽和核酸分配到重组缩合物中的分配自由能，将实验通量提高了数个数量级。研究利用该技术揭示了大量源自无序蛋白质组的多肽的分配自由能，直接反映了蛋白质之间的相互作用。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["测定技术[蛋白质组规模凝结物相互作用]: 凝结物分配mRNA展示技术","测量指标[无序蛋白质多价相互作用]: 分配自由能"]},{"i":39832,"as":"海洋内部小规模湍流混合对调节海洋环流、 tracer分布及全球气候至关重要，其影响涵盖从亚年度到百年及千年的时空尺度。除了在百年至千年尺度上促进深海环流分支平衡外，内部湍流混合还是决定短至亚年度时间尺度海洋tracer收支的主要因素。研究强调了垂直（跨等密度面）混合与侧向（等密度面）搅动之间的相互依赖性，在建立大尺度气候系统中发挥重要作用。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":4.0,"t":5.0},"kp":[]},{"i":39833,"as":"本文为作者更正声明，涉及探讨应对欧洲Dunkelflaute（风电与太阳能发电同时不足）事件的长期电力存储需求及应对策略的相关研究。","scd":{"b":4.5,"i":3.0,"r":4.0,"d":3.0,"t":5.0},"kp":[]},{"i":39834,"as":"人为强迫加剧导致土壤水分干旱频发。土壤水分异常会通过调节能量和碳通量影响近地表空气温度。研究发现，在土壤水分干旱发生后的第二年，年度土壤水分流失引起的年度变暖效应，大于等量水分增加带来的降温效应。这种不对称的温度响应仅在包含人为温室气体强迫的影响时出现。原因在于干旱后植被受到的抑制强于水分增加后的促进，导致蒸腾作用和碳吸收减少。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":4.0,"t":5.0},"kp":[]},{"i":39835,"as":"全球地表臭氧（O3）受气候变化影响加剧，对健康和生态系统构成威胁。中国在实施严格空气政策后仍存在持续的O3污染。研究揭示了中国在实现协同清洁空气与气候行动目标数十年尺度上的O3缓解策略存在路径依赖性。中国特大城市集群中脱天气O3浓度与敏感度趋势的同步停滞（2020-2023年）证实了这种路径依赖。基于路径依赖性的理解，定量表明尽早控制O3污染是必要的。","scd":{"b":4.5,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":[]},{"i":39836,"as":"针对美国湖泊长期实施磷（P）控制后依然加剧的富营养化现象，研究结合机器学习和贝叶斯分层方法，地理追踪并分析了2012至2022年间121个湖泊的营养物质滞留变化。发现湖泊中优先滞留P的比例在2012年为70.3%，到2017年转变为85.1%的湖泊优先滞留氮（N），到2022年这一比例达到92.6%。四个关键湖泊指标表现出闪烁样动态，可用于识别水生生态系统的营养代谢失调状态。结论表明当前的富营养化特征是优先氮滞留。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["样本规模[美国湖泊营养滞留分析]: 121个湖泊","时间跨度[美国湖泊营养滞留追踪]: 2012-2022年","分析方法[湖泊营养保留变化]: 机器学习结合贝叶斯分层方法","核心发现[美国湖泊当前富营养化]: 呈现氮优先滞留特征"]},{"i":39837,"as":"","scd":null,"kp":[]},{"i":39838,"as":"","scd":null,"kp":[]},{"i":39839,"as":"","scd":null,"kp":[]},{"i":39840,"as":"研究利用包含类似自然听觉刺激统计规律的素材，探究了时间前向预测的神经机制。通过神经外科患者的颅内脑电图记录发现，预测信号主要由广泛皮质区域（包括感觉、顶叶和额叶区域）的低频活动承载。预测误差（PE）信号同时存在于低频和高频活动中，其中高频成分主要局限于感觉区域。研究结果推翻了先前的假设，揭示了预测与预测误差在皮层中的特定频率分布特征。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["实验手段[自然听觉时间前向预测机制]: 神经外科患者颅内脑电图记录"]},{"i":39841,"as":"神经母细胞瘤是儿童癌症死亡的主要原因，具有高度生物异质性。研究提出了一种用于精准肿瘤学的多模态基础模型NEVA（NEuroblastoma Vision–language AI）。与依赖冻结编码器和多实例学习的传统方法不同，NEVA采用受病理学家启发的分层工作流，并进行端到端优化。在跨越多个中心、包含1238名患者的大型多机构队列中开发和评估，NEVA在评估的11项临床任务的大多数任务中，性能超越了TITAN、UNI和Virchow等十个代表性的基础模型。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":5.0,"t":6.0},"kp":["模型架构[神经母细胞瘤视觉语言基础模型]: 模拟病理学家工作流程的分层多模态模型(NEVA)","技术特征[精准肿瘤学AI模型]: 摒弃传统冻结编码器与多实例学习，采用病理学家启发的分层工作流"]},{"i":39842,"as":"研究发现，数百万份arXiv预印本提交的元数据和源文件中包含从未打算共享的敏感信息。这些被意外包含的泄露信息包括密码、GPS坐标以及私人对话记录。这一发现揭示了学术预印本在提交和共享过程中的数据隐私与安全漏洞。","scd":{"b":3.0,"i":4.0,"r":6.0,"d":3.0,"t":7.0},"kp":["[arXiv预印本元数据与源文件泄露]: 发现密码、GPS坐标和私人对话等非共享信息"]},{"i":39843,"as":"现有使用血浆游离RNA（cfRNA）的多癌症液体活检方法通常依赖基因注释，容易忽略未注释或重复基因组区域的信号。研究提出了一种基于Transformer的模型GeneLLM，该模型直接处理比对到人类基因组的cfRNA读取的核苷酸序列，以识别癌症指示特征。通过绕过基因水平的定量，该模型保留了来自转录组“暗物质”的信号。GeneLLM学习潜在的伪生物标志物，将其作为癌症分类的判别特征。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["模型架构[癌症循环转录组特征解码]: 基于Transformer直接处理cfRNA核苷酸序列的GeneLLM模型","[基因水平定量]: 被模型绕过以保留来自未注释或重复基因组区域的信号"]},{"i":39844,"as":"","scd":null,"kp":[]},{"i":39845,"as":"单原子催化剂（SACs）的活性位点构型对催化性能至关重要，但其在层状Fe-N-C中氧还原反应（ORR）的理论预测与实验活性间存在长期差异。在X射线吸收精细结构（XAFS）观察以及模拟和机器学习的指导下，研究确认了堆叠的双层金属-金属耦合（MMC）构型是这些催化剂中重要的活性位点基元。这一发现解析了催化剂的构效关系，为SACs的合理设计和可预测性提供了新见解。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["原子经济率[催化剂性能]: 接近100%","活性位点构型[催化性能决定因素]: 层间金属-金属耦合","材料类型[理论预测与实验性能存在差异]: 层状Fe-N-C","应用场景[催化反应类型]: 氧还原反应(ORR)"]},{"i":39846,"as":"在硼催化的丙烷氧化脱氢（ODHP）反应中，关于真正活性位点的鉴定一直存在争议。传统的静态高能BOx模型无法解释非还原性B(III)中心如何介导高效的C-H键活化并保持极高的丙烯选择性。结合对9700种构型的热力学筛选和增强采样第一性原理分子动力学（AIMD），研究证明催化活性并非源于预先存在的结构，而是通过[BO3]与[BO4]持续相互转化产生的瞬时可及的过配位[BO4]介导的。这种动态的sp2到sp3杂化转变是实现C-H键活化的关键。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["筛选体系规模[硼基丙烷氧化脱氢热力学]: 9700种","[瞬时过度配位状态]: 解锁了不可还原的B(III)中心介导高效C-H活化与维持高丙烯选择性之间的悖论"]},{"i":39847,"as":"多肽中丝氨酸和苏氨酸残基的位点特异性化学修饰具有挑战性，主要因其羟基亲核性弱且存在多个难以区分的位点。研究报道，氨氧基丝氨酸或氨氧基苏氨酸可通过瞬态的1,2,4-噁二嗪烷中间体在水溶液中介导有效的氨氧基连接（AOL），从而实现N端位置的化学选择性肽连接。此外，AOL后嵌入的氨氧基官能团随后与酮酸发生化学选择性酯连接（CEL），将氨氧基恢复为天然丝氨酸。该策略实现了未受保护多肽中羟基位点的可编程编辑。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":5.0,"t":6.0},"kp":["编辑方法[未受保护多肽中的丝氨酸和苏氨酸]: 氨基氧基丝氨酸或氨基氧基苏氨酸介导的氨基氧连接(AOL)"]},{"i":39848,"as":"镧系氮化物十分罕见。研究将一种新的大环己基三酰胺配体[TachDMBS]引入镧系化学，成功分离出具有线性CeNCe核心结构的氮化二铈(IV)络合物，且该结构未与任何碱金属发生相互作用。该络合物通过双核“tuck-in-tuck-over”铈(IV)金属环与NaNH2在苯中（含12-冠-4）反应制备，产率为48%。其Ce-N（氮化物）键长（2.051(19) Å）接近目前报道的最短Ce-N键，且Ce-N-Ce键角为180.00度，呈现完美的线性结构。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":6.0,"t":6.0},"kp":["络合物核心结构[二铈(IV)氮化物]: 不受碱金属相互作用的线性CeNCe核心","稳定配体[二铈(IV)氮化物]: 环己基三酰胺配体[TachDMBS]"]},{"i":39849,"as":"利用深度学习的现代蛋白质设计方法，研究开发出一种含有钴卟啉IX（CoPPIX）辅因子的超稳定从头合成CO2还原酶。这种含CoPPIX的酶在体内通过在培养基中补充钴盐组装而成，并表现出光催化CO2还原活性。研究确定了两种半胱氨酸连接的设计，它们具有高催化活性（转换数>1000，速率高达25 min-1），同时能有效抑制竞争性析氢副反应。2.1 Å的晶体结构显示其与设计模型高度一致，证明了计算蛋白质设计在开发定制催化酶方面的强大能力。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["辅因子[从头设计CO2还原酶]: 半胱氨酸连接的钴卟啉IX(CoPPIX)","组装方式[含CoPPIX的酶]: 通过在培养基中补充钴盐进行体内组装"]},{"i":39850,"as":"研究提出了一种数据驱动的策略，使低成本的硝酸锂能够作为锂离子电池电解液的主要盐类。这种新型设计的低浓度电解液有效降低了电池制造成本，同时能够稳定电池的内部界面。该电解液配方成功使软包电池具备了在全天候条件下稳定运行的能力。","scd":{"b":7.0,"i":6.0,"r":6.0,"d":6.0,"t":6.0},"kp":["电解质主盐[成分]: 硝酸锂","电解液浓度[状态]: 稀/低浓度","电池界面[性能表现]: 稳定","电池运行环境[温度条件]: 全气候","电解液成本[经济性特征]: 低成本"]},{"i":39851,"as":"针对锡铅（Sn-Pb）钙钛矿太阳能电池，研究提出了一种采用氧化石墨烯和自组装单分子层的双层策略。该策略成功构建了高效且稳定的三结全钙钛矿太阳能电池。所制备的器件实现了27.3%的光电转换效率，并在运行稳定性方面表现出色，其T90寿命达到770小时。","scd":{"b":7.5,"i":5.0,"r":6.0,"d":9.0,"t":6.0},"kp":["转换效率[三结全钙钛矿太阳能电池]: 27.3%","T90寿命[三结全钙钛矿太阳能电池]: 770小时","接触层策略[锡铅钙钛矿电池]: 采用氧化石墨烯和自组装单分子的双层结构"]},{"i":39852,"as":"研究探讨了利用芳香分子控制钙钛矿量子点的成熟过程，旨在提升量子点在高效太阳能电池中的光电性能与稳定性。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["成熟过程调控[钙钛矿量子点]: 利用芳香分子控制"]},{"i":39853,"as":"研究利用锍配体调节钙钛矿的结晶界面动力学，有效减少了非辐射跃迁，成功制备出外量子效率达27%的高效近红外钙钛矿发光二极管。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["外量子效率[近红外钙钛矿发光二极管]: 27%","结晶界面动力学调控[钙钛矿]: 利用锍配体调节"]},{"i":39854,"as":"研究通过对比分析溶液加工法与真空蒸镀法制备的卤化铅钙钛矿薄膜的缺陷情况，探讨不同制备工艺对材料光电性能的影响。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["缺陷情况对比[卤化铅钙钛矿薄膜]: 溶液加工法 vs 真空蒸镀法"]},{"i":39855,"as":"研究从发展中国家性别不平等的视角，探讨权力分配与平等问题对能源贫困状况的影响，揭示了社会经济层面的能源获取差异。","scd":null,"kp":[]},{"i":39856,"as":"研究以俄乌冲突作为准自然实验，评估了地缘政治冲突这一外部冲击对企业推进能源转型进程的具体影响与作用机制。","scd":{"b":2.0,"i":2.0,"r":5.0,"d":3.0,"t":3.0},"kp":[]},{"i":39857,"as":"研究提出一种基于知识替代引导的深度学习方法，旨在解决实时事件驱动的电力系统应急控制问题，推动构建可信赖的人工智能应用。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["人工智能控制方法[实时事件驱动电力系统应急控制]: 知识替代引导的深度学习方法"]},{"i":39858,"as":"探讨恒温控制负载的自适应建模技术，重点研究如何实现模型阶数的最佳选择以优化控制效果。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["模型阶数选择[恒温控制负载自适应建模]: 具有最佳阶数选择"]},{"i":39859,"as":"研究含产消者的配电网络能源交易，提出一种解决非凸P2P交易问题的两阶段分布式优化方法。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["交易优化机制[含产消者配电网络非凸P2P能源交易]: 两阶段分布式优化方法"]},{"i":39860,"as":"聚焦中期电力负荷预测，构建混合频率框架，结合宏观经济趋势与微观动态以提升预测稳健性。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["负荷预测框架[中期电力负荷]: 结合宏观经济趋势与微观动态的稳健混合频率框架"]},{"i":39861,"as":"分析中国基础研究领域的最新政策、战略部署及相关支持举措，探讨未来科研发展方向。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":3.0,"t":6.0},"kp":[]},{"i":39862,"as":"以往通常将住宅太阳能的采用视为个人层面的决策，而忽略了家庭内部关系的复杂性。通过对39对夫妇的访谈数据，研究识别出两类家庭角色：“同步型”（具有共同目标和劳动分工，常见于采用者家庭）和“对立型”（存在分歧，常见于未采用者家庭）。然而，同步型家庭往往需要外部催化剂（如税收抵免到期、账单增加）才会最终采取行动。通过对394名当前和已流失采用者的调查发现，家庭成员（如伴侣和父母）在其中扮演着关键角色。","scd":{"b":2.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["家庭决策模式[住宅光伏采用者]: 同步状态（具有共同目标和劳动分工）","家庭决策模式[住宅光伏非采用者]: 对立状态（存在分歧）"]},{"i":39863,"as":"研究表明，包含整个家庭在内的协调与积极商议有助于促进太阳能的采用。因此，针对能源采用的政策干预措施如果能设计为支持家庭集体决策，而不是仅针对单一家庭成员，其效果将更为显著。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[家庭太阳能采用]: 旨在支持家庭集体决策的干预措施比针对单一成员更有效"]},{"i":39864,"as":"涉及海洋生态学，研究如何利用热力状况与生态网络连接性来促进珊瑚礁海景的进化与适应。","scd":null,"kp":[]},{"i":39865,"as":"真空沉积为钙钛矿太阳能电池提供了一种与工业兼容的制造途径，但控制钙钛矿的结晶过程仍面临挑战。研究在钙钛矿吸光层下方引入了结构导向层，并利用原位光致发光（PL）技术实时监测钙钛矿的成核、应变和缺陷情况。这种对晶体生长过程的精确控制，最终成功制备出具有更高效率和改善稳定性的钙钛矿太阳能电池器件。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":7.0,"t":7.0},"kp":["结构导向层[钙钛矿吸收层下方]: 引入以控制钙钛矿结晶","[真空沉积钙钛矿]: 结合原位光致发光监测成核、应变和缺陷，提升器件效率与稳定性"]},{"i":39866,"as":"为应对人工智能数据中心扩张引发的温室气体排放、电网压力和水资源消耗问题，该研究提出了多项缓解策略。硬件设计上，使用回收或老旧组件可减少隐含排放，使数据中心整体排放降低10-20%。电网集成型AI数据中心通过将工作负载与电网运行条件匹配，最多可减少约10%的碳排放。数据中心的用水量同样受到关注。","scd":{"b":4.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["减排潜力[数据中心硬件设计]: 使用回收或旧组件可降低10-20%的整体（隐含）排放"]},{"i":39867,"as":"该研究开发了一种名为SOLIDs的溶酶体自分选纳米降解剂，用于清除血液中循环的致病性血清介质。SOLIDs具有刚性半导体聚合物核心，能实现近定量的溶酶体积累。通过表面生物偶联和可控蛋白质晕形成，可从血液中捕获特定免疫介质，并在肝脏中进行生物降解。实验表明，捕获IL-6的SOLIDs能有效降低血清中的IL-6水平。","scd":{"b":8.5,"i":3.0,"r":8.0,"d":7.0,"t":7.0},"kp":["核心成分[纳米降解剂]: 刚性半导体聚合物核心","溶酶体蓄积[SOLIDs纳米降解剂]: 近乎定量的溶酶体蓄积"]},{"i":39868,"as":"研究探讨了空位填充赫斯勒合金中的原子有序性，以解决多成分导致的位置无序问题。实验在Slater-Pauling半导体MRu1.5Sb (M = Ti, Zr, Hf)中观察到原子占位有序现象：Ru原子在过多的晶体学位置上呈调制分布，选择性占据4c和4d Wyckoff位置。这种选择性占据不仅破坏了局部对称性，还引发了特定现象。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[空位填充赫斯勒合金]: 实验观察到Slater-Pauling半导体合金中的紧急原子有序性"]},{"i":39869,"as":"为解决层状热电材料PbSnS2面外电子传输受阻的问题，该研究提出了SnSe合金化策略。SnSe的掺入提高了载流子浓度，并通过改善晶格对称性和优化电子能带，显著提升了面外电荷迁移率。同时，合金化引发的点缺陷加剧了声子散射，实现了电子和声子传输的有效解耦。该策略协同优化了n型PbSnS2的面外热电性能。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[n型PbSnS2晶体]: 通过SnSe合金化协同提升面外热电性能及载流子输运能力"]},{"i":39870,"as":"该研究开发了一种呋喃/丙烯酰胺机械载药分子，能够在较低作用力（FCOGEF = 3.0 nN）下被完全且选择性地激活，并在标准超声波浴中即可实现完全激活，无需特殊设备。该技术突破了传统机械载药分子激活力过高的限制，在需要高效率和选择性的控制释放应用中具有潜力。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[机械力响应基团]: 利用弱键实现完全激活和高效货物释放"]},{"i":39871,"as":"关于一项利用特定有机框架进行线粒体靶向声动力疗法及抗肿瘤免疫的纳米医学研究的撤稿声明。","scd":{"b":2.0,"i":1.0,"r":3.0,"d":3.0,"t":4.0},"kp":[]},{"i":39872,"as":"科学家已成功查明导致超过一百万只海洋动物死亡的“罪魁祸首”，确认为一种特定的藻类。研究表明，该有毒藻类的异常增殖对海洋生态系统造成了毁灭性打击，引发了大规模的海洋生物死亡灾难。这一重大发现为预防和控制此类海洋生态危机提供了关键的线索，对于未来保护海洋生物多样性、深入研究有毒藻华的成因及其环境干预机制具有重要的科学意义。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":3.0,"t":5.0},"kp":[]},{"i":39873,"as":"为解决工业水系统中的二氧化硅结垢问题，研究引入了模块化大分子设计平台，结合可控自由基聚合与聚合后修饰，制备出链长、功能和构象可独立调节的聚合物二氧化硅抑制剂。通过计算与实验结合，研究确立了控制抑制性能的关键结构-性质关系，并指出了传统抑制剂存在的关键局限。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[聚合物阻垢剂]: 采用模块化合成平台结合可控自由基聚合与聚合后修饰以抑制二氧化硅聚合"]},{"i":39874,"as":"该研究将粉煤灰和矿渣等工业固体废物转化为一种高强度、具有离子导电性的地质聚合物电解质，用于锌离子砖电池。通过设计连通的孔隙结构来高效引导离子，该材料将机械耐久性与长期的电化学性能相结合，为开发兼具承重和储能功能的建筑组件指明了方向。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["电解质材料[结构储能锌离子砖电池]: 离子导电地质聚合物","原料[地质聚合物电解质]: 工业固体废物(粉煤灰和矿渣)","结构特征[地质聚合物电解质]: 具有引导离子高效传输的连通孔隙"]},{"i":39875,"as":"该研究提出了一种在水相中检测N-亚硝基二甲胺（NDMA）的荧光检测新策略。通过光化学转化NDMA，使其与生物素化聚合物试剂反应，生成带有生物素标签的荧光产物。随后利用链霉亲和素-生物素相互作用对该产物进行选择性富集，有效分离分析信号与背景干扰。该检测方法全水相进行，免除了样品预处理，并在优化条件下实现准确定量。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[NDMA荧光检测]: 使用光化学转化和亲和捕获替代基于色谱柱的分离"]},{"i":39876,"as":"胶原蛋白的稳定性来源于富含脯氨酸和4-羟基脯氨酸的重复序列。研究表明，苏氨酸磷酸化可作为4-羟基脯氨酸的生物可逆替代物。利用合成胶原多肽进行替换实验发现，在中心Pro-Hyp-Gly三联体的Yaa位置引入磷酸化苏氨酸能够保持与Hyp相当的三螺旋稳定性。此外，三螺旋内的磷酸化苏氨酸是特定酶的底物。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[胶原三螺旋]: 苏氨酸磷酸化是脯氨酸羟基化的生物可逆替代物"]},{"i":39877,"as":"利用石墨烯原子级光滑表面实现超润滑的质量传输是一个重大挑战。该研究展示了一种铁电极化辅助策略，成功制造出厚度仅为3.5纳米的石墨烯表皮膜，用于超快速和选择性分离。该无缺陷石墨烯膜成功实现了近无摩擦的分子流动，从而在超快速渗透分离应用中取得突破。","scd":{"b":8.5,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[石墨烯膜超快速分离]: 铁电诱导分子滑动实现近无摩擦流动","石墨烯膜厚度[几纳米]: 几纳米"]},{"i":39878,"as":"电化学NO还原合成绿氨的过程中，铁表现出了优异的活性和选择性。通过机器学习势函数驱动的计算模拟，研究发现铁的高电化学性能并非源于其本征活性，而是由于在反应条件下发生“自单原子化”。反应中铁表面主要被吸附的N*物种覆盖，从而形成FeNx结构。统计分析证实了该结构转变机制。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[电化学NO还原合成氨]: Fe表现出高活性和选择性源于原位自适应的自单原子化能力，而非本征活性","[驱动模拟方法]: 机器学习势驱动的巨正则蒙特卡罗(GCMC)模拟"]},{"i":39879,"as":"在NaCl辅助化学气相沉积生长WS2的过程中，界面上残留的盐分是限制其环境稳定性的关键瓶颈。研究表明，暴露在空气中时，含Na和W的无定形残留物会结晶并机械破坏WS2层，同时形成富Na吸湿环境，导致W-S键氧化断裂。这是一种表观活化能约为0.22 eV的热激活降解过程。生长后退火（PGA）处理可以消除这些残留物。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[NaCl辅助CVD生长WS2降解机制]: 暴露空气时，含Na和W的无定形残留物结晶并机械破坏WS2层，同时吸水促进降解","[界面残留物]: 含Na和W的无定形残留物"]},{"i":39880,"as":"","scd":null,"kp":[]},{"i":39881,"as":"该研究开发了一种基于氨基磷酸酯的共价适应性网络（CANs），打破了热固性材料在可持续性和防火安全之间的传统权衡。该设计将环氧固化、本征阻燃和动态键交换集成于单一分子中。通过P-O键上的高效反式氨基磷酸酯交换，材料可多次重新加工且性能不损失，其动态网络重排速度也快于其他磷酸化网络。此外，该材料具备本征防火特性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["固化剂设计[反式氨基磷酸酯衍生]: 在单一分子设计中集成环氧固化、内在阻燃性和动态键交换","[环氧共价适应性网络]: 可多次再加工且打破可持续性与防火安全性之间的传统权衡"]},{"i":39882,"as":"该研究开发了一种基于非对称CuO-Cu2O纳米线薄膜的视觉-味觉多模态神经形态感觉器件。该器件将固态光电电子学与液相离子学本征耦合，纳米线网络表现出显著的光伏效应和固液界面电荷重排，实现在水相中的无偏压运行。与化学响应相关的离子吸附形成双电层，动态调控器件状态，从而模拟生物系统中的跨模态联想行为。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[多模态神经形态感觉设备]: 基于不对称CuO-Cu2O纳米线薄膜实现固态光电子学与液相离子学的内在耦合，模拟视觉-味觉跨模态联想"]},{"i":39883,"as":"该研究提出了一种电子给受体（EDA）络合物辅助策略，在无添加剂的酶兼容水相条件下成功构建β-酮烯胺共价有机框架（COFs），并同步实现酶的原位封装。富电子单体与缺电子单体形成的EDA络合物预排列了单体取向并降低了反应活化能，从而生成高结晶度的COFs。框架中的特定单元不仅提供保护支架，还可作为螯合各种金属离子的锚定位点，用于级联生物传感。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[酶兼容介质中晶体COF组装策略]: 电子供体-受体(EDA)络合物辅助的无添加剂水相环境构建，并实现酶的原位封装","COF类型[β-酮烯胺连接]: Bpy与Tp单体预排列形成"]},{"i":39884,"as":"该研究构建了两种由氟桥七核钴簇和吡啶基配体组成的金属有机框架（LIFM-712和LIFM-713）。受限的BF4-反荷阴离子与桥联氟配体协同，形成了富氟孔隙环境，提供了大量识别位点。LIFM-712对乙炔结合力强，而LIFM-713在298K和1bar下实现了149.8 cm³/g的乙炔吸附量。理论计算表明，LIFM-713对C2H2/CO2的选择性高达4.5。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[C2H2/CO2高选择性分离]: 氟桥连七核[Co7F12]2+簇与三齿吡啶配体构建富含氟的孔隙环境，提供丰富的C-H···F识别位点"]},{"i":39885,"as":"为控制电化学还原CO2的反应路径，研究提出了一种界面工程策略，通过调节Cu2O催化剂上二氧化硅外壳的厚度来改变产物选择性。具有薄二氧化硅层的催化剂在预还原后形成Cu/Cu2O/SiO2三相界面，有利于不对称中间体的形成，从而促进C-C偶联生成C2+产物。而厚二氧化硅层则能够引导反应向深度氢化生成甲烷的方向进行。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[调控CO2电还原路径]: 调节Cu2O催化剂表面二氧化硅壳层厚度以控制界面重构，实现C2+产物或CH4之间的选择性切换"]},{"i":39886,"as":"该研究设计了一种通过旋涂制备的不对称高盐复合聚合物电解质，用于高性能固态锂金属电池。该电解质采用贯穿膜的聚偏氟乙烯（PVDF）骨架，并在正极侧构建富含环丁砜的聚环氧乙烷（PEO）/双三氟甲磺酰亚胺锂（LiTFSI）层，形成高介电微环境。该设计将离子聚集体转化为与醚氧配位的游离锂离子，有效克服了室温离子电导率低、锂离子迁移数有限和界面机械不兼容等挑战。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[复合聚合物电解质设计]: 旋涂法制备不对称富盐聚合物电解质，解决室温离子电导率低、锂离子迁移数有限及界面机械不相容问题"]},{"i":39887,"as":"针对耐药细菌引起的骨缺损治疗难题，研究人员开发了名为SPMiL的磺化PEEK支架。该支架携带LL37抗菌肽和富含线粒体的细胞外囊泡（EV-Mito）。通过敲除线粒体动态调节关键基因Opa1，使外胚层间充质干细胞的囊泡产量大幅增加。在感染耐甲氧西林金黄色葡萄球菌（MRSA）的大鼠颅骨缺损模型测试中，SPMiL支架成功释放有效载荷以对抗耐药骨感染并促进骨修复。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["支架材料[耐药骨感染治疗]: 磺化PEEK支架(SPMiL)共载抗菌肽LL37与富含线粒体的细胞外囊泡(EV-Mito)","[EV-Mito囊泡来源]: Opa1敲除的颅神经嵴间充质干细胞"]},{"i":39888,"as":"为提高微生物电化学系统对四环素（TC）的去除率，研究人员设计了Co3O4@PEDOT-CC阳极。该阳极通过在碳布上生长包覆聚(3,4-乙撑二氧噻吩)（PEDOT）的Co3O4纳米线制成，具备优异的导电性、生物相容性和分层结构。其电荷转移电阻仅为6.5欧姆，比裸碳布低27.3倍，并实现了3.33 W/m2的最大功率密度，显著优于以往报道的钴基纳米材料。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["去除目标[微生物电化学系统]: 四环素(TC)","阳极材料[电池体系]: Co3O4@PEDOT-CC","材料结构[阳极]: 聚(3,4-乙烯二氧噻吩)(PEDOT)包覆生长在碳布上的Co3O4纳米线","材料特征[阳极]: 具有分层结构和优异导电及界面性质"]},{"i":39889,"as":"苯并氧硼杂环具有独特的反应性和蛋白识别能力。研究人员合成了一系列带有双吖丙啶/炔烃标签的苯并氧硼杂环，通过细胞内光亲和标记实验，发现部分分子对真核翻译起始因子4E（eIF4E）具有高选择性。该结合过程具有立体选择性，且与mRNA的7-甲基鸟苷帽呈竞争关系。标签位点实验表明，该片段结合在eIF4E的帽结合口袋处，计算模型证实了氢键相互作用的存在。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["靶标蛋白[苯并氧硼杂环]: 真核翻译起始因子4E (eIF4E)","靶向选择性[药物分子库]: 对eIF4E具有高选择性","化学合成[功能探针]: 含有重氮丙烷/炔烃标签以实现细胞内光亲和标记"]},{"i":39890,"as":"为解决传统氧化钒（VOx）柔性红外探测器电阻温度系数（TCR）低、制造成本高等瓶颈，研究人员利用VO2(B)纳米片墨水，通过可扩展的滴注法制备了柔性红外热探测器。该材料在室温下的TCR高达4.57% K-1，器件的响应度为9.84 A/W，室温下的比探测率达到3.27×108 Jones。这种低成本柔性传感器成功实现了从单器件传感到阵列成像的应用。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["材料体系[非制冷红外微测辐射热计]: 氧化钒(VOx)","技术瓶颈[VOx器件]: 本征电阻温度系数(TCR)值低、器件非柔性且制造成本高","核心材料[柔性红外热探测器]: VO2(B)纳米墨水"]},{"i":39891,"as":"为解决赖氨酸乙酰转移酶（KATs）同源选择性的难题，研究人员将基于CRBN的分子胶扩展到了经典降解决定子之外，开发出高选择性的KAT2A降解剂。冷冻电镜技术证实，CRBN以独立于降解决定子的方式招募KAT2A，通过结合表面暴露的酪氨酸模拟抗体识别。这种选择性降解能有效消除组蛋白H3第9位赖氨酸的乙酰化，并在急性髓系白血病细胞中表现出抗增殖作用。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["降解靶标[CRBN分子胶]: 赖氨酸乙酰转移酶2A (KAT2A)","靶向机制[分子胶]: 独立于降解决定子的招募(非经典降解决定子空间)","结构解析技术[CRBN-KAT2A相互作用]: 冷冻电子显微镜"]},{"i":39892,"as":"研究人员提出一种非平衡瞬时组装策略，用于超快合成具有复杂结构的纳米催化剂。以核壳结构的铂皮金属间化合物（Pt@PtFe-i）为例，利用周期性热脉冲驱动高能瞬态PtFe构型演化，实现了高阶PtFe金属间核心与原子层精度铂表层的同步组装。Pt@PtFe-i催化剂的铂表层具有依赖于配位的压缩应变，从而产生了高密度的催化活性位点，大幅提升了燃料电池的催化效率。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["催化剂合成策略[非平衡态]: 瞬时组装策略","纳米催化剂结构[核心-壳层]: 核壳结构铂皮金属间化合物(以Pt@PtFe-i为例)","合成驱动力[超快合成]: 周期性热脉冲协议"]},{"i":39893,"as":"传统主族元素多重键模型基于独立的σ和π轨道，但在重元素分子中，自旋-轨道耦合引起的相对论效应会混合这些轨道。研究人员利用高分辨率低温光电子能谱和四分量相对论Dirac-Coulomb耦合簇计算，探测了CBi−阴离子中的碳-铋三键。该研究首次提供了实验证据，直接证实了相对论效应引发的σ-π键合框架塌陷，使得总角动量投影成为唯一的有效量子数。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":6.0,"t":5.0},"kp":["化学键探针[CBi−分子离子]: 碳-铋三键","成键效应[重元素分子]: 相对论效应通过自旋-轨道耦合混合σ和π轨道，导致经典三键框架相对论塌陷"]},{"i":39894,"as":"针对当前人工智能技术的发展，批评人士指出，如果这项技术将人类用户转变为“半人马”的反向形态（即人类被迫为人工智能进行低级辅助工作或被其控制），公众将对其失去热情与支持。文章引发了对AI时代人机协作关系的反思。","scd":{"b":0.0,"i":0.0,"r":4.0,"d":1.0,"t":4.0},"kp":[]},{"i":39895,"as":"","scd":null,"kp":[]},{"i":39896,"as":"研究发现，仅数分钟的冷冻过程即可决定铁矿物的长期转化归宿。单次冻融循环通过物理和化学机制不可逆地聚集水铁矿。冰冻浓缩作用会破坏静电势垒，冷吸作用剥离水合层，将纳米颗粒压缩成微米级平面聚集体。界面羟桥配位和氢键作用阻止了聚集体解体，使其锁定在介晶状组合中，从而抑制了其向针铁矿的溶解-再沉淀过程。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["相变驱动力[铁矿物转化]: 单一冷冻-融化循环","转化效应[水合老化]: 数分钟的冷冻决定了随后数月水相老化过程中的铁矿物归宿","微观聚集机制[六方水铁矿]: 冷冻浓缩破坏静电屏障，冷吸剥离水合层并使纳米颗粒压缩成微米级平面聚集体(不可逆聚集)"]},{"i":39897,"as":"针对依靠翅膀推进的潜水鸟类如何实现空中与水中跨界运动，研究人员通过对比潜水鸟类数据与能飞行、游泳和跃水的扑翼机器人实验发现：扑动频率的适应性调整、柔性机翼以及强力驱动使其无需折叠翅膀即可实现两种介质间的无缝过渡。此外，较大的翅膀能增强飞行能力且不显著降低水下效率，而尾身距离和出水角度是影响成功跃出水面的关键因素。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["研究对象[跨介质运动]: 扑翼潜水鸟类","关键技术参数[扑翼机器人]: 扑动频率、翅膀尺寸、刚度","实验模型[两栖过渡运动]: 能够飞行、游泳、俯冲潜水并跃出水面的扑翼机器人"]},{"i":39898,"as":"","scd":null,"kp":[]},{"i":39899,"as":"","scd":null,"kp":[]},{"i":39900,"as":"","scd":null,"kp":[]},{"i":39901,"as":"相干特性是量子系统研究的核心。研究人员在二维光学晶格中，利用高阶塔博尔复苏的直接物质波成像技术，观察了超冷玻色气体热相变过程。同时，他们开发了一种基于相位波成像技术的“相位显微镜”，通过位点分辨技术将相位涨落映射为密度涨落。该研究成功观测到了超流相中相位关联的代数衰减规律及指数随温度的线性增加，为强相关量子系统的相干特性研究提供了空间全分辨技术。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":8.0},"kp":["研究系统[热相变]: 二维光学晶格中的超冷玻色气体","观测方法[相位涨落]: 基于在更高Talbot复苏期间将相位涨降映射到密度涨落的位点分辨映射技术的相显微镜","测量手段[相位相干性]: 高阶Talbot复苏的直接物质波成像"]},{"i":39902,"as":"为支持《全球塑料条约》的制定与实施，相关报告指出，未来的数据汇报工作必须重点考虑全球数据标准的协调统一、塑料供应链指标的建立以及污染热点区域的精确识别，以弥合当前存在的关键数据缺口。","scd":{"b":1.0,"i":1.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[全球塑料条约报告机制]: 需考虑数据协调、供应链指标和污染热点识别"]},{"i":39903,"as":"","scd":null,"kp":[]},{"i":39904,"as":"","scd":null,"kp":[]},{"i":39905,"as":"","scd":null,"kp":[]},{"i":39906,"as":"","scd":null,"kp":[]},{"i":39907,"as":"","scd":null,"kp":[]},{"i":39908,"as":"评估美国军事扩张及深海采矿活动对关岛周边海洋生态环境带来的潜在风险与负面影响。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[深海采矿环境影响]: 对海洋生态环境造成潜在风险与负面影响"]},{"i":39909,"as":"","scd":null,"kp":[]},{"i":39910,"as":"冰冻过程能够作为一种地球化学反应器，彻底改变地球冰冻圈环境中铁元素的化学形态、物理聚集状态及其在自然环境中的最终转化归宿。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[地球冰冻圈铁化学反应]: 冰冻过程改变铁的归宿"]},{"i":39911,"as":"","scd":null,"kp":[]},{"i":39912,"as":"","scd":null,"kp":[]},{"i":39913,"as":"","scd":null,"kp":[]},{"i":39914,"as":"","scd":null,"kp":[]},{"i":39915,"as":"","scd":null,"kp":[]},{"i":39916,"as":"研究发现，拟南芥中单链断裂（SSB）修复缺陷是触发全基因组转座元件（TE）去抑制和DNA从头甲基化的强烈因素。ZDP/APE2基因的突变会阻碍3'端受阻SSB的修复，导致广泛的TE激活。同时，无效的SSB修复会激活ATR-SOG1介导的DNA损伤反应，进而增强RNA指导的DNA甲基化途径，以维持植物基因组和表观基因组的完整性。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[拟南芥DNA单链断裂修复缺陷]: 引发全基因组转座元件去抑制和广泛的DNA从头甲基化"]},{"i":39917,"as":"研究通过结合理论、模拟和实验，证明了溶致液晶（如日落黄水色素混合物）在分子间无微观吸引力的情况下也能发生自发相分离。在最小模型中，相分离仅依赖于局部向列分子密度与取向顺序之间的类昂萨格耦合。当耦合足够强时，向列缺陷会触发各向同性液滴的成核，这些液滴在弹性或界面张力作用下合并，从而实现大规模的图案形成和自组装。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[溶致向列混合物(日落黄-水)相分离]: 依赖于类昂萨格机制，无需微观吸引力即可自发相分离"]},{"i":39918,"as":"在具有切向锚定的向列液晶（NLC）环形液滴中，外部磁场可诱导形成稳定的Helfrich壁（排列反转壁）。在环形受限几何形状与外部磁场的相互作用下，Helfrich壁能自然形成、转化和迁移。零场状态下的向列配置中点缺陷的存在和数量决定了壁的类型：无点缺陷时出现弯曲-弯曲壁；存在成对点缺陷时则形成其他类型的壁。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[磁场下的向列环形液滴]: 形成稳定的磁场诱导取向反转壁(Helfrich壁)"]},{"i":39919,"as":"电突触间隙连接通道的分子组成多样性决定了其生理特性。在秀丽隐杆线虫的机械感觉回路中发现，单个电突触可由INX-1、UNC-7和UNC-9三种不同的内联蛋白组成的异质通道聚集形成。这种被称为“异通道突触”的组合配置赋予了突触连接高度的选择性，使其能够与特定突触伙伴建立连接，并由不同的细胞机制维持。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["间隙连接通道分子组成[电突触]: 决定其生理特性","组合内联蛋白代码[细胞机制控制]: 选择性突触连接建立"]},{"i":39920,"as":"化脓性链球菌分泌的细胞包膜蛋白酶SpyCEP通过裂解CXCL8等趋化因子来逃避人类中性粒细胞免疫。结构研究表明，SpyCEP内部被切割的成熟环（CAML）中含有一个无序的芳香族和酸性区域。该区域模拟受体N端结构并结合到CXCL8的变构位点，形成动态模糊复合物，促使CXCL8二聚体解离，从而增强SpyCEP对趋化因子底物的切割和灭活能力。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["SpyCEP靶向作用[中性粒细胞吸引趋化因子]: 裂解并灭活CXCL8"]},{"i":39921,"as":"针对实验草地中共存、生产力与稳定性之间机制联系的研究文章进行勘误更正。","scd":{"b":1.0,"i":1.0,"r":1.0,"d":1.0,"t":2.0},"kp":[]},{"i":39922,"as":"皮肤过敏原致敏（CAS）是引发特应性皮炎并导致全身性过敏反应（如食物过敏和过敏性休克）的关键。在连接皮肤炎症与全身过敏性休克的小鼠模型中研究发现，白介素-13（IL-13）调控高亲和力IgE抗体的产生。通过细胞特异性敲除实验证实，2型常规树突状细胞（cDC2）是IL-13作用的关键靶点，而非T细胞或B细胞，cDC2中的IL-13信号传导对于驱动全身过敏反应至关重要。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["IL-13信号传导[2型常规树突状细胞cDC2]: 全身过敏反应和高亲和力IgE抗体生成的必需调节因子"]},{"i":39923,"as":"植物根系能够通过一种名为“腐生性（saprotropism）”的未知生长反应来避开腐烂区域。真菌驱动的微生物分解释放有机酸并在土壤中形成稳定的局部pH梯度，根系表皮细胞通过根分生组织生长因子肽-受体模块感知这种外部酸性不对称。随后，外部pH信号被转化为不对称的脱落酸（ABA）分布，ABA的不对称进一步驱动微管重组，引导根系在复杂土壤中精确导航。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[植物根系趋腐性]: 真菌驱动的微生物分解释放有机酸形成稳定pH梯度，引导根系主动避开腐烂区域"]},{"i":39924,"as":"经典补体级联反应启动因子C1q在成人大脑中介导了活动依赖性的突触消除。活体化学遗传学证实，神经元过度活跃会诱导成年海马体中特定区域发生依赖C1q的突触丢失。在阿尔茨海默病小鼠模型中，抑制神经元过度活跃可减少淀粉样蛋白β并减少C1q沉积。结合空间转录组等技术，发现分泌抗体的B谱系细胞与成人大脑中生理条件下依赖C1q的突触消除过程密切相关。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["C1q介导机制[成人大脑海马区神经元过度活跃]: 诱导区域特异性活动依赖性突触损失"]},{"i":39925,"as":"非洲入侵性城市疟疾媒介（斯氏按蚊）威胁着非洲1.26亿城市居民。对非洲、中东和亚洲645个全基因组的分析表明，南亚的初次入侵在吉布提建立了桥接群体，随后扩散至苏丹、埃塞俄比亚/肯尼亚和也门。其传播速率和路线受地形地貌影响。该蚊类的杀虫剂抗性主要由代谢解毒基因介导，并伴随特定的抗性单倍型和基因拷贝数变异。","scd":{"b":5.0,"i":3.0,"r":8.0,"d":8.0,"t":6.0},"kp":["基因组测序分析范围[非洲入侵城市疟疾蚊子]: 645个全基因组样本"]},{"i":39926,"as":"社会动物需要不断更新社会记忆的价态以适应关系变化。当原本中性的同类变得具有攻击性时，海马体腹侧CA1（vCA1）-基底外侧杏仁核（BLA）-伏隔核的神经回路负责实现价态更新。经历失败后，vCA1中的社会记忆印记神经元加强了其与BLA中携带负面价态神经元的突触连接。这种生理和突触连接的增强使得vCA1-BLA-NAc回路能够灵活调节适应性的社会行为。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["神经回路调控[社会记忆价态更新]: 依赖于海马腹侧CA1(vCA1)-基底外侧杏仁核(BLA)-伏隔核(NAc)之间突触连接性的增强和生理变化"]},{"i":39927,"as":"交叉呈递型树突状细胞对于癌症免疫周期至关重要。表观遗传酶CARM1（辅激活因子相关精氨酸甲基转移酶1）是cDC1细胞癌症抗原呈递的负调节因子。失活Carm1基因可促进cDC1的抗原交叉呈递、激活和在肿瘤内的积累。使用CARM1抑制剂能够增强癌症新抗原疫苗引发的cDC1介导的T细胞活化，其机制是增加了对cDC1功能和激活至关重要的BATF3-Jun和RelA位点染色质的可及性。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["CARM1表观遗传酶功能[癌症免疫cDC1细胞]: 选择性负向调节cDC1的抗原呈递(对cDC2无此作用)"]},{"i":39928,"as":"提出了一种统计假设检验方法，用于评估个性化干预政策的性能是否优于单一的最佳干预措施。该检验在保持严格的第一类错误控制的同时，在特定条件下实现了具有最小可能方差的渐近正态性。在职业培训、抑郁症治疗、教育和推荐系统等多个真实数据集上的结果表明，该方法具有广泛适用性且优于现有替代方案，为个性化干预的收益提供了严谨的量化检验。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[个性化干预统计假设检验]: 在保持严格的第一类错误控制的同时，评估个性化干预策略是否优于最佳单一干预"]},{"i":39929,"as":"安第斯叶耳鼠生活在海平面至海拔6700米以上的极高区域。群体基因组学分析表明，高原种群进化出了增强的低氧热生成能力，这与骨骼肌线粒体呼吸能力增强有关。研究揭示了其低氧适应的机制，并发现了意想不到的环境适应维度：对生物转化途径的选择表明该鼠类进化出了代谢植物源性饮食毒素的能力，使其能够在极端高海拔梯度下生存。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["栖息海拔上限[安第斯叶耳鼠]: >6700米","产热能力[高海拔缺氧环境相对于低地同类增强]: 提升的线粒体呼吸能力"]},{"i":39930,"as":"维持合适的核质比对细胞生理功能至关重要。在多核共享细胞质（如丝状真菌）的网络中，核分裂是异步的，但单位体积内的核数量（核密度）受到严格调控。研究通过将核建立为具有相振荡器的分裂群体模型，探究了分支真菌网络中全局核密度调控与局部细胞周期异步性如何共存，揭示了共质体生物内部的核密度控制机制。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":39931,"as":"对探讨清醒状态下海马体尖波波纹如何支持空间记忆的神经科学研究文章进行勘误。","scd":{"b":1.0,"i":1.0,"r":1.0,"d":0.0,"t":2.0},"kp":[]},{"i":39932,"as":"勘误更正关于颗粒酶A裂解GSDMB诱导靶细胞焦亡的免疫学机制研究内容。","scd":{"b":1.0,"i":1.0,"r":1.0,"d":0.0,"t":2.0},"kp":[]},{"i":39933,"as":"通过将自旋-轨道耦合光投射到人类视网膜上，经典的伯姆画刷被转化为多叶状拓扑结构。这种结构光束由圆偏振和轨道角动量的不可分叠加组成，通过视网膜中依赖于偏振的散射产生方位调制的内视现象。与黄斑双色吸收产生的海丁格刷不同，该现象是由散射强度相对于局部偏振方向的角变化驱动的，当散射中心的偏振取向趋同并相互增强时，会产生更明亮的内视图像。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["光束结构特征[调控自旋耦合光束]: 圆偏振与轨道角动量的不可分离叠加","视觉光学现象[偏振相关视网膜散射]: 方位调制的内视现象"]},{"i":39934,"as":"由于反应中较低的截面产率、较短的半衰期以及缺乏专门研究，远离稳定区域的变形奇奇核的低能级结构特征一直鲜为人知。该研究对奇奇稀土轻质量同位素（162Lu）的低能级结构进行了表征，填补了原子核结构领域相关的认知空白。","scd":{"b":5.0,"i":1.0,"r":6.0,"d":6.0,"t":6.0},"kp":[]},{"i":39935,"as":"通过核反应合成Z=119号超重核是扩展元素周期表的核心挑战。研究针对使用钙、钛、钒和铬作为射弹合成119号超重元素的反应进行了理论估计。由于超重核的产生涉及高度复杂的反应机制，研究重点评估了反应Q值和质量模型依赖性对超重核合成截面与产率的直接影响，为未来的实验合成提供了理论基础。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":6.0,"t":6.0},"kp":[]},{"i":39936,"as":"","scd":null,"kp":[]},{"i":39937,"as":"","scd":null,"kp":[]},{"i":39938,"as":"研究人员提出在月球上建立引力波天文台的设想，并发现月球自身的地质结构能够为引力波探测提供比以往认知更多的信息。这项研究表明，利用校准后的引力波可以进行月球结构层析成像，从而在探测引力波的同时，通过月球地质特性获取更多的物理约束和数据。该成果发表于《物理评论快报》。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":4.0,"t":7.0},"kp":["[月球引力波层析成像]: 可利用校准引力波约束月球地质结构"]},{"i":39939,"as":"一项发表于《物理评论快报》的研究指出，拟建中的月球引力波天文台有望获取超出预期的信息，这得益于月球的地质特征。研究发现，月球厚重的月壳能够对十分之一赫兹（0.1 Hz）频段的引力波信号起到显著的放大作用，这一地质特性将大幅提升月球引力波探测器的观测能力与数据获取量。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":4.0,"t":7.0},"kp":["[月球引力波信号探测]: 厚重的月壳能够放大0.1 Hz频率的引力波信号"]},{"i":39940,"as":"本研究开发了一种光氧化还原中性的合成平台，能够直接将亚甲基吡啶连接子转移到未活化的芳烃C-H键上。该技术成功将惰性C-H位点转化为通用的合成官能团，生成的苄基吡啶产物作为可广泛寻址的中间体，可支持多种C-C和C-杂原子键的形成。该方法通过模块化C1单元的直接引入，为高效获取药物化学中有价值的取代甲基分子提供了新途径。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":5.0,"t":6.0},"kp":["[光氧化还原中性C-H芳烃官能化]: 实现亚甲基吡啶鎓连接体向未活化芳烃的直接转移，将惰性C-H位点转化为合成把手"]},{"i":39941,"as":"研究编译了撒哈拉以南非洲48个国家的住宅电价数据集，并使用多级框架（MTF）模型估算电费。基于收入分布的承受能力评估表明，在现行电价和10%能源贫困阈值下，约6.08亿人（50%）无法负担第4级（Tier 4）电力，无法负担第5级电力的人数升至10.5亿（85%）。5%和15%阈值的敏感性分析证实了该结论的稳健性，揭示了电网扩容面临的电费承受能力瓶颈。","scd":{"b":4.0,"i":5.0,"r":8.0,"d":9.0,"t":5.0},"kp":["数据集范围[撒哈拉以南非洲国家]: 48个","电费评估模型[标准化居民电费]: 多层级框架(MTF)"]},{"i":39942,"as":"","scd":null,"kp":[]},{"i":39943,"as":"每日科学简报涵盖了三项核心进展：1. 基因突变使得章鱼的蛋白质合成机制出现中断，从而提高了其制造蛋白质的精确度；2. 一位诺贝尔奖得主离开美国前往中国；3. 科学家探讨了微重力环境对人体大脑产生的影响和效应。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":3.0,"t":7.0},"kp":["[章鱼蛋白质合成机制]: 其蛋白质合成机器发生突变从而提升制造精确度"]},{"i":39944,"as":"本观点文章探讨了无人机（UAV）的空中具身智能技术发展。文章指出，无人机在接收到开放式指令后，应当在执行最终的安全动作之前，先将这些指令转化为可在飞行过程中进行验证的测量数据。这一机制确保了无人机在复杂空中任务中的操作安全性和行动可靠性。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":3.0,"t":5.0},"kp":["[无人机具身智能]: 须将开放式指令转化为可验证的飞行测量数据后再执行安全动作"]},{"i":39945,"as":"探讨托卡马克核聚变技术ST-E1预概念设计，分享核聚变试点电站的建设规划。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":3.0,"t":6.0},"kp":["[核聚变试点电站建设规划]: 托卡马克能源公司ST-E1预概念设计"]},{"i":39946,"as":"ST-E1是Tokamak Energy开发的概念前聚变电站。为实现高可用性和商业可行性，该设计提出了一套有效的维护策略。由于托卡马克的维护方式对反应堆及其基础设施的空间设计具有决定性影响，该方案从设计初期就纳入了综合考量。ST-E1采用两阶段运行策略（先导阶段与商业阶段）来验证商业运营，并对电站的托卡马克架构、维护机制及场地布局进行了详细规划。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[ST-E1聚变电站维护策略]: 采用有效维护方案以实现高可用性和短暂停机时间","[托卡马克设计原则]: 维护方法对空间设计及周边基础设施影响重大，需在初期统筹考量"]},{"i":39947,"as":"研究探讨了主半径5米的低环径比托卡马克（ST-E1聚变电站）的功率耗散挑战及解决方案。使用一维边缘等离子体模型和SOLPS-ITER代码，在双零点和单零点构型下评估了脱离模式的可达性。分析表明，在以氩为初始杂质并采用钨偏滤器的条件下，除了最保守的参数假设外，均可实现脱离。为达成耗散偏滤器目标，必须在磁体工程和尚不确定的等离子体参数区间之间进行权衡。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":8.0,"t":6.0},"kp":["大半径[低环径比托卡马克]: 5 m","主要杂质[偏滤器脱靶运行]: 氩气","面向等离子体部件(PFC)[ST-E1]: 钨","[偏滤器脱靶可达性]: 通过1D边缘等离子体模型证实双零和单零构型下均可实现脱靶"]},{"i":39948,"as":"ST-E1聚变电站开发了一套集成的氚燃料循环架构。该系统将氦冷却液态锂增殖包层与专用循环回路耦合，在统一的系统边界内实现氚提取、排热和存量控制。下游氚处理系统涵盖提取、纯化、同位素分离和存储子系统，能够适应电站动态的氚生产与消耗率。存量建模评估了提取方案、氚滞留时间以及与氚控制相关的敏感性，综合评估证实了该集成方案的可行性。","scd":{"b":8.0,"i":5.0,"r":8.0,"d":8.0,"t":6.0},"kp":["包层系统[ST-E1氚燃料循环]: 氦冷液态锂增殖剂包层","[氚处理系统]: 集成了提取、纯化、同位素分离与存储子系统"]},{"i":39949,"as":"ST-E1是目标产生1.5吉瓦聚变功率的低环径比聚变电站。针对其等离子体演化，研究重点解决了在击穿和磁面形成后，如何将等离子体从初始状态爬升至目标平顶态的问题。由于ST-E1的环径比较低，其可用螺线管磁通受限。时间相关建模（METIS）表明，通过主要利用外部垂直场线圈提供的感应磁通，并在相对较高的等离子体密度下进行爬坡，可以成功实现等离子体的爬升。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":8.0,"t":6.0},"kp":["目标聚变功率[ST-E1]: 1.5 GW","[等离子体爬坡策略]: 针对低环径比导致螺线管磁通受限的问题进行特殊设计以实现向平顶态爬坡"]},{"i":39950,"as":"ST-E1低环径比托卡马克聚变反应堆在概念前设计阶段重点考虑了核技术因素。辐射屏蔽在保护高温超导（HTS）磁体系统方面的效能，是决定反应堆尺寸、电站寿命和系统平衡的关键。设计团队利用基于Geant4工具包开发的G4Tokamak应用程序，建立了专用的全电站规模中子学模拟工作流。该工作流加快了设计迭代速度，并通过基准测试验证了模拟结果，确保中子学材料考量贯穿于整个系统工程框架中。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":7.0,"t":6.0},"kp":["磁体系统[ST-E1辐射屏蔽]: 高温超导磁体","[中子学与材料考量]: 辐射屏蔽效能是决定反应堆尺寸、电站寿命及辅助系统设计的关键驱动因素"]},{"i":39951,"as":"ST-E1聚变电站的辅助加热和电流驱动系统物理基础研究指出，其平顶等离子体运行完全非感应，自举电流比例为0.9，剩余电流由电子回旋波（EC波）驱动。基于物理优化方法，采用160–200 GHz频率的基模O模（O1）从真空容器低场侧顶部发射（LFS top-launch），可达成目标平顶电流驱动，净效率达52 kA/MW。结论表明，LFS顶部发射O1 ECCD在等离子体运行的早期爬坡阶段同样有效。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":8.0,"t":6.0},"kp":["自举电流份额[ST-E1平顶等离子体]: 0.9","非感应电流驱动[ST-E1平顶等离子体]: 电子回旋波(EC波)","净效率[ECCD系统]: 52 kA/MW"]},{"i":39952,"as":"作为美国能源部聚变能发展计划的一部分，Tokamak Energy完成了ST-E1聚变发电站的预概念设计。该电站计划分两阶段运行：以持续净发电为目标的试点阶段，以及以稳态运行和低资本成本为目标的商业阶段。设计采用高度迭代的集成方法，重点在于探索设计空间、明确系统级权衡并确立总体概念。本文作为该设计系列论文之一，重点阐述了ST-E1试点阶段一系列参考平顶等离子体运行工况的物理基础与开发过程。","scd":{"b":8.0,"i":5.0,"r":8.0,"d":8.0,"t":7.0},"kp":["[ST-E1商业化电站阶段]: 目标实现稳态运行","[ST-E1设计流程]: 采用高度迭代的流程整合所有主要系统"]},{"i":39953,"as":"为支持ST-E1聚变电站的概念前设计，研究人员开发了全新的系统仿真代码PyTok。该代码基于纯Python面向对象框架，将等离子体物理和工程约束编入其中，以实现快速的设计迭代和电站参数空间探索。结合技术经济分析，PyTok确定了ST-E1的初始参考设计点：在5.0米主半径、特定环径比和环向场参数下，可实现具备商业竞争力的托卡马克功率核心，兼顾先导电站和商业电站的双重需求。","scd":{"b":6.0,"i":5.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[系统建模框架]: 面向对象的纯Python架构(PyTok)，用于快速设计迭代和探索参数空间","[数据结构]: 支持人类与机器可读，可与外部物理代码及数据分析工具耦合"]},{"i":39954,"as":"针对ST-E1低环径比聚变电站，研究提供了热管理和净功率性能的综合分析。研究量化了冷却剂回路设计、压降、泵送功率和蓄热对电站效率的具体影响，并探讨了冷却系统设计、动力循环集成与电气负载之间的相互作用。分析明确了达到300-500 MWe先导阶段净功率目标所需的条件，揭示了制约聚变电站可行性的系统级权衡因素，并为提升净功率性能提供了指导路径。","scd":{"b":6.0,"i":5.0,"r":7.0,"d":8.0,"t":6.0},"kp":["[ST-E1低纵横比托卡马克发电厂]: 综合量化了冷却剂回路设计、压降、泵送功率及热储存对电厂效率与净功率的影响"]},{"i":39955,"as":"为应对气候变化和由AI数据中心增长驱动的能源需求，Tokamak Energy提出了低环径比托卡马克聚变电站ST-E1的概念前设计，以解决聚变商业化面临的投资悖论。ST-E1从一开始就专为分阶段运行而设计，包括先导阶段、升级阶段和商业阶段，重点强调商业可行性与风险降低。该设计旨在提供稳定、低碳的基荷电力，满足未来对充沛能源的迫切需求。","scd":{"b":8.0,"i":5.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[聚变商业化悖论]: 试点电厂对于降低物理、工程和运营风险至关重要，但其寿命期内的能量输出有限且前期成本高昂，导致融资困难"]},{"i":39956,"as":"ST-E1聚变电站采用具有超长寿命的高温超导（HTS）磁体笼设计，目前已完成概念前设计阶段。为解决超导磁体、等离子体物理和功率耗散系统的同步集成难题，研究团队开发了一种新型集成工作流。该工作流能够精确表征感应电流驱动，将磁平衡、磁通摆动和高温超导运行极限紧密耦合在一起，从而避免了串行设计循环和后期出现的不可行运行场景，实现了早期阶段的快速迭代设计。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["磁体笼[ST-E1商业聚变发电厂]: 具备使用寿命的高温超导(HTS)磁体笼，已完成概念前设计阶段"]},{"i":39957,"as":"研究人员利用3D牵引力显微镜结合胶原蛋白运动学，量化了青光眼小梁网（TM）细胞在高流量（HF）和低流量（LF）区域的细胞骨架调节机制。实验在弹性模量为27.7 kPa的I型原纤维胶原蛋白凝胶上进行。对照组结果显示，HF和LF区域细胞的平均牵引力在4到12小时内均有增加（HF：36.2-44.8 kPa；LF：23.6-40.6 kPa）。Latrunculin B药物能在早期降低牵引力并伴随部分恢复。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":8.0,"t":5.0},"kp":["弹性模量[I型胶原凝胶]: 27.7 kPa","荧光微球直径[I型胶原凝胶]: 0.2 μm","[成像时间]: 胶原凝胶接种后每小时成像一次，持续12小时"]},{"i":39958,"as":"利用混合频率模型分析能源转型、碳政策与贸易冲突之间的动态协同效应。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[能源转型、碳政策与贸易冲突分析]: 混合频率模型应用"]},{"i":39959,"as":"电池护照对于实现储能系统的可追溯性、安全性和循环经济至关重要，但目前学术界的电池研究主要采用叙述性方式，难以顺利融入数字生态系统。文章提出建立“学术电池护照”框架，旨在为监管、人工智能和生命周期智能提供可互操作、机器可读的电池科学数据支持。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[学术电池护照框架]: 提出具备互操作性和机器可读性的电池科学数据框架，以支持监管、人工智能和生命周期智能化"]},{"i":39960,"as":"研究提出了一种适用于钠全固态电池锡负极的界面-界面工程策略，该策略兼容卷对卷电极制造工艺。通过将注入的钠硼氢化物负极电解质与碳纳米管（CNT）支架集成，工程化的锡负极实现了可逆的合金化化学反应和低压运行能力。结合阴极和固体电解质薄膜的干法制造工艺，首次成功实现了袋型钠全固态电池的演示验证。","scd":{"b":7.0,"i":5.0,"r":8.0,"d":8.0,"t":7.0},"kp":["[锡阳极界面设计]: 将注入的钠closo-borate阳极电解液与碳纳米管(CNT)支架相结合，实现可逆合金化化学反应和低压运行能力","[极片制造工艺]: 与卷对卷电极制造工艺兼容","[全固态钠电池]: 结合正极和固体电解质薄膜的干法工艺，首次实现袋型钠全固态电池演示"]},{"i":39961,"as":"研究人员利用四维扫描透射电子显微镜，在原子尺度上直接可视化了极性GaN势垒的InGaN/GaN异质结处由极化引起的电场。观测结果打破了经典物理中关于突变片状电荷的近似，揭示了空间上离域的负电荷积累现象。结合电子能量损失光谱和密度泛函理论计算，证实铟的掺入削弱了局部的金属-氮键，这是造成这种不对称电荷分布的微观机制。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[极化诱导电场]: 利用四维扫描透射电子显微镜直接实现原子尺度可视化，揭示非理想的突变片电荷分布"]},{"i":39962,"as":"针对蛋白质治疗剂跨细胞渗透性差且易被蛋白酶水解的局限，研究人员设计了一种氧化还原响应的蛋白前药RP-ss-PK。该前药通过二硫键将细胞毒性蛋白酶K（PK）共价结合到多功能聚合物RGD-PEG-ss-NPC上。其α端的环状RGD肽用于整合素介导的肿瘤靶向，ω端的NPC基团用于与PK上富含赖氨酸的残基进行位点特异性结合。该前药可在谷胱甘肽的触发下释放，从而抑制原发性肿瘤及其转移，并激发抗肿瘤免疫反应。","scd":null,"kp":["前体药物设计[抗肿瘤治疗]: 还原响应型蛋白前药RP-ss-PK","聚合物载体[前药递送系统]: 多功能线性异双官能团聚合物(RGD-PEG-ss-NPC)","[蛋白递送屏障克服策略]: 共价偶联细胞毒性蛋白酶K(PK)以规避跨膜渗透性受限和蛋白水解易感性"]},{"i":39963,"as":"为解决黑色素瘤术后复发及愈合困难的问题，研究人员开发了一种共载HMnO2和阿霉素（DOX）的微针（MN）贴片。该贴片能够穿透角质层将药物直接递送至手术部位。在近红外光照射下，HMnO2介导的光热消融（PTT）能有效清除残留的黑色素瘤细胞，而DOX则抑制潜在的微转移灶。此外，该系统还能调节局部炎症微环境，促进术后伤口愈合。","scd":null,"kp":["载药系统[黑色素瘤术后治疗]: 共载HMnO2和阿霉素(DOX)的微针(MN)贴片","[透皮递送机制]: 微针穿透角质层实现高效靶向透皮递送以管理残留病灶并促进创口修复"]},{"i":39964,"as":"综述MXene材料在超级电容器中的研究进展，涵盖合成、表面工程及下一代应用。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":4.0,"t":3.0},"kp":["[MXene基超级电容器研究进展]: 涵盖合成、表面工程及下一代应用的系统性综述"]},{"i":39965,"as":"受海参可逆机械切换行为的启发，研究团队开发了一种由明胶、水和1-乙基-3-甲基咪唑鎓硫酸乙酯组成的仿生热响应离子生物凝胶（IBG）。明胶形成了具有可逆溶胶-凝胶转变特性的物理网络，离子液体则通过氢键和静电相互作用调节网络并提供可移动离子，有效解决了传统预成型导电凝胶难以适应复杂动态皮肤形变的问题，提升了贴皮生物电子设备的界面粘附与信号传输性能。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[仿生离子生物凝胶]: 受海胆启发，开发出具有可逆机械切换行为的热响应离子生物凝胶(IBG)，解决预成型导电凝胶在动态变形皮肤表面的粘附与信号传输限制"]},{"i":39966,"as":"氮化铝（AlN）因高导热性和电绝缘性在热界面材料中备受关注，但在潮湿环境中的水解问题限制了其应用。研究人员开发了一种新型表面改性策略：先在AlN颗粒上接枝巯基，随后用液态金属（LM）层进行封装。将得到的LM@AlN填料掺入聚二甲基硅氧烷（PDMS）基体中固化，并结合机械训练策略，制备出了高性能的导热复合有机硅弹性体，有效避免了AlN的水解并提升了材料性能。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":4.0},"kp":["[AlN填料封装策略]: 采用液态金属封装解决AlN在潮湿环境下的水解和性能退化问题，以兼顾高加工效率和增强的材料性能"]},{"i":39967,"as":"为解决大段骨缺损修复中内源性骨髓间充质干细胞（BMSCs）募集和成骨能力有限的问题，研究人员开发了一种无细胞策略，将脱细胞鱼鳞（DC-FS）支架与干细胞片来源的细胞外囊泡（CS-EVs）相结合。该复合支架利用鱼鳞固有的微槽形貌引导细胞定向迁移，同时通过释放CS-EVs提供持续的促成骨信号。实验表明，该设计促进了BMSCs的定向粘附、迁移和成骨分化，有效增强了骨再生。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":4.0},"kp":["支架材料[核心尺寸骨缺损修复]: 脱细胞鱼鳞(DC-FS)与干细胞片来源细胞外囊泡(CS-EVs)结合的无细胞策略","[支架功能]: 利用鱼鳞先天微槽形貌进行定向细胞引导，并负载CS-EVs提供持续递送"]},{"i":39968,"as":"为满足基础设施在极寒潮湿与电磁干扰环境下的运行需求，研究人员开发了非对称结构的MXene/WPU复合涂层（AMWC）。该涂层将富含MXene的光热西兰花状顶层固定在富含MXene的层状电热底层上。其表面水接触角约为162°，滑动角约5°，展现出优异的超疏水性及机械化学鲁棒性。通过可调的光电热效应，该涂层实现了全天候防冰/除冰与以吸收为主的电磁干扰屏蔽的协同优化。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":4.0},"kp":["涂层结构[Mxene/WPU复合涂层]: 非对称结构设计(光热西兰花状贫Mxene顶层固定于电热层状富Mxene基底上)","[涂层功能]: 全天候防/除冰与吸收主导的电磁干扰屏蔽协同优化"]},{"i":39969,"as":"为了克服分子电化学发光（ECL）探针细胞摄取率低和靶向性差的缺陷，研究人员设计了一种胶体磁性纳米探针。该探针以6-7纳米的氧化铁为核心，表面修饰既可作为荧光探针又可作为ECL探针的钌联吡啶配合物，并进一步功能化靶向配体。将分子ECL发光体转化为胶体纳米颗粒探针，有效提高了细胞的摄取能力，拓展了其在荧光与电化学发光双模态生物成像及检测中的应用潜力。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":4.0},"kp":["[分子ECL发光体缺陷]: 细胞摄取差且缺乏细胞靶向性","[改进策略]: 将分子ECL发光体转化为胶体纳米探针(结合Ru(bpy)3^2+与磁性纳米粒子)以提升细胞摄取能力"]},{"i":39970,"as":"利用X射线自由电子激光器和激光驱动冲击压缩技术，研究人员在177-440 GPa的外核压力下对铁、Fe+4.5FeO和Fe2O3熔体进行了原位X射线衍射测量。结果表明，压缩的铁氧化物熔体的Fe-O配位数在4.0至4.5之间，以四重配位环境为主，这明显小于下地幔含铁相的配位数。铁氧化物熔体中较短的Fe-Fe原子间距驱动了比常压熔体更致密的原子堆积，这种结构差异对理解地核轻元素的物理性质和地磁发电机运行具有重要意义。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":8.0,"t":4.0},"kp":["配位数[Fe-O(177-440 GPa地核压力下熔融态)]: 4.0(0.4)至4.5(0.4)","测试压力[激光驱动冲击压缩下X射线自由电子激光测量]: 177-440 GPa","元素比例[Fe+4.5FeO测试样品]: 原子比例"]},{"i":39971,"as":"研究人员展示了在宽度为10-20纳米、数量高达105,000个的收缩型自旋霍尔纳米振荡器（SHNO）晶格中实现的纳秒级相位排序。微波光谱证实了完全的相互同步，其品质因子超过106，功率与N成正比，线宽与N成反比。时间分辨布里渊光散射测量表明，同步时间随阵列尺寸呈弱对数增长。这一大规模相互同步的纳米振荡器网络为非常规物理计算奠定了基础。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["振荡器数量[自旋霍尔纳米振荡器(SHNO)晶格互同步]: 高达105,000个","器件宽度[收缩型SHNO]: 10–20 nm","[技术特征]: 实现了超大晶格中的纳秒级相排序"]},{"i":39972,"as":"研究提出了一种基于刚性聚阴离子骨架与含锂离子液体之间定制相互作用的复合聚合物电解质设计策略。该设计使锂离子的传导与聚合物链段动力学解耦，同时实现了快速的界面电荷转移和较高的机械模量，从而有效稳定了与锂金属电极接触的界面。通过固态交换核磁共振和马尔可夫状态模型验证，该结构实现了多种离子传输途径和纳米团簇动力学，满足了高离子电导率与低界面阻力的双重需求。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["电解质设计[复合聚合物电解质]: 基于刚性聚阴离子结构与含锂离子液体间定制相互作用的策略"]},{"i":39973,"as":"针对厚锂离子电池电极中离子传输迟缓、反应不均和机械退化等挑战，研究通过调控晶体生长过程，向富锂层状氧化物中引入相干孪晶界（CTBs），构建了准三维离子扩散网络。富锂层状氧化物虽具有高理论比容量，但面临结构应力和氧氧化还原不可逆等问题。CTBs的引入有效缓解了厚电极中的传输限制和结构退化，显著提升了电池的整体电化学性能。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["[极化限制]: 厚电极面临离子传输缓慢、反应不均及机械降解问题","材料缺陷[富锂层状氧化物]: 存在纳米级结构应力、氧氧化还原不可逆性及电极级传输限制","[材料优势]: 通过阴离子电荷补偿提供高理论比容量"]},{"i":39974,"as":"聚烯烃加氢裂化是废塑料升级回收的有效途径。研究重新审视了传统碳氢化合物加氢裂化策略及其纳米级构效关系在聚合物催化领域的适用性。塑料的大分子特性、传质限制、杂质分布以及在催化剂-聚合物纳米界面的独特相互作用，阻碍了传统理论的直接套用。这些差异为设计能够实现高效解聚反应的新一代双功能纳米催化剂提供了全新的工程化机遇。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":5.0,"t":3.0},"kp":["[催化机制]: 依赖双功能纳米催化剂实现高效解聚","[设计基础]: 基于传统碳氢化合物加氢裂化的纳米级结构-活性关系"]},{"i":39975,"as":"分析指出，欧盟对进口纯电动汽车征收关税虽不会显著阻碍整体的电气化进程，但会大幅降低脆弱市场的电动汽车普及率。研究揭示了广泛贸易干预手段带来的不均衡影响，强调了制定补充性政策以支持向具有弹性和包容性的电动化转型过渡的重要性。","scd":{"b":2.0,"i":8.0,"r":5.0,"d":4.0,"t":6.0},"kp":["[政策影响]: 不会实质性阻碍整体电气化进程，但会大幅降低脆弱市场的采用率","[干预机制]: 广泛的贸易干预需配合补充性政策以支持具韧性和包容性的转型"]},{"i":39976,"as":"通过结合车型成本数据与市场采纳框架，研究量化了2024年欧盟对中国纯电动汽车加征额外关税对20个欧盟国家和10个车辆级别的分配性影响。根据车企不同的应对策略，预计2035年欧盟电动汽车市场份额将在56.4%（撤出市场）至68.9%（低成本本地化生产）之间波动，而基准预期为64.4%。由于关税引起的成本冲击，对价格敏感的车型和低收入国家的电动汽车普及率损失最为严重。","scd":{"b":4.5,"i":5.0,"r":6.0,"d":8.0,"t":6.0},"kp":["关税实施时间[欧盟对中国电动汽车]: 2024年7月","[模型分析变量]: 车型成本数据与市场采用框架","[市场评估范围]: 涵盖20个欧盟国家及10个车辆级别"]},{"i":39977,"as":"研究宽带隙钙钛矿材料，探讨本征卤化物梯度对相分离路径重塑的影响机制。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":5.0,"t":7.0},"kp":["[宽带隙钙钛矿相分离调控]: 本征卤化物梯度重塑相分离路径"]},{"i":39978,"as":"注入血液中的机械发光纳米材料能够在超声波的控制下实现发光，这一技术突破成功实现了对深层组织中神经元的光遗传学刺激。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":5.0,"t":7.0},"kp":["机械发光纳米材料[深层组织神经元光遗传学刺激]: 通过血液循环给药并受超声控制发光"]},{"i":39979,"as":"力学微环境不仅调节肿瘤的转移扩散过程，还深刻影响着机体的抗肿瘤免疫力。将力学传导与免疫反应过程相整合的“力学免疫学”，为深入理解肿瘤转移的进展机制以及开发新型治疗干预手段提供了重要的理论框架。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[肿瘤转移与抗肿瘤免疫交互]: 力学信号调节转移扩散与抗肿瘤免疫的力学免疫学框架"]},{"i":39980,"as":"一种原位显微镜技术能够在几分钟内监测数千个单独纳米晶体的尺寸和发光特性，从而揭示半导体纳米晶体生命周期中与尺寸相关的物理现象，实现了单粒子精度的观测与分析。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":5.0,"t":7.0},"kp":["监测速度[单个半导体纳米晶体尺寸与发光特性]: 数分钟内可监测数千个","原位散射光学显微技术[纳米晶体生命周期]: 具备单粒子精度的数字能力并揭示尺寸依赖现象"]},{"i":39981,"as":"氟化物离子等阴离子电荷载体可作为电化学储能中锂离子的替代品。阴离子载体具有高理论能量密度、低成本等优势，并能解决轻金属电极沉积的挑战。本文概述了转换型和插入型电极的设计原理及其与液态和固态电解质配合使用的跨尺度材料设计概念。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["电荷载体[电化学储能体系设计]: 氟化物离子","理论能量密度[阴离子电荷载体电池体系]: 超越现有锂离子技术且成本显著降低"]},{"i":39982,"as":"分析1970年至2021年15个经合组织国家的数据发现，将能源密集型产业转移至国外的离岸外包行为，显著且持续地降低了本国的能源强度。研究指出，国内生产总值能源强度的下降不能简单视为国家对全球脱碳的贡献，呼吁气候评估指标超越基于生产的核算框架。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":7.0,"t":4.0},"kp":["[国家GDP能源强度下降与全球脱碳关系]: 归因于能源密集型产业向海外转移的结构性变化(离岸外包)而非实质脱碳"]},{"i":39983,"as":"π共轭水凝胶半导体结合了水凝胶的生物相容性、柔软性三维结构与π共轭聚合物的半导体特性，在晶体管等先进电子领域具应用潜力。本文综述了该材料的设计、制备、表征标准，并深入探讨了热力学条件下离子与电子的传输机制及其相互作用。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["半导体行为[水凝胶网络设计]: 基于π共轭聚合物的网络设计","材料属性[生物电子应用]: 具备生物相容性、柔软性及三维架构的类组织特性"]},{"i":39984,"as":"对探讨自生矿物相如何驱动上层海洋铁循环的海洋生物地球化学研究进行勘误。","scd":{"b":5.0,"i":2.0,"r":3.0,"d":2.0,"t":2.0},"kp":["[上层海洋铁循环驱动机制]: 自生矿物相的驱动作用"]},{"i":39985,"as":"","scd":null,"kp":[]},{"i":39986,"as":"","scd":null,"kp":[]},{"i":39987,"as":"通用人工智能科学工具（如Claude Science）旨在加速科学研究进程。本文为研究人员提供了指南，帮助在众多AI工具中评估并选择适合自身实验室具体需求的“人工智能科学家”。","scd":{"b":5.0,"i":4.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[通用科学人工智能工具]: Claude Science等有望加速科学研究进程"]},{"i":39988,"as":"","scd":null,"kp":[]},{"i":39989,"as":"科学家利用干细胞培育出了未成熟的人类精子，使生育力技术取得新突破。这项实验性操作通过在小鼠肾脏上培育干细胞，成功引导其转化为精子细胞。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":4.0,"t":6.0},"kp":["[干细胞体外分化培养]: 利用小鼠肾脏作为滋养载体生成未成熟人类精子"]},{"i":39990,"as":"","scd":null,"kp":[]},{"i":39991,"as":"在中国早石炭世（约3.6亿年前）地层中发现了一种具有叶片着生胚珠的早期种子植物新属——甘尼蕨属。该发现为解释二叠纪冈瓦纳大陆主导植物群舌羊齿目的起源提供了关键的进化信息。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":7.0,"t":5.0},"kp":["地质年代[甘尼蕨属化石出土层位]: 约3.6亿年前早石炭世","进化意义[早期种子植物]: 提供舌羊齿类起源的关键信息"]},{"i":39992,"as":"提出利用阴离子桥联二次溶剂化鞘策略，以提升水系锌离子电池稳定性的研究。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":3.0,"t":7.0},"kp":["[水系锌离子电池稳定性提升]: 采用阴离子桥联二次溶剂化鞘策略"]},{"i":39993,"as":"降冰片二烯和炔烃的[2+2]环加成通常倾向于形成外型产物。现开发出一种镍催化内选择性[2+2]环加成方法，生成了难以合成的内型-三环壬二烯，并通过分子内[2+2]光化学环加成进一步衍生化，成功合成了高立方烷。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["区域选择性[降冰片二烯与炔烃反应]: 镍催化实现内选择性[2+2]环加成","产物[内选择性环加成及光化学衍生化]: 成功合成难以获取的内型-三环壬二烯并进一步合成高立方烷"]},{"i":39994,"as":"在Ni/SiAlO催化剂作用下，通过非热等离子体激活催化过程，在温和条件下实现了氮气和甲烷向烷基胺和氨的一步直接共转化。该等离子体与催化剂的协同作用促进了反应物活化及中间体的耦合，绕过了高耗能的传统工艺，提供了一条可持续合成路线。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":8.0,"t":7.0},"kp":["催化体系[N2和CH4直接共转化为烷基胺和氨]: 非热等离子体激活的Ni/SiAlO催化剂","反应条件[N2和CH4直接共转化]: 温和条件下的等离子体催化协同一步过程"]},{"i":39995,"as":"单片钙钛矿/硅串联太阳能电池有望打破传统晶硅器件约29.4%的效率极限。实验室成果的突破得益于钙钛矿成分工程、添加剂引入、界面钝化、电荷选择性接触优化及硅底电池架构的改进。本文综述了推动该光伏技术效率提升的材料基础与器件工程策略。","scd":{"b":7.0,"i":6.0,"r":6.0,"d":8.0,"t":6.0},"kp":["理论效率极限[传统晶体硅光伏器件]: 约29.4%","器件工程[单片钙钛矿/硅串联光伏]: 实验室验证已超越硅器件理论极限并具备制造级扩展性"]},{"i":39996,"as":"开发出一种基于酸碱反应的金属有机骨架（MOFs）合成方法。该方法直接使用廉价的金属氢氧化物，仅产生水作为副产物，实现了接近分子筛成本的大规模可扩展生产。合成的没食子酸盐基MOF材料能够高效分离极具挑战性的醇/苯共沸物。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":8.0,"t":7.0},"kp":["副产物[金属有机框架酸碱合成]: 仅生成水","合成原料[低成本规模化制备MOF]: 廉价金属氢氧化物","分离能力[没食子酸基MOF]: 高效分离极具挑战性的醇/苯共沸物"]},{"i":39997,"as":"介绍利用化学指纹技术优化环境足迹评估及饲料采购策略，涉及分析化学与农业可持续发展领域。","scd":{"b":3.0,"i":3.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[环境足迹与饲料采购优化]: 利用化学指纹技术进行评估与策略优化"]},{"i":39998,"as":"在手性掺杂诱导中心对称晶体产生压电性的研究中，利用拉曼光谱等技术探讨了微观极化起源。将四种手性N-乙酰-L-氨基酸掺入中心对称晶体后证实，极化主要源于掺杂剂与宿主分子间的偶极子失配，或是掺杂剂诱导的晶格畸变。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["掺杂策略[中心对称分子晶体]: 立体选择性掺杂手性添加剂以降低反演对称性","极化产生机制[微观尺度]: 掺杂剂与宿主分子间的偶极子错配"]},{"i":39999,"as":"利用时间分辨X射线光电子能谱结合理论与实验研究了氟吡啶。研究发现，在光激发态弛豫过程中，氟原子位点主要响应振动弛豫，对电子激发态的敏感度极低；而氮原子位点的化学位移敏感性则表现出对电子激发的显著响应。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["化学位移灵敏度[局部振动]: 光诱导增强","核心电子结合能偏移[tr-XPS测量]: 亚电子伏特级"]}]);